$nativeCode = @"
using System;
using System.Runtime.InteropServices;
using System.IO;
using System.Security.Cryptography;
using System.Diagnostics;

public class NativeMethods {
    [DllImport("user32.dll")]
    public static extern bool ShowWindow(int handle, int state);
    [DllImport("kernel32.dll")]
    public static extern int GetConsoleWindow();
    // v1.2.7: Debug switch icin (-NoConsole modda console yok, AllocConsole ile yeni olustur)
    [DllImport("kernel32.dll")]
    public static extern bool AllocConsole();
    [DllImport("kernel32.dll")]
    public static extern bool FreeConsole();
    [DllImport("kernel32.dll")]
    public static extern bool SetConsoleTitle(string title);
    [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    public static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint Msg, UIntPtr wParam, string lParam, uint fuFlags, uint uTimeout, out UIntPtr lpdwResult);
    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    public static extern int SystemParametersInfo(int uAction, int uParam, string lpvParam, int fuWinIni);
    // v1.3.0: SPI_SETMOUSE (0x0004) — fare ivmesi esik/hiz dizisini (int[3]) oturum kapatmadan aninda uygular.
    [DllImport("user32.dll", EntryPoint = "SystemParametersInfo")]
    public static extern bool SystemParametersInfoInts(int uAction, int uParam, int[] lpvParam, int fuWinIni);
    [DllImport("shell32.dll")]
    public static extern void SHChangeNotify(int wEventId, int uFlags, IntPtr dwItem1, IntPtr dwItem2);
    // v1.3.0: koyu baslik cubugu (20 = dark mode, 34 = kenar, 35 = baslik rengi, 36 = baslik yazisi; 35/36/34 Win11)
    [DllImport("dwmapi.dll")]
    public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int value, int size);
    // v1.3.0 (§97): masaustu gorunumune (SHELLDLL_DefView) "Yenile" komutu gondermek icin
    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern IntPtr FindWindow(string lpClassName, string lpWindowName);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern IntPtr FindWindowEx(IntPtr hwndParent, IntPtr hwndChildAfter, string lpszClass, string lpszWindow);
    [DllImport("user32.dll")]
    public static extern bool PostMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);
