public class FileSelector {
    [DllImport("shell32.dll", ExactSpelling = true)]
    public static extern void ILFree(IntPtr pidlList);
    [DllImport("shell32.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
    public static extern IntPtr ILCreateFromPathW(string pszPath);
    [DllImport("shell32.dll", ExactSpelling = true)]
    public static extern int SHOpenFolderAndSelectItems(IntPtr pidlFolder, uint cidl, IntPtr[] apidl, uint dwFlags);

    public static void Select(string path) {
        IntPtr pidl = ILCreateFromPathW(path);
        if(pidl != IntPtr.Zero) {
            try {
                SHOpenFolderAndSelectItems(pidl, 0, null, 0);
            } finally {
                ILFree(pidl);
            }
        }
    }
}

public class SecureWiper {
    public static bool WipeFile(string filePath, int passes) {
        try {
            if (!File.Exists(filePath)) return true;
            FileInfo fi = new FileInfo(filePath);
            if (fi.IsReadOnly) fi.IsReadOnly = false;
            
            long length = fi.Length;
            using (FileStream fs = new FileStream(filePath, FileMode.Open, FileAccess.Write, FileShare.None)) {
                // Güvenli rastgele veri üretici
                using (var rng = new RNGCryptoServiceProvider()) {
                    byte[] buffer = new byte[1024 * 1024]; // 1MB tampon
                    for (int p = 0; p < passes; p++) {
                        fs.Position = 0;
                        long written = 0;
                        while (written < length) {
                            rng.GetBytes(buffer);
                            int toWrite = (int)Math.Min(buffer.Length, length - written);
                            fs.Write(buffer, 0, toWrite);
                            written += toWrite;
                        }
                        fs.Flush();
                    }
                }
            }
            File.Delete(filePath);
            return true;
        } catch { return false; }
    }
}

public class RamCleaner {
    // Working Set boşaltma (process-level)
    [DllImport("psapi.dll")]
    public static extern bool EmptyWorkingSet(IntPtr hProcess);

    // System-wide memory list manipulation (Standby Memory + Modified Pages purge)
    [DllImport("ntdll.dll")]
    public static extern int NtSetSystemInformation(int InfoClass, IntPtr Info, int Length);

    // Token + privilege adjustment (SeProfileSingleProcessPrivilege gerekli — admin process bile default'ta enable değil)
    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern bool OpenProcessToken(IntPtr ProcessHandle, uint DesiredAccess, out IntPtr TokenHandle);

    [DllImport("advapi32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    public static extern bool LookupPrivilegeValue(string lpSystemName, string lpName, out long lpLuid);

    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern bool AdjustTokenPrivileges(IntPtr TokenHandle, bool DisableAllPrivileges,
        ref TOKEN_PRIVILEGES NewState, uint BufferLength, IntPtr PreviousState, IntPtr ReturnLength);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr GetCurrentProcess();

    [DllImport("kernel32.dll")]
    public static extern bool CloseHandle(IntPtr hObject);

    [StructLayout(LayoutKind.Sequential)]
    public struct LUID_AND_ATTRIBUTES { public long Luid; public uint Attributes; }

    [StructLayout(LayoutKind.Sequential)]
    public struct TOKEN_PRIVILEGES { public uint PrivilegeCount; public LUID_AND_ATTRIBUTES Privileges; }

    private const uint TOKEN_ADJUST_PRIVILEGES = 0x20;
    private const uint TOKEN_QUERY = 0x8;
    private const uint SE_PRIVILEGE_ENABLED = 0x2;

    // SystemMemoryListInformation = 80
    // MemoryListCommand: PurgeStandbyList = 4, PurgeLowPriorityStandbyList = 5, FlushModifiedList = 3, EmptyWorkingSets = 2
    private const int SystemMemoryListInformation = 80;
    private const int MemoryEmptyWorkingSets = 2;
    private const int MemoryFlushModifiedList = 3;
    private const int MemoryPurgeStandbyList = 4;

    private static bool EnablePrivilege(string privName) {
        IntPtr hToken;
        if (!OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, out hToken)) return false;
        try {
            long luid;
            if (!LookupPrivilegeValue(null, privName, out luid)) return false;
            TOKEN_PRIVILEGES tp = new TOKEN_PRIVILEGES();
            tp.PrivilegeCount = 1;
            tp.Privileges.Luid = luid;
            tp.Privileges.Attributes = SE_PRIVILEGE_ENABLED;
            return AdjustTokenPrivileges(hToken, false, ref tp, 0, IntPtr.Zero, IntPtr.Zero);
        } finally {
            CloseHandle(hToken);
        }
    }

    private static int InvokeMemoryListCommand(int command) {
        IntPtr cmdPtr = Marshal.AllocHGlobal(sizeof(int));
        try {
            Marshal.WriteInt32(cmdPtr, command);
            return NtSetSystemInformation(SystemMemoryListInformation, cmdPtr, sizeof(int));
        } finally {
            Marshal.FreeHGlobal(cmdPtr);
        }
    }

    public static int CleanAll() {
        // 1) Working Set: her process icin (admin olmayan dahil)
        int wsCount = 0;
        foreach (Process p in Process.GetProcesses()) {
            try { EmptyWorkingSet(p.Handle); wsCount++; } catch {}
        }

        // 2) System-wide memory list operations (admin + SeProfileSingleProcessPrivilege gerek)
        // RAMMap-style: Standby Memory + Modified Pages temizle
        try { EnablePrivilege("SeProfileSingleProcessPrivilege"); } catch {}
        try { EnablePrivilege("SeIncreaseQuotaPrivilege"); } catch {}

        // Modified pages diske flush (bu olmadan standby purge eksik kalir)
        try { InvokeMemoryListCommand(MemoryFlushModifiedList); } catch {}
        // Standby memory listesini bosalt (en buyuk kazanim — RAMMap'in "Empty Standby List")
        try { InvokeMemoryListCommand(MemoryPurgeStandbyList); } catch {}
        // System-wide working sets bosalt (per-process EmptyWorkingSet'ten daha kapsamli)
        try { InvokeMemoryListCommand(MemoryEmptyWorkingSets); } catch {}

        return wsCount;
    }
}

public struct MEMORYSTATUSEX {
    public uint dwLength;
    public uint dwMemoryLoad;
    public ulong ullTotalPhys;
    public ulong ullAvailPhys;
    public ulong ullTotalPageFile;
    public ulong ullAvailPageFile;
    public ulong ullTotalVirtual;
    public ulong ullAvailVirtual;
    public ulong ullAvailExtendedVirtual;
}

public class RamInfo {[DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool GlobalMemoryStatusEx(ref MEMORYSTATUSEX lpBuffer);

    public static double[] GetRamUsageGB() {
        MEMORYSTATUSEX memStatus = new MEMORYSTATUSEX();
        memStatus.dwLength = (uint)Marshal.SizeOf(typeof(MEMORYSTATUSEX));
        if (GlobalMemoryStatusEx(ref memStatus)) {
            // Bayt değerini GB'a çeviriyoruz
            double total = memStatus.ullTotalPhys / 1073741824.0;
            double avail = memStatus.ullAvailPhys / 1073741824.0;
            double used = total - avail;
            
            // Windows'un tahmini "dwMemoryLoad" değeri yerine KESİN matematik hesabı:
            double percent = (used / total) * 100.0;
            
            return new double[] { total, used, percent };
        }
        return new double[] { 0, 0, 0 };
    }
}
public struct IO_COUNTERS {
    public ulong ReadOperationCount;
    public ulong WriteOperationCount;
    public ulong OtherOperationCount;
    public ulong ReadTransferCount;
    public ulong WriteTransferCount;
    public ulong OtherTransferCount;
}

public class ProcessMonitor {
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool GetProcessIoCounters(IntPtr hProcess, out IO_COUNTERS lpIoCounters);

    public static long GetProcessTotalIo(int processId) {
        try {
            Process p = Process.GetProcessById(processId);
            IO_COUNTERS counters;
            if (GetProcessIoCounters(p.Handle, out counters)) {
                // Okuma ve Yazma baytlarının toplamını döndürür
                return (long)(counters.ReadTransferCount + counters.WriteTransferCount);
            }
        } catch { }
        return -1; // Process kapandıysa veya okunamıyorsa -1 döner
    }
}

// v1.2.9: Timer Resolution kontrolu (NtSetTimerResolution + MeasureSleep tarzi olcum)
// Windows API public — herhangi bir process 0.5ms (5000 hns) gonderebilir; sistem global
// olarak en dusuk requested degeri tutar. Lucas Hale Pro veya valleyofdoom clone'larina
// gerek yok, inline implementation.
public class TimerRes {
    [DllImport("ntdll.dll", SetLastError = true)]
    public static extern int NtSetTimerResolution(uint DesiredResolution, bool SetResolution, out uint CurrentResolution);

    [DllImport("ntdll.dll", SetLastError = true)]
    public static extern int NtQueryTimerResolution(out uint MinimumResolution, out uint MaximumResolution, out uint CurrentResolution);

    [DllImport("kernel32.dll")]
    public static extern bool QueryPerformanceCounter(out long lpPerformanceCount);

    [DllImport("kernel32.dll")]
    public static extern bool QueryPerformanceFrequency(out long lpFrequency);

    [DllImport("kernel32.dll")]
    public static extern void Sleep(uint dwMilliseconds);

    // valleyofdoom MeasureSleep birebir: REALTIME priority class ile Sleep olcumu hassas olur.
    // Win11 default NORMAL priority Sleep'i throttle eder (EcoQoS uzerinden), bu yuzden test
    // oncesi REALTIME, test sonrasi NORMAL'a don.
    [DllImport("kernel32.dll")]
    public static extern bool SetPriorityClass(IntPtr hProcess, uint dwPriorityClass);

    [DllImport("kernel32.dll")]
    public static extern IntPtr GetCurrentProcess();

    public const uint REALTIME_PRIORITY_CLASS = 0x00000100;
    public const uint HIGH_PRIORITY_CLASS     = 0x00000080;
    public const uint NORMAL_PRIORITY_CLASS   = 0x00000020;

    public static bool SetRealtimePriority() {
        return SetPriorityClass(GetCurrentProcess(), REALTIME_PRIORITY_CLASS);
    }

    public static bool SetHighPriority() {
        // Stress Benchmark icin guvenli yuksek priority — REALTIME + stress thread'leri
        // sistemi kilitleyebilir, HIGH iyi orta yol (sample hassasiyet + sistem responsive).
        return SetPriorityClass(GetCurrentProcess(), HIGH_PRIORITY_CLASS);
    }

    public static bool SetNormalPriority() {
        return SetPriorityClass(GetCurrentProcess(), NORMAL_PRIORITY_CLASS);
    }

    // Hedef ms (0.5, 1.0). 100ns birime cevrilir (1ms = 10000 hns). Donus: gercek set edilen ms.
    public static double Set(double ms) {
        uint hns = (uint)(ms * 10000);
        uint current;
        NtSetTimerResolution(hns, true, out current);
        return current / 10000.0;
    }

    // Bu process'in tuttugu timer'i release et (SetResolution=false). Sistem default'a doner
    // (eger baska bir process daha dusuk resolution hold etmiyorsa).
    public static void Release() {
        uint current;
        NtSetTimerResolution(5000, false, out current);
    }

    // Mevcut sistem timer resolution (ms cinsinden)
    public static double QueryMs() {
        uint min, max, current;
        NtQueryTimerResolution(out min, out max, out current);
        return current / 10000.0;
    }

    // v1.2.22: Platform en ince ulasilabilir timer resolution (ms). NtQueryTimerResolution'da
    // "max" = en kucuk hns degeri = donanimin inebildigi en dusuk ms. NtSetTimerResolution bu
    // degerin ALTINI sessizce buna yuvarlar (ornek modern Win11'de 0.5ms). Auto-Tune tarama
    // araligini bu sinira clamp etmek + kullaniciyi bilgilendirmek icin kullanilir.
    public static double QueryMaxMs() {
        uint min, max, current;
        NtQueryTimerResolution(out min, out max, out current);
        return max / 10000.0;
    }

    // Tek Sleep(1) cagrisi yap, QueryPerformanceCounter ile gercek olcum (ms) dondur.
    // MeasureSleep.exe tarzi delta hesabi icin temel ozellik.
    public static double MeasureOnce() {
        long freq, t1, t2;
        QueryPerformanceFrequency(out freq);
        QueryPerformanceCounter(out t1);
        Sleep(1);
        QueryPerformanceCounter(out t2);
        return ((t2 - t1) * 1000.0) / freq;
    }
}

// v1.2.9: Native CPU stress generator — PowerShell scriptblock stress yetersiz (%42 CPU max).
// Tight long*long loop, branch prediction friendly, native compile = %100 core yuk.
// Static volatile flag ile tum runspace thread'leri kontrollu durdurulur (Stop cagrisi sonrasi).
public class CpuStress {
    public static volatile bool ShouldStop = false;

    public static void Run() {
        long sum = 0;
        while (!ShouldStop) {
            for (long j = 0; j < 10000000 && !ShouldStop; j++) {
                sum += j * j;
            }
        }
        // sum'i kullan ki compiler optimize edip atmasin
        if (sum == long.MinValue) { System.Console.Write(""); }
    }

    public static void Start() { ShouldStop = false; }
    public static void Stop()  { ShouldStop = true; }
}
"@
# Derleyici sadece 1 kez çalışır
Add-Type -TypeDefinition $nativeCode -Language CSharp

# --- KONSOL PENCERESİNİ GİZLEME VE DEBUG SWITCH İÇİN GLOBAL HANDLE ---
# Defansif: PS2EXE Console mode'da console acilirsa hemen gizle.
# Early FreeConsole zaten ana pencereyi detach eder; bu fallback baska durumlar icin.
$global:ConsoleHandle = [NativeMethods]::GetConsoleWindow()
if ($global:ConsoleHandle -ne 0) {
    [void][NativeMethods]::ShowWindow($global:ConsoleHandle, 0)  # SW_HIDE = 0 (defansif; -NoConsole aktif olunca handle 0 olur)
}

# --- YARDIMCI FONKSİYONLAR ---

# #endregion 1 -- C# INTEROP (Native Methods, SecureWiper, RamCleaner, vb.)


# =========================================================================

# #region 2 -- YONETICI KONTROL, RUNSPACE POOL, TEMA
# =========================================================================

function Refresh-WindowsTheme {
    $null = [NativeMethods]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, "ImmersiveColorSet", 2, 2000, [ref][UIntPtr]::Zero)
    $null =[NativeMethods]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, "Environment", 2, 2000, [ref][UIntPtr]::Zero)
}

# --- YÖNETİCİ KONTROLÜ (GÜNCELLENDİ) ---
$currentPrincipal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
$isAdmin = $currentPrincipal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
$global:MrCleanSelfPath = if ($PSCommandPath) { $PSCommandPath } else { try { [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { "" } }
$global:MrCleanElevTask = "MrClean (Yonetici Baslatici)"
if (-not $isAdmin) {
    # v1.3.0 (8. tur): kullanici bir kez izin verdiyse (Ayarlar > "Onay sormadan baslat") yonetici yetkili gorev UAC sormadan acar.
    # Gorev SADECE Program Files\MrClean altindaki kopyayi calistirir (yalnizca yonetici degistirebilir); bu dosya o kopyayla
    # birebir ayni degilse (yeni surum indirildiyse) klasik UAC istenir ve yonetici olarak acilinca kopya guncellenir.
    $viaTask = $false
    try {
        if ((Get-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AdminLauncher" -ErrorAction SilentlyContinue).AdminLauncher -eq 1 -and $global:MrCleanSelfPath) {
            $inst = Join-Path $env:ProgramFiles ("MrClean\" + [IO.Path]::GetFileName($global:MrCleanSelfPath))
            if ((Test-Path $inst) -and ((Get-FileHash $inst -Algorithm SHA256).Hash -eq (Get-FileHash $global:MrCleanSelfPath -Algorithm SHA256).Hash)) {
                & schtasks.exe /run /tn $global:MrCleanElevTask 2>$null | Out-Null
                if ($LASTEXITCODE -eq 0) { $viaTask = $true }
            }
        }
    } catch {}
    # Eğer yönetici değilse, kendini yönetici olarak yeniden başlatır
    if (-not $viaTask) { Start-Process powershell.exe "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs }
    exit
}
# PS2EXE -NoConsole modunda Console nesnesi olmaz — try/catch ile sarmal
try {
    [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
} catch {
}
# PS2EXE -NoConsole modunda console yok — Write-* cagrilari MessageBox'a donusur
# Doğru tespit: Host.Name = "PSRunspace-Host" (PS2EXE'in özel host'u). RawUI.WindowSize
# erisilebilir AMA gerçek console yok — bu yüzden RawUI check'i false-positive verir.
$script:IsPs2Exe = ($Host.Name -eq 'PSRunspace-Host' -or $Host.Name -like '*ConsoleHost-NoConsole*')
if ($script:IsPs2Exe) {
    # PS2EXE -NoConsole detected — output stream'lari sessize al (sadece ana process scope)
    # Hata stream'leri MessageBox olarak cikiyordu; bu override hepsini yutar
    function global:Write-Host {
        param([Parameter(ValueFromPipeline=$true, Position=0)] $Object,
              [Parameter(ValueFromRemainingArguments=$true)] $Rest)
        process { }
    }
    function global:Out-Default {
        param([Parameter(ValueFromPipeline=$true)] $InputObject,
              [Parameter(ValueFromRemainingArguments=$true)] $Rest)
        process { }
    }
    function global:Out-Host {
        param([Parameter(ValueFromPipeline=$true)] $InputObject,
              [Parameter(ValueFromRemainingArguments=$true)] $Rest)
        process { }
    }
    # Implicit pipeline output (orn. fonksiyon return degeri) Out-Default'a gider — yukarida yutuluyor
    # Stream preferences — silent default'lar (PS2EXE NoConsole'de stream MessageBox'a yonlenmesin)
    $global:WarningPreference     = 'SilentlyContinue'
    $global:VerbosePreference     = 'SilentlyContinue'
    $global:DebugPreference       = 'SilentlyContinue'
    $global:InformationPreference = 'SilentlyContinue'
    # ErrorActionPreference Continue kalsın — hatalar Add_Loaded'daki try/catch'lerle yakalanir
}
# --- GLOBAL RUNSPACE POOL (HIZ VE VERİMLİLİK İÇİN) ---
if (-not $global:MrCleanPool) {
    $sessionState = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
    # En az 1, en fazla 5 paralel iş yapabilen havuz
    $global:MrCleanPool = [runspacefactory]::CreateRunspacePool(1, 5, $sessionState, $Host)
    $global:MrCleanPool.Open()
}

# --- YAPILANDIRMA ---

# #endregion 2 -- YONETICI KONTROL, RUNSPACE POOL, TEMA

# =========================================================================
# #region 3 -- GLOBAL DEGISKENLER & DOSYA YOLLARI
# =========================================================================

# Migration: %APPDATA%\GeminiCare -> %APPDATA%\MrClean (one-time, eski kurulumlardan gelen kullanicilar icin)
# Eski klasor varsa ve yeni klasor yoksa, butun ayarlari/profilleri korumak icin rename yap.
$_legacyAppData = "$env:APPDATA\GeminiCare"
$_newAppData    = "$env:APPDATA\MrClean"
if ((Test-Path -LiteralPath $_legacyAppData) -and -not (Test-Path -LiteralPath $_newAppData)) {
    try { Rename-Item -LiteralPath $_legacyAppData -NewName 'MrClean' -ErrorAction Stop } catch { }
}

$AppDataPath = "$env:APPDATA\MrClean"
if (-not (Test-Path $AppDataPath)) { New-Item -Path $AppDataPath -ItemType Directory -Force | Out-Null }

# v1.2.30: Roaming\MrClean duzeni — dosyalar alt klasorlerde tutulur (config/cache/database/logs/tools).
# helpers (TimerResHelper) ve update_staging kokte kalir (zamanlanmis gorev tam-yol referansi + gecici).
$ConfigDir   = "$AppDataPath\config"
$CacheDir    = "$AppDataPath\cache"
$DatabaseDir = "$AppDataPath\database"
$LogsDir     = "$AppDataPath\logs"
$ToolsDir    = "$AppDataPath\tools"
function Migrate-AppDataLayout {
    # Tek seferlik, guvenli gecis: alt klasorleri olustur, mevcut dosyalari tasi (yoksa atla, hata sessiz).
    try {
        $map = [ordered]@{
            $ConfigDir   = @('user_config.json','user_config.json.bak1','user_config.json.bak2','user_config.json.bak3','user_config.json.bak4','user_config.json.bak5','app_state.json','settings.json','trt_settings.json','no_cache.flag','update_skipped_versions.txt')
            $CacheDir    = @('app_cache.json','tweak_status_cache.json')
            $DatabaseDir = @('Winapp2.ini','Winapp2.prev.ini')
            $LogsDir     = @('tweak_history.log')
        }
        foreach ($dir in $map.Keys) {
            if (-not (Test-Path $dir)) { New-Item -Path $dir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null }
            foreach ($f in $map[$dir]) {
                $src = Join-Path $AppDataPath $f; $dst = Join-Path $dir $f
                if ((Test-Path $src) -and -not (Test-Path $dst)) { Move-Item -Path $src -Destination $dst -Force -ErrorAction SilentlyContinue }
            }
        }
        Get-ChildItem -Path $AppDataPath -Filter 'winapp2_diff_*.txt' -File -ErrorAction SilentlyContinue | ForEach-Object {
            $dd = Join-Path $DatabaseDir $_.Name
            if (-not (Test-Path $dd)) { Move-Item -Path $_.FullName -Destination $dd -Force -ErrorAction SilentlyContinue }
        }
    } catch {}
}
Migrate-AppDataLayout

# v1.3.0 (11. tur, birlestirme): islem kaydi paneli sadece bellekte; her oturum logs\session.log a da yazilir, bir onceki
# oturum session_prev.log olarak kalir (sorun bildirirken / cokme sonrasi bakmak icin).
$global:SessionLogWriter = $null
try {
    if (-not (Test-Path $LogsDir)) { New-Item -Path $LogsDir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null }
    $sessionLog = Join-Path $LogsDir "session.log"
    if (Test-Path $sessionLog) { Move-Item -Path $sessionLog -Destination (Join-Path $LogsDir "session_prev.log") -Force -ErrorAction Stop }
    $sessionLogStream = New-Object System.IO.StreamWriter($sessionLog, $false, (New-Object System.Text.UTF8Encoding($false)))
    $sessionLogStream.AutoFlush = $true
    $global:SessionLogWriter = [System.IO.TextWriter]::Synchronized($sessionLogStream)
    $global:SessionLogWriter.WriteLine("=== MrClean oturumu: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') | Windows $([Environment]::OSVersion.Version) ===")
    $global:BootT0 = [Diagnostics.Stopwatch]::StartNew()
} catch {}
if (-not $global:BootT0) { $global:BootT0 = [Diagnostics.Stopwatch]::StartNew() }

$Winapp2Path = "$DatabaseDir\Winapp2.ini"
$UserConfigPath = "$ConfigDir\user_config.json"
$AppStatePath   = "$ConfigDir\app_state.json"
$CachePath      = "$CacheDir\app_cache.json"
# Auto-update: kullanicinin atladigi surumler ve guncelleme staging klasoru
# PS2EXE-safe: $env:APPDATA kullaniyoruz, $AppDataPath script scope'a bagimli olmasin
$global:UpdateSkippedFile = "$ConfigDir\update_skipped_versions.txt"
$global:UpdateStagingDir  = "$env:APPDATA\MrClean\update_staging"

