function Get-Default-Tweaks {
    return [ordered]@{
        # --- 1. GÖRSEL PERFORMANS (PROCESS MONITOR VERİLERİNE GÖRE) ---
        "Görsel Performans" = @(
            @{
                Name="Görsel Efektler: Özel (Yazı Tipi + Küçük Resimler Açık)";
                Description="Görsel Efektler'i 'Özel' moda alır: yalnız yazı tipi yumuşatma (ClearType) ve küçük resim önizlemeleri açık kalır; pencere animasyonları, gölgeler, saydamlık ve diğer efektler kapanır. Arayüzün CPU / GPU yükü düşer, eski bilgisayarlarda belirgin hızlanma olur.`n`nAyarlar anında uygulanır; Gezgin yeniden başlatılır.`nℹ️ Duvar kâğıdına dokunmaz. Geri aldıktan sonra masaüstü düz siyah kalırsa sebep 'Karanlık Modu Aç (Sistem + Wallpaper + Kilit Ekranı)' tweak'idir — onu da geri alın.";
                RestartExplorer="Hard";
                DetectScript='
                    $fx = (Get-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects" -Name VisualFXSetting -ErrorAction SilentlyContinue).VisualFXSetting
                    $fs = (Get-ItemProperty "HKCU:\Control Panel\Desktop" -Name FontSmoothing -ErrorAction SilentlyContinue).FontSmoothing
                    $io = (Get-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name IconsOnly -ErrorAction SilentlyContinue).IconsOnly
                    $ma = (Get-ItemProperty "HKCU:\Control Panel\Desktop\WindowMetrics" -Name MinAnimate -ErrorAction SilentlyContinue).MinAnimate
                    return (("$fx" -eq "3") -and ("$fs" -eq "2") -and ("$io" -eq "0") -and ("$ma" -eq "0"))
                ';
                Batch=@(
                    # 1. Modu "Özel" (Custom) yap
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects"; ValueName="VisualFXSetting"; Type="DWord"; Data=3; Undo=0 },
                    
                    # 2. Maske: yazi tipi + thumbnails. Byte1=0x00 (selection fade / cursor shadow kapali).
                    @{ Key="HKCU:\Control Panel\Desktop"; ValueName="UserPreferencesMask"; Type="Binary"; Data=[byte[]](0x90,0x00,0x03,0x80,0x10,0x00,0x00,0x00); Undo=[byte[]](0x9E,0x1E,0x07,0x80,0x12,0x00,0x00,0x00) },

                    # 3. Yazı Tipi Düzeltme (ProcMon: 2)
                    @{ Key="HKCU:\Control Panel\Desktop"; ValueName="FontSmoothing"; Type="String"; Data="2"; Undo="2" },
                    
                    # 4. Görev Çubuğu Animasyonları (ProcMon: 0)
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; ValueName="TaskbarAnimations"; Type="DWord"; Data=0; Undo=1 },
                    
                    # 5. Liste Gölgeleri (ProcMon: 0)
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; ValueName="ListviewShadow"; Type="DWord"; Data=0; Undo=1 },
                    
                    # 6. Aero Peek (ProcMon: 0)
                    @{ Key="HKCU:\Software\Microsoft\Windows\DWM"; ValueName="EnableAeroPeek"; Type="DWord"; Data=0; Undo=1 },
                    
                    # 7. Sürüklerken İçeriği Göster (ProcMon: 0)
                    @{ Key="HKCU:\Control Panel\Desktop"; ValueName="DragFullWindows"; Type="String"; Data="0"; Undo="1" },
                    
                    # 8. Seçim Dikdörtgeni Saydamlığı (ProcMon: 0)
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; ValueName="ListviewAlphaSelect"; Type="DWord"; Data=0; Undo=1 },

                    # 9. Küçük Resimler (Senin İsteğin - IconsOnly=0)
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; ValueName="IconsOnly"; Type="DWord"; Data=0; Undo=0 },

                    # 10. v1.2.16: Pencereler Animasyonla Küçültülüp Büyütülsün — MinAnimate (WindowMetrics).
                    # Bu checkbox UserPreferencesMask'ta DEGIL, ayri bir registry value. Format sonrasi
                    # taze Win11 sisteminde default "1" (animasyon ON) — tweak Custom mode'a aldigi halde
                    # bu spesifik checkbox ON kaliyordu (kullanici raporu). Acikca "0" yazarak kapat.
                    @{ Key="HKCU:\Control Panel\Desktop\WindowMetrics"; ValueName="MinAnimate"; Type="String"; Data="0"; Undo="1" },
                    @{ Key="HKCU:\Software\Microsoft\Windows\DWM"; ValueName="AlwaysHibernateThumbnails"; Type="DWord"; Data=0; Undo=0 },
                    @{
                        Command='
                            if (-not ("SpiFx" -as [type])) {
                                Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class SpiFx {
  [StructLayout(LayoutKind.Sequential)]
  public struct ANIMATIONINFO { public uint cbSize; public int iMinAnimate; }
  [DllImport("user32.dll", SetLastError=true)]
  public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, ref ANIMATIONINFO pvParam, uint fWinIni);
  [DllImport("user32.dll", SetLastError=true)]
  public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, [MarshalAs(UnmanagedType.Bool)] bool pvParam, uint fWinIni);
}
"@
                            }
                            $ai = New-Object SpiFx+ANIMATIONINFO
                            $ai.cbSize = [System.Runtime.InteropServices.Marshal]::SizeOf($ai)
                            $ai.iMinAnimate = 0
                            [void][SpiFx]::SystemParametersInfo(0x0049, [uint32]$ai.cbSize, [ref]$ai, 3)
                            [void][SpiFx]::SystemParametersInfo(0x1025, 0, $false, 3)
                            [void][SpiFx]::SystemParametersInfo(0x1015, 0, $false, 3)
                            [void][SpiFx]::SystemParametersInfo(0x101B, 0, $false, 3)
                            [void][SpiFx]::SystemParametersInfo(0x0025, 0, $false, 3)
                            [void][SpiFx]::SystemParametersInfo(0x004B, 1, $false, 3)
                            Start-Process -FilePath "$env:SystemRoot\System32\rundll32.exe" -ArgumentList "user32.dll,UpdatePerUserSystemParameters" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                            Write-Host "[Gorsel] SPI: MinAnimate=0 DropShadow=off FontSmoothing=on"
                        ';
                        UndoCommand='
                            if (-not ("SpiFx" -as [type])) {
                                Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class SpiFx {
  [StructLayout(LayoutKind.Sequential)]
  public struct ANIMATIONINFO { public uint cbSize; public int iMinAnimate; }
  [DllImport("user32.dll", SetLastError=true)]
  public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, ref ANIMATIONINFO pvParam, uint fWinIni);
  [DllImport("user32.dll", SetLastError=true)]
  public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, [MarshalAs(UnmanagedType.Bool)] bool pvParam, uint fWinIni);
}
"@
                            }
                            $ai = New-Object SpiFx+ANIMATIONINFO
                            $ai.cbSize = [System.Runtime.InteropServices.Marshal]::SizeOf($ai)
                            $ai.iMinAnimate = 1
                            [void][SpiFx]::SystemParametersInfo(0x0049, [uint32]$ai.cbSize, [ref]$ai, 3)
                            [void][SpiFx]::SystemParametersInfo(0x1025, 0, $true, 3)
                            [void][SpiFx]::SystemParametersInfo(0x1015, 0, $true, 3)
                            [void][SpiFx]::SystemParametersInfo(0x101B, 0, $true, 3)
                            [void][SpiFx]::SystemParametersInfo(0x0025, 1, $false, 3)
                            Start-Process -FilePath "$env:SystemRoot\System32\rundll32.exe" -ArgumentList "user32.dll,UpdatePerUserSystemParameters" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                        '
                    }
                )
            },
            @{
                Name="Fare Üzerine Gelme ve Görev Çubuğu Önizleme Gecikmesini Azalt"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Fareyle bir öğenin üzerine gelince açılan ipucu/önizlemelerin ve görev çubuğu küçük resim önizlemesinin bekleme süresini kısaltır (400 ms → 100 ms). Arayüz daha çevik hissettirir. Anında uygulanır.`n`nℹ️ Bazı araçlar 0 ms kullanır; bu, fare geçerken her şeyin açılmasına neden olduğu için 100 ms seçildi.`n📚 Kaynak: winscript, RyTuneX, optimizer (MouseHoverTime); talon (ExtendedUIHoverTime).";
                DetectScript='
                    $m = (Get-ItemProperty -Path "HKCU:\Control Panel\Mouse" -Name "MouseHoverTime" -ErrorAction SilentlyContinue).MouseHoverTime
                    $e = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ExtendedUIHoverTime" -ErrorAction SilentlyContinue).ExtendedUIHoverTime
                    return ("$m" -eq "100" -and "$e" -eq "100")
                ';
                Command='
                    Set-ItemProperty -Path "HKCU:\Control Panel\Mouse" -Name "MouseHoverTime" -Value "100" -Type String -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ExtendedUIHoverTime" -Value 100 -Type DWord -Force
                    try { [void][NativeMethods]::SystemParametersInfo(0x0067, 100, "", 3) } catch {}
                ';
                UndoCommand='
                    Set-ItemProperty -Path "HKCU:\Control Panel\Mouse" -Name "MouseHoverTime" -Value "400" -Type String -Force
                    Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ExtendedUIHoverTime" -Force -ErrorAction SilentlyContinue
                    try { [void][NativeMethods]::SystemParametersInfo(0x0067, 400, "", 3) } catch {}
                '
            },
            @{
                Name="Oturum Açma Ekranı Bulanıklığını Kapat (Acrylic)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Oturum açma (şifre) ekranındaki buzlu cam bulanıklık efektini kapatır; arka plan resmi net görünür ve giriş ekranı GPU efekti çizmez. Group Policy ile aynıdır.`n📚 Kaynak: kubsonxtm/Windows-Tweaks, Microsoft ADMX (DisableAcrylicBackgroundOnLogon).";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\System"; ValueName="DisableAcrylicBackgroundOnLogon"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Duvar Kâğıdı Kalitesini %100 Yap (JPEG Sıkıştırmasını Kapat)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows duvar kâğıdı olarak ayarlanan JPEG resimleri varsayılan olarak %85 kaliteye yeniden sıkıştırır (bulanıklık/bant oluşur). Bu tweak tam kaliteyi korur. Bir sonraki duvar kâğıdı ayarlamada geçerli olur.`n📚 Kaynak: Sophia Script, GTweak.";
                Key="HKCU:\Control Panel\Desktop"; ValueName="JPEGImportQuality"; Type="DWord"; Data=100; Undo="DELETE_VALUE"
            },
            @{
                Name="Saydamlık Efektlerini Kapat"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Başlat menüsü, görev çubuğu, Ayarlar ve bildirim panelindeki buzlu cam (Mica/Acrylic) saydamlığını kapatır. DWM'nin arka plandaki bulanıklaştırma işini kaldırır — zayıf iGPU'larda ve oyun üstüne açılan panellerde hafif GPU tasarrufu.`n`nAyarlar > Kişiselleştirme > Renkler > Saydamlık efektleri ile aynıdır. Anında uygulanır.";
                Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"; ValueName="EnableTransparency"; Type="DWord"; Data=0; Undo=1
            },
            @{
                Name="Dinamik Aydınlatmayı Kapat (RGB)"; Since="2.0.0"; MinBuild=22631;
                Risk="Low"; RestartExplorer=$false;
                Description="Ayarlar > Kişiselleştirme > Dinamik aydınlatma > 'Cihazlarımda Dinamik aydınlatmayı kullan' seçeneğini kapatır. RGB klavye / fare / kasa ışıkları Windows'un arka plan denetiminden çıkar; G Hub, Razer Synapse, OpenRGB gibi yazılımlar kendi ışık ayarlarıyla çalışmaya devam eder.`n`nℹ️ Değer hiç yazılmamışsa Windows bu özelliği açık kabul eder.`n📚 Kaynak: Microsoft Destek (Dynamic Lighting), Microsoft Learn (LampArray).";
                Key="HKCU:\Software\Microsoft\Lighting"; ValueName="AmbientLightingEnabled"; Type="DWord"; Data=0; Undo=1
            },
            @{
                Name="İçerik Uyarlamalı Parlaklığı Kapat (CABC)"; Since="2.0.0"; MinBuild=22621; Requires=@("CABC");
                Risk="Low"; RestartExplorer=$false;
                Description="Ayarlar > Sistem > Ekran > Parlaklık > 'Parlaklığı içeriğe göre değiştir' seçeneğini kapatır. Koyu sahnelerde panelin parlaklığı kısması oyun ve videoda parlaklık zıplamasına ve takılma hissine yol açar.`n`nℹ️ Ekran üreticisi bu özelliği açmadıysa Ayarlar'da seçenek yoktur ve tweak gri görünür.`n📚 Kaynak: Microsoft Destek (parlaklık), ElevenForum CABC.";
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers"; ValueName="CABCOption"; Type="DWord"; Data=0; Undo="DELETE_VALUE"
            }

        )
		# --- 2. GÖREV ÇUBUĞU VE BAŞLAT ---
        "Kişiselleştirme" = @(
            # NOT: "Windows Spotlight Kapat" tweak'i Karanlik Mod tweak'ine entegre edildi (v1.2.2).
            # Karanlik Mod uygulandiginda Spotlight otomatik kapanir, BackgroundType=1 (renk modu, siyah) yapilir.

			# v1.3.0 fix: eskiden RotatingLockScreenEnabled yaziyordu — o deger Spotlight RESIM DONGUSUNU kapatir,
			# "eglenceli bilgiler/ipuclari" katmanini degil. Dogru degerler: Overlay + SubscribedContent-338387.
			@{
