				Description="Kilit ekranındaki 'eğlenceli bilgiler, ipuçları, püf noktaları' metin katmanını kapatır (Ayarlar > Kişiselleştirme > Kilit ekranı). Kilit ekranı resminiz ve Spotlight resim döngüsü değişmez.";
				Batch=@(
					@{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"; ValueName="RotatingLockScreenOverlayEnabled"; Type="DWord"; Data=0; Undo=1 },
					@{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"; ValueName="SubscribedContent-338387Enabled"; Type="DWord"; Data=0; Undo=1 }
				)
			},
            @{
                Name="Masaüstündeki 'Bu Resim Hakkında' (Spotlight) Simgesini Gizle"; SubCategory="Arka Plan"; Since="2.0.0";
                Risk="Low"; RestartExplorer="Soft";
                Description="Masaüstü arka planı 'Windows Spotlight' iken sağ üstte çıkan 'Bu resim hakkında bilgi edinin' simgesini gizler. Spotlight resimleri değişmeye devam eder.`n📚 Kaynak: Win11Debloat (Hide_Desktop_Spotlight_Icon), GTweak.";
                Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel"; ValueName="{2cc5ca98-6485-489a-920e-b3e88a6ccce3}"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
