                Name="Karanlık Modu Aç (Sistem + Wallpaper + Kilit Ekranı)";
				SubCategory="Renkler";
                Description="Tek tıkla tam koyu görünüm:`n• Sistem ve uygulamalar koyu tema`n• Saydamlık kapalı, başlık çubukları renksiz`n• Pencere kenarları ve görev çubuğu vurgu rengi koyu gri`n• Klasik Denetim Masası arka planı siyah`n• Masaüstü düz siyah renk`n• Kilit ekranı ekran çözünürlüğünde siyah resim`n`n↩️ Geri alma açık temaya ve Windows Spotlight masaüstü arka planına döner.";
                RestartExplorer=$false;
                DetectScript='
                    $path = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"
                    $sys = (Get-ItemProperty -Path $path -Name "SystemUsesLightTheme" -ErrorAction SilentlyContinue).SystemUsesLightTheme
                    $app = (Get-ItemProperty -Path $path -Name "AppsUseLightTheme" -ErrorAction SilentlyContinue).AppsUseLightTheme
                    $bg = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers" -Name "BackgroundType" -ErrorAction SilentlyContinue).BackgroundType
                    $spot = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Settings" -Name "EnabledState" -ErrorAction SilentlyContinue).EnabledState
                    $black = Test-Path "C:\Windows\Black.jpg"
                    # 14. tur: duvar kagidi / kilit ekrani tek seferlik ayar — kullanici sonradan degistirince tweak "donmus" sayilmasin
                    return (("$sys" -eq "0") -and ("$app" -eq "0"))
                ';
                Command='
                    # === BOLUM 1: SISTEM TEMASI ===
                    # Personalize: Apps + System koyu, ColorPrevalence=0 (renksiz baslik cubuklari -- kullanici istegi v1.2.2), saydamlik off
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "AppsUseLightTheme"     -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "ColorPrevalence"      -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "EnableTransparency"   -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "SystemUsesLightTheme" -Value 0 -Type DWord -Force

                    # HKLM Personalize (sistem geneli)
                    if (-not (Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Themes\Personalize")) {
                        New-Item -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "AppsUseLightTheme" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue

                    # Accent Palette: Win11 standart Sari/Altin 32-byte palette (kullanici secimi v1.2.3, gercek registry verisi)
                    # 8 ton: Light3, Light2, Light1, Base (#FFB900 ana altin), Dark1, Dark2, Dark3, Complementary (teal)
                    if (-not (Test-Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent")) {
                        New-Item -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    $palette = [byte[]](0xFF,0xE8,0x45,0x00, 0xFF,0xD5,0x2A,0x00, 0xFF,0xC2,0x0D,0x00, 0xFF,0xB9,0x00,0x00, 0xE1,0x9D,0x00,0x00, 0x9B,0x5D,0x00,0x00, 0x5C,0x21,0x00,0x00, 0x00,0xB2,0x94,0x00)
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent" -Name "AccentPalette"      -Value $palette -Type Binary -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent" -Name "StartColorMenu"     -Value 0        -Type DWord  -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent" -Name "AccentColorMenu"    -Value 0        -Type DWord  -Force

                    # DWM (window borders, taskbar accent)
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "EnableWindowColorization" -Value 1          -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "AccentColor"             -Value 0xff191919 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "ColorizationColor"        -Value 0xc4191919 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "ColorizationAfterglow"    -Value 0xc4191919 -Type DWord -Force

                    # Klasik Kontrol Paneli arka planlari (eski uygulamalar icin) — siyah masaustu rengi
                    Set-ItemProperty -Path "HKCU:\Control Panel\Colors" -Name "Background" -Value "0 0 0" -Force

                    # === BOLUM 2: SIYAH WALLPAPER + KILIT EKRANI ===
                    Write-Host "[Karanlik] Siyah JPG olusturuluyor..."
                    Add-Type -AssemblyName System.Windows.Forms
                    Add-Type -AssemblyName System.Drawing
                    $w = [System.Windows.Forms.SystemInformation]::PrimaryMonitorSize.Width
                    $h = [System.Windows.Forms.SystemInformation]::PrimaryMonitorSize.Height
                    $file = "C:\Windows\Black.jpg"
                    $bmp = New-Object System.Drawing.Bitmap $w, $h
                    $g = [System.Drawing.Graphics]::FromImage($bmp)
                    $g.FillRectangle([System.Drawing.Brushes]::Black, 0, 0, $bmp.Width, $bmp.Height)
                    $g.Dispose()
                    $bmp.Save($file)
                    $bmp.Dispose()
                    Write-Host "[Karanlik] Black.jpg ${w}x${h} olusturuldu."

                    # Kilit ekrani (PersonalizationCSP)
                    if (-not (Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\PersonalizationCSP")) {
                        New-Item -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\PersonalizationCSP" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\PersonalizationCSP" -Name "LockScreenImagePath"   -Value $file -Type String -Force
                    Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\PersonalizationCSP" -Name "LockScreenImageStatus" -Value 1     -Type DWord  -Force

                    # === BOLUM 3: MASAUSTU = DUZ RENK SIYAH + SPOTLIGHT KAPAT (kullanici istegi) ===
                    # BackgroundType=1 -> duz renk modu (Settings te "Duz renk" gorunur).
                    # Renk = Control Panel\Colors\Background = "0 0 0" (siyah).
                    # Wallpaper="" + SPI bos broadcast -> Win11 cache i wallpaper kaldirir, duz renk aktif olur.
                    if (-not (Test-Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers")) {
                        New-Item -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers" -Name "BackgroundType" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    if (-not (Test-Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Settings")) {
                        New-Item -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Settings" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Settings" -Name "EnabledState" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Settings" -Name "SpotlightDisabledReason" -Value 100 -Type DWord -Force -ErrorAction SilentlyContinue

                    # Wallpaper kayit bos + SPI bos broadcast -> duz renk modu zorlanir
                    Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "Wallpaper" -Value "" -Type String -Force
                    [NativeMethods]::SystemParametersInfo(20, 0, "", 3) | Out-Null

                    rundll32.exe user32.dll, UpdatePerUserSystemParameters
                    Refresh-WindowsTheme
                    Write-Host "[Karanlik] Tum siyah yuzeyler uygulandi."
                ';
                UndoCommand='
                    # === BOLUM 1: SISTEM TEMASI -> Light defaults ===
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "AppsUseLightTheme"     -Value 1 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "ColorPrevalence"      -Value 0 -Type DWord -Force  # Light default
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "EnableTransparency"   -Value 1 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Name "SystemUsesLightTheme" -Value 1 -Type DWord -Force

                    # HKLM Personalize key sil (FR33THY: [-HKLM\...] ile siliniyor)
                    Remove-Item -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Themes\Personalize" -Recurse -Force -ErrorAction SilentlyContinue

                    # Accent Palette default (mavi tonlari — FR33THY default, v1.2.3 geri eklendi)
                    if (-not (Test-Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent")) {
                        New-Item -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    $defaultPalette = [byte[]](0x99,0xeb,0xff,0x00, 0x4c,0xc2,0xff,0x00, 0x00,0x91,0xf8,0x00, 0x00,0x78,0xd4,0x00, 0x00,0x67,0xc0,0x00, 0x00,0x3e,0x92,0x00, 0x00,0x1a,0x68,0x00, 0xf7,0x63,0x0c,0x00)
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent" -Name "AccentPalette"   -Value $defaultPalette -Type Binary -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent" -Name "StartColorMenu"  -Value 0xffc06700      -Type DWord  -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent" -Name "AccentColorMenu" -Value 0xffd47800      -Type DWord  -Force

                    # DWM defaults (mavi accent)
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "EnableWindowColorization" -Value 0          -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "AccentColor"             -Value 0xffd47800 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "ColorizationColor"        -Value 0xc40078d4 -Type DWord -Force
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "ColorizationAfterglow"    -Value 0xc40078d4 -Type DWord -Force

                    Set-ItemProperty -Path "HKCU:\Control Panel\Colors" -Name "Background" -Value "0 0 0" -Force

                    # === BOLUM 2: WALLPAPER + KILIT EKRANI -> defaults ===
                    Remove-Item -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\PersonalizationCSP" -Recurse -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "Wallpaper" -Value "C:\Windows\Web\Wallpaper\Windows\img0.jpg" -Type String -Force -ErrorAction SilentlyContinue

                    # === BOLUM 3: SPOTLIGHT TAM RESTORE ===
                    # KRITIK BUG FIX (v1.2.3): Apply tarafinda SpotlightDisabledReason=100 set edilir.
                    # Bu deger Windows e "kullanici Spotlight i kapatti" der -> Undo da BackgroundType=3 set etsek
                    # bile Windows Spotlight i devreye sokmaz. Bu key i SILMEK kritik.
                    Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Settings" -Name "SpotlightDisabledReason" -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Settings" -Name "EnabledState" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight" -Name "ImagesUsed" -Value 2 -Type DWord -Force -ErrorAction SilentlyContinue
                    if (-not (Test-Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Creatives")) {
                        New-Item -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Creatives" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Creatives" -Name "ImageIndex" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue

                    # BackgroundType=3 (Spotlight modu) — Wallpaper kayitindan SONRA set
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers" -Name "BackgroundType" -Value 3 -Type DWord -Force -ErrorAction SilentlyContinue

                    # AppXSvc restart — Spotlight servisinin yeni ayarlari yuklemesi icin gerekli
                    if (Get-Service "AppXSvc" -ErrorAction SilentlyContinue) {
                        Restart-Service "AppXSvc" -Force -ErrorAction SilentlyContinue
                    }

                    # SPI_SETDESKWALLPAPER ile img0.jpg path broadcast — Win11 cache (Apply daki bos string) bypass.
                    [NativeMethods]::SystemParametersInfo(20, 0, "C:\Windows\Web\Wallpaper\Windows\img0.jpg", 3) | Out-Null

                    rundll32.exe user32.dll, UpdatePerUserSystemParameters
                    Remove-Item -Path "C:\Windows\Black.jpg" -Force -ErrorAction SilentlyContinue

                    Refresh-WindowsTheme
                    Write-Host "[Karanlik] Tum siyah yuzeyler default (light) gore donduruldu."
                '
            },

			# NOT (v1.2.8): 8 atomik "Başlat Menüsü" tweak'i + "Format Sonrası Temiz Düzen (FR33THY)" tek bir kompozit
			# tweak'te birleştirildi -> "Başlat Menüsü: Tertemiz Paket (Tek Tık - Hepsi)" (aşağıda, Kişiselleştirme grubunun sonunda).
			# Eski tweak'ler: Layout, En son Eklenen, Atlama listesi, Gözatma Geçmişi, İpuçları, Hesap Bildirimleri,
			# Web Arama, Önerilenler Bölümü, Format Sonrası Temiz Düzen — hepsinin işi Tertemiz Paket içinde.

			@{ Name="Arama Butonunu Gizle"; SubCategory="Görev Çubuğu"; Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Search"; ValueName="SearchboxTaskbarMode"; Type="DWord"; Data=0; Undo=2; RestartExplorer=$false; Description="Görev çubuğundaki arama kutusunu / simgesini gizler. Win tuşuna basıp yazarak arama aynen çalışır. Geri alma Windows 11 varsayılanı olan arama kutusuna döner." },
            @{ Name="Görev Görünümü Butonunu Gizle"; Description="Görev çubuğundaki Görev Görünümü (sanal masaüstleri) düğmesini gizler. Win+Tab kısayolu aynen çalışır."; SubCategory="Görev Çubuğu"; Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; ValueName="ShowTaskViewButton"; Type="DWord"; Data=0; Undo=1; RestartExplorer=$false },
            @{
                Name="Pencere Öğelerini (Widget) Kapat";
				SubCategory="Görev Çubuğu";
				RestartExplorer=$false;
				Description="Görev çubuğundaki Pencere Öğeleri (haber, hava durumu, borsa) düğmesini ve panosunu Group Policy ile kapatır; arka planda çalışan Widgets / WebView süreçleri durur. Kilit ekranındaki hava durumu kartları ayrı tweak'tir.`n📚 Kaynak: Sophia Script, winscript; Microsoft ADMX (AllowNewsAndInterests).";
				DetectScript='
					$pol = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Dsh" -Name "AllowNewsAndInterests" -ErrorAction SilentlyContinue).AllowNewsAndInterests
					return ("$pol" -eq "0")
				';
				Batch=@(
                    # 1. Kullanıcı Ayarı (Erişim hatası verse bile önemli değil)
                    # v1.3.0: 24H2+ da UCPD surucusu TaskbarDa degerine powershell.exe den yazmayi ENGELLER (Sophia L1935,
                    # winscript L877). Eskiden her Apply da yaniltici "yetki hatasi" logu cikiyordu. Artik sessizce denenir;
                    # asil isi asagidaki Group Policy (AllowNewsAndInterests=0) yapar — Widget dugmesi ve panosu kalkar.
                    @{
                        Command='try { Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarDa" -Value 0 -Type DWord -Force -ErrorAction Stop } catch {}';
                        UndoCommand='try { Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarDa" -Value 1 -Type DWord -Force -ErrorAction Stop } catch {}'
                    },

                    # 2. Grup İlkesi (GPO) - ASIL İŞİ YAPAN BU
                    # Bu ayar 0 olduğunda sistem widgetları tamamen devre dışı bırakır.
					@{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Dsh"; ValueName="AllowNewsAndInterests"; Type="DWord"; Data=0; Undo="DELETE_VALUE" }
                )
			},

			# === GÖREV ÇUBUĞU EK TWEAK'LERİ (FR33THY 1 Start Menu Taskbar.ps1 birebir) ===
			@{
				Name="Görev Çubuğunu Ortala (Win11)";
				SubCategory="Görev Çubuğu";
				Description="Windows 11 görev çubuğu simgelerini ortaya hizalar (Ayarlar > Kişiselleştirme > Görev çubuğu > Görev çubuğu hizalaması). Daha önce sola aldıysanız ortaya geri getirir.";
				Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; ValueName="TaskbarAl"; Type="DWord"; Data=1; Undo=0; RestartExplorer="Soft";
				DetectScript='
					$v = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarAl" -ErrorAction SilentlyContinue).TaskbarAl
					return ("$v" -eq "1")
				'
			},
			@{
				Name="Chat Butonunu Gizle";
				SubCategory="Görev Çubuğu";
				Description="Görev çubuğundaki Microsoft Teams 'Sohbet' düğmesini kaldırır. Güncel Windows 11 sürümlerinde bu düğme zaten çoğunlukla yoktur.";
				Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; ValueName="TaskbarMn"; Type="DWord"; Data=0; Undo="DELETE_VALUE"; RestartExplorer="Soft";
				DetectScript='
					$v = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarMn" -ErrorAction SilentlyContinue).TaskbarMn
					return ("$v" -eq "0")
				'
			},
			@{
				Name="Meet Now Butonunu Gizle";
				SubCategory="Görev Çubuğu";
				Description="Sistem tepsisindeki Skype 'Şimdi Toplantı Yap' (Meet Now) simgesini gizler.";
				Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Policies\Explorer"; ValueName="HideSCAMeetNow"; Type="DWord"; Data=1; Undo="DELETE_VALUE"; RestartExplorer="Soft";
				DetectScript='
					$v = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Policies\Explorer" -Name "HideSCAMeetNow" -ErrorAction SilentlyContinue).HideSCAMeetNow
					return ("$v" -eq "1")
				'
			},
			@{
				Name="Tüm Tray İkonlarını Göster";
				SubCategory="Görev Çubuğu";
				Description="Sistem tepsisindeki gizli simgelerin hepsini görev çubuğunda gösterir; '^' taşma menüsüne düşen simge kalmaz. Gezgin yeniden başlatılır.";
				RestartExplorer="Hard";
				DetectScript='
					$v = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer" -Name "EnableAutoTray" -ErrorAction SilentlyContinue).EnableAutoTray
					return ("$v" -eq "0")
				';
				Command='
					# Win10/Win11 ortak: EnableAutoTray=0 ile tasma menusunu kapatir
					Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer" -Name "EnableAutoTray" -Value 0 -Type DWord -Force

					# Win11 22H2+ icin: NotifyIconSettings altinda HER ikon kaydina IsPromoted=1 yaz.
					# Onceki bug: "if cur -ne 0 -and -ne null" hidden ikonlari (cur=0) BYPASS ediyordu —
					# esas gostermek istediklerimizi atliyordu. Simdi tum kayitlara unconditional set.
					$nip = Get-ChildItem -Path "registry::HKEY_CURRENT_USER\Control Panel\NotifyIconSettings" -Recurse -Force -ErrorAction SilentlyContinue
					foreach ($k in $nip) {
						Set-ItemProperty -Path "registry::$k" -Name "IsPromoted" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
					}
				';
				UndoCommand='
					Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer" -Name "EnableAutoTray" -Force -ErrorAction SilentlyContinue
					$nip = Get-ChildItem -Path "registry::HKEY_CURRENT_USER\Control Panel\NotifyIconSettings" -Recurse -Force -ErrorAction SilentlyContinue
					foreach ($k in $nip) {
						$cur = (Get-ItemProperty -Path "registry::$k" -Name "IsPromoted" -ErrorAction SilentlyContinue).IsPromoted
						if ($cur -ne 0 -and $cur -ne $null) {
							Set-ItemProperty -Path "registry::$k" -Name "IsPromoted" -Value 0 -Force -ErrorAction SilentlyContinue
						}
					}
				'
			},

