				Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Start\Companions\Microsoft.YourPhone_8wekyb3d8bbwe"; ValueName="IsEnabled"; Type="DWord"; Data=0; Undo=1
			},
			@{
				Name="Phone Link / Mobil Cihazları Kapat"; Since="2.0.0"; MinBuild=22621;
				Risk="Low"; RestartExplorer=$false;
				Description="Telefon-PC bağlantısını (Telefon Bağlantısı / Mobil cihazlar) bu bilgisayarda kapatır: hem kullanıcı ayarı hem tüm kullanıcılar için Group Policy kilidi yazılır (Ayarlar > Bluetooth ve cihazlar > Mobil cihazlar). Başlat menüsündeki 'Mobil cihaz' paneli ayrı tweak'tir.`n📚 Kaynak: Microsoft ADMX ('Phone-PC linking on this device'), ElevenForum.";
				Batch=@(
					@{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Mobility"; ValueName="PhoneLinkEnabled"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
					@{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\System"; ValueName="EnableMmx"; Type="DWord"; Data=0; Undo="DELETE_VALUE" }
				);
				DetectScript='
					$p = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System" -Name "EnableMmx" -ErrorAction SilentlyContinue).EnableMmx
					return ("$p" -eq "0")
				'
			}
        )
		"Oyun" = @(
			@{ Name="Kol ile Game Bar Açmayı Kapat"; Aliases=@("Kol ile Game Bar Acmayi Kapat"); Key="HKCU:\Software\Microsoft\GameBar"; ValueName="UseNexusForGameBarEnabled"; Type="DWord"; Data=0; Undo=1; RestartExplorer=$false;
			   Description="Kumandadaki Xbox (Nexus) tuşuna basınca Game Bar'ın açılmasını kapatır — oyun sırasında yanlışlıkla açılan Game Bar paneli ve odak kaybı biter.`n`nℹ️ Game Bar'ı KALDIRMAZ (bilerek): Oyun Modu algılaması, Xbox kablosuz kulaklık/kumanda ve çift CCD'li Ryzen X3D (7950X3D / 9950X3D) çekirdek park etme mekanizması Game Bar'a ihtiyaç duyar." },
			@{ Name="Oyun Çubuğu Başlangıç İpuçlarını Kapat"; Since="2.0.0"; Risk="Low"; RestartExplorer=$false;
			   Description="Oyun başlarken Game Bar'ın gösterdiği 'Win+G ile Oyun Çubuğunu açın' ipucu/panelini kapatır.`n`n✅ Game Bar'ın kendisi KAPANMAZ — çift CCD'li Ryzen X3D çekirdek yönlendirmesi, Oyun Modu ve Xbox aksesuarları etkilenmez.`n📚 Kaynak: Sophia Script, RyTuneX, optimizer.";
			   Key="HKCU:\Software\Microsoft\GameBar"; ValueName="ShowStartupPanel"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
			@{ Name="Uygulama Arşivlemeyi Kapat (Oyunlar Silinmesin)"; Since="2.0.0"; Risk="Low"; RestartExplorer=$false;
			   Description="Windows'un az kullanılan Microsoft Store / Game Pass uygulamalarını yer açmak için kendiliğinden 'arşivlemesini' (dosyalarını silip kısayolunu bırakmasını) engeller. Bir süre oynamadığınız Game Pass oyunu açarken yeniden indirme beklemezsiniz.`n📚 Kaynak: kubsonxtm/Windows-Tweaks, Microsoft ADMX (AllowAutomaticAppArchiving).";
			   Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\Appx"; ValueName="AllowAutomaticAppArchiving"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
			@{ Name="Oyun Modunu Aç"; RestartExplorer=$false;
			   # v1.3.0 (4. tur): AllowAutoGameMode da yazilir (optimizer, optimizerNXT, GTweak ortak)
			   Batch=@(
			       @{ Key="HKCU:\Software\Microsoft\GameBar"; ValueName="AutoGameModeEnabled"; Type="DWord"; Data=1; Undo="DELETE_VALUE" },
			       @{ Key="HKCU:\Software\Microsoft\GameBar"; ValueName="AllowAutoGameMode"; Type="DWord"; Data=1; Undo="DELETE_VALUE" }
			   );
			   Description="Windows Oyun Modu'nu açar: oyun açıkken Windows Update sürücü kurulumu ve yeniden başlatma bildirimleri ertelenir, oyuna CPU / GPU önceliği verilir. Windows 11'de varsayılan olarak açıktır ve AMD X3D işlemciler (özellikle çift CCD) için gereklidir; bu yüzden değer hiç yazılmamışsa da aktif görünür.`n`n↩️ Geri alma Oyun Modu'nu kapatmaz, Windows varsayılanına bırakır.";
			   DetectScript='
					$v = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\GameBar" -Name "AutoGameModeEnabled" -ErrorAction SilentlyContinue).AutoGameModeEnabled
					return ($null -eq $v -or "$v" -eq "1")
			   ' }
		)

       "Gizlilik ve Telemetri" = @(
            @{  Name="Reklam Kimliğini Kapat"; Description="Windows'un size özel reklam kimliğini kapatır (Ayarlar > Gizlilik ve güvenlik > Genel > 'Uygulamaların bana kişiselleştirilmiş reklamlar göstermesine izin ver'). Uygulamalar sizi bu kimlikle izleyip kişiselleştirilmiş reklam gösteremez.";
				SubCategory="Genel";
				RestartExplorer=$false;
				Batch=@(
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\CPSS\Store\AdvertisingInfo"; ValueName="Value"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo"; ValueName="Enabled"; Type="DWord"; Data=0; Undo=1 }
                ) 
			},
			@{  
				Name="Yerel olarak uygun içerik Kapat"; Description="Web sitelerinin dil listenize erişip size göre içerik sunmasını kapatır (Ayarlar > Gizlilik ve güvenlik > Genel > 'Web sitelerinin dil listeme erişerek yerel olarak uygun içerik sunmasına izin ver').";
				SubCategory="Genel";
				RestartExplorer=$false; # Bu ayar için explorer gerekmez, Settings uygulamasını kapatıp açmak yeterlidir.
				Batch=@(
					# 1. Dil Listesine Erişimi Kapat (Switch'i Kapalı konuma getirir)
					# 1 = Opt-Out (Kapalı), 0 = Opt-In (Açık)
					@{ Key="HKCU:\Control Panel\International\User Profile"; ValueName="HttpAcceptLanguageOptOut"; Type="DWord"; Data=1; Undo=0 },

					# 2. İnternet Explorer/Edge tarafındaki dil bilgisini temizle (İsteğe bağlı)
					@{ Key="HKCU:\Software\Microsoft\Internet Explorer\International"; ValueName="AcceptLanguage"; Type="String"; Data=""; Undo="DELETE_VALUE" }
				) 
			},
			@{ Name="Başlatma ve Arama Sonuçlarını Geliştir Kapat"; Description="Windows'un hangi uygulamaları başlattığınızı izleyip Başlat menüsü ve arama sonuçlarını buna göre düzenlemesini kapatır (Ayarlar > Gizlilik ve güvenlik > Genel > 'Başlat ve arama sonuçlarını iyileştirmek için uygulama başlatmaları izlensin')."; SubCategory="Genel"; Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"; ValueName="Start_TrackProgs"; Type="DWord"; Data=0; Undo=1; RestartExplorer=$false },
			@{ 
                Name="Ayarlar ve Windows Genelinde Önerileri Gizle"; Description="Ayarlar uygulamasında ve Windows genelinde çıkan önerilen içerikleri, uygulama tanıtımlarını ve 'Windows'tan en iyi şekilde yararlanın' tipi önerileri kapatır (Ayarlar > Gizlilik ve güvenlik > Genel > 'Ayarlar uygulamasında önerilen içeriği göster')."; 
                SubCategory="Genel";
                RestartExplorer=$false;
                Batch=@(
                    # --- 1. KULLANICI AYARLARI (HKCU) ---
                    # Kapatırken 0, Açarken 1 yapıyoruz.
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"; ValueName="SystemPaneSuggestionsEnabled"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"; ValueName="SubscribedContent-338393Enabled"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"; ValueName="SubscribedContent-353694Enabled"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"; ValueName="SubscribedContent-353696Enabled"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"; ValueName="SubscribedContent-338389Enabled"; Type="DWord"; Data=0; Undo=1 },

                    # --- 2. POLICY KİLİTLERİ (HKLM) - SORUNU ÇÖZEN KISIM ---
                    # Bu anahtarlar varsa, kullanıcı HKCU'dan açsa bile Windows geri kapatır.
                    # Uygula (Kapat): Değeri 1 yapıyoruz (Engelle).
                    # Geri Al (Aç): Değeri 0 yapıyoruz (Engeli Kaldır).
                    
                    # Windows İpuçları (Soft Landing)
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent"; ValueName="DisableSoftLanding"; Type="DWord"; Data=1; Undo="DELETE_VALUE" },
                    
                    # Tüketici Özellikleri (Consumer Features)
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent"; ValueName="DisableWindowsConsumerFeatures"; Type="DWord"; Data=1; Undo="DELETE_VALUE" }
                )
            },
            @{
                Name="Bildirimleri Ayarlar Uygulamasında Göster Kapat";
                SubCategory="Genel"; RestartExplorer=$false; Risk="Low";
                Description="Ayarlar uygulamasında çıkan Microsoft hesabı bildirimlerini ('hesabınızı tamamlayın', yedekleme hatırlatmaları vb.) kapatır. Ayar ve Group Policy birlikte yazılır, böylece güncellemeyle geri açılmaz.";
                Batch=@(
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\SystemSettings\AccountNotifications"; ValueName="EnableAccountNotifications"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\AccountNotifications"; ValueName="DisableAccountNotifications"; Type="DWord"; Data=1; Undo="DELETE_VALUE" }
                )
            },
			@{ 
                Name="Windows Tanılama Verileri Kapat"; 
                SubCategory="Genel"; 
                RestartExplorer=$false;
                Description="Windows'un Microsoft'a gönderdiği tanılama (telemetri) verisini Group Policy ile en düşük düzeye indirir ve 'Bağlı Kullanıcı Deneyimleri ve Telemetri' (DiagTrack) servisini kapatır.`n`nℹ️ Microsoft en düşük düzeyi (Güvenlik) yalnız Enterprise / Education sürümlerinde uygular; Home / Pro'da Windows bunu 'Gerekli' düzeyine yükseltebilir — o zaman tweak pasif görünür, bu beklenen bir durumdur. Sistemin açılmasını ya da güncellemeleri etkilemez.";
                # v1.3.0 (11. tur, birlestirme): gercek tespit — ilke 0 VE DiagTrack devre disi (ikisinden biri yeşil yakmaz)
                DetectScript='
                    $val = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "AllowTelemetry" -ErrorAction SilentlyContinue).AllowTelemetry
                    $s = Get-Service -Name "DiagTrack" -ErrorAction SilentlyContinue
                    return (("$val" -eq "0") -and $s -and "$($s.StartType)" -eq "Disabled")
                ';
                # Command kullanıyoruz çünkü önce izinleri (ACL) düzeltmemiz lazım.
                Command='
					$key = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection"
					if (-not (Test-Path $key)) { New-Item -Path $key -Force | Out-Null }
					
					# İzinlerle oynamak yerine sadece policy degerlerini atiyoruz
					try {
						Set-ItemProperty -Path $key -Name "AllowTelemetry" -Value 0 -Type DWord -Force
						Set-ItemProperty -Path $key -Name "MaxTelemetryAllowed" -Value 0 -Type DWord -Force
						# v1.3.0 (4. tur): MaxTelemetryAllowed in Windows un OKUDUGU yeri CurrentVersion\Policies\DataCollection (ustteki satir uyumluluk icin)
						$k2 = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection"
						if (-not (Test-Path $k2)) { New-Item -Path $k2 -Force | Out-Null }
						Set-ItemProperty -Path $k2 -Name "AllowTelemetry" -Value 0 -Type DWord -Force
						Set-ItemProperty -Path $k2 -Name "MaxTelemetryAllowed" -Value 0 -Type DWord -Force
						# DoNotShowFeedbackNotifications artik SADECE "Geri Bildirim Isteklerini Kapat" tweakinde (iki tweak ayni degeri paylasinca birini geri almak digerini bozuyordu)
						Stop-Service "DiagTrack" -Force -ErrorAction SilentlyContinue
						Set-Service "DiagTrack" -StartupType Disabled -ErrorAction SilentlyContinue
					} catch {
						Write-Warning "Telemetri kapatılırken erişim engellendi. GPO kullanılıyor."
					}
				';
                
                # Geri Alma: Değerleri silerek varsayılana döndür
                UndoCommand='
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "AllowTelemetry" -ErrorAction SilentlyContinue;
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "MaxTelemetryAllowed" -ErrorAction SilentlyContinue;
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" -Name "AllowTelemetry" -ErrorAction SilentlyContinue;
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" -Name "MaxTelemetryAllowed" -ErrorAction SilentlyContinue;
                    Set-Service "DiagTrack" -StartupType Automatic -ErrorAction SilentlyContinue;
                    Start-Service "DiagTrack" -ErrorAction SilentlyContinue;
                ';
            },
