            @{
                Name="Arka Plan Uygulamalarını Kapat (Sistem Politikası)";
                SubCategory="Uygulama İzinleri";
                Description="Microsoft Store (UWP) uygulamalarının arka planda çalışmasını Group Policy ile tüm kullanıcılar için engeller. Xbox Game Bar istisna tutulur (çift CCD Ryzen X3D çekirdek yönlendirmesi ve Oyun Modu için gerekli).`n`n✅ Discord, Steam, masaüstü Spotify, medya tuşları ve PrtSc / Ekran Alıntısı etkilenmez.`n⚠️ Posta, Takvim, Fotoğraflar, Telefon Bağlantısı ve Mağaza WhatsApp arka planda bildirim gönderemez. Spotify'ın Mağaza sürümünde medya tuşu sorunu olursa geri alın.`nℹ️ Uygulama ve geri alma sonrası Ayarlar > Arka plan uygulamaları sayfası açılır.";
                DetectScript='
                    $v = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy" -Name "LetAppsRunInBackground" -ErrorAction SilentlyContinue).LetAppsRunInBackground
                    return ("$v" -eq "2")
                ';
                Command='
                    $key = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy"
                    if (-not (Test-Path $key)) { New-Item -Path $key -Force | Out-Null }
                    Set-ItemProperty -Path $key -Name "LetAppsRunInBackground" -Value 2 -Type DWord -Force
                    # v1.3.0 (4. tur): Game Bar (Xbox Gaming Overlay) istisna — cift CCD Ryzen X3D cekirdek park mekanizmasi ve
                    # Oyun Modu algilamasi icin arka planda calismasi gerekir (resmi Policy CSP: ForceAllowTheseApps).
                    Set-ItemProperty -Path $key -Name "LetAppsRunInBackground_ForceAllowTheseApps" -Value ([string[]]@("Microsoft.XboxGamingOverlay_8wekyb3d8bbwe")) -Type MultiString -Force
                    Start-Process "ms-settings:privacy-backgroundapps" -ErrorAction SilentlyContinue
                ';
                UndoCommand='
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy" -Name "LetAppsRunInBackground" -Force -ErrorAction SilentlyContinue
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy" -Name "LetAppsRunInBackground_ForceAllowTheseApps" -Force -ErrorAction SilentlyContinue
                    Start-Process "ms-settings:privacy-backgroundapps" -ErrorAction SilentlyContinue
                ';
                RestartExplorer=$false
            },

