            @{
                Name="Cloud Clipboard Devre Disi (Win+V Senkronizasyonu Kapat)";
                SubCategory="Genel";
                Risk="Low"; RestartExplorer=$false;
                Description="Panonun (kopyaladıklarınızın) Microsoft hesabı üzerinden diğer cihazlarla bulut senkronizasyonunu Group Policy ile kapatır. Kopyaladıklarınız bu bilgisayarda kalır; şifre, kart numarası gibi bilgiler yanlışlıkla buluta gitmez.`n`n✅ Ctrl+C / Ctrl+V ve Win+V pano geçmişi normal çalışır (geçmişi kapatmak ayrı tweak: 'Pano Geçmişini (Win+V) Kapat').`n⚠️ Telefon / başka bilgisayarla pano paylaşımı çalışmaz.";
                DetectScript='
                    $k = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System"
                    $v = (Get-ItemProperty -Path $k -Name "AllowCrossDeviceClipboard" -ErrorAction SilentlyContinue).AllowCrossDeviceClipboard
                    # 14. tur: pano GECMISI kapaliysa (eski surum ya da "Pano Gecmisini Kapat" tweaki) bu kullanicinin tercihi —
                    # PASIF gosterilmez (eskiden gosteriliyor, yeniden uygulama gecmisi istemeden aciyordu).
                    return ("$v" -eq "0")
                ';
                Command='
                    $k = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System"
                    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
                    Set-ItemProperty -Path $k -Name "AllowCrossDeviceClipboard" -Value 0 -Type DWord -Force
                    # 14. tur: pano gecmisine (Win+V) DOKUNULMAZ — ayri tweak: "Pano Gecmisini (Win+V) Kapat"
                    $u = "HKCU:\Software\Microsoft\Clipboard"
                    if (-not (Test-Path $u)) { New-Item -Path $u -Force | Out-Null }
                    Set-ItemProperty -Path $u -Name "EnableCloudClipboard" -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path $u -Name "CloudClipboardAutomaticUpload" -Value 0 -Type DWord -Force
                ';
                UndoCommand='
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System" -Name "AllowCrossDeviceClipboard" -Force -ErrorAction SilentlyContinue
                    Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Clipboard" -Name "EnableCloudClipboard" -Force -ErrorAction SilentlyContinue
                    Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Clipboard" -Name "CloudClipboardAutomaticUpload" -Force -ErrorAction SilentlyContinue
                '
            },
            # v1.3.0 (14. tur): kullanici panoyu kullanmiyor ve kapali tutuyor — Cloud Clipboard tweakinden ayri, bilincli secim
            @{
                Name="Pano Geçmişini (Win+V) Kapat"; Since="2.0.0";
                SubCategory="Genel";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows pano geçmişini (Win+V ile açılan, kopyalanan son öğeler listesi) ilkeyle kapatır. Kopyala / yapıştır normal çalışır; sadece geçmiş tutulmaz (parola, kart numarası gibi kopyalanan bilgiler bellekte birikmez).`n`nℹ️ Bulut senkronizasyonu ayrı tweaktir: 'Cloud Clipboard Devre Disi'. Geri alma ilkeyi kaldırır, Ayarlar > Sistem > Pano'dan yeniden açılabilir.";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\System"; ValueName="AllowClipboardHistory"; Type="DWord"; Data=0; Undo="DELETE_VALUE"
            },

            @{
                Name="Connected Devices Platform (CDP) Servisini El Ile Al";
                Aliases=@("Connected Devices Platform (CDP) Servisini Kapat");
                SubCategory="Telemetri";
                Risk="Low"; RestartExplorer=$false;
                Description="Bağlı Cihazlar Platformu servisini (CDPSvc) durdurur ve 'El ile' başlatmaya alır — kapatmaz. Arka planda sürekli çalışmaz; Bluetooth Swift Pair veya Yakın Paylaşım gerektiğinde Windows yine başlatır.`n`n⚠️ Telefon Bağlantısı, PC'den sesli arama ve telefon-PC dosya paylaşımı gecikebilir ya da zayıflayabilir.`n↩️ Geri alma servisi yeniden otomatik başlatır.";
                Command='
                    try { Stop-Service "CDPSvc" -Force -ErrorAction SilentlyContinue } catch {}
                    # v1.3.0: Devre Disi yerine El ile — Bluetooth Swift Pair eslestirme bildirimleri ve Yakin Paylasim gerektiginde calisabilir
                    try { Set-Service "CDPSvc" -StartupType Manual -ErrorAction SilentlyContinue } catch {}
                ';
                UndoCommand='
                    try { Set-Service "CDPSvc" -StartupType Automatic -ErrorAction SilentlyContinue } catch {}
                    try { Start-Service "CDPSvc" -ErrorAction SilentlyContinue } catch {}
                ';
                DetectScript='
                    $s = Get-Service -Name "CDPSvc" -ErrorAction SilentlyContinue
                    return ($s -and ("$($s.StartType)" -eq "Disabled" -or "$($s.StartType)" -eq "Manual"))
                '
            },

