                    # v1.3.0 (4. tur): ek icerik teslim anahtarlari (optimizer, RyTuneX, kubsonxtm ortak)
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"; ValueName="PreInstalledAppsEverEnabled"; Type="DWord"; Data=0; Undo=1 },
