            @{
                Name="Bulut Optimize İçerik, Üçüncü Taraf Öneriler ve Çevrimiçi İpuçlarını Kapat";
                SubCategory="Reklam ve Öneriler"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows'un buluttan indirdiği 'optimize edilmiş' tanıtım içeriklerini, üçüncü taraf uygulama önerilerini ve Ayarlar'daki çevrimiçi ipuçlarını Group Policy ile kapatır.`n`n✅ Discord/Spotify bildirimleri ve Windows güncellemeleri etkilenmez.`n📚 Kaynak: RyTuneX, optimizer, optimizerNXT, GTweak; Microsoft ADMX (CloudContent).";
                Batch=@(
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent"; ValueName="DisableCloudOptimizedContent"; Type="DWord"; Data=1; Undo="DELETE_VALUE" },
                    @{ Key="HKCU:\Software\Policies\Microsoft\Windows\CloudContent"; ValueName="DisableThirdPartySuggestions"; Type="DWord"; Data=1; Undo="DELETE_VALUE" },
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer"; ValueName="AllowOnlineTips"; Type="DWord"; Data=0; Undo="DELETE_VALUE" }
                )
