            @{
                Name="Dev Home ve Yeni Outlook'un Kendiliğinden Kurulmasını Engelle";
                SubCategory="Reklam ve Öneriler"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows Update'in Dev Home ve yeni Outlook uygulamalarını kendiliğinden kurmasını engeller: bekleyen kurulum görevleri silinir ve kalıcı engelleme kaydı yazılır (yalnız görevleri silmek özellik güncellemesinde geri gelir).`n📚 Kaynak: Microsoft Orchestrator (BlockedOobeUpdaters), GTweak.";
                DetectScript='
                    $b = "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe"
                    $gone = (-not (Test-Path "$b\DevHomeUpdate") -and -not (Test-Path "$b\OutlookUpdate"))
                    $blk = @((Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Orchestrator" -Name "BlockedOobeUpdaters" -ErrorAction SilentlyContinue).BlockedOobeUpdaters)
                    return ($gone -and ($blk -contains "MS_DevHome") -and ($blk -contains "MS_Outlook"))
                ';
                Command='
                    foreach ($n in @("DevHomeUpdate","OutlookUpdate")) { Remove-Item -Path "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe\$n" -Recurse -Force -ErrorAction SilentlyContinue }
                    $orch = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Orchestrator"
                    if (-not (Test-Path $orch)) { New-Item -Path $orch -Force | Out-Null }
                    Set-ItemProperty -Path $orch -Name "BlockedOobeUpdaters" -Value ([string[]]@("MS_DevHome","MS_Outlook")) -Type MultiString -Force
                ';
                UndoCommand='
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Orchestrator" -Name "BlockedOobeUpdaters" -Force -ErrorAction SilentlyContinue
                '
            },
            @{
                Name="OneDrive Klasör Yedekleme Dayatmasını Engelle (KFM)";
                SubCategory="Reklam ve Öneriler"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="OneDrive'ın Masaüstü / Belgeler / Resimler klasörlerinizi 'yedeklemek' için buluta taşıma (Known Folder Move) teklifini ve bildirimlerini Group Policy ile engeller. Oyun ayar dosyaları ve ekran görüntüleri yerel klasörde kalır (bazı oyunlar OneDrive'a taşınan 'Belgeler' yüzünden kayıt/ayar sorunu yaşar).`n`n✅ OneDrive'ı kullanmaya devam edebilirsiniz; sadece klasör taşıma dayatması kapanır. Zaten taşınmış klasörler etkilenmez.`n📚 Kaynak: Winrift, Microsoft OneDrive ADMX (KFMBlockOptIn).";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\OneDrive"; ValueName="KFMBlockOptIn"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Ayarlar Ana Sayfasında Microsoft 365 Reklamlarını Kapat";
                SubCategory="Reklam ve Öneriler"; Since="2.0.0"; MinBuild=22631;
                Risk="Low"; RestartExplorer=$false;
                Description="Ayarlar 'Giriş' sayfasındaki Microsoft 365 / Game Pass / OneDrive hesap durumu kartlarını Group Policy ile kapatır. Ana sayfanın kendisi kalır (gizlemek için 'Ayarlar Ana Sayfasını (Home) Tamamen Gizle').`n`nℹ️ Microsoft bu ilkeyi Enterprise / Education için belgeler; Home / Pro'da kartlar kalabilir.";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent"; ValueName="DisableConsumerAccountStateContent"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },

            @{
                Name="Ayarlar Ana Sayfasını (Home) Tamamen Gizle";
                SubCategory="Reklam ve Öneriler"; Since="2.0.0"; MinBuild=22631;
                Risk="Low"; RestartExplorer=$false;
                Description="Ayarlar uygulaması açıldığında reklam/öneri kartlı 'Giriş' sayfası yerine doğrudan Sistem sayfası açılır. SettingsPageVisibility policy'sine 'home' eklenir.`n`n💡 Daha önce başka sayfaları gizlediyseniz (hide:...) korunur, sadece 'home' eklenir/çıkarılır. 'showonly:' modu kullanılıyorsa dokunulmaz.";
                DetectScript='
                    $cur = "$((Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" -Name "SettingsPageVisibility" -ErrorAction SilentlyContinue).SettingsPageVisibility)"
                    return ($cur -match "(?i)^hide:(.*;)?home(;|$)")
                ';
                Command='
                    $k = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer"
                    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
                    $cur = "$((Get-ItemProperty -Path $k -Name "SettingsPageVisibility" -ErrorAction SilentlyContinue).SettingsPageVisibility)"
                    if ($cur -match "(?i)^showonly:") {
                        Write-Host "[SettingsHome] showonly: modu mevcut — dokunulmadi."
                    } else {
                        $pages = @()
                        if ($cur -match "(?i)^hide:(.*)$") { $pages = @($Matches[1].Split(";") | Where-Object { $_ }) }
                        if ($pages -notcontains "home") { $pages += "home" }
                        Set-ItemProperty -Path $k -Name "SettingsPageVisibility" -Value ("hide:" + ($pages -join ";")) -Type String -Force
                    }
                ';
                UndoCommand='
                    $k = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer"
                    $cur = "$((Get-ItemProperty -Path $k -Name "SettingsPageVisibility" -ErrorAction SilentlyContinue).SettingsPageVisibility)"
                    if ($cur -match "(?i)^hide:(.*)$") {
                        $pages = @($Matches[1].Split(";") | Where-Object { $_ -and $_ -ne "home" })
                        if ($pages.Count -gt 0) {
                            Set-ItemProperty -Path $k -Name "SettingsPageVisibility" -Value ("hide:" + ($pages -join ";")) -Type String -Force
                        } else {
                            Remove-ItemProperty -Path $k -Name "SettingsPageVisibility" -Force -ErrorAction SilentlyContinue
                        }
                    }
                '
            },

