                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\EdgeUpdate"; ValueName="RemoveDesktopShortcut{56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}"; Type="DWord"; Data=1; Undo="DELETE_VALUE" }
