        # --- 5. SİSTEM VE OYUN ---
        "Sistem ve Oyun" = @(

            @{
                Name="Yapışkan Tuşları Kapat"; RestartExplorer=$false; Risk="Low";
                Description="Oyun sırasında oyunu masaüstüne atan erişilebilirlik kısayollarını kapatır:`n• Yapışkan Tuşlar — Shift'e 5 kez basınca açılan pencere`n• Filtre Tuşları — sağ Shift'i 8 sn basılı tutunca açılan pencere`n• Geçiş Tuşları — Num Lock'u 5 sn basılı tutunca çalan ses / pencere`n`nÖzellikler kapalı kalır; yalnız kısayolla yanlışlıkla açılmaları engellenir. Ayarlar > Erişilebilirlik > Klavye'den yine açabilirsiniz.`n📚 Kaynak: Win11Debloat, GTweak, RyTuneX.";
                Batch=@(
                    @{ Key="HKCU:\Control Panel\Accessibility\StickyKeys"; ValueName="Flags"; Type="String"; Data="506"; Undo="510" },
                    @{ Key="HKCU:\Control Panel\Accessibility\Keyboard Response"; ValueName="Flags"; Type="String"; Data="122"; Undo="126" },
                    @{ Key="HKCU:\Control Panel\Accessibility\ToggleKeys"; ValueName="Flags"; Type="String"; Data="58"; Undo="62" },
                    # v1.3.0 (4. tur): oturum acma ekrani (HKU\.DEFAULT) — optimizer / optimizerNXT ile ayni
                    @{ Key="Registry::HKEY_USERS\.DEFAULT\Control Panel\Accessibility\StickyKeys"; ValueName="Flags"; Type="String"; Data="506"; Undo="510" },
                    @{ Key="Registry::HKEY_USERS\.DEFAULT\Control Panel\Accessibility\Keyboard Response"; ValueName="Flags"; Type="String"; Data="122"; Undo="126" },
                    @{ Key="Registry::HKEY_USERS\.DEFAULT\Control Panel\Accessibility\ToggleKeys"; ValueName="Flags"; Type="String"; Data="58"; Undo="62" }
                )
            },
            @{
                Name="Klavye Tekrar Gecikmesini En Kısa Yap"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Bir tuşu basılı tuttuğunuzda tekrarlamaya başlamadan önceki bekleme süresini en kısaya indirir (Denetim Masası > Klavye > Tekrar gecikmesi: Kısa). Silme / ok tuşlarıyla gezinme ve basılı tutulan oyun içi metin girişleri daha çevik olur. Anında uygulanır.`n`nℹ️ Oyunlar tuşları ham olarak okuduğu için oyun içi hareket tuşları etkilenmez — fark yazarken ve masaüstünde hissedilir.`n📚 Kaynak: RyTuneX.";
                DetectScript='
                    return ("$((Get-ItemProperty -Path "HKCU:\Control Panel\Keyboard" -Name "KeyboardDelay" -ErrorAction SilentlyContinue).KeyboardDelay)" -eq "0")
                ';
                Command='
                    Set-ItemProperty -Path "HKCU:\Control Panel\Keyboard" -Name "KeyboardDelay" -Value "0" -Type String -Force
                    try { [void][NativeMethods]::SystemParametersInfo(0x0017, 0, "", 3) } catch {}
                ';
                UndoCommand='
                    Set-ItemProperty -Path "HKCU:\Control Panel\Keyboard" -Name "KeyboardDelay" -Value "1" -Type String -Force
                    try { [void][NativeMethods]::SystemParametersInfo(0x0017, 1, "", 3) } catch {}
                '
            },
            @{
                Name="Açılışta NumLock'u Açık Başlat"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Bilgisayar açılınca / oturum açma ekranında NumLock açık gelir (şifrede sayı tuşlarını kullananlar için). Numpad'i olmayan klavyelerde etkisizdir.`n📚 Kaynak: Sophia Script.";
                Key="Registry::HKEY_USERS\.DEFAULT\Control Panel\Keyboard"; ValueName="InitialKeyboardIndicators"; Type="String"; Data="2147483650"; Undo="2147483648"
            },
            @{
                Name="Açılış ve Kapanışta Ayrıntılı Durum Mesajlarını Göster"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Açılış, oturum açma ve kapanışta 'Lütfen bekleyin' yerine Windows'un o an ne yaptığını gösterir (ör. 'Grup İlkesi uygulanıyor', 'X hizmeti durduruluyor'). Yavaş açılış / kapanışın sebebini görmeyi kolaylaştırır; hızı etkilemez.`n📚 Kaynak: winscript, RyTuneX, optimizer.";
                Key="HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System"; ValueName="VerboseStatus"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Defender Tarama CPU Kullanımını Sınırla (%25)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Microsoft Defender ZAMANLANMIŞ / hızlı tarama ortalama CPU tavanını %50'den %25'e indirir (ScanAvgCPULoadFactor). Taramalar uzar, planlı tarama takılması azalabilir.`n`n⚠️ Oyun sırası gerçek zamanlı koruma (RTP) CPU'su bundan düşmez. Bulut koruması ve imza güncellemeleri etkilenmez.`n📚 Kaynak: Microsoft Set-MpPreference.";
                DetectScript='
                    # v1.3.0 (§89): Defender modülü yerine kayıt defteri (ilke, sonra Defender ayarı); ikisi de yoksa eski yol
                    $v = $null
                    foreach ($p in @("HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Scan", "HKLM:\SOFTWARE\Microsoft\Windows Defender\Scan")) {
                        if ($null -eq $v) { $v = (Get-ItemProperty -LiteralPath $p -Name AvgCPULoadFactor -ErrorAction SilentlyContinue).AvgCPULoadFactor }
                    }
                    if ($null -eq $v) { $v = (Get-MpPreference -ErrorAction SilentlyContinue).ScanAvgCPULoadFactor }
                    return ($v -and [int]$v -le 25)
                ';
                Command='Set-MpPreference -ScanAvgCPULoadFactor 25 -ErrorAction SilentlyContinue';
                UndoCommand='Set-MpPreference -ScanAvgCPULoadFactor 50 -ErrorAction SilentlyContinue'
            },
            @{
                Name="Sanal Makine Platformunu Kapat (Sanallaştırma Yükü - Oyun FPS)"; Since="2.0.0";
                Risk="High"; RestartExplorer=$false; RequiresReboot=$true;
                Description="Windows özelliği 'Sanal Makine Platformu'nu (Virtual Machine Platform) kaldırır. Microsoft'un oyun performansı rehberinde (2025'te kaldırıldı, arşivde mevcut) Bellek Bütünlüğü ile birlikte önerilen ikinci adımdır; sanallaştırma katmanının CPU yükü düşer, bazı CPU ağırlıklı oyunlarda birkaç yüzde FPS kazancı ölçülmüştür (Tom's Hardware VBS testleri).`n`n⚠️ YÜKSEK RİSK — şunlar ÇALIŞMAZ: WSL2 (Linux), Docker Desktop, Windows Sandbox, Android alt sistemi, bazı emülatörler.`n🔒 Hyper-V VM, WSL distrosu veya çalışan Docker varsa Apply kilitlenir (özellik açık olması yetmez). Sadece özellik kuruluysa sorulur.`n⚠️ Bazı anti-cheat'ler (Riot Vanguard, FACEIT) VBS/Bellek Bütünlüğü isteyebilir — oyun açılmazsa geri alın.`n⚠️ Yeniden başlatma gerekir. Hiçbir profile eklenmedi.`n📚 Kaynak: Microsoft (arşiv) 'Options to optimize gaming performance in Windows 11', valleyofdoom/PC-Tuning.";
                DetectScript='
                    # v1.3.0 (§89): bütün özellik listesini süzmek yerine doğrudan WMI nesnesi (~500 -> ~85 ms); olmazsa eski yol
                    $f = $null
                    try { $f = [wmi]"root\cimv2:Win32_OptionalFeature.Name=''VirtualMachinePlatform''" } catch { $f = $null }
                    if (-not $f) { $f = Get-CimInstance -ClassName Win32_OptionalFeature -Filter "Name=''VirtualMachinePlatform''" -ErrorAction SilentlyContinue }
                    return (-not $f -or [int]$f.InstallState -ne 1)
                ';
                Command='
                    if (-not (Confirm-VirtHeavyTweak "Sanal Makine Platformu")) { return }
                    try { Disable-WindowsOptionalFeature -Online -FeatureName VirtualMachinePlatform -NoRestart -ErrorAction Stop | Out-Null; Write-Host "[VMP] Kapatildi — yeniden baslatma sonrasi gecerli." } catch { Write-Host "[VMP] Kapatilamadi: $($_.Exception.Message)" }
                ';
                UndoCommand='
                    try { Enable-WindowsOptionalFeature -Online -FeatureName VirtualMachinePlatform -All -NoRestart -ErrorAction Stop | Out-Null } catch {}
                '
            },
            @{
                Name="Mavi Ekranda Ayrıntılı Hata Bilgisi Göster"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Mavi ekran (BSOD) olduğunda sadece üzgün surat yerine hata kodunu ve parametrelerini de gösterir. Çökmenin hangi sürücüden kaynaklandığını anlamayı ve 'Çökme Analizi' sekmesindeki kayıtlarla eşleştirmeyi kolaylaştırır. Sistem davranışını değiştirmez.`n📚 Kaynak: Sparkle (detailed-bsod), RyTuneX.";
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl"; ValueName="DisplayParameters"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Xbox Game DVR Kapat"; RestartExplorer=$false; Risk="Low";
                Description="Xbox Game Bar'ın arka planda sürekli video kaydı tutmasını (son 30 sn'yi kaydet / Game DVR) kapatır — oyun sırasında GPU kodlayıcı ve disk yükü kalkar.`n`n✅ Game Bar'ın kendisi, Oyun Modu, Xbox kumanda / kulaklık desteği, Discord, PrtSc ve Ekran Alıntısı etkilenmez. Yalnız Game Bar kaydı (Win+Alt+R / Win+Alt+PrtSc) çalışmaz — NVIDIA ShadowPlay / AMD ReLive / OBS kullananlar için sorun değildir.";
                Batch=@(
                    @{ Key="HKCU:\System\GameConfigStore"; ValueName="GameDVR_Enabled"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR"; ValueName="AppCaptureEnabled"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR"; ValueName="HistoricalCaptureEnabled"; Type="DWord"; Data=0; Undo=1 }
                );
                DetectScript='
                    $v = (Get-ItemProperty -Path "HKCU:\System\GameConfigStore" -Name "GameDVR_Enabled" -ErrorAction SilentlyContinue).GameDVR_Enabled
                    return ("$v" -eq "0")
                '
            },
            @{
                Name="Hazırda Bekletmeyi Kapat (Hibernate)";
                Description="Hazırda bekletmeyi kapatır ve hiberfil.sys dosyasını siler (RAM boyutunun bir kısmı kadar disk alanı geri gelir). Hızlı Başlangıç hazırda bekletmeye bağlı olduğu için o da kapanır.`n`n⚠️ Dizüstünde uygulamadan önce sorulur: pil bitince oturumun diske kaydedilmesi çalışmaz.`n↩️ Geri alma hazırda bekletmeyi açar; Hızlı Başlangıç tercihi 'Hızlı Başlatmayı Kapat' tweak'ine bırakılır.";
                RestartExplorer=$false;
                DetectScript='
                    return (-not (Test-Path "$env:SystemDrive\hiberfil.sys"))
                ';
                Command='
                    if (-not (Confirm-LaptopPowerTweak "Hazirda Bekletmeyi Kapat")) { return }
                    powercfg -h off
                    $p = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power"
                    if (-not (Test-Path $p)) { New-Item -Path $p -Force -ErrorAction SilentlyContinue | Out-Null }
                    Set-ItemProperty -Path $p -Name "HiberbootEnabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
                    Write-Host "[Hibernate] hiberfile silindi, HiberbootEnabled=0 (Hizli Baslangic da olu)."
                ';
                UndoCommand='
                    powercfg -h on
                    # v1.3.0 (11. tur, birlestirme): HiberbootEnabled ZORLA 1 yapilmaz — "Hizli Baslatmayi Kapat" tweaki aciksa onu bozardi.
                    # Hizli Baslangic tercihi o tweakte; hiberfile acilinca Windows onceki tercihe gore davranir.
                    Write-Host "[Hibernate] hiberfile acildi (Hizli Baslangic tercihine dokunulmadi)."
                '
            },

            # === UAC Never Notify (EnableLUA=1 kalir; EnableLUA=0 UWP'yi kirar) ===
            @{
                Name="UAC Bildirimini Kapat (Never Notify)";
                Aliases=@("UAC (Kullanıcı Hesabı Denetimi) Kapat", "UAC (Kullanıcı Hesabı Denetimi) Kapat (Risk: Yüksek)");
                Description="Kullanıcı Hesabı Denetimi kaydırıcısını 'Hiçbir zaman bildirme' yapar: yönetici hesabında onay penceresi çıkmaz, programlar sormadan yönetici yetkisi alır. UAC tamamen kapatılmaz — tamamen kapatmak Mağaza uygulamalarını (Ekran Alıntısı, Hesap Makinesi, Fotoğraflar, Xbox) bozar.`n`n⚠️ YÜKSEK RİSK: kötü amaçlı bir program da sessizce yönetici yetkisi alabilir.`n⚠️ Yeniden başlatma gerekir.";
                Risk="High"; RestartExplorer=$false; RequiresReboot=$true;
                DetectScript='
                    $p = Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" -ErrorAction SilentlyContinue
                    return ("$($p.EnableLUA)" -ne "0" -and "$($p.ConsentPromptBehaviorAdmin)" -eq "0")
                ';
                Batch=@(
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System"; ValueName="EnableLUA"; Type="DWord"; Data=1; Undo=1 },
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System"; ValueName="ConsentPromptBehaviorAdmin"; Type="DWord"; Data=0; Undo=5 },
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System"; ValueName="PromptOnSecureDesktop"; Type="DWord"; Data=0; Undo=1 }
                )
            },

            # === LOUDNESS EQ AKTIF ET (FR33THY 24 Loudness EQ.ps1 birebir) ===
            @{
                Name="Ses: Loudness EQ Aktif Et (Enhancements Tab Unhide)";
                Description="Ses çıkış aygıtlarına 'Ses Yüksekliği Dengeleme' (Loudness Equalization) iyileştirmesini ekler: Ses özellikleri penceresinde 'Geliştirmeler' sekmesi görünür ve ses seviyesi dengelenir — sessiz diyaloglar yükselir, gürültülü sahneler kısılır.`n`n⚠️ Ses servisi yeniden başlatılır (anlık kesinti olabilir).`n✅ Yalnız bu ayarı eksik olan aygıtlara yazılır; geri alma yalnız MrClean'in eklediklerini siler.`n💡 Çalışmazsa ses sürücüsünü yeniden yükleyin ya da başka bir aygıt deneyin.";
                Risk="Low"; RestartExplorer=$false;
                DetectScript='
                    # v1.3.0 (8. tur): DOGRU tespit — aktif her cikis aygitinda (FxProperties olan) Enhancements UI degeri var mi.
                    # Eskiden "herhangi bir aygitta var" sayiliyordu; bu deger cogu aygitta zaten Windows varsayilani -> hep "aktif" gorunuyordu.
                    $base = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render"
                    $n = 0; $miss = 0
                    foreach ($d in @(Get-ChildItem -Path $base -ErrorAction SilentlyContinue)) {
                        if ((Get-ItemProperty $d.PSPath -ErrorAction SilentlyContinue).DeviceState -ne 1) { continue }
                        $fx = "$($d.PSPath)\FxProperties"; if (-not (Test-Path $fx)) { continue }
                        $n++; if ($null -eq (Get-ItemProperty -Path $fx -Name "{d04e05a6-594b-4fb6-a80d-01af5eed7d1d},3" -ErrorAction SilentlyContinue)) { $miss++ }
                    }
                    # 14. tur: MrClean in ekledigi aygit listesi varsa ve en az biri hala ayarliysa uygulanmis say (sonradan takilan
                    # yeni aygit — monitor hoparloru vb. — tum tweaki pasif gostermesin). Liste yoksa eski kati kural.
                    $added = @((Get-ItemProperty -Path "HKLM:\SOFTWARE\MrClean" -Name "LoudnessEqAdded" -ErrorAction SilentlyContinue).LoudnessEqAdded)
                    if ($added.Count -gt 0) { return ($n -gt 0 -and $miss -lt $n) }
                    return ($n -gt 0 -and $miss -eq 0)
                ';
                Command='
                    # v1.3.0 (8. tur): FxProperties ACL i yoneticiye sadece SetValue verir -> .NET ile SetValue hakkiyla yazilir (Set-MrCleanFxValue);
                    # eski regedit /s ice aktarma ve Remove-ItemProperty sessizce basarisiz oluyordu. Sadece EKSIK olan aygita yazilir, eklenenler
                    # kaydedilir; geri alma SADECE onlari siler (Windows un kendi varsayilan degerine dokunulmaz).
                    $base = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render"
                    $name = "{d04e05a6-594b-4fb6-a80d-01af5eed7d1d},3"
                    $added = @()
                    foreach ($d in @(Get-ChildItem -Path $base -ErrorAction SilentlyContinue)) {
                        $fx = "$($d.PSPath)\FxProperties"; if (-not (Test-Path $fx)) { continue }
                        if ($null -ne (Get-ItemProperty -Path $fx -Name $name -ErrorAction SilentlyContinue)) { continue }
                        try { Set-MrCleanFxValue ("HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render\" + $d.PSChildName + "\FxProperties") $name "{5860E1C5-F95C-4a7a-8EC8-8AEF24F379A1}"; $added += $d.PSChildName } catch {}
                    }
                    $bk = "HKLM:\SOFTWARE\MrClean"; if (-not (Test-Path $bk)) { New-Item -Path $bk -Force | Out-Null }
                    $prev = @((Get-ItemProperty -Path $bk -Name "LoudnessEqAdded" -ErrorAction SilentlyContinue).LoudnessEqAdded)
                    New-ItemProperty -Path $bk -Name "LoudnessEqAdded" -PropertyType MultiString -Value ([string[]]@(@($prev) + $added | Where-Object { $_ } | Select-Object -Unique)) -Force | Out-Null
                    WpfLog "[LoudnessEQ] $($added.Count) aygita Enhancements sekmesi eklendi."
                    if ($added.Count -gt 0) {
                        $deps = @((Get-Service Audiosrv).DependentServices | Where-Object { "$($_.Status)" -eq "Running" } | ForEach-Object { $_.Name })
                        Restart-Service audiosrv -Force -ErrorAction SilentlyContinue; foreach ($s in $deps) { Start-Service $s -ErrorAction SilentlyContinue }
                    }
                    Start-Process mmsys.cpl -ErrorAction SilentlyContinue
                ';
                UndoCommand='
                    $bk = "HKLM:\SOFTWARE\MrClean"
                    $list = @((Get-ItemProperty -Path $bk -Name "LoudnessEqAdded" -ErrorAction SilentlyContinue).LoudnessEqAdded)
                    foreach ($g in @($list | Where-Object { $_ })) {
                        try { Set-MrCleanFxValue ("HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render\" + $g + "\FxProperties") "{d04e05a6-594b-4fb6-a80d-01af5eed7d1d},3" $null } catch {}
                    }
                    Remove-ItemProperty -Path $bk -Name "LoudnessEqAdded" -ErrorAction SilentlyContinue
                    if ($list.Count -gt 0) {
                        $deps = @((Get-Service Audiosrv).DependentServices | Where-Object { "$($_.Status)" -eq "Running" } | ForEach-Object { $_.Name })
                        Restart-Service audiosrv -Force -ErrorAction SilentlyContinue; foreach ($s in $deps) { Start-Service $s -ErrorAction SilentlyContinue }
                    }
                    WpfLog "[LoudnessEQ] MrClean in ekledigi $(@($list | Where-Object { $_ }).Count) deger kaldirildi (Windows varsayilanlarina dokunulmadi)."
                '
            },

            # --- YENİ EKLENEN GÜVENLİ PERFORMANS / INPUT LAG TWEAK'LERİ (Intel/AMD agnostik) ---

            @{
                Name="Power Throttling Kapat (CPU Tam Frekans)";
                Description="Windows'un 'Power Throttling' (EcoQoS) mekanizmasını kapatır: arka planda kalan uygulamaların (Discord, Spotify, tarayıcı, OBS, oyun alt süreçleri) işlemcisi verimlilik moduna düşürülmez. Oyun alt-tab'dayken veya yayın / kayıt yazılımı arka plandayken takılma azalır.`n`n✅ Masaüstünde güvenli; dizüstünde pil süresi biraz kısalır.`n⚠️ Yeniden başlatma sonrası tam etkin olur.`n📚 Kaynak: Winaero, RyTuneX, Sparkle.";
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling";
                ValueName="PowerThrottlingOff"; Type="DWord"; Data=1; Undo="DELETE_VALUE"; RequiresReboot=$true;
                Risk="Low"; RestartExplorer=$false
            },
            @{
                Name="Menu Açılma Gecikmesini Sıfırla (MenuShowDelay=0)";
                Description="Sağ tık alt menüleri ve diğer Windows menüleri beklemeden açılır (varsayılan 400 ms gecikme kalkar). Yalnız arayüz hissini hızlandırır; anında uygulanır, yeniden başlatma gerekmez.";
                Key="HKCU:\Control Panel\Desktop"; ValueName="MenuShowDelay"; Type="String"; Data="0"; Undo="400";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                DetectScript='
                    $v = (Get-ItemProperty "HKCU:\Control Panel\Desktop" -Name MenuShowDelay -ErrorAction SilentlyContinue).MenuShowDelay
                    return ("$v" -eq "0")
                ';
                Command='
                    Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "MenuShowDelay" -Value "0" -Type String -Force
                    if (-not ("SpiMenu" -as [type])) {
                        Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class SpiMenu {
  [DllImport("user32.dll", SetLastError=true)]
  public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, IntPtr pvParam, uint fWinIni);
}
"@
                    }
                    [void][SpiMenu]::SystemParametersInfo(0x006B, 0, [IntPtr]::Zero, 3)
                    Write-Host "[Menu] MenuShowDelay=0 + SPI"
                ';
                UndoCommand='
                    Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "MenuShowDelay" -Value "400" -Type String -Force
                    if (-not ("SpiMenu" -as [type])) {
                        Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class SpiMenu {
  [DllImport("user32.dll", SetLastError=true)]
  public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, IntPtr pvParam, uint fWinIni);
}
"@
                    }
                    [void][SpiMenu]::SystemParametersInfo(0x006B, 400, [IntPtr]::Zero, 3)
                '
            },
            @{
                Name="NDU Servisini Kapat (Network Polling)";
                Description="Ağ Veri Kullanımı (NDU) izleme sürücüsünü kapatır. Bağlantı ve internet hızı etkilenmez; eski Killer / bazı ağ sürücülerindeki bellek sızıntısının bilinen çözümüdür. Kazanç küçüktür.`n`n⚠️ Görev Yöneticisi'nde uygulama başına ağ kullanımı ve Ayarlar > Veri kullanımı sayaçları çalışmaz.`n⚠️ Yeniden başlatma gerekir.";
                Command="Set-Service -Name Ndu -StartupType Disabled -ErrorAction SilentlyContinue";
                UndoCommand="Set-Service -Name Ndu -StartupType Automatic -ErrorAction SilentlyContinue";
                RequiresReboot=$true;
                # Detection: Get-Service ile StartType — Set-Service gecikmesinden bagimsiz, dil bagimsiz (servis name'e bakar)
                DetectScript="(Get-Service -Name Ndu -ErrorAction SilentlyContinue).StartType -eq 'Disabled'";
                Risk="Low"; RestartExplorer=$false
            },
            @{
                Name="Bellek Sayfa Birleştirmeyi Kapat (Page Combining)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows'un RAM'deki aynı içerikli sayfaları periyodik olarak tarayıp birleştirmesini (page combining) kapatır — arka planda zaman zaman çalışan bu taramanın CPU maliyeti kalkar. 16 GB+ RAM'de bellek kazancı zaten önemsizdir.`n`nResmi cmdlet: Disable-MMAgent -PageCombining. Geri alınabilir.`nℹ️ Etkisi küçüktür (anlık mikro yük); kayıt defteri 'DisablePageCombining' tweak'inin resmi ve güvenli karşılığıdır.";
                DetectScript="(Get-MMAgent -ErrorAction SilentlyContinue).PageCombining -eq `$false";
                Command="Disable-MMAgent -PageCombining -ErrorAction SilentlyContinue";
                UndoCommand="Enable-MMAgent -PageCombining -ErrorAction SilentlyContinue"
            },
            @{
                Name="Gereksiz Arka Plan Servislerini El ile Başlat (Güvenli Liste)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Açılışta otomatik başlayan ama günlük kullanımda gerekmeyen servisleri 'El ile' yapar (gerektiğinde Windows yine başlatır):`n• MapsBroker — İndirilen Haritalar Yöneticisi`n• TrkWks — Dağıtılmış Bağlantı İzleme İstemcisi`n• PcaSvc — Program Uyumluluk Yardımcısı`n• dmwappushservice — WAP Push (telemetri / MDM)`n`n✅ Bluetooth, Xbox, ses, ağ, yazıcı, arama, bildirim, Windows Update, Defender ve Edge güncelleme servisine dokunulmaz. Hiçbiri devre dışı bırakılmaz; önceki başlangıç türleri yedeklenir, geri alma onlara döner.";
                DetectScript='
                    foreach ($n in @("MapsBroker","TrkWks","PcaSvc","dmwappushservice")) {
                        $s = Get-Service -Name $n -ErrorAction SilentlyContinue
                        if ($s -and "$($s.StartType)" -eq "Automatic") { return $false }
                    }
                    return $true
                ';
                Command='
                    $bk = "HKLM:\SOFTWARE\MrClean\ServiceStartBackup"
                    if (-not (Test-Path $bk)) { New-Item -Path $bk -Force | Out-Null }
                    # Eski surum edgeupdate El Ile yaptiysa Edge yamasini geri ac
                    $eu = (Get-ItemProperty -Path $bk -Name "edgeupdate" -ErrorAction SilentlyContinue).edgeupdate
                    if ($eu) {
                        $regEu = "HKLM:\SYSTEM\CurrentControlSet\Services\edgeupdate"
                        if (Test-Path $regEu) {
                            $partsEu = "$eu".Split("|")
                            if ($partsEu[0]) { Set-ItemProperty -Path $regEu -Name "Start" -Value ([int]$partsEu[0]) -Type DWord -Force -ErrorAction SilentlyContinue }
                            if ($partsEu.Count -gt 1 -and $partsEu[1] -ne "") { Set-ItemProperty -Path $regEu -Name "DelayedAutostart" -Value ([int]$partsEu[1]) -Type DWord -Force -ErrorAction SilentlyContinue }
                        }
                        Remove-ItemProperty -Path $bk -Name "edgeupdate" -Force -ErrorAction SilentlyContinue
                    }
                    foreach ($n in @("MapsBroker","TrkWks","PcaSvc","dmwappushservice")) {
                        $reg = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"
                        if (-not (Test-Path $reg)) { continue }
                        $start = (Get-ItemProperty -Path $reg -Name "Start" -ErrorAction SilentlyContinue).Start
                        $delayed = (Get-ItemProperty -Path $reg -Name "DelayedAutostart" -ErrorAction SilentlyContinue).DelayedAutostart
                        if ($null -eq (Get-ItemProperty -Path $bk -Name $n -ErrorAction SilentlyContinue)) {
                            Set-ItemProperty -Path $bk -Name $n -Value "$start|$delayed" -Type String -Force
                        }
                        try { Set-Service -Name $n -StartupType Manual -ErrorAction Stop }
                        catch { Set-ItemProperty -Path $reg -Name "Start" -Value 3 -Type DWord -Force -ErrorAction SilentlyContinue }
                    }
                ';
                UndoCommand='
                    $bk = "HKLM:\SOFTWARE\MrClean\ServiceStartBackup"
                    $defaults = @{ MapsBroker="2|1"; TrkWks="2|"; PcaSvc="2|"; dmwappushservice="3|" }
                    $names = @($defaults.Keys)
                    if (Test-Path $bk) {
                        foreach ($p in @((Get-Item $bk -ErrorAction SilentlyContinue).Property)) {
                            if ($p -and $names -notcontains $p) { $names += $p }
                        }
                    }
                    foreach ($n in $names) {
                        $reg = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"
                        if (-not (Test-Path $reg)) { continue }
                        $val = $null
                        if (Test-Path $bk) { $val = (Get-ItemProperty -Path $bk -Name $n -ErrorAction SilentlyContinue).$n }
                        if (-not $val) { $val = $defaults[$n] }
                        if (-not $val) { continue }
                        $parts = "$val".Split("|")
                        if ($parts[0]) { Set-ItemProperty -Path $reg -Name "Start" -Value ([int]$parts[0]) -Type DWord -Force -ErrorAction SilentlyContinue }
                        if ($parts.Count -gt 1 -and $parts[1] -ne "") { Set-ItemProperty -Path $reg -Name "DelayedAutostart" -Value ([int]$parts[1]) -Type DWord -Force -ErrorAction SilentlyContinue }
                    }
                    Remove-Item -Path $bk -Recurse -Force -ErrorAction SilentlyContinue
                '
            },
            @{
                Name="Arka Plan Uygulamalarını Kapat (UWP)";
                Description="Mail, Calendar, Photos gibi UWP (Mağaza) uygulamalarının arka planda çalışmasını engeller. RAM ve network tasarrufu. Bildirim almıyorsan dert değil; e-posta canlı bildirim isteyenler dikkat.`n`n✅ Spotify (spotify.com masaüstü sürümü), Discord, Steam, medya tuşları ve PrtSc etkilenmez.`n⚠️ Telefon Bağlantısı ve WhatsApp (Store) arka planda çalışmaz. Spotify Microsoft Store sürümünde pencere küçültülünce sorun olursa geri alın.";
                Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications";
                ValueName="GlobalUserDisabled"; Type="DWord"; Data=1; Undo=0;
                Risk="Low"; RestartExplorer=$false
            },
            @{
                Name="AppInstaller Deneysel Özellikleri Kapat";
                Description="Microsoft Store AppInstaller'ın deneysel/telemetri özelliklerini kapatır. Az network ve CPU tasarrufu.";
                Key="HKLM:\Software\Policies\Microsoft\Windows\AppInstaller";
                ValueName="EnableExperimentalFeatures"; Type="DWord"; Data=0; Undo="DELETE_VALUE";
                Risk="Low"; RestartExplorer=$false
            },
            @{
                Name="DPS (Tanılama) Servisini Manuele Al";
                Description="Tanılayıcı İlkesi Hizmeti'ni (Diagnostic Policy Service, DPS) 'Otomatik' yerine 'El ile' başlatmaya alır; açılışta çalışmaz, gerektiğinde başlar. Küçük bir RAM / CPU tasarrufu sağlar.`n`n⚠️ Windows'un sorun giderici araçları ve ağ tanılaması bu servise ihtiyaç duyduğunda yavaş açılabilir.";
                Command="Set-Service -Name DPS -StartupType Manual -ErrorAction SilentlyContinue";
                UndoCommand="Set-Service -Name DPS -StartupType Automatic -ErrorAction SilentlyContinue";
                # Detection: Get-Service StartType — dil bagimsiz, registry erisimi gerekmez
                DetectScript="(Get-Service -Name DPS -ErrorAction SilentlyContinue).StartType -eq 'Manual'";
                Risk="Low"; RestartExplorer=$false
            },

            # --- v1.3.0: 24H2 / 25H2 / 26H2 SİSTEM VE OYUN EKLERİ ---
            @{
                Name="Pencereli Oyunlar İçin Optimizasyon (Flip Model)";
                Aliases=@("Pencereli Oyunlar icin Iyilestirmeleri Ac");
                Since="2.0.0"; MinBuild=22621;
                Risk="Low"; RestartExplorer=$false;
                Description="Ayarlar > Ekran > Grafik > 'Pencereli oyunlar için iyileştirmeler' seçeneğini açar. Eski DirectX 10 / 11 oyunları pencereli / kenarlıksız modda daha verimli sunum yöntemine (flip model) geçer: daha düşük giriş gecikmesi, değişken yenileme hızı (VRR) ve Auto HDR desteği.`n`nℹ️ Windows 11 24H2+ bu ayarı varsayılan olarak açık kabul eder. Diğer grafik ayarlarınız korunur.";
                DetectScript='
                    $v = [string](Get-ItemProperty -Path "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences" -Name "DirectXUserGlobalSettings" -ErrorAction SilentlyContinue).DirectXUserGlobalSettings
                    if ($v -match "SwapEffectUpgradeEnable=0") { return $false }
                    if ($v -match "SwapEffectUpgradeEnable=1") { return $true }
                    $build = 0
                    try { $build = [int](Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion" -Name CurrentBuildNumber -ErrorAction Stop).CurrentBuildNumber } catch {}
                    return ($build -ge 26100)
                ';
                Command='
                    $k = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
                    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
                    $cur = "$((Get-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -ErrorAction SilentlyContinue).DirectXUserGlobalSettings)"
                    $pairs = [ordered]@{}
                    foreach ($p in ($cur -split ";")) { if ($p -match "^\s*([^=]+)=(.*)$") { $pairs[$Matches[1].Trim()] = $Matches[2].Trim() } }
                    $pairs["SwapEffectUpgradeEnable"] = "1"
                    $new = (($pairs.Keys | ForEach-Object { "$_=$($pairs[$_])" }) -join ";") + ";"
                    Set-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -Value $new -Type String -Force
                ';
                UndoCommand='
                    $k = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
                    $cur = "$((Get-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -ErrorAction SilentlyContinue).DirectXUserGlobalSettings)"
                    $pairs = [ordered]@{}
                    foreach ($p in ($cur -split ";")) { if ($p -match "^\s*([^=]+)=(.*)$") { $pairs[$Matches[1].Trim()] = $Matches[2].Trim() } }
                    $pairs.Remove("SwapEffectUpgradeEnable")
                    if ($pairs.Count -gt 0) {
                        $new = (($pairs.Keys | ForEach-Object { "$_=$($pairs[$_])" }) -join ";") + ";"
                        Set-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -Value $new -Type String -Force
                    } else {
                        Remove-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -Force -ErrorAction SilentlyContinue
                    }
                '
            },
            @{
                Name="Hızlı Başlatmayı Kapat (Fast Startup)";
                Aliases=@("Hizli Baslangic Kapat");
                Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="'Kapat' dendiğinde Windows çekirdeği hazırda bekletmeye almak yerine gerçekten kapanır. Her açılışta temiz sürücü/çekirdek durumu: sürücü güncellemeleri, 'kapatıp açınca düzelmeyen' sorunlar ve çift işletim sistemi (dual boot) kurulumları için önerilir.`n`n⚠️ Açılış birkaç saniye uzayabilir (NVMe SSD'de genelde fark edilmez).";
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power"; ValueName="HiberbootEnabled"; Type="DWord"; Data=0; Undo=1;
                DetectScript='
                    $hb = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power" -Name "HiberbootEnabled" -ErrorAction SilentlyContinue).HiberbootEnabled
                    if ("$hb" -eq "0") { return $true }
                    return (-not (Test-Path "$env:SystemDrive\hiberfil.sys"))   # hazirda bekletme kapaliysa Hizli Baslangic da calismaz
                '
            },
            @{
                Name="Uygulama Başlangıç Gecikmesini Kaldır (Startup Delay)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows oturum açıldıktan sonra başlangıç uygulamalarını ~10 saniye bekletip sırayla başlatır. Bu tweak gecikmeyi kaldırır — tepsi uygulamaları (Discord, Steam, sürücü panelleri) hemen açılır.`n`n💡 Çok fazla başlangıç uygulaması olan yavaş HDD sistemlerde ilk saniyeler daha yoğun geçebilir; SSD'de fark hissedilmez.";
                Batch=@(
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize"; ValueName="StartupDelayInMSec"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize"; ValueName="WaitForIdleState"; Type="DWord"; Data=0; Undo="DELETE_VALUE" }
                )
            },
            @{
                Name="Edge Arka Planda Çalışmasın (Startup Boost + Arka Plan Modu)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Microsoft Edge'in oturum açılışında ön-yüklenmesini (Startup Boost) ve pencereler kapandıktan sonra arka planda çalışmaya devam etmesini kapatır. Edge kullanmıyorsanız boşa giden ~100-300 MB RAM ve açılış süresi kazanılır.`n`n⚠️ Edge 'Kuruluşunuz tarafından yönetiliyor' yazısı gösterebilir.";
                Batch=@(
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Edge"; ValueName="StartupBoostEnabled"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Edge"; ValueName="BackgroundModeEnabled"; Type="DWord"; Data=0; Undo="DELETE_VALUE" }
                )
            },
            @{
                Name="Ayrılmış Depolamayı Kapat (~7 GB Geri Kazan)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows'un güncellemeler için C: diskinde ayırdığı ~7 GB 'Ayrılmış Depolama' alanını serbest bırakır. Küçük SSD'lerde (128-256 GB) değerli.`n`n⚠️ Bir güncelleme kurulurken bu ayar değiştirilemez — hata alırsanız güncellemeyi tamamlayıp yeniden başlatın, sonra tekrar deneyin.`n💡 Disk dolduğunda büyük güncellemeler için yer açmanız gerekebilir.";
                DetectScript='
                    try { return ("$((Get-WindowsReservedStorageState -ErrorAction Stop).ReservedStorageState)" -eq "Disabled") } catch { return $false }
                ';
                Command='
                    try { Set-WindowsReservedStorageState -State Disabled -ErrorAction Stop | Out-Null; Write-Host "[ReservedStorage] Devre disi." }
                    catch { Write-Host "[ReservedStorage] Degistirilemedi (guncelleme suruyor olabilir): $($_.Exception.Message)" }
                ';
                UndoCommand='
                    try { Set-WindowsReservedStorageState -State Enabled -ErrorAction Stop | Out-Null } catch {}
                '
            },
            @{
                Name="BitLocker Otomatik Cihaz Şifrelemesini Engelle"; Since="2.0.0";
                Risk="Medium"; RestartExplorer=$false;
                Description="24H2 ile temiz kurulumlarda (Home dahil) Microsoft hesabıyla oturum açınca diskin SESSİZCE BitLocker ile şifrelenmesini engeller. Kurtarma anahtarını bilmeden BIOS/anakart değişikliğinde veri kilitlenme riskini ve NVMe'deki küçük performans kaybını önler.`n`n⚠️ Zaten şifrelenmiş bir diski ÇÖZMEZ — durumu görmek için: Yönetici CMD > manage-bde -status`n⚠️ Güvenlik ödünleşimi: cihaz çalınırsa disk okunabilir. Dizüstü kullanıcıları bilerek karar vermeli.";
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\BitLocker"; ValueName="PreventDeviceEncryption"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Bellek Bütünlüğü (HVCI / Çekirdek Yalıtımı) Kapat - Oyun FPS";
                Aliases=@("VBS / Bellek Butunlugu Kapat");
                Since="2.0.0";
                Risk="High"; RequiresReboot=$true; RestartExplorer=$false;
                Description="Windows Güvenliği > Cihaz güvenliği > Çekirdek yalıtımı > 'Bellek bütünlüğü' (HVCI) özelliğini kapatır — Windows Güvenliği'ndeki anahtarla aynı değeri yazar. Microsoft'un (arşivlenmiş) oyun performansı rehberindeki adımdır; kazanç sisteme bağlıdır, sanallaştırma tabanlı güvenlik açık kalırsa FPS farkı çıkmayabilir.`n`n⚠️ YÜKSEK RİSK — çekirdek seviyesindeki kötü amaçlı sürücülere karşı koruma azalır.`n⚠️ Riot Vanguard, FACEIT gibi bazı anti-cheat'ler bu özelliğin açık olmasını isteyebilir — oyun açılmazsa geri alın.`n🔒 Hyper-V sanal makinesi, WSL veya çalışan Docker varsa uygulanmaz.`nℹ️ Windows Update bu özelliği bilerek kapatılmış bilgisayarlarda açmaz; açarsa MrClean'in güncelleme sonrası denetimi bildirir.`n↩️ Geri alma önceki değerinize döner. Yeniden başlatma gerekir; kurumsal UEFI kilidi varsa değişmez.";
                # v1.3.0 (4. tur): Geri alma ORIJINAL degere doner (eski Undo=1 Bellek Butunlugunu, uyumsuz surucu
                # nedeniyle hic acilamayan sistemlerde bile ZORLA aciyordu — acilis/surucu engeli riski).
                DetectScript='
                    $v = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" -Name "Enabled" -ErrorAction SilentlyContinue).Enabled
                    return ("$v" -eq "0")
                ';
                Command='
                    if (-not (Confirm-VirtHeavyTweak "Bellek Butunlugu (HVCI)")) { return }
                    $k = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity"
                    Backup-TweakRegValue "HvciEnabled" $k "Enabled"
                    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
                    Set-ItemProperty -Path $k -Name "Enabled" -Value 0 -Type DWord -Force
                ';
                UndoCommand='
                    Restore-TweakRegValue "HvciEnabled" "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" "Enabled" 1 "DWord"
                ' 
            }
        )
        
        # --- 6. GÜÇ PLANLARI ---
        "Güç Planı" = @(
            @{
                Name="PCIe Bağlantı Güç Tasarrufunu Kapat (ASPM, Prizde)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Etkin güç planında 'PCI Express > Bağlantı Durumu Güç Yönetimi'ni prizdeyken KAPALI yapar: ekran kartı ve NVMe bağlantısı boşta düşük güç durumuna (L0s/L1) geçmez, ilk yükte uyanma gecikmesi olmaz. Bazı anakartlarda NVMe/GPU kaynaklı mikro takılma ve WHEA uyarılarını giderir.`n`nℹ️ Dürüst not: Kazanç sisteme bağlıdır; ASPM'yi BIOS yönetiyorsa etkisizdir. Yüksek Performans planında zaten kapalıdır.`n⚠️ Boşta birkaç watt fazla tüketim. Dizüstünde sorulur; pil (DC) ayarına dokunulmaz.`n✅ Önceki değer yedeklenir, geri alma ona döner. Güç planını DEĞİŞTİRMEZ (X3D için Dengeli plan korunur).`n📚 Kaynak: Microsoft PCIe ASPM belgesi; kubsonxtm/Windows-Tweaks, Winrift.";
                DetectScript='
                    $i = Get-PowerSettingIndex "501a4d13-42af-4429-9fd1-a8218c268e20" "ee12f906-d277-404b-b6da-e5fa1a576df5"
                    return ($i -and $i.AC -eq 0)
                ';
                Command='
                    if (-not (Confirm-LaptopPowerTweak "PCIe ASPM Kapat")) { return }
                    $sub = "501a4d13-42af-4429-9fd1-a8218c268e20"; $set = "ee12f906-d277-404b-b6da-e5fa1a576df5"
                    Backup-PowerSettingIndex "PcieAspm" $sub $set
                    & powercfg -setacvalueindex SCHEME_CURRENT $sub $set 0 2>$null | Out-Null
                    & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null
                ';
                UndoCommand='
                    Restore-PowerSettingIndex "PcieAspm" "501a4d13-42af-4429-9fd1-a8218c268e20" "ee12f906-d277-404b-b6da-e5fa1a576df5" 1 2
                '
            },
            # v1.3.0 (13. tur): OLCUME DAYALI — oyun yuku benzetimi (FurMark tam ekran + 10 isci CPU/RAM yuku + giris gecikmesi),
            # 3 tur x 5 kosul: min %100 ile CS2 benzeri 1% low 635 -> 724 (+%14), BF6 benzeri 197 -> 219 (+%11), giris gecikmesi p99 248 -> 126 us;
            # bostan sonra ilk is paketi ~200 -> ~115 us. Yuk altinda olumsuz etki yok (Ryzen 7 9850X3D, Win11 26200).
            @{
                Name="İşlemci Minimum Durumu %100 — Yalnız Oyun Açıkken (Prizde)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Listedeki bir oyun açıldığında etkin güç planında 'En düşük işlemci durumu'nu prizdeyken %100 yapar; son oyun kapanınca önceki değere döner. Oyunda işlemci kareler arasındaki kısa boşluklarda saat hızını düşürmez, yeni iş geldiğinde yeniden hızlanmayı beklemez. Masaüstünde ve boştayken Windows'un normal güç yönetimi çalışır — gereksiz ısınma ve tüketim olmaz.`n`n📊 MrClean ölçümü (oyun yükü benzetimi, 3 tur, Ryzen 7 9850X3D): CS2 benzeri yükte 1% low +%14, BF6 benzeri yükte +%11, giriş gecikmesi (p99) 248 → 126 µs.`n`nℹ️ Oyunlar: bilinen rekabetçi oyunlar + Steam / Epic / EA / Riot / Battle.net / Ubisoft / GOG kütüphanelerinde bulunanlar. Yeni oyun kurduysanız tweak'i kapatıp yeniden uygulayın. Oyun en geç ~2 sn içinde algılanır. Yönetici yetkisi istemeyen küçük bir zamanlanmış görev ('MrClean-OyunIslemci') kurulur.`nℹ️ Yüksek / Nihai Performans planı bu değeri fabrika ayarında %100 getirir, ama yonga seti sürücüsü, Process Lasso gibi araçlar ya da başka optimizasyon programları düşürebilir (bu bilgisayarda ölçüm yapılırken etkin planda %0'dı). Tweak hangi plan seçili olursa olsun oyunda %100 yapar; plan zaten %100 ise hiçbir şey değiştirmez. Planı değiştirmez — çift CCD X3D (7950X3D / 9950X3D) için AMD'nin önerdiği Dengeli plan korunur.`n⚠️ Pilde (dizüstü) değiştirilmez.`n💾 Geri alma görevi kaldırır; oyun açıkken geri alınırsa önceki değer hemen yazılır.";
                # v1.3.0 (§102): kalici %100 yerine oyun algilayan gorev (Install-MrCleanGameCpuAgent); tespit = gorev kurulu
                DetectScript='
                    return (Test-MrCleanGameCpuAgent)
                ';
                Command='
                    if (-not (Confirm-LaptopPowerTweak "Islemci Minimum Durumu %100 (oyunda)")) { return }
                    Convert-MrCleanLegacyProcMin
                    Install-MrCleanGameCpuAgent
                ';
                UndoCommand='
                    Remove-MrCleanGameCpuAgent
                '
            },
            # v1.3.0 (15. tur): OLCUME DAYALI — bostan uyanma maliyetini sifirlar. 6 tur (Ryzen 7 9850X3D): giris gecikmesi p99 59-84 -> 40-45 us,
            # bostan sonra ilk is paketi 115 -> 100 us, CS2 benzeri 1% low ~810 -> ~877. Bedel: paket gucu bosta 30 -> 86 W, sicaklik 46 -> 60 C.
            # "Yalniz C1" (IDLESTATEMAX=1) ve EPP=0 olculdu: kazanc yok. Bu yuzden profillere eklenmedi; uzman ayari.
            @{
                Name="İşlemci Boşta Durumlarını Kapat (Rekabetçi, Uzman, Prizde)"; Since="2.0.0";
                Risk="Medium"; RestartExplorer=$false;
                Description="İşlemci çekirdeklerinin boştayken uyku durumlarına (C-state) girmesini prizdeyken kapatır; çekirdekler her an hazır bekler. Böylece boştan uyanma gecikmesi tamamen kalkar.`n`n📊 MrClean ölçümü (Ryzen 7 9850X3D, 6 tur, Benchmark oyun yükü):`n• Giriş gecikmesi en kötü %1: 59-84 µs → 40-45 µs (ve turdan tura oynamıyor)`n• Boştan sonra hızlanma: 115 µs → 100 µs (kayıp sıfır)`n• CS2 benzeri yük 1% low: ~810 → ~877 (+%8)`n`n⚠️ BEDEL: İşlemci boşta da tam çalışır — ölçülen paket gücü 30 W → 86 W, sıcaklık 46 °C → 60 °C (oyunda 64 °C). Fan sesi ve elektrik tüketimi artar. Dosya/süreç işlemleri ~%20 yavaşlar (SMT kardeş iş parçacığı boşta da döner).`n⚠️ Görev Yöneticisi CPU'yu genelde %100 gösterir — çekirdekler uyumadığı için; bu bir kilitlenme değildir.`nℹ️ 'Yalnız C1' ve 'EPP=0' gibi hafif seçenekler de ölçüldü: kazanç yok, bu yüzden eklenmedi.`n💡 Rekabetçi oyuncular için. İstemezseniz Geri Al ile Windows varsayılanına (boşta kalma açık) döner. Pil (DC) ayarına dokunulmaz.`n🔒 Masaüstü ve dizüstünde Apply öncesi onay istenir. Önerilen profillerde YOKTUR.`n📚 Microsoft güç ayarı: Processor idle disable (IDLEDISABLE).";
                DetectScript='
                    $i = Get-PowerSettingIndex "54533251-82be-4824-96c1-47b60b740d00" "5d76a2ca-e8c0-402f-a133-2158492d58ad"
                    return ($i -and $i.AC -eq 1)
                ';
                Command='
                    if (-not (Confirm-IdleDisableTweak)) { return }
                    $sub = "54533251-82be-4824-96c1-47b60b740d00"; $set = "5d76a2ca-e8c0-402f-a133-2158492d58ad"
                    Backup-PowerSettingIndex "IdleDisable" $sub $set
                    & powercfg -setacvalueindex SCHEME_CURRENT $sub $set 1 2>$null | Out-Null
                    & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null
                ';
                UndoCommand='
                    Restore-PowerSettingIndex "IdleDisable" "54533251-82be-4824-96c1-47b60b740d00" "5d76a2ca-e8c0-402f-a133-2158492d58ad" 0 0
                '
            },
            @{
                Name="Wi-Fi Güç Tasarrufunu Pilde de Kapat (Dizüstü)"; Requires=@("WiFi","Laptop"); Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Dizüstü bilgisayar PİLDEYKEN de kablosuz ağ kartını 'Maksimum Performans' modunda tutar. Pilde Wi-Fi güç tasarrufu, oyunda ve Discord'da periyodik ping sıçramalarının klasik sebebidir. Prizdeyken Windows zaten maksimum performans kullanır.`n`n⚠️ Pil süresi biraz kısalır. Masaüstünde etkisizdir.`n✅ Önceki değer yedeklenir, geri alma ona döner.`n📚 Kaynak: Microsoft güç ayarı (Wireless Adapter Settings > Power Saving Mode).";
                DetectScript='
                    $i = Get-PowerSettingIndex "19cbb8fa-5279-450e-9fac-8a3d5fedd0c1" "12bbebe6-58d6-4636-95bb-3217ef867c1a"
                    return ($i -and $i.DC -eq 0)
                ';
                Command='
                    $sub = "19cbb8fa-5279-450e-9fac-8a3d5fedd0c1"; $set = "12bbebe6-58d6-4636-95bb-3217ef867c1a"
                    Backup-PowerSettingIndex "WifiPowerDC" $sub $set
                    & powercfg -setdcvalueindex SCHEME_CURRENT $sub $set 0 2>$null | Out-Null
                    & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null
                ';
                UndoCommand='
                    Restore-PowerSettingIndex "WifiPowerDC" "19cbb8fa-5279-450e-9fac-8a3d5fedd0c1" "12bbebe6-58d6-4636-95bb-3217ef867c1a" 0 2
                '
            },
            @{
                Name="Modern Bekleme Sırasında Ağ Bağlantısını Kapat (Dizüstü)"; Requires=@("Laptop"); Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Modern Bekleme (S0) destekli dizüstülerde, kapak kapalı / uykudayken Wi-Fi'nin açık kalıp e-posta, bildirim ve güncelleme indirmesini engeller — çantada ısınma ve gece pil bitmesi biter.`n`n⚠️ Uykudayken Discord/e-posta bildirimleri gelmez (cihaz uyanınca gelir). Klasik S3 uykulu masaüstülerde etkisizdir.`n📚 Kaynak: Win11Debloat (Disable_Modern_Standby_Networking; geri alma orada yanlışlıkla 1 yazıyor, burada ilke silinir).";
                Batch=@(
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Power\PowerSettings\f15576e8-98b7-4186-b944-eafa664402d9"; ValueName="ACSettingIndex"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Power\PowerSettings\f15576e8-98b7-4186-b944-eafa664402d9"; ValueName="DCSettingIndex"; Type="DWord"; Data=0; Undo="DELETE_VALUE" }
                )
            },
            @{ 
                Name="Nihai Performans Güç Planını Aktif Et";
				Group="PowerPlan";
                Description="Windows 'Nihai Performans' (Ultimate Performance) güç planını oluşturup etkinleştirir: işlemci boşta frekans düşürmez, çekirdek park etme kapalı, disk / PCIe güç tasarrufu kapalı; PCIe bağlantı güç yönetimi (ASPM) prizdeyken ayrıca kapatılır. Tek CCD'li işlemcilerde (5800X3D, 9800X3D, 9850X3D, Intel) en düşük gecikme için.`n`n⚠️ Çift CCD'li X3D (7900X3D / 7950X3D / 9900X3D / 9950X3D): AMD 'Dengeli' planı önerir — bu planda V-Cache CCD park mekanizması çalışmaz, FPS düşebilir. Bu işlemcilerde uygulamadan önce uyarı gösterilir.`n⚠️ Boşta güç tüketimi ve sıcaklık artar; dizüstünde önerilmez.`nℹ️ İşlemci minimum durumu bu planda fabrika ayarında %100'dür (sürücü / araçlar düşürebilir). Boşta işlemcinin serin kalması, oyunda ise %100 olması için ayrı tweak: 'İşlemci Minimum Durumu %100 — Yalnız Oyun Açıkken'.";
                # v1.3.0 (4. tur): Plan SABIT bir GUID ile kopyalanir — Fransizca/Almanca Windows ta plan adi farkli oldugu icin
                # eski ada gore arama her Uygula da YENI bir kopya olusturuyordu. Tespit de GUID ile yapilir.
                DetectScript='
                    # v1.3.0 (§93): yalniz etkin plana bakilir. ASPM (12. tur) uygulamada yine kapatilir ama tespite katilmaz —
                    # ayri "PCIe Baglanti Guc Tasarrufunu Kapat" tweakinin geri alinmasi Nihai Performansi pasif gosteriyordu.
                    $act = "$(& powercfg /getactivescheme 2>$null)"
                    return ($act -match "e9a42b02-d5df-448d-aa00-03f14749eb61|3b7c1a5e-6d2f-4c8a-9e41-7f0d2b6c5a19" -or $act -match "(Nihai|Ultimate) Performan")
                ';
                Command='if (-not (Confirm-DualCcdX3DPowerTweak "Nihai Performans Guc Plani")) { return }; if (-not (Confirm-LaptopPowerTweak "Nihai Performans Guc Plani")) { return }; $fixed = "3b7c1a5e-6d2f-4c8a-9e41-7f0d2b6c5a19"; $list = "$(& powercfg /list 2>$null)"; if ($list -match "e9a42b02-d5df-448d-aa00-03f14749eb61") { & powercfg -setactive e9a42b02-d5df-448d-aa00-03f14749eb61 2>$null | Out-Null } elseif ($list -match $fixed) { & powercfg -setactive $fixed 2>$null | Out-Null } else { $p = @(& powercfg /list | Select-String "(Nihai|Ultimate) Performan") | Select-Object -First 1; if ($p -and "$p" -match "([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})") { & powercfg -setactive $Matches[1] 2>$null | Out-Null } else { & powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 $fixed 2>$null | Out-Null; & powercfg -setactive $fixed 2>$null | Out-Null } }; & powercfg -setacvalueindex SCHEME_CURRENT SUB_PCIEXPRESS ASPM 0 2>$null | Out-Null; & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null';
                UndoCommand='powercfg -setactive 381b4222-f694-41f0-9685-ff5bb260df2e 2>$null; if ($LASTEXITCODE -ne 0) { powercfg -duplicatescheme 381b4222-f694-41f0-9685-ff5bb260df2e 381b4222-f694-41f0-9685-ff5bb260df2e | Out-Null; powercfg -setactive 381b4222-f694-41f0-9685-ff5bb260df2e }'; 
                RestartExplorer=$false 
            },
            @{ Name="Yüksek Performans Güç Planını Aktif Et"; Group="PowerPlan";
               Description="Windows 'Yüksek Performans' güç planını etkinleştirir: fabrika ayarında işlemci prizdeyken minimum %100'de çalışır, disk / PCIe güç tasarrufu kapalıdır ve bilgisayar uykuya geçmez.`n`n⚠️ Çift CCD'li X3D işlemcilerde (7950X3D / 9950X3D vb.) AMD 'Dengeli' planı önerir — uygulamadan önce uyarı gösterilir.";
               Command='if (-not (Confirm-DualCcdX3DPowerTweak "Yuksek Performans Guc Plani")) { return }; powercfg -setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'; UndoCommand='powercfg -setactive 381b4222-f694-41f0-9685-ff5bb260df2e 2>$null; if ($LASTEXITCODE -ne 0) { powercfg -duplicatescheme 381b4222-f694-41f0-9685-ff5bb260df2e 381b4222-f694-41f0-9685-ff5bb260df2e | Out-Null; powercfg -setactive 381b4222-f694-41f0-9685-ff5bb260df2e }'; RestartExplorer=$false }
        )
        
        # --- 7. UYGULAMA KALDIRMA ---
        "Uygulama Kaldırma" = @(
            @{
                Name="OneDrive'ı Sistemden Tamamen Kaldır"; Risk="Medium";
                Description="OneDrive'ı bilgisayardan kaldırır: önce OneDrive'ın kendi kaldırma komutu kullanılır, bulunamazsa Windows'taki kurulum dosyası denenir. Başlangıç kaydı, OneDrive güncelleme / raporlama görevleri ve Gezgin'deki boş OneDrive girişi de temizlenir.`n`n✅ OneDrive klasörünüzdeki dosyalar silinmez.`n⚠️ Geri alma yoktur — yeniden kullanmak için OneDrive'ı Microsoft'tan indirip kurun.";
                DetectScript='
                    # v1.3.0: Program Files kurulumu ve Uninstall kaydi da kontrol edilir (eski sezgisel sadece AppData ya bakiyordu)
                    if (Get-Process -Name "OneDrive" -ErrorAction SilentlyContinue) { return $false }
                    foreach ($p in @("$env:LOCALAPPDATA\Microsoft\OneDrive\OneDrive.exe", "$env:ProgramFiles\Microsoft OneDrive\OneDrive.exe", "${env:ProgramFiles(x86)}\Microsoft OneDrive\OneDrive.exe")) { if (Test-Path $p) { return $false } }
                    $u = Get-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OneDriveSetup.exe","HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\OneDriveSetup.exe" -ErrorAction SilentlyContinue
                    return (-not $u)
                ';
                Command='taskkill /f /im OneDrive.exe 2>$null; $u = @(Get-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OneDriveSetup.exe","HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\OneDriveSetup.exe","HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\OneDriveSetup.exe" -ErrorAction SilentlyContinue | Where-Object { $_.UninstallString }) | Select-Object -First 1; if ($u) { $us = "$($u.UninstallString)"; if ($us -match "^\s*`"([^`"]+)`"\s*(.*)$") { $exe = $Matches[1]; $args0 = $Matches[2] } else { $exe = ($us -split "\s+/")[0]; $args0 = $us.Substring($exe.Length) }; if ($args0 -notmatch "/silent") { $args0 = "$args0 /silent" }; Start-Process -FilePath $exe -ArgumentList $args0 -Wait -ErrorAction SilentlyContinue } elseif (Test-Path "$env:SystemRoot\SysWOW64\OneDriveSetup.exe") { Start-Process "$env:SystemRoot\SysWOW64\OneDriveSetup.exe" -ArgumentList "/uninstall" -Wait } elseif (Test-Path "$env:SystemRoot\System32\OneDriveSetup.exe") { Start-Process "$env:SystemRoot\System32\OneDriveSetup.exe" -ArgumentList "/uninstall" -Wait } else { Write-Host "OneDrive Setup bulunamadi" }; Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run" -Name "OneDriveSetup" -Force -ErrorAction SilentlyContinue; Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskName -like "OneDrive Standalone Update Task*" -or $_.TaskName -like "OneDrive Reporting Task*" } | Unregister-ScheduledTask -Confirm:$false -ErrorAction SilentlyContinue; $nav = "HKCU:\Software\Classes\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}"; if (-not (Test-Path $nav)) { New-Item -Path $nav -Force | Out-Null }; Set-ItemProperty -Path $nav -Name "System.IsPinnedToNameSpaceTree" -Value 0 -Type DWord -Force';
                UndoCommand="";
                RestartExplorer=$false
            },

            # === FR33THY 13 Bloatware.ps1 birebir — 5 ek uygulama kaldirma ===
            @{
                Name="Microsoft GameInput Servisini El Ile Al";
                Aliases=@("Microsoft GameInput Kaldır");
                Description="Microsoft GameInput servislerini (varsa) durdurup 'El ile' başlatmaya alır; paket kaldırılmaz. Gerektiğinde (Xbox uygulaması, Game Pass oyunu, kumanda) Windows servisi yine başlatır.`n`n⚠️ Uygulamadan önce sorulur. Kumandayla oynayan ya da Game Pass kullanan biriyseniz 'Hayır' deyin.`n↩️ Geri alma önceki başlangıç türlerine döner.";
                Risk="Low"; RestartExplorer=$false;
                DetectScript='
                    foreach ($n in @("GameInputSvc","GameInput","GameInputRedistService")) {
                        $s = Get-Service -Name $n -ErrorAction SilentlyContinue
                        if ($s -and "$($s.StartType)" -eq "Automatic") { return $false }
                    }
                    return $true
                ';
                Command='
                    $r = [System.Windows.MessageBox]::Show("GameInput paketi kaldirilmaz; servis El Ile alinir.`n`nXbox / Game Pass / kumanda kullaniyorsaniz Hayir deyin.`n`nUygulansin mi?", "GameInput", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
                    if ($r -ne "Yes") { Write-Host "[GameInput] Kullanici iptal."; return }
                    $bk = "HKLM:\SOFTWARE\MrClean\GameInputStartBackup"
                    if (-not (Test-Path $bk)) { New-Item -Path $bk -Force | Out-Null }
                    $any = $false
                    foreach ($n in @("GameInputSvc","GameInput","GameInputRedistService")) {
                        $reg = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"
                        if (-not (Test-Path $reg)) { continue }
                        $any = $true
                        $start = (Get-ItemProperty -Path $reg -Name "Start" -ErrorAction SilentlyContinue).Start
                        if ($null -eq (Get-ItemProperty -Path $bk -Name $n -ErrorAction SilentlyContinue)) {
                            Set-ItemProperty -Path $bk -Name $n -Value "$start" -Type String -Force
                        }
                        try { Stop-Service -Name $n -Force -ErrorAction SilentlyContinue } catch {}
                        try { Set-Service -Name $n -StartupType Manual -ErrorAction Stop }
                        catch { Set-ItemProperty -Path $reg -Name "Start" -Value 3 -Type DWord -Force -ErrorAction SilentlyContinue }
                    }
                    if (-not $any) { Write-Host "[GameInput] Servis yok — paket durur, kaldirilmaz." }
                    else { Write-Host "[GameInput] Servis El Ile. Paket yerinde." }
                ';
                UndoCommand='
                    $bk = "HKLM:\SOFTWARE\MrClean\GameInputStartBackup"
                    foreach ($n in @("GameInputSvc","GameInput","GameInputRedistService")) {
                        $reg = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"
                        if (-not (Test-Path $reg)) { continue }
                        $val = $null
                        if (Test-Path $bk) { $val = (Get-ItemProperty -Path $bk -Name $n -ErrorAction SilentlyContinue).$n }
                        $start = 2
                        if ("$val" -match "^\d+$") { $start = [int]$val }
                        Set-ItemProperty -Path $reg -Name "Start" -Value $start -Type DWord -Force -ErrorAction SilentlyContinue
                        if ($start -eq 2) { try { Set-Service -Name $n -StartupType Automatic -ErrorAction SilentlyContinue; Start-Service -Name $n -ErrorAction SilentlyContinue } catch {} }
                    }
                    Remove-Item -Path $bk -Recurse -Force -ErrorAction SilentlyContinue
                    Write-Host "[GameInput] Servis geri alindi."
                '
            },



            @{
                Name="Microsoft Update Health Tools Kaldır";
                Description="Microsoft Update Health Tools paketini (güncelleme sağlık telemetrisi ve uhssvc servisi) kaldırır.`n`nℹ️ Paket sistemde zaten yoksa tweak, MrClean ile kaldırılmadıkça aktif görünmez.`n⚠️ Geri alma paketi yeniden kurmaz; Windows Update gerekirse kendisi kurar.";
                Risk="Low"; RestartExplorer=$false;
                DetectScript='
                    # v1.3.0 (§89): kaldırma listesi .NET ile, yalnız DisplayName okunur (~200 -> ~17 ms)
                    $f = $null
                    try {
                        $uk = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall")
                        foreach ($n in $uk.GetSubKeyNames()) { $sk = $uk.OpenSubKey($n); if ($sk) { if ("$($sk.GetValue("DisplayName"))" -like "*Microsoft Update Health Tools*") { $f = $n }; $sk.Close() } }
                        $uk.Close()
                    } catch { $f = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*" -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like "*Microsoft Update Health Tools*" } }
                    $svc = Get-Service -Name uhssvc -ErrorAction SilentlyContinue
                    $mk = (Get-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "RemovedUpdateHealth" -ErrorAction SilentlyContinue).RemovedUpdateHealth
                    $applied = @((Get-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AppliedTweaks" -ErrorAction SilentlyContinue).AppliedTweaks)
                    return (($null -eq $f) -and ($null -eq $svc) -and ("$mk" -eq "1" -or $applied -contains "Microsoft Update Health Tools Kaldır"))
                ';
                Command='
                    $f = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*" -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like "*Microsoft Update Health Tools*" }
                    if ($f) {
                        $guid = $f.PSChildName
                        Write-Host "[UpdateHealth] Kaldiriliyor: $guid"
                        Start-Process "msiexec.exe" -ArgumentList "/x $guid /qn /norestart" -Wait -NoNewWindow
                    }
                    cmd /c "reg delete `"HKLM\SYSTEM\ControlSet001\Services\uhssvc`" /f >nul 2>&1"
                    Unregister-ScheduledTask -TaskName PLUGScheduler -Confirm:$false -ErrorAction SilentlyContinue | Out-Null
                    $mk = "HKCU:\Software\MrClean\AppliedMarkers"
                    if (-not (Test-Path $mk)) { New-Item -Path $mk -Force -ErrorAction SilentlyContinue | Out-Null }
                    Set-ItemProperty -Path $mk -Name "RemovedUpdateHealth" -Value 1 -Type DWord -Force
                    Write-Host "[UpdateHealth] uhssvc + PLUGScheduler temizlendi."
                ';
                UndoCommand='
                    Remove-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "RemovedUpdateHealth" -Force -ErrorAction SilentlyContinue
                    Write-Host "[UpdateHealth] Marker silindi (paket geri kurulmaz)."
                '
            },

            @{
                Name="Şifresiz Giriş Devre Dışı (Klasik Şifre Açık)";
                Description="Windows 11'in 'Gelişmiş güvenlik için bu cihazda yalnız Windows Hello oturum açmasına izin ver' (şifresiz oturum) seçeneğini kapatır. Oturum açma ekranında klasik şifre seçeneği yeniden görünür; Microsoft hesabı ve yerel hesap için geçerlidir.";
                Risk="Low"; RestartExplorer=$false;
                Key="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\PasswordLess\Device";
                ValueName="DevicePasswordLessBuildVersion"; Type="DWord"; Data=0; Undo=2
            }
        )
        
        # --- 8. AĞ VE DNS (v1.2.5: netsh tabanli — PowerShell Set-DnsClientServerAddress Win11 de bazen
        # TCP/IPv4 Properties dialog'unda "otomatik" gosteriyordu, netsh source=static|dhcp daha guvenilir) ---
        "Ağ ve DNS Ayarları" = @(
            @{
                Name="DNS: Google (Hız ve Kararlılık)"; Description="Fiziksel ağ kartlarında DNS'i Google'a ayarlar (8.8.8.8 / 8.8.4.4, IPv6 2001:4860:4860::8888). Hızlı ve yaygın, dünyanın her yerinde düşük gecikmeli bir DNS.`n`n✅ VPN / sanal kartların DNS'ine dokunulmaz. Önceki elle girilmiş DNS yedeklenir; geri alma ona (yoksa otomatik DNS'e) döner. Gecikmeyi Araçlar > DNS Benchmark ile karşılaştırabilirsiniz."; Requires=@("NoDnsTool");
                Group="DNS";
                Command='
                    # v1.3.0 (4. tur): sadece FIZIKSEL adaptorler (VPN/Hyper-V/Tailscale DNS i bozulmaz), kopuk Wi-Fi dahil;
                    # onceki (elle girilmis) DNS yedeklenir — geri alma onu geri yukler. Adres: address=8.8.8.8
                    Set-MrCleanDnsPreset "8.8.8.8" "8.8.4.4" "2001:4860:4860::8888" "2001:4860:4860::8844"
                ';
                UndoCommand='
                    # v1.3.0 (4. tur): onceki DNS yedekten geri yuklenir (yoksa otomatik/DHCP). source=dhcp
                    Restore-MrCleanDnsStatic
                ';
                RestartExplorer=$false
            },
            @{
                Name="DNS: Cloudflare (Gizlilik ve Hız)"; Description="Fiziksel ağ kartlarında DNS'i Cloudflare'e ayarlar (1.1.1.1 / 1.0.0.1, IPv6 2606:4700:4700::1111). Genellikle en hızlı genel DNS'tir ve sorgu kaydı tutmama taahhüdü verir.`n`n✅ VPN / sanal kartların DNS'ine dokunulmaz. Önceki elle girilmiş DNS yedeklenir; geri alma ona (yoksa otomatik DNS'e) döner. Gecikmeyi Araçlar > DNS Benchmark ile karşılaştırabilirsiniz."; Requires=@("NoDnsTool");
                Group="DNS";
                Command='
                    # v1.3.0 (4. tur): sadece FIZIKSEL adaptorler (VPN/Hyper-V/Tailscale DNS i bozulmaz), kopuk Wi-Fi dahil;
                    # onceki (elle girilmis) DNS yedeklenir — geri alma onu geri yukler. Adres: address=1.1.1.1
                    Set-MrCleanDnsPreset "1.1.1.1" "1.0.0.1" "2606:4700:4700::1111" "2606:4700:4700::1001"
                ';
                UndoCommand='
                    # v1.3.0 (4. tur): onceki DNS yedekten geri yuklenir (yoksa otomatik/DHCP). source=dhcp
                    Restore-MrCleanDnsStatic
                ';
                RestartExplorer=$false
            },
            @{
                Name="DNS: Quad9 (Güvenlik + Gizlilik)"; Requires=@("NoDnsTool");
                Group="DNS"; Since="2.0.0";
                Description="Quad9 DNS (9.9.9.9 / 149.112.112.112, IPv6 2620:fe::fe): bilinen zararlı/oltalama alan adlarını DNS seviyesinde engeller, kayıt tutmaz (İsviçre merkezli, kâr amacı gütmeyen). Cloudflare/Google'a göre gecikme konuma göre değişir — Araçlar > DNS Benchmark ile karşılaştırın.`n📚 Kaynak: RyTuneX ve Sparkle DNS ön ayarları.";
                Command='
                    # v1.3.0 (4. tur): sadece FIZIKSEL adaptorler (VPN/Hyper-V/Tailscale DNS i bozulmaz), kopuk Wi-Fi dahil;
                    # onceki (elle girilmis) DNS yedeklenir — geri alma onu geri yukler. Adres: address=9.9.9.9
                    Set-MrCleanDnsPreset "9.9.9.9" "149.112.112.112" "2620:fe::fe" "2620:fe::9"
                ';
                UndoCommand='
                    # v1.3.0 (4. tur): onceki DNS yedekten geri yuklenir (yoksa otomatik/DHCP). source=dhcp
                    Restore-MrCleanDnsStatic
                ';
                RestartExplorer=$false
            },
            @{
                Name="DNS: AdGuard (Reklam ve İzleyici Engelleme)"; Requires=@("NoDnsTool");
                Group="DNS"; Since="2.0.0";
                Description="AdGuard DNS (94.140.14.14 / 94.140.15.15): reklam, izleyici ve bilinen zararlı alan adlarını DNS seviyesinde engeller — tüm uygulamalarda ve tarayıcılarda geçerli.`n`n⚠️ Bazı alışveriş/kampanya bağlantıları, reklamlı ücretsiz oyun ödülleri veya mağaza sayfaları açılmayabilir — sorun olursa başka DNS seçin. Gecikmeyi Araçlar > DNS Benchmark ile karşılaştırın.`n✅ Sadece fiziksel ağ kartları; önceki DNS yedeklenir.`n📚 Kaynak: optimizer, optimizerNXT DNS ön ayarları.";
                Command='
                    # Adres: address=94.140.14.14
                    Set-MrCleanDnsPreset "94.140.14.14" "94.140.15.15" "2a10:50c0::ad1:ff" "2a10:50c0::ad2:ff"
                ';
                UndoCommand='
                    # source=dhcp
                    Restore-MrCleanDnsStatic
                ';
                RestartExplorer=$false
            },
            @{
                Name="DNS: Cloudflare Güvenlik (Zararlı Site Engelleme)"; Requires=@("NoDnsTool");
                Group="DNS"; Since="2.0.0";
                Description="Cloudflare'in zararlı yazılım engelleyen DNS'i (1.1.1.2 / 1.0.0.2): Cloudflare hızında, bilinen zararlı ve oltalama alan adlarını engeller. Reklamları engellemez (site kırma riski düşük).`n✅ Sadece fiziksel ağ kartları; önceki DNS yedeklenir.`n📚 Kaynak: ağ araştırması; Cloudflare for Families belgesi.";
                Command='
                    # Adres: address=1.1.1.2
                    Set-MrCleanDnsPreset "1.1.1.2" "1.0.0.2" "2606:4700:4700::1112" "2606:4700:4700::1002"
                ';
                UndoCommand='
                    # source=dhcp
                    Restore-MrCleanDnsStatic
                ';
                RestartExplorer=$false
            },
            @{
                Name="Şifreli DNS (DoH) Aç — Cloudflare / Google / Quad9"; Requires=@("NoDnsTool");
                Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Kullandığınız DNS sunucusu Windows'un yerleşik şifreli DNS listesindeyse (Cloudflare, Google, Quad9) DNS sorgularını HTTPS ile şifreler (DNS over HTTPS). ISS'nin DNS sorgularını görmesini, değiştirmesini ve yönlendirmesini engeller.`n`n💡 Önce 'DNS: Cloudflare / Google / Quad9' tweak'lerinden birini uygulayın; başka DNS kullanıyorsanız bu tweak hiçbir şey yapmaz (log'a yazar).`nℹ️ Oyun içi ping'i değiştirmez (DNS sadece bağlantı başında kullanılır). Sadece fiziksel ağ kartlarına uygulanır; VPN DNS'i etkilenmez.`n🛡️ Güvenlik ağı: şifreli bağlantı kurulamazsa (otel/kafe giriş sayfası, 443 engeli) normal DNS'e düşülür; uygulamadan hemen sonra test edilir, ad çözümleme başarısızsa ayar otomatik geri alınır.`n📚 Kaynak: Microsoft 'DNS over HTTPS client' belgesi; Sophia Script, helgeklein/Win-DNS-DoH-PoSh.";
                DetectScript='
                    # v1.3.0 (§89): yalnız takılı fiziksel kartlar (Get-MrCleanNicFast; kart GUID = NetworkInterface.Id)
                    foreach ($a in (Get-MrCleanNicFast)) {
                        $b = "HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$($a.Ni.Id)\DohInterfaceSettings"
                        foreach ($fam in @("Doh","Doh6")) { if (@(Get-ChildItem -Path "$b\$fam" -ErrorAction SilentlyContinue).Count -gt 0) { return $true } }
                    }
                    return $false
                ';
                Command='
                    if (Test-MrCleanDnsBlocked "Sifreli DNS (DoH)") { return }
                    $known = @{}
                    foreach ($d in @(Get-DnsClientDohServerAddress -ErrorAction SilentlyContinue)) { $known["$($d.ServerAddress)"] = $true }
                    $used = New-Object System.Collections.Generic.List[string]
                    $lm = [Microsoft.Win32.Registry]::LocalMachine
                    foreach ($a in (Get-MrCleanPhysicalAdapters)) {
                        $srv = @(Get-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ErrorAction SilentlyContinue | ForEach-Object { $_.ServerAddresses })
                        foreach ($ip in $srv) {
                            if (-not $known.ContainsKey("$ip")) { continue }
                            $fam = if ("$ip" -match ":") { "Doh6" } else { "Doh" }
                            $sub = "SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$($a.InterfaceGuid)\DohInterfaceSettings\$fam\$ip"
                            $k = $lm.CreateSubKey($sub)
                            if ($k) { $k.SetValue("DohFlags", [long]1, [Microsoft.Win32.RegistryValueKind]::QWord); $k.Close(); if (-not $used.Contains("$ip")) { $used.Add("$ip") } }
                        }
                    }
                    if ($used.Count -eq 0) { WpfLog "[DoH] Mevcut DNS sunuculariniz sifreli DNS listesinde degil — once DNS: Cloudflare / Google / Quad9 tweaklerinden birini uygulayin."; return }
                    foreach ($ip in $used) { try { Set-DnsClientDohServerAddress -ServerAddress $ip -AllowFallbackToUdp $true -AutoUpgrade $true -ErrorAction SilentlyContinue | Out-Null } catch {} }
                    Clear-DnsClientCache -ErrorAction SilentlyContinue
                    Start-Sleep -Milliseconds 800
                    $ok = $false
                    foreach ($h in @("www.microsoft.com","www.cloudflare.com")) { try { Resolve-DnsName -Name $h -DnsOnly -QuickTimeout -ErrorAction Stop | Out-Null; $ok = $true; break } catch {} }
                    if (-not $ok) {
                        foreach ($a in (Get-MrCleanPhysicalAdapters)) {
                            foreach ($fam in @("Doh","Doh6")) { try { $lm.DeleteSubKeyTree("SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$($a.InterfaceGuid)\DohInterfaceSettings\$fam", $false) } catch {} }
                        }
                        Clear-DnsClientCache -ErrorAction SilentlyContinue
                        WpfLog "[DoH] Sifreli DNS ile ad cozumlenemedi — guvenlik icin GERI ALINDI (ag 443 portunu engelliyor olabilir)."
                        return
                    }
                    WpfLog "[DoH] Sifreli DNS acildi: $($used -join ", ")"
                ';
                UndoCommand='
                    $lm = [Microsoft.Win32.Registry]::LocalMachine
                    foreach ($a in (Get-MrCleanPhysicalAdapters)) {
                        foreach ($fam in @("Doh","Doh6")) { try { $lm.DeleteSubKeyTree("SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$($a.InterfaceGuid)\DohInterfaceSettings\$fam", $false) } catch {} }
                    }
                    Clear-DnsClientCache -ErrorAction SilentlyContinue
                '
            },
            @{
                Name="DNS: Otomatik (Varsayılan / İSS)"; Description="Fiziksel ağ kartlarında DNS'i otomatik (modem / İSS'den DHCP ile) yapar — Windows'un varsayılanı. Elle girilmiş DNS ve MrClean'in DNS yedeği temizlenir. VPN / sanal kartlara dokunulmaz."; Requires=@("NoDnsTool");
                Group="DNS";
                Command='
                    # v1.3.0 (4. tur): tum FIZIKSEL adaptorlerde DNS otomatik (DHCP / ISS). source=dhcp
                    if (Test-MrCleanDnsBlocked "DNS: Otomatik") { return }
                    foreach ($a in (Get-MrCleanPhysicalAdapters)) {
                        & netsh interface ipv4 set dnsservers name="$($a.Name)" source=dhcp | Out-Null
                        & netsh interface ipv6 set dnsservers name="$($a.Name)" source=dhcp | Out-Null
                    }
                    Remove-Item -Path "HKLM:\SOFTWARE\MrClean\DnsBackup" -Recurse -Force -ErrorAction SilentlyContinue
                    ipconfig /flushdns > $null
                ';
                UndoCommand="";
                RestartExplorer=$false
            }
        )

        # --- 9. GELİŞMİŞ SİSTEM (BATCH) ---
        "Gelişmiş Sistem (Batch)" = @(
            @{
                Name="Cortana ve Cloud Aramayı Tamamen Kapat"; Description="Cortana'yı ve aramanın bulut içeriğini (Microsoft hesabı / iş hesabı içerikleri) Group Policy ile kapatır; kilit ekranında Cortana çalışmaz. Yerel dosya, uygulama ve ayar araması aynen çalışır.";
                RestartExplorer=$false;
                Batch=@(
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search"; ValueName="AllowCloudSearch"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search"; ValueName="AllowCortana"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search"; ValueName="AllowCortanaAboveLock"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Search"; ValueName="CortanaEnabled"; Type="DWord"; Data=0; Undo=1 },
                    @{ Key="HKCU:\Software\Microsoft\Windows\CurrentVersion\Search"; ValueName="CortanaConsent"; Type="DWord"; Data=0; Undo=1 }
                )
            },

            # === COPILOT TAMAMEN KAPAT (FR33THY 9 Copilot.ps1 birebir) ===
            @{
                Name="Copilot Tamamen Kapat (Uninstall + Policy)";
                Aliases=@("Copilot Butonunu Gizle");
                Description="Windows Copilot'u kapatır: Copilot uygulaması kaldırılır, Group Policy ile yeniden kurulup açılması engellenir ve görev çubuğu düğmesi gizlenir. Çalışan Copilot ve Pencere Öğeleri süreçleri durdurulur; Edge, OneDrive, Game Bar ve arama etkilenmez.`n`n↩️ Geri alma ilkeleri ve düğme ayarını kaldırır; Copilot uygulamasını Microsoft Store'dan yeniden kurabilirsiniz.";
                Risk="Medium"; RestartExplorer=$false;
                DetectScript='
                    $hku = (Get-ItemProperty -Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot" -Name "TurnOffWindowsCopilot" -ErrorAction SilentlyContinue).TurnOffWindowsCopilot
                    $hlm = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot" -Name "TurnOffWindowsCopilot" -ErrorAction SilentlyContinue).TurnOffWindowsCopilot
                    $rem = (Get-ItemProperty -Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsAI" -Name "RemoveMicrosoftCopilotApp" -ErrorAction SilentlyContinue).RemoveMicrosoftCopilotApp
                    # 12. tur (birlestirme): komutun yazdigi UC ilke de olmali ("biri varsa yesil" yaniltiyordu; bazi SKU larda tek ilke yetmiyor)
                    if ("$hku" -ne "1" -or "$hlm" -ne "1") { return $false }
                    if ("$rem" -eq "1") { return $true }
                    # 14. tur: eski surumle uygulanmis (25H2 ilkesi yok) ama Copilot paketi kaldirilmis -> uygulanmis say
                    # v1.3.0 (§89): Appx modülü yerine kayıt defteri AppxAllUserStore (ortak + kullanıcı SID alt anahtarları)
                    try {
                        $st = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore")
                        $hit = $false
                        foreach ($sub in @($st.GetSubKeyNames() | Where-Object { $_ -eq "Applications" -or $_ -like "S-1-5-*" })) {
                            $k = $st.OpenSubKey($sub); if ($k) { if (@($k.GetSubKeyNames() | Where-Object { $_ -like "*Copilot*" }).Count -gt 0) { $hit = $true }; $k.Close() }
                        }
                        $st.Close()
                        return (-not $hit)
                    } catch { return (-not (Get-AppxPackage -AllUsers -Name "*Copilot*" -ErrorAction SilentlyContinue)) }
                ';
                Command='
                    Write-Host "[Copilot] Copilot/Widget process kapatiliyor (Edge/OneDrive/GameBar dokunulmaz)..."
                    $stop = "Copilot", "WidgetService", "Widgets"
                    foreach ($p in $stop) { Stop-Process -Name $p -Force -ErrorAction SilentlyContinue }

                    Write-Host "[Copilot] AppX paketi kaldiriliyor..."
                    Get-AppXPackage -AllUsers | Where-Object { $_.Name -like "*Copilot*" } | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue
                    Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like "*Copilot*" } | ForEach-Object {
                        Remove-AppxProvisionedPackage -Online -PackageName $_.PackageName -ErrorAction SilentlyContinue | Out-Null
                    }

                    # 25H2 (Nisan 2026+) resmi policy — RemoveMicrosoftCopilotApp (HKCU\...\WindowsAI)
                    if (-not (Test-Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsAI")) {
                        New-Item -Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsAI" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsAI" -Name "RemoveMicrosoftCopilotApp" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ShowCopilotButton" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue

                    Write-Host "[Copilot] Policy etkinlestiriliyor (HKCU + HKLM)..."
                    if (-not (Test-Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot")) {
                        New-Item -Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot" -Name "TurnOffWindowsCopilot" -Value 1 -Type DWord -Force
                    if (-not (Test-Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot")) {
                        New-Item -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot" -Name "TurnOffWindowsCopilot" -Value 1 -Type DWord -Force
                    Write-Host "[Copilot] Tamamen kapatildi."
                ';
                UndoCommand='
                    Write-Host "[Copilot] Geri aliniyor..."
                    Get-AppXPackage -AllUsers | Where-Object { $_.Name -like "*Copilot*" } | ForEach-Object {
                        Add-AppxPackage -DisableDevelopmentMode -Register -ErrorAction SilentlyContinue "$($_.InstallLocation)\AppXManifest.xml"
                    }
                    Remove-Item -Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot" -Recurse -Force -ErrorAction SilentlyContinue
                    Remove-Item -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot" -Recurse -Force -ErrorAction SilentlyContinue
                    # WindowsAI anahtarinin tamami silinmez — Recall / Click to Do policy leri de orada yasar.
                    Remove-ItemProperty -Path "HKCU:\Software\Policies\Microsoft\Windows\WindowsAI" -Name "RemoveMicrosoftCopilotApp" -Force -ErrorAction SilentlyContinue
                    Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ShowCopilotButton" -Force -ErrorAction SilentlyContinue
                    Write-Host "[Copilot] Policy silindi. Uygulama kaldirildiysa Microsoft Store dan yeniden kurun."
                '
            },
            @{ 
                Name="Windows Update'i Kısıtla (Otomatik Yüklemeyi Kapat)";
                RestartExplorer=$false; Group="WUPolicy";
                Description="Windows Update'i 'indirmeden önce bildir' moduna alır (Group Policy: Otomatik Güncelleştirmeleri Yapılandır = 2). Güncellemeler onayınız olmadan indirilmez / kurulmaz; Ayarlar > Windows Update'ten istediğiniz zaman denetleyip kurabilirsiniz. Cihaz takılınca sürücüler de otomatik aranmaz.`n`n💡 Sürüm yükseltmesini durdurmak için 'Özellik Güncellemesini Mevcut Sürümde Sabitle' tweak'ini kullanın. 'Windows Update'i TAMAMEN Kilitle' ile aynı gruptadır (biri seçilince diğeri kapanır).`n📚 Kaynak: optimizer / optimizerNXT, Microsoft Group Policy belgesi.";
                DetectScript='
                    $au = Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" -ErrorAction SilentlyContinue
                    $wu = Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" -ErrorAction SilentlyContinue
                    return ("$($au.NoAutoUpdate)" -eq "0" -and "$($au.AUOptions)" -eq "2" -and "$($wu.SetDisableUXWUAccess)" -ne "1")
                ';
                Batch=@(
                    # v1.3.0 (4. tur): eski surumun kilitleri temizlenir (Apply), geri almada da silinir
                    @{
                        Command='
                            Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" -Name "SetDisableUXWUAccess" -Force -ErrorAction SilentlyContinue
                            Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" -Name "DisableOSUpgrade" -Force -ErrorAction SilentlyContinue
                        ';
                        UndoCommand='
                            Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" -Name "SetDisableUXWUAccess" -Force -ErrorAction SilentlyContinue
                            Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" -Name "DisableOSUpgrade" -Force -ErrorAction SilentlyContinue
                        '
                    },
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU"; ValueName="NoAutoUpdate"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
                    @{ Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU"; ValueName="AUOptions"; Type="DWord"; Data=2; Undo="DELETE_VALUE" }, 
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching"; ValueName="SearchOrderConfig"; Type="DWord"; Data=0; Undo=1 }
                )
            },

            # --- v1.3.0 (11. tur, birlestirme): diger gelistiricinin "Kisitla" surumu ayri ve acik uyarili tweak olarak ---
            @{
                Name="Windows Update'i TAMAMEN Kilitle (Güncelleme Ekranı Dahil)"; Since="2.0.0";
                RestartExplorer=$false; Group="WUPolicy"; Risk="High";
                Description="⛔ YÜKSEK RİSK — Windows Update'i tamamen kilitler:`n  • Otomatik güncelleme KAPALI (NoAutoUpdate=1)`n  • Ayarlar > Windows Update ekranı ERİŞİLEMEZ olur (SetDisableUXWUAccess=1) — elle 'Güncelleştirmeleri denetle' de yapılamaz`n  • Sürüm yükseltmesi (ör. 25H2 → 26H2) engellenir (DisableOSUpgrade=1)`n  • Windows Update üzerinden sürücü indirme kapalı`n`n⚠️ GÜVENLİK GÜNCELLEMELERİ GELMEZ. Sadece kısa süreli (ör. turnuva / yayın haftası) veya güncellemenin bozduğu bir sürücüyü korumak için kullanın; iş bitince 'Geri Al' ya da 'Windows Update'i Kısıtla' seçin (ikisi aynı gruptadır, biri seçilince diğeri kapanır).`n⚠️ Microsoft Defender virüs tanımlarının güncel kaldığını kontrol edin (Windows Güvenliği > Virüs ve tehdit koruması).`n🔒 Apply öncesi onay zorunlu. Önerilen profillerde YOKTUR.";
                DetectScript='
                    $au = Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" -ErrorAction SilentlyContinue
                    $wu = Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" -ErrorAction SilentlyContinue
                    return ("$($au.NoAutoUpdate)" -eq "1" -and "$($wu.SetDisableUXWUAccess)" -eq "1")
                ';
                Command='
                    if (-not (Confirm-WuLockTweak)) { return }
                    $wu = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
                    $au = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU"
                    $ds = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching"
                    foreach ($p in @($wu, $au, $ds)) { if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null } }
                    Set-ItemProperty -Path $wu -Name "DisableOSUpgrade" -Value 1 -Type DWord -Force
                    Set-ItemProperty -Path $wu -Name "SetDisableUXWUAccess" -Value 1 -Type DWord -Force
                    Set-ItemProperty -Path $au -Name "NoAutoUpdate" -Value 1 -Type DWord -Force
                    Set-ItemProperty -Path $au -Name "AUOptions" -Value 2 -Type DWord -Force
                    Set-ItemProperty -Path $ds -Name "SearchOrderConfig" -Value 0 -Type DWord -Force
                ';
                UndoCommand='
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" -Name "DisableOSUpgrade" -Force -ErrorAction SilentlyContinue
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" -Name "SetDisableUXWUAccess" -Force -ErrorAction SilentlyContinue
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" -Name "NoAutoUpdate" -Force -ErrorAction SilentlyContinue
                    Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" -Name "AUOptions" -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching" -Name "SearchOrderConfig" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                '
            },

            # --- v1.3.0: WINDOWS UPDATE (24H2 / 25H2 / 26H2 — ortak servis dali) ---
            @{
                Name="Windows Update Arka Plan İndirme Hızını Sınırla (%30)";
                SubCategory="Windows Update"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows Update ve Microsoft Store güncellemelerinin ARKA PLANDA indirirken kullanabileceği bant genişliğini, ölçülen hattınızın %30'u ile sınırlar (Teslim İyileştirme ilkesi). Oyun oynarken arkada büyük güncelleme inerse ping sıçraması ve tampon şişmesi (bufferbloat) azalır.`n`n✅ ÖN PLANDA başlattığınız indirmeler (Ayarlar'dan 'Şimdi indir', Xbox uygulamasından oyun indirme) sınırlanmaz. Steam, Discord, Spotify etkilenmez.`n⚠️ Arka plan güncellemeleri biraz daha geç tamamlanır.`n📚 Kaynak: Microsoft Teslim İyileştirme belgesi (DOPercentageMaxBackgroundBandwidth); ağ araştırması — incelenen araçların hiçbiri bu sınırı koymuyordu.";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization"; ValueName="DOPercentageMaxBackgroundBandwidth"; Type="DWord"; Data=30; Undo="DELETE_VALUE"
            },
            @{
                Name="Yeniden Başlatma Gerektiğinde Bildirim Göster";
                SubCategory="Windows Update"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Bir güncelleme yeniden başlatma beklediğinde Windows bildirim gösterir (varsayılanda sessizce bekler, sonra kendi zamanında yeniden başlatabilir). 'Oturum Açıkken Otomatik Yeniden Başlatmayı Engelle' ile birlikte, ne zaman yeniden başlatılacağını siz seçersiniz.`n📚 Kaynak: Sophia Script.";
                Key="HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings"; ValueName="RestartNotificationsAllowed2"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Güncelleme Duraklatma Süresini Uzat (Ayarlardan 1 Yıla Kadar)";
                SubCategory="Windows Update"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Ayarlar > Windows Update > 'Güncellemeleri duraklat' menüsündeki en uzun seçeneği 5 haftadan 52 haftaya çıkarır. Kendisi hiçbir şeyi duraklatmaz — siz seçmedikçe güncellemeler normal gelir.`n`n⚠️ Uzun bir süre seçerseniz o süre boyunca güvenlik güncellemeleri de gelmez.`nℹ️ Resmi bir ilke değildir; Windows Insider ayarları seçenekleri 7 güne döndürebilir.";
                Key="HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings"; ValueName="FlightSettingsMaxPauseDays"; Type="DWord"; Data=364; Undo="DELETE_VALUE"
            },
            @{
                Name="Özellik Güncellemesini Mevcut Sürümde Sabitle (Sürüm Kilidi)";
                SubCategory="Windows Update"; Since="2.0.0"; MinBuild=22000;
                Risk="Medium"; RestartExplorer=$false;
                Description="Windows'u şu anki sürümde (ör. 25H2) tutar: büyük özellik güncellemesi (sürüm yükseltmesi) gelmez, aylık güvenlik güncellemeleri gelmeye devam eder (resmi Group Policy: TargetReleaseVersion).`n`nℹ️ Pro / Enterprise / Education'da çalışır; Home'da etkisiz kalabilir. Sürümün destek süresi bitince Microsoft yine yükseltme yapabilir.`n↩️ Geri alma kilidi kaldırır.";
                DetectScript='
                    $k = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
                    $t = (Get-ItemProperty -Path $k -Name "TargetReleaseVersion" -ErrorAction SilentlyContinue).TargetReleaseVersion
                    $i = (Get-ItemProperty -Path $k -Name "TargetReleaseVersionInfo" -ErrorAction SilentlyContinue).TargetReleaseVersionInfo
                    return ("$t" -eq "1" -and -not [string]::IsNullOrWhiteSpace("$i"))
                ';
                Command='
                    $cv = Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion" -ErrorAction SilentlyContinue
                    $dv = "$($cv.DisplayVersion)"
                    if (-not $dv) { Write-Host "[SurumKilidi] DisplayVersion okunamadi — atlandi."; return }
                    $product = if ([int]$cv.CurrentBuildNumber -ge 22000) { "Windows 11" } else { "Windows 10" }
                    $k = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
                    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
                    Set-ItemProperty -Path $k -Name "TargetReleaseVersion"     -Value 1        -Type DWord  -Force
                    Set-ItemProperty -Path $k -Name "ProductVersion"           -Value $product -Type String -Force
                    Set-ItemProperty -Path $k -Name "TargetReleaseVersionInfo" -Value $dv      -Type String -Force
                    Write-Host "[SurumKilidi] $product $dv surumunde sabitlendi."
                ';
                UndoCommand='
                    $k = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
                    foreach ($n in @("TargetReleaseVersion","ProductVersion","TargetReleaseVersionInfo")) {
                        Remove-ItemProperty -Path $k -Name $n -Force -ErrorAction SilentlyContinue
                    }
                '
            },
            @{
                Name="Güncellemeleri Hemen Al (Erken Erişim) Seçeneğini Kapat";
                SubCategory="Windows Update"; Since="2.0.0"; MinBuild=22631;
                Risk="Low"; RestartExplorer=$false;
                Description="Ayarlar > Windows Update > 'En son güncellemeleri kullanıma sunulur sunulmaz alın' seçeneğini kapatır. Açıkken yeni özellikler ve isteğe bağlı önizleme güncellemeleri kademeli dağıtımdan önce gelir — kararlılık isteyenler için kapalı olmalı. Değer hiç yazılmamışsa Windows varsayılanı zaten kapalıdır (aktif görünür).";
                DetectScript='
                    $v = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings" -Name "IsContinuousInnovationOptedIn" -ErrorAction SilentlyContinue).IsContinuousInnovationOptedIn
                    return ($null -eq $v -or "$v" -eq "0")
                ';
                Key="HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings"; ValueName="IsContinuousInnovationOptedIn"; Type="DWord"; Data=0; Undo=1
            },
            @{
                Name="Oturum Açıkken Güncelleme Sonrası Otomatik Yeniden Başlatmayı Engelle";
                SubCategory="Windows Update"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Bir kullanıcı oturum açmışken Windows Update'in güncelleme sonrası bilgisayarı kendiliğinden yeniden başlatmasını engelleyen Group Policy ayarını açar. Güncellemeler iner ve kurulur; yeniden başlatmayı siz yaparsınız.`n`nℹ️ Microsoft bu eski ilkenin her durumda uygulanmayabileceğini belirtir — kilitli oturumda Windows 11 yine yeniden başlatabilir. 'Yeniden Başlatma Gerektiğinde Bildirim Göster' ile birlikte kullanın.";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU"; ValueName="NoAutoRebootWithLoggedOnUsers"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Teslim İyileştirmeyi Kapat (P2P Güncelleme Paylaşımı)";
                SubCategory="Windows Update"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows Update'in güncelleme parçalarını yerel ağdaki veya internetteki DİĞER bilgisayarlarla paylaşmasını (upload) kapatır. Güncellemeler doğrudan Microsoft sunucularından (HTTP) iner. Kotalı/yavaş upload bağlantılarında ve oyun sırasında arka plan upload'ını önler.`n`nPolicy: DeliveryOptimization\DODownloadMode = 0";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization"; ValueName="DODownloadMode"; Type="DWord"; Data=0; Undo="DELETE_VALUE"
            },
            @{
                Name="Windows Update Sürücü Güncellemelerini Hariç Tut";
                SubCategory="Windows Update"; Since="2.0.0";
                Risk="Medium"; RestartExplorer=$false;
                Description="Windows Update'in ekran kartı, ses, ağ ve yonga seti sürücülerini otomatik kurmasını engeller (Group Policy: ExcludeWUDriversInQualityUpdate). NVIDIA / AMD sürücünüz Windows'un eski sürücüsüyle ezilmez.`n`n⚠️ Sürücü güncellemelerini artık üreticinin sitesinden ya da uygulamasından kendiniz almanız gerekir; Windows Update'ten sürücü yaması gelmez.";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"; ValueName="ExcludeWUDriversInQualityUpdate"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },

            # --- v1.3.0: GÜVENLİK SIKILAŞTIRMA (tweaqas "network security" paketinden — oyun/LAN/Spotify Connect bozmayanlar) ---
            # Bilerek EKLENMEYENLER: ICMP (ping) engelleme, tum gelen baglantilari engelleme, mDNS engelleme,
            # Ag Bulma kapatma → Spotify Connect / Chromecast / LAN oyun / Steam Remote Play / yazici kesfini bozar.
            @{
                Name="Anakart Yazılım Enjeksiyonunu Engelle (WPBT — Armoury Crate vb.)";
                SubCategory="Güvenlik Sıkılaştırma"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; RequiresReboot=$true;
                Description="Windows Platform Binary Table (WPBT): anakart üreticisinin BIOS/UEFI içine gömdüğü bir programı Windows her açılışta SORMADAN çalıştırır. Format sonrası kendiliğinden kurulan ASUS Armoury Crate, MSI Center, Gigabyte Control Center, Lenovo Vantage gibi yazılımların kaynağı budur. Bu tweak WPBT yürütmesini kapatır.`n`n✅ Sürücüler, BIOS ayarları ve zaten kurulu yazılımlar etkilenmez — sadece firmware'in Windows'a zorla yazılım yerleştirmesi durur. İstediğiniz OEM yazılımını normal yoldan kurabilirsiniz.`n⚠️ Kurumsal hırsızlık önleme yazılımları (Absolute/Computrace) bu mekanizmayı kullanır — şirket dizüstünde uygulamayın.`n⚠️ Bir sonraki açılıştan itibaren geçerlidir.`n📚 Kaynak: Chris Titus winutil, Sparkle, RyTuneX, Jamesits/dropWPBT.";
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager"; ValueName="DisableWpbtExecution"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Aygıt Üretici Uygulamalarının Otomatik Kurulumunu Engelle";
                SubCategory="Güvenlik Sıkılaştırma"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Yeni bir aygıt (monitör, kulaklık, fare, yazıcı) takıldığında Windows'un internetten aygıt bilgisi indirip üreticinin 'yardımcı' uygulamasını (ör. LG monitör uygulaması, OEM ses panelleri) SORMADAN kurmasını engeller. Sürücüler Windows Update'ten normal şekilde gelmeye devam eder.`n`n💡 'WPBT' tweak'iyle birlikte kullanın: biri anakart yazılımlarını, diğeri aygıt yazılımlarını durdurur.`n📚 Kaynak: Win11Debloat (Disable_Device_Auto_App_Download), optimizerNXT; Microsoft 'Device Metadata' ilkesi.";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\Device Metadata"; ValueName="PreventDeviceMetadataFromNetwork"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Kayıt Defteri Otomatik Yedeğini Aç (RegBack)";
                SubCategory="Güvenlik Sıkılaştırma"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows'un kayıt defterini düzenli olarak C:\Windows\System32\config\RegBack klasörüne yedeklemesini yeniden açar (Microsoft KB4509719; Windows 10 1803'ten beri varsayılan olarak kapalı).`n`nℹ️ Yedek görevi (RegIdleBackup) bilgisayar boştayken çalışır; yedek ~100-200 MB yer kaplar. Windows açılmazsa Sistem Geri Yükleme noktası yine daha güvenilir yoldur.";
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Configuration Manager"; ValueName="EnablePeriodicBackup"; Type="DWord"; Data=1; Undo="DELETE_VALUE"
            },
            @{
                Name="Bu Bilgisayara Kablosuz Yansıtmayı (Miracast Alıcısı) Kapat";
                SubCategory="Güvenlik Sıkılaştırma"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Bilgisayarın başka cihazlardan kablosuz görüntü ALMASINI (Bu bilgisayara yansıtma / Miracast alıcısı) kapatır; açık bir ağ hizmeti kapanır.`n`n✅ Bilgisayardan TV'ye/monitöre yansıtma (Win+K), Chromecast ve Spotify Connect ETKİLENMEZ.`n📚 Kaynak: optimizer, optimizerNXT; Microsoft ADMX (AllowProjectionToPC).";
                Key="HKLM:\SOFTWARE\Policies\Microsoft\Windows\Connect"; ValueName="AllowProjectionToPC"; Type="DWord"; Data=0; Undo="DELETE_VALUE"
            },
            @{
                Name="Uzak Kayıt Defteri ve Mağaza Demo Servislerini Devre Dışı Bırak";
                SubCategory="Güvenlik Sıkılaştırma"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Ağ üzerinden kayıt defterine erişim sağlayan Uzak Kayıt Defteri (RemoteRegistry) ve mağaza vitrin modu (RetailDemo) servislerini Devre Dışı yapar. Win11'de RemoteRegistry zaten varsayılan olarak kapalıdır — tweak çoğu sistemde 'Aktif' görünür.`n`n✅ Orijinal başlangıç türleri yedeklenir, geri alma onlara döner.`n📚 Kaynak: optimizer, optimizerNXT, GTweak.";
                DetectScript='
                    foreach ($n in @("RemoteRegistry","RetailDemo")) {
                        $s = Get-Service -Name $n -ErrorAction SilentlyContinue
                        if ($s -and "$($s.StartType)" -ne "Disabled") { return $false }
                    }
                    return $true
                ';
                Command='
                    foreach ($n in @("RemoteRegistry","RetailDemo")) {
                        $reg = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"
                        if (-not (Test-Path $reg)) { continue }
                        Backup-TweakRegValue "SvcStart_$n" $reg "Start"
                        try { Stop-Service -Name $n -Force -ErrorAction SilentlyContinue } catch {}
                        Set-ItemProperty -Path $reg -Name "Start" -Value 4 -Type DWord -Force -ErrorAction SilentlyContinue
                    }
                ';
                UndoCommand='
                    foreach ($n in @("RemoteRegistry","RetailDemo")) {
                        $reg = "HKLM:\SYSTEM\CurrentControlSet\Services\$n"
                        if (Test-Path $reg) { Restore-TweakRegValue "SvcStart_$n" $reg "Start" 3 "DWord" }
                    }
                '
            },
            @{
                Name="Uzak Yardım (Remote Assistance) Kapat";
                SubCategory="Güvenlik Sıkılaştırma"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows Uzak Yardım davetlerini kapatır (Sistem Özellikleri > Uzak > 'Bu bilgisayara Uzak Yardım bağlantılarına izin ver'). Sosyal mühendislik ('Microsoft destek' dolandırıcılığı) için kullanılan bir saldırı yüzeyi kapanır.`n`n✅ AnyDesk / TeamViewer / Parsec / Steam Remote Play / Discord ekran paylaşımı ETKİLENMEZ.";
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\Remote Assistance"; ValueName="fAllowToGetHelp"; Type="DWord"; Data=0; Undo=1
            },
            @{
                Name="SMBv1 Protokolünü Kaldır (WannaCry Koruması)";
                SubCategory="Güvenlik Sıkılaştırma"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; RequiresReboot=$true;
                Description="1990'lardan kalma, WannaCry/NotPetya fidye yazılımlarının yayıldığı SMB 1.0 protokolünü Windows özelliklerinden kaldırır. Win11 temiz kurulumda zaten kurulu değildir — tweak çoğu sistemde 'Aktif' görünür, yapılacak iş yoktur. Yükseltilmiş eski sistemlerde açık kalmış olabilir.`n`n⚠️ Sadece çok eski NAS/modem paylaşımları (SMB1 isteyen) etkilenir. Yeniden başlatma gerekir.";
                DetectScript='
                    # SMB1 istemci surucusu (mrxsmb10) servisi yoksa ozellik kaldirilmistir (hizli, DISM cagrisiz kontrol)
                    return (-not (Test-Path "HKLM:\SYSTEM\CurrentControlSet\Services\mrxsmb10"))
                ';
                Command='
                    try { Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -NoRestart -ErrorAction Stop | Out-Null; Write-Host "[SMB1] Kaldirildi (yeniden baslatma sonrasi tamamlanir)." }
                    catch { Write-Host "[SMB1] Kaldirilamadi: $($_.Exception.Message)" }
                ';
                UndoCommand='
                    try { Enable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -All -NoRestart -ErrorAction Stop | Out-Null } catch {}
                '
            },
            @{
                Name="Windows Script Host'u Kapat (VBS/JS Zararlı Koruması)";
                SubCategory="Güvenlik Sıkılaştırma"; Since="2.0.0";
                Risk="Medium"; RestartExplorer=$false;
                Description="Windows Script Host'u (wscript / cscript) kapatır: e-posta eki ya da indirilen .vbs / .js / .wsf dosyalarına çift tıklanınca çalışmaz — bu tür zararlıların yaygın yolu kapanır. 32 bit ve 64 bit için birlikte uygulanır.`n`n⚠️ Eski kurulum programları, bazı uzak yönetim (RMM) araçları ve .vbs betikleri çalışmaz — sorun olursa geri alın. PowerShell ve .bat dosyaları etkilenmez.";
                Batch=@(
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows Script Host\Settings"; ValueName="Enabled"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
                    @{ Key="HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows Script Host\Settings"; ValueName="Enabled"; Type="DWord"; Data=0; Undo="DELETE_VALUE" }
                )
            }
        )
		# --- 10. LOW LATENCY / ESPOR PAKETİ ---
        "🎮 Low Latency (Espor)" = @(
            # --- A: FARE VE KLAVYE (INPUT) ---
            @{ 
                Name="Fare İvmesini (Acceleration) Tamamen Kapat"; 
                SubCategory="Giriş ve İşlemci";
				Description="Windows'un 'İşaretçi hassasiyetini artır' (fare ivmesi) özelliğini kapatır: farenin fiziksel hareketi ile imleç hareketi 1'e 1 olur (kas hafızası için önemli). Oyunların çoğu ham girdi kullanır; fark masaüstünde, menülerde ve ham girdi kullanmayan oyunlarda hissedilir.`n`nAnında uygulanır; oturum açma ekranı için de yazılır.`nℹ️ İnternette dolaşan 'MarkC' ivme eğrileri ivme kapalıyken hiçbir şey yapmadığı için eklenmedi.";
                DetectScript='
                    $m = Get-ItemProperty -Path "HKCU:\Control Panel\Mouse" -ErrorAction SilentlyContinue
                    return ("$($m.MouseSpeed)" -eq "0" -and "$($m.MouseThreshold1)" -eq "0" -and "$($m.MouseThreshold2)" -eq "0")
                ';
                Batch=@(
                    # MouseSpeed=0 ivmeyi kapatır. Threshold'lar 0 olmalı.
                    @{ Key="HKCU:\Control Panel\Mouse"; ValueName="MouseSpeed"; Type="String"; Data="0"; Undo="1" },
                    @{ Key="HKCU:\Control Panel\Mouse"; ValueName="MouseThreshold1"; Type="String"; Data="0"; Undo="6" },
                    @{ Key="HKCU:\Control Panel\Mouse"; ValueName="MouseThreshold2"; Type="String"; Data="0"; Undo="10" },
                    # Oturum acma ekrani (HKU\.DEFAULT) + SPI_SETMOUSE ile aninda uygulama (SPIF_UPDATEINIFILE|SPIF_SENDCHANGE = 3)
                    @{
                        Command='
                            foreach ($n in @("MouseSpeed","MouseThreshold1","MouseThreshold2")) { Set-ItemProperty -Path "Registry::HKEY_USERS\.DEFAULT\Control Panel\Mouse" -Name $n -Value "0" -Type String -Force -ErrorAction SilentlyContinue }
                            try { [void][NativeMethods]::SystemParametersInfoInts(4, 0, [int[]](0,0,0), 3) } catch {}
                        ';
                        UndoCommand='
                            $def = @{ MouseSpeed="1"; MouseThreshold1="6"; MouseThreshold2="10" }
                            foreach ($n in $def.Keys) { Set-ItemProperty -Path "Registry::HKEY_USERS\.DEFAULT\Control Panel\Mouse" -Name $n -Value $def[$n] -Type String -Force -ErrorAction SilentlyContinue }
                            try { [void][NativeMethods]::SystemParametersInfoInts(4, 0, [int[]](6,10,1), 3) } catch {}
                        '
                    }
                );
                RestartExplorer=$false
            },
            # v1.3.0 (§104): oyunlara kalici Yuksek islemci onceligi (IFEO PerfOptions) — Process Lasso'suz
            @{
                Name="Oyunlara Yüksek İşlemci Önceliği Ver (Deneysel)"; Since="2.0.0"; SkipRebootDialog=$true;  # oyunun bir sonraki acilisinda gecerli, yeniden baslatma gerekmez (§106)
                SubCategory="Giriş ve İşlemci"; Risk="Low"; RestartExplorer=$false;
                Description="Oyunların (bilinen rekabetçi oyunlar + Steam / Epic / EA / Riot / Battle.net / Ubisoft / GOG kütüphanelerinde bulunanlar) işlemci önceliğini her açılışta 'Yüksek' yapar. Windows'un kendi özelliğiyle (Image File Execution Options > PerfOptions) yazılır; Process Lasso gibi arka planda çalışan bir program gerekmez. İşlemci yoğunken oyun iş parçacıkları normal öncelikli arka plan işlerinden önce çalışır.`n`nℹ️ Dürüst not: Deneyseldir. İnternetteki CS2 / Process Lasso rehberlerinde sık önerilir ama FPS kazancını gösteren kontrollü bir ölçüm bulunamadı; işlemci boşta çekirdeklere sahipken fark beklenmez. Önce / sonra MrClean Benchmark ile ölçün.`n⚠️ Oyun açıkken Discord, yayın (OBS) ve müzik gibi arka plan uygulamaları daha geç işlemci alır. 'Gerçek zamanlı' öncelik bilerek kullanılmaz (sistemi kilitleyebilir).`nℹ️ Oyun bir sonraki açılışında geçerli olur. Yeni oyun kurduysanız tweak'i yeniden uygulayın. Anti-cheat'lerle uyumludur (yalnız öncelik ayarı).`n↩️ Geri alma yalnız MrClean'in yazdığı öncelikleri önceki hâline döndürür.";
                DetectScript='
                    return (Test-MrCleanGamePriority)
                ';
                Command='
                    Set-MrCleanGamePriority
                ';
                UndoCommand='
                    Remove-MrCleanGamePriority
                '
            },
            # v1.3.0 (§106): CS2 icin yalniz CPU 0 benzesimden cikarilir (gercek CS2 olcumuyle)
            @{
                Name="CS2: CPU 0'ı Oyundan Ayır (Ölçümlü)"; Since="2.0.0"; SkipRebootDialog=$true;  # oyunun bir sonraki acilisinda gecerli, yeniden baslatma gerekmez (§106)
                SubCategory="Giriş ve İşlemci"; Risk="Low"; RestartExplorer=$false;
                Description="Counter-Strike 2 açıldığında oyunun kullanabileceği işlemcilerden yalnız CPU 0'ı çıkarır (Görev Yöneticisi > Ayrıntılar > cs2.exe > 'Benzeşimi ayarla'da CPU 0'ın işaretini kaldırmakla aynı), her açılışta kendiliğinden. Windows'un kendi işleri ve donanım kesmeleri çoğunlukla CPU 0'da çalışır; CS2'nin ana iş parçacıkları onlarla çakışmaz.`n`n📊 MrClean ölçümü (gerçek CS2, atölye FPS benchmark haritası, 3 + 3 tur, Ryzen 7 9800X3D): ortalama FPS 758,9 → 788,6 (+%3,9), 1% low 319,4 → 348,8 (+%9,2), en kötü %1 kare süresi 3,14 → 2,87 ms.`n`nℹ️ Kazanç sisteme göre değişir; önce / sonra kendi bilgisayarınızda ölçün. Yalnız CS2'ye uygulanır — çok iş parçacıklı oyunlarda işlemci ayırmak yapay testte FPS'i düşürdü.`nℹ️ Yönetici yetkisi istemeyen küçük bir zamanlanmış görev ('MrClean-CS2Cpu0') kurulur; CS2 açıldıktan ~2 sn içinde uygulanır, oyun kapanınca iz kalmaz. VAC ile uyumludur (yalnız işlemci benzeşimi). Process Lasso'da CS2 için ayrı bir benzeşim kuralınız varsa kaldırın.`n↩️ Geri alma görevi kaldırır; açık bir CS2 varsa tüm işlemcilere geri verilir.";
                DetectScript='
                    return (Test-MrCleanCs2Cpu0)
                ';
                Command='
                    Install-MrCleanCs2Cpu0
                ';
                UndoCommand='
                    Remove-MrCleanCs2Cpu0
                '
            },
            @{
                Name="MSI Mode (GPU Interrupt) Aç";
                SubCategory="Giriş ve İşlemci";
                Description="Fiziksel ekran kartları için Message Signaled Interrupts (MSI) modunu açar: klasik hat tabanlı kesme yerine mesajla kesme kullanılır, paylaşımlı IRQ çakışması ve DPC gecikmesi azalır. Anti-cheat uyumludur.`n`nℹ️ AMD ve yeni NVIDIA kartların çoğunda sürücü MSI'yı zaten açar — bu sistemlerde tweak aktif görünür, yapılacak iş yoktur.`n✅ Yalnız gerçek PCI ekran kartlarına uygulanır (sanal / uzak masaüstü adaptörleri atlanır); önceki değer yedeklenir, geri alma ona döner.`n⚠️ Yeniden başlatma sonrası geçerli olur.";
                Risk="Low"; RestartExplorer=$false;
                # v1.3.0 (4. tur): ControlSet001 yerine CurrentControlSet; sadece mevcut (PresentOnly) fiziksel PCI ekran
                # kartlari (sanal/Parsec/IddCx adaptorleri atlanir); orijinal MSISupported yedeklenir. Eski undo degeri
                # SILIYORDU — surucusu MSI'yi zaten acan kartlar (AMD, RTX 50 cogu) eski tip IRQ'ya dusuyordu.
                DetectScript='
                    # 14. tur: surucusuz aygit (Status Error — or. Ryzen dahili grafik "Microsoft Temel Goruntu Bagdastiricisi") sayilmaz
                    $gpus = @(Get-PnpDevice -Class Display -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -like "PCI\VEN_*" -and "$($_.Status)" -eq "OK" })
                    if ($gpus.Count -eq 0) { return $false }
                    foreach ($g in $gpus) {
                        $key = "HKLM:\SYSTEM\CurrentControlSet\Enum\$($g.InstanceId)\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
                        $v = (Get-ItemProperty -Path $key -Name "MSISupported" -ErrorAction SilentlyContinue).MSISupported
                        if ("$v" -ne "1") { return $false }
                    }
                    return $true
                ';
                Command='
                    Get-PnpDevice -Class Display -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -like "PCI\VEN_*" } | ForEach-Object {
                        $instId = $_.InstanceId
                        $key = "HKLM:\SYSTEM\CurrentControlSet\Enum\$instId\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
                        $id = "MSI_" + ($instId -replace "[^A-Za-z0-9]", "_")
                        Backup-TweakRegValue $id $key "MSISupported"
                        if (-not (Test-Path $key)) { New-Item -Path $key -Force -ErrorAction SilentlyContinue | Out-Null }
                        Set-ItemProperty -Path $key -Name "MSISupported" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    }
                ';
                UndoCommand='
                    # Yedekten geri yukle: surucu MSI yi kendisi aciyorsa (deger 1) aynen kalir; hic yoksa silinir
                    Get-PnpDevice -Class Display -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -like "PCI\VEN_*" } | ForEach-Object {
                        $instId = $_.InstanceId
                        $key = "HKLM:\SYSTEM\CurrentControlSet\Enum\$instId\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
                        $id = "MSI_" + ($instId -replace "[^A-Za-z0-9]", "_")
                        if (Test-Path $key) { Restore-TweakRegValue $id $key "MSISupported" }
                    }
                '
            },
            # v1.3.0 (5. tur): "Timer Resolution 0.5ms (Espor)" tweak'i KALDIRILDI — tek yeri Araclar > Timer Testi
            # (stres testi ile bulunan optimal deger + Enable/Disable-MrCleanTimerResolution).

            # --- B: AĞ VE PİNG (NETWORK) ---
            # v1.3.0 (11. tur, birlestirme): diger gelistiricinin RSC tweaki — bagimsiz; tespit dilden bagimsiz (Get-NetOffloadGlobalSetting)
            @{
                Name="RSC (Receive Segment Coalescing) Kapat"; Since="2.0.0";
                SubCategory="Ağ ve Ping"; Group="NetProfile";
                Risk="Low"; RestartExplorer=$false; RequiresReboot=$true;
                Description="Ağ kartının gelen küçük TCP paketlerini birleştirip toplu teslim etmesini (Receive Segment Coalescing) kapatır. Paketler beklemeden tek tek işlenir — TCP kullanan oyun / uygulamalarda küçük bir gecikme kazancı olabilir.`n`n⚠️ Çok büyük dosya indirmelerinde (Steam, 1 Gbit+) CPU kullanımı biraz artabilir.`nℹ️ Sadece FİZİKSEL ağ kartlarına uygulanır — Mullvad / WARP / Proton gibi VPN sanal kartlarına dokunulmaz. '[SIFIRLA] Windows Varsayılanları' ile aynı gruptadır (biri seçilince diğeri kapanır) — [SIFIRLA] RSC'yi geri açar.`n🔄 Kartın yeniden başlaması / bilgisayarın yeniden başlatılması sonrası tam etkili olur.";
                DetectScript='
                    # v1.3.0 (§89): denetimden önce zaten okunan netsh çıktısı (~216 -> ~0 ms); satır bulunamazsa eski yol
                    $o = "$script:NetshTcpGlobalOutput"
                    if ($o -match "(?im)^\s*Receive Segment Coalescing State\s*:\s*(\w+)") { return ($Matches[1] -eq "disabled") }
                    $g = Get-NetOffloadGlobalSetting -ErrorAction SilentlyContinue
                    return ($g -and "$($g.ReceiveSegmentCoalescing)" -eq "Disabled")
                ';
                Command='
                    try { Set-NetOffloadGlobalSetting -ReceiveSegmentCoalescing Disabled -ErrorAction Stop } catch { netsh int tcp set global rsc=disabled | Out-Null }
                    Get-MrCleanPhysicalAdapters | ForEach-Object { Disable-NetAdapterRsc -Name $_.Name -NoRestart -ErrorAction SilentlyContinue }
                    $script:NetshTcpGlobalOutput = ""
                    Write-Host "[RSC] Genel + fiziksel ag kartlarinda RSC kapatildi."
                ';
                UndoCommand='
                    try { Set-NetOffloadGlobalSetting -ReceiveSegmentCoalescing Enabled -ErrorAction Stop } catch { netsh int tcp set global rsc=enabled | Out-Null }
                    Get-MrCleanPhysicalAdapters | ForEach-Object { Enable-NetAdapterRsc -Name $_.Name -NoRestart -ErrorAction SilentlyContinue }
                    $script:NetshTcpGlobalOutput = ""
                    Write-Host "[RSC] Windows varsayilani (acik) geri yuklendi."
                '
            },
			@{
				Name        = "[SIFIRLA] Windows Varsayılanları"
				SubCategory = "Ağ ve Ping"
				Group       = "NetProfile"
				Description = "Tüm ağ yığınını, TCP algoritmalarını ve kısıtlamaları Windows'un orijinal kurulum ayarlarına geri döndürür.`n`nℹ️ MrClean bilerek hat HIZINA göre ayar yapmaz (sabit TCP pencere boyutu, kısıtlı/kapalı otomatik pencere ayarı, MinRto vb.): Türkiye'de hat hızı ve gecikme gün içinde çok dalgalanır; bir hıza göre sabitlenen değer başka bir saatte indirmeyi ciddi yavaşlatabilir — riskli. Başka bir 'optimizasyon' aracı bu tür değerler bıraktıysa bu seçenek Windows'un kendi otomatik ayarına döndürür.`n✅ YogaDNS, GoodbyeDPI ve Mullvad / WARP / Proton gibi VPN'lere dokunmaz.";
				Command     = '
					# ✅ Önce disabled/restricted modunu kır, sonra normal yap
					netsh int tcp set global autotuninglevel=disabled  | Out-Null
					Start-Sleep -Milliseconds 200
					netsh int tcp set global autotuninglevel=normal    | Out-Null

					netsh int tcp set global congestionprovider=default | Out-Null
					netsh int tcp set global ecncapability=default      | Out-Null
					netsh int tcp set global rss=enabled                | Out-Null
					netsh int tcp set global rsc=enabled                | Out-Null
					netsh int tcp set global timestamps=disabled        | Out-Null
					netsh int tcp set global maxsynretransmissions=2    | Out-Null
					netsh int tcp set global nonsackrttresiliency=disabled | Out-Null

					$pathTCP = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters"
					@(
						"MaxUserPort","TcpTimedWaitDelay","DefaultTTL",
						"InitialRto","MinRto","TcpWindowSize","GlobalMaxTcpWindowSize"
					) | ForEach-Object {
						Remove-ItemProperty -Path $pathTCP -Name $_ -ErrorAction SilentlyContinue
					}

					$pathMM = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
					Set-ItemProperty -Path $pathMM -Name "NetworkThrottlingIndex" -Value 10 -Type DWord -Force
					Set-ItemProperty -Path $pathMM -Name "SystemResponsiveness"   -Value 20 -Type DWord -Force

					# v1.3.0 (4. tur): IPv6 de geri acilir (profil IPv4+IPv6 kapatiyordu), sadece fiziksel adaptorler
					Get-MrCleanPhysicalAdapters | ForEach-Object {
						Enable-NetAdapterChecksumOffload -Name $_.Name -IpIPv4 -TcpIPv4 -TcpIPv6 -UdpIPv4 -UdpIPv6 -NoRestart -ErrorAction SilentlyContinue
						Enable-NetAdapterLso -Name $_.Name -IPv4 -IPv6 -NoRestart -ErrorAction SilentlyContinue
						Enable-NetAdapterRsc -Name $_.Name -IPv4 -IPv6 -NoRestart -ErrorAction SilentlyContinue
					}
					# TCP sablonu varsayilani (gecikmeli ACK 40 ms / 2)
					netsh int tcp set supplemental template=internet delayedackfrequency=2 delayedacktimeout=40 | Out-Null
					# v1.3.0 (11. tur, birlestirme): dinamik (gecici) port araligi Windows varsayilanina — baska "optimizasyon" araclari daraltiyor
					netsh int ipv4 set dynamicport tcp start=49152 num=16384 | Out-Null
					netsh int ipv4 set dynamicport udp start=49152 num=16384 | Out-Null
					netsh int ipv6 set dynamicport tcp start=49152 num=16384 | Out-Null
					netsh int ipv6 set dynamicport udp start=49152 num=16384 | Out-Null
				'
				UndoCommand     = ""
				RestartExplorer = $false
			},
            @{
                Name="Network Throttling Kapat (Ağ Kısıtlamasını Kaldır)";
                SubCategory="Ağ ve Ping";
				Description="Windows'un multimedya (müzik/video) çalarken multimedya dışı ağ paketlerini sınırlayan mekanizmasını kapatır (NetworkThrottlingIndex=FFFFFFFF). Arka planda Spotify/YouTube açıkken yüksek hızlı indirmelerde fark edilir.`n`nℹ️ Dürüst not: Oyun ping'ine etkisi küçüktür; djdallmann ölçümlerinde açık bırakmak (varsayılan 10) NDIS DPC gecikmesini bir miktar düşürmüştür. 1 Gbit+ hatta indirme yapan için faydalı, sadece oyun için tartışmalıdır. Varsayılana dönmek için geri alın.";
                Key="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"; ValueName="NetworkThrottlingIndex"; Type="DWord"; Data=0xffffffff; Undo=10; RestartExplorer=$false
            },

            # === NETWORK ADAPTER POWER SAVINGS & WAKE (FR33THY 26 birebir kompozit) ===
            @{
                Name="Ağ Kartı Güç Tasarrufu ve Uyandırma Kapat (Tümü)";
                SubCategory="Ağ ve Ping";
                Risk="Low"; RestartExplorer=$false;
                Description="Fiziksel Ethernet ve Wi-Fi kartlarındaki güç tasarrufu ve uyandırma özelliklerini kapatır — boşta kalınca kartın uykuya geçip ilk paketlerde gecikme / ping sıçraması yapmasını önler:`n• Energy Efficient Ethernet, Green Ethernet, Power Saving Mode, Gigabit Lite ve benzeri tasarruf modları`n• Otomatik güç tasarrufu, dinamik güç kesme, kapanınca hız düşürme`n• Wake-on-LAN / Magic Packet / desen ile uyandırma`n• Aygıt Yöneticisi > Güç Yönetimi: 'Güç tasarrufu için bilgisayar bu aygıtı kapatabilir' kapalı`n`n✅ Yalnız sürücünün desteklediği ayarlar değişir; orijinal değerler yedeklenir, geri alma sürücünün kendi değerlerini aynen geri yükler.`n⚠️ Wake-on-LAN (uzaktan açma) kullanıyorsanız uygulamayın. Dizüstünde pil biraz daha hızlı tükenebilir.";
                DetectScript='
                    # v1.3.0 (4. tur): sadece PnPCapabilities degil GERCEK guc degerleri de kontrol edilir. Surucu guncellemesi
                    # EEE / Green Ethernet / Selective Suspend degerlerini sifirlarsa tweak PASIF gorunur → yeniden uygulanir.
                    $base = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"
                    $chk = @("*EEE","AdvancedEEE","EnableGreenEthernet","GigaLite","PowerSavingMode","ULPMode","*SelectiveSuspend","*NicAutoPowerSaver","AutoPowerSaveModeEnabled")
                    $found = 0
                    foreach ($k in (Get-ChildItem -Path $base -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match "^\d{4}$" })) {
                        $p = Get-ItemProperty -Path $k.PSPath -ErrorAction SilentlyContinue
                        if (-not $p -or "$($p."*IfType")" -notin @("6","71")) { continue }
                        if ("$($p.DriverDesc)" -match "(?i)Virtual|VPN|TAP|Hyper-V|Miniport|Bluetooth|Loopback") { continue }
                        $found++
                        if ("$($p.PnPCapabilities)" -ne "24") { return $false }
                        foreach ($n in $chk) { if (($p.PSObject.Properties.Name -contains $n) -and "$($p.$n)" -ne "0") { return $false } }
                    }
                    return ($found -gt 0)
                ';
                Command='
                    $base = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"
                    $bkRoot = "HKLM:\SOFTWARE\MrClean\NicPowerBackup"
                    $names = @("*EEE","AdvancedEEE","EEELinkAdvertisement","SipsEnabled","ULPMode","GigaLite","EnableGreenEthernet","PowerSavingMode",
                               "*NicAutoPowerSaver","AutoPowerSaveModeEnabled","EnableConnectedPowerGating","*EnableDynamicPowerGating","ReduceSpeedOnPowerDown",
                               "S5WakeOnLan","*WakeOnMagicPacket","*ModernStandbyWoLMagicPacket","*WakeOnPattern","WakeOnLink","*DeviceSleepOnDisconnect","*SelectiveSuspend")
                    $count = 0
                    Get-ChildItem -Path $base -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match "^\d{4}$" } | ForEach-Object {
                        $p = $_.PSPath
                        $props = Get-ItemProperty -Path $p -ErrorAction SilentlyContinue
                        if (-not $props) { return }
                        # Sadece fiziksel Ethernet (6) / Wi-Fi (71) — sanal/VPN/Bluetooth PAN adaptorleri atlanir
                        if ("$($props."*IfType")" -notin @("6","71")) { return }
                        if ("$($props.DriverDesc)" -match "(?i)Virtual|VPN|TAP|Hyper-V|Miniport|Bluetooth|Loopback") { return }

                        # Yedek: ilk uygulamada orijinal degerler saklanir (tekrar uygulamada uzerine yazilmaz)
                        $bk = Join-Path $bkRoot $_.PSChildName
                        if (-not (Test-Path $bk)) {
                            New-Item -Path $bk -Force -ErrorAction SilentlyContinue | Out-Null
                            $hasPnp = $props.PSObject.Properties.Name -contains "PnPCapabilities"
                            if ($hasPnp) { Set-ItemProperty -Path $bk -Name "PnPCapabilities" -Value $props.PnPCapabilities -Type DWord -Force }
                            else { Set-ItemProperty -Path $bk -Name "__PnPCapabilities_absent" -Value 1 -Type DWord -Force }
                            foreach ($n in $names) {
                                if ($props.PSObject.Properties.Name -contains $n) {
                                    Set-ItemProperty -Path $bk -Name $n -Value "$($props.$n)" -Type String -Force
                                }
                            }
                        }

                        Set-ItemProperty -Path $p -Name "PnPCapabilities" -Value 24 -Type DWord -Force -ErrorAction SilentlyContinue
                        foreach ($n in $names) {
                            # Surucu bu ayari tanimlamiyorsa YAZMA (gereksiz deger birakma)
                            if ($props.PSObject.Properties.Name -contains $n) {
                                Set-ItemProperty -Path $p -Name $n -Value "0" -Force -ErrorAction SilentlyContinue
                            }
                        }
                        $count++
                    }
                    Write-Host "[NetAdapter] $count fiziksel adaptor icin guc tasarrufu + uyandirma kapatildi (orijinaller yedeklendi)."
                ';
                UndoCommand='
                    $base = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"
                    $bkRoot = "HKLM:\SOFTWARE\MrClean\NicPowerBackup"
                    $count = 0
                    Get-ChildItem -Path $base -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match "^\d{4}$" } | ForEach-Object {
                        $p = $_.PSPath
                        $bk = Join-Path $bkRoot $_.PSChildName
                        if (Test-Path $bk) {
                            $b = Get-ItemProperty -Path $bk -ErrorAction SilentlyContinue
                            foreach ($prop in $b.PSObject.Properties) {
                                if ($prop.Name -like "PS*") { continue }
                                if ($prop.Name -eq "__PnPCapabilities_absent") {
                                    Remove-ItemProperty -Path $p -Name "PnPCapabilities" -Force -ErrorAction SilentlyContinue
                                } elseif ($prop.Name -eq "PnPCapabilities") {
                                    Set-ItemProperty -Path $p -Name "PnPCapabilities" -Value $prop.Value -Type DWord -Force -ErrorAction SilentlyContinue
                                } else {
                                    Set-ItemProperty -Path $p -Name $prop.Name -Value $prop.Value -Force -ErrorAction SilentlyContinue
                                }
                            }
                            $count++
                        } else {
                            # Yedek yok (v1.2.x ile uygulanmis): sadece bizim ekledigimiz PnPCapabilities=24 kaldirilir;
                            # surucu degerleri SILINMEZ (eski surumun Gelismis sekmesini bosaltan davranisi duzeltildi).
                            $v = (Get-ItemProperty -Path $p -Name "PnPCapabilities" -ErrorAction SilentlyContinue).PnPCapabilities
                            if ("$v" -eq "24") { Remove-ItemProperty -Path $p -Name "PnPCapabilities" -Force -ErrorAction SilentlyContinue; $count++ }
                        }
                    }
                    Remove-Item -Path $bkRoot -Recurse -Force -ErrorAction SilentlyContinue
                    Write-Host "[NetAdapter] $count adaptor orijinal guc ayarlarina dondu."
                '
            },
            @{
                Name="RSS İşlemcisini Çekirdek 0'dan Uzaklaştır (Ethernet, Uzman)"; Requires=@("Ethernet","Cores4");
                SubCategory="Ağ ve Ping"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Ethernet kartının gelen paket işleme (RSS) işini 0. çekirdek yerine 2. mantıksal işlemciden (2. fiziksel çekirdek) başlatır. 0. çekirdek sistem saati, birçok kesme ve DPC ile zaten en meşgul çekirdektir; ağ DPC'leri oradan uzaklaşınca DPC gecikmesi düşebilir.`n`nℹ️ Dürüst not: Etki sisteme bağlıdır; djdallmann/GamingPCSetup ağ rehberinin önerisidir, büyük FPS kazancı beklemeyin. 4'ten az mantıksal işlemcide ve RSS'i kapalı kartlarda hiçbir şey yapmaz. Wi-Fi kartlarında RSS genelde yoktur.`n⚠️ Ayar uygulanırken Ethernet bağlantısı 2-5 sn kopabilir.`n✅ Önceki değer yedeklenir, geri alma ona döner.`n📚 Kaynak: djdallmann/GamingPCSetup (NETWORK), tweaqas Network_Tweaker; Microsoft RSS belgeleri.";
                DetectScript='
                    # v1.3.0 (§90): yalnız takılı Ethernet kartları; *RSS ve *RssBaseProcNumber kartın sürücü kaydından (değer yoksa sürücü varsayılanı)
                    $seen = 0
                    foreach ($a in (Get-MrCleanNicFast | Where-Object { $_.InterfaceType -eq 6 })) {
                        $ps = Get-MrCleanNicParamsFast $a.RegPath
                        if ($null -eq $ps) { $r = Get-NetAdapterRss -Name $a.Name -ErrorAction SilentlyContinue; if (-not $r -or -not $r.Enabled) { continue }; $seen++; if ([int]$r.BaseProcessorNumber -lt 2) { return $false }; continue }
                        $en = @($ps | Where-Object { $_.RegistryKeyword -eq "*RSS" })[0]
                        if (-not $en -or "$($en.RegistryValue)" -ne "1") { continue }
                        $seen++
                        $bp = @($ps | Where-Object { $_.RegistryKeyword -eq "*RssBaseProcNumber" })[0]
                        $bv = 0; if ($bp -and "$($bp.RegistryValue)" -ne "") { $bv = [int]"$($bp.RegistryValue)" }
                        if ($bv -lt 2) { return $false }
                    }
                    return ($seen -gt 0)
                ';
                Command='
                    if ([Environment]::ProcessorCount -lt 4) { WpfLog "[RSS] 4 ten az mantiksal islemci — atlandi."; return }
                    foreach ($a in (Get-MrCleanPhysicalAdapters | Where-Object { $_.InterfaceType -eq 6 })) {
                        $r = Get-NetAdapterRss -Name $a.Name -ErrorAction SilentlyContinue
                        if (-not $r -or -not $r.Enabled) { continue }
                        $id = "RssBase_" + ("$($a.InterfaceGuid)" -replace "[^A-Za-z0-9]", "")
                        $root = "HKLM:\SOFTWARE\MrClean\ValueBackup"
                        if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }
                        if (-not ((Get-Item -Path $root).GetValueNames() -contains $id)) { Set-ItemProperty -Path $root -Name $id -Value "$($r.BaseProcessorNumber)" -Type String -Force }
                        try { Set-NetAdapterRss -Name $a.Name -BaseProcessorNumber 2 -ErrorAction Stop } catch { WpfLog "[RSS] $($a.Name): $($_.Exception.Message)" }
                    }
                ';
                UndoCommand='
                    $root = "HKLM:\SOFTWARE\MrClean\ValueBackup"
                    foreach ($a in (Get-MrCleanPhysicalAdapters | Where-Object { $_.InterfaceType -eq 6 })) {
                        $id = "RssBase_" + ("$($a.InterfaceGuid)" -replace "[^A-Za-z0-9]", "")
                        $v = (Get-ItemProperty -Path $root -Name $id -ErrorAction SilentlyContinue).$id
                        $base = if ("$v" -match "^\d+$") { [int]$v } else { 0 }
                        try { Set-NetAdapterRss -Name $a.Name -BaseProcessorNumber $base -ErrorAction SilentlyContinue } catch {}
                        Remove-ItemProperty -Path $root -Name $id -Force -ErrorAction SilentlyContinue
                    }
                '
            },
            @{
                Name="Ethernet Akış Denetimini Kapat (Flow Control, Uzman)"; Requires=@("Ethernet");
                SubCategory="Ağ ve Ping"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Ethernet kartının 802.3x 'duraklat' (pause) çerçevelerine uymasını kapatır: switch / modem yoğunken kart gönderimi saniyenin kesirleri kadar durdurmaz.`n`nℹ️ Dürüst not: ev ağlarında pause çerçevesi nadirdir. MrClean ölçümünde (Realtek 5GbE) varsayılandan fark görülmedi; bu yüzden profillerde yoktur. Bağlantı sorunu görürseniz geri alın.`n⚠️ Uygulanırken Ethernet bağlantısı birkaç saniye kopar.`n✅ Önceki değer yedeklenir, geri alma ona döner. Wi-Fi'ye dokunulmaz.`n📚 Kaynak: djdallmann/GamingPCSetup, tweaqas Network_Tweaker.";
                DetectScript='
                    $seen = 0
                    foreach ($a in (Get-MrCleanNicFast | Where-Object { $_.InterfaceType -eq 6 })) {   # v1.3.0 (§90): sürücü kaydından
                        $ps = Get-MrCleanNicParamsFast $a.RegPath
                        $p = if ($null -eq $ps) { Get-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword "*FlowControl" -ErrorAction SilentlyContinue } else { @($ps | Where-Object { $_.RegistryKeyword -eq "*FlowControl" })[0] }
                        if (-not $p) { continue }
                        $seen++
                        if ("$(@($p.RegistryValue)[0])" -ne "0") { return $false }
                    }
                    return ($seen -gt 0)
                ';
                Command='
                    $n = Set-MrCleanEthProperty "FlowCtl" "*FlowControl" { param($p) "0" }
                    if ($n -gt 0) { Restart-MrCleanEthernet }
                ';
                UndoCommand='
                    if ((Restore-MrCleanWifiProperties "FlowCtl") -gt 0) { Restart-MrCleanEthernet }
                '
            },
            @{
                Name="Ethernet Alım Arabelleğini Artır (Receive Buffers ≥ 1024)"; Requires=@("Ethernet");
                SubCategory="Ağ ve Ping"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Ethernet kartının alım arabelleği 1024'ün altındaysa (bazı Realtek / Intel kartlarda varsayılan 256-512) sürücünün izin verdiği en fazla 2048'e çıkarır. Yoğun indirme + oyun anında kartın paket düşürmesini önler; gecikmeyi artırmaz (birkaç yüz KB RAM).`n`nℹ️ Zaten 1024 ve üstündeyse hiçbir şey değiştirilmez ('Aktif' görünür).`n⚠️ Değişiklik olursa Ethernet bağlantısı 2-5 sn kopar.`n✅ Önceki değer yedeklenir, geri alma ona döner.`n📚 Kaynak: djdallmann/GamingPCSetup (NETWORK: 'increase to 1024 or higher'), tweaqas Network_Tweaker.";
                DetectScript='
                    $seen = 0
                    foreach ($a in (Get-MrCleanNicFast | Where-Object { $_.InterfaceType -eq 6 })) {   # v1.3.0 (§90): sürücü kaydından
                        $ps = Get-MrCleanNicParamsFast $a.RegPath
                        $p = if ($null -eq $ps) { Get-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword "*ReceiveBuffers" -ErrorAction SilentlyContinue } else { @($ps | Where-Object { $_.RegistryKeyword -eq "*ReceiveBuffers" })[0] }
                        if (-not $p) { continue }
                        $seen++
                        $max = if ($p.NumericParameterMaxValue) { [int]$p.NumericParameterMaxValue } else { 1024 }
                        if ([int]"0$(@($p.RegistryValue)[0])" -lt [Math]::Min(1024, $max)) { return $false }
                    }
                    return ($seen -gt 0)
                ';
                Command='
                    $n = Set-MrCleanEthProperty "RxBuf" "*ReceiveBuffers" {
                        param($p)
                        $cur = [int]"0$(@($p.RegistryValue)[0])"
                        if ($cur -ge 1024) { return $null }
                        $max = if ($p.NumericParameterMaxValue) { [int]$p.NumericParameterMaxValue } else { 2048 }
                        $t = [Math]::Min(2048, $max)
                        if ($p.NumericParameterStepValue -and [int]$p.NumericParameterStepValue -gt 1) { $st = [int]$p.NumericParameterStepValue; $t = [int]([Math]::Floor($t / $st) * $st) }
                        if ($t -le $cur) { return $null }
                        return "$t"
                    }
                    if ($n -gt 0) { Restart-MrCleanEthernet }
                ';
                UndoCommand='
                    if ((Restore-MrCleanWifiProperties "RxBuf") -gt 0) { Restart-MrCleanEthernet }
                '
            },
            @{
                Name="NetBIOS Ad Yayınlarını Kapat (Eski Ağ Protokolü)";
                SubCategory="Ağ ve Ping"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Fiziksel ağ kartlarında eski 'NetBIOS over TCP/IP' protokolünü kapatır: 137-139 portları kapanır, yerel ağa sürekli ad yayını yapılmaz (güvenlik + ağ gürültüsü). Anında uygulanır.`n`n✅ Spotify Connect, Chromecast, Steam yerel ağ / Remote Play, yazıcı keşfi (mDNS / WSD) ve internet ETKİLENMEZ.`n⚠️ Çok eski NAS / modem paylaşımına veya Windows XP/7 dönemi cihaza ADIYLA (\\\\BILGISAYAR) erişiyorsanız IP adresiyle erişmeniz gerekebilir.`n📚 Kaynak: djdallmann/GamingPCSetup, valleyofdoom/PC-Tuning, Winrift.";
                DetectScript='
                    $seen = 0
                    foreach ($a in (Get-MrCleanNicFast)) {   # v1.3.0 (§90): yalnız takılı kartlar
                        $v = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces\Tcpip_$($a.Ni.Id)" -Name "NetbiosOptions" -ErrorAction SilentlyContinue).NetbiosOptions
                        $seen++
                        if ("$v" -ne "2") { return $false }
                    }
                    return ($seen -gt 0)
                ';
                Command='
                    foreach ($a in (Get-MrCleanPhysicalAdapters)) {
                        $k = "HKLM:\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces\Tcpip_$($a.InterfaceGuid)"
                        if (Test-Path $k) { Set-ItemProperty -Path $k -Name "NetbiosOptions" -Value 2 -Type DWord -Force -ErrorAction SilentlyContinue }
                    }
                    # Bagli adaptorlerde aninda uygula (WMI)
                    Get-CimInstance Win32_NetworkAdapterConfiguration -Filter "IPEnabled=TRUE" -ErrorAction SilentlyContinue | ForEach-Object {
                        try { Invoke-CimMethod -InputObject $_ -MethodName SetTcpipNetbios -Arguments @{ TcpipNetbiosOptions = [uint32]2 } -ErrorAction SilentlyContinue | Out-Null } catch {}
                    }
                ';
                UndoCommand='
                    foreach ($a in (Get-MrCleanPhysicalAdapters)) {
                        $k = "HKLM:\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces\Tcpip_$($a.InterfaceGuid)"
                        if (Test-Path $k) { Set-ItemProperty -Path $k -Name "NetbiosOptions" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue }
                    }
                    Get-CimInstance Win32_NetworkAdapterConfiguration -Filter "IPEnabled=TRUE" -ErrorAction SilentlyContinue | ForEach-Object {
                        try { Invoke-CimMethod -InputObject $_ -MethodName SetTcpipNetbios -Arguments @{ TcpipNetbiosOptions = [uint32]0 } -ErrorAction SilentlyContinue | Out-Null } catch {}
                    }
                '
            },
            @{
                Name="IPv4'ü IPv6'ya Tercih Et (Ölçümlü, IPv6 Kapatılmaz)";
                SubCategory="Ağ ve Ping"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Hem IPv4 hem IPv6 adresi olan sunuculara (web, CDN, Discord, Steam, Battle.net) bağlanırken IPv4'ün tercih edilmesini sağlar — bazı ISS'lerde IPv6 yolu daha uzun / daha dalgalı olabiliyor. Microsoft'un önerdiği yöntem: önek tablosunda IPv4 önceliği yükseltilir (yeniden başlatma GEREKMEZ). IPv6 KAPATILMAZ (kapatmak Windows bileşenlerini bozar).`n`n📏 Uygulamadan önce ÖLÇÜLÜR: Google DNS'e IPv4 ve IPv6 ping karşılaştırılır; IPv6 belirgin şekilde daha hızlıysa tweak UYGULANMAZ (log'a yazılır).`nℹ️ Oyun sunucularının çoğu zaten yalnızca IPv4'tür; fark daha çok web/launcher/CDN tarafındadır. DS-Lite / CGNAT'lı ISS'lerde IPv4 daha yavaş olabilir — ölçüm bunu yakalar.`n📚 Kaynak: Microsoft 'Configure IPv6 in Windows' (prefer IPv4 over IPv6); winscript, kubsonxtm (orada kayıt değeriyle — yeniden başlatma ister).";
                DetectScript='
                    $line = @(& netsh interface ipv6 show prefixpolicies 2>$null | Where-Object { "$_" -match "::ffff:0:0/96" }) | Select-Object -First 1
                    return ("$line" -match "^\s*(\d+)\s+\d+\s+::ffff:0:0/96" -and [int]$Matches[1] -ge 45)
                ';
                Command='
                    $v4 = Measure-MrCleanRtt "8.8.8.8"
                    $v6 = Measure-MrCleanRtt "2001:4860:4860::8888"
                    if ($null -ne $v6 -and $null -ne $v4 -and $v6 -lt ($v4 - 1)) {
                        WpfLog "[ATLANDI] IPv4 tercihi: bu baglantida IPv6 daha hizli (IPv6 $v6 ms / IPv4 $v4 ms) — degisiklik yapilmadi."
                        return
                    }
                    & netsh interface ipv6 set prefixpolicy ::ffff:0:0/96 45 4 2>$null | Out-Null
                    $txt6 = if ($null -eq $v6) { "IPv6 yok" } else { "IPv6 $v6 ms" }
                    WpfLog "[IPv4 tercihi] Uygulandi (IPv4 $v4 ms / $txt6)."
                ';
                UndoCommand='
                    & netsh interface ipv6 set prefixpolicy ::ffff:0:0/96 35 4 2>$null | Out-Null
                '
            },
            @{
                Name="Wi-Fi: 5 GHz Bandını Tercih Et"; Requires=@("WiFiBand");
                SubCategory="Wi-Fi (Kablosuz)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Wi-Fi kartının sürücü ayarı 'Tercih Edilen Bant'ı 5 GHz yapar (Intel / Qualcomm / MediaTek / Realtek / Killer — ayar adı ve dilinden bağımsız bulunur). Modem aynı adla 2.4 + 5 GHz yayın yapıyorsa kart kalabalık 2.4 GHz yerine 5 GHz'e bağlanır: daha düşük ve kararlı ping.`n`n🎧 ÖNEMLİ YAN FAYDA: 2.4 GHz bandı Bluetooth ve 2.4 GHz kablosuz kulaklık / fare / klavye alıcılarıyla AYNI frekanstır. Wi-Fi 5 GHz'e geçince bu cihazların kopma ve ses cızırtısı azalır (Wi-Fi + Bluetooth birleşik kartlarda belirgin).`n`n⚠️ Uygulanırken Wi-Fi 5-15 sn kopar. 5 GHz duvarlardan daha zayıf geçer — modeme uzak odada sinyal düşerse geri alın. Kartta bu ayar yoksa hiçbir şey yapmaz.`n✅ Önceki değer yedeklenir, geri alma ona döner.`n📚 Kaynak: Intel kablosuz gelişmiş ayarlar belgesi; ağ araştırması.";
                DetectScript='
                    return (Test-MrCleanWifiProperty "(?i)prefer.*band|band.*prefer|tercih.*bant|bant.*tercih" "(?i)5\s*G")
                ';
                Command='
                    $n = Set-MrCleanWifiProperty "WifiBand" "(?i)prefer.*band|band.*prefer|tercih.*bant|bant.*tercih" "(?i)5\s*G"
                    if ($n -gt 0) { Restart-MrCleanWifi } else { WpfLog "[Wi-Fi] Tercih edilen bant ayari bulunamadi veya zaten 5 GHz." }
                ';
                UndoCommand='
                    if ((Restore-MrCleanWifiProperties "WifiBand") -gt 0) { Restart-MrCleanWifi }
                '
            },
            @{
                Name="Wi-Fi: Dolaşımı En Aza İndir ve Güç Tasarrufunu Kapat (Tek Modem)"; Requires=@("WiFiAdv");
                SubCategory="Wi-Fi (Kablosuz)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Wi-Fi kartının sürücü ayarlarını oyun için düzenler (ayar adı ve dilinden bağımsız bulunur, kartta olmayan atlanır):`n  • Dolaşım saldırganlığı (Roaming Aggressiveness / Sensitivity) = En Düşük: kart sinyal biraz düşünce 'daha iyi erişim noktası' aramak için kanal taramaz → periyodik ping sıçramaları azalır.`n  • MIMO güç tasarrufu = Kapalı (No SMPS): tüm anten akışları açık kalır.`n  • Paket birleştirme (Packet Coalescing) = Kapalı.`n`n⚠️ Mesh / birden fazla erişim noktalı evlerde odalar arası geçiş yavaşlar — o durumda uygulamayın. Uygulanırken Wi-Fi 5-15 sn kopar. Pil tüketimi biraz artar.`n✅ Önceki değerler yedeklenir, geri alma onlara döner.`n📚 Kaynak: Intel 'Roaming Aggressiveness' ve gelişmiş ayarlar belgeleri; Intel topluluk ping sıçraması başlıkları.";
                DetectScript='
                    return (Test-MrCleanWifiProperty "(?i)roam" "(?i)lowest|en d.{1,2}s.{1,2}k|^\s*1[\.\s]")
                ';
                Command='
                    $n = 0
                    $n += Set-MrCleanWifiProperty "WifiRoam" "(?i)roam" "(?i)lowest|en d.{1,2}s.{1,2}k|^\s*1[\.\s]"
                    $n += Set-MrCleanWifiProperty "WifiRoam" "(?i)MIMO" "(?i)no\s*SMPS|SMPS\s*yok|kapal|disabled"
                    $n += Set-MrCleanWifiProperty "WifiRoam" "(?i)packet\s*coalesc|paket\s*birle" "(?i)^disabled$|devre d|kapal"
                    if ($n -gt 0) { Restart-MrCleanWifi } else { WpfLog "[Wi-Fi] Uygun surucu ayari bulunamadi veya zaten ayarli." }
                ';
                UndoCommand='
                    if ((Restore-MrCleanWifiProperties "WifiRoam") -gt 0) { Restart-MrCleanWifi }
                '
            },
            @{
                Name="Ağ Adaptörü Offload Profili (LSO Kapalı, RSS/Checksum Açık)";
                Aliases=@("Ağ Adaptörü Offload Devre Dışı (RSS / LSO / Checksum)");
                SubCategory="Ağ ve Ping";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Ağ kartı offload ayarlarını oyun için düzenler (hepsini kapatmaz):`n• Large Send Offload (LSO v1 / v2, IPv4 / IPv6) → kapalı`n• Receive Side Scaling (RSS) → açık`n• TCP / UDP / IP checksum offload → açık`n• Kesme hafifletme (Interrupt Moderation) → dokunulmaz`n`n⚠️ Ağ kartı birkaç saniye yeniden başlar. MrClean ölçümünde ping farkı görülmediği için profillerde yoktur.`n📚 Kaynak: djdallmann/GamingPCSetup (xperf ISR / DPC ölçümleri).";
                DetectScript='
                    # Aktif sayilma: herhangi bir fiziksel NIC de LSOv2 (IPv4 veya IPv6) kapali.
                    # Status filtresi YOK (Wi-Fi Disconnected iken de registry okunabilir — v1.2.11 dersi).
                    # v1.3.0 (§89): yalnız takılı fiziksel kartlar; değerler kartın sürücü kaydından (Get-NetAdapterAdvancedProperty ile aynı
                    # anahtarlar) — ~580 ms -> ~60 ms. Takılı olmayan eski kart kayıtları artık sonucu değiştirmez.
                    $lsoOff = $false
                    foreach ($a in (Get-MrCleanNicFast)) {
                        $pp = Get-ItemProperty -LiteralPath $a.RegPath -ErrorAction SilentlyContinue
                        if (-not $pp) { continue }
                        # v1.2.x kalintisi: RSS veya Checksum offload KAPALI ise PASIF goster → yeniden uygulayinca acilir
                        foreach ($kw in @("*RSS","*TCPChecksumOffloadIPv4","*UDPChecksumOffloadIPv4")) {
                            $q = $pp.$kw
                            if ($null -ne $q -and "$q" -eq "0") { return $false }
                        }
                        foreach ($kw in @("*LsoV2IPv4","*LsoV2IPv6")) {
                            $q = $pp.$kw
                            if ($null -ne $q -and "$q" -eq "0") { $lsoOff = $true }
                        }
                    }
                    return $lsoOff
                ';
                Command='
                    # NDIS standart keyword tablosu (dil bagimsiz). Desteklenmeyen keyword sessizce atlanir.
                    # LSO = 0 (kapali). RSS = 1 (acik). Checksum = 3 (Rx ve Tx acik).
                    $settings = @(
                        @{ Key = "*LsoV2IPv4";              Value = 0 },
                        @{ Key = "*LsoV2IPv6";              Value = 0 },
                        @{ Key = "*LsoV1IPv4";              Value = 0 },
                        @{ Key = "*RSS";                    Value = 1 },
                        @{ Key = "*TCPChecksumOffloadIPv4"; Value = 3 },
                        @{ Key = "*TCPChecksumOffloadIPv6"; Value = 3 },
                        @{ Key = "*UDPChecksumOffloadIPv4"; Value = 3 },
                        @{ Key = "*UDPChecksumOffloadIPv6"; Value = 3 },
                        @{ Key = "*IPChecksumOffloadIPv4";  Value = 3 }
                    )
                    $adapters = Get-MrCleanPhysicalAdapters
                    $adapterInfo = @($adapters | Select-Object Name, InterfaceType, Status)
                    $adapterNames = @($adapterInfo | Select-Object -ExpandProperty Name)
                    $hasWiFi = @($adapterInfo | Where-Object { $_.InterfaceType -eq 71 }).Count -gt 0
                    $dbg = $false; try { $dbg = [bool]$chkDebug.IsChecked } catch {}
                    if ($adapterNames.Count -eq 0) {
                        try { WpfLog "[NetAdapter] ⚠️ HIC fiziksel NIC bulunamadi! Internete bagli misin? Wi-Fi acik mi?" } catch {}
                    }
                    foreach ($a in $adapters) {
                        $ok = 0; $skip = 0
                        foreach ($o in $settings) {
                            # Sadece surucunun destekledigi ve degeri farkli olan keyword yazilir (gereksiz restart yok)
                            $cur = Get-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword $o.Key -ErrorAction SilentlyContinue
                            if (-not $cur) { $skip++; continue }
                            if ("$($cur.RegistryValue)" -eq "$($o.Value)") { $ok++; continue }
                            try {
                                Set-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword $o.Key -RegistryValue $o.Value -NoRestart -ErrorAction Stop
                                $ok++
                            } catch { $skip++ }
                        }
                        if ($dbg) { try { WpfLog ("[NetAdapter] " + $a.Name + ": " + $ok + " ayar dogru, " + $skip + " desteklenmiyor/atlandi") } catch {} }
                    }
                    # Tek seferde restart — yeni offload ayarlari ancak NIC yeniden baslayinca aktif olur
                    if ($adapterNames.Count -gt 0) {
                        try { $adapterNames | ForEach-Object { Restart-NetAdapter -Name $_ -Confirm:$false -ErrorAction SilentlyContinue } } catch {}
                    }
                    $timeoutSec = if ($hasWiFi) { 30 } else { 12 }
                    $deadline = (Get-Date).AddSeconds($timeoutSec)
                    while ((Get-Date) -lt $deadline) {
                        $allReady = $true
                        foreach ($n in $adapterNames) {
                            $cur = Get-NetAdapter -Name $n -ErrorAction SilentlyContinue
                            if (-not $cur -or $cur.Status -notin @("Up","Disconnected")) { $allReady = $false; break }
                        }
                        if ($allReady) { break }
                        Start-Sleep -Milliseconds 500
                    }
                ';
                UndoCommand='
                    # LSO surucu varsayilanina (acik) doner. RSS/Checksum zaten varsayilan (acik) — dokunulmaz.
                    $adapters = Get-MrCleanPhysicalAdapters
                    $adapterNames = @($adapters | Select-Object -ExpandProperty Name)
                    $hasWiFi = @($adapters | Where-Object { $_.InterfaceType -eq 71 }).Count -gt 0
                    foreach ($a in $adapters) {
                        foreach ($kw in @("*LsoV2IPv4","*LsoV2IPv6","*LsoV1IPv4")) {
                            $cur = Get-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword $kw -ErrorAction SilentlyContinue
                            if ($cur -and "$($cur.RegistryValue)" -ne "1") {
                                try { Set-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword $kw -RegistryValue 1 -NoRestart -ErrorAction Stop } catch {}
                            }
                        }
                    }
                    if ($adapterNames.Count -gt 0) {
                        try { $adapterNames | ForEach-Object { Restart-NetAdapter -Name $_ -Confirm:$false -ErrorAction SilentlyContinue } } catch {}
                    }
                    $timeoutSec = if ($hasWiFi) { 30 } else { 12 }
                    $deadline = (Get-Date).AddSeconds($timeoutSec)
                    while ((Get-Date) -lt $deadline) {
                        $allReady = $true
                        foreach ($n in $adapterNames) {
                            $cur = Get-NetAdapter -Name $n -ErrorAction SilentlyContinue
                            if (-not $cur -or $cur.Status -notin @("Up","Disconnected")) { $allReady = $false; break }
                        }
                        if ($allReady) { break }
                        Start-Sleep -Milliseconds 500
                    }
                '
            },

            # --- C: ZAMANLAYICI (TIMER & BCDEDIT) ---
            # NOT (v1.2.9): "Dinamik Tık Kapat" + "Platform Tick Zorla" tweak'leri kaldirildi.
            # "Timer Resolution 0.5ms (Espor)" tweak'i ayni ayarlari iceriyor:
            #   - disabledynamictick yes (eski "Dinamik Tık Kapat")
            #   - useplatformtick deletevalue + useplatformclock deletevalue (Platform Tick Zorla'nin
            #     tersi — topluluk kaniti useplatformtick yes Sleep hassasiyetini bozar / input lag).
            # Boylece "HPET Kapat" tek timer tweak olarak kaldi (modern Ryzen/Core icin DPC fix).
            # NOT (v1.2.7): Group="TimerMode" kaldirildi — timer tweak'leri mutual exclusive yapan grup
            # davranisi vardi (birini secince digerleri kapaniyordu). Kullanici hepsini birden secebilir,
            # acikma kullanici karari (description'larda anti-cheat uyarisi var).
            @{
                Name="HPET (Platform Clock) Kapat";
                SubCategory="Zamanlayıcı (Timer)";
				Description="Windows'un HPET'i (eski platform saati) zorla kullanmasını sağlayan 'useplatformclock' önyükleme ayarını siler. Modern Ryzen / Core sistemlerde Windows zaten daha hızlı olan TSC saatini kullanır; HPET'in zorlanması zamanlama çağrılarını yavaşlatıp takılmaya yol açar.`n`n💡 Bu, Windows'un varsayılan durumudur — çoğu sistemde tweak zaten aktif görünür, yapılacak iş yoktur. Geri alma HPET'i zorla açmaz.`n📚 Kaynak: Blur Busters topluluk ölçümleri.";
                Command='bcdedit /deletevalue useplatformclock';
                UndoCommand='';
                RestartExplorer=$false
            },
            # NOT (v1.2.9): "Platform Tick Zorla" tweak'i kaldirildi — Topluluk kaniti
            # (Overclock.net + Blur Busters): useplatformtick yes input lag yaratir + Sleep
            # hassasiyetini bozar. Timer Resolution 0.5ms (Espor) tweak'i zaten useplatformtick
            # deletevalue cagirip default davranisa donduruyor. Bu tweak zararliydi, silindi.

            # --- v1.2.20 SPRINT: Modern repo arastirmasi sonucu eklenen 4 tweak ---
            # Kaynaklar: valleyofdoom/PC-Tuning, NicholasBly/Windows-11-Latency-Optimization,
            # theantipopau/windows11nontouchgamingoptimizer cross-referenced.

            # --- D: DEPOLAMA (SSD) ---
            @{
                Name="SSD Optimize (8.3 Filename + Last Access)"; Requires=@("SSD");
                SubCategory="Depolama (SSD)";
                Risk="Low"; RestartExplorer=$false;
                Description="SSD / NVMe için iki NTFS ayarı:`n• 8.3 kısa dosya adı oluşturmayı kapatır — her yeni dosyada ek kısa ad yazımı kalkar (modern uygulamalar kullanmaz)`n• Son erişim zamanı güncellemesini kapatır — her dosya okumada meta veri yazımı kalkar`n`n↩️ Geri alma iki ayarı da Windows varsayılanına döner.`n📚 Kaynak: Microsoft NTFS / fsutil belgeleri, valleyofdoom/PC-Tuning.";
                Command='
                    & fsutil 8dot3name set 1 2>$null | Out-Null
                    & fsutil behavior set disablelastaccess 1 2>$null | Out-Null
                ';
                UndoCommand='
                    # Windows varsayilanlari: 8dot3name=2 (birim bazli), disablelastaccess=2 (sistem yonetimli)
                    & fsutil 8dot3name set 2 2>$null | Out-Null
                    & fsutil behavior set disablelastaccess 2 2>$null | Out-Null
                    # eski surumun (v1.3.0 oncesi / "+ SysMain Disable") kapattigi SysMain varsa geri acilir
                    $sm = Get-Service SysMain -ErrorAction SilentlyContinue
                    if ($sm -and "$($sm.StartType)" -eq "Disabled") { try { Set-Service SysMain -StartupType Automatic -ErrorAction SilentlyContinue; Start-Service SysMain -ErrorAction SilentlyContinue } catch {} }
                ';
                DetectScript='
                    $fs = Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -ErrorAction SilentlyContinue
                    $dot3 = $fs.NtfsDisable8dot3NameCreation
                    $la = $fs.NtfsDisableLastAccessUpdate
                    return (("$dot3" -eq "1") -and ($null -ne $la) -and (([int64]$la -band 3) -eq 1))
                '
            },

            # --- E: USB / GIRDI LATENCY ---
            @{
                Name="USB Selective Suspend Devre Dışı";
                SubCategory="Giriş ve İşlemci";
                Risk="Low"; RestartExplorer=$false;
                Description="USB aygıtlarının güç tasarrufu için askıya alınmasını engeller. Fare, klavye, kumanda, 2.4 GHz kablosuz alıcılar, Bluetooth adaptörü ve USB ses kartları sürekli hazır kalır:`n• Boşta bekledikten sonra ilk harekette / tuşta uyanma gecikmesi ve takılma olmaz`n• Kablosuz kulaklık / fare alıcısı kopmaları ve Bluetooth ses kesilmeleri azalır`n• USB DAC / ses arayüzü cızırtıları azalır`n`nHer USB aygıtında Aygıt Yöneticisi > Güç Yönetimi > 'Güç tasarrufu için bilgisayar bu aygıtı kapatabilir' seçeneği de kapatılır (değiştirilenler kaydedilir, geri alma aynen geri açar).`n⚠️ Dizüstünde onay istenir ve yalnız priz (AC) ayarı değişir; masaüstünde priz + pil.`n📚 Kaynak: valleyofdoom/PC-Tuning, djdallmann/GamingPCSetup.";
                DetectScript='
                    # v1.3.0 (11. tur, birlestirme): tespit ETKIN guc planindaki USB askiya alma (AC) degerinden — eski XP anahtari tek basina
                    # yaniltiyordu (plan geri donmus olsa da yesil). Get-PowerSettingIndex sayisal okur: Turkce / Ingilizce / Fransizca ayni.
                    $v = Get-PowerSettingIndex "2a737441-1930-4402-8d77-b2bebba308a3" "48e6b7a6-50f5-4782-a5d4-53bb8f07e226"
                    return ($null -ne $v -and $v.AC -eq 0)
                ';
                Command='
                    if (-not (Confirm-LaptopPowerTweak "USB Selective Suspend")) { return }
                    # 1) HKLM USB global flag
                    if (-not (Test-Path "HKLM:\SYSTEM\CurrentControlSet\Services\USB")) {
                        New-Item -Path "HKLM:\SYSTEM\CurrentControlSet\Services\USB" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\USB" -Name "DisableSelectiveSuspend" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    # 2) Power scheme USB selective suspend: AC tum planlar. DC yalniz masaustu.
                    $subUsb = "2a737441-1930-4402-8d77-b2bebba308a3"
                    $usbSusp = "48e6b7a6-50f5-4782-a5d4-53bb8f07e226"
                    Backup-PowerSettingIndex "UsbSelectiveSuspend" $subUsb $usbSusp
                    & powercfg /attributes $subUsb $usbSusp -ATTRIB_HIDE 2>$null | Out-Null
                    $writeDc = $true
                    try { if (Test-IsLaptop) { $writeDc = $false } } catch {}
                    foreach ($line in @(& powercfg /list 2>$null)) {
                        if ("$line" -match "([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})") {
                            & powercfg -setacvalueindex $Matches[1] $subUsb $usbSusp 0 2>$null | Out-Null
                            if ($writeDc) { & powercfg -setdcvalueindex $Matches[1] $subUsb $usbSusp 0 2>$null | Out-Null }
                        }
                    }
                    & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null
                    # 3) v1.3.0: USB aygitlarinda "Guc tasarrufu icin bilgisayar bu aygiti kapatabilir" = KAPALI
                    #    (MSPower_DeviceEnable WMI sinifi — Aygit Yoneticisi Guc Yonetimi sekmesiyle ayni ayar).
                    #    Sadece AKTIF olanlar kapatilir ve listesi kaydedilir; Undo sadece bunlari geri acar.
                    $changed = New-Object System.Collections.Generic.List[string]
                    try {
                        Get-CimInstance -Namespace root\wmi -ClassName MSPower_DeviceEnable -ErrorAction Stop |
                            Where-Object { $_.InstanceName -like "USB\*" -and $_.Enable -eq $true } | ForEach-Object {
                                try { Set-CimInstance -InputObject $_ -Property @{ Enable = $false } -ErrorAction Stop; $changed.Add($_.InstanceName) } catch {}
                            }
                    } catch {}
                    if ($changed.Count -gt 0) {
                        $bk = "HKLM:\SOFTWARE\MrClean"
                        if (-not (Test-Path $bk)) { New-Item -Path $bk -Force | Out-Null }
                        $prev = @((Get-ItemProperty -Path $bk -Name "UsbPowerMgmtDisabled" -ErrorAction SilentlyContinue).UsbPowerMgmtDisabled)
                        $all = @($prev + $changed) | Where-Object { $_ } | Select-Object -Unique
                        Set-ItemProperty -Path $bk -Name "UsbPowerMgmtDisabled" -Value ([string[]]$all) -Type MultiString -Force
                    }
                    Write-Host "[USB] Selective suspend kapatildi; $($changed.Count) USB aygitinda guc yonetimi kapatildi."
                ';
                UndoCommand='
                    # v1.3.0: Apply in kapattigi aygitlarin guc yonetimini geri ac
                    $bk = "HKLM:\SOFTWARE\MrClean"
                    $list = @((Get-ItemProperty -Path $bk -Name "UsbPowerMgmtDisabled" -ErrorAction SilentlyContinue).UsbPowerMgmtDisabled) | Where-Object { $_ }
                    if ($list.Count -gt 0) {
                        try {
                            Get-CimInstance -Namespace root\wmi -ClassName MSPower_DeviceEnable -ErrorAction Stop |
                                Where-Object { $list -contains $_.InstanceName } | ForEach-Object {
                                    try { Set-CimInstance -InputObject $_ -Property @{ Enable = $true } -ErrorAction Stop } catch {}
                                }
                        } catch {}
                        Remove-ItemProperty -Path $bk -Name "UsbPowerMgmtDisabled" -Force -ErrorAction SilentlyContinue
                    }
                    Remove-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\USB" -Name "DisableSelectiveSuspend" -Force -ErrorAction SilentlyContinue
                    $subUsb = "2a737441-1930-4402-8d77-b2bebba308a3"
                    $usbSusp = "48e6b7a6-50f5-4782-a5d4-53bb8f07e226"
                    # v1.3.0 (4. tur): yedekten geri yukle (yoksa Windows varsayilani: Etkin / Etkin)
                    Restore-PowerSettingIndex "UsbSelectiveSuspend" $subUsb $usbSusp 1 1
                '
            },

            # --- F: CORE PARKING (CPU) ---
            @{
                Name="USB 3 Bağlantı Güç Yönetimini Kapat (U1/U2)";
                SubCategory="Giriş ve İşlemci"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; SkipRebootDialog=$true;
                Description="Etkin güç planında 'USB 3 Bağlantı Güç Yönetimi'ni prizdeyken KAPALI yapar: USB 3 bağlantıları boşta U1/U2 düşük güç durumuna geçmez. USB 3 hub'a / ön panele takılı ses kartı, kulaklık alıcısı, 4-8 kHz fare alıcısı ve webcam'lerde uyanma gecikmesi, mikro kopma ve cızırtıları azaltır.`n`nℹ️ 2.4 GHz alıcıların çoğu USB 2'dir — onlar için 'USB Selective Suspend Devre Dışı' tweak'i asıl çözümdür; bu tweak USB 3 yolunu tamamlar.`n✅ Güç planını değiştirmez (X3D için Dengeli plan korunur). Önceki değer yedeklenir. Pil (DC) ayarına dokunulmaz. Anında uygulanır.`n📚 Kaynak: kubsonxtm/Windows-Tweaks, tweaqas Stix güç planı; tenforums/guru3d güç ayarı belgeleri.";
                DetectScript='
                    $i = Get-PowerSettingIndex "2a737441-1930-4402-8d77-b2bebba308a3" "d4e98f31-5ffe-4ce1-be31-1b38b384c009"
                    return ($i -and $i.AC -eq 0)
                ';
                Command='
                    $sub = "2a737441-1930-4402-8d77-b2bebba308a3"; $set = "d4e98f31-5ffe-4ce1-be31-1b38b384c009"
                    & powercfg /attributes $sub $set -ATTRIB_HIDE 2>$null | Out-Null
                    Backup-PowerSettingIndex "Usb3Lpm" $sub $set
                    & powercfg -setacvalueindex SCHEME_CURRENT $sub $set 0 2>$null | Out-Null
                    & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null
                ';
                UndoCommand='
                    Restore-PowerSettingIndex "Usb3Lpm" "2a737441-1930-4402-8d77-b2bebba308a3" "d4e98f31-5ffe-4ce1-be31-1b38b384c009" -1 -1
                '
            },
            @{
                Name="Disklerin Kapanmasını Engelle (Prizde: Asla)"; Requires=@("HDD");
                SubCategory="Depolama (SSD)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Etkin güç planında 'Sabit diski şu süreden sonra kapat' ayarını prizdeyken ASLA yapar (Dengeli varsayılanı 20 dk). Oyun kütüphanesi mekanik diskte (HDD) olanlarda, diskin uykudan dönerken 1-3 saniye donması (oyun yüklerken, dosya açarken) biter. SSD/NVMe-only sistemlerde etkisi yoktur ama zararı da yoktur.`n`n✅ Güç planını değiştirmez. Önceki değer yedeklenir. Pil (DC) ayarına dokunulmaz.`n📚 Kaynak: kubsonxtm/Windows-Tweaks, tweaqas Stix güç planı.";
                DetectScript='
                    $i = Get-PowerSettingIndex "0012ee47-9041-4b5d-9b77-535fba8b1442" "6738e2c4-e8a5-4a42-b16a-e040e769756e"
                    return ($i -and $i.AC -eq 0)
                ';
                Command='
                    $sub = "0012ee47-9041-4b5d-9b77-535fba8b1442"; $set = "6738e2c4-e8a5-4a42-b16a-e040e769756e"
                    Backup-PowerSettingIndex "DiskIdle" $sub $set
                    & powercfg -setacvalueindex SCHEME_CURRENT $sub $set 0 2>$null | Out-Null
                    & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null
                ';
                UndoCommand='
                    Restore-PowerSettingIndex "DiskIdle" "0012ee47-9041-4b5d-9b77-535fba8b1442" "6738e2c4-e8a5-4a42-b16a-e040e769756e" 1200 600
                '
            },
            @{
                Name="NVMe / SATA Bağlantı Güç Tasarrufunu Kapat (Uzman, Prizde)";
                SubCategory="Depolama (SSD)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Prizdeyken depolama bağlantısının güç tasarrufunu kapatır: SATA bağlantı güç yönetimi (HIPM/DIPM) = Etkin, NVMe birincil boşta kalma zaman aşımı = 0 (APST'ye geçmez), NVMe NOPPME = Kapalı. Disk ilk erişimde uykudan uyanma gecikmesi yaşamaz.`n`nℹ️ Dürüst not: Kazanç tek seferlik küçük erişimlerde milisaniye düzeyindedir; FPS ölçümü yoktur. Uzman ayarıdır, profillere eklenmedi.`n⚠️ M.2 SSD boşta daha sıcak çalışır (soğutucusuz dizüstü/mini PC'de önerilmez; dizüstünde sorulur).`n✅ Önceki değerler yedeklenir, geri alma onlara döner. Pil (DC) ayarına dokunulmaz.`n📚 Kaynak: kubsonxtm/Windows-Tweaks güç planı, tweaqas Stix güç planı.";
                DetectScript='
                    $a = Get-PowerSettingIndex "0012ee47-9041-4b5d-9b77-535fba8b1442" "d639518a-e56d-4345-8af2-b9f32fb26109"
                    return ($a -and $a.AC -eq 0)
                ';
                Command='
                    if (-not (Confirm-LaptopPowerTweak "NVMe / SATA Baglanti Guc Tasarrufu Kapat")) { return }
                    $sub = "0012ee47-9041-4b5d-9b77-535fba8b1442"
                    $items = @(@("SataLpm","0b2d69d7-a2a1-449c-9680-f91c70521c60"), @("NvmeIdle","d639518a-e56d-4345-8af2-b9f32fb26109"), @("NvmeNoppme","fc7372b6-ab2d-43ee-8797-15e9841f2cca"))
                    foreach ($it in $items) {
                        & powercfg /attributes $sub $it[1] -ATTRIB_HIDE 2>$null | Out-Null
                        Backup-PowerSettingIndex $it[0] $sub $it[1]
                        & powercfg -setacvalueindex SCHEME_CURRENT $sub $it[1] 0 2>$null | Out-Null
                    }
                    & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null
                ';
                UndoCommand='
                    $sub = "0012ee47-9041-4b5d-9b77-535fba8b1442"
                    Restore-PowerSettingIndex "SataLpm" $sub "0b2d69d7-a2a1-449c-9680-f91c70521c60" -1 -1
                    Restore-PowerSettingIndex "NvmeIdle" $sub "d639518a-e56d-4345-8af2-b9f32fb26109" -1 -1
                    Restore-PowerSettingIndex "NvmeNoppme" $sub "fc7372b6-ab2d-43ee-8797-15e9841f2cca" -1 -1
                '
            },
            @{
                Name="CPU Core Parking Devre Dışı (Tüm Çekirdekler Aktif)";
                SubCategory="Giriş ve İşlemci";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows'un işlem yükü düşükken işlemci çekirdeklerini 'park etmesini' (uyutmasını) engeller; tüm çekirdekler sürekli hazır kalır:`n• Park'tan uyanma gecikmesi olmaz`n• Çok çekirdekli oyunlarda kare süresi daha tutarlı olur`n• Arka plan işleri çekirdeklere daha düzgün dağılır`n`n⚠️ Boşta tüketim biraz artar (masaüstünde 5-10 W); dizüstünde pil süresi kısalır, uygulamadan önce sorulur.`n⚠️ Çift CCD'li X3D (7900X3D / 7950X3D / 9900X3D / 9950X3D): kullanmayın — AMD'nin oyunda V-Cache olmayan CCD'yi park etme mekanizması buna dayanır, kapatınca FPS düşer. Bu işlemcilerde uygulamadan önce uyarı gösterilir. Tek CCD'li X3D'ler (5800X3D / 9800X3D / 9850X3D) güvenle kullanabilir.`n✅ Etkin güç planına uygulanır; önceki değer yedeklenir, geri alma ona döner.`n📚 Kaynak: valleyofdoom/PC-Tuning.";
                Command='
                    # v1.3.0: cift CCD X3D de core parking kapatmak V-Cache CCD park mekanizmasini bozar
                    if (-not (Confirm-DualCcdX3DPowerTweak "CPU Core Parking Devre Disi")) { return }
                    if (-not (Confirm-LaptopPowerTweak "CPU Core Parking Devre Disi")) { return }
                    # v1.3.0: Bazi tweak paketleri (kubsonxtm/Windows-Tweaks vb.) CPMINCORES ayarinin izin verilen ust sinirini
                    # (ValueMax) 0 yapar — o durumda asagidaki "100" degeri ARALIK DISI kalir ve powercfg sessizce reddeder.
                    $cpKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerSettings\54533251-82be-4824-96c1-47b60b740d00\0cc5b647-c1df-4637-891a-dec35c318583"
                    $vmax = (Get-ItemProperty -Path $cpKey -Name "ValueMax" -ErrorAction SilentlyContinue).ValueMax
                    if ($null -ne $vmax -and [int]$vmax -lt 100) { Set-ItemProperty -Path $cpKey -Name "ValueMax" -Value 100 -Type DWord -Force -ErrorAction SilentlyContinue }
                    # CPMINCORES guid: 0cc5b647-c1df-4637-891a-dec35c318583 (min unparked cores %)
                    # SubGroup PROCESSOR_SETTINGS: 54533251-82be-4824-96c1-47b60b740d00
                    # KRITIK: Windows defaultta bu attribute HIDDEN gelir, expose edilmeden
                    # setvalueindex sessiz fail eder. Once attribute goster, sonra value yaz.
                    $subPower = "54533251-82be-4824-96c1-47b60b740d00"
                    $cpmin = "0cc5b647-c1df-4637-891a-dec35c318583"
                    & powercfg /attributes $subPower $cpmin -ATTRIB_HIDE 2>$null | Out-Null
                    # v1.3.0 (4. tur): orijinal AC/DC degeri yedeklenir — geri alma plana gore dogru degere doner
                    # (eski undo her planda 5 yaziyordu; Yuksek/Nihai planda varsayilan 100, yani undo park etmeyi ACIYORDU)
                    Backup-PowerSettingIndex "CoreParkingMinCores" $subPower $cpmin
                    & powercfg -setacvalueindex SCHEME_CURRENT $subPower $cpmin 100 2>$null | Out-Null
                    & powercfg -setdcvalueindex SCHEME_CURRENT $subPower $cpmin 100 2>$null | Out-Null
                    & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null
                ';
                UndoCommand='
                    # v1.3.0 (4. tur): yedekten geri yukle; yedek yoksa Dengeli plan varsayilani (%5 AC / %5 DC)
                    $subPower = "54533251-82be-4824-96c1-47b60b740d00"
                    $cpmin = "0cc5b647-c1df-4637-891a-dec35c318583"
                    & powercfg /attributes $subPower $cpmin -ATTRIB_HIDE 2>$null | Out-Null
                    Restore-PowerSettingIndex "CoreParkingMinCores" $subPower $cpmin 5 5
                ';
                DetectScript='
                    # Attribute expose et (zaten exposeysa no-op), sonra query
                    & powercfg /attributes 54533251-82be-4824-96c1-47b60b740d00 0cc5b647-c1df-4637-891a-dec35c318583 -ATTRIB_HIDE 2>$null | Out-Null
                    # v1.3.0 (4. tur): dil bagimsiz okuma (eski regex sadece Ingilizce powercfg ciktisinda calisiyordu)
                    $idx = Get-PowerSettingIndex "54533251-82be-4824-96c1-47b60b740d00" "0cc5b647-c1df-4637-891a-dec35c318583"
                    return ($idx -and $idx.AC -ge 100)
                '
            },

            # --- v1.2.22 SPRINT: Hardware GPU Scheduling ---

            # --- H: GPU / DISPLAY ---
            @{
                Name="Algılanan Oyunlara Yüksek Performans GPU Ata";
                SubCategory="GPU / Display"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Kurulu oyunları launcher kütüphanelerinden (Steam, Epic, EA, Riot, Battle.net, Ubisoft, GOG) bulur ve her birinin exe'sine Ayarlar > Ekran > Grafik > 'GPU tercihi: Yüksek performans' atar (ekran görüntünüzdeki BF1 ayarının aynısı, toplu ve otomatik). Özellikle hem dahili (iGPU) hem harici ekran kartı olan sistemlerde oyunların yanlış GPU'da açılmasını önler.`n`n✅ Arka planda SÜREKLİ TARAMA YOK — CPU/FPS'e etkisi sıfır. Tarama sadece siz uyguladığınızda bir kez yapılır (oyun sayısına göre birkaç saniye).`n✅ Yeni oyun kurunca tweak 'pasif' görünür; tekrar uygulamak yalnızca yeni oyunları ekler.`n✅ Kendi seçtiğiniz GPU tercihleri ve diğer oyun ayarları (pencereli oyun iyileştirmeleri vb.) korunur. Geri alma sadece MrClean'in eklediklerini kaldırır.`nℹ️ Tek ekran kartlı sistemlerde zararsızdır, değişiklik yaratmaz. Launcher dışı (elle kopyalanmış) oyunlar için Ayarlar > Grafik'ten ekleyin.`n📚 Kaynak: Microsoft 'GPU tercihi' (UserGpuPreferences); NVIDIA App benzeri kütüphane okuma.";
                DetectScript='
                    $list = @((Get-ItemProperty -Path "HKCU:\Software\MrClean" -Name "GpuPrefAdded" -ErrorAction SilentlyContinue).GpuPrefAdded) | Where-Object { $_ }
                    if ($list.Count -eq 0) { return $false }
                    $cnt = (Get-ItemProperty -Path "HKCU:\Software\MrClean" -Name "GpuPrefGameCount" -ErrorAction SilentlyContinue).GpuPrefGameCount
                    return ([int]"0$cnt" -ge @(Get-AllDetectedGames).Count)
                ';
                Command='Set-MrCleanGameGpuPreference';
                UndoCommand='Remove-MrCleanGameGpuPreference'
            },
            @{
                Name="Pencereli Oyunlarda Değişken Yenileme Hızı (VRR) İyileştirmesi";
                SubCategory="GPU / Display"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Ayarlar > Ekran > Grafik > 'Değişken yenileme hızı' seçeneğini açar: kendi VRR desteği olmayan DirectX 11 oyunları da G-SYNC / FreeSync monitörde değişken yenileme hızıyla çalışır (tearing ve takılma azalır).`n`n⚠️ Çok az sayıda eski oyunda titreme yapabilir — görürseniz geri alın. VRR desteklemeyen monitörde etkisizdir.`n✅ Mevcut DirectX ayarlarınız (ör. 'Pencereli oyun optimizasyonu') korunur, sadece bu anahtar eklenir.`n📚 Kaynak: Microsoft destek sayfası; winscript (orada tüm dizeyi eziyordu — burada birleştirilir).";
                DetectScript='
                    $cur = "$((Get-ItemProperty -Path "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences" -Name "DirectXUserGlobalSettings" -ErrorAction SilentlyContinue).DirectXUserGlobalSettings)"
                    return ($cur -match "(^|;)\s*VRROptimizeEnable=1\s*(;|$)")
                ';
                Command='
                    $k = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
                    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
                    $cur = "$((Get-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -ErrorAction SilentlyContinue).DirectXUserGlobalSettings)"
                    $pairs = [ordered]@{}
                    foreach ($p in ($cur -split ";")) { if ($p -match "^\s*([^=]+)=(.*)$") { $pairs[$Matches[1].Trim()] = $Matches[2].Trim() } }
                    $pairs["VRROptimizeEnable"] = "1"
                    $new = (($pairs.Keys | ForEach-Object { "$_=$($pairs[$_])" }) -join ";") + ";"
                    Set-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -Value $new -Type String -Force
                ';
                UndoCommand='
                    $k = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
                    $cur = "$((Get-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -ErrorAction SilentlyContinue).DirectXUserGlobalSettings)"
                    $pairs = [ordered]@{}
                    foreach ($p in ($cur -split ";")) { if ($p -match "^\s*([^=]+)=(.*)$") { $pairs[$Matches[1].Trim()] = $Matches[2].Trim() } }
                    $pairs.Remove("VRROptimizeEnable")
                    if ($pairs.Count -gt 0) {
                        $new = (($pairs.Keys | ForEach-Object { "$_=$($pairs[$_])" }) -join ";") + ";"
                        Set-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -Value $new -Type String -Force
                    } else {
                        Remove-ItemProperty -Path $k -Name "DirectXUserGlobalSettings" -Force -ErrorAction SilentlyContinue
                    }
                '
            },
            @{
                Name="Hardware Accelerated GPU Scheduling Aç (HAGS)";
                SubCategory="GPU / Display";
                Risk="Low"; RestartExplorer=$false; RequiresReboot=$true;
                Description="Donanım Hızlandırmalı GPU Zamanlamasını (HAGS) açar — Ayarlar > Ekran > Grafik > Varsayılan grafik ayarları ile aynı. GPU iş kuyruğunun yönetimi işlemciden ekran kartının kendi zamanlayıcısına geçer; işlemci yükü ve kare kuyruğu gecikmesi azalır. NVIDIA DLSS Frame Generation (RTX 40 / 50) HAGS'ın açık olmasını ister.`n`n⚠️ Bazı sistemlerde takılma bildirilmiştir — sorun olursa geri alın. Yeniden başlatma gerekir.`n✅ NVIDIA RTX 20+, AMD RX 6000 / 7000 / 9000, Intel Arc için güncel sürücülerle önerilir; desteklemeyen eski kartlarda etkisizdir. Geri alma önceki değerinize döner.";
                # v1.3.0 (4. tur): Geri alma artik ORIJINAL degere doner (eski: her zaman 1 = KAPALI yaziyordu; yeni Win11
                # kurulumlarinda HAGS varsayilan acik oldugu icin geri alma onu kapatiyordu). Deger hic yoksa silinir.
                DetectScript='
                    $v = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" -Name "HwSchMode" -ErrorAction SilentlyContinue).HwSchMode
                    return ("$v" -eq "2")
                ';
                Command='
                    Backup-TweakRegValue "HwSchMode" "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" "HwSchMode"
                    Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" -Name "HwSchMode" -Value 2 -Type DWord -Force
                ';
                UndoCommand='
                    Restore-TweakRegValue "HwSchMode" "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" "HwSchMode"
                ' 
            },

            # --- G: AUDIO (MMCSS Pro Audio Task Boost) ---
            @{
                Name="MMCSS Pro Audio Task Priority Boost";
                SubCategory="Ses (Audio)";
                Risk="Low"; RestartExplorer=$false;
                Description="Multimedya Sınıf Zamanlayıcısı'nda (MMCSS) 'Pro Audio' görevinin önceliğini 1'den 2'ye yükseltir. Bu görevi Chromium tabanlı uygulamalar (Edge, Chrome, Discord gibi Electron uygulamaları) ve ASIO kullanan müzik yazılımları (Cubase, Ableton, FL Studio) kullanır: Discord sesinde, tarayıcıda müzik / videoda ve DAW'larda ses kesilmeleri azalır. Oyunların kendi ses motorları genelde bu görevi kullanmaz.`n`n✅ Yalnız öncelik değeri değişir; önceki değer kaydedilir, geri alma ona döner.`n📚 Kaynak: Microsoft MMCSS belgeleri, djdallmann ölçümleri.";
                # v1.3.0 (11. tur, birlestirme): sabit "Undo=1" yerine onceki deger saklanir ve AYNEN geri yazilir; zaten 2 ise hic yazilmaz
                DetectScript='
                    $v = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio" -Name "Priority" -ErrorAction SilentlyContinue).Priority
                    return ("$v" -eq "2")
                ';
                Command='
                    $path = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio"
                    $prev = (Get-ItemProperty -Path $path -Name "Priority" -ErrorAction SilentlyContinue).Priority
                    $mk = "HKCU:\Software\MrClean\AppliedMarkers"
                    if (-not (Test-Path $mk)) { New-Item -Path $mk -Force -ErrorAction SilentlyContinue | Out-Null }
                    if ("$prev" -eq "2") {
                        Remove-ItemProperty -Path $mk -Name "MmcssProAudioPrevious" -Force -ErrorAction SilentlyContinue
                        Write-Host "[MMCSS] Pro Audio zaten Priority=2 — yazilmadi."
                    } else {
                        $old = if ($null -eq $prev) { "ABSENT" } else { "$prev" }
                        Set-ItemProperty -Path $mk -Name "MmcssProAudioPrevious" -Value $old -Type String -Force
                        if (-not (Test-Path $path)) { New-Item -Path $path -Force -ErrorAction SilentlyContinue | Out-Null }
                        Set-ItemProperty -Path $path -Name "Priority" -Value 2 -Type DWord -Force
                        Write-Host "[MMCSS] Priority 2 yazildi (onceki=$old)."
                    }
                ';
                UndoCommand='
                    $mk = "HKCU:\Software\MrClean\AppliedMarkers"
                    $raw = [string](Get-ItemProperty -Path $mk -Name "MmcssProAudioPrevious" -ErrorAction SilentlyContinue).MmcssProAudioPrevious
                    $path = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio"
                    if (-not $raw) { Write-Host "[MMCSS] Geri alinacak kayit yok (deger zaten 2 idi, dokunulmadi)." }
                    elseif ($raw -eq "ABSENT") { Remove-ItemProperty -Path $path -Name "Priority" -Force -ErrorAction SilentlyContinue; Remove-ItemProperty -Path $mk -Name "MmcssProAudioPrevious" -Force -ErrorAction SilentlyContinue }
                    else { Set-ItemProperty -Path $path -Name "Priority" -Value ([int]$raw) -Type DWord -Force -ErrorAction SilentlyContinue; Remove-ItemProperty -Path $mk -Name "MmcssProAudioPrevious" -Force -ErrorAction SilentlyContinue; Write-Host "[MMCSS] Priority $raw geri yazildi." }
                '
            },

            @{
                Name="Ses Kartı Güç Tasarrufunu Kapat (Ses Başı Kesilmesi / Pıt Sesi)";
                SubCategory="Ses (Audio)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; RequiresReboot=$true;
                Description="HD Audio ses aygıtlarının (Realtek, NVIDIA / AMD HDMI sesi vb.) ~10 sn sessizlikten sonra güç tasarrufuna geçmesini kapatır. Bu uyku yüzünden yeni bir ses başladığında (şarkı değişimi, Discord bildirimi, oyunda ilk efekt) sesin ilk yarım saniyesi kesilir ya da hoparlörden 'pıt' sesi gelir — tweak bunu giderir.`n`n✅ Yalnız sürücüsü bu ayarı tanımlayan aygıtlar değişir; orijinal değerler yedeklenir, geri alma aynen geri yükler. USB / Bluetooth / kablosuz kulaklıklar etkilenmez (onlar için 'USB Selective Suspend Devre Dışı').`n⚠️ Yeniden başlatma (ya da ses aygıtını kapatıp açma) sonrası geçerli olur.`n📚 Kaynak: GTweak, HD Audio sürücü güç ayarları.";
                DetectScript='
                    $base = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e96c-e325-11ce-bfc1-08002be10318}"
                    $found = 0
                    foreach ($k in (Get-ChildItem -Path $base -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match "^\d{4}$" })) {
                        $ps = Join-Path $k.PSPath "PowerSettings"
                        $v = Get-ItemProperty -Path $ps -ErrorAction SilentlyContinue
                        if (-not $v -or $null -eq $v.IdlePowerState) { continue }
                        $found++
                        if ((@($v.IdlePowerState) -join ",") -ne "0,0,0,0" -or (@($v.ConservationIdleTime) -join ",") -ne "255,255,255,255") { return $false }
                    }
                    return $true
                ';
                Command='
                    $base = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e96c-e325-11ce-bfc1-08002be10318}"
                    $bkRoot = "HKLM:\SOFTWARE\MrClean\AudioPowerBackup"
                    $n = 0
                    foreach ($k in (Get-ChildItem -Path $base -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match "^\d{4}$" })) {
                        $ps = Join-Path $k.PSPath "PowerSettings"
                        $v = Get-ItemProperty -Path $ps -ErrorAction SilentlyContinue
                        if (-not $v -or $null -eq $v.IdlePowerState) { continue }
                        $bk = Join-Path $bkRoot $k.PSChildName
                        if (-not (Test-Path $bk)) {
                            New-Item -Path $bk -Force | Out-Null
                            foreach ($nm in @("ConservationIdleTime","IdlePowerState","PerformanceIdleTime")) {
                                if ($null -ne $v.$nm) { Set-ItemProperty -Path $bk -Name $nm -Value ([byte[]]$v.$nm) -Type Binary -Force }
                            }
                        }
                        Set-ItemProperty -Path $ps -Name "ConservationIdleTime" -Value ([byte[]](0xFF,0xFF,0xFF,0xFF)) -Type Binary -Force -ErrorAction SilentlyContinue
                        Set-ItemProperty -Path $ps -Name "PerformanceIdleTime"  -Value ([byte[]](0xFF,0xFF,0xFF,0xFF)) -Type Binary -Force -ErrorAction SilentlyContinue
                        Set-ItemProperty -Path $ps -Name "IdlePowerState"       -Value ([byte[]](0x00,0x00,0x00,0x00)) -Type Binary -Force -ErrorAction SilentlyContinue
                        $n++
                    }
                    Write-Host "[Audio] $n ses aygitinda guc tasarrufu kapatildi (yeniden baslatma sonrasi gecerli)."
                ';
                UndoCommand='
                    $base = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e96c-e325-11ce-bfc1-08002be10318}"
                    $bkRoot = "HKLM:\SOFTWARE\MrClean\AudioPowerBackup"
                    foreach ($k in (Get-ChildItem -Path $base -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match "^\d{4}$" })) {
                        $ps = Join-Path $k.PSPath "PowerSettings"
                        if (-not (Test-Path $ps)) { continue }
                        $bk = Join-Path $bkRoot $k.PSChildName
                        $b = Get-ItemProperty -Path $bk -ErrorAction SilentlyContinue
                        # Yedek yoksa HD Audio surucu varsayilanlari: 10 sn / D3 / 10 sn
                        $cons = if ($b -and $b.ConservationIdleTime) { [byte[]]$b.ConservationIdleTime } else { [byte[]](0x0A,0,0,0) }
                        $idle = if ($b -and $b.IdlePowerState)       { [byte[]]$b.IdlePowerState }       else { [byte[]](0x03,0,0,0) }
                        $perf = if ($b -and $b.PerformanceIdleTime)  { [byte[]]$b.PerformanceIdleTime }  else { [byte[]](0x0A,0,0,0) }
                        if ((Get-ItemProperty -Path $ps -ErrorAction SilentlyContinue).IdlePowerState -ne $null) {
                            Set-ItemProperty -Path $ps -Name "ConservationIdleTime" -Value $cons -Type Binary -Force -ErrorAction SilentlyContinue
                            Set-ItemProperty -Path $ps -Name "IdlePowerState"       -Value $idle -Type Binary -Force -ErrorAction SilentlyContinue
                            Set-ItemProperty -Path $ps -Name "PerformanceIdleTime"  -Value $perf -Type Binary -Force -ErrorAction SilentlyContinue
                        }
                    }
                    Remove-Item -Path $bkRoot -Recurse -Force -ErrorAction SilentlyContinue
                '
            },

            @{
                Name="Görüşmede Oyun/Müzik Sesini Kısmayı Kapat (Discord)";
                SubCategory="Ses (Audio)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false;
                Description="Windows, bir 'iletişim etkinliği' (Discord / Teams / TeamSpeak sesli görüşmesi) algılayınca diğer tüm sesleri varsayılan olarak %80 KISAR — oyun sesi ve Spotify aniden kısılır. Bu tweak 'Hiçbir şey yapma' seçeneğini ayarlar; görüşme sırasında oyun ve müzik sesi aynen kalır.`n`nSes Denetim Masası > İletişim sekmesi ile aynıdır (UserDuckingPreference: 0 kapat, 1 %80 kıs (varsayılan), 2 %50 kıs, 3 hiçbir şey yapma).`n📚 Kaynak: kubsonxtm/Windows-Tweaks (Registry.reg).";
                Key="HKCU:\Software\Microsoft\Multimedia\Audio"; ValueName="UserDuckingPreference"; Type="DWord"; Data=3; Undo="DELETE_VALUE"
            }
        )
		# --- 11. (eski "🌐 Bufferbloat ve Ağ Profilleri") ---
		# v1.3.0 (12. tur): kategori kaldirildi. "[PROFİL] Düşük Gecikme + Tam Hız (Üniversal)" EMEKLİ — icerigi ya Windows
		# varsayilani ya da ayri tweak (RSC); LSO kapatma olculdu, fark 0 (DEGISIKLIKLER 21.1). "[SIFIRLA] Windows Varsayılanları"
		# RSC ile ayni alt klasore ("Ağ ve Ping", Low Latency) tasindi — Group radyo davranisi sadece kardes ogeler arasinda calisir.

		# --- 12. GPU AYARLARI (MANUEL) ---
		# Vendor-spesifik tweak'ler. Recommended Profiles'a DAHIL DEGIL — kullanici kendi GPU'suna
		# gore manuel secer. Vendor="NVIDIA"|"AMD" tag'i ile Apply-System-Tweaks uyumsuzluk uyarisi verir.
		"🎮 GPU Ayarları (Manuel)" = @(

			@{
				Name="AMD Adrenalin Optimizasyonu (Reklam/Popup/Bildirim Kapat)";
				SubCategory="AMD";
				Vendor="AMD";
				Risk="Low";
				RestartExplorer=$false;
				Description="AMD Software: Adrenalin Edition'ın reklamlarını, otomatik güncellemesini, sistem tepsisi menüsünü, oyun içi katmanını, hata bildirim aracını ve bildirimlerini kapatır. Grafik profili 'Özel' yapılır (Standart / Esports / Oyun ön ayarı seçimi kalkar), doku filtreleme kalitesi 'Performans'.`n`n✅ V-Sync, FreeSync ve mozaikleme ayarlarınıza dokunulmaz; sürücü Anti-Lag'ine dokunulmaz.`n🎮 Destekleyen oyunlarda (CS2, Warzone) oyun içi 'AMD Anti-Lag 2'yi açın; rekabetçi oyunlarda Radeon Chill ve Boost'u kapalı tutun.`n⚠️ Ayarların kaydedilmesi için Adrenalin 30 sn açılıp kapatılır. Yalnız AMD ekran kartı + Adrenalin kurulu sistemlerde anlamlıdır.";
				DetectScript='
					# AutoUpdate=0 ana marker + v1.3.0 isareti (v1.2.x ile uygulayanlar PASIF gorur → yeniden uygulayinca
					# eski V-Sync/Tessellation zorlamasi varsayilana cevrilir)
					$v = (Get-ItemProperty -Path "HKCU:\Software\AMD\CN" -Name "AutoUpdate" -ErrorAction SilentlyContinue).AutoUpdate
					$m = (Get-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "AmdProfileVer" -ErrorAction SilentlyContinue).AmdProfileVer
					return ("$v" -eq "0" -and [int]"0$m" -ge 130)
				';
				Command='
					$rsoft = "$env:SystemDrive\Program Files\AMD\CNext\CNext\RadeonSoftware.exe"
					if (Test-Path $rsoft) {
						Write-Host "[AMD] Adrenalin baslatiliyor (ayarlarin commit olmasi icin 30 sn bekleniyor)..."
						Start-Process $rsoft -ErrorAction SilentlyContinue
						Start-Sleep -Seconds 30
						Stop-Process -Name "RadeonSoftware" -Force -ErrorAction SilentlyContinue
						Start-Sleep -Seconds 2
					} else {
						Write-Host "[AMD] Adrenalin bulunamadi — registry tweakleri yine de uygulaniyor (yazilim yuklendiginde aktif olur)."
					}

					# --- SISTEM ---
					reg add "HKCU\Software\AMD\CN"  /v "AutoUpdate"     /t REG_DWORD /d "0" /f | Out-Null
					reg add "HKCU\Software\AMD\AIM" /v "LaunchBugTool"  /t REG_DWORD /d "0" /f | Out-Null

					# --- HOTKEYS ---
					reg add "HKCU\Software\AMD\DVR" /v "HotkeysDisabled" /t REG_DWORD /d "1" /f | Out-Null

					# --- TERCIHLER ---
					reg add "HKCU\Software\AMD\CN"  /v "SystemTray"               /t REG_SZ /d "false" /f | Out-Null
					reg add "HKCU\Software\AMD\DVR" /v "ShowRSOverlay"            /t REG_SZ /d "false" /f | Out-Null
					reg add "HKCU\Software\AMD\CN"  /v "RSXBrowserUnavailable"    /t REG_SZ /d "true"  /f | Out-Null
					reg add "HKCU\Software\AMD\CN"  /v "AllowWebContent"          /t REG_SZ /d "false" /f | Out-Null
					reg add "HKCU\Software\AMD\CN"  /v "CN_Hide_Toast_Notification" /t REG_SZ /d "true" /f | Out-Null
					reg add "HKCU\Software\AMD\CN"  /v "AnimationEffect"          /t REG_SZ /d "false" /f | Out-Null

					# --- GRAFIK PROFILI: Custom ---
					reg add "HKCU\Software\AMD\CN"  /v "WizardProfile"            /t REG_SZ /d "PROFILE_CUSTOM" /f | Out-Null

					# --- DISPLAY OVERRIDE EULA ---
					reg add "HKCU\Software\AMD\CN\CustomResolutions" /v "EulaAccepted" /t REG_SZ /d "true" /f | Out-Null
					reg add "HKCU\Software\AMD\CN\DisplayOverride"   /v "EulaAccepted" /t REG_SZ /d "true" /f | Out-Null

					# --- BILDIRIM SPAM KAPAT ---
					reg delete "HKCU\Software\AMD\CN\Notification" /f 2>$null | Out-Null
					reg add    "HKCU\Software\AMD\CN\Notification"            /f | Out-Null
					reg add    "HKCU\Software\AMD\CN\FreeSync"                /v "AlreadyNotified" /t REG_DWORD /d "1" /f | Out-Null
					reg add    "HKCU\Software\AMD\CN\OverlayNotification"     /v "AlreadyNotified" /t REG_DWORD /d "1" /f | Out-Null
					reg add    "HKCU\Software\AMD\CN\VirtualSuperResolution"  /v "AlreadyNotified" /t REG_DWORD /d "1" /f | Out-Null

					# --- HKLM Class GUID DISPLAY: VSync, TFQ, Tessellation, Vari-Bright, Tuning ---
					# FR33THY birebir: ControlSet001 (orig satir 63)
					$basePath = "HKLM:\System\ControlSet001\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"

					# UMD subkeyleri: TFQ (Doku Filtreleme Kalitesi) = Performans
					# v1.3.0: VSyncControl=Always Off ve Tessellation=Override/Kapali KALDIRILDI.
					#   - V-Sync: FreeSync + surucu V-Sync + FPS limiti (tearing olmayan onerilen kurulum) bozuluyordu.
					#   - Tessellation: AMD ve guncel rehberler "AMD Optimized" (varsayilan) onerir; zorla kapatmak
					#     BF4/BF1 gibi DX11 oyunlarda zemin/su detaylarini bozabiliyor, RX 9000 da FPS kazanci yok.
					#   - Gecis: v1.2.x nin yazdigi degerler AYNEN duruyorsa varsayilana cevrilir (kullanicinin kendi
					#     Adrenalin secimine dokunulmaz).
					$umdKeys = Get-ChildItem -Path $basePath -Recurse -ErrorAction SilentlyContinue |
						Where-Object { $_.PSChildName -eq "UMD" }
					foreach ($k in $umdKeys) {
						$p = $k.PSPath
						New-ItemProperty -Path $p -Name "TFQ"                 -Value ([byte[]](0x32,0x00))                  -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
						$cur = Get-ItemProperty -Path $p -ErrorAction SilentlyContinue
						if ($cur.VSyncControl -and (($cur.VSyncControl) -join ",") -eq "48,0") {
							New-ItemProperty -Path $p -Name "VSyncControl" -Value ([byte[]](0x31,0x00,0x00,0x00)) -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
						}
						if ($cur.Tessellation_OPTION -and (($cur.Tessellation_OPTION) -join ",") -eq "50,0") {
							New-ItemProperty -Path $p -Name "Tessellation"        -Value ([byte[]](0x36,0x00,0x34,0x00,0x00,0x00)) -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
							New-ItemProperty -Path $p -Name "Tessellation_OPTION" -Value ([byte[]](0x30,0x00,0x00,0x00))           -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
						}
					}
					if (-not (Test-Path "HKCU:\Software\MrClean\AppliedMarkers")) { New-Item -Path "HKCU:\Software\MrClean\AppliedMarkers" -Force | Out-Null }
					Set-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "AmdProfileVer" -Value 130 -Type DWord -Force

					# power_v1 (Vari-Bright kapat)
					$pwrKeys = Get-ChildItem -Path $basePath -Recurse -ErrorAction SilentlyContinue |
						Where-Object { $_.PSChildName -eq "power_v1" }
					foreach ($k in $pwrKeys) {
						New-ItemProperty -Path $k.PSPath -Name "abmlevel" -Value ([byte[]](0x00,0x00,0x00,0x00)) -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
					}

					# Adapter klasorleri (4 haneli) — Manual Tuning + GPU/Fan/VRAM/Power kontrol
					$adapterKeys = Get-ChildItem -Path $basePath -ErrorAction SilentlyContinue |
						Where-Object { $_.PSChildName -match "^\d{4}$" }
					foreach ($k in $adapterKeys) {
						New-ItemProperty -Path $k.PSPath -Name "IsAutoDefault"     -Value ([byte[]](0x00,0x00,0x00,0x00)) -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
						New-ItemProperty -Path $k.PSPath -Name "IsComponentControl" -Value ([byte[]](0x0F,0x00,0x00,0x00)) -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
					}
				';
				UndoCommand='
					# Adrenalin acmaya gerek yok — registry silindiginde Adrenalin bir sonraki acilista default e doner
					# --- SISTEM ---
					reg delete "HKCU\Software\AMD\CN"  /v "AutoUpdate"    /f 2>$null | Out-Null
					Remove-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "AmdProfileVer" -Force -ErrorAction SilentlyContinue
					reg add    "HKCU\Software\AMD\AIM" /v "LaunchBugTool" /t REG_DWORD /d "1" /f | Out-Null

					# --- HOTKEYS / PREFS ---
					reg delete "HKCU\Software\AMD\DVR" /v "HotkeysDisabled"             /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN"  /v "SystemTray"                  /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\DVR" /v "ShowRSOverlay"               /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN"  /v "RSXBrowserUnavailable"       /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN"  /v "AllowWebContent"             /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN"  /v "CN_Hide_Toast_Notification"  /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN"  /v "AnimationEffect"             /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN"  /v "WizardProfile"               /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN\CustomResolutions"                 /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN\DisplayOverride"                   /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN\Notification"                      /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN\FreeSync"                          /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN\OverlayNotification"               /f 2>$null | Out-Null
					reg delete "HKCU\Software\AMD\CN\VirtualSuperResolution"            /f 2>$null | Out-Null

					# --- HKLM Class GUID Undo (FR33THY birebir: belirli default degerleri yaz, silme) ---
					$basePath = "HKLM:\System\ControlSet001\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"

					# UMD subkeyleri:
					#   VSyncControl       -> REG_BINARY 31000000 (Application Default — orig satir 187)
					#   TFQ                -> SIL (orig satir 196)
					#   Tessellation       -> REG_BINARY 360034000000 (orig satir 206 — 6 byte)
					#   Tessellation_OPTION -> REG_BINARY 30000000 (orig satir 207)
					$umdKeys = Get-ChildItem -Path $basePath -Recurse -ErrorAction SilentlyContinue |
						Where-Object { $_.PSChildName -eq "UMD" }
					foreach ($k in $umdKeys) {
						$p = $k.PSPath
						New-ItemProperty -Path $p -Name "VSyncControl"        -Value ([byte[]](0x31,0x00,0x00,0x00))                  -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
						Remove-ItemProperty -Path $p -Name "TFQ" -Force -ErrorAction SilentlyContinue
						New-ItemProperty -Path $p -Name "Tessellation"        -Value ([byte[]](0x36,0x00,0x34,0x00,0x00,0x00))        -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
						New-ItemProperty -Path $p -Name "Tessellation_OPTION" -Value ([byte[]](0x30,0x00,0x00,0x00))                  -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
					}

					# power_v1\abmlevel -> SIL (orig satir 223)
					$pwrKeys = Get-ChildItem -Path $basePath -Recurse -ErrorAction SilentlyContinue |
						Where-Object { $_.PSChildName -eq "power_v1" }
					foreach ($k in $pwrKeys) {
						Remove-ItemProperty -Path $k.PSPath -Name "abmlevel" -Force -ErrorAction SilentlyContinue
					}

					# Adapter (4 hane):
					#   IsAutoDefault      -> REG_DWORD 1     (orig satir 234 — DIKKAT: REG_DWORD, REG_BINARY degil)
					#   IsComponentControl -> REG_BINARY 00000000 (orig satir 247)
					$adapterKeys = Get-ChildItem -Path $basePath -ErrorAction SilentlyContinue |
						Where-Object { $_.PSChildName -match "^\d{4}$" }
					foreach ($k in $adapterKeys) {
						$p = $k.PSPath
						# Once eski tip varsa sil ki tip cakismasin (REG_BINARY -> REG_DWORD gecisi icin)
						Remove-ItemProperty -Path $p -Name "IsAutoDefault" -Force -ErrorAction SilentlyContinue
						New-ItemProperty -Path $p -Name "IsAutoDefault"      -Value 1                                       -PropertyType DWord  -Force -ErrorAction SilentlyContinue | Out-Null
						New-ItemProperty -Path $p -Name "IsComponentControl" -Value ([byte[]](0x00,0x00,0x00,0x00))         -PropertyType Binary -Force -ErrorAction SilentlyContinue | Out-Null
					}
				'
			},

			@{
				Name="NVIDIA Optimizasyonu (Kontrol Paneli + Registry)";
				SubCategory="NVIDIA";
				Vendor="NVIDIA";
				Risk="Medium";
				RestartExplorer=$false;
				Description="NVIDIA sürücü ayarlarını tek tıkla düzenler:`n• Kayıt defteri: PhysX GPU'da, geliştirici araçları açık, tepsi simgesi kapalı, eski keskinleştirme açık`n• NVIDIA Profile Inspector ile (resmi sürüm otomatik indirilir, ~1 MB): Ultra Düşük Gecikme, doku filtreleme kalitesi, güç yönetimi = maksimum performans, CUDA P2 durumu, gölgelendirici önbelleği = sınırsız (derleme takılmalarını azaltır)`n`n✅ G-SYNC, V-Sync, anizotropik filtreleme ve MSAA'ya dokunulmaz — oyunun ve sizin tercihiniz geçerli. Threaded Optimization sürücü varsayılanında kalır.`n🎮 Reflex'li oyunlarda (CS2, BF6, Warzone) oyun içi Reflex 'Açık + Boost' kullanın; Reflex'siz oyunlarda Ultra Düşük Gecikme devreye girer.`n⚠️ Uygulamadan önce global profil sürücü varsayılanına sıfırlanır; mevcut profiliniz otomatik yedeklenir (nvidia_profile_backup.nip) ve geri alma onu geri yükler.`nℹ️ NVIDIA Kontrol Paneli yerine artık NVIDIA App > Grafik bölümünden görebilirsiniz; ayarlar aynı sürücü profiline yazılır. Inspector indirilemezse yalnız kayıt defteri ayarları uygulanır.";
				DetectScript='
					# StartOnLogin=0 (registry bolumu) + v1.3.0 profil isareti (Inspector profili guncel surumle uygulandi).
					# v1.2.x ile uygulayanlarda isaret yok → PASIF gorunur → yeniden uygulayinca G-SYNC/AF/MSAA duzelir.
					$v = (Get-ItemProperty -Path "HKCU:\Software\NVIDIA Corporation\NvTray" -Name "StartOnLogin" -ErrorAction SilentlyContinue).StartOnLogin
					$m = (Get-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "NvidiaProfileVer" -ErrorAction SilentlyContinue).NvidiaProfileVer
					return ("$v" -eq "0" -and [int]"0$m" -ge 130)
				';
				Command='
					# === BOLUM 1: REGISTRY ===
					Write-Host "[NVIDIA] Registry tweakleri uygulaniyor..."

					# Drs (Driver settings) klasorunu unblock et — MoTW olabilir
					$drsPath = "$env:ProgramData\NVIDIA Corporation\Drs"
					if (Test-Path $drsPath) {
						Get-ChildItem -Path $drsPath -Recurse -ErrorAction SilentlyContinue | Unblock-File -ErrorAction SilentlyContinue
					}

					# PhysX -> GPU (FR33THY birebir: ControlSet001)
					reg add "HKLM\System\ControlSet001\Services\nvlddmkm\Parameters\Global\NVTweak" /v "NvCplPhysxAuto" /t REG_DWORD /d "0" /f | Out-Null
					# Developer Tools acik (ControlSet001)
					reg add "HKLM\System\ControlSet001\Services\nvlddmkm\Parameters\Global\NVTweak" /v "NvDevToolsVisible" /t REG_DWORD /d "1" /f | Out-Null

					# v1.3.0: "GPU Performance Counter erisimi tum kullanicilara" (RmProfilingAdminOnly=0) KALDIRILDI.
					# Performansa etkisi yok; NVIDIA CVE-2018-6260 sonrasi bu erisimi yoneticiye kisitlamisti.
					# Undo tarafindaki silme komutlari korundu — eski surumde uygulayanlarin degeri temizlenir.

					# Tray icon kapat
					reg add "HKCU\Software\NVIDIA Corporation\NvTray" /v "StartOnLogin" /t REG_DWORD /d "0" /f | Out-Null

					# Legacy Sharpen aktif et (GR535=0) — FR33THY birebir 3 yola yazar (belt-and-suspenders)
					reg add "HKLM\SYSTEM\CurrentControlSet\Services\nvlddmkm\FTS"             /v "EnableGR535" /t REG_DWORD /d "0" /f | Out-Null
					reg add "HKLM\SYSTEM\ControlSet001\Services\nvlddmkm\Parameters\FTS"      /v "EnableGR535" /t REG_DWORD /d "0" /f | Out-Null
					reg add "HKLM\SYSTEM\CurrentControlSet\Services\nvlddmkm\Parameters\FTS" /v "EnableGR535" /t REG_DWORD /d "0" /f | Out-Null

					Write-Host "[NVIDIA] Registry OK."

					# === BOLUM 2: NVIDIA INSPECTOR ===
					$insp = Get-NvidiaInspectorPath
					if (-not $insp) {
						Write-Host "[NVIDIA] Inspector indirilemedi — registry tamamlandi, profil ayarlari atlandi."
						Write-Host "[NVIDIA] Eksik kalan: Ultra Low Latency, Shader Cache, Texture Filtering optimize. Internet kontrol edip tekrar deneyin."
						return
					}

					# 2a. Yedek: ilk uygulamadaki ORIJINAL ozellestirilmis profiller (tekrar uygulamada ezilmez)
					#     v1.3.0: dogru CLI (-exportCustomized) + zaman asimi korumasi. Eski "-export" hic calismiyordu.
					$backupNip = Join-Path $AppDataPath "nvidia_profile_backup.nip"
					if (-not (Test-Path $backupNip)) {
						Write-Host "[NVIDIA] Mevcut ozel profiller yedekleniyor..."
						if (Backup-NvidiaProfiles -Exe $insp -TargetNip $backupNip) {
							Write-Host "[NVIDIA] Yedek OK ($([Math]::Round((Get-Item $backupNip).Length / 1KB, 1)) KB)."
						} else {
							Write-Host "[NVIDIA] Yedeklenecek ozel profil yok veya yedek alinamadi — Undo surucu varsayilanlarina doner."
						}
					}

					# 2b. Optimize .nip import: -silentImport = REPLACE modu (NPI v3 kaynak kodu): Base Profile once
					#     surucu varsayilanina SIFIRLANIR, sonra sadece bu dosyadaki ayarlar yazilir. Bu sayede v1.2.x
					#     profilinin kapattigi G-SYNC / AF / MSAA gibi ayarlar da kendiliginden varsayilana doner.
					$tmpNip = Join-Path $env:TEMP "mrclean_nv_optimized.nip"
					$ok = $false
					try {
						Set-Content -Path $tmpNip -Value $global:NvidiaInspectorOptimizedNip -Encoding Unicode -Force
						Write-Host "[NVIDIA] Optimize profil import ediliyor..."
						$ok = Invoke-NvidiaInspector -Exe $insp -Arguments "-silentImport `"$tmpNip`"" -TimeoutSec 60
						if ($ok) {
							$bad = Test-NvidiaProfileApplied -Exe $insp -ExpectedNip $global:NvidiaInspectorOptimizedNip
							if ($null -eq $bad) { Write-Host "[NVIDIA] Inspector profili uygulandi (dogrulama yapilamadi)." }
							elseif ($bad.Count -eq 0) { Write-Host "[NVIDIA] Inspector profili uygulandi ve dogrulandi." }
							else { Write-Host "[NVIDIA] UYARI: Surucude farkli kalan ayarlar: $($bad -join ", ")" }
						} else { Write-Host "[NVIDIA] Import basarisiz veya zaman asimi." }
					} catch {
						Write-Host "[NVIDIA] Import hatasi: $($_.Exception.Message)"
					} finally {
						Remove-Item $tmpNip -Force -ErrorAction SilentlyContinue
					}
					# v1.3.0 profil isareti — DetectScript bunu arar; v1.2.x profili olanlar tweaki PASIF gorur ve yeniden uygular
					if ($ok) {
						if (-not (Test-Path "HKCU:\Software\MrClean\AppliedMarkers")) { New-Item -Path "HKCU:\Software\MrClean\AppliedMarkers" -Force | Out-Null }
						Set-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "NvidiaProfileVer" -Value 130 -Type DWord -Force
					}

					# 2c. Gorsel dogrulama: NVIDIA App (NVCP Mayis 2026 da emekliye ayrildi), yoksa klasik Kontrol Paneli
					Open-NvidiaSettingsApp
				';
				UndoCommand='
					Write-Host "[NVIDIA] Geri alma basliyor..."

					# === BOLUM 1: REGISTRY GERI AL ===
					reg delete "HKLM\System\ControlSet001\Services\nvlddmkm\Parameters\Global\NVTweak" /v "NvCplPhysxAuto"      /f 2>$null | Out-Null
					reg delete "HKLM\System\ControlSet001\Services\nvlddmkm\Parameters\Global\NVTweak" /v "NvDevToolsVisible"   /f 2>$null | Out-Null
					reg delete "HKLM\System\ControlSet001\Services\nvlddmkm\Parameters\Global\NVTweak" /v "RmProfilingAdminOnly" /f 2>$null | Out-Null

					$cls = "Registry::HKLM\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
					Get-ChildItem -Path $cls -Force -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -notmatch "Configuration" } | ForEach-Object {
						reg delete "$($_.Name)" /v "RmProfilingAdminOnly" /f 2>$null | Out-Null
					}

					reg delete "HKCU\Software\NVIDIA Corporation\NvTray" /f 2>$null | Out-Null

					reg add "HKLM\SYSTEM\CurrentControlSet\Services\nvlddmkm\FTS"             /v "EnableGR535" /t REG_DWORD /d "1" /f | Out-Null
					reg add "HKLM\SYSTEM\ControlSet001\Services\nvlddmkm\Parameters\FTS"      /v "EnableGR535" /t REG_DWORD /d "1" /f | Out-Null
					reg add "HKLM\SYSTEM\CurrentControlSet\Services\nvlddmkm\Parameters\FTS" /v "EnableGR535" /t REG_DWORD /d "1" /f | Out-Null

					Write-Host "[NVIDIA] Registry geri alindi."

					# === BOLUM 2: INSPECTOR — backup varsa onu yukle, yoksa bos profil ===
					$insp = Get-NvidiaInspectorPath
					if (-not $insp) {
						Write-Host "[NVIDIA] Inspector erisilemedi — profil geri alinamadi. Manuel olarak NVIDIA Control Panel ayarlarini kontrol edin."
						return
					}

					# v1.3.0: 1) Base Profile bos NIP ile (REPLACE) surucu varsayilanina sifirlanir — yedekte Base Profile
					#            olmasa bile bizim yazdigimiz global ayarlar temizlenir.
					#         2) Yedek varsa (ilk Apply oncesi ozel profiller) REPLACE ile aynen geri yuklenir, sonra silinir
					#            (bir sonraki Apply guncel durumu yeniden yedekler).
					$tmpEmpty = Join-Path $env:TEMP "mrclean_nv_empty.nip"
					try {
						Set-Content -Path $tmpEmpty -Value $global:NvidiaInspectorEmptyNip -Encoding Unicode -Force
						if (Invoke-NvidiaInspector -Exe $insp -Arguments "-silentImport `"$tmpEmpty`"" -TimeoutSec 60) {
							Write-Host "[NVIDIA] Base Profile surucu varsayilanina sifirlandi."
						}
					} finally {
						Remove-Item $tmpEmpty -Force -ErrorAction SilentlyContinue
					}
					$backupNip = Join-Path $AppDataPath "nvidia_profile_backup.nip"
					if (Test-Path $backupNip) {
						Write-Host "[NVIDIA] Yedek profiller geri yukleniyor: $backupNip"
						if (Invoke-NvidiaInspector -Exe $insp -Arguments "-silentImport `"$backupNip`"" -TimeoutSec 60) {
							Write-Host "[NVIDIA] Ozel profilleriniz geri yuklendi."
							Remove-Item $backupNip -Force -ErrorAction SilentlyContinue
						} else {
							Write-Host "[NVIDIA] Yedek geri yuklenemedi — dosya korunuyor: $backupNip"
						}
					}
					Remove-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "NvidiaProfileVer" -Force -ErrorAction SilentlyContinue

					Open-NvidiaSettingsApp
				'
			},

			@{
				Name="NVIDIA Telemetri Kapat";
				SubCategory="NVIDIA"; Vendor="NVIDIA"; Since="2.0.0";
				Risk="Low"; RestartExplorer=$false;
				Description="NVIDIA sürücüsünün ve Kontrol Paneli'nin kullanım verisi (telemetri) göndermesini kapatır: Kontrol Paneli 'veri paylaşımı' tercihi = Hayır, sürücü başlangıç telemetrisi = Kapalı.`n`nℹ️ Performansa etkisi yok denecek kadar azdır; gizlilik ayarıdır. NVIDIA App / GeForce Experience özellikleri (ShadowPlay, sürücü güncelleme, Reflex, DLSS) etkilenmez.`n📚 Kaynak: tweaqas paketi (Remove Telemetry.bat).";
				Batch=@(
					@{ Key="HKLM:\SOFTWARE\NVIDIA Corporation\NvControlPanel2\Client"; ValueName="OptInOrOutPreference"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
					@{ Key="HKLM:\SYSTEM\CurrentControlSet\Services\nvlddmkm\Global\Startup"; ValueName="SendTelemetryData"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
					# v1.3.0: winscript (Basic preset) ve Chris Titus winutil ile ayni FTS telemetri bayraklari
					@{ Key="HKLM:\SOFTWARE\NVIDIA Corporation\Global\FTS"; ValueName="EnableRID44231"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
					@{ Key="HKLM:\SOFTWARE\NVIDIA Corporation\Global\FTS"; ValueName="EnableRID64640"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
					@{ Key="HKLM:\SOFTWARE\NVIDIA Corporation\Global\FTS"; ValueName="EnableRID66610"; Type="DWord"; Data=0; Undo="DELETE_VALUE" },
					# v1.3.0 (4. tur): eski surucu telemetri servisi ve gorevleri (varsa) — optimizer, optimizerNXT, GTweak
					@{
						Command='
							$s = Get-Service -Name "NvTelemetryContainer" -ErrorAction SilentlyContinue
							if ($s) { try { Stop-Service -Name "NvTelemetryContainer" -Force -ErrorAction SilentlyContinue } catch {}; Set-Service -Name "NvTelemetryContainer" -StartupType Disabled -ErrorAction SilentlyContinue }
							Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskName -like "NvTmRep*" -or $_.TaskName -like "NvTmMon*" } | Disable-ScheduledTask -ErrorAction SilentlyContinue | Out-Null
						';
						UndoCommand='
							if (Get-Service -Name "NvTelemetryContainer" -ErrorAction SilentlyContinue) { Set-Service -Name "NvTelemetryContainer" -StartupType Automatic -ErrorAction SilentlyContinue }
							Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskName -like "NvTmRep*" -or $_.TaskName -like "NvTmMon*" } | Enable-ScheduledTask -ErrorAction SilentlyContinue | Out-Null
						'
					}
				);
				DetectScript='
					$v = (Get-ItemProperty -Path "HKLM:\SOFTWARE\NVIDIA Corporation\NvControlPanel2\Client" -Name "OptInOrOutPreference" -ErrorAction SilentlyContinue).OptInOrOutPreference
					$f = (Get-ItemProperty -Path "HKLM:\SOFTWARE\NVIDIA Corporation\Global\FTS" -Name "EnableRID66610" -ErrorAction SilentlyContinue).EnableRID66610
					return ("$v" -eq "0" -and "$f" -eq "0")
				' 
			}
		)
    }
}

