Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Xaml,System.Windows.Forms

# --- XAML (MAIN WINDOW) ---
$xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="MrClean Sistem Bakım Aracı v$($global:AppVersion)" Height="950" Width="1280" MinWidth="1100" MinHeight="680"
        Background="#0F1115" WindowStartupLocation="CenterScreen" WindowState="Maximized"
        FontFamily="{DynamicResource UiFont}" FontSize="13" UseLayoutRounding="True">
  
  <Window.Resources>
    <!-- v1.3.0 (§60): arayüz yazı tipi. Varsayılan Segoe UI Variable; Set-UiFont açılışta gömülü Inter'i bağlar (bulunamazsa bu değerler kalır). -->
    <FontFamily x:Key="UiFont">Segoe UI Variable Text, Segoe UI</FontFamily>
    <FontFamily x:Key="UiFontHead">Segoe UI Variable Display, Segoe UI</FontFamily>
    <Style TargetType="ToolTip"> <Setter Property="FontFamily" Value="{DynamicResource UiFont}"/> </Style>
    <!-- RENK PALETİ (v1.3.0 tasarım E) -->
    <SolidColorBrush x:Key="AccentColor" Color="#4C8DFF"/>
    <SolidColorBrush x:Key="PanelBg" Color="#161920"/>
    <SolidColorBrush x:Key="BorderBrush" Color="#262B34"/>

    <!-- v1.3.0 (tasarım E): yan menü -->
    <Style x:Key="NavItem" TargetType="RadioButton">
        <Setter Property="Foreground" Value="#A9B0BB"/>
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Height" Value="34"/>
        <Setter Property="Margin" Value="0,1"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="RadioButton">
                    <Border x:Name="Bd" CornerRadius="6" Background="Transparent">
                        <Grid>
                            <Border x:Name="Rail" Width="3" Height="16" CornerRadius="2" Background="#4C8DFF" HorizontalAlignment="Left" Visibility="Hidden"/>
                            <ContentPresenter Margin="10,0,8,0" VerticalAlignment="Center"/>
                        </Grid>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="#1A1E25"/>
                            <Setter Property="Foreground" Value="#E6E8EB"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="#1C2433"/>
                            <Setter TargetName="Rail" Property="Visibility" Value="Visible"/>
                            <Setter Property="Foreground" Value="#FFFFFF"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="NavIcon" TargetType="TextBlock">
        <Setter Property="FontFamily" Value="Segoe Fluent Icons, Segoe MDL2 Assets"/>
        <Setter Property="FontSize" Value="16"/>
        <Setter Property="Width" Value="28"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
    </Style>
    <Style x:Key="NavCaption" TargetType="TextBlock">
        <Setter Property="FontSize" Value="12"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Foreground" Value="#6B7280"/>
        <Setter Property="Margin" Value="12,14,0,5"/>
    </Style>
    <Style x:Key="SideBtn" TargetType="Button">
        <Setter Property="Foreground" Value="#A9B0BB"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="FontSize" Value="13.5"/>
        <Setter Property="Height" Value="32"/>
        <Setter Property="Margin" Value="0,1"/>
        <Setter Property="Padding" Value="12,0"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="HorizontalContentAlignment" Value="Left"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="Bd" CornerRadius="6" Background="{TemplateBinding Background}">
                        <ContentPresenter Margin="{TemplateBinding Padding}" HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1A1E25"/> </Trigger>
                        <Trigger Property="IsPressed" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#20252E"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="Bd" Property="Opacity" Value="0.4"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- v1.3.0 (tasarım E): sayfa butonları -->
    <Style x:Key="BtnSecondary" TargetType="Button">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Background" Value="#1D2129"/>
        <Setter Property="BorderBrush" Value="#2C313B"/>
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Height" Value="34"/>
        <Setter Property="Padding" Value="14,0"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Grid x:Name="root">
                        <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="6"/>
                        <Border x:Name="overlay" Background="White" Opacity="0" CornerRadius="6"/>
                        <ContentPresenter Margin="{TemplateBinding Padding}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.06"/> </Trigger>
                        <Trigger Property="IsPressed" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.12"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="root" Property="Opacity" Value="0.4"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="BtnPrimary" TargetType="Button" BasedOn="{StaticResource BtnSecondary}">
        <Setter Property="Foreground" Value="White"/>
        <Setter Property="Background" Value="#4C8DFF"/>
        <Setter Property="BorderBrush" Value="#4C8DFF"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
    </Style>
    <Style x:Key="BtnDanger" TargetType="Button" BasedOn="{StaticResource BtnSecondary}">
        <Setter Property="Foreground" Value="#F2A0A0"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="BorderBrush" Value="#5A2E33"/>
    </Style>
    <!-- Geri al: yalnızca etkinken görünür (kod IsEnabled'ı açıp kapatıyor) -->
    <Style x:Key="BtnUndo" TargetType="Button" BasedOn="{StaticResource BtnDanger}">
        <Style.Triggers>
            <Trigger Property="IsEnabled" Value="False"> <Setter Property="Visibility" Value="Collapsed"/> </Trigger>
        </Style.Triggers>
    </Style>
    <Style x:Key="BtnGhostIcon" TargetType="Button" BasedOn="{StaticResource BtnSecondary}">
        <Setter Property="Foreground" Value="#8A919C"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="BorderBrush" Value="Transparent"/>
        <Setter Property="Width" Value="34"/>
        <Setter Property="Padding" Value="0"/>
    </Style>

    <!-- v1.3.0 (tasarım E): arama kutusu; Tag = yer tutucu metni -->
    <Style x:Key="SearchBox" TargetType="TextBox">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="CaretBrush" Value="#E6E8EB"/>
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Height" Value="34"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="TextBox">
                    <Border x:Name="Bd" Background="#14171C" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="6">
                        <Grid Margin="10,0">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                            <TextBlock FontFamily="Segoe Fluent Icons, Segoe MDL2 Assets" Text="&#xE721;" FontSize="13" Foreground="#5D6470" VerticalAlignment="Center" Margin="0,0,8,0"/>
                            <TextBlock x:Name="Ph" Grid.Column="1" Text="{Binding Tag, RelativeSource={RelativeSource TemplatedParent}}" Foreground="#5D6470" VerticalAlignment="Center" Visibility="Collapsed" IsHitTestVisible="False"/>
                            <ScrollViewer x:Name="PART_ContentHost" Grid.Column="1" VerticalAlignment="Center" Focusable="False"/>
                        </Grid>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="Text" Value=""> <Setter TargetName="Ph" Property="Visibility" Value="Visible"/> </Trigger>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="BorderBrush" Value="#3E4552"/> </Trigger>
                        <Trigger Property="IsKeyboardFocused" Value="True"> <Setter TargetName="Bd" Property="BorderBrush" Value="#4C8DFF"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- v1.3.0 (tasarım E): içerikli üç durumlu onay kutusu (ağaçlardaki başlık kutuları) -->
    <Style x:Key="TreeCheck" TargetType="CheckBox">
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="CheckBox">
                    <StackPanel Orientation="Horizontal" Background="Transparent">
                        <Border x:Name="Box" Width="18" Height="18" CornerRadius="4" BorderThickness="1.5" BorderBrush="#4A515E" Background="Transparent" VerticalAlignment="Center">
                            <Grid>
                                <TextBlock x:Name="Mark" FontFamily="Segoe Fluent Icons, Segoe MDL2 Assets" Text="&#xE73E;" FontSize="12" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center" Visibility="Collapsed"/>
                                <Border x:Name="Dash" Width="8" Height="2" CornerRadius="1" Background="White" Visibility="Collapsed"/>
                            </Grid>
                        </Border>
                        <ContentPresenter Margin="10,0,0,0" VerticalAlignment="Center"/>
                    </StackPanel>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Box" Property="BorderBrush" Value="#7A8394"/> </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Box" Property="Background" Value="#4C8DFF"/>
                            <Setter TargetName="Box" Property="BorderBrush" Value="#4C8DFF"/>
                            <Setter TargetName="Mark" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="{x:Null}">
                            <Setter TargetName="Box" Property="Background" Value="#4C8DFF"/>
                            <Setter TargetName="Box" Property="BorderBrush" Value="#4C8DFF"/>
                            <Setter TargetName="Dash" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter Property="Opacity" Value="0.45"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- v1.3.0 (tasarım E): tweak satırı — içerik solda, anahtar sağda, alt çizgi. Genişliği kod verir (TweakRowWidth*). -->
    <Style x:Key="TweakRowToggle" TargetType="CheckBox">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="CheckBox">
                    <Border x:Name="Row" Background="Transparent" BorderBrush="#1E2229" BorderThickness="0,0,0,1" Padding="12,10,12,10" CornerRadius="4">
                        <Grid>
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                            <ContentPresenter x:Name="Body" VerticalAlignment="Center" Margin="0,0,16,0"/>
                            <Grid Grid.Column="1" Width="40" Height="20" VerticalAlignment="Center">
                                <Border x:Name="Track" CornerRadius="10" Background="Transparent" BorderThickness="1.5" BorderBrush="#5A6170"/>
                                <Ellipse x:Name="Dot" Fill="#A9B0BB" Width="12" Height="12" HorizontalAlignment="Left" Margin="4,0,0,0">
                                    <Ellipse.RenderTransform> <TranslateTransform X="0"/> </Ellipse.RenderTransform>
                                </Ellipse>
                            </Grid>
                        </Grid>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Row" Property="Background" Value="#181C23"/>
                            <Setter TargetName="Track" Property="BorderBrush" Value="#8A919C"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Track" Property="Background" Value="#4C8DFF"/>
                            <Setter TargetName="Track" Property="BorderBrush" Value="#4C8DFF"/>
                            <Setter TargetName="Dot" Property="Fill" Value="White"/>
                            <Trigger.EnterActions>
                                <BeginStoryboard> <Storyboard> <DoubleAnimation Storyboard.TargetName="Dot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)" To="20" Duration="0:0:0.18"><DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction></DoubleAnimation> </Storyboard> </BeginStoryboard>
                            </Trigger.EnterActions>
                            <Trigger.ExitActions>
                                <BeginStoryboard> <Storyboard> <DoubleAnimation Storyboard.TargetName="Dot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)" To="0" Duration="0:0:0.18"><DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction></DoubleAnimation> </Storyboard> </BeginStoryboard>
                            </Trigger.ExitActions>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter TargetName="Track" Property="BorderBrush" Value="#3A404B"/>
                            <Setter TargetName="Dot" Property="Fill" Value="#4A505B"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- v1.3.0 (tasarım E): Tweaks sol kategori listesi öğesi -->
    <Style x:Key="TweakCatListItem" TargetType="ListBoxItem">
        <Setter Property="Foreground" Value="#A9B0BB"/>
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ListBoxItem">
                    <Grid Margin="0,1">
                        <Border x:Name="Bd" Background="Transparent" CornerRadius="6" Padding="12,7,10,7">
                            <ContentPresenter HorizontalAlignment="Stretch" VerticalAlignment="Center"/>
                        </Border>
                        <Border x:Name="Rail" Width="3" Height="16" CornerRadius="1.5" Background="#4C8DFF" HorizontalAlignment="Left" Visibility="Collapsed"/>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="#181C23"/>
                            <Setter Property="Foreground" Value="#E6E8EB"/>
                        </Trigger>
                        <Trigger Property="IsSelected" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="#1C2433"/>
                            <Setter TargetName="Rail" Property="Visibility" Value="Visible"/>
                            <Setter Property="Foreground" Value="White"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- v1.3.0 (tasarım E): ince kaydırma çubuğu (dikey + yatay) -->
    <ControlTemplate x:Key="ThinScrollThumb" TargetType="Thumb">
        <Border x:Name="T" CornerRadius="3" Background="#323843" Margin="2"/>
        <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="T" Property="Background" Value="#4A515E"/> </Trigger>
            <Trigger Property="IsDragging" Value="True"> <Setter TargetName="T" Property="Background" Value="#5A6270"/> </Trigger>
        </ControlTemplate.Triggers>
    </ControlTemplate>
    <Style TargetType="ScrollBar">
        <Setter Property="Width" Value="10"/>
        <Setter Property="MinWidth" Value="10"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ScrollBar">
                    <Grid Background="Transparent">
                        <Track x:Name="PART_Track" IsDirectionReversed="True">
                            <Track.Thumb> <Thumb Template="{StaticResource ThinScrollThumb}"/> </Track.Thumb>
                        </Track>
                    </Grid>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
        <Style.Triggers>
            <Trigger Property="Orientation" Value="Horizontal">
                <Setter Property="Width" Value="Auto"/>
                <Setter Property="MinWidth" Value="0"/>
                <Setter Property="Height" Value="10"/>
                <Setter Property="MinHeight" Value="10"/>
                <Setter Property="Template">
                    <Setter.Value>
                        <ControlTemplate TargetType="ScrollBar">
                            <Grid Background="Transparent">
                                <Track x:Name="PART_Track" IsDirectionReversed="False">
                                    <Track.Thumb> <Thumb Template="{StaticResource ThinScrollThumb}"/> </Track.Thumb>
                                </Track>
                            </Grid>
                        </ControlTemplate>
                    </Setter.Value>
                </Setter>
            </Trigger>
        </Style.Triggers>
    </Style>

    <!-- v1.3.0 (§76): koyu sağ tık menüsü (ortak blokla aynı; Onizleme7 onaylı) -->
    <!-- sağ tık menüsü -->
    <Style TargetType="ContextMenu">
        <Setter Property="Background" Value="#15181E"/>
        <Setter Property="BorderBrush" Value="#2C313B"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="FontFamily" Value="{DynamicResource UiFont}"/>
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Padding" Value="4"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ContextMenu">
                    <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="8" Padding="{TemplateBinding Padding}">
                        <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="MenuItem">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="MenuItem">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="5" Padding="12,7" MinWidth="200">
                        <ContentPresenter ContentSource="Header" RecognizesAccessKey="True" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsHighlighted" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1C2433"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="Bd" Property="Padding" Value="12,8,12,4"/> <Setter Property="Cursor" Value="Arrow"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="{x:Static MenuItem.SeparatorStyleKey}" TargetType="Separator">
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Separator"> <Border Height="1" Background="#232831" Margin="6,4"/> </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <!-- MENÜLER (KORUNDU) -->
    <ContextMenu x:Key="TweakItemMenu">
        <MenuItem Header="Bu Ayarı Düzenle" Name="ctxEditTweak" FontWeight="Bold"/>
        <MenuItem Header="Kayıt Defterinde Aç (Regedit)" Name="ctxOpenReg"/>
        <Separator/>
        <MenuItem Header="Listeden Sil" Name="ctxDeleteTweak" Foreground="#E5484D"/>
    </ContextMenu>
    <ContextMenu x:Key="ItemMenu">
        <MenuItem Header="Konumu Aç (İncele)" Name="ctxOpenLocation" />
        <MenuItem Header="Yolları Düzenle (Gelişmiş)" Name="ctxEditPaths" FontWeight="Bold" Foreground="#4C8DFF"/>
        <Separator/>
        <MenuItem Header="Listeden Gizle (Yoksay)" Name="ctxIgnoreApp" Foreground="#E5484D"/>
    </ContextMenu>
    <ContextMenu x:Key="CustomItemMenu">
        <MenuItem Header="Bu Kuralı Sil" Name="ctxDeleteCustomRule" Foreground="#E5484D" FontWeight="Bold"/>
    </ContextMenu>

    <!-- TOGGLE SWITCH -->
    <!-- v1.3.0: Modern toggle — yumusak (CubicEase) gecis, hover vurgusu, basili halde topun genislemesi -->
    <Style x:Key="ToggleSwitch" TargetType="CheckBox">
        <Setter Property="Foreground" Value="White"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="CheckBox">
                    <StackPanel Orientation="Horizontal" Margin="2" Background="Transparent">
                        <Grid Width="40" Height="20" VerticalAlignment="Center">
                            <Border x:Name="Border" CornerRadius="10" Background="Transparent" BorderThickness="1.5" BorderBrush="#5A6170"/>
                            <Ellipse x:Name="Dot" Fill="#A9B0BB" Width="12" Height="12" HorizontalAlignment="Left" Margin="4,0,0,0">
                                <Ellipse.RenderTransform> <TranslateTransform X="0"/> </Ellipse.RenderTransform>
                            </Ellipse>
                        </Grid>
                        <ContentPresenter Margin="12,0,0,0" VerticalAlignment="Center"/>
                    </StackPanel>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Border" Property="BorderBrush" Value="#8A919C"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Border" Property="Background" Value="#4C8DFF"/>
                            <Setter TargetName="Border" Property="BorderBrush" Value="#4C8DFF"/>
                            <Setter TargetName="Dot" Property="Fill" Value="White"/>
                            <Trigger.EnterActions>
                                <BeginStoryboard> <Storyboard> <DoubleAnimation Storyboard.TargetName="Dot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)" To="20" Duration="0:0:0.18"><DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction></DoubleAnimation> </Storyboard> </BeginStoryboard>
                            </Trigger.EnterActions>
                            <Trigger.ExitActions>
                                <BeginStoryboard> <Storyboard> <DoubleAnimation Storyboard.TargetName="Dot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)" To="0" Duration="0:0:0.18"><DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction></DoubleAnimation> </Storyboard> </BeginStoryboard>
                            </Trigger.ExitActions>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter TargetName="Border" Property="BorderBrush" Value="#3A404B"/>
                            <Setter TargetName="Dot" Property="Fill" Value="#4A505B"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- v1.3.0: Tweaks sekmesi hizli filtre cipleri (RadioButton, GroupName=TweakChips) -->
    <Style x:Key="ChipStyle" TargetType="RadioButton">
        <Setter Property="Foreground" Value="#A9B0BB"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Margin" Value="0,0,8,8"/>
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="RadioButton">
                    <Border x:Name="Bd" Height="28" CornerRadius="14" Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" Padding="12,0">
                        <ContentPresenter VerticalAlignment="Center" HorizontalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="BorderBrush" Value="#3E4552"/>
                            <Setter Property="Foreground" Value="#E6E8EB"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="#1C2433"/>
                            <Setter TargetName="Bd" Property="BorderBrush" Value="#4C8DFF"/>
                            <Setter Property="Foreground" Value="White"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- v1.3.0 (tasarım E): Temizlik sayfası — ağaçlar dış ScrollViewer içinde, satır genişliğini kod verir (CleanRowW0/1/2) -->
    <Style x:Key="CleanTree" TargetType="TreeView">
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Padding" Value="0"/>
        <Setter Property="ScrollViewer.VerticalScrollBarVisibility" Value="Disabled"/>
        <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
        <Style.Resources>
            <SolidColorBrush x:Key="{x:Static SystemColors.HighlightBrushKey}" Color="#1A1F28"/>
            <SolidColorBrush x:Key="{x:Static SystemColors.InactiveSelectionHighlightBrushKey}" Color="Transparent"/>
            <SolidColorBrush x:Key="{x:Static SystemColors.HighlightTextBrushKey}" Color="White"/>
            <Style TargetType="CheckBox" BasedOn="{StaticResource TreeCheck}"/>
        </Style.Resources>
    </Style>
    <!-- Onarım: tek tık onarım kartı (simge + başlık + açıklama, sola hizalı) -->
    <Style x:Key="RepairCardBtn" TargetType="Button">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Margin" Value="0,0,0,8"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Grid x:Name="root">
                        <Border Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8"/>
                        <Border x:Name="overlay" Background="White" Opacity="0" CornerRadius="8"/>
                        <ContentPresenter Margin="12,10,12,10" HorizontalAlignment="Stretch" VerticalAlignment="Center"/>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.05"/> </Trigger>
                        <Trigger Property="IsPressed" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.10"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="root" Property="Opacity" Value="0.45"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <!-- Araçlar: kart (simge, başlık, açıklama; üstten hizalı, satırdaki kartlar eşit yükseklikte) -->
    <Style x:Key="ToolCardBtn" TargetType="Button" BasedOn="{StaticResource RepairCardBtn}">
        <Setter Property="Margin" Value="0,0,12,12"/>
        <Setter Property="MinHeight" Value="118"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Grid x:Name="root">
                        <Border x:Name="bd" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10"/>
                        <Border x:Name="overlay" Background="White" Opacity="0" CornerRadius="10"/>
                        <ContentPresenter Margin="18,16,18,16" HorizontalAlignment="Stretch" VerticalAlignment="Top"/>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.04"/> <Setter TargetName="bd" Property="BorderBrush" Value="#3E4552"/> </Trigger>
                        <Trigger Property="IsPressed" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.08"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="root" Property="Opacity" Value="0.45"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <!-- v1.3.0 (§79, B12, Onizleme9 onaylı): kart simgesi 40 px yuvarlak kare içinde, tek renk açık mavi -->
    <Style x:Key="ToolCardIconBox" TargetType="Border">
        <Setter Property="Width" Value="40"/>
        <Setter Property="Height" Value="40"/>
        <Setter Property="CornerRadius" Value="10"/>
        <Setter Property="Background" Value="#1C2433"/>
        <Setter Property="HorizontalAlignment" Value="Left"/>
        <Setter Property="Margin" Value="0,0,0,12"/>
    </Style>
    <Style x:Key="ToolCardIcon" TargetType="TextBlock">
        <Setter Property="FontFamily" Value="Segoe Fluent Icons, Segoe MDL2 Assets"/>
        <Setter Property="FontSize" Value="20"/>
        <Setter Property="Foreground" Value="#8CB4FF"/>
        <Setter Property="HorizontalAlignment" Value="Center"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
    </Style>
    <Style x:Key="ToolCardTitle" TargetType="TextBlock">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="FontSize" Value="15"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
    </Style>
    <Style x:Key="ToolCardDesc" TargetType="TextBlock">
        <Setter Property="Foreground" Value="#8A919C"/>
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="TextWrapping" Value="Wrap"/>
        <Setter Property="Margin" Value="0,4,0,0"/>
    </Style>
    <Style x:Key="CleanSecHead" TargetType="Grid">
        <Setter Property="Margin" Value="4,14,6,4"/>
    </Style>
    <Style x:Key="CleanSecTitle" TargetType="TextBlock">
        <Setter Property="Foreground" Value="#8A919C"/>
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
    </Style>
    <Style x:Key="CleanSecInfo" TargetType="TextBlock">
        <Setter Property="Foreground" Value="#5D6470"/>
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="HorizontalAlignment" Value="Right"/>
    </Style>
    <Style x:Key="SegItem" TargetType="RadioButton">
        <Setter Property="Foreground" Value="#A9B0BB"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="RadioButton">
                    <Border x:Name="Bd" Height="30" CornerRadius="6" Background="Transparent" BorderBrush="Transparent" BorderThickness="1">
                        <ContentPresenter VerticalAlignment="Center" HorizontalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter Property="Foreground" Value="#E6E8EB"/> </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="#1C2433"/>
                            <Setter TargetName="Bd" Property="BorderBrush" Value="#4C8DFF"/>
                            <Setter Property="Foreground" Value="White"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- v1.3.0: Tweak kategori basligi (Header string kalir — genel arama/secim kodu bozulmasin diye sadece gorunum degisir) -->
    <DataTemplate x:Key="TweakCatHeaderTemplate">
        <Border BorderBrush="#4C8DFF" BorderThickness="3,0,0,0" Padding="10,3,12,3" Margin="0,10,0,4" CornerRadius="2">
            <TextBlock Text="{Binding}" FontSize="15.5" FontWeight="SemiBold" FontFamily="{DynamicResource UiFontHead}" Foreground="#E6E8EB"/>
        </Border>
    </DataTemplate>

    <Style TargetType="TabItem">
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Height" Value="40"/>
        <Setter Property="Width" Value="135"/>
        <Setter Property="Foreground" Value="#A9B0BB"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="TabItem">
                    <Border x:Name="Border" Background="Transparent" CornerRadius="6" Margin="2,1">
                        <ContentPresenter x:Name="ContentSite" VerticalAlignment="Center" HorizontalAlignment="Left" ContentSource="Header" Margin="14,0"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Border" Property="Background" Value="#1A1E25"/>
                        </Trigger>
                        <!-- v1.3.0 (§61): FontWeight=SemiBold kaldırıldı. Sekme başlıkları gizli (yan menü seçer); ayar yalnız
                             sayfa içeriğine miras geçip açık ağırlığı olmayan tüm metinleri yarı kalın yapıyordu. Onizleme6 gibi normal. -->
                        <Trigger Property="IsSelected" Value="True">
                            <Setter TargetName="Border" Property="Background" Value="#1C2433"/>
                            <Setter Property="Foreground" Value="#FFFFFF"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style TargetType="Button">
        <Setter Property="Foreground" Value="White"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Grid x:Name="root">
                        <Border x:Name="border" CornerRadius="6" Background="{TemplateBinding Background}" BorderThickness="0"/>
                        <Border x:Name="overlay" CornerRadius="6" Background="White" Opacity="0"/>
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}"/>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.07"/> </Trigger>
                        <Trigger Property="IsPressed" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.14"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="root" Property="Opacity" Value="0.35"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
	<ControlTemplate x:Key="ComboBoxToggleButton" TargetType="ToggleButton">
        <Grid>
            <Grid.ColumnDefinitions>
                <ColumnDefinition />
                <ColumnDefinition Width="20" />
            </Grid.ColumnDefinitions>
            <Border x:Name="Border" Grid.ColumnSpan="2" CornerRadius="6" Background="#1D2129" BorderBrush="#2C313B" BorderThickness="1" />
            <Path x:Name="Arrow" Grid.Column="1" Fill="#8A919C" HorizontalAlignment="Center" VerticalAlignment="Center" Data="M 0 0 L 4 4 L 8 0 Z"/>
        </Grid>
    </ControlTemplate>

    <Style TargetType="ComboBox">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Background" Value="#1D2129"/>
        <Setter Property="BorderBrush" Value="#2C313B"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ComboBox">
                    <Grid>
                        <ToggleButton Name="ToggleButton" Template="{StaticResource ComboBoxToggleButton}" Grid.Column="2" Focusable="false" IsChecked="{Binding Path=IsDropDownOpen,Mode=TwoWay,RelativeSource={RelativeSource TemplatedParent}}" ClickMode="Press"/>
                        <ContentPresenter Name="ContentSite" IsHitTestVisible="False"  Content="{TemplateBinding SelectionBoxItem}" ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}" ContentTemplateSelector="{TemplateBinding ItemTemplateSelector}" Margin="10,3,23,3" VerticalAlignment="Center" HorizontalAlignment="Left" />
                        <TextBox x:Name="PART_EditableTextBox" Style="{x:Null}" Template="{x:Null}" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="3,3,23,3" Focusable="True" Background="Transparent" Visibility="Hidden" IsReadOnly="{TemplateBinding IsReadOnly}"/>
                        <Popup Name="Popup" Placement="Bottom" IsOpen="{TemplateBinding IsDropDownOpen}" AllowsTransparency="True" Focusable="False" PopupAnimation="Slide">
                            <Grid Name="DropDown" SnapsToDevicePixels="True" MinWidth="{TemplateBinding ActualWidth}" MaxHeight="{TemplateBinding MaxDropDownHeight}">
                                <Border x:Name="DropDownBorder" Background="#161920" BorderThickness="1" BorderBrush="#2C313B" CornerRadius="6"/>
                                <ScrollViewer Margin="4,6,4,6" SnapsToDevicePixels="True">
                                    <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Contained" />
                                </ScrollViewer>
                            </Grid>
                        </Popup>
                    </Grid>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
	<Style TargetType="ComboBoxItem">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="Padding" Value="5"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ComboBoxItem">
                    <Border x:Name="Border" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}">
                        <ContentPresenter />
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Border" Property="Background" Value="#1A1E25"/>
                        </Trigger>
                        <Trigger Property="IsSelected" Value="True">
                            <Setter TargetName="Border" Property="Background" Value="#1C2433"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
	<!-- BAŞLANGIÇ YÖNETİCİSİ SAĞ TIK MENÜSÜ -->
    <ContextMenu x:Key="StartupItemMenu">
        <MenuItem Header="Durumu Değiştir (Aç / Kapat)" Name="ctxToggleStartup" FontWeight="Bold" Foreground="#4C8DFF"/>
        <MenuItem Header="Dosya Konumunu Aç (Dosyayı Seç)" Name="ctxOpenStartupLoc"/>
        <MenuItem Header="Dosya Yolunu Kopyala" Name="ctxCopyStartupPath" Foreground="#3FB97A"/>
        <MenuItem Header="Kayıt Defterinde Aç" Name="ctxOpenStartupReg"/>
        <Separator/>
        <MenuItem Header="@@ctx_deleteperm@@" Name="ctxDeleteStartup" Foreground="#E5484D" FontWeight="Bold"/>
    </ContextMenu>

    <!-- MODERN LISTVIEW VE SÜTUN BAŞLIKLARI TASARIMI -->
    <Style TargetType="GridViewColumnHeader">
        <Setter Property="Background" Value="#13161B"/>
        <Setter Property="Foreground" Value="#6B7280"/>
        <Setter Property="Padding" Value="10,5"/>
        <Setter Property="FontWeight" Value="Bold"/>
        <Setter Property="BorderThickness" Value="0,0,1,1"/>
        <Setter Property="BorderBrush" Value="#232831"/>
        <Setter Property="HorizontalContentAlignment" Value="Left"/>
    </Style>
    <Style TargetType="ListViewItem">
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="BorderThickness" Value="0,0,0,1"/>
        <Setter Property="BorderBrush" Value="#1F232B"/>
        <Setter Property="Margin" Value="0"/>
        <Setter Property="Padding" Value="5,8"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ListViewItem">
                    <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}">
                        <GridViewRowPresenter Content="{TemplateBinding Content}" Margin="{TemplateBinding Padding}"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter Property="Background" Value="#181C23"/>
                        </Trigger>
                        <Trigger Property="IsSelected" Value="True">
                            <Setter Property="Background" Value="#1C2433"/>
                            <Setter Property="Foreground" Value="White"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <!-- v1.3.0 (tasarım E, §54): Genel Bakış — Onizleme5 pgDash stilleri -->
    <Style x:Key="DashCard" TargetType="Border">
        <Setter Property="Background" Value="#15181E"/>
        <Setter Property="BorderBrush" Value="#232831"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="CornerRadius" Value="10"/>
    </Style>
    <Style x:Key="DashCaption" TargetType="TextBlock">
        <Setter Property="FontSize" Value="12"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Foreground" Value="#6B7280"/>
    </Style>
    <Style x:Key="DashBigNum" TargetType="TextBlock">
        <Setter Property="FontSize" Value="30"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="FontFamily" Value="{DynamicResource UiFontHead}"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Margin" Value="0,6,0,0"/>
    </Style>
    <Style x:Key="DashUnit" TargetType="TextBlock">
        <Setter Property="FontSize" Value="17"/>
        <Setter Property="Foreground" Value="#8A919C"/>
        <Setter Property="VerticalAlignment" Value="Bottom"/>
        <Setter Property="Margin" Value="0,0,0,5"/>
    </Style>
    <Style x:Key="DashBar" TargetType="ProgressBar">
        <Setter Property="Height" Value="6"/>
        <Setter Property="Minimum" Value="0"/>
        <Setter Property="Maximum" Value="100"/>
        <Setter Property="Background" Value="#252A33"/>
        <Setter Property="Foreground" Value="#4C8DFF"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ProgressBar">
                    <Grid>
                        <Border x:Name="PART_Track" CornerRadius="3" Background="{TemplateBinding Background}"/>
                        <Border x:Name="PART_Indicator" CornerRadius="3" Background="{TemplateBinding Foreground}" HorizontalAlignment="Left"/>
                    </Grid>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="BtnSubtle" TargetType="Button" BasedOn="{StaticResource BtnSecondary}">
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="BorderBrush" Value="Transparent"/>
        <Setter Property="Foreground" Value="#A9B0BB"/>
        <Setter Property="Padding" Value="10,0"/>
    </Style>
    <Style x:Key="DashRec" TargetType="Button">
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="Bd" CornerRadius="8" Padding="12,10" Background="Transparent">
                        <ContentPresenter HorizontalAlignment="Stretch"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1A1E25"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="DashRow" TargetType="Border">
        <Setter Property="Padding" Value="0,11,0,11"/>
        <Setter Property="BorderBrush" Value="#1F232B"/>
        <Setter Property="BorderThickness" Value="0,0,0,1"/>
    </Style>
    <Style x:Key="DashRowLabel" TargetType="TextBlock">
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Foreground" Value="#8A919C"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
    </Style>
    <Style x:Key="DashRowValue" TargetType="TextBlock">
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Setter Property="TextTrimming" Value="CharacterEllipsis"/>
    </Style>
  </Window.Resources>

  <Grid>
    <Grid.ColumnDefinitions>
        <ColumnDefinition Width="236"/>
        <ColumnDefinition Width="*"/>
    </Grid.ColumnDefinitions>

    <!-- v1.3.0 (tasarım E): YAN MENÜ. Sekme başlıkları gizli; nav öğesinin Tag'i hedef TabItem adıdır. -->
    <Border Grid.Column="0" Background="#12151A" BorderBrush="#1E2229" BorderThickness="0,0,1,0">
        <DockPanel Margin="10,14,10,12">
            <!-- v1.3.0 (§80, B10, Onizleme10 onaylı): logo resmi yerine "M" kare + ad; yan menü 214 → 236 px -->
            <StackPanel DockPanel.Dock="Top" Orientation="Horizontal" Margin="6,2,0,10">
                <Border Width="34" Height="34" CornerRadius="9">
                    <Border.Background>
                        <LinearGradientBrush StartPoint="0,0" EndPoint="1,1"> <GradientStop Color="#5E9CFF" Offset="0"/> <GradientStop Color="#3767D6" Offset="1"/> </LinearGradientBrush>
                    </Border.Background>
                    <TextBlock Text="M" FontSize="17" FontWeight="Bold" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <StackPanel Margin="11,0,0,0" VerticalAlignment="Center">
                    <TextBlock Text="MrClean" FontSize="15" FontWeight="SemiBold" Foreground="#E6E8EB"/>
                    <TextBlock Text="@@boot_subtitle@@" FontSize="12" Foreground="#6B7280"/>
                </StackPanel>
            </StackPanel>
            <StackPanel DockPanel.Dock="Bottom">
                <Border Height="1" Background="#1E2229" Margin="0,8,0,8"/>
                <Button x:Name="btnRefreshApp" Content="@@btn_update@@" Style="{StaticResource SideBtn}"/>
                <Button x:Name="btnNightMode" Content="@@btn_shutdown@@" Style="{StaticResource SideBtn}" ToolTip="Akıllı Otomatik Kapanma ve İndirme Takibi"/>
                <Button x:Name="btnSettings" Content="@@btn_settings@@" Style="{StaticResource SideBtn}"/>
            </StackPanel>
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                <StackPanel x:Name="pnlNav">
                    <TextBlock Text="@@nav_grp_general@@" Style="{StaticResource NavCaption}" Margin="12,8,0,5"/>
                    <RadioButton x:Name="navDashboard" Tag="tabDashboard" GroupName="MainNav" Style="{StaticResource NavItem}" IsChecked="True"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xE80F;"/><TextBlock Text="@@tab_dashboard@@" VerticalAlignment="Center"/></StackPanel></RadioButton>

                    <TextBlock Text="@@nav_grp_clean@@" Style="{StaticResource NavCaption}"/>
                    <RadioButton x:Name="navClean" Tag="tabClean" GroupName="MainNav" Style="{StaticResource NavItem}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xE74D;"/><TextBlock Text="@@tab_clean@@" VerticalAlignment="Center"/></StackPanel></RadioButton>

                    <TextBlock Text="@@nav_grp_maint@@" Style="{StaticResource NavCaption}"/>
                    <RadioButton x:Name="navRepair" Tag="tabRepair" GroupName="MainNav" Style="{StaticResource NavItem}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xE90F;"/><TextBlock Text="@@tab_repair@@" VerticalAlignment="Center"/></StackPanel></RadioButton>
                    <RadioButton x:Name="navTools" Tag="tabTools" GroupName="MainNav" Style="{StaticResource NavItem}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xEC7A;"/><TextBlock Text="@@tab_tools@@" VerticalAlignment="Center"/></StackPanel></RadioButton>
                    <RadioButton x:Name="navWinget" Tag="tabWinget" GroupName="MainNav" Style="{StaticResource NavItem}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xE7B8;"/><TextBlock Text="@@tab_winget@@" VerticalAlignment="Center"/></StackPanel></RadioButton>

                    <TextBlock Text="@@nav_grp_system@@" Style="{StaticResource NavCaption}"/>
                    <RadioButton x:Name="navTweaks" Tag="tabTweaks" GroupName="MainNav" Style="{StaticResource NavItem}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xE9E9;"/><TextBlock Text="@@tab_tweaks@@" VerticalAlignment="Center"/></StackPanel></RadioButton>
                    <RadioButton x:Name="navStartup" Tag="tabStartup" GroupName="MainNav" Style="{StaticResource NavItem}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xE7E8;"/><TextBlock Text="@@tab_startup@@" VerticalAlignment="Center"/></StackPanel></RadioButton>

                    <TextBlock Text="@@nav_grp_analysis@@" Style="{StaticResource NavCaption}"/>
                    <RadioButton x:Name="navLargeFiles" Tag="tabLargeFiles" GroupName="MainNav" Style="{StaticResource NavItem}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xEDA2;"/><TextBlock Text="@@tab_largefiles@@" VerticalAlignment="Center"/></StackPanel></RadioButton>
                    <RadioButton x:Name="navCrash" Tag="tabCrash" GroupName="MainNav" Style="{StaticResource NavItem}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource NavIcon}" Text="&#xE7BA;"/><TextBlock Text="@@tab_crash@@" VerticalAlignment="Center"/></StackPanel></RadioButton>
                </StackPanel>
            </ScrollViewer>
        </DockPanel>
    </Border>

    <!-- v1.3.0 (tasarım E): içerik | sürükleme çubuğu | işlem kayıtları (altta, kapalı başlar) | ince durum çubuğu -->
    <Grid Grid.Column="1" Margin="14,14,14,0">
	<Grid.RowDefinitions>
        <RowDefinition Height="*" MinHeight="240"/>
        <RowDefinition x:Name="rowLogSplit" Height="0"/>
        <RowDefinition x:Name="rowLog" Height="0"/>
        <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>

    <!-- CONTENT -->
    <Grid Grid.Row="0">
        <Border Background="Transparent" BorderThickness="0" Padding="2">
            <Grid>
                <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                <TabControl x:Name="tabControl" Grid.Row="1" Background="Transparent" BorderThickness="0" TabStripPlacement="Left" Margin="0,0,0,5">
                    <!-- v1.3.0 (tasarım E): sekme şeridi hiç görünmez; seçimi yan menü yapar -->
                    <TabControl.Template>
                        <ControlTemplate TargetType="TabControl">
                            <Grid>
                                <StackPanel x:Name="HeaderPanel" IsItemsHost="True" Visibility="Collapsed"/>
                                <ContentPresenter x:Name="PART_SelectedContentHost" ContentSource="SelectedContent"/>
                            </Grid>
                        </ControlTemplate>
                    </TabControl.Template>
				<!-- ANA KONTROL PANELİ (DASHBOARD) -->
                    <TabItem Header="@@tab_dashboard@@" x:Name="tabDashboard" IsSelected="True">
                        <!-- v1.3.0 (tasarım E, §54): Onizleme5 pgDash düzeni. 4 kart (öneri sayısı, bellek, disk, gecikme), solda etiket | değer sistem bilgisi
                             (DNS ve bağlantı bu listenin satırı), sağda önerilen işlemler + yalnız gerçek kayıt varsa son işlemler. Tüm eski x:Name'ler duruyor. -->
                        <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Margin="16,12,14,12">
                            <StackPanel>
                                <Grid Margin="0,0,0,20">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <StackPanel VerticalAlignment="Center">
                                        <TextBlock Text="@@tab_dashboard@@" Foreground="#E6E8EB" FontSize="26" FontWeight="SemiBold" FontFamily="{DynamicResource UiFontHead}"/>
                                        <TextBlock x:Name="txtDashSubHeader" Text="@@dash_rec_wait@@" Foreground="#8A919C" FontSize="13.5" Margin="0,4,0,0" TextTrimming="CharacterEllipsis"/>
                                    </StackPanel>
                                    <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                                        <Button x:Name="btnHardwareDetail" Style="{StaticResource BtnSecondary}" Content="@@dash_detail@@" IsEnabled="False"/>
                                        <Button x:Name="btnPingTest" Style="{StaticResource BtnPrimary}" Content="@@dash_test@@" Margin="8,0,0,0"/>
                                    </StackPanel>
                                </Grid>
                                <Grid Margin="0,0,0,16">
                                    <Grid.ColumnDefinitions>
                                        <ColumnDefinition Width="*"/><ColumnDefinition Width="16"/>
                                        <ColumnDefinition Width="*"/><ColumnDefinition Width="16"/>
                                        <ColumnDefinition Width="*"/><ColumnDefinition Width="16"/>
                                        <ColumnDefinition Width="*"/>
                                    </Grid.ColumnDefinitions>
                                    <Border x:Name="cardDashRec" Grid.Column="0" Style="{StaticResource DashCard}" Height="124" Padding="18,16" Cursor="Hand">
                                        <Grid>
                                            <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
                                            <TextBlock Text="@@dash_rec_card@@" Style="{StaticResource DashCaption}"/>
                                            <TextBlock Style="{StaticResource NavIcon}" Width="Auto" Text="&#xE82F;" Foreground="#8CB4FF" HorizontalAlignment="Right" VerticalAlignment="Top"/>
                                            <TextBlock x:Name="txtDashHero" Grid.Row="1" Text="—" Style="{StaticResource DashBigNum}"/>
                                            <TextBlock x:Name="txtDashHeroSub" Grid.Row="3" Text="@@dash_rec_wait@@" Foreground="#8A919C" FontSize="13" TextTrimming="CharacterEllipsis"/>
                                        </Grid>
                                    </Border>
                                    <Border Grid.Column="2" Style="{StaticResource DashCard}" Height="124" Padding="18,16">
                                        <Grid>
                                            <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
                                            <TextBlock Text="@@dash_card_mem@@" Style="{StaticResource DashCaption}"/>
                                            <Button x:Name="btnCleanRAM" Grid.RowSpan="2" Style="{StaticResource BtnSecondary}" Content="@@dash_ram_free@@" Height="24" Padding="10,0" FontSize="12" Margin="0,-4,0,0"
                                                    HorizontalAlignment="Right" VerticalAlignment="Top" ToolTip="Çalışan süreçlerin Working Set belleğini boşaltır. Anlık RAM kullanımını düşürür."/>
                                            <StackPanel Grid.Row="1" Orientation="Horizontal">
                                                <TextBlock>
                                                    <TextBlock.Style>
                                                        <Style TargetType="TextBlock" BasedOn="{StaticResource DashBigNum}">
                                                            <Setter Property="Text" Value="{Binding Value, ElementName=pbDashRAM, StringFormat={}{0:0}}"/>
                                                            <Style.Triggers> <DataTrigger Binding="{Binding Text, ElementName=txtDashRAM}" Value="—"> <Setter Property="Text" Value="—"/> </DataTrigger> </Style.Triggers>
                                                        </Style>
                                                    </TextBlock.Style>
                                                </TextBlock>
                                                <TextBlock Text=" %" Style="{StaticResource DashUnit}"/>
                                            </StackPanel>
                                            <TextBlock x:Name="txtDashRAM" Grid.Row="3" Text="—" Foreground="#8A919C" FontSize="13" Margin="0,0,0,8" TextTrimming="CharacterEllipsis"/>
                                            <ProgressBar x:Name="pbDashRAM" Grid.Row="4" Style="{StaticResource DashBar}"/>
                                        </Grid>
                                    </Border>
                                    <Border x:Name="cardDashDisk" Grid.Column="4" Style="{StaticResource DashCard}" Height="124" Padding="18,16" Cursor="Hand">
                                        <Grid>
                                            <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
                                            <TextBlock Text="@@dash_card_disk@@" Style="{StaticResource DashCaption}"/>
                                            <StackPanel Grid.Row="1" Orientation="Horizontal">
                                                <TextBlock>
                                                    <TextBlock.Style>
                                                        <Style TargetType="TextBlock" BasedOn="{StaticResource DashBigNum}">
                                                            <Setter Property="Text" Value="{Binding Value, ElementName=pbDashDisk, StringFormat={}{0:0}}"/>
                                                            <Style.Triggers> <DataTrigger Binding="{Binding Text, ElementName=txtDashDisk}" Value="—"> <Setter Property="Text" Value="—"/> </DataTrigger> </Style.Triggers>
                                                        </Style>
                                                    </TextBlock.Style>
                                                </TextBlock>
                                                <TextBlock Text=" %" Style="{StaticResource DashUnit}"/>
                                            </StackPanel>
                                            <TextBlock x:Name="txtDashDisk" Grid.Row="3" Text="—" Foreground="#8A919C" FontSize="13" Margin="0,0,0,8" TextTrimming="CharacterEllipsis"/>
                                            <ProgressBar x:Name="pbDashDisk" Grid.Row="4" Style="{StaticResource DashBar}"/>
                                        </Grid>
                                    </Border>
                                    <Border Grid.Column="6" Style="{StaticResource DashCard}" Height="124" Padding="18,16">
                                        <Grid>
                                            <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
                                            <TextBlock Text="@@dash_pingcard@@" Style="{StaticResource DashCaption}"/>
                                            <StackPanel Grid.Row="1" Orientation="Horizontal">
                                                <TextBlock x:Name="txtDashLivePing" Text="—" Style="{StaticResource DashBigNum}"/>
                                                <TextBlock x:Name="txtDashLivePingUnit" Text=" ms" Style="{StaticResource DashUnit}"/>
                                            </StackPanel>
                                            <TextBlock Grid.Row="3" FontSize="13" Foreground="#8A919C" TextTrimming="CharacterEllipsis" ToolTip="@@dash_ping_tip@@"><Run x:Name="txtPingCF" Text="Cloudflare —"/><Run Text=" · "/><Run x:Name="txtPingGoogle" Text="Google —"/><Run Text=" · "/><Run x:Name="txtPingGW" Text="@@dash_ping_gw@@ —"/></TextBlock>
                                        </Grid>
                                    </Border>
                                </Grid>
                                <Grid>
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="3*"/> <ColumnDefinition Width="16"/> <ColumnDefinition Width="2*"/> </Grid.ColumnDefinitions>
                                    <Border Style="{StaticResource DashCard}">
                                        <DockPanel>
                                            <Border DockPanel.Dock="Top" BorderBrush="#232831" BorderThickness="0,0,0,1" Padding="20,14,12,14">
                                                <DockPanel>
                                                    <Button x:Name="btnSysSecDetail" DockPanel.Dock="Right" Style="{StaticResource BtnSubtle}" Height="28"
                                                            ToolTip="Defender, güvenlik duvarı, BitLocker, sistem kimliği, son güncellemeler — detaylı ve kopyalanabilir liste">
                                                        <StackPanel Orientation="Horizontal">
                                                            <TextBlock Text="@@dash_more@@" VerticalAlignment="Center"/>
                                                            <TextBlock Style="{StaticResource NavIcon}" Width="Auto" Text="&#xE76C;" FontSize="11" Margin="6,1,0,0"/>
                                                        </StackPanel>
                                                    </Button>
                                                    <TextBlock Text="@@dash_sysinfo@@" Foreground="#E6E8EB" FontSize="15" FontWeight="SemiBold" VerticalAlignment="Center"/>
                                                </DockPanel>
                                            </Border>
                                            <StackPanel Margin="20,4,20,12">
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_os@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock Grid.Column="1" Style="{StaticResource DashRowValue}"><Run x:Name="txtDashOS" Text="—"/><Run Text="  ·  "/><Run x:Name="txtDashWinVer" Text=""/></TextBlock>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_cpu@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock x:Name="txtDashCPU" Grid.Column="1" Text="—" Style="{StaticResource DashRowValue}"/>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_gpu@@" Style="{StaticResource DashRowLabel}" VerticalAlignment="Top"/>
                                                    <TextBlock x:Name="txtDashGPU" Grid.Column="1" Text="—" Style="{StaticResource DashRowValue}" LineHeight="20"/>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_mem@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock x:Name="txtDashRamInfo" Grid.Column="1" Text="—" Style="{StaticResource DashRowValue}"/>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_disk@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock x:Name="txtDashDiskInfo" Grid.Column="1" Text="—" Style="{StaticResource DashRowValue}"/>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_sec@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock x:Name="txtDashSecurity" Grid.Column="1" Text="—" Style="{StaticResource DashRowValue}"/>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_up@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock x:Name="txtDashUptime" Grid.Column="1" Text="—" Style="{StaticResource DashRowValue}"/>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_upd@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock x:Name="txtDashLastUpdate" Grid.Column="1" Text="—" Style="{StaticResource DashRowValue}"/>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_dns@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock x:Name="txtDashDNS" Grid.Column="1" Text="—" Style="{StaticResource DashRowValue}"/>
                                                </Grid></Border>
                                                <Border Style="{StaticResource DashRow}" BorderThickness="0"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="185"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                    <TextBlock Text="@@dash_row_net@@" Style="{StaticResource DashRowLabel}"/>
                                                    <TextBlock Grid.Column="1" Style="{StaticResource DashRowValue}"><Run x:Name="txtDashNic" Text="—"/><Run Text="  ·  ↓ "/><Run x:Name="txtDashDownload" Text="—"/><Run Text="  ·  ↑ "/><Run x:Name="txtDashUpload" Text="—"/></TextBlock>
                                                </Grid></Border>
                                                <TextBlock x:Name="txtDashHwAge" Text="" Foreground="#5D6470" FontSize="12" Margin="0,8,0,0"/>
                                            </StackPanel>
                                        </DockPanel>
                                    </Border>
                                    <Border Grid.Column="2" Style="{StaticResource DashCard}">
                                        <StackPanel>
                                            <Border BorderBrush="#232831" BorderThickness="0,0,0,1" Padding="20,14,20,14">
                                                <TextBlock Text="@@dash_rec_title@@" Foreground="#E6E8EB" FontSize="15" FontWeight="SemiBold" Height="28" Padding="0,5,0,0"/>
                                            </Border>
                                            <StackPanel x:Name="pnlDashRec" Margin="8,8,8,4"/>
                                            <StackPanel x:Name="bdDashHist" Visibility="Collapsed">
                                                <Border BorderBrush="#232831" BorderThickness="0,1,0,0" Padding="20,14,20,6" Margin="0,4,0,0">
                                                    <TextBlock Text="@@dash_hist_title@@" Foreground="#E6E8EB" FontSize="15" FontWeight="SemiBold"/>
                                                </Border>
                                                <StackPanel x:Name="pnlDashHist" Margin="20,4,20,14"/>
                                            </StackPanel>
                                        </StackPanel>
                                    </Border>
                                </Grid>
                            </StackPanel>
                        </ScrollViewer>
                    </TabItem>
                    <!-- v1.3.0 (tasarım E): Tarayıcılar / Uygulamalar / Sistem / ShellBags tek sayfada; 4 ağaç ayrı kalır -->
                    <TabItem Header="@@tab_clean@@" x:Name="tabClean">
                        <Grid Margin="16,12,14,12">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="16"/> <ColumnDefinition Width="300"/> </Grid.ColumnDefinitions>
                            <Grid Grid.Column="0">
                                <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                <Grid Grid.Row="0" Margin="0,0,0,12">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <StackPanel>
                                        <TextBlock Text="@@tab_clean@@" Foreground="#E6E8EB" FontSize="22" FontWeight="SemiBold"/>
                                        <TextBlock x:Name="txtCleanSubtitle" Text="@@cl_sub_none@@" Foreground="#8A919C" FontSize="13" Margin="0,3,0,0" TextTrimming="CharacterEllipsis"/>
                                    </StackPanel>
                                    <Button x:Name="btnCleanAnalyze" Grid.Column="1" Style="{StaticResource BtnSecondary}" Content="{Binding Content, ElementName=btnAnalyze}" IsEnabled="{Binding IsEnabled, ElementName=btnAnalyze}" Background="{Binding Background, ElementName=btnAnalyze}" MinWidth="120" Padding="14,0" VerticalAlignment="Center"/>
                                </Grid>
                                <Grid Grid.Row="1" Margin="0,0,0,10">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <TextBox x:Name="txtCleanSearch" Style="{StaticResource SearchBox}" Tag="@@cl_search_ph@@" MaxWidth="420" HorizontalAlignment="Stretch"/>
                                    <Button x:Name="btnCleanSelectAll" Grid.Column="1" Style="{StaticResource BtnSecondary}" Content="@@cl_select_all@@" Padding="14,0" Margin="10,0,0,0"/>
                                    <Button x:Name="btnCleanUnselectAll" Grid.Column="2" Style="{StaticResource BtnSecondary}" Content="@@cl_unselect@@" Padding="14,0" Margin="8,0,0,0"/>
                                </Grid>
                                <WrapPanel Grid.Row="2" Margin="0,0,0,4">
                                    <RadioButton x:Name="chipClAll" GroupName="CleanChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_all@@" IsChecked="True"/>
                                    <RadioButton x:Name="chipClBrowser" GroupName="CleanChips" Style="{StaticResource ChipStyle}" Content="@@tab_browsers@@"/>
                                    <RadioButton x:Name="chipClApps" GroupName="CleanChips" Style="{StaticResource ChipStyle}" Content="@@tab_apps@@"/>
                                    <RadioButton x:Name="chipClSystem" GroupName="CleanChips" Style="{StaticResource ChipStyle}" Content="@@tab_system@@"/>
                                    <RadioButton x:Name="chipClPrivacy" GroupName="CleanChips" Style="{StaticResource ChipStyle}" Content="@@cl_chip_privacy@@"/>
                                </WrapPanel>
                                <Border Grid.Row="3" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="6,4,2,6">
                                    <Grid>
                                        <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                        <Grid Margin="10,6,22,6">
                                            <TextBlock Text="@@cl_col_item@@" Style="{StaticResource NavCaption}" Margin="0"/>
                                            <TextBlock Text="@@cl_col_size@@" Style="{StaticResource NavCaption}" Margin="0" HorizontalAlignment="Right"/>
                                        </Grid>
                                        <ScrollViewer x:Name="svClean" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                            <StackPanel x:Name="pnlCleanSections" Margin="4,0,8,0">
                                                <StackPanel x:Name="secClBrowser">
                                                    <Grid Style="{StaticResource CleanSecHead}"> <TextBlock Text="@@tab_browsers@@" Style="{StaticResource CleanSecTitle}"/> <TextBlock x:Name="txtClInfoBrowser" Style="{StaticResource CleanSecInfo}"/> </Grid>
                                                    <TreeView x:Name="tvBrowser" Style="{StaticResource CleanTree}"/>
                                                </StackPanel>
                                                <StackPanel x:Name="secClApps">
                                                    <Grid Style="{StaticResource CleanSecHead}"> <TextBlock Text="@@tab_apps@@" Style="{StaticResource CleanSecTitle}"/> <TextBlock x:Name="txtClInfoApps" Style="{StaticResource CleanSecInfo}"/> </Grid>
                                                    <TreeView x:Name="tvApps" Style="{StaticResource CleanTree}"/>
                                                </StackPanel>
                                                <StackPanel x:Name="secClSystem">
                                                    <Grid Style="{StaticResource CleanSecHead}"> <TextBlock Text="@@tab_system@@" Style="{StaticResource CleanSecTitle}"/> <TextBlock x:Name="txtClInfoSystem" Style="{StaticResource CleanSecInfo}"/> </Grid>
                                                    <TreeView x:Name="tvSystem" Style="{StaticResource CleanTree}"/>
                                                </StackPanel>
                                                <StackPanel x:Name="secClPrivacy">
                                                    <Grid Style="{StaticResource CleanSecHead}"> <TextBlock Text="@@cl_chip_privacy@@" Style="{StaticResource CleanSecTitle}"/> <TextBlock x:Name="txtClInfoPrivacy" Style="{StaticResource CleanSecInfo}"/> </Grid>
                                                    <TreeView x:Name="tvShellBags" Style="{StaticResource CleanTree}"/>
                                                </StackPanel>
                                            </StackPanel>
                                        </ScrollViewer>
                                    </Grid>
                                </Border>
                            </Grid>
                            <Border Grid.Column="2" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="18,16">
                                <DockPanel LastChildFill="True">
                                    <StackPanel DockPanel.Dock="Bottom" Margin="0,12,0,0">
                                        <TextBlock Text="@@cl_method@@" Style="{StaticResource NavCaption}" Margin="0,0,0,8"/>
                                        <Border Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="3">
                                            <UniformGrid Columns="3">
                                                <RadioButton x:Name="rbDelFast" GroupName="CleanDelMethod" Style="{StaticResource SegItem}" Content="@@cl_m_fast@@" ToolTip="@@del_fast@@"/>
                                                <RadioButton x:Name="rbDelZero" GroupName="CleanDelMethod" Style="{StaticResource SegItem}" Content="@@cl_m_zero@@" ToolTip="@@del_secure_zero@@"/>
                                                <RadioButton x:Name="rbDelRandom" GroupName="CleanDelMethod" Style="{StaticResource SegItem}" Content="@@cl_m_random@@" ToolTip="@@del_secure_random@@"/>
                                            </UniformGrid>
                                        </Border>
                                        <Button x:Name="btnCleanStart" Style="{StaticResource BtnPrimary}" Height="42" FontSize="15" Margin="0,14,0,0" Content="{Binding Content, ElementName=btnRun}" IsEnabled="{Binding IsEnabled, ElementName=btnRun}" Background="{Binding Background, ElementName=btnRun}" BorderBrush="{Binding Background, ElementName=btnRun}"/>
                                    </StackPanel>
                                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                        <StackPanel>
                                            <TextBlock Text="@@cl_selected@@" Style="{StaticResource NavCaption}" Margin="0,0,0,6"/>
                                            <TextBlock x:Name="txtCleanSelTotal" Text="—" Foreground="#E6E8EB" FontSize="32" FontWeight="SemiBold"/>
                                            <TextBlock x:Name="txtCleanSelSub" Text="" Foreground="#8A919C" FontSize="13" Margin="0,2,0,0" TextWrapping="Wrap"/>
                                            <TextBlock x:Name="txtCleanUnmeasured" Text="" Foreground="#E0A23B" FontSize="13" Margin="0,6,0,0" TextWrapping="Wrap" Visibility="Collapsed"/>
                                            <Border Height="1" Background="#232831" Margin="0,16,0,14"/>
                                            <TextBlock Text="@@cl_by_cat@@" Style="{StaticResource NavCaption}" Margin="0,0,0,10"/>
                                            <StackPanel x:Name="pnlCleanCats"/>
                                            <Border Height="1" Background="#232831" Margin="0,6,0,14"/>
                                            <TextBlock Text="@@cl_history@@" Style="{StaticResource NavCaption}" Margin="0,0,0,8"/>
                                            <StackPanel x:Name="pnlCleanHistory"/>
                                        </StackPanel>
                                    </ScrollViewer>
                                </DockPanel>
                            </Border>
                        </Grid>
                    </TabItem>
                    <!-- ONARIM SEKMESİ (GÜNCELLENDİ) -->
                    <TabItem Header="@@tab_repair@@" x:Name="tabRepair">
                        <!-- v1.3.0 (tasarım E): seçmeli onarımlar solda (Başlat ile sırayla), tek tık onarımlar sağ panelde -->
                        <Grid Margin="16,12,14,12">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="16"/> <ColumnDefinition Width="300"/> </Grid.ColumnDefinitions>
                            <Grid Grid.Column="0">
                                <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
                                <StackPanel Grid.Row="0" Margin="0,0,0,12">
                                    <TextBlock Text="@@tab_repair@@" Foreground="#E6E8EB" FontSize="22" FontWeight="SemiBold"/>
                                    <TextBlock Text="@@rp_sub@@" Foreground="#8A919C" FontSize="13" Margin="0,3,0,0" TextTrimming="CharacterEllipsis"/>
                                </StackPanel>
                                <Border Grid.Row="1" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="6,4,2,6">
                                    <Grid>
                                        <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                        <Grid Margin="10,6,22,6">
                                            <TextBlock Text="@@rp_col_item@@" Style="{StaticResource NavCaption}" Margin="0"/>
                                            <TextBlock Text="@@rp_col_note@@" Style="{StaticResource NavCaption}" Margin="0" HorizontalAlignment="Right"/>
                                        </Grid>
                                        <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                            <StackPanel x:Name="pnlRepairList" Margin="4,6,8,0">
                                                <TreeView x:Name="tvRepair" Style="{StaticResource CleanTree}"/>
                                            </StackPanel>
                                        </ScrollViewer>
                                    </Grid>
                                </Border>
                            </Grid>
                            <Border Grid.Column="2" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="18,16">
                                <DockPanel LastChildFill="True">
                                    <StackPanel DockPanel.Dock="Bottom" Margin="0,12,0,0">
                                        <TextBlock Text="@@rp_quick@@" Style="{StaticResource NavCaption}" Margin="0,0,0,8"/>
                                        <Button x:Name="btnFixUpdate" Style="{StaticResource RepairCardBtn}" ToolTip="Windows Update onarımı: servisleri (wuauserv, bits, cryptSvc) sıfırla + SoftwareDistribution/catroot2 önbelleğini temizle + policy düzelt. 'Update çalışmıyor' sorunları için.">
                                            <Grid> <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                                <TextBlock Style="{StaticResource NavIcon}" Text="&#xE895;" Foreground="#E0A23B" VerticalAlignment="Top" Margin="0,2,12,0"/>
                                                <StackPanel Grid.Column="1"> <TextBlock Text="@@rp_fixupdate@@" FontWeight="SemiBold" Foreground="#E6E8EB"/> <TextBlock Text="@@rp_fixupdate_d@@" FontSize="12" Foreground="#8A919C" TextWrapping="Wrap" Margin="0,2,0,0"/> </StackPanel>
                                            </Grid>
                                        </Button>
                                        <Button x:Name="btnResetNet" Style="{StaticResource RepairCardBtn}" ToolTip="TCP/IP + WinSock + DNS ayarlarını sıfırlar (5 adım). Sürücülere DOKUNMAZ. Günlük ağ sorunları için ilk denenecek seçenek. Ağaçtaki 'Netcfg' bundan çok daha sert (tüm ağ sürücülerini kaldırır).">
                                            <Grid> <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                                <TextBlock Style="{StaticResource NavIcon}" Text="&#xE839;" Foreground="#4C8DFF" VerticalAlignment="Top" Margin="0,2,12,0"/>
                                                <StackPanel Grid.Column="1"> <TextBlock Text="@@rp_resetnet@@" FontWeight="SemiBold" Foreground="#E6E8EB"/> <TextBlock Text="@@rp_resetnet_d@@" FontSize="12" Foreground="#8A919C" TextWrapping="Wrap" Margin="0,2,0,0"/> </StackPanel>
                                            </Grid>
                                        </Button>
                                        <Button x:Name="btnFixAmd" Style="{StaticResource RepairCardBtn}" Margin="0" ToolTip="AMD Chipset Software güncellenemiyor / kaldırılamıyorsa ('Eksik dosyalar', 1603, 'yalnızca yüklü ürünler için geçerli'): bozuk Windows Installer kayıtlarını bulur, yedekler ve temizler. Sürücülere dokunmaz; ardından yeni AMD yükleyicisi temiz kurulum yapar.">
                                            <Grid> <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                                <TextBlock Style="{StaticResource NavIcon}" Text="&#xE950;" Foreground="#E07B4C" VerticalAlignment="Top" Margin="0,2,12,0"/>
                                                <StackPanel Grid.Column="1"> <TextBlock Text="@@rp_fixamd@@" FontWeight="SemiBold" Foreground="#E6E8EB"/> <TextBlock Text="@@rp_fixamd_d@@" FontSize="12" Foreground="#8A919C" TextWrapping="Wrap" Margin="0,2,0,0"/> </StackPanel>
                                            </Grid>
                                        </Button>
                                    </StackPanel>
                                    <StackPanel DockPanel.Dock="Bottom">
                                        <Button x:Name="btnRepairStart" Style="{StaticResource BtnPrimary}" Height="42" FontSize="15" Margin="0,14,0,0" Content="{Binding Content, ElementName=btnRun}" IsEnabled="{Binding IsEnabled, ElementName=btnRun}" Background="{Binding Background, ElementName=btnRun}" BorderBrush="{Binding Background, ElementName=btnRun}"/>
                                        <Border Height="1" Background="#232831" Margin="0,16,0,0"/>
                                    </StackPanel>
                                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                        <StackPanel>
                                            <TextBlock Text="@@cl_selected@@" Style="{StaticResource NavCaption}" Margin="0,0,0,6"/>
                                            <TextBlock x:Name="txtRepairSelCount" Text="0" Foreground="#E6E8EB" FontSize="32" FontWeight="SemiBold"/>
                                            <StackPanel x:Name="pnlRepairSelected" Margin="0,8,0,0"/>
                                            <TextBlock x:Name="txtRepairWarn" Text="" Foreground="#E0A23B" FontSize="13" Margin="0,8,0,0" TextWrapping="Wrap" Visibility="Collapsed"/>
                                            <Button x:Name="btnRepairUnselect" Style="{StaticResource BtnSecondary}" Content="@@cl_unselect@@" HorizontalAlignment="Left" Padding="14,0" Margin="0,12,0,0"/>
                                        </StackPanel>
                                    </ScrollViewer>
                                </DockPanel>
                            </Border>
                        </Grid>
                    </TabItem>
                    <TabItem Header="@@tab_tools@@" x:Name="tabTools">
                        <!-- v1.3.0 (tasarım E): araç kartları iki grupta; düğme adları ve olayları aynı -->
                        <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                            <StackPanel Margin="16,12,14,12">
                                <TextBlock Text="@@tab_tools@@" Foreground="#E6E8EB" FontSize="22" FontWeight="SemiBold"/>
                                <TextBlock Text="@@to_sub@@" Foreground="#8A919C" FontSize="13" Margin="0,3,0,0" TextWrapping="Wrap"/>
                                <TextBlock Text="@@to_grp_measure@@" Style="{StaticResource NavCaption}" Margin="0,22,0,10"/>
                                <UniformGrid Columns="3" Margin="0,0,-12,0">
                                    <Button x:Name="btnBenchmark" Style="{StaticResource ToolCardBtn}" ToolTip="6 metrik performans ölçümü — tweak öncesi/sonrası snapshot al, karşılaştır (Timer, Ping, DNS, DPC, RAM)">
                                        <StackPanel> <Border Style="{StaticResource ToolCardIconBox}"><TextBlock Style="{StaticResource ToolCardIcon}" Text="&#xE9D9;"/></Border> <TextBlock Text="@@to_bench@@" Style="{StaticResource ToolCardTitle}"/> <TextBlock Text="@@to_bench_d@@" Style="{StaticResource ToolCardDesc}"/> </StackPanel>
                                    </Button>
                                    <Button x:Name="btnTimerResTest" Style="{StaticResource ToolCardBtn}" ToolTip="Timer Resolution canlı test + Otomatik İnce Ayar + Stress Bench (valleyofdoom/SwiftyPop algoritması)">
                                        <StackPanel> <Border Style="{StaticResource ToolCardIconBox}"><TextBlock Style="{StaticResource ToolCardIcon}" Text="&#xE916;"/></Border> <TextBlock Text="@@to_timer@@" Style="{StaticResource ToolCardTitle}"/> <TextBlock Text="@@to_timer_d@@" Style="{StaticResource ToolCardDesc}"/> </StackPanel>
                                    </Button>
                                    <Button x:Name="btnNetQuality" Style="{StaticResource ToolCardBtn}" ToolTip="Gercek internet hizi + yuk altinda gecikme (bufferbloat) olcumu ve hattiniza gore oneriler">
                                        <StackPanel> <Border Style="{StaticResource ToolCardIconBox}"><TextBlock Style="{StaticResource ToolCardIcon}" Text="&#xE701;"/></Border> <TextBlock Text="@@to_net@@" Style="{StaticResource ToolCardTitle}"/> <TextBlock Text="@@to_net_d@@" Style="{StaticResource ToolCardDesc}"/> </StackPanel>
                                    </Button>
                                </UniformGrid>
                                <TextBlock Text="@@to_grp_system@@" Style="{StaticResource NavCaption}" Margin="0,10,0,10"/>
                                <UniformGrid Columns="3" Margin="0,0,-12,0">
                                    <Button x:Name="btnAudioProfile" Style="{StaticResource ToolCardBtn}" ToolTip="Tek tikla: Equalizer APO kurulumu, tum ses aygitlarini otomatik algilama, kulaklik modeli (AutoEq), oyun acilinca Oyun modu, temiz mikrofon">
                                        <StackPanel> <Border Style="{StaticResource ToolCardIconBox}"><TextBlock Style="{StaticResource ToolCardIcon}" Text="&#xE8D6;"/></Border> <TextBlock Text="@@to_audio@@" Style="{StaticResource ToolCardTitle}"/> <TextBlock Text="@@to_audio_d@@" Style="{StaticResource ToolCardDesc}"/> </StackPanel>
                                    </Button>
                                    <Button x:Name="btnDefenderExc" Style="{StaticResource ToolCardBtn}" ToolTip="Windows Defender Exclusion Manager — oyun klasörlerini AV scan'inden hariç tut (Steam/Epic/EA/Riot/Battle.net/Ubisoft/GOG auto-detect)">
                                        <StackPanel> <Border Style="{StaticResource ToolCardIconBox}"><TextBlock Style="{StaticResource ToolCardIcon}" Text="&#xEA18;"/></Border> <TextBlock Text="@@to_defender@@" Style="{StaticResource ToolCardTitle}"/> <TextBlock Text="@@to_defender_d@@" Style="{StaticResource ToolCardDesc}"/> </StackPanel>
                                    </Button>
                                    <Button x:Name="btnActivityLog" Style="{StaticResource ToolCardBtn}" ToolTip="Apply / Undo geçmişi — son 100 işlem, tek tek veya toplu geri alma">
                                        <StackPanel> <Border Style="{StaticResource ToolCardIconBox}"><TextBlock Style="{StaticResource ToolCardIcon}" Text="&#xE81C;"/></Border> <TextBlock Text="@@to_activity@@" Style="{StaticResource ToolCardTitle}"/> <TextBlock Text="@@to_activity_d@@" Style="{StaticResource ToolCardDesc}"/> </StackPanel>
                                    </Button>
                                    <!-- v1.3.0 (§78): sürücü yedeği eski Araçlar menüsünden karta taşındı (Onizleme8 onaylı) -->
                                    <Button x:Name="btnDriverBackup" Style="{StaticResource ToolCardBtn}" ToolTip="DISM ile kurulu sürücüleri seçtiğiniz klasöre dışa aktarır">
                                        <StackPanel> <Border Style="{StaticResource ToolCardIconBox}"><TextBlock Style="{StaticResource ToolCardIcon}" Text="&#xE7B8;"/></Border> <TextBlock Text="@@to_drivers@@" Style="{StaticResource ToolCardTitle}"/> <TextBlock Text="@@to_drivers_d@@" Style="{StaticResource ToolCardDesc}"/> </StackPanel>
                                    </Button>
                                </UniformGrid>
                            </StackPanel>
                        </ScrollViewer>
                    </TabItem>
                    <TabItem Header="@@tab_winget@@" x:Name="tabWinget">
                        <!-- v1.3.0 (tasarım E): arama + çipler, solda liste, sağda seçim özeti + kur/kaldır + bakım kartları -->
                        <Grid Margin="16,12,14,12">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="16"/> <ColumnDefinition Width="300"/> </Grid.ColumnDefinitions>
                            <Grid Grid.Column="0">
                                <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                <Grid Grid.Row="0" Margin="0,0,0,12">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <StackPanel>
                                        <TextBlock Text="@@tab_winget@@" Foreground="#E6E8EB" FontSize="22" FontWeight="SemiBold"/>
                                        <TextBlock x:Name="txtWingetSub" Text="" Foreground="#8A919C" FontSize="13" Margin="0,3,0,0" TextTrimming="CharacterEllipsis"/>
                                    </StackPanel>
                                    <Button x:Name="btnManageWinget" Grid.Column="1" Style="{StaticResource BtnSecondary}" Content="@@wg_manage@@" Padding="14,0" VerticalAlignment="Center"/>
                                    <Button x:Name="btnRefreshWinget" Grid.Column="2" Style="{StaticResource BtnSecondary}" Content="@@wg_refresh@@" MinWidth="110" Padding="14,0" Margin="8,0,0,0" VerticalAlignment="Center"/>
                                </Grid>
                                <TextBox x:Name="txtWingetSearch" Grid.Row="1" Style="{StaticResource SearchBox}" Tag="@@wg_search_ph@@" MaxWidth="420" HorizontalAlignment="Left" Width="420" Margin="0,0,0,10"/>
                                <WrapPanel Grid.Row="2" Margin="0,0,0,4">
                                    <RadioButton x:Name="chipWgAll" GroupName="WingetChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_all@@" IsChecked="True"/>
                                    <RadioButton x:Name="chipWgInstalled" GroupName="WingetChips" Style="{StaticResource ChipStyle}" Content="@@wg_chip_installed@@"/>
                                    <RadioButton x:Name="chipWgMissing" GroupName="WingetChips" Style="{StaticResource ChipStyle}" Content="@@wg_chip_missing@@"/>
                                    <RadioButton x:Name="chipWgAppx" GroupName="WingetChips" Style="{StaticResource ChipStyle}" Content="@@wg_chip_appx@@"/>
                                </WrapPanel>
                                <Border Grid.Row="3" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="6,4,2,6">
                                    <Grid>
                                        <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                        <Grid Margin="10,6,22,6">
                                            <TextBlock Text="@@wg_col_app@@" Style="{StaticResource NavCaption}" Margin="0"/>
                                            <TextBlock Text="@@wg_col_state@@" Style="{StaticResource NavCaption}" Margin="0" HorizontalAlignment="Right"/>
                                        </Grid>
                                        <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                            <StackPanel x:Name="pnlWingetList" Margin="4,6,8,0">
                                                <TreeView x:Name="tvWinget" Style="{StaticResource CleanTree}"/>
                                            </StackPanel>
                                        </ScrollViewer>
                                    </Grid>
                                </Border>
                            </Grid>
                            <Border Grid.Column="2" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="18,16">
                                <DockPanel LastChildFill="True">
                                    <StackPanel DockPanel.Dock="Bottom" Margin="0,12,0,0">
                                        <TextBlock Text="@@wg_maint@@" Style="{StaticResource NavCaption}" Margin="0,0,0,8"/>
                                        <Button x:Name="btnWingetUpdateAll" Style="{StaticResource RepairCardBtn}">
                                            <Grid> <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                                <TextBlock Style="{StaticResource NavIcon}" Text="&#xE895;" Foreground="#4C8DFF" VerticalAlignment="Top" Margin="0,2,6,0"/>
                                                <StackPanel Grid.Column="1"> <TextBlock Text="@@wg_updateall@@" FontWeight="SemiBold" Foreground="#E6E8EB"/> <TextBlock Text="@@wg_updateall_d@@" FontSize="12" Foreground="#8A919C" TextWrapping="Wrap" Margin="0,2,0,0"/> </StackPanel>
                                            </Grid>
                                        </Button>
                                        <Button x:Name="btnBloatware" Style="{StaticResource RepairCardBtn}" Margin="0">
                                            <Grid> <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                                <TextBlock Style="{StaticResource NavIcon}" Text="&#xE74D;" Foreground="#E07B6A" VerticalAlignment="Top" Margin="0,2,6,0"/>
                                                <StackPanel Grid.Column="1"> <TextBlock Text="@@wg_bloat@@" FontWeight="SemiBold" Foreground="#E6E8EB"/> <TextBlock Text="@@wg_bloat_d@@" FontSize="12" Foreground="#8A919C" TextWrapping="Wrap" Margin="0,2,0,0"/> </StackPanel>
                                            </Grid>
                                        </Button>
                                    </StackPanel>
                                    <StackPanel DockPanel.Dock="Bottom">
                                        <Button x:Name="btnInstallWinget" Style="{StaticResource BtnPrimary}" Height="40" FontSize="14" Margin="0,14,0,0" Content="@@wg_install@@"/>
                                        <Button x:Name="btnUninstallWinget" Style="{StaticResource BtnDanger}" Height="36" Margin="0,8,0,0" Content="@@wg_uninstall@@"/>
                                        <Border Height="1" Background="#232831" Margin="0,16,0,0"/>
                                    </StackPanel>
                                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                        <StackPanel>
                                            <TextBlock Text="@@cl_selected@@" Style="{StaticResource NavCaption}" Margin="0,0,0,6"/>
                                            <TextBlock x:Name="txtWingetSelCount" Text="0" Foreground="#E6E8EB" FontSize="32" FontWeight="SemiBold"/>
                                            <TextBlock x:Name="txtWingetSelSub" Text="" Foreground="#8A919C" FontSize="13" Margin="0,2,0,0" TextWrapping="Wrap"/>
                                            <Button x:Name="btnWingetUnselect" Style="{StaticResource BtnSecondary}" Content="@@cl_unselect@@" HorizontalAlignment="Left" Padding="14,0" Margin="0,12,0,0"/>
                                        </StackPanel>
                                    </ScrollViewer>
                                </DockPanel>
                            </Border>
                        </Grid>
                    </TabItem>
                    <TabItem Header="@@tab_tweaks@@" x:Name="tabTweaks">
                        <!-- v1.3.0 (tasarım E, 2. adım): başlık + eylemler üstte, liste kartta. x:Name'ler aynı. -->
                        <Grid Margin="14,10,12,10">
                            <Grid.RowDefinitions>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="*"/>
                            </Grid.RowDefinitions>

                            <Grid Grid.Row="0">
                                <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                <StackPanel VerticalAlignment="Center" Margin="0,0,12,0">
                                    <TextBlock Text="@@tab_tweaks@@" FontSize="24" FontWeight="SemiBold" FontFamily="{DynamicResource UiFontHead}" Foreground="#E6E8EB"/>
                                    <TextBlock x:Name="txtTweakWinInfo" Text="" Foreground="#8A919C" FontSize="13" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                </StackPanel>
                                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                                    <Button x:Name="btnCheckTweaks" Content="@@btn_check@@" Style="{StaticResource BtnSecondary}" Margin="0,0,8,0"/>
                                    <Button x:Name="btnApplyTweaks" Content="@@btn_apply@@" Style="{StaticResource BtnPrimary}" MinWidth="110"/>
                                </StackPanel>
                            </Grid>

                            <Grid Grid.Row="1" Margin="0,14,0,0">
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="*" MinWidth="160"/>
                                    <ColumnDefinition Width="Auto"/>
                                    <ColumnDefinition Width="Auto"/>
                                </Grid.ColumnDefinitions>
                                <TextBox x:Name="txtTweakSearch" Grid.Column="0" Style="{StaticResource SearchBox}" Tag="@@tw_search_ph@@" ToolTip="@@tw_filter_tip@@"/>
                                <Button x:Name="btnTweakSearchClear" Grid.Column="1" Content="✕" Style="{StaticResource BtnGhostIcon}" Margin="4,0,0,0" ToolTip="@@tw_filter_clear@@"/>
                                <StackPanel Grid.Column="2" Orientation="Horizontal" Margin="8,0,0,0">
                                    <Button x:Name="btnProfile" Content="@@btn_profile@@" Style="{StaticResource BtnSecondary}" Margin="0,0,8,0"/>
                                    <Button x:Name="btnSaveProfile" Content="@@btn_saveprofile@@" Style="{StaticResource BtnSecondary}" Margin="0,0,8,0"/>
                                    <Button x:Name="btnQuickUndo" Content="@@btn_quickundo@@" Style="{StaticResource BtnUndo}" Margin="0,0,8,0" IsEnabled="False" ToolTip="Son uygulanan tweak setini tersine çevirir."/>
                                    <Button x:Name="btnManageTweaks" Content="@@btn_manage@@" Style="{StaticResource BtnSecondary}"/>
                                </StackPanel>
                            </Grid>

                            <Grid Grid.Row="2" Margin="0,12,0,0">
                                <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                <WrapPanel>
                                    <RadioButton x:Name="chipTwAll"     GroupName="TweakChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_all@@" IsChecked="True"/>
                                    <RadioButton x:Name="chipTwActive"  GroupName="TweakChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_active@@"/>
                                    <RadioButton x:Name="chipTwPassive" GroupName="TweakChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_passive@@"/>
                                    <RadioButton x:Name="chipTwNew"     GroupName="TweakChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_new@@"/>
                                    <RadioButton x:Name="chipTwRisky"   GroupName="TweakChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_risky@@"/>
                                    <RadioButton x:Name="chipTwReboot"  GroupName="TweakChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_reboot@@"/>
                                </WrapPanel>
                                <TextBlock x:Name="txtTweakFilterCount" Grid.Column="1" Text="" Foreground="#8A919C" FontSize="13" VerticalAlignment="Top" Margin="10,6,0,0" TextWrapping="NoWrap"/>
                            </Grid>

                            <Grid Grid.Row="3" Margin="0,2,0,10" Height="4" ToolTip="@@tw_progress_tip@@">
                                <Border x:Name="bdTweakProgressTrack" Height="4" CornerRadius="2" Background="#252A33"/>
                                <Border x:Name="bdTweakProgressFill" Height="4" CornerRadius="2" HorizontalAlignment="Left" Width="0">
                                    <Border.Background>
                                        <LinearGradientBrush StartPoint="0,0" EndPoint="1,0">
                                            <GradientStop Color="#4C8DFF" Offset="0"/>
                                            <GradientStop Color="#3FB97A" Offset="1"/>
                                        </LinearGradientBrush>
                                    </Border.Background>
                                </Border>
                            </Grid>

                            <Grid Grid.Row="4">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="320"/> <ColumnDefinition Width="12"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                            <Border Grid.Column="0" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="8,12,8,8">
                                <DockPanel>
                                    <TextBlock DockPanel.Dock="Top" Text="@@tw_cats_title@@" Style="{StaticResource NavCaption}" Margin="6,0,0,8"/>
                                    <ListBox x:Name="lstTweakCats" Background="Transparent" BorderThickness="0" ItemContainerStyle="{StaticResource TweakCatListItem}" ScrollViewer.HorizontalScrollBarVisibility="Disabled"/>
                                </DockPanel>
                            </Border>
                            <Border Grid.Column="2" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="4,6,2,6">
                                <TreeView x:Name="tvTweaks" BorderThickness="0" Background="Transparent" ScrollViewer.HorizontalScrollBarVisibility="Disabled" VirtualizingStackPanel.IsVirtualizing="True" VirtualizingStackPanel.VirtualizationMode="Recycling">
                                    <TreeView.Resources>
                                        <!-- v1.3.0: varsayilan mavi secim vurgusunu kaldir (satir hover vurgusu kendi Border'inda) -->
                                        <SolidColorBrush x:Key="{x:Static SystemColors.HighlightBrushKey}" Color="Transparent"/>
                                        <SolidColorBrush x:Key="{x:Static SystemColors.InactiveSelectionHighlightBrushKey}" Color="Transparent"/>
                                        <SolidColorBrush x:Key="{x:Static SystemColors.HighlightTextBrushKey}" Color="White"/>
                                        <!-- alt kategori başlığı (üç durumlu CheckBox); tweak satırları kendi TweakRowToggle stilini kullanır -->
                                        <Style TargetType="CheckBox" BasedOn="{StaticResource TreeCheck}"/>
                                    </TreeView.Resources>
                                    <TreeView.ItemContainerStyle>
                                        <Style TargetType="{x:Type TreeViewItem}">
                                            <Setter Property="IsExpanded" Value="True"/>
                                            <Setter Property="Foreground" Value="#E6E8EB"/>
                                            <Setter Property="Padding" Value="5,2"/>
                                        </Style>
                                    </TreeView.ItemContainerStyle>
                                </TreeView>
                            </Border>
                            </Grid>
                        </Grid>
                    </TabItem>
					<TabItem Header="@@tab_startup@@" x:Name="tabStartup">
                        <!-- v1.3.0 (tasarım E): segment + arama + çipler, solda anahtarlı liste, sağda seçili öğe ayrıntısı ve eylemler (sağ tık menüsüyle aynı işler) -->
                        <Grid Margin="16,12,14,12">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="16"/> <ColumnDefinition Width="300"/> </Grid.ColumnDefinitions>
                            <Grid Grid.Column="0">
                                <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                <Grid Grid.Row="0" Margin="0,0,0,12">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <StackPanel>
                                        <TextBlock Text="@@tab_startup@@" Foreground="#E6E8EB" FontSize="22" FontWeight="SemiBold"/>
                                        <TextBlock x:Name="txtStartupSub" Text="" Foreground="#8A919C" FontSize="13" Margin="0,3,0,0" TextTrimming="CharacterEllipsis"/>
                                    </StackPanel>
                                    <Button x:Name="btnRefreshStartup" Grid.Column="1" Style="{StaticResource BtnSecondary}" Content="@@su_refresh@@" MinWidth="110" Padding="14,0" VerticalAlignment="Center"/>
                                </Grid>
                                <Grid Grid.Row="1" Margin="0,0,0,10">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="12"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                    <Border Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="3">
                                        <StackPanel Orientation="Horizontal">
                                            <RadioButton x:Name="rbStartupWin" GroupName="StartupSeg" Style="{StaticResource SegItem}" Content="@@su_seg_apps@@" Width="130" IsChecked="True"/>
                                            <RadioButton x:Name="rbStartupTask" GroupName="StartupSeg" Style="{StaticResource SegItem}" Content="@@su_seg_tasks@@" Width="160"/>
                                        </StackPanel>
                                    </Border>
                                    <TextBox x:Name="txtStartupSearch" Grid.Column="2" Style="{StaticResource SearchBox}" Tag="@@su_search_ph@@" MaxWidth="360" HorizontalAlignment="Left" Width="360" VerticalAlignment="Center"/>
                                </Grid>
                                <WrapPanel Grid.Row="2" Margin="0,0,0,4">
                                    <RadioButton x:Name="chipSuAll" GroupName="StartupChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_all@@" IsChecked="True"/>
                                    <RadioButton x:Name="chipSuOn" GroupName="StartupChips" Style="{StaticResource ChipStyle}" Content="@@su_chip_on@@"/>
                                    <RadioButton x:Name="chipSuOff" GroupName="StartupChips" Style="{StaticResource ChipStyle}" Content="@@su_chip_off@@"/>
                                </WrapPanel>
                                <Border Grid.Row="3" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="6,6,2,6">
                                    <Grid>
                                        <ListView x:Name="lvStartup" Background="Transparent" BorderThickness="0" Foreground="#E6E8EB" ContextMenu="{StaticResource StartupItemMenu}"
                                                  ScrollViewer.HorizontalScrollBarVisibility="Disabled" HorizontalContentAlignment="Stretch" SelectionMode="Single">
                                            <!-- Liste her değişiklikte yeniden çizildiği için ToggleSwitch animasyonu tüm açık anahtarlarda tekrar oynardı; burada animasyonsuz -->
                                            <ListView.Resources>
                                                <Style x:Key="SuSwitch" TargetType="CheckBox">
                                                    <Setter Property="Cursor" Value="Hand"/>
                                                    <Setter Property="Template">
                                                        <Setter.Value>
                                                            <ControlTemplate TargetType="CheckBox">
                                                                <Grid Width="40" Height="20" Margin="2" Background="Transparent" VerticalAlignment="Center">
                                                                    <Border x:Name="Border" CornerRadius="10" Background="Transparent" BorderThickness="1.5" BorderBrush="#5A6170"/>
                                                                    <Ellipse x:Name="Dot" Fill="#A9B0BB" Width="12" Height="12" HorizontalAlignment="Left" Margin="4,0,0,0"/>
                                                                </Grid>
                                                                <ControlTemplate.Triggers>
                                                                    <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Border" Property="BorderBrush" Value="#8A919C"/> </Trigger>
                                                                    <Trigger Property="IsChecked" Value="True">
                                                                        <Setter TargetName="Border" Property="Background" Value="#4C8DFF"/>
                                                                        <Setter TargetName="Border" Property="BorderBrush" Value="#4C8DFF"/>
                                                                        <Setter TargetName="Dot" Property="Fill" Value="White"/>
                                                                        <Setter TargetName="Dot" Property="Margin" Value="24,0,0,0"/>
                                                                    </Trigger>
                                                                </ControlTemplate.Triggers>
                                                            </ControlTemplate>
                                                        </Setter.Value>
                                                    </Setter>
                                                </Style>
                                            </ListView.Resources>
                                            <ListView.ItemContainerStyle>
                                                <Style TargetType="ListViewItem">
                                                    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
                                                    <Setter Property="Margin" Value="0,0,6,1"/>
                                                    <Setter Property="Template">
                                                        <Setter.Value>
                                                            <ControlTemplate TargetType="ListViewItem">
                                                                <Border x:Name="Bd" Background="Transparent" CornerRadius="6" Padding="10,7,10,7">
                                                                    <ContentPresenter/>
                                                                </Border>
                                                                <ControlTemplate.Triggers>
                                                                    <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#181C23"/> </Trigger>
                                                                    <Trigger Property="IsSelected" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1C2433"/> </Trigger>
                                                                </ControlTemplate.Triggers>
                                                            </ControlTemplate>
                                                        </Setter.Value>
                                                    </Setter>
                                                </Style>
                                            </ListView.ItemContainerStyle>
                                            <ListView.ItemTemplate>
                                                <DataTemplate>
                                                    <Grid>
                                                        <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                                        <CheckBox Style="{StaticResource SuSwitch}" IsChecked="{Binding IsEnabled, Mode=OneWay}" VerticalAlignment="Center" Margin="0,0,10,0" Focusable="False"/>
                                                        <StackPanel Grid.Column="1" Opacity="{Binding RowOpacity}" VerticalAlignment="Center">
                                                            <TextBlock Text="{Binding Name}" FontSize="14" FontWeight="SemiBold" Foreground="#E6E8EB" TextTrimming="CharacterEllipsis"/>
                                                            <TextBlock Text="{Binding Detail}" ToolTip="{Binding Path}" FontSize="12" Foreground="#5D6470" Margin="0,1,0,0" TextTrimming="CharacterEllipsis"/>
                                                        </StackPanel>
                                                    </Grid>
                                                </DataTemplate>
                                            </ListView.ItemTemplate>
                                        </ListView>
                                        <TextBlock x:Name="txtStartupEmpty" Text="@@su_empty@@" Foreground="#5D6470" FontSize="13" HorizontalAlignment="Center" VerticalAlignment="Center" Visibility="Collapsed"/>
                                    </Grid>
                                </Border>
                            </Grid>
                            <Border Grid.Column="2" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="18,16">
                                <DockPanel LastChildFill="True">
                                    <Border DockPanel.Dock="Bottom" Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,12,0,0">
                                        <TextBlock x:Name="txtStartupNote" Text="" FontSize="12" Foreground="#8A919C" TextWrapping="Wrap"/>
                                    </Border>
                                    <StackPanel x:Name="pnlStartupActions" DockPanel.Dock="Bottom" IsEnabled="False">
                                        <Button x:Name="btnSuOpenLoc" Style="{StaticResource BtnSecondary}" Content="@@su_open_loc@@" Height="34" Margin="0,8,0,0"/>
                                        <Button x:Name="btnSuCopyPath" Style="{StaticResource BtnSecondary}" Content="@@su_copy_path@@" Height="34" Margin="0,8,0,0"/>
                                        <Button x:Name="btnSuOpenReg" Style="{StaticResource BtnSecondary}" Content="@@su_open_reg@@" Height="34" Margin="0,8,0,0"/>
                                        <Button x:Name="btnSuDelete" Style="{StaticResource BtnDanger}" Content="@@su_delete@@" Height="34" Margin="0,8,0,0"/>
                                    </StackPanel>
                                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                        <StackPanel>
                                            <TextBlock Text="@@su_selected@@" Style="{StaticResource NavCaption}" Margin="0,0,0,8"/>
                                            <TextBlock x:Name="txtSuSelName" Text="@@su_pick@@" Foreground="#8A919C" FontSize="17" FontWeight="SemiBold" TextWrapping="Wrap"/>
                                            <TextBlock x:Name="txtSuSelState" Text="" FontSize="13" FontWeight="SemiBold" Margin="0,4,0,0"/>
                                            <StackPanel x:Name="pnlSuSelInfo" Visibility="Collapsed">
                                                <TextBlock Text="@@su_lbl_source@@" Style="{StaticResource NavCaption}" Margin="0,16,0,4"/>
                                                <TextBlock x:Name="txtSuSelSource" Text="" Foreground="#C9CED6" FontSize="13" TextWrapping="Wrap"/>
                                                <TextBlock x:Name="lblSuSelDelay" Text="@@su_lbl_delay@@" Style="{StaticResource NavCaption}" Margin="0,12,0,4"/>
                                                <TextBlock x:Name="txtSuSelDelay" Text="" Foreground="#C9CED6" FontSize="13"/>
                                                <TextBlock Text="@@su_lbl_cmd@@" Style="{StaticResource NavCaption}" Margin="0,12,0,4"/>
                                                <TextBox x:Name="txtSuSelPath" Text="" IsReadOnly="True" Background="Transparent" BorderThickness="0" Foreground="#C9CED6" FontSize="12.5" TextWrapping="Wrap" Padding="0" FontFamily="Cascadia Mono, Consolas"/>
                                            </StackPanel>
                                        </StackPanel>
                                    </ScrollViewer>
                                </DockPanel>
                            </Border>
                        </Grid>
                    </TabItem>
					<!-- BÜYÜK DOSYA AVCISI -->
                    <TabItem Header="@@tab_largefiles@@" x:Name="tabLargeFiles">
                        <!-- v1.3.0 (tasarım E): hedef segmenti + boyut çipleri, solda boyut önde liste, sağda toplam + seçili dosya.
                             cbScanTarget / cbMinSize gizli; segment ve çipler onların SelectedIndex'ini eşitler (Start-LargeFileScan onları okur). -->
                        <Grid Margin="16,12,14,12">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="16"/> <ColumnDefinition Width="300"/> </Grid.ColumnDefinitions>
                            <Grid Grid.Column="0">
                                <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                <Grid Grid.Row="0" Margin="0,0,0,12">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <StackPanel>
                                        <TextBlock Text="@@tab_largefiles@@" Foreground="#E6E8EB" FontSize="22" FontWeight="SemiBold"/>
                                        <TextBlock x:Name="txtLargeStatus" Text="@@lf_ready@@" Foreground="#8A919C" FontSize="13" Margin="0,3,0,0" TextTrimming="CharacterEllipsis"/>
                                    </StackPanel>
                                    <Button x:Name="btnScanFiles" Grid.Column="1" Style="{StaticResource BtnPrimary}" Content="@@lf_scan@@" MinWidth="120" Height="34" Padding="18,0" VerticalAlignment="Center"/>
                                </Grid>
                                <ComboBox x:Name="cbScanTarget" Grid.Row="0" Visibility="Collapsed" SelectedIndex="0">
                                    <ComboBoxItem Content="@@lf_userfolders@@"/>
                                    <ComboBoxItem Content="@@lf_cdisk@@"/>
                                    <ComboBoxItem Content="@@lf_customfolder@@"/>
                                </ComboBox>
                                <ComboBox x:Name="cbMinSize" Grid.Row="0" Visibility="Collapsed" SelectedIndex="1">
                                    <ComboBoxItem Content="> 50 MB" Tag="52428800"/>
                                    <ComboBoxItem Content="> 100 MB" Tag="104857600"/>
                                    <ComboBoxItem Content="> 500 MB" Tag="524288000"/>
                                    <ComboBoxItem Content="> 1 GB" Tag="1073741824"/>
                                </ComboBox>
                                <Grid Grid.Row="1" Margin="0,0,0,10">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="12"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <Border Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="3">
                                        <StackPanel Orientation="Horizontal">
                                            <RadioButton x:Name="rbLfUser" GroupName="LfTarget" Style="{StaticResource SegItem}" Content="@@lf_seg_user@@" MinWidth="130" IsChecked="True"/>
                                            <RadioButton x:Name="rbLfDisk" GroupName="LfTarget" Style="{StaticResource SegItem}" Content="@@lf_seg_disk@@" MinWidth="100"/>
                                            <RadioButton x:Name="rbLfCustom" GroupName="LfTarget" Style="{StaticResource SegItem}" Content="@@lf_seg_custom@@" MinWidth="110"/>
                                        </StackPanel>
                                    </Border>
                                    <Border Grid.Column="2" Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="3">
                                        <StackPanel Orientation="Horizontal">
                                            <RadioButton x:Name="rbLfMin50" GroupName="LfMin" Style="{StaticResource SegItem}" Content="50 MB+" MinWidth="70"/>
                                            <RadioButton x:Name="rbLfMin100" GroupName="LfMin" Style="{StaticResource SegItem}" Content="100 MB+" MinWidth="76" IsChecked="True"/>
                                            <RadioButton x:Name="rbLfMin500" GroupName="LfMin" Style="{StaticResource SegItem}" Content="500 MB+" MinWidth="76"/>
                                            <RadioButton x:Name="rbLfMin1G" GroupName="LfMin" Style="{StaticResource SegItem}" Content="1 GB+" MinWidth="64"/>
                                        </StackPanel>
                                    </Border>
                                </Grid>
                                <Grid Grid.Row="2" Margin="0,0,0,10">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <TextBox x:Name="txtLfSearch" Style="{StaticResource SearchBox}" Tag="@@lf_search_ph@@" Width="320" VerticalAlignment="Center"/>
                                    <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
                                        <TextBlock Text="@@lf_sort@@" Foreground="#8A919C" FontSize="13" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                        <Border Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="3">
                                            <StackPanel Orientation="Horizontal">
                                                <RadioButton x:Name="rbLfSortSize" GroupName="LfSort" Style="{StaticResource SegItem}" Content="@@lf_sort_size@@" MinWidth="64" IsChecked="True"/>
                                                <RadioButton x:Name="rbLfSortDate" GroupName="LfSort" Style="{StaticResource SegItem}" Content="@@lf_sort_date@@" MinWidth="64"/>
                                                <RadioButton x:Name="rbLfSortName" GroupName="LfSort" Style="{StaticResource SegItem}" Content="@@lf_sort_name@@" MinWidth="56"/>
                                            </StackPanel>
                                        </Border>
                                    </StackPanel>
                                </Grid>
                                <WrapPanel Grid.Row="3" Margin="0,0,0,4">
                                    <RadioButton x:Name="chipLfAll" GroupName="LfChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_all@@" IsChecked="True"/>
                                    <RadioButton x:Name="chipLfVideo" GroupName="LfChips" Style="{StaticResource ChipStyle}" Content="@@lf_chip_video@@"/>
                                    <RadioButton x:Name="chipLfArchive" GroupName="LfChips" Style="{StaticResource ChipStyle}" Content="@@lf_chip_archive@@"/>
                                    <RadioButton x:Name="chipLfImage" GroupName="LfChips" Style="{StaticResource ChipStyle}" Content="@@lf_chip_image@@"/>
                                    <RadioButton x:Name="chipLfSetup" GroupName="LfChips" Style="{StaticResource ChipStyle}" Content="@@lf_chip_setup@@"/>
                                    <RadioButton x:Name="chipLfOther" GroupName="LfChips" Style="{StaticResource ChipStyle}" Content="@@lf_chip_other@@"/>
                                </WrapPanel>
                                <Border Grid.Row="4" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="6,6,2,6">
                                    <Grid>
                                        <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                        <ProgressBar x:Name="pbLargeScan" Height="3" Margin="4,0,10,4" Background="Transparent" BorderThickness="0" Foreground="#4C8DFF" Visibility="Collapsed" IsIndeterminate="True"/>
                                        <ListView x:Name="lvLargeFiles" Grid.Row="1" Background="Transparent" BorderThickness="0" Foreground="#E6E8EB"
                                                  ScrollViewer.HorizontalScrollBarVisibility="Disabled" HorizontalContentAlignment="Stretch" SelectionMode="Single">
                                            <ListView.ContextMenu>
                                                <ContextMenu>
                                                    <MenuItem Header="@@ctx_openloc@@" Name="ctxOpenLargeFile" FontWeight="Bold" Foreground="#8CB4FF"/>
                                                    <MenuItem Header="@@ctx_copypath@@" Name="ctxCopyLargePath"/>
                                                    <Separator/>
                                                    <MenuItem Header="@@ctx_deleteperm@@" Name="ctxDeleteLargeFile" Foreground="#E5484D" FontWeight="Bold"/>
                                                </ContextMenu>
                                            </ListView.ContextMenu>
                                            <ListView.ItemContainerStyle>
                                                <Style TargetType="ListViewItem">
                                                    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
                                                    <Setter Property="Margin" Value="0,0,6,1"/>
                                                    <Setter Property="Template">
                                                        <Setter.Value>
                                                            <ControlTemplate TargetType="ListViewItem">
                                                                <Border x:Name="Bd" Background="Transparent" CornerRadius="6" Padding="10,7,10,7">
                                                                    <ContentPresenter/>
                                                                </Border>
                                                                <ControlTemplate.Triggers>
                                                                    <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#181C23"/> </Trigger>
                                                                    <Trigger Property="IsSelected" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1C2433"/> </Trigger>
                                                                </ControlTemplate.Triggers>
                                                            </ControlTemplate>
                                                        </Setter.Value>
                                                    </Setter>
                                                </Style>
                                            </ListView.ItemContainerStyle>
                                            <ListView.ItemTemplate>
                                                <DataTemplate>
                                                    <Grid>
                                                        <Grid.ColumnDefinitions> <ColumnDefinition Width="92"/> <ColumnDefinition Width="14"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                                        <StackPanel VerticalAlignment="Center">
                                                            <TextBlock Text="{Binding SizeStr}" FontSize="14" FontWeight="SemiBold" Foreground="#E6E8EB" HorizontalAlignment="Right"/>
                                                            <Grid Height="3" Margin="0,4,0,0">
                                                                <Border Background="#1E2229" CornerRadius="1.5"/>
                                                                <Border Background="#4C8DFF" CornerRadius="1.5" HorizontalAlignment="Right" Width="{Binding BarWidth}"/>
                                                            </Grid>
                                                        </StackPanel>
                                                        <StackPanel Grid.Column="2" VerticalAlignment="Center">
                                                            <TextBlock Text="{Binding Name}" FontSize="14" FontWeight="SemiBold" Foreground="#E6E8EB" TextTrimming="CharacterEllipsis"/>
                                                            <TextBlock Text="{Binding Detail}" ToolTip="{Binding FullName}" FontSize="12" Foreground="#5D6470" Margin="0,1,0,0" TextTrimming="CharacterEllipsis"/>
                                                        </StackPanel>
                                                    </Grid>
                                                </DataTemplate>
                                            </ListView.ItemTemplate>
                                        </ListView>
                                        <TextBlock x:Name="txtLfEmpty" Grid.Row="1" Text="@@lf_empty_start@@" Foreground="#5D6470" FontSize="13" HorizontalAlignment="Center" VerticalAlignment="Center" TextAlignment="Center" TextWrapping="Wrap" MaxWidth="360"/>
                                    </Grid>
                                </Border>
                            </Grid>
                            <Border Grid.Column="2" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="18,16">
                                <DockPanel LastChildFill="True">
                                    <Border DockPanel.Dock="Bottom" Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,12,0,0">
                                        <TextBlock Text="@@lf_note@@" FontSize="12" Foreground="#8A919C" TextWrapping="Wrap"/>
                                    </Border>
                                    <StackPanel x:Name="pnlLfActions" DockPanel.Dock="Bottom" IsEnabled="False">
                                        <Button x:Name="btnLfOpen" Style="{StaticResource BtnSecondary}" Content="@@su_open_loc@@" Height="34" Margin="0,8,0,0"/>
                                        <Button x:Name="btnLfCopy" Style="{StaticResource BtnSecondary}" Content="@@su_copy_path@@" Height="34" Margin="0,8,0,0"/>
                                        <Button x:Name="btnLfDelete" Style="{StaticResource BtnDanger}" Content="@@su_delete@@" Height="34" Margin="0,8,0,0"/>
                                    </StackPanel>
                                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                        <StackPanel>
                                            <TextBlock Text="@@lf_found@@" Style="{StaticResource NavCaption}" Margin="0,0,0,6"/>
                                            <TextBlock x:Name="txtLfTotal" Text="—" Foreground="#E6E8EB" FontSize="32" FontWeight="SemiBold"/>
                                            <TextBlock x:Name="txtLfTotalSub" Text="" Foreground="#8A919C" FontSize="13" Margin="0,2,0,0" TextWrapping="Wrap"/>
                                            <Border Height="1" Background="#232831" Margin="0,16,0,16"/>
                                            <TextBlock Text="@@su_selected@@" Style="{StaticResource NavCaption}" Margin="0,0,0,8"/>
                                            <TextBlock x:Name="txtLfSelName" Text="@@lf_pick@@" Foreground="#8A919C" FontSize="16" FontWeight="SemiBold" TextWrapping="Wrap"/>
                                            <StackPanel x:Name="pnlLfSelInfo" Visibility="Collapsed">
                                                <TextBlock x:Name="txtLfSelSize" Text="" Foreground="#E6E8EB" FontSize="14" FontWeight="SemiBold" Margin="0,4,0,0"/>
                                                <TextBlock Text="@@lf_lbl_folder@@" Style="{StaticResource NavCaption}" Margin="0,14,0,4"/>
                                                <TextBox x:Name="txtLfSelFolder" Text="" IsReadOnly="True" Background="Transparent" BorderThickness="0" Foreground="#C9CED6" FontSize="12.5" TextWrapping="Wrap" Padding="0" FontFamily="Cascadia Mono, Consolas"/>
                                                <TextBlock Text="@@lf_lbl_date@@" Style="{StaticResource NavCaption}" Margin="0,12,0,4"/>
                                                <TextBlock x:Name="txtLfSelDate" Text="" Foreground="#C9CED6" FontSize="13"/>
                                            </StackPanel>
                                        </StackPanel>
                                    </ScrollViewer>
                                </DockPanel>
                            </Border>
                        </Grid>
                    </TabItem>
					<!-- ÇÖKME VE HATA DEDEKTİFİ (KARA KUTU) -->
                    <TabItem Header="@@tab_crash@@" x:Name="tabCrash">
                        <!-- v1.3.0 (tasarım E): tek Tara (olay + dosya), süre, tür çipleri, program adı önde gruplu liste, sağda olgu / olasılık.
                             cbCrashTime gizli; btnScanLogs gizli (yalnız dosya taraması, Tara zaten dosyayı da alır). -->
                        <Grid Margin="16,12,14,12">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="16"/> <ColumnDefinition Width="300"/> </Grid.ColumnDefinitions>
                            <Grid Grid.Column="0">
                                <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                <Grid Grid.Row="0" Margin="0,0,0,12">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <StackPanel>
                                        <TextBlock Text="@@tab_crash@@" Foreground="#E6E8EB" FontSize="22" FontWeight="SemiBold"/>
                                        <TextBlock Text="@@cr_sub@@" Foreground="#8A919C" FontSize="13" Margin="0,3,0,0" TextTrimming="CharacterEllipsis"/>
                                    </StackPanel>
                                    <Button x:Name="btnScanLogs" Visibility="Collapsed" Content="@@cr_logs@@"/>
                                    <Button x:Name="btnScanCrashes" Grid.Column="1" Style="{StaticResource BtnPrimary}" Content="@@cr_scan@@" MinWidth="120" Height="34" Padding="18,0" VerticalAlignment="Center"/>
                                </Grid>
                                <Border Grid.Row="1" Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,10">
                                    <Grid>
                                        <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                        <Ellipse x:Name="shpBlackBoxStatus" Width="10" Height="10" Fill="#5D6470" VerticalAlignment="Top" Margin="0,4,10,0"/>
                                        <StackPanel Grid.Column="1" VerticalAlignment="Center">
                                            <TextBlock Text="@@cr_bb_title@@" Foreground="#E6E8EB" FontSize="14" FontWeight="SemiBold"/>
                                            <TextBlock x:Name="txtBlackBoxStatus" Text="@@cr_bb_checking@@" Foreground="#8A919C" FontSize="12.5" TextWrapping="Wrap" Margin="0,2,0,0"/>
                                        </StackPanel>
                                        <Button x:Name="btnFixBlackBox" Grid.Column="2" Style="{StaticResource BtnSecondary}" Content="@@cr_bb_enable@@" Padding="14,0" Height="32" Margin="12,0,0,0" VerticalAlignment="Center" Visibility="Collapsed" Tag="off"
                                                ToolTip="3 şeyi kontrol eder: (1) WER servisi çalışıyor mu, (2) Mavi Ekran (BSOD) dökümü açık mı, (3) Uygulama/oyun çökünce .dmp toplanıyor mu (LocalDumps). 3. madde Windows'ta varsayılan KAPALIDIR — 'Aç' dersen bundan sonraki çökmelerde otomatik .dmp toplanır. Önce Tara ile mevcut dosyalara bakman yeterli olabilir."/>
                                    </Grid>
                                </Border>
                                <Grid Grid.Row="2" Margin="0,0,0,10">
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="12"/> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                    <ComboBox x:Name="cbCrashTime" Visibility="Collapsed" SelectedIndex="2">
                                        <ComboBoxItem Content="@@crash_t1h@@" Tag="1"/>
                                        <ComboBoxItem Content="@@crash_t4h@@" Tag="4"/>
                                        <ComboBoxItem Content="@@crash_t24h@@" Tag="24"/>
                                        <ComboBoxItem Content="@@crash_t3d@@" Tag="72"/>
                                        <ComboBoxItem Content="@@crash_t7d@@" Tag="168"/>
                                    </ComboBox>
                                    <Border Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="3">
                                        <StackPanel Orientation="Horizontal">
                                            <RadioButton x:Name="rbCr1h" GroupName="CrTime" Style="{StaticResource SegItem}" Content="@@cr_t1h@@" MinWidth="58"/>
                                            <RadioButton x:Name="rbCr4h" GroupName="CrTime" Style="{StaticResource SegItem}" Content="@@cr_t4h@@" MinWidth="58"/>
                                            <RadioButton x:Name="rbCr24h" GroupName="CrTime" Style="{StaticResource SegItem}" Content="@@cr_t24h@@" MinWidth="64" IsChecked="True"/>
                                            <RadioButton x:Name="rbCr3d" GroupName="CrTime" Style="{StaticResource SegItem}" Content="@@cr_t3d@@" MinWidth="64"/>
                                            <RadioButton x:Name="rbCr7d" GroupName="CrTime" Style="{StaticResource SegItem}" Content="@@cr_t7d@@" MinWidth="64"/>
                                        </StackPanel>
                                    </Border>
                                    <TextBox x:Name="txtCrashFilter" Grid.Column="2" Style="{StaticResource SearchBox}" Tag="@@cr_search_ph@@" MaxWidth="360" HorizontalAlignment="Left" Width="360" VerticalAlignment="Center"
                                             ToolTip="Yazdıkça listeyi daraltır — dosya adı, tür, konum, açıklama içinde arar (örn: bf6, ntdll, .dmp, EA)"/>
                                    <TextBlock x:Name="txtCrashCount" Grid.Column="3" Text="" Foreground="#8A919C" FontSize="13" VerticalAlignment="Center" Margin="10,0,0,0"/>
                                </Grid>
                                <WrapPanel Grid.Row="3" Margin="0,0,0,4">
                                    <RadioButton x:Name="chipCrAll" GroupName="CrChips" Style="{StaticResource ChipStyle}" Content="@@tw_chip_all@@" IsChecked="True"/>
                                    <RadioButton x:Name="chipCrApp" GroupName="CrChips" Style="{StaticResource ChipStyle}" Content="@@cr_chip_app@@"/>
                                    <RadioButton x:Name="chipCrHang" GroupName="CrChips" Style="{StaticResource ChipStyle}" Content="@@cr_chip_hang@@"/>
                                    <RadioButton x:Name="chipCrGpu" GroupName="CrChips" Style="{StaticResource ChipStyle}" Content="@@cr_chip_gpu@@"/>
                                    <RadioButton x:Name="chipCrBsod" GroupName="CrChips" Style="{StaticResource ChipStyle}" Content="@@cr_chip_bsod@@"/>
                                    <RadioButton x:Name="chipCrFile" GroupName="CrChips" Style="{StaticResource ChipStyle}" Content="@@cr_chip_file@@"/>
                                </WrapPanel>
                                <Border Grid.Row="4" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="6,6,2,6">
                                    <Grid>
                                        <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                        <ProgressBar x:Name="pbCrashScan" Height="3" Margin="4,0,10,4" Background="Transparent" BorderThickness="0" Foreground="#4C8DFF" Visibility="Collapsed" IsIndeterminate="True"/>
                                        <ListView x:Name="lvCrashes" Grid.Row="1" Background="Transparent" BorderThickness="0" Foreground="#E6E8EB"
                                                  ScrollViewer.HorizontalScrollBarVisibility="Disabled" HorizontalContentAlignment="Stretch" SelectionMode="Single">
                                            <ListView.ContextMenu>
                                                <ContextMenu>
                                                    <MenuItem Header="@@ctx_copydetail@@" Name="ctxCopyCrash" FontWeight="Bold" Foreground="#4CC2FF"/>
                                                    <MenuItem Header="@@ctx_googlesearch@@" Name="ctxSearchCrash" Foreground="#3FB97A"/>
                                                    <Separator/>
                                                    <MenuItem Header="@@ctx_opendump@@" Name="ctxOpenDump" Foreground="#E0A23B" FontWeight="Bold"/>
                                                </ContextMenu>
                                            </ListView.ContextMenu>
                                            <ListView.ItemContainerStyle>
                                                <Style TargetType="ListViewItem">
                                                    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
                                                    <Setter Property="Margin" Value="0,0,6,1"/>
                                                    <Setter Property="Template">
                                                        <Setter.Value>
                                                            <ControlTemplate TargetType="ListViewItem">
                                                                <Border x:Name="Bd" Background="Transparent" CornerRadius="6" Padding="10,7,10,7">
                                                                    <ContentPresenter/>
                                                                </Border>
                                                                <ControlTemplate.Triggers>
                                                                    <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#181C23"/> </Trigger>
                                                                    <Trigger Property="IsSelected" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1C2433"/> </Trigger>
                                                                </ControlTemplate.Triggers>
                                                            </ControlTemplate>
                                                        </Setter.Value>
                                                    </Setter>
                                                </Style>
                                            </ListView.ItemContainerStyle>
                                            <ListView.ItemTemplate>
                                                <DataTemplate>
                                                    <Grid>
                                                        <Grid.ColumnDefinitions> <ColumnDefinition Width="3"/> <ColumnDefinition Width="12"/> <ColumnDefinition Width="*"/> </Grid.ColumnDefinitions>
                                                        <Border Background="{Binding Color}" CornerRadius="1.5" Opacity="0.85"/>
                                                        <Grid Grid.Column="2">
                                                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                                            <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
                                                            <TextBlock FontSize="13.5" TextTrimming="CharacterEllipsis">
                                                                <Run Text="{Binding TitleText, Mode=OneWay}" Foreground="#E6E8EB" FontWeight="SemiBold"/>
                                                                <Run Text="  "/>
                                                                <Run Text="{Binding CountText, Mode=OneWay}" Foreground="#8A919C"/>
                                                            </TextBlock>
                                                            <Border Grid.Column="1" Background="#1C2433" CornerRadius="4" Padding="7,1" Margin="8,0,0,0" VerticalAlignment="Center">
                                                                <TextBlock Text="{Binding Category}" FontSize="11.5" Foreground="{Binding Color}"/>
                                                            </Border>
                                                            <TextBlock Grid.Row="1" Grid.ColumnSpan="2" Text="{Binding Detail}" FontSize="12.5" Foreground="#8A919C" Margin="0,2,0,0" TextTrimming="CharacterEllipsis"/>
                                                        </Grid>
                                                    </Grid>
                                                </DataTemplate>
                                            </ListView.ItemTemplate>
                                        </ListView>
                                        <TextBlock x:Name="txtCrashEmpty" Grid.Row="1" Text="@@cr_empty@@" Foreground="#5D6470" FontSize="13" HorizontalAlignment="Center" VerticalAlignment="Center" TextAlignment="Center" TextWrapping="Wrap" MaxWidth="380"/>
                                    </Grid>
                                </Border>
                            </Grid>
                            <Border Grid.Column="2" Background="#15181E" BorderBrush="#232831" BorderThickness="1" CornerRadius="10" Padding="18,16">
                                <DockPanel LastChildFill="True">
                                    <Border DockPanel.Dock="Bottom" Background="#161920" BorderBrush="#2A2F39" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,12,0,0">
                                        <TextBlock Text="@@crash_hint@@" FontSize="12" Foreground="#8A919C" TextWrapping="Wrap"/>
                                    </Border>
                                    <StackPanel x:Name="pnlCrActions" DockPanel.Dock="Bottom" IsEnabled="False">
                                        <Button x:Name="btnCrCopy" Style="{StaticResource BtnSecondary}" Content="@@cr_copy@@" Height="34" Margin="0,8,0,0"/>
                                        <Button x:Name="btnCrSearch" Style="{StaticResource BtnSecondary}" Content="@@cr_search_web@@" Height="34" Margin="0,8,0,0"/>
                                        <Button x:Name="btnCrOpenDump" Style="{StaticResource BtnSecondary}" Content="@@cr_open_file@@" Height="34" Margin="0,8,0,0"/>
                                    </StackPanel>
                                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Focusable="False">
                                        <StackPanel>
                                            <TextBlock Text="@@su_selected@@" Style="{StaticResource NavCaption}" Margin="0,0,0,8"/>
                                            <TextBlock x:Name="txtCrSelCat" Text="@@cr_pick@@" Foreground="#8A919C" FontSize="16" FontWeight="SemiBold" TextWrapping="Wrap"/>
                                            <StackPanel x:Name="pnlCrSelInfo" Visibility="Collapsed">
                                                <TextBlock x:Name="txtCrSelMeta" Text="" Foreground="#C9CED6" FontSize="13" Margin="0,4,0,0" TextWrapping="Wrap"/>
                                                <TextBlock Text="@@cr_lbl_facts@@" Style="{StaticResource NavCaption}" Margin="0,14,0,4"/>
                                                <TextBox x:Name="txtCrSelDesc" Text="" IsReadOnly="True" Background="Transparent" BorderThickness="0" Foreground="#C9CED6" FontSize="13" TextWrapping="Wrap" Padding="0"/>
                                                <TextBlock x:Name="lblCrHint" Text="@@cr_lbl_maybe@@" Style="{StaticResource NavCaption}" Margin="0,14,0,4" Visibility="Collapsed"/>
                                                <TextBox x:Name="txtCrSelHint" Text="" IsReadOnly="True" Background="Transparent" BorderThickness="0" Foreground="#8A919C" FontSize="13" TextWrapping="Wrap" Padding="0"/>
                                            </StackPanel>
                                        </StackPanel>
                                    </ScrollViewer>
                                </DockPanel>
                            </Border>
                        </Grid>
                    </TabItem>
                </TabControl>
            </Grid>
        </Border>
    </Grid>

    <GridSplitter x:Name="splLog" Grid.Row="1" Height="8" HorizontalAlignment="Stretch" VerticalAlignment="Center" ResizeDirection="Rows" ResizeBehavior="PreviousAndNext" Background="Transparent" Cursor="SizeNS" Visibility="Collapsed"/>
    <Border x:Name="bdLogPanel" Grid.Row="2" Background="#0C0E12" BorderBrush="#1E2229" BorderThickness="1" CornerRadius="10" Padding="12,8,12,10" Visibility="Collapsed">
        <Grid>
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
            <Grid Grid.Row="0" Margin="0,0,0,6">
                <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                    <TextBlock Text="@@log_title@@" Foreground="#E6E8EB" FontWeight="SemiBold" FontSize="14" VerticalAlignment="Center" Margin="0,0,18,0"/>
                    <CheckBox x:Name="chkDebug" Content="@@chk_debug@@" Foreground="#8A919C" FontSize="12" Margin="0,0,14,0" Style="{StaticResource ToggleSwitch}" VerticalAlignment="Center"/>
                    <Button x:Name="btnOpenData" Content="@@btn_opendata@@" Style="{StaticResource BtnGhostIcon}" Width="Auto" Height="26" Padding="8,0" FontSize="12"/>
                </StackPanel>
                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                    <Button x:Name="btnCopyLog" Content="@@log_copy@@" Style="{StaticResource BtnSecondary}" Height="26" Padding="10,0" FontSize="12" Margin="0,0,6,0"/>
                    <Button x:Name="btnClearLog" Content="@@log_clear@@" Style="{StaticResource BtnDanger}" Height="26" Padding="10,0" FontSize="12" Margin="0,0,6,0"/>
                    <Button x:Name="btnLogClose" Content="✕" Style="{StaticResource BtnGhostIcon}" Height="26" Width="26" FontSize="12" ToolTip="@@log_toggle_hide@@"/>
                </StackPanel>
            </Grid>
            <TextBox x:Name="txtLog" Grid.Row="1" Background="Transparent" Foreground="#9AA3B2" BorderThickness="0" VerticalScrollBarVisibility="Auto" IsReadOnly="True" TextWrapping="Wrap" FontFamily="Cascadia Mono, Consolas" FontSize="13" Padding="6"/>
        </Grid>
    </Border>

    <!-- FOOTER: ince durum çubuğu (durum | Analiz/Başlat | işlem kayıtları) -->
    <Grid Grid.Row="3" Margin="0,8,0,8">
        <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
        <StackPanel Grid.Column="0" VerticalAlignment="Center">
            <DockPanel LastChildFill="True">
                <Ellipse DockPanel.Dock="Left" Width="8" Height="8" Fill="#3FB97A" VerticalAlignment="Center" Margin="2,0,10,0"/>
                <TextBlock x:Name="lblStatus" DockPanel.Dock="Left" Text="Sistem Hazır" Foreground="#E6E8EB" FontWeight="SemiBold" FontSize="14" VerticalAlignment="Center" Margin="0,0,12,0"/>
                <TextBlock x:Name="txtWinappStatus" DockPanel.Dock="Left" Text="Veritabanı bekleniyor..." Foreground="#8A919C" VerticalAlignment="Center" FontSize="12" Margin="0,0,12,0"/>
                <TextBlock x:Name="lblDetail" Text="İşlem bekleniyor..." Foreground="#A9B0BB" FontSize="13" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/>
            </DockPanel>
            <Grid Margin="0,8,0,0"> <Border Height="3" Background="#252A33" CornerRadius="1.5"/> <ProgressBar x:Name="pbMain" Height="3" Background="Transparent" Foreground="{StaticResource AccentColor}" BorderThickness="0" Value="0"/> </Grid>
        </StackPanel>
        <StackPanel x:Name="pnlRunActions" Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center" Margin="20,0,0,0">
            <ComboBox x:Name="cbSecureDelete" Width="190" Height="34" SelectedIndex="0" VerticalContentAlignment="Center" Margin="0,0,10,0" ToolTip="@@footer_deletemethod@@">
                <ComboBoxItem Content="@@del_fast@@"/>
                <ComboBoxItem Content="@@del_secure_zero@@"/>
                <ComboBoxItem Content="@@del_secure_random@@"/>
            </ComboBox>
            <Button x:Name="btnAnalyze" Content="@@btn_analyze@@" Width="110" Height="36" Background="#1D2129" BorderThickness="1" BorderBrush="#2C313B" Margin="0,0,10,0"/>
            <Button x:Name="btnRun" Content="@@btn_start@@" Width="130" Height="36" Background="{StaticResource AccentColor}" FontWeight="Bold" FontSize="15">
                <Button.Effect> <DropShadowEffect Color="#4C8DFF" BlurRadius="16" ShadowDepth="0" Opacity="0.3"/> </Button.Effect>
            </Button>
        </StackPanel>
        <Grid Grid.Column="2" VerticalAlignment="Center" Margin="14,0,0,0">
            <Button x:Name="btnLogToggle" Content="@@log_toggle_show@@" Style="{StaticResource BtnSecondary}" Height="32" FontSize="13"/>
            <Border x:Name="bdLogBadge" Background="#E5484D" CornerRadius="8" MinWidth="16" Height="16" Padding="4,0" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-7,-7,0" IsHitTestVisible="False" Visibility="Collapsed">
                <TextBlock x:Name="txtLogBadge" Text="0" Foreground="White" FontSize="11" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
        </Grid>
    </Grid>
    </Grid>
    <Grid x:Name="grdBootOverlay" Grid.ColumnSpan="2" Panel.ZIndex="999" Background="#0F1115" Cursor="Wait" IsHitTestVisible="True">
        <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
            <TextBlock Text="MrClean" FontSize="30" FontWeight="Bold" Foreground="#E6E8EB" HorizontalAlignment="Center" Margin="0,0,0,6"/>
            <TextBlock Text="@@boot_subtitle@@" FontSize="14" Foreground="#8A919C" HorizontalAlignment="Center" Margin="0,0,0,22"/>
            <ProgressBar x:Name="pbBoot" Width="280" Height="6" Minimum="0" Maximum="100" Value="4" IsIndeterminate="False" Foreground="#4C8DFF" Background="#252A33" BorderThickness="0"/>
            <TextBlock x:Name="txtBootStatus" Text="@@boot_loading@@" FontSize="13" Foreground="#A9B0BB" HorizontalAlignment="Center" Margin="0,16,0,0"/>
        </StackPanel>
    </Grid>
  </Grid>
 
</Window>
"@

# --- DİĞER XAML DOSYALARI (AYNEN KORUNDU) ---
# v1.3.0 (§62, B13): alt pencerelerin ortak görünümü. Ana pencereyle aynı palet + Inter + B ölçüsü.
# Her alt pencere XAML'inde <Window.Resources> içine $($global:SubTheme) olarak eklenir; anahtarlar Sw önekli
# (pencerelerin kendi stilleriyle çakışmasın). Örtük stiller: Button, TextBox, ComboBox(+Item), CheckBox, RadioButton,
# ListBox(+Item), ScrollBar, ToolTip. Yazı tipi: UiFont kaynağı; Initialize-SubWindow açılışta Inter'i bağlar.
$global:SubTheme = @'
    <FontFamily x:Key="UiFont">Segoe UI Variable Text, Segoe UI</FontFamily>
    <FontFamily x:Key="UiFontHead">Segoe UI Variable Display, Segoe UI</FontFamily>
    <Style TargetType="ToolTip"> <Setter Property="FontFamily" Value="{DynamicResource UiFont}"/> </Style>

    <Style x:Key="SwCard" TargetType="Border">
        <Setter Property="Background" Value="#15181E"/>
        <Setter Property="BorderBrush" Value="#232831"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="CornerRadius" Value="10"/>
        <Setter Property="Padding" Value="16,14"/>
    </Style>
    <Style x:Key="SwTitle" TargetType="TextBlock">
        <Setter Property="FontFamily" Value="{DynamicResource UiFontHead}"/>
        <Setter Property="FontSize" Value="20"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
    </Style>
    <Style x:Key="SwSection" TargetType="TextBlock">
        <Setter Property="FontSize" Value="15"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
    </Style>
    <Style x:Key="SwDesc" TargetType="TextBlock">
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="Foreground" Value="#8A919C"/>
        <Setter Property="TextWrapping" Value="Wrap"/>
    </Style>

    <Style x:Key="SwBtn" TargetType="Button">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Background" Value="#1D2129"/>
        <Setter Property="BorderBrush" Value="#2C313B"/>
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="MinHeight" Value="32"/>
        <Setter Property="Padding" Value="14,6"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Grid x:Name="root">
                        <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="6"/>
                        <Border x:Name="overlay" Background="White" Opacity="0" CornerRadius="6"/>
                        <ContentPresenter Margin="{TemplateBinding Padding}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.06"/> </Trigger>
                        <Trigger Property="IsPressed" Value="True"> <Setter TargetName="overlay" Property="Opacity" Value="0.12"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="root" Property="Opacity" Value="0.4"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="Button" BasedOn="{StaticResource SwBtn}"/>
    <Style x:Key="SwBtnPrimary" TargetType="Button" BasedOn="{StaticResource SwBtn}">
        <Setter Property="Foreground" Value="White"/>
        <Setter Property="Background" Value="#4C8DFF"/>
        <Setter Property="BorderBrush" Value="#4C8DFF"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
    </Style>
    <Style x:Key="SwBtnDanger" TargetType="Button" BasedOn="{StaticResource SwBtn}">
        <Setter Property="Foreground" Value="#F2A0A0"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="BorderBrush" Value="#5A2E33"/>
    </Style>
    <Style x:Key="SwBtnDangerSolid" TargetType="Button" BasedOn="{StaticResource SwBtn}">
        <Setter Property="Foreground" Value="White"/>
        <Setter Property="Background" Value="#E5484D"/>
        <Setter Property="BorderBrush" Value="#E5484D"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
    </Style>
    <Style x:Key="SwBtnGhost" TargetType="Button" BasedOn="{StaticResource SwBtn}">
        <Setter Property="Foreground" Value="#8A919C"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="BorderBrush" Value="Transparent"/>
        <Setter Property="MinHeight" Value="0"/>
        <Setter Property="Padding" Value="0"/>
    </Style>

    <Style TargetType="TextBox">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Background" Value="#14171C"/>
        <Setter Property="BorderBrush" Value="#2A2F39"/>
        <Setter Property="CaretBrush" Value="#E6E8EB"/>
        <Setter Property="SelectionBrush" Value="#4C8DFF"/>
        <!-- §70: 8,5 idi; eski pencerelerdeki sabit 28 px yükseklikli kutularda yazı dikeyde kesiliyordu -->
        <Setter Property="Padding" Value="8,3"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="TextBox">
                    <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="6">
                        <ScrollViewer x:Name="PART_ContentHost" Margin="{TemplateBinding Padding}" Focusable="False"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="BorderBrush" Value="#3E4552"/> </Trigger>
                        <Trigger Property="IsKeyboardFocused" Value="True"> <Setter TargetName="Bd" Property="BorderBrush" Value="#4C8DFF"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter Property="Opacity" Value="0.5"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <ControlTemplate x:Key="SwComboToggle" TargetType="ToggleButton">
        <Grid>
            <Grid.ColumnDefinitions> <ColumnDefinition/> <ColumnDefinition Width="22"/> </Grid.ColumnDefinitions>
            <Border x:Name="Border" Grid.ColumnSpan="2" CornerRadius="6" Background="#1D2129" BorderBrush="#2C313B" BorderThickness="1"/>
            <Path Grid.Column="1" Fill="#8A919C" HorizontalAlignment="Center" VerticalAlignment="Center" Data="M 0 0 L 4 4 L 8 0 Z"/>
        </Grid>
        <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Border" Property="BorderBrush" Value="#3E4552"/> </Trigger>
        </ControlTemplate.Triggers>
    </ControlTemplate>
    <Style TargetType="ComboBox">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="MinHeight" Value="30"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ComboBox">
                    <Grid>
                        <ToggleButton Template="{StaticResource SwComboToggle}" Focusable="False" ClickMode="Press"
                                      IsChecked="{Binding Path=IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}"/>
                        <ContentPresenter x:Name="ContentSite" IsHitTestVisible="False" Content="{TemplateBinding SelectionBoxItem}"
                                          ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}" ContentTemplateSelector="{TemplateBinding ItemTemplateSelector}"
                                          Margin="10,3,26,3" VerticalAlignment="Center" HorizontalAlignment="Left"/>
                        <TextBox x:Name="PART_EditableTextBox" Style="{x:Null}" Background="Transparent" BorderThickness="0" Foreground="#E6E8EB" CaretBrush="#E6E8EB"
                                 Margin="6,3,26,3" VerticalAlignment="Center" Focusable="True" Visibility="Hidden" IsReadOnly="{TemplateBinding IsReadOnly}"/>
                        <Popup IsOpen="{TemplateBinding IsDropDownOpen}" Placement="Bottom" AllowsTransparency="True" Focusable="False" PopupAnimation="Slide">
                            <Grid SnapsToDevicePixels="True" MinWidth="{TemplateBinding ActualWidth}" MaxHeight="{TemplateBinding MaxDropDownHeight}">
                                <Border Background="#161920" BorderBrush="#2C313B" BorderThickness="1" CornerRadius="6"/>
                                <ScrollViewer Margin="4,6" SnapsToDevicePixels="True">
                                    <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Contained"/>
                                </ScrollViewer>
                            </Grid>
                        </Popup>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsEditable" Value="True">
                            <Setter TargetName="PART_EditableTextBox" Property="Visibility" Value="Visible"/>
                            <Setter TargetName="ContentSite" Property="Visibility" Value="Hidden"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter Property="Opacity" Value="0.5"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="ComboBoxItem">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Padding" Value="8,5"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ComboBoxItem">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="4" Padding="{TemplateBinding Padding}"> <ContentPresenter/> </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1A1E25"/> </Trigger>
                        <Trigger Property="IsSelected" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1C2433"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="SwCheck" TargetType="CheckBox">
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="CheckBox">
                    <StackPanel Orientation="Horizontal" Background="Transparent">
                        <Border x:Name="Box" Width="18" Height="18" CornerRadius="4" BorderThickness="1.5" BorderBrush="#4A515E" Background="Transparent" VerticalAlignment="Center">
                            <Grid>
                                <TextBlock x:Name="Mark" FontFamily="Segoe Fluent Icons, Segoe MDL2 Assets" Text="&#xE73E;" FontSize="12" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center" Visibility="Collapsed"/>
                                <Border x:Name="Dash" Width="8" Height="2" CornerRadius="1" Background="White" Visibility="Collapsed"/>
                            </Grid>
                        </Border>
                        <ContentPresenter x:Name="Cp" Margin="10,0,0,0" VerticalAlignment="Center"/>
                    </StackPanel>
                    <ControlTemplate.Triggers>
                        <Trigger Property="Content" Value="{x:Null}"> <Setter TargetName="Cp" Property="Margin" Value="0"/> </Trigger>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Box" Property="BorderBrush" Value="#7A8394"/> </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Box" Property="Background" Value="#4C8DFF"/>
                            <Setter TargetName="Box" Property="BorderBrush" Value="#4C8DFF"/>
                            <Setter TargetName="Mark" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="{x:Null}">
                            <Setter TargetName="Box" Property="Background" Value="#4C8DFF"/>
                            <Setter TargetName="Box" Property="BorderBrush" Value="#4C8DFF"/>
                            <Setter TargetName="Dash" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter Property="Opacity" Value="0.45"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="CheckBox" BasedOn="{StaticResource SwCheck}"/>
    <Style TargetType="RadioButton">
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="RadioButton">
                    <StackPanel Orientation="Horizontal" Background="Transparent">
                        <Grid Width="18" Height="18" VerticalAlignment="Center">
                            <Ellipse x:Name="Ring" Stroke="#4A515E" StrokeThickness="1.5" Fill="Transparent"/>
                            <Ellipse x:Name="Dot" Width="8" Height="8" Fill="White" Visibility="Collapsed"/>
                        </Grid>
                        <ContentPresenter Margin="8,0,0,0" VerticalAlignment="Center"/>
                    </StackPanel>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Ring" Property="Stroke" Value="#7A8394"/> </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Ring" Property="Stroke" Value="#4C8DFF"/>
                            <Setter TargetName="Ring" Property="Fill" Value="#4C8DFF"/>
                            <Setter TargetName="Dot" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter Property="Opacity" Value="0.45"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style TargetType="ListBox">
        <Setter Property="Background" Value="#13161B"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="BorderBrush" Value="#232831"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="Padding" Value="4"/>
        <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
    </Style>
    <Style TargetType="ListBoxItem">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Padding" Value="8,5"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ListBoxItem">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="5" Padding="{TemplateBinding Padding}" Margin="0,1"> <ContentPresenter/> </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#181C23"/> </Trigger>
                        <Trigger Property="IsSelected" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1C2433"/> <Setter Property="Foreground" Value="White"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <ControlTemplate x:Key="SwScrollThumb" TargetType="Thumb">
        <Border x:Name="T" CornerRadius="3" Background="#323843" Margin="2"/>
        <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="T" Property="Background" Value="#4A515E"/> </Trigger>
            <Trigger Property="IsDragging" Value="True"> <Setter TargetName="T" Property="Background" Value="#5A6270"/> </Trigger>
        </ControlTemplate.Triggers>
    </ControlTemplate>
    <Style TargetType="ScrollBar">
        <Setter Property="Width" Value="10"/>
        <Setter Property="MinWidth" Value="10"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ScrollBar">
                    <Grid Background="Transparent">
                        <Track x:Name="PART_Track" IsDirectionReversed="True"> <Track.Thumb> <Thumb Template="{StaticResource SwScrollThumb}"/> </Track.Thumb> </Track>
                    </Grid>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
        <Style.Triggers>
            <Trigger Property="Orientation" Value="Horizontal">
                <Setter Property="Width" Value="Auto"/>
                <Setter Property="MinWidth" Value="0"/>
                <Setter Property="Height" Value="10"/>
                <Setter Property="MinHeight" Value="10"/>
                <Setter Property="Template">
                    <Setter.Value>
                        <ControlTemplate TargetType="ScrollBar">
                            <Grid Background="Transparent">
                                <Track x:Name="PART_Track" IsDirectionReversed="False"> <Track.Thumb> <Thumb Template="{StaticResource SwScrollThumb}"/> </Track.Thumb> </Track>
                            </Grid>
                        </ControlTemplate>
                    </Setter.Value>
                </Setter>
            </Trigger>
        </Style.Triggers>
    </Style>
    <!-- v1.3.0 (§76, tutarlılık turu, Onizleme7 onaylı): sağ tık menüsü, kaydırıcı, açılır başlık, tablo başlığı (SwGridHeader), tarih kutusu + takvim -->
    <!-- sağ tık menüsü -->
    <Style TargetType="ContextMenu">
        <Setter Property="Background" Value="#15181E"/>
        <Setter Property="BorderBrush" Value="#2C313B"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="FontFamily" Value="{DynamicResource UiFont}"/>
        <Setter Property="FontSize" Value="14"/>
        <Setter Property="Padding" Value="4"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ContextMenu">
                    <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="8" Padding="{TemplateBinding Padding}">
                        <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="MenuItem">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="MenuItem">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="5" Padding="12,7" MinWidth="200">
                        <ContentPresenter ContentSource="Header" RecognizesAccessKey="True" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsHighlighted" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1C2433"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="Bd" Property="Padding" Value="12,8,12,4"/> <Setter Property="Cursor" Value="Arrow"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="{x:Static MenuItem.SeparatorStyleKey}" TargetType="Separator">
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Separator"> <Border Height="1" Background="#232831" Margin="6,4"/> </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- kaydırıcı -->
    <Style TargetType="Slider">
        <Setter Property="MinHeight" Value="24"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Slider">
                    <Grid VerticalAlignment="Center">
                        <Border Height="4" CornerRadius="2" Background="#2C313B" VerticalAlignment="Center"/>
                        <Track x:Name="PART_Track">
                            <Track.DecreaseRepeatButton>
                                <RepeatButton Command="Slider.DecreaseLarge" Focusable="False">
                                    <RepeatButton.Template> <ControlTemplate TargetType="RepeatButton"> <Border Height="4" CornerRadius="2" Background="#4C8DFF"/> </ControlTemplate> </RepeatButton.Template>
                                </RepeatButton>
                            </Track.DecreaseRepeatButton>
                            <Track.IncreaseRepeatButton>
                                <RepeatButton Command="Slider.IncreaseLarge" Focusable="False">
                                    <RepeatButton.Template> <ControlTemplate TargetType="RepeatButton"> <Border Background="Transparent"/> </ControlTemplate> </RepeatButton.Template>
                                </RepeatButton>
                            </Track.IncreaseRepeatButton>
                            <Track.Thumb>
                                <Thumb Width="16" Height="16">
                                    <Thumb.Template>
                                        <ControlTemplate TargetType="Thumb">
                                            <Ellipse x:Name="E" Fill="#E6E8EB" Stroke="#4C8DFF" StrokeThickness="2"/>
                                            <ControlTemplate.Triggers> <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="E" Property="Fill" Value="White"/> </Trigger> </ControlTemplate.Triggers>
                                        </ControlTemplate>
                                    </Thumb.Template>
                                </Thumb>
                            </Track.Thumb>
                        </Track>
                    </Grid>
                    <ControlTemplate.Triggers> <Trigger Property="IsEnabled" Value="False"> <Setter Property="Opacity" Value="0.45"/> </Trigger> </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- açılır başlık -->
    <Style TargetType="Expander">
        <Setter Property="Foreground" Value="#A9B0BB"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Expander">
                    <DockPanel>
                        <ToggleButton DockPanel.Dock="Top" Cursor="Hand" Focusable="False" Content="{TemplateBinding Header}" Foreground="{TemplateBinding Foreground}"
                                      IsChecked="{Binding IsExpanded, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
                            <ToggleButton.Template>
                                <ControlTemplate TargetType="ToggleButton">
                                    <Border Background="Transparent" Padding="0,4">
                                        <StackPanel Orientation="Horizontal">
                                            <Path x:Name="Chev" Data="M 0 0 L 4 4 L 0 8" Stroke="#8A919C" StrokeThickness="1.6" Width="8" Height="8" Margin="2,0,10,0" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5"/>
                                            <ContentPresenter VerticalAlignment="Center"/>
                                        </StackPanel>
                                    </Border>
                                    <ControlTemplate.Triggers>
                                        <Trigger Property="IsChecked" Value="True"> <Setter TargetName="Chev" Property="RenderTransform"> <Setter.Value> <RotateTransform Angle="90"/> </Setter.Value> </Setter> </Trigger>
                                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Chev" Property="Stroke" Value="#E6E8EB"/> </Trigger>
                                    </ControlTemplate.Triggers>
                                </ControlTemplate>
                            </ToggleButton.Template>
                        </ToggleButton>
                        <ContentPresenter x:Name="Site" Visibility="Collapsed" Margin="18,6,0,0"/>
                    </DockPanel>
                    <ControlTemplate.Triggers> <Trigger Property="IsExpanded" Value="True"> <Setter TargetName="Site" Property="Visibility" Value="Visible"/> </Trigger> </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- tablo sütun başlığı (pencerelerdeki yerel ColumnHeaderContainerStyle yerine) -->
    <Style x:Key="SwGridHeader" TargetType="GridViewColumnHeader">
        <Setter Property="Background" Value="#13161B"/>
        <Setter Property="Foreground" Value="#8A919C"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="Padding" Value="10,6"/>
        <Setter Property="BorderBrush" Value="#232831"/>
        <Setter Property="BorderThickness" Value="0,0,1,1"/>
        <Setter Property="HorizontalContentAlignment" Value="Left"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="GridViewColumnHeader">
                    <Grid>
                        <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="Center" RecognizesAccessKey="True"/>
                        </Border>
                        <Thumb x:Name="PART_HeaderGripper" HorizontalAlignment="Right" Width="8" Margin="0,0,-4,0" Cursor="SizeWE">
                            <Thumb.Template> <ControlTemplate TargetType="Thumb"> <Border Background="Transparent"/> </ControlTemplate> </Thumb.Template>
                        </Thumb>
                    </Grid>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- tarih kutusu + takvim -->
    <Style TargetType="DatePickerTextBox">
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="CaretBrush" Value="#E6E8EB"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="DatePickerTextBox">
                    <Grid Background="Transparent">
                        <ScrollViewer x:Name="PART_ContentHost" Margin="{TemplateBinding Padding}" VerticalAlignment="Center" Focusable="False" HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Hidden"/>
                        <ContentControl x:Name="PART_Watermark" Margin="{TemplateBinding Padding}" Foreground="#6B7280" IsHitTestVisible="False" Focusable="False" VerticalAlignment="Center" Visibility="Collapsed"/>
                    </Grid>
                    <ControlTemplate.Triggers> <Trigger Property="Text" Value=""> <Setter TargetName="PART_Watermark" Property="Visibility" Value="Visible"/> </Trigger> </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="DatePicker">
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Background" Value="#14171C"/>
        <Setter Property="BorderBrush" Value="#2A2F39"/>
        <Setter Property="MinHeight" Value="32"/>
        <Setter Property="IsTodayHighlighted" Value="True"/>
        <Setter Property="CalendarStyle" Value="{DynamicResource SwCalendar}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="DatePicker">
                    <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="6">
                        <Grid x:Name="PART_Root">
                            <Grid.ColumnDefinitions> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                            <DatePickerTextBox x:Name="PART_TextBox" Foreground="{TemplateBinding Foreground}" Padding="8,0,0,0" VerticalContentAlignment="Center"/>
                            <Button x:Name="PART_Button" Grid.Column="1" Style="{x:Null}" Focusable="False" Cursor="Hand" Width="32">
                                <Button.Template>
                                    <ControlTemplate TargetType="Button">
                                        <Border x:Name="b" Background="Transparent" CornerRadius="0,5,5,0">
                                            <TextBlock x:Name="g" Text="&#xE787;" FontFamily="Segoe Fluent Icons, Segoe MDL2 Assets" FontSize="14" Foreground="#8A919C" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                        </Border>
                                        <ControlTemplate.Triggers> <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="b" Property="Background" Value="#1D2129"/> <Setter TargetName="g" Property="Foreground" Value="#E6E8EB"/> </Trigger> </ControlTemplate.Triggers>
                                    </ControlTemplate>
                                </Button.Template>
                            </Button>
                            <Popup x:Name="PART_Popup" AllowsTransparency="True" Placement="Bottom" PlacementTarget="{Binding ElementName=PART_Root}" StaysOpen="False" VerticalOffset="4"/>
                        </Grid>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="BorderBrush" Value="#3E4552"/> </Trigger>
                        <Trigger Property="IsKeyboardFocusWithin" Value="True"> <Setter TargetName="Bd" Property="BorderBrush" Value="#4C8DFF"/> </Trigger>
                        <Trigger Property="IsEnabled" Value="False"> <Setter Property="Opacity" Value="0.45"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="SwCalNav" TargetType="Button">
        <Setter Property="Focusable" Value="False"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="b" Background="Transparent" CornerRadius="6" Padding="8,4" MinWidth="30" MinHeight="28">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="#E6E8EB" TextElement.FontWeight="SemiBold"/>
                    </Border>
                    <ControlTemplate.Triggers> <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="b" Property="Background" Value="#1D2129"/> </Trigger> </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="CalendarItem">
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="CalendarItem">
                    <ControlTemplate.Resources>
                        <DataTemplate x:Key="{ComponentResourceKey ResourceId=DayTitleTemplate, TypeInTargetAssembly={x:Type CalendarItem}}">
                            <TextBlock Text="{Binding}" Foreground="#6B7280" FontSize="12" FontWeight="SemiBold" HorizontalAlignment="Center" Margin="0,4,0,6"/>
                        </DataTemplate>
                    </ControlTemplate.Resources>
                    <Grid x:Name="PART_Root">
                        <Border Background="#15181E" BorderBrush="#2C313B" BorderThickness="1" CornerRadius="8" Padding="8">
                            <Grid>
                                <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="*"/> </Grid.RowDefinitions>
                                <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                <Button x:Name="PART_PreviousButton" Grid.Column="0" Style="{StaticResource SwCalNav}">
                                    <Path Data="M 5 0 L 0 5 L 5 10" Stroke="#8A919C" StrokeThickness="1.6"/>
                                </Button>
                                <Button x:Name="PART_HeaderButton" Grid.Column="1" Style="{StaticResource SwCalNav}"/>
                                <Button x:Name="PART_NextButton" Grid.Column="2" Style="{StaticResource SwCalNav}">
                                    <Path Data="M 0 0 L 5 5 L 0 10" Stroke="#8A919C" StrokeThickness="1.6"/>
                                </Button>
                                <Grid x:Name="PART_MonthView" Grid.Row="1" Grid.ColumnSpan="3" Margin="0,6,0,0" Visibility="Visible">
                                    <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                </Grid>
                                <Grid x:Name="PART_YearView" Grid.Row="1" Grid.ColumnSpan="3" Margin="0,6,0,0" Visibility="Hidden">
                                    <Grid.RowDefinitions> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
                                    <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
                                </Grid>
                            </Grid>
                        </Border>
                        <Rectangle x:Name="PART_DisabledVisual" Fill="#0F1115" Opacity="0.5" RadiusX="8" RadiusY="8" Visibility="Collapsed"/>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsEnabled" Value="False"> <Setter TargetName="PART_DisabledVisual" Property="Visibility" Value="Visible"/> </Trigger>
                        <DataTrigger Binding="{Binding DisplayMode, RelativeSource={RelativeSource FindAncestor, AncestorType={x:Type Calendar}}}" Value="Year">
                            <Setter TargetName="PART_MonthView" Property="Visibility" Value="Hidden"/> <Setter TargetName="PART_YearView" Property="Visibility" Value="Visible"/>
                        </DataTrigger>
                        <DataTrigger Binding="{Binding DisplayMode, RelativeSource={RelativeSource FindAncestor, AncestorType={x:Type Calendar}}}" Value="Decade">
                            <Setter TargetName="PART_MonthView" Property="Visibility" Value="Hidden"/> <Setter TargetName="PART_YearView" Property="Visibility" Value="Visible"/>
                        </DataTrigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="SwCalDay" TargetType="CalendarDayButton">
        <Setter Property="Foreground" Value="#C9CED6"/>
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="CalendarDayButton">
                    <Border x:Name="Bd" Background="Transparent" BorderBrush="Transparent" BorderThickness="1" CornerRadius="6" Margin="1" MinWidth="32" MinHeight="30">
                        <ContentPresenter x:Name="Cp" TextElement.Foreground="#C9CED6" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1D2129"/> </Trigger>
                        <Trigger Property="IsInactive" Value="True"> <Setter TargetName="Cp" Property="TextElement.Foreground" Value="#5D6470"/> </Trigger>
                        <Trigger Property="IsToday" Value="True"> <Setter TargetName="Bd" Property="BorderBrush" Value="#4C8DFF"/> </Trigger>
                        <Trigger Property="IsSelected" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#4C8DFF"/> <Setter TargetName="Cp" Property="TextElement.Foreground" Value="White"/> </Trigger>
                        <Trigger Property="IsBlackedOut" Value="True"> <Setter Property="Opacity" Value="0.3"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="SwCalMonth" TargetType="CalendarButton">
        <Setter Property="Foreground" Value="#C9CED6"/>
        <Setter Property="FontSize" Value="13"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="CalendarButton">
                    <Border x:Name="Bd" Background="Transparent" BorderBrush="Transparent" BorderThickness="1" CornerRadius="6" Margin="2" MinWidth="52" MinHeight="44">
                        <ContentPresenter x:Name="Cp" TextElement.Foreground="#C9CED6" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"> <Setter TargetName="Bd" Property="Background" Value="#1D2129"/> </Trigger>
                        <Trigger Property="HasSelectedDays" Value="True"> <Setter TargetName="Bd" Property="BorderBrush" Value="#4C8DFF"/> </Trigger>
                        <Trigger Property="IsInactive" Value="True"> <Setter TargetName="Cp" Property="TextElement.Foreground" Value="#5D6470"/> </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="SwCalendar" TargetType="Calendar">
        <Setter Property="CalendarDayButtonStyle" Value="{StaticResource SwCalDay}"/>
        <Setter Property="CalendarButtonStyle" Value="{StaticResource SwCalMonth}"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Calendar">
                    <StackPanel x:Name="PART_Root" HorizontalAlignment="Center"> <CalendarItem x:Name="PART_CalendarItem"/> </StackPanel>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style TargetType="Calendar" BasedOn="{StaticResource SwCalendar}"/>
    <!-- v1.3.0 (§85): tablo satırı (GridView) — sistem şablonunun açık renkli vurgu / seçim şeridi ve beyaz odak çerçevesi yok.
         Pencereler ItemContainerStyle'ı BasedOn ile türetir; kendi tetikleyicileri (ör. DNS "en hızlı" yeşili) bunun üstüne yazar. -->
    <Style x:Key="SwListRow" TargetType="ListViewItem">
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="Foreground" Value="#E6E8EB"/>
        <Setter Property="BorderBrush" Value="#1F232B"/>
        <Setter Property="BorderThickness" Value="0,0,0,1"/>
        <Setter Property="Padding" Value="2,4"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ListViewItem">
                    <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}">
                        <GridViewRowPresenter Margin="{TemplateBinding Padding}" VerticalAlignment="Center"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True"> <Setter Property="Background" Value="#181C23"/> </Trigger>
            <Trigger Property="IsSelected" Value="True"> <Setter Property="Background" Value="#1C2433"/> </Trigger>
        </Style.Triggers>
    </Style>
'@

$xamlSettings = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="@@win_settings_title@@" Height="1000" Width="620" MinHeight="700" MinWidth="560"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterScreen" WindowStyle="ToolWindow" ResizeMode="CanResize">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <!-- v1.3.0 (§63): bölümler kaydırılabilir alanda; pencere küçülünce kaydırma çubuğu çıkar, alt düğmeler sabit kalır -->
    <Grid Margin="20">
        <Grid.RowDefinitions> <RowDefinition Height="*"/> <RowDefinition Height="Auto"/> </Grid.RowDefinitions>
        <ScrollViewer Grid.Row="0" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <Grid Margin="0,0,10,0">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/> <!-- 0: Görünüm -->
            <RowDefinition Height="Auto"/> <!-- 1: Geliştirici -->
            <RowDefinition Height="Auto"/> <!-- 2: LİSTE YÖNETİMİ -->
            <RowDefinition Height="Auto"/> <!-- 3: SİSTEM GERİ YÜKLEME -->
            <RowDefinition Height="Auto"/> <!-- 4: PROGRAM GÜNCELLEMESİ -->
            <RowDefinition Height="Auto"/> <!-- 5: GERİ BİLDİRİM (v1.2.3) -->
            <RowDefinition Height="Auto"/> <!-- 6: Dosyalar -->
        </Grid.RowDefinitions>

        <!-- 1. GÖRÜNÜM -->
        <Border Grid.Row="0" Style="{StaticResource SwCard}" Margin="0,0,0,12">
            <StackPanel>
                <TextBlock Text="@@set_appearance@@" Style="{StaticResource SwSection}" Margin="0,0,0,5"/>
                <StackPanel Orientation="Horizontal" Margin="0,4,0,0">
                    <TextBlock Text="@@set_language@@:" VerticalAlignment="Center" Margin="0,0,10,0"/>
                    <ComboBox x:Name="cmbLanguage" Width="190"/>
                </StackPanel>
                <CheckBox x:Name="chkAdminLauncher" Content="@@set_adminlauncher@@" ToolTip="@@set_adminlauncher_tip@@" Margin="0,12,0,0"/>
            </StackPanel>
        </Border>

        <!-- 2. GELİŞTİRİCİ MODU -->
        <Border Grid.Row="1" Style="{StaticResource SwCard}" Margin="0,0,0,12">
            <StackPanel>
                <TextBlock Text="@@set_dev_title@@" Style="{StaticResource SwSection}" Margin="0,0,0,5"/>
                <CheckBox x:Name="chkDisableCache" Content="@@set_dev_cache@@"/>
            </StackPanel>
        </Border>

        <!-- 3. LİSTE YÖNETİMİ -->
        <Border Grid.Row="2" Style="{StaticResource SwCard}" Margin="0,0,0,12">
            <StackPanel>
                <TextBlock Text="@@set_list_title@@" Style="{StaticResource SwSection}" Margin="0,0,0,10"/>
                <StackPanel Orientation="Horizontal">
                    <Button x:Name="btnOpenBlacklist" Content="@@set_ignored@@" MinWidth="120" Margin="0,0,10,0"/>
                    <Button x:Name="btnOpenCustom" Content="@@set_customrules@@" MinWidth="120" Margin="0,0,10,0"/>
					<Button x:Name="btnEditWinapp2" Content="@@set_winapp2edit@@" Margin="0,0,10,0"/>
                </StackPanel>
            </StackPanel>
        </Border>

        <!-- 4. SİSTEM GERİ YÜKLEME (YENİ) -->
        <Border Grid.Row="3" Style="{StaticResource SwCard}" Margin="0,0,0,12">
            <StackPanel>
                <TextBlock Text="@@set_restore_title@@" Style="{StaticResource SwSection}" Margin="0,0,0,10"/>
                <WrapPanel Orientation="Horizontal" Margin="0,0,0,6">
                    <RadioButton x:Name="rbRPAsk"   Content="@@set_rp_ask@@"  GroupName="RPMode" Margin="0,0,16,6"/>
                    <RadioButton x:Name="rbRPAuto"  Content="@@set_rp_auto@@"   GroupName="RPMode" Margin="0,0,16,6"/>
                    <RadioButton x:Name="rbRPNever" Content="@@set_rp_never@@"     GroupName="RPMode" Margin="0,0,0,6"/>
                </WrapPanel>
                <TextBlock x:Name="txtRPInfo" Text="Son nokta: -- • VSS servisi: --" Foreground="#8A919C" FontSize="12" Margin="0,6,0,10"/>
                <StackPanel Orientation="Horizontal">
                    <Button x:Name="btnRPManualCreate" Content="@@set_rp_manual@@" MinWidth="180" Margin="0,0,10,0"/>
                    <Button x:Name="btnRPWindowsPanel" Content="@@set_rp_panel@@" MinWidth="200"/>
                </StackPanel>
            </StackPanel>
        </Border>

        <!-- 5. PROGRAM GÜNCELLEMESİ -->
        <Border Grid.Row="4" Style="{StaticResource SwCard}" Margin="0,0,0,12">
            <StackPanel>
                <TextBlock Text="@@set_update_title@@" Style="{StaticResource SwSection}" Margin="0,0,0,8"/>
                <Grid Margin="0,0,0,8">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="*"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel Grid.Column="0">
                        <TextBlock Text="@@set_curver@@" Foreground="#8A919C" FontSize="12"/>
                        <TextBlock x:Name="txtCurrentVersion" Text="v?.?.?" FontWeight="SemiBold" FontSize="15" Margin="0,2,0,0"/>
                    </StackPanel>
                    <StackPanel Grid.Column="1">
                        <TextBlock Text="@@set_ghrepo@@" Foreground="#8A919C" FontSize="12"/>
                        <TextBlock x:Name="txtAppRepo" Text="" Foreground="#8CB4FF" FontSize="13" Margin="0,2,0,0" TextTrimming="CharacterEllipsis"/>
                    </StackPanel>
                </Grid>
                <TextBlock x:Name="txtUpdateStatus" Text="Sürüm kontrolü için 'Şimdi Kontrol Et'e basın." Foreground="#8A919C" FontSize="12" Margin="0,4,0,8" TextWrapping="Wrap"/>
                <StackPanel Orientation="Horizontal">
                    <Button x:Name="btnCheckUpdate" Content="@@set_checkupdate@@" MinWidth="170" Margin="0,0,10,0"/>
                    <Button x:Name="btnOpenReleases" Content="@@set_releases@@" MinWidth="170"/>
                </StackPanel>
            </StackPanel>
        </Border>

        <!-- 6. GERİ BİLDİRİM & İLETİŞİM (v1.2.3) -->
        <Border Grid.Row="5" Style="{StaticResource SwCard}" Margin="0,0,0,12">
            <StackPanel>
                <TextBlock Text="@@set_feedback_title@@" Style="{StaticResource SwSection}" Margin="0,0,0,4"/>
                <TextBlock Text="@@set_feedback_desc@@" Foreground="#8A919C" FontSize="12" Margin="0,0,0,8" TextWrapping="Wrap"/>
                <Button x:Name="btnOpenFeedback" Content="@@set_feedback_btn@@" MinWidth="220" HorizontalAlignment="Left"/>
            </StackPanel>
        </Border>

        <!-- 7. DOSYA YÖNETİMİ -->
        <TextBlock Grid.Row="6" Text="@@set_datafiles@@" Style="{StaticResource SwSection}" Margin="0,0,0,5"/>
        <ListBox x:Name="lstFiles" Grid.Row="6" SelectionMode="Extended" Margin="0,26,0,4" MinHeight="140" MaxHeight="260"/>

        </Grid>
        </ScrollViewer>

        <!-- 8. ALT BUTONLAR (kaydırma alanının dışında, hep görünür) -->
        <Grid Grid.Row="1" Margin="0,12,0,0">
            <Grid.ColumnDefinitions> <ColumnDefinition Width="Auto"/> <ColumnDefinition Width="*"/> <ColumnDefinition Width="Auto"/> </Grid.ColumnDefinitions>
            <Button x:Name="btnDeleteFiles" Grid.Column="0" Content="@@set_delete_sel@@" Style="{StaticResource SwBtnDanger}"/>
            <StackPanel Grid.Column="2" Orientation="Horizontal">
                <Button x:Name="btnImportUI" Content="@@set_import@@" Margin="0,0,6,0"/>
                <Button x:Name="btnExportUI" Content="@@set_export@@"/>
            </StackPanel>
        </Grid>
    </Grid>
</Window>
"@

$xamlNightMode = @"
<Window xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
        xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'
        Title='@@nm_title@@' Height='480' Width='580' Background='#0F1115' Foreground='#E6E8EB' FontFamily='{DynamicResource UiFont}' FontSize='14' WindowStartupLocation='CenterOwner' WindowStyle='ToolWindow' ResizeMode='NoResize'>
    
    <Window.Resources>
$($global:SubTheme)
        <!-- BUTON STİLİ (Renk sorunu çözüldü) -->
        
    </Window.Resources>

    <Grid Margin='20'>
        <Grid.RowDefinitions>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='*'/>
            <RowDefinition Height='Auto'/>
        </Grid.RowDefinitions>

        <TextBlock Text='@@nm_autoshut@@' Foreground='#8CB4FF' FontSize='22' FontWeight='Bold' HorizontalAlignment='Center'/>
        <TextBlock Grid.Row='1' Text='@@nm_choosewhen@@' Foreground='#8A919C' FontSize='13' HorizontalAlignment='Center' Margin='0,5,0,20'/>

        <!-- SEKMELER -->
        <TabControl x:Name='tcNightMode' Grid.Row='2' Background='Transparent' BorderThickness='0'>
            <TabControl.Resources>
                <Style TargetType='TabItem'>
                    <Setter Property='Template'>
                        <Setter.Value>
                            <ControlTemplate TargetType='TabItem'>
                                <Border Name='Border' BorderThickness='1' BorderBrush='#232831' Background='#15181E' Margin='0,0,5,0' Padding='15,8' CornerRadius='4'>
                                    <ContentPresenter x:Name='ContentSite' VerticalAlignment='Center' HorizontalAlignment='Center' ContentSource='Header' RecognizesAccessKey='True'/>
                                </Border>
                                <ControlTemplate.Triggers>
                                    <Trigger Property='IsSelected' Value='True'>
                                        <Setter TargetName='Border' Property='Background' Value='#1C2433'/>
                                        <Setter TargetName='Border' Property='BorderBrush' Value='#4C8DFF'/>
                                        <Setter Property='Foreground' Value='#E6E8EB'/>
                                    </Trigger>
                                    <Trigger Property='IsSelected' Value='False'>
                                        <Setter Property='Foreground' Value='#8A919C'/>
                                    </Trigger>
                                </ControlTemplate.Triggers>
                            </ControlTemplate>
                        </Setter.Value>
                    </Setter>
                </Style>
            </TabControl.Resources>

            <!-- 1. SÜRE MODU -->
            <TabItem Header='@@nm_tab_time@@'>
                <StackPanel Margin='0,20,0,0'>
                    <TextBlock Text='@@nm_after@@' Foreground='#E6E8EB' FontSize='15' Margin='0,0,0,10'/>
                    <StackPanel Orientation='Horizontal'>
                        <TextBox x:Name='txtHours' Width='64' Height='38' FontSize='17' TextAlignment='Center' VerticalContentAlignment='Center' Text='1'/>
                        <TextBlock Text='@@nm_hours@@' Foreground='#A9B0BB' VerticalAlignment='Center' Margin='10,0,20,0'/>
                        <TextBox x:Name='txtMins' Width='64' Height='38' FontSize='17' TextAlignment='Center' VerticalContentAlignment='Center' Text='30'/>
                        <TextBlock Text='@@nm_mins@@' Foreground='#A9B0BB' VerticalAlignment='Center' Margin='10,0,0,0'/>
                    </StackPanel>
                </StackPanel>
            </TabItem>

            <!-- 2. AĞ MODU (Siyah zorlaması silindi, orjinal beyaz oldu) -->
            <TabItem Header='@@nm_tab_net@@'>
                <StackPanel Margin='0,20,0,0'>
                    <TextBlock Text='@@nm_belowspeed@@' Foreground='#E6E8EB' FontSize='15' Margin='0,0,0,10'/>
                    <StackPanel Orientation='Horizontal' Margin='0,0,0,15'>
                        <ComboBox x:Name='cbNetSpeed' Width='140' MinHeight='32' VerticalContentAlignment='Center'>
                            <ComboBoxItem Content='0.5 Mbps' Tag='0.5'/>
                            <ComboBoxItem Content='1 Mbps' Tag='1' IsSelected='True'/>
                            <ComboBoxItem Content='5 Mbps' Tag='5'/>
                        </ComboBox>
                    </StackPanel>
                    <TextBlock Text='@@nm_waittime@@' Foreground='#E6E8EB' FontSize='15' Margin='0,0,0,10'/>
                    <ComboBox x:Name='cbNetWait' Width='140' MinHeight='32' VerticalContentAlignment='Center'>
                        <ComboBoxItem Content='@@nm_2min@@' Tag='2'/>
                        <ComboBoxItem Content='@@nm_5min@@' Tag='5' IsSelected='True'/>
                        <ComboBoxItem Content='@@nm_10min@@' Tag='10'/>
                    </ComboBox>
                </StackPanel>
            </TabItem>

            <!-- 3. UYGULAMA MODU (Siyah zorlaması silindi, orjinal beyaz oldu) -->
            <TabItem Header='@@nm_tab_app@@'>
                <StackPanel Margin='0,20,0,0'>
                    <TextBlock Text='@@nm_pickclient@@' Foreground='#E6E8EB' FontSize='15' Margin='0,0,0,10'/>
                    <ComboBox x:Name='cbProcess' MinHeight='32' VerticalContentAlignment='Center' Margin='0,0,0,15'/>
                    <TextBlock Text='@@nm_event@@' Foreground='#E6E8EB' FontSize='15' Margin='0,0,0,10'/>
                    <TextBlock Text='@@nm_eventdesc@@' Foreground='#E0A23B' FontSize='13' TextWrapping='Wrap'/>
                </StackPanel>
            </TabItem>
        </TabControl>

        <!-- ALT BUTONLAR VE DURUM -->
        <Grid Grid.Row='3' Margin='0,20,0,0'>
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width='*'/>
                <ColumnDefinition Width='Auto'/>
                <ColumnDefinition Width='Auto'/>
            </Grid.ColumnDefinitions>
            <TextBlock x:Name='txtStatus' Grid.Column='0' Text='@@nm_status_off@@' Foreground='#8A919C' VerticalAlignment='Center' TextWrapping='Wrap'/>
            
            <!-- v1.3.0 (B13 Grup 5): düğmeler ortak stil bloğundan -->
            <Button Style="{StaticResource SwBtnDanger}" x:Name='btnStop' Grid.Column='1' Content='@@btn_stop@@' MinWidth='90' Height='35' Margin='0,0,10,0' IsEnabled='False'/>
            <Button Style="{StaticResource SwBtnPrimary}" x:Name='btnStart' Grid.Column='2' Content='@@btn_start@@' MinWidth='120' Height='35'/>
        </Grid>
    </Grid>
</Window>
"@

# --- GERİ SAYIM / UYANDIRMA EKRANI ---
$xamlCountdown = @"
<Window xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
        xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'
        Title='@@cd_title@@' WindowStyle='None' WindowState='Maximized' Topmost='True' AllowsTransparency='True' Background='#E60F1115' Foreground='#E6E8EB' FontFamily='{DynamicResource UiFont}' FontSize='14'>
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid>
        <StackPanel HorizontalAlignment='Center' VerticalAlignment='Center'>
            <TextBlock Text='@@btn_shutdown@@' Foreground='#8CB4FF' FontSize='38' FontWeight='Bold' HorizontalAlignment='Center' Margin='0,0,0,20'/>
            <TextBlock Text='@@cd_reached@@' Foreground='#E6E8EB' FontSize='26' HorizontalAlignment='Center' TextAlignment='Center' TextWrapping='Wrap' MaxWidth='1100' Margin='0,0,0,40'/>
            <TextBlock x:Name='txtSeconds' Text='60' Foreground='#E5484D' FontSize='120' FontWeight='Bold' HorizontalAlignment='Center' Margin='0,0,0,50'/>
            <Button x:Name='btnAbort' Style='{StaticResource SwBtnDangerSolid}' Content='@@cd_abort@@' Width='360' Height='80' FontSize='26' FontWeight='Bold'>
                <Button.Effect> <DropShadowEffect Color='#E5484D' BlurRadius='20' ShadowDepth='0' Opacity='0.6'/> </Button.Effect>
            </Button>
        </StackPanel>
    </Grid>
</Window>
"@

$xamlExport = @"

<Window
    xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
    xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Title='@@set_export@@' Height='300' Width='400' Background='#0F1115' Foreground='#E6E8EB' FontFamily='{DynamicResource UiFont}' FontSize='14' WindowStartupLocation='CenterScreen' WindowStyle='ToolWindow' ResizeMode='NoResize'>
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid Margin='20'>
        <Grid.RowDefinitions>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='*'/>
            <RowDefinition Height='Auto'/>
        </Grid.RowDefinitions>
        <TextBlock Text='@@exp_whatbackup@@' Foreground='#8CB4FF' FontWeight='Bold' Margin='0,0,0,15'/>
        <StackPanel Grid.Row='1'>
            <CheckBox x:Name='chkBlacklist' Content='@@exp_blacklist@@' Foreground='#E6E8EB' IsChecked='True' Margin='0,0,0,8'/>
            <CheckBox x:Name='chkPathOverrides' Content='@@exp_custompaths@@' Foreground='#E6E8EB' IsChecked='True' Margin='0,0,0,8'/>
            <CheckBox x:Name='chkCustomRules' Content='@@exp_customrules@@' Foreground='#E6E8EB' IsChecked='True' Margin='0,0,0,8'/>
            <CheckBox x:Name='chkWinget' Content='@@exp_winget@@' Foreground='#E6E8EB' IsChecked='True' Margin='0,0,0,8'/>
            <CheckBox x:Name='chkTweaks' Content='@@exp_tweaks@@' Foreground='#E6E8EB' IsChecked='True' Margin='0,0,0,8'/>
            <CheckBox x:Name='chkMyProfile' Content='@@exp_profile@@' Foreground='#E6E8EB' IsChecked='True' Margin='0,0,0,8'/>
        </StackPanel>
        <Button Style="{StaticResource SwBtnPrimary}" x:Name='btnDoExport' Grid.Row='2' Content='@@exp_do@@' Height='35' FontWeight='Bold'/>
    </Grid>
</Window>
"@
$xamlWingetMgr = @"

<Window
    xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
    xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Title='@@wm_title@@' Height='520' Width='540' Background='#0F1115' Foreground='#E6E8EB' FontFamily='{DynamicResource UiFont}' FontSize='14' WindowStartupLocation='CenterScreen' WindowStyle='ToolWindow'>
    <Window.Resources>
$($global:SubTheme)
        
        
    </Window.Resources>
    <Grid Margin='15'>
        <Grid.RowDefinitions>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='*'/>
            <RowDefinition Height='Auto'/>
        </Grid.RowDefinitions>
        <StackPanel Grid.Row='0' Orientation='Horizontal' HorizontalAlignment='Center' Margin='0,0,0,15'>
            <RadioButton Name='rbModeWinget' Margin='0,0,20,0' FontWeight='SemiBold' Content='@@tab_winget@@' IsChecked='True' GroupName='Mode'/>
            <RadioButton Name='rbModeAppx' FontWeight='SemiBold' Content='@@wm_windows@@' GroupName='Mode'/>
        </StackPanel>
        <TextBlock Name='lblTitle' Grid.Row='1' Text='@@wm_addlabel@@' Foreground='#8CB4FF' FontWeight='Bold' Margin='0,0,0,10'/>
        <Grid Grid.Row='2' Margin='0,0,0,15'>
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width='*'/>
                <ColumnDefinition Width='*'/>
                <ColumnDefinition Width='120'/>
            </Grid.ColumnDefinitions>
            <StackPanel Grid.Column='0' Margin='0,0,5,0'>
                <TextBlock Text='@@wm_name@@' Foreground='#8A919C' FontSize='12'/>
                <TextBox x:Name='txtName'/>
            </StackPanel>
            <StackPanel Grid.Column='1' Margin='0,0,5,0'>
                <TextBlock x:Name='lblID' Text='ID' Foreground='#8A919C' FontSize='12'/>
                <TextBox x:Name='txtID'/>
            </StackPanel>
            <Button Style="{StaticResource SwBtnPrimary}" x:Name='btnAddW' Grid.Column='2' Content='@@m_add_caps@@' Height='38' VerticalAlignment='Bottom'/>
        </Grid>
        <ListBox x:Name='lstWinget' Grid.Row='3' Background='#15181E' Foreground='#E6E8EB' BorderThickness='0' Margin='0,0,0,10'/>
        <StackPanel Grid.Row='4' Orientation='Horizontal' HorizontalAlignment='Right'>
            <Button x:Name='btnEditW' Content='@@m_edit@@' MinWidth='80' Height='30' Margin='0,0,10,0'/>
            <Button Style="{StaticResource SwBtnDanger}" x:Name='btnDelW' Content='@@m_delete@@' MinWidth='100' Height='30' Margin='0,0,10,0'/>
            <Button Style="{StaticResource SwBtnPrimary}" x:Name='btnCloseW' Content='@@m_save@@' MinWidth='120' Height='30'/>
        </StackPanel>
    </Grid>
</Window>
"@
$xamlTweakMgr = @"
<Window
    xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
    xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Title='Ayar Yöneticisi' Height='900' Width='1180' Background='#0F1115' Foreground='#E6E8EB' FontFamily='{DynamicResource UiFont}' FontSize='14' WindowStartupLocation='CenterScreen' WindowStyle='ToolWindow'>
    <Window.Resources>
$($global:SubTheme)
        <Style TargetType='TextBlock'>
            <Setter Property='Foreground' Value='#A9B0BB'/>
            <Setter Property='VerticalAlignment' Value='Center'/>
            <Setter Property='Margin' Value='0,0,10,0'/>
        </Style>
    </Window.Resources>
    <Grid Margin='15'>
        <Grid.ColumnDefinitions>
            <ColumnDefinition Width='410'/>
            <ColumnDefinition Width='20'/>
            <ColumnDefinition Width='*'/>
        </Grid.ColumnDefinitions>
        <Grid Grid.Column='0'>
            <Grid.RowDefinitions>
                <RowDefinition Height='*'/>
                <RowDefinition Height='Auto'/>
            </Grid.RowDefinitions>
            <ListBox x:Name='lstTweaks' Grid.Row='0'/>
            <StackPanel Grid.Row='1' Orientation='Horizontal' HorizontalAlignment='Center' Margin='0,10,0,0'>
                <Button x:Name='btnNewTweak' Content='+ Yeni' MinWidth='80' Style='{StaticResource SwBtnPrimary}' Margin='0,0,6,0'/>
                <Button x:Name='btnCloneTweak' Content='🔁 Klonla' MinWidth='90' Margin='0,0,6,0' ToolTip='Seçili ayarı kopyalayarak yeni bir ayar oluşturur.'/>
                <Button x:Name='btnDelTweak' Content='@@m_delete@@' MinWidth='70' Style='{StaticResource SwBtnDanger}'/>
            </StackPanel>
        </Grid>
        <Border Grid.Column='2' Style='{StaticResource SwCard}' Padding='16'>
			<ScrollViewer VerticalScrollBarVisibility='Visible' HorizontalScrollBarVisibility='Disabled'>
				<Grid Margin='0,0,18,0'>
					<Grid.ColumnDefinitions>
						<ColumnDefinition Width='*'/>
					</Grid.ColumnDefinitions>
					<StackPanel Grid.Column='0' HorizontalAlignment='Stretch'>
                    <TextBlock Text='AYAR DETAYLARI' Style='{StaticResource SwSection}' FontSize='17' Margin='0,0,0,15'/>
                    <Grid Margin='0,0,0,10'>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width='90'/>
                            <ColumnDefinition Width='*'/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Text='Ad:' Grid.Column='0'/>
                        <TextBox x:Name='txtName' Grid.Column='1'/>
                    </Grid>
                    <Grid Margin='0,0,0,10'>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width='90'/>
                            <ColumnDefinition Width='*'/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Text='Kategori:' Grid.Column='0'/>
                        <ComboBox x:Name='cbCategory' Grid.Column='1' IsEditable='True'/>
                    </Grid>
                    <Grid Margin='0,0,0,10'>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width='90'/>
                            <ColumnDefinition Width='*'/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Text='Alt Kat:' Grid.Column='0'/>
                        <TextBox x:Name='txtSubCat' Grid.Column='1'/>
                    </Grid>
                    <Grid Margin='0,0,0,10'>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width='90'/>
                            <ColumnDefinition Width='*'/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Text='Grup ID:' Grid.Column='0'/>
                        <TextBox x:Name='txtGroup' Grid.Column='1' ToolTip='Aynı Grup adı (ör. NetProfile, DNS, WUPolicy) radyo düğmesi gibi çalışır: biri açılınca diğeri kapanır. Komut / tespit Kaydet ile silinmez.'/>
                    </Grid>
                    
                    <!-- YENİ EKLENEN AÇIKLAMA (TOOLTIP) KUTUSU -->
                    <Grid Margin='0,0,0,10'>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width='90'/>
                            <ColumnDefinition Width='*'/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Text='Açıklama:' Grid.Column='0' VerticalAlignment='Top' Margin='0,5,0,0' Foreground='#E0A23B' FontWeight='SemiBold'/>
                        <TextBox x:Name='txtTweakDesc' Grid.Column='1' Height='50' TextWrapping='Wrap' AcceptsReturn='True' BorderBrush='#6E5A2E' ToolTip='Bu metin, ayarın üzerine gelindiğinde ipucu (Tooltip) olarak gösterilir.'/>
                    </Grid>

                    <Grid Margin='0,0,0,10'>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width='90'/>
                            <ColumnDefinition Width='*'/>
                            <ColumnDefinition Width='90'/>
                            <ColumnDefinition Width='*'/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Text='Restart:' Grid.Column='0'/>
                        <ComboBox x:Name='cbRestartMode' Grid.Column='1' SelectedIndex='0' ToolTip='Yok = hiçbir şey | Soft = açık Explorer pencereleri yenilenir | Hard = Explorer kill+restart'>
                            <ComboBoxItem Content='Yok'/>
                            <ComboBoxItem Content='Soft (Refresh)'/>
                            <ComboBoxItem Content='Hard (Restart)'/>
                        </ComboBox>
                        <TextBlock Text='Risk:' Grid.Column='2' Margin='10,0,10,0'/>
                        <ComboBox x:Name='cbRiskLevel' Grid.Column='3' SelectedIndex='0' ToolTip='Yüksek riskli ayarlar Apply sırasında ekstra onay ister.'>
                            <ComboBoxItem Content='🟢 Düşük'/>
                            <ComboBoxItem Content='🟡 Orta'/>
                            <ComboBoxItem Content='🔴 Yüksek'/>
                        </ComboBox>
                    </Grid>
                    <WrapPanel Orientation='Horizontal' Margin='0,0,0,15'>
                        <TextBlock Text='Tür:' Width='90'/>
                        <RadioButton x:Name='rbReg' Content='Kayıt Defteri' IsChecked='True' Margin='0,0,10,0'/>
                        <RadioButton x:Name='rbCmd' Content='Komut (CMD/PS)' Margin='0,0,10,0'/>
                        <RadioButton x:Name='rbBatch' Content='Toplu İşlem (Batch/JSON)' Margin='0,0,10,0'/>
                        <RadioButton x:Name='rbDns' Content='DNS'/>
                    </WrapPanel>
                    <StackPanel x:Name='pnlRegistry'>
                        <TextBlock Text='Registry Ayarları' Style='{StaticResource SwSection}' Margin='0,0,0,10'/>
                        <TextBlock Text='Key:'/>
                        <TextBox x:Name='txtKey' Margin='0,5,0,10'/>
                        <Grid Margin='0,0,0,10'>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width='*'/>
                                <ColumnDefinition Width='100'/>
                            </Grid.ColumnDefinitions>
                            <StackPanel Grid.Column='0' Margin='0,0,10,0'>
                                <TextBlock Text='ValueName:'/>
                                <TextBox x:Name='txtValueName' Margin='0,5,0,0'/>
                            </StackPanel>
                            <StackPanel Grid.Column='1'>
                                <TextBlock Text='Tipi:'/>
                                <ComboBox x:Name='cbType' Margin='0,5,0,0'>
                                    <ComboBoxItem Content='DWord'/>
                                    <ComboBoxItem Content='String'/>
                                    <ComboBoxItem Content='Binary'/>
                                </ComboBox>
                            </StackPanel>
                        </Grid>
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width='*'/>
                                <ColumnDefinition Width='*'/>
                            </Grid.ColumnDefinitions>
                            <StackPanel Grid.Column='0' Margin='0,0,5,0'>
                                <TextBlock Text='Data:'/>
                                <TextBox x:Name='txtData' Margin='0,5,0,0'/>
                            </StackPanel>
                            <StackPanel Grid.Column='1' Margin='5,0,0,0'>
                                <TextBlock Text='Undo:'/>
                                <TextBox x:Name='txtUndo' Margin='0,5,0,0'/>
                            </StackPanel>
                        </Grid>
                    </StackPanel>
                    <StackPanel x:Name='pnlCommand' Visibility='Collapsed'>
                        <TextBlock Text='Komut' Style='{StaticResource SwSection}' Margin='0,0,0,10'/>
                        <TextBlock Text='Command:'/>
                        <TextBox x:Name='txtCommand' Height='60' TextWrapping='Wrap' AcceptsReturn='True' Margin='0,5,0,10'/>
                        <TextBlock Text='Undo:'/>
                        <TextBox x:Name='txtUndoCommand' Height='60' TextWrapping='Wrap' AcceptsReturn='True' Margin='0,5,0,0'/>
                    </StackPanel>
                    <StackPanel x:Name='pnlBatch' Visibility='Collapsed'>
                        <TextBlock Text='Batch Editör' Style='{StaticResource SwSection}' Margin='0,0,0,5'/>
                        <TextBox x:Name='txtRawInput' Height='150' TextWrapping='Wrap' AcceptsReturn='True' FontFamily='Cascadia Mono, Consolas' FontSize='12' Margin='0,5,0,5'/>
                        <StackPanel Orientation='Horizontal' HorizontalAlignment='Right' Margin='0,0,0,10'>
                            <Button x:Name='btnConvert' Content='JSON Dönüştür' MinWidth='140' Margin='0,0,6,0'/>
                            <Button x:Name="btnValidate" Content="✔ Yapıyı Kontrol Et" MinWidth="130"/>
                        </StackPanel>
                        <TextBlock Text='Sonuç:' FontSize='12' Foreground='#8A919C'/>
                        <TextBox x:Name='txtBatchInput' Height='200' TextWrapping='Wrap' AcceptsReturn='True' FontFamily='Cascadia Mono, Consolas' FontSize='13' VerticalScrollBarVisibility='Auto'/>
                    </StackPanel>
                    <StackPanel x:Name='pnlDns' Visibility='Collapsed'>
                        <TextBlock Text='DNS' Style='{StaticResource SwSection}' Margin='0,0,0,10'/>
                        <Grid Margin='0,0,0,10'>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width='*'/>
                                <ColumnDefinition Width='10'/>
                                <ColumnDefinition Width='*'/>
                            </Grid.ColumnDefinitions>
                            <StackPanel Grid.Column='0'>
                                <TextBlock Text='DNS 1:'/>
                                <TextBox x:Name='txtDns1' Margin='0,5,0,0'/>
                            </StackPanel>
                            <StackPanel Grid.Column='2'>
                                <TextBlock Text='DNS 2:'/>
                                <TextBox x:Name='txtDns2' Margin='0,5,0,0'/>
                            </StackPanel>
                        </Grid>
                        <CheckBox x:Name='chkDnsIPv6' Content='IPv6' Margin='0,10,0,10'/>
                        <Grid x:Name='grdIPv6' IsEnabled='False' Opacity='0.5'>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width='*'/>
                                <ColumnDefinition Width='10'/>
                                <ColumnDefinition Width='*'/>
                            </Grid.ColumnDefinitions>
                            <StackPanel Grid.Column='0'>
                                <TextBlock Text='IPv6 1:'/>
                                <TextBox x:Name='txtDns6_1' Margin='0,5,0,0'/>
                            </StackPanel>
                            <StackPanel Grid.Column='2'>
                                <TextBlock Text='IPv6 2:'/>
                                <TextBox x:Name='txtDns6_2' Margin='0,5,0,0'/>
                            </StackPanel>
                        </Grid>
                    </StackPanel>
                    <!-- ÖNİZLEME PANELİ -->
                    <Border Background='#13161B' BorderBrush='#232831' BorderThickness='1' CornerRadius='8' Padding='12' Margin='0,15,0,10'>
                        <StackPanel>
                            <TextBlock Text='📋 ÖNİZLEME (Etkilenecek değerler)' Style='{StaticResource SwSection}' Margin='0,0,0,6'/>
                            <TextBox x:Name='txtPreview' IsReadOnly='True' Background='#0C0E12' Foreground='#9AA3B2' FontFamily='Cascadia Mono, Consolas' FontSize='12' Height='100' TextWrapping='Wrap' VerticalScrollBarVisibility='Auto' BorderThickness='0' Text='Bir ayar seçin veya yeni ayar oluşturun...'/>
                        </StackPanel>
                    </Border>
                    <StackPanel Orientation='Horizontal' HorizontalAlignment='Right' Margin='0,5,0,0'>
                        <Button x:Name='btnPreviewRefresh' Content='🔄 Önizleme Yenile' MinWidth='150' Height='36' Margin='0,0,10,0'/>
                        <Button x:Name='btnSaveTweak' Content='KAYDET' MinWidth='120' Height='36' Style='{StaticResource SwBtnPrimary}'/>
                    </StackPanel>
                </StackPanel>
			 </Grid>
            </ScrollViewer>
        </Border>
    </Grid>
</Window>
"@
$xamlPrivacyWarn = @"

<Window
    xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
    xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Title='@@pw_title@@' SizeToContent='Height' Width='450' MaxHeight='600' Background='#0F1115' Foreground='#E6E8EB' FontFamily='{DynamicResource UiFont}' FontSize='14' WindowStartupLocation='CenterScreen' WindowStyle='ToolWindow' ResizeMode='NoResize'>
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid Margin='20'>
        <Grid.RowDefinitions>
            <RowDefinition Height='*'/>
