# --- GERI BILDIRIM PENCERESI (v1.2.3) ---
$xamlFeedback = @"
<Window
    xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
    xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'
    Title='@@set_feedback_btn@@' Height='600' Width='620'
    Background='#0F1115' Foreground='#E6E8EB' FontFamily='{DynamicResource UiFont}' FontSize='14' WindowStartupLocation='CenterScreen' WindowStyle='ToolWindow' ResizeMode='NoResize'>
    <Window.Resources>
$($global:SubTheme)
        <!-- Ana pencereden birebir kopya — Silme Yontemi dropdown'u ile ayni stil -->
        <ControlTemplate x:Key='ComboBoxToggleButton' TargetType='ToggleButton'>
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition />
                    <ColumnDefinition Width='20' />
                </Grid.ColumnDefinitions>
                <Border x:Name='Border' Grid.ColumnSpan='2' CornerRadius='2' Background='#1D2129' BorderBrush='#232831' BorderThickness='1' />
                <Path x:Name='Arrow' Grid.Column='1' Fill='White' HorizontalAlignment='Center' VerticalAlignment='Center' Data='M 0 0 L 4 4 L 8 0 Z'/>
            </Grid>
        </ControlTemplate>
        
        
    </Window.Resources>
    <Grid Margin='20'>
        <Grid.RowDefinitions>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='*'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
        </Grid.RowDefinitions>

        <TextBlock Grid.Row='0' Text='@@fb_header@@' Foreground='#E6E8EB' FontSize='20' FontWeight='Bold' Margin='0,0,0,4'/>
        <TextBlock Grid.Row='1' Text='@@fb_desc@@' Foreground='#8A919C' FontSize='12' Margin='0,0,0,12' TextWrapping='Wrap'/>

        <!-- TUR + BASLIK -->
        <Grid Grid.Row='2' Margin='0,0,0,10'>
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width='130'/>
                <ColumnDefinition Width='*'/>
            </Grid.ColumnDefinitions>
            <ComboBox x:Name='cbFeedbackType' Grid.Column='0' Background='#15181E' Foreground='#E6E8EB' BorderBrush='#232831' Padding='6' SelectedIndex='0'>
                <ComboBoxItem Content='@@fb_bug@@' Tag='bug'/>
                <ComboBoxItem Content='@@fb_suggestion@@' Tag='suggestion'/>
                <ComboBoxItem Content='@@fb_question@@' Tag='question'/>
            </ComboBox>
            <TextBox x:Name='txtFeedbackTitle' Grid.Column='1' Margin='10,0,0,0' Background='#15181E' Foreground='#E6E8EB' BorderBrush='#232831' Padding='6' Tag='Başlık (kısa, açıklayıcı)'/>
        </Grid>

        <!-- MESAJ ETIKETI -->
        <TextBlock Grid.Row='3' Text='@@fb_msglabel@@' Foreground='#C9CED6' FontSize='13' Margin='0,0,0,4'/>

        <!-- MESAJ TEXTAREA (MaxLength: Discord/GitHub limitlerini asmasin) -->
        <TextBox x:Name='txtFeedbackBody' Grid.Row='4' Background='#15181E' Foreground='#E6E8EB' BorderBrush='#232831' Padding='6'
                 AcceptsReturn='True' TextWrapping='Wrap' VerticalScrollBarVisibility='Auto' MinHeight='160' MaxLength='3500'/>

        <!-- E-POSTA -->
        <Grid Grid.Row='5' Margin='0,12,0,4'>
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width='Auto'/>
                <ColumnDefinition Width='*'/>
            </Grid.ColumnDefinitions>
            <TextBlock Grid.Column='0' Text='@@fb_email@@' Foreground='#C9CED6' FontSize='13' VerticalAlignment='Center' Margin='0,0,10,0'/>
            <TextBox x:Name='txtFeedbackEmail' Grid.Column='1' Background='#15181E' Foreground='#E6E8EB' BorderBrush='#232831' Padding='6'/>
        </Grid>

        <!-- SISTEM BILGILERI CHECKBOX -->
        <CheckBox x:Name='chkIncludeSystem' Grid.Row='6' Foreground='#C9CED6' FontSize='13' IsChecked='True' Margin='0,8,0,0'>
            <CheckBox.Content>
                <TextBlock Text='@@fb_includesys@@' TextWrapping='Wrap'/>
            </CheckBox.Content>
        </CheckBox>

        <!-- DURUM SATIRI -->
        <TextBlock x:Name='lblFeedbackStatus' Grid.Row='7' Text='' Foreground='#8A919C' FontSize='12' Margin='0,8,0,0' TextWrapping='Wrap'/>

        <!-- BUTONLAR -->
        <StackPanel Grid.Row='8' Orientation='Horizontal' HorizontalAlignment='Right' Margin='0,12,0,0'>
            <Button x:Name='btnFeedbackCancel' Content='@@m_cancel@@' MinWidth='85' Height='32' Margin='0,0,8,0'/>
            <Button x:Name='btnFeedbackClipboard' Content='@@fb_clipboard@@' MinWidth='150' Height='32' Margin='0,0,8,0'/>
            <Button x:Name='btnFeedbackGitHub' Content='@@fb_github@@' Background='#24292E' Foreground='White' MinWidth='130' Height='32' Margin='0,0,8,0'/>
            <Button x:Name='btnFeedbackSend' Content='@@fb_discord@@' Background='#5865F2' Foreground='White' MinWidth='110' Height='32' FontWeight='Bold'/>
        </StackPanel>
    </Grid>
</Window>
"@

$xamlAddCustom = @"

<Window
    xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
    xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Title='@@ac_title@@' Height='330' Width='500' Background='#0F1115' Foreground='#E6E8EB' FontFamily='{DynamicResource UiFont}' FontSize='14' WindowStartupLocation='CenterScreen' WindowStyle='ToolWindow' ResizeMode='NoResize'>
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid Margin='20'>
        <Grid.RowDefinitions>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='Auto'/>
            <RowDefinition Height='*'/>
        </Grid.RowDefinitions>
        <TextBlock Text='@@ac_path@@' Foreground='#E6E8EB' Margin='0,0,0,5'/>
        <Grid Grid.Row='1' Margin='0,0,0,15'>
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width='*'/>
                <ColumnDefinition Width='Auto'/>
            </Grid.ColumnDefinitions>
            <TextBox x:Name='txtCustomPath' Height='28'/>
            <Button x:Name='btnBrowse' Grid.Column='1' Content='...' MinWidth='35' Height='28' Margin='5,0,0,0'/>
        </Grid>
