# v1.3.0 (§60): gömülü Inter'i %APPDATA%\MrClean\fonts\ altına çıkarır (yalnız eksik / bozuksa yazar). Klasör Uri'si ya da $null döner.
function Initialize-UiFont([string]$Dir = (Join-Path $AppDataPath 'fonts')) {
    try {
        if (-not $global:UiFontFiles) { return $null }
        if (-not (Test-Path -LiteralPath $Dir)) { New-Item -ItemType Directory -Path $Dir -Force | Out-Null }
        foreach ($name in $global:UiFontFiles.Keys) {
            $f = $global:UiFontFiles[$name]
            $p = Join-Path $Dir $name
            $ok = (Test-Path -LiteralPath $p) -and ((Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash -eq $f.Sha)
            if (-not $ok) {
                [IO.File]::WriteAllBytes($p, [Convert]::FromBase64String($f.B64))
                if ((Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash -ne $f.Sha) { return $null }
            }
        }
        $full = (Resolve-Path -LiteralPath $Dir).ProviderPath.TrimEnd('\') + '\'
        return New-Object System.Uri($full)
    } catch { return $null }
}

# Inter gerçekten açılabiliyorsa pencerenin UiFont / UiFontHead kaynaklarına bağlar; yoksa XAML'deki Segoe UI Variable kalır.
function Set-UiFont($window, $baseUri) {
    if (-not $window -or -not $baseUri) { return $false }
    try {
        # ::new (New-Object değil): New-Object PSObject sarmalı döndürüyor; Resources[...] (object) ona atanınca WPF 'geçerli FontFamily değil' diyor
        $ff = [System.Windows.Media.FontFamily]::new($baseUri, './#Inter, Segoe UI Variable Text, Segoe UI')
        $tf = [System.Windows.Media.Typeface]::new($ff, [System.Windows.FontStyles]::Normal, [System.Windows.FontWeights]::SemiBold, [System.Windows.FontStretches]::Normal)
        $gt = $null
        if (-not $tf.TryGetGlyphTypeface([ref]$gt)) { return $false }
        # Windows yolu büyük harfle döndürüyor; tr-TR'de -match 'I' harfinde şaştığı için kültürden bağımsız karşılaştırma
        if ([IO.Path]::GetFileName($gt.FontUri.LocalPath).ToUpperInvariant() -ne 'INTER-SEMIBOLD.TTF') { return $false }
        $window.Resources['UiFont'] = $ff
        $window.Resources['UiFontHead'] = $ff
        $script:UiFontFamily = $ff
        return $true
    } catch { return $false }
}

# v1.3.0 (§62, B13): alt pencere açılışı — Inter'i bağlar (Set-UiFont başarılıysa) ve ana penceredeki gibi koyu başlık çubuğu.
# XAML'in $($global:SubTheme) içermesi gerekir (UiFont kaynağı orada).
function Initialize-SubWindow($w) {
    if (-not $w) { return }
    # v1.3.0 (§87): XAML hazırlanmasından (Localize-Xaml) ilk çizime kadar geçen süre; Localize-Xaml kullanmayan pencerede buradan
    try {
        $mSw = $global:MrCleanSubWinSw; $global:MrCleanSubWinSw = $null
        if ($mSw -and $mSw.ElapsedMilliseconds -gt 120000) { $mSw = $null }   # bayat (ör. açılıştaki ana pencere XAML) sayılmaz
        if (-not $mSw) { $mSw = [Diagnostics.Stopwatch]::StartNew() }
        $w.Add_ContentRendered({ try { WpfLog ("[ÖLÇÜM] pencere '" + $this.Title + "': " + $mSw.ElapsedMilliseconds + " ms") } catch {} }.GetNewClosure())
    } catch {}
    try {
        if ($script:UiFontFamily) {
            $w.Resources['UiFont'] = $script:UiFontFamily
            $w.Resources['UiFontHead'] = $script:UiFontFamily
        }
    } catch {}
    try {
        $w.Add_SourceInitialized({
            try {
                $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($this)).Handle
                $v = 1;            [void][NativeMethods]::DwmSetWindowAttribute($hwnd, 20, [ref]$v, 4)
                $cap = 0x0015110F; [void][NativeMethods]::DwmSetWindowAttribute($hwnd, 35, [ref]$cap, 4)
                $txt = 0x00EBE8E6; [void][NativeMethods]::DwmSetWindowAttribute($hwnd, 36, [ref]$txt, 4)
                $bor = 0x00292420; [void][NativeMethods]::DwmSetWindowAttribute($hwnd, 34, [ref]$bor, 4)
            } catch {}
        })
    } catch {}
}

