        $tab = $Win.FindName([string]$this.Tag)
        if ($tab -and -not $tab.IsSelected) { $tab.IsSelected = $true }
    })
}
function Sync-NavToTab {
    $sel = $tabControl.SelectedItem
    if (-not $sel) { return }
    $nav = $script:NavItems[[string]$sel.Name]
    if ($nav -and -not $nav.IsChecked) {
        $script:NavSyncing = $true
        try { $nav.IsChecked = $true } finally { $script:NavSyncing = $false }
    }
}
