$script:LogRowHeight    = 200.0
$script:LogOpen         = $false
$script:LogUnread       = 0
function Set-LogPanelVisible([bool]$show) {
    if (-not $script:rowLog -or -not $script:bdLogPanel) { return }
    $isShown = "$($script:bdLogPanel.Visibility)" -eq 'Visible'
    if ($show -eq $isShown) { return }
    if ($show) {
        $script:rowLog.Height = New-Object System.Windows.GridLength($script:LogRowHeight)
        $script:rowLogSplit.Height = New-Object System.Windows.GridLength(8)
        $script:bdLogPanel.Visibility = 'Visible'; $script:splLog.Visibility = 'Visible'
        Set-LogUnread 0
        try { $txtLog.ScrollToEnd() } catch {}
    } else {
        # Kullanicinin surukleyerek verdigi yukseklik bir sonraki acilista geri gelir
        if ($script:rowLog.ActualHeight -ge 80) { $script:LogRowHeight = $script:rowLog.ActualHeight }
        $script:rowLog.Height = New-Object System.Windows.GridLength(0)
        $script:rowLogSplit.Height = New-Object System.Windows.GridLength(0)
        $script:bdLogPanel.Visibility = 'Collapsed'; $script:splLog.Visibility = 'Collapsed'
    }
}
# Panel kapaliyken gelen hata/uyari sayisi — "Islem kayitlari" dugmesinde kirmizi rozet; panel kendiliginden acilmaz.
function Set-LogUnread([int]$n) {
    $script:LogUnread = $n
    if (-not $script:bdLogBadge) { return }
    $script:txtLogBadge.Text = if ($n -gt 99) { "99+" } else { "$n" }
    $script:bdLogBadge.Visibility = if ($n -gt 0) { 'Visible' } else { 'Collapsed' }
}
