function Update-PageChrome {
    $onTweaks = [bool]($tabTweaks -and $tabTweaks.IsSelected)
    $onClean  = [bool]($script:tabClean -and $script:tabClean.IsSelected)
    $onRepair = [bool]($script:tabRepair -and $script:tabRepair.IsSelected)
    $onTools  = [bool]($script:tabTools -and $script:tabTools.IsSelected)
    $onWinget = [bool]($tabWinget -and $tabWinget.IsSelected)
    $onStartup = [bool]($script:tabStartup -and $script:tabStartup.IsSelected)
    $onLargeFiles = [bool]($script:tabLargeFiles -and $script:tabLargeFiles.IsSelected)
    $onCrash = [bool]($script:tabCrash -and $script:tabCrash.IsSelected)
    $ownChrome = $onTweaks -or $onClean -or $onRepair -or $onTools -or $onWinget -or $onStartup -or $onLargeFiles -or $onCrash
    # Temizlik ve Onarım kendi Analiz/Başlat düğmelerini taşıyor; alt çubuktaki grup gizli kalır (btnRun/btnAnalyze/cbSecureDelete arkada çalışır)
    if ($script:pnlRunActions)   { $script:pnlRunActions.Visibility   = 'Collapsed' }
    if ($onClean)  { try { Update-CleanPage } catch {} }
