# --- LOGO + ICON: Base64 embed'den memory stream ile yükle (PS2EXE tek-EXE deneyimi) ---
# Yan dosya aramaya gerek yok — global ($global:LogoIcoBase64; LogoPngBase64 §81'de kaldırıldı)
# region3'te gomulu. Eski $PSScriptRoot bagimliligi kaldirildi.
function Load-EmbeddedImage {
    param([string]$Base64, [bool]$Freeze = $true)
    if (-not $Base64) { return $null }
    try {
        $bytes = [Convert]::FromBase64String($Base64)
        $stream = New-Object System.IO.MemoryStream(,$bytes)
        $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
        $bmp.BeginInit()
        $bmp.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
        $bmp.StreamSource = $stream
        $bmp.EndInit()
        if ($Freeze) { $bmp.Freeze() }  # cross-thread guvenligi
        return $bmp
    } catch {
        return $null
    }
}

