function Pump-BootUi {
    $p = $script:pbBoot
    if ($p) {
        try {
            $target = 100.0
            if ($null -ne $script:BootPctTarget) { $target = [double]$script:BootPctTarget }
            $cur = [double]$p.Value
            if ($cur -lt $target) {
                $delta = ($target - $cur) * 0.22
                if ($delta -lt 0.9) { $delta = 0.9 }
                $next = $cur + $delta
                if ($next -gt $target) { $next = $target }
                $p.Value = $next
            }
        } catch {}
    }
    try {
        [System.Windows.Threading.Dispatcher]::CurrentDispatcher.Invoke(
            [System.Action]{},
            [System.Windows.Threading.DispatcherPriority]::Render
        )
    } catch {}
}

function Do-Events { 
    # UI sadece 20 milisaniyede bir yenilenir (Akıcı görünüm sağlar, CPU'yu yormaz)
    $bootVis = $false
    try { $bootVis = ($script:grdBootOverlay -and "$($script:grdBootOverlay.Visibility)" -eq 'Visible') } catch {}
    $limit = 20
    if ($bootVis) { $limit = 16 }
    if ($global:DoEventsTimer.ElapsedMilliseconds -gt $limit) {
        if ($bootVis) {
            Pump-BootUi
        } else {
            try {[System.Windows.Threading.Dispatcher]::CurrentDispatcher.Invoke(
                    [System.Action]{}, 
                    [System.Windows.Threading.DispatcherPriority]::Background
                ) 
            } catch {}
        }
        $global:DoEventsTimer.Restart()
    }
}

function Set-BootProgress([string]$key, [double]$pct) {
    $script:BootPctTarget = $pct
    $t = $script:txtBootStatus
    if ($t) { try { $t.Text = [string](T $key) } catch {} }
    Pump-BootUi
}

function Test-BootOverlayVisible {
    try { return ($script:grdBootOverlay -and "$($script:grdBootOverlay.Visibility)" -eq 'Visible') } catch { return $false }
}

# v1.3.0 (§87, §57 Adım 0): iş süresi ölçümü — davranışı değiştirmez, yalnız "[ÖLÇÜM] ad: N ms" kaydı yazar
# (kayıt paneli + session.log). Arka plan işleri için başlangıç / bitiş ayrı yerlerde çağrılır; global tablo
# (GetNewClosure kapanışlarından da erişilsin diye). Bitmeyen bir ölçüm sonraki başlangıçta üzerine yazılır.
$global:MrCleanMeasure = @{}
function Start-MrCleanMeasure([string]$Name) { try { $global:MrCleanMeasure[$Name] = [Diagnostics.Stopwatch]::StartNew() } catch {} }
function Stop-MrCleanMeasure([string]$Name, [string]$Note = '') {
    try {
        $sw = $global:MrCleanMeasure[$Name]
        if (-not $sw) { return }
        [void]$global:MrCleanMeasure.Remove($Name)
        WpfLog ("[ÖLÇÜM] " + $Name + ": " + $sw.ElapsedMilliseconds + " ms" + $(if ($Note) { " (" + $Note + ")" } else { "" }))
    } catch {}
}

function Measure-BootStep([string]$name, [scriptblock]$work) {
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try { & $work }
    finally {
        $ms = [int]$sw.ElapsedMilliseconds
        try { WpfLog ("[BOOT] " + $name + ": " + $ms + " ms") } catch {}
    }
}

function Complete-TweakTreeFirstVisit {
    if (-not $script:TweakTreeReady) { return }
    if (-not $tabTweaks -or -not $tabTweaks.IsSelected) { return }
    if ($global:TweaksLoaded) { return }
    $global:TweaksLoaded = $true
    try { Show-Privacy-Warning } catch {}
    try { Check-Tweak-Status } catch {}
}

function WpfLog([string]$text) { 
    if (-not $text) { return }
    
    if ($global:SessionLogWriter) { try { $global:SessionLogWriter.WriteLine("[$(Get-Date -Format 'HH:mm:ss')] $text") } catch {} }
    # UI henüz yüklenmediyse (pencere açılmadan log gelirse) hata vermesin
    if ($null -eq $txtLog -or $null -eq $Win) { return }

    $timestamp = Get-Date -Format "HH:mm:ss"
    $msg = "[$timestamp] $text"
    
    try {
        $Win.Dispatcher.Invoke([Action]{ 
            # --- PERFORMANS KORUMASI: SATIR SAYISI BAZLI LOG BUDAMA ---
            $currentLines = $txtLog.LineCount
            if ($currentLines -gt 500) {
                $allText = $txtLog.Text
                $lines = $allText -split "`r`n"
                $kept = $lines | Select-Object -Last 200
                $txtLog.Text = "... [Bellek tasarrufu — eski kayıtlar temizlendi] ...`r`n" + ($kept -join "`r`n") + "`r`n"
            }
            $txtLog.AppendText("$msg`r`n")
            $txtLog.ScrollToEnd() 
            if (-not $script:LogOpen -and $text -match '^\W{0,3}(\[(HATA|UYARI)|HATA\s*:|❌|⚠)') { Set-LogUnread ($script:LogUnread + 1) }
        })
    } catch {
        # Dispatcher erişim hatası (kapatma esnasında olabilir) - sessizce yoksay
    }
}

function Format-Size($bytes) { 
    if ($bytes -ge 1GB) { return "{0:N2} GB" -f ($bytes / 1GB) } 
    elseif ($bytes -ge 1MB) { return "{0:N2} MB" -f ($bytes / 1MB) } 
    else { return "{0:N2} KB" -f ($bytes / 1KB) } 
}

