# MrClean ile uygulanmis plana bagli tweak'ler: uygulama listesinde (HKCU AppliedTweaks) ya da guc yedegi alinmis
# (yedek her ilk uygulamada alinir, liste 6. turdan once uygulananlari icermeyebilir)
function Get-MrCleanPlanBoundAppliedNames {
    $r = @{}
    $list = @(); try { $list = @((Get-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AppliedTweaks" -ErrorAction SilentlyContinue).AppliedTweaks) } catch {}
    $bk = $null; try { $bk = Get-ItemProperty -Path "HKLM:\SOFTWARE\MrClean\PowerBackup" -ErrorAction SilentlyContinue } catch {}
    foreach ($n in $script:PlanBoundPowerTweaks.Keys) {
        if ($list -contains $n) { $r[$n] = $true; continue }
        foreach ($id in @($script:PlanBoundBackupIds[$n])) { if ($bk -and $null -ne $bk.$id) { $r[$n] = $true; break } }
    }
    return $r
}

function Get-MrCleanActiveSchemeGuid {
    $o = "$(& powercfg /getactivescheme 2>$null)"
    if ($o -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') { return $Matches[1].ToLowerInvariant() }
    return $null
}

# Plan degistikten sonra, daha once aktif olan plana bagli ayarlari yeni plana da yazar. Onay penceresi ve yedek yok:
# kullanici bunlari ilk uygulamada onayladi, yedek de o zaman alindi (Geri Al o yedege doner).
function Sync-MrCleanPlanBoundPower([string[]]$Names) {
    $done = New-Object System.Collections.Generic.List[string]
    foreach ($n in @($Names)) {
        $specs = $script:PlanBoundPowerTweaks[$n]
        if (-not $specs) { continue }
        foreach ($sp in @($specs)) {
            $p = $sp.Split('|')
            if ($p.Count -gt 4 -and $p[4] -eq 'A') { & powercfg /attributes $p[0] $p[1] -ATTRIB_HIDE 2>$null | Out-Null }
            if ($p[2] -match 'AC') { & powercfg -setacvalueindex SCHEME_CURRENT $p[0] $p[1] $p[3] 2>$null | Out-Null }
            if ($p[2] -match 'DC') { & powercfg -setdcvalueindex SCHEME_CURRENT $p[0] $p[1] $p[3] 2>$null | Out-Null }
        }
        $done.Add($n)
    }
    if ($done.Count) { & powercfg -setactive SCHEME_CURRENT 2>$null | Out-Null }
    return $done.ToArray()
}

# Guc plani tweak'leri once calissin; plan degistiyse onceden aktif olan plana bagli ayarlar yeni plana tasinsin.
# $Run: { param($tweak, $isUndo) ... } — Apply ve Hizli Geri Al kendi isleyicisini verir. Planla ilgisizleri calistirmaz.
function Invoke-MrCleanPowerPlanFirst($Disable, $Enable, [scriptblock]$Run) {
    $planOff = @(@($Disable) | Where-Object { $_ -and "$($_.Group)" -eq 'PowerPlan' })
    $planOn  = @(@($Enable)  | Where-Object { $_ -and "$($_.Group)" -eq 'PowerPlan' })
    if (($planOff.Count + $planOn.Count) -eq 0) { return }
    $before = Get-MrCleanActiveSchemeGuid
    foreach ($t in $planOff) { & $Run $t $true }
    foreach ($t in $planOn)  { & $Run $t $false }
    $after = Get-MrCleanActiveSchemeGuid
    if (-not $before -or -not $after -or $before -eq $after) { return }
    $touched = @{}
    foreach ($t in @(@($Disable) + @($Enable))) { if ($t -and $t.Name) { $touched[[string]$t.Name] = $true } }
    # Yalniz MrClean ile uygulanmis olanlar tasinir (uygulama listesi ya da guc yedegi). Plan varsayilani yuzunden aktif gorunen
    # ayar tasinmaz — test: Nihai'ye gecince "Disklerin Kapanmasini Engelle" planin kendi degeriyle aktif oldu, geri donuste
    # kullanicinin hic uygulamadigi bu ayar Yuksek Performans planina da yaziliyordu.
    $byMrClean = Get-MrCleanPlanBoundAppliedNames
    $carry = @($script:PlanBoundPowerTweaks.Keys | Where-Object { -not $touched.ContainsKey($_) -and $byMrClean.ContainsKey($_) -and $global:TweakStatusCache -and $global:TweakStatusCache.ContainsKey($_) -and [bool]$global:TweakStatusCache[$_] })
    $synced = @(Sync-MrCleanPlanBoundPower $carry)
    if ($synced.Count) {
        WpfLog ("[GÜÇ] Güç planı değişti; açık olan {0} güç ayarı yeni plana da yazıldı:" -f $synced.Count)
        foreach ($n in $synced) { WpfLog "   • $n" }
    }
}

function Get-MrCleanTweakDependents($t) {
    $out = New-Object System.Collections.Generic.List[string]
    if (-not $t) { return @() }
    if ($t.Group) {
        foreach ($item in (Get-AllTweakItems)) { $ot = $item.Tag; if ($ot -and "$($ot.Group)" -eq "$($t.Group)") { $out.Add([string]$ot.Name) } }
    }
    if ("$($t.Group)" -eq 'PowerPlan') { foreach ($n in $script:PlanBoundPowerTweaks.Keys) { $out.Add($n) } }
    $se = $script:TweakSideEffects[[string]$t.Name]
    if ($se) { foreach ($n in $se) { $out.Add($n) } }
    return $out.ToArray()
}

function Update-TweakStatusAfterApply($toEnable, $toDisable) {
    if (-not $global:TweakStatusCache) { $global:TweakStatusCache = @{} }
    # v1.3.0 (§93): uygulananlar artik denetlenmeden "aktif" sayilmiyor. Yalniz degisenler + etkiledikleri (ayni grup,
    # guc planina bagli ayarlar, [SIFIRLA]'nin geri aldiklari) canli denetlenir; 208'in tamami degil.
    Start-MrCleanMeasure 'Uygulama sonrası doğrulama'
    $enabled = @{}; $disabled = @{}; $check = @{}
    foreach ($t in @($toEnable))  { if ($t -and $t.Name) { $enabled[[string]$t.Name] = $true;  $check[[string]$t.Name] = $true; foreach ($d in (Get-MrCleanTweakDependents $t)) { $check[$d] = $true } } }
    foreach ($t in @($toDisable)) { if ($t -and $t.Name) { $disabled[[string]$t.Name] = $true; $check[[string]$t.Name] = $true; foreach ($d in (Get-MrCleanTweakDependents $t)) { $check[$d] = $true } } }
    try { Refresh-PowerCfg-Cache; Refresh-BcdEdit-Cache; Refresh-NetshTcp-Cache } catch {}
    $notOn = @(); $pendingReboot = @(); $stillOn = @(); $side = @()
    foreach ($item in (Get-AllTweakItems)) {
        $tw = $item.Tag; $n = [string]$tw.Name
        if (-not $n -or -not $check.ContainsKey($n)) { continue }
        $on = $false; try { $on = [bool](Test-TweakApplied $tw) } catch {}
        if ($enabled.ContainsKey($n) -and -not $on) {
            # Yeniden baslatma isteyen tweak'in tespiti baslatmadan once tutmayabilir: aktif kabul edilir, sonraki Denetle dogrular
            if ($tw.RequiresReboot -eq $true) { $pendingReboot += $n; $on = $true } else { $notOn += $n }
        }
        elseif ($disabled.ContainsKey($n) -and $on) { $stillOn += $n }
        elseif (-not $enabled.ContainsKey($n) -and -not $disabled.ContainsKey($n) -and $global:TweakStatusCache.ContainsKey($n) -and [bool]$global:TweakStatusCache[$n] -ne $on) {
            $side += [pscustomobject]@{ Name = $n; Now = $on }
        }
        $global:TweakStatusCache[$n] = $on
    }
    Stop-MrCleanMeasure 'Uygulama sonrası doğrulama' ("{0} ayar denetlendi" -f $check.Count)
    try {
        foreach ($n in $notOn)   { WpfLog "[DOĞRULAMA] ❌ Uygulandı ama etkin görünmüyor: $n" }
        foreach ($n in $stillOn) { WpfLog "[DOĞRULAMA] ❌ Geri alındı ama hâlâ etkin görünüyor: $n" }
        foreach ($n in $pendingReboot) { WpfLog "[DOĞRULAMA] ⏳ Yeniden başlatmadan sonra etkin olacak: $n" }
        foreach ($c in $side) { WpfLog ("[DOĞRULAMA] {0} {1}" -f $(if ($c.Now) { "↗ Bu işlemle aktif oldu:" } else { "↘ Bu işlemle pasife düştü:" }), $c.Name) }
        if (-not ($notOn.Count + $stillOn.Count)) { WpfLog ("[DOĞRULAMA] ✓ Değişen {0} ayarın hepsi doğrulandı." -f ($enabled.Count + $disabled.Count)) }
    } catch {}
    try {
        if ($script:TweakScanTimer -and $script:TweakScanTimer.IsEnabled) {
            $script:TweakScanTimer.Stop()
            if ($btnCheckTweaks) { $btnCheckTweaks.Content = "♻ Denetle"; $btnCheckTweaks.IsEnabled = $true }
        }
    } catch {}
    try { Save-TweakStatusCache $global:TweakStatusCache } catch {}
    try {
        foreach ($item in (Get-AllTweakItems)) {
            $n = [string]$item.Tag.Name
            if ($n -and $global:TweakStatusCache.ContainsKey($n)) {
                Set-TweakItemUI -item $item -isApplied ([bool]$global:TweakStatusCache[$n]) -fromCache $false
            }
        }
        Update-Parent-Headers-Recursive $tvTweaks.Items
        Update-TweakSummary $global:TweakStatusCache
    } catch {}
    # v1.3.0 (§99): Uygula sonrasi "Aktif" cipine ZORLA gecilmiyor (kullanici: baska tweak'ler de acacaktim, her seferinde
    # "Tumu"ne donmek zorunda kaliyordum). Secili cip kalir; Aktif / Pasif seciliyse liste yeni duruma gore yenilenir.
    try { Apply-TweakFilter } catch {}
}

# Ust bilgi bandi: "🪟 Windows 11 25H2 · 26200.xxxx   ✅ 34 / 112 aktif   ⛔ 3 uyumsuz"
# $ResultMap verilmezse sadece Windows bilgisi + uyumsuz sayisi yazilir.
function Update-TweakSummary($ResultMap = $null) {
    if (-not $txtTweakWinInfo) { return }
    $os  = if ($global:WinBuild -ge 22000) { "Windows 11" } elseif ($global:WinBuild) { "Windows 10" } else { "Windows" }
    $rel = if ($global:WinDisplayVersion) { $global:WinDisplayVersion } else { Get-WinReleaseLabel $global:WinBuild }
    $parts = @("⊞ $os $rel · $($global:WinBuild).$($global:WinUBR)")

    $items = Get-AllTweakItems
    $incompat = @($items | Where-Object { -not (Test-TweakBuildCompatible $_.Tag) }).Count
    if ($ResultMap -and $ResultMap.Count -gt 0) {
        # Sadece agacta GERCEKTEN olan tweak'leri say (eski surum cache'inde silinmis isimler kalmis olabilir)
        $active = @($items | Where-Object { $ResultMap.ContainsKey($_.Tag.Name) -and $ResultMap[$_.Tag.Name] }).Count
        $parts += ((T 'tw_active_count') -f $active, $items.Count)
        # v1.3.0: ilerleme cubugu — aktif / toplam orani, yumusak genislik animasyonu
        try {
            if ($bdTweakProgressFill -and $items.Count -gt 0) {
                $trackW = if ($bdTweakProgressTrack -and $bdTweakProgressTrack.ActualWidth -gt 0) { $bdTweakProgressTrack.ActualWidth } else { 220 }
                $script:TweakActiveRatio = $active / [double]$items.Count
                $target = [Math]::Round($trackW * $script:TweakActiveRatio, 1)
                $from = if ([double]::IsNaN($bdTweakProgressFill.Width)) { 0 } else { $bdTweakProgressFill.Width }
                $anim = New-Object System.Windows.Media.Animation.DoubleAnimation($from, $target, [TimeSpan]::FromMilliseconds(600))
                $anim.EasingFunction = New-Object System.Windows.Media.Animation.CubicEase
                $bdTweakProgressFill.BeginAnimation([System.Windows.FrameworkElement]::WidthProperty, $anim)
                if ($bdTweakProgressTrack) { $bdTweakProgressTrack.ToolTip = (T 'tw_active_count') -f $active, $items.Count }
            }
        } catch {}
    }
    if ($incompat -gt 0) { $parts += ((T 'tw_incompat_count') -f $incompat) }
    $txtTweakWinInfo.Text = $parts -join "    "
    try { $txtTweakWinInfo.ToolTip = "🖥 " + (Get-MrCleanHwSummary) } catch {}
}

# Tweak isminin yanindaki kucuk renkli etiket (YENİ / 24H2+)
function New-TweakBadge([string]$text, [string]$bg, [string]$fg = "#FFFFFF") {
    $b = New-Object System.Windows.Controls.Border
    $b.Background = $bg
    $b.CornerRadius = New-Object System.Windows.CornerRadius(4)
    $b.Padding = New-Object System.Windows.Thickness(6, 1, 6, 1)
    $b.Margin = New-Object System.Windows.Thickness(8, 0, 0, 0)
    $b.VerticalAlignment = 'Center'
    $t = New-Object System.Windows.Controls.TextBlock
    $t.Text = $text
    $t.FontSize = 10.5
    $t.FontWeight = 'SemiBold'
    $t.Foreground = $fg
    $b.Child = $t
    return $b
}

# v1.3.0 (tasarım E): anahtar son denetimden farkliysa "DEĞİŞECEK" rozetini gosterir. Son durum bilinmiyorsa gizli.
# Uygula butonu bekleyen degisiklik sayisini gosterir ("UYGULA · 2"); sayac $script:TweakPendingSet'ten okunur.
$script:TweakPendingSet = New-Object 'System.Collections.Generic.HashSet[string]'
function Get-TweakPendingBadge($chk) {
    if (-not $chk -or -not ($chk.Content -is [System.Windows.Controls.Panel])) { return $null }
    foreach ($c in $chk.Content.Children) { if ("$($c.Tag)" -eq "TweakPending") { return $c } }
    return $null
}
function Update-TweakApplyCount {
    if (-not $btnApplyTweaks) { return }
    $n = $script:TweakPendingSet.Count
    $btnApplyTweaks.Content = if ($n -gt 0) { "$(T 'btn_apply')  ·  $n" } else { T 'btn_apply' }
    try { Update-DashRecommendations } catch {}
}
function Set-TweakPendingState($chk, [string]$name, [bool]$pending) {
    $mark = Get-TweakPendingBadge $chk
    if ($mark) { $mark.Visibility = if ($pending) { 'Visible' } else { 'Collapsed' } }
    if (-not $name) { return }
    $changed = if ($pending) { $script:TweakPendingSet.Add($name) } else { $script:TweakPendingSet.Remove($name) }
    if ($changed) { Update-TweakApplyCount }
}
function Update-TweakPendingMark($chk) {
    if (-not (Get-TweakPendingBadge $chk)) { return }
    $pending = $false
    $item = $chk.Parent.Parent
    $name = if ($item -and $item.Tag) { [string]$item.Tag.Name } else { "" }
    if ($name -and $global:TweakStatusCache -and $global:TweakStatusCache.ContainsKey($name)) {
        $pending = ([bool]$global:TweakStatusCache[$name]) -ne ($chk.IsChecked -eq $true)
    }
    Set-TweakPendingState $chk $name $pending
}

function Create-Tweak-Item($tweak, [bool]$nested = $false, [string]$caption = "") {
    $item = New-Object System.Windows.Controls.TreeViewItem
    # Header = StackPanel { CheckBox } — Get-CheckFromItem Children[0]'i, tiklama isleyicisi $me.Parent.Parent'i kullanir
    $stack = New-Object System.Windows.Controls.StackPanel; $stack.Orientation = 'Horizontal'

    $chk = New-Object System.Windows.Controls.CheckBox
    $chk.Width = 640
    $chk.SetResourceReference([System.Windows.FrameworkElement]::WidthProperty, $(if ($nested) { "TweakRowWidthNested" } else { "TweakRowWidth" }))

    # Content = dikey StackPanel { satir1: [isim (Tag=TweakName)] [rozetler] ; satir2: aciklama ozeti ; satir3: kategori }
    $contentOuter = New-Object System.Windows.Controls.StackPanel
    $contentOuter.Orientation = 'Vertical'
    $contentPanel = New-Object System.Windows.Controls.StackPanel
    $contentPanel.Orientation = 'Horizontal'
    [void]$contentOuter.Children.Add($contentPanel)

    $lbl = New-Object System.Windows.Controls.TextBlock
    $lbl.Text = $tweak.Name
    $lbl.Tag = "TweakName"
    $lbl.FontSize = 14.5
    $lbl.FontWeight = 'Medium'
    $lbl.VerticalAlignment = 'Center'
    $lbl.TextTrimming = 'CharacterEllipsis'
    [void]$contentPanel.Children.Add($lbl)

    # Rozetler ismin SAGINA, Border icinde (Get-TweakDisplayName / Set-TweakItemUI ilk TextBlock'u isim kabul ediyor)
    $isCompatible = Test-TweakBuildCompatible $tweak
    $rsVal = "$($tweak.Risk)"
    if ($rsVal -eq "High") {
        $rk = New-TweakBadge (T 'tw_badge_risk_high') "#3A2226" "#F08A8A"
        $rk.ToolTip = "Yüksek risk — sistemi ciddi etkiler"
        [void]$contentPanel.Children.Add($rk)
    } elseif ($rsVal -eq "Medium") {
        $rk = New-TweakBadge (T 'tw_badge_risk_med') "#3A2E1A" "#E0A23B"
        $rk.ToolTip = "Orta risk"
        [void]$contentPanel.Children.Add($rk)
    }
    if (Test-TweakIsNew $tweak) {
        [void]$contentPanel.Children.Add((New-TweakBadge (T 'tw_badge_new') "#1C2B45" "#7FB0FF"))
    }
    if (-not $isCompatible) {
        [void]$contentPanel.Children.Add((New-TweakBadge (Get-TweakBuildRequirement $tweak) "#3A2226" "#F2A0A0"))
    }
    if (Test-TweakNeedsReboot $tweak) {
        $rb = New-TweakBadge (T 'tw_badge_reboot') "#23272F" "#A9B0BB"
        $rb.ToolTip = (T 'tw_badge_reboot_tip')
        [void]$contentPanel.Children.Add($rb)
    }

    # Alt satir: aciklamanin ilk cumlesi (kullanici ozel aciklamasi varsa o)
    $descSrc = if ($global:ItemDescriptions.ContainsKey($tweak.Name)) { $global:ItemDescriptions[$tweak.Name] } else { "$($tweak.Description)" }
    $sum = Get-TweakSummaryLine $descSrc
    if ($sum) {
        $sub = New-Object System.Windows.Controls.TextBlock
        $sub.Text = $sum
        $sub.Tag = "TweakSub"
        $sub.FontSize = 13
        $sub.Foreground = $script:TweakSubBrush
        $sub.Margin = New-Object System.Windows.Thickness(0, 3, 0, 0)
        $sub.TextTrimming = 'CharacterEllipsis'
        [void]$contentOuter.Children.Add($sub)
    }
    if ($caption) {
        $cap = New-Object System.Windows.Controls.TextBlock
        $cap.Text = $caption
        $cap.FontSize = 12
        $cap.Foreground = $script:TweakCaptionBrush
        $cap.Margin = New-Object System.Windows.Thickness(0, 3, 0, 0)
        $cap.TextTrimming = 'CharacterEllipsis'
        [void]$contentOuter.Children.Add($cap)
    }

    # Content = Grid { [metin bloklari] [BEKLİYOR rozeti — anahtarin hemen solunda] }
    $rowGrid = New-Object System.Windows.Controls.Grid
    $gc0 = New-Object System.Windows.Controls.ColumnDefinition; $gc0.Width = New-Object System.Windows.GridLength(1, 'Star')
    $gc1 = New-Object System.Windows.Controls.ColumnDefinition; $gc1.Width = [System.Windows.GridLength]::Auto
    $rowGrid.ColumnDefinitions.Add($gc0); $rowGrid.ColumnDefinitions.Add($gc1)
    [void]$rowGrid.Children.Add($contentOuter)
    $pend = New-TweakBadge (T 'tw_badge_pending') "#4C8DFF" "#FFFFFF"
    $pend.Child.FontWeight = 'Bold'
    $pend.Child.FontSize = 11
    $pend.Padding = New-Object System.Windows.Thickness(8, 2, 8, 2)
    $pend.Margin = New-Object System.Windows.Thickness(12, 0, 0, 0)
    $pend.Tag = "TweakPending"
    $pend.ToolTip = (T 'tw_badge_pending_tip')
    $pend.Visibility = 'Collapsed'
    [System.Windows.Controls.Grid]::SetColumn($pend, 1)
    [void]$rowGrid.Children.Add($pend)

    $chk.Content = $rowGrid
    $chk.Style = $Win.Resources["TweakRowToggle"]
    $chk.Add_Checked({ Update-TweakPendingMark $this })
    $chk.Add_Unchecked({ Update-TweakPendingMark $this })

    # Bu Windows surumunde gecersiz tweak: tiklanamaz + soluk. Apply-System-Tweaks ayrica atlar
    # (profil/import ile programatik isaretlenmis olsa bile).
    if (-not $isCompatible) {
        $chk.IsEnabled = $false
        $chk.Opacity = 0.45
        # v1.3.0 (§95): durum gelince aktifse yalniz kapatmak icin acilir (Set-TweakItemUI)
        if (-not $script:TweakIncompatNames) { $script:TweakIncompatNames = @{} }
        $script:TweakIncompatNames[[string]$tweak.Name] = $true
    }

    $chk.Add_Click({
        $me = $this; $treeItem = $me.Parent.Parent; $tweakObj = $treeItem.Tag
        if ($me.IsChecked -and $tweakObj.Group) {
            $parentFolder = $treeItem.Parent 
            foreach ($sibling in $parentFolder.Items) {
                if ($sibling -ne $treeItem -and $sibling.Tag.Group -eq $tweakObj.Group) { (Get-CheckFromItem $sibling).IsChecked = $false }
            }
        }
        $currentParent = $treeItem.Parent
        while ($currentParent -is[System.Windows.Controls.TreeViewItem]) {
            $allChildrenChecked = $true
            foreach ($child in $currentParent.Items) {
                if (-not (Get-CheckFromItem $child).IsChecked) { $allChildrenChecked = $false; break }
            }
            $parentChk = Get-CheckFromItem $currentParent
            if ($parentChk) { $parentChk.IsChecked = $allChildrenChecked }
            $currentParent = $currentParent.Parent
        }
    })

    $stack.Children.Add($chk) | Out-Null
    $item.Header = $stack
    $item.Tag = $tweak 
    $item.ContextMenu = $Win.Resources["TweakItemMenu"]
    
    # --- TOOLTIP KONTROLÜ (GÜNCELLENDİ) ---
    $finalDesc = ""
    # 1. Eğer kod içinde (hardcoded) Description tanımlıysa onu al
    if ($tweak.Description) { $finalDesc = $tweak.Description }
    # 2. Eğer sağ tıkla sonradan eklenmiş bir açıklama varsa (JSON), onu tercih et (Override)
    if ($global:ItemDescriptions.ContainsKey($tweak.Name)) { $finalDesc = $global:ItemDescriptions[$tweak.Name] }

    if (-not $isCompatible) {
        $hwWhy = ""; try { $hwWhy = Get-TweakHardwareReason $tweak } catch {}
        $buildBad = ($tweak.MinBuild -and $global:WinBuild -and $global:WinBuild -lt [int]$tweak.MinBuild) -or ($tweak.MaxBuild -and $global:WinBuild -and $global:WinBuild -gt [int]$tweak.MaxBuild)
        $req = if ($hwWhy -and -not $buildBad) { (T 'tw_hw_tip') -f $hwWhy } else { (T 'tw_incompat_tip') -f (Get-TweakBuildRequirement $tweak), "$($global:WinDisplayVersion) ($($global:WinBuild))" }
        $finalDesc = if ($finalDesc) { "$req`n`n$finalDesc" } else { $req }
        [System.Windows.Controls.ToolTipService]::SetShowOnDisabled($chk, $true)
    }

    if ($finalDesc) { Attach-ToolTip $chk $finalDesc }

    return $item
}

function Show-Privacy-Warning {
    # Eğer kullanıcı "Gösterme" dediyse direk çık
    if (-not $global:ShowPrivacyWarning) { return }

    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlPrivacyWarn))
        $winWarn = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winWarn
        
        $chk = $winWarn.FindName('chkDontShowAgain')
        $btn = $winWarn.FindName('btnOk')
        
        $btn.Add_Click({
            if ($chk.IsChecked) {
                $global:ShowPrivacyWarning = $false
                Mark-ConfigDirty # Tercihi kaydet
            }
            $winWarn.Close()
        })
        
        $winWarn.ShowDialog() | Out-Null
    } catch { WpfLog "❌ [HATA] Gizlilik uyarısı: $($_.Exception.Message)" }
}

function Apply-System-Tweaks {
    $script:ReapplySticky = $null   # 14. tur: guncelleme sonrasi denetim isaretleri UYGULA ile tuketilir
    $script:TweakApplyCacheHits = 0
    $script:TweakApplyLiveHits = 0
    # Son Denetle / disk cache / yarim tarama varsa 208 canli tarama yok — onay hemen gelir.
    if (-not $global:TweakStatusCache -or $global:TweakStatusCache.Count -lt 1) {
        if ($script:TweakScanResultMap -and $script:TweakScanResultMap.Count -gt 0) {
            $global:TweakStatusCache = $script:TweakScanResultMap.Clone()
        } else {
            try {
                $diskCache = Load-TweakStatusCache
                if ($diskCache -and $diskCache.Count -gt 0) { $global:TweakStatusCache = $diskCache }
            } catch {}
        }
    }
    if (-not $global:TweakStatusCache -or $global:TweakStatusCache.Count -lt 1) {
        Refresh-PowerCfg-Cache
        Refresh-BcdEdit-Cache
        Refresh-NetshTcp-Cache
    }
    $toEnable = New-Object System.Collections.ArrayList
    $toDisable = New-Object System.Collections.ArrayList
    
    $script:latencyChanged = $false

    function Scan-Nodes($nodes) {
        foreach ($node in $nodes) {
            if ($node.Tag -is[System.Collections.IDictionary] -or $node.Tag -is [System.Management.Automation.PSCustomObject]) {
                $tweak = $node.Tag
                if ($tweak.Name) {
                    $chk = Get-CheckFromItem $node
                    $isCurrentlyApplied = $false
                    try {
                        $isCurrentlyApplied = Get-TweakAppliedForApply $tweak
                    } catch { $isCurrentlyApplied = $false }

                    if ($chk.IsChecked -and -not $isCurrentlyApplied -and -not (Test-TweakBuildCompatible $tweak)) {
                        WpfLog "[ATLANDI] $($tweak.Name) — bu bilgisayarda uygulanamaz: $(Get-TweakBuildRequirement $tweak)."
                    }
                    elseif ($chk.IsChecked -and -not $isCurrentlyApplied) { $toEnable.Add($tweak) | Out-Null }
                    elseif (-not $chk.IsChecked -and $isCurrentlyApplied) { $toDisable.Add($tweak) | Out-Null }
                }
            }
            if ($node.Items.Count -gt 0) { Scan-Nodes $node.Items }
        }
    }
    
    Scan-Nodes $tvTweaks.Items
    try { WpfLog ("[UYGULA] durum: cache " + [int]$script:TweakApplyCacheHits + ", canli " + [int]$script:TweakApplyLiveHits) } catch {}

    $totalOps = $toEnable.Count + $toDisable.Count
    if ($totalOps -eq 0) {[System.Windows.MessageBox]::Show((T 'mbx_nochange'), (T 'mb_info')) | Out-Null; return }

    # --- MESAJ GÜNCELLEMESİ (Daha Anlaşılır) ---
    $msg = "Seçimleriniz (Açık/Kapalı durumları) sisteminizle eşitlenecek.`n`n"
    if ($toEnable.Count -gt 0) { $msg += "✅ $($toEnable.Count) ayar UYGULANACAK (Açılacak).`n" }
    if ($toDisable.Count -gt 0) { $msg += "❌ $($toDisable.Count) ayar GERİ ALINACAK (Varsayılana dönecek).`n" }
    $msg += "`nDevam edilsin mi?"
    
    if ([System.Windows.MessageBox]::Show($msg, "Tweak Eşitleme Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question) -ne 'Yes') { return }

    # --- YÜKSEK RİSK UYARISI (Sprint 4.4) ---
    # Risk="High" olan tweak'ler icin ek onay (sadece Apply icin, Undo'da risk yok)
    $highRiskApply = @($toEnable | Where-Object { "$($_.Risk)" -eq "High" })
    if ($highRiskApply.Count -gt 0) {
        $names = ($highRiskApply | ForEach-Object { "  • $($_.Name)" }) -join "`n"
        $hrMsg = "DİKKAT — Yüksek riskli ayar(lar) uygulanacak:`n`n$names`n`n" +
                 "Bu ayarlar sistem davranışını ciddi şekilde değiştirebilir veya geri alma gerektirebilir.`n`n" +
                 "Devam etmek istiyor musunuz?"
        if ([System.Windows.MessageBox]::Show($hrMsg, "Yüksek Risk Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning) -ne 'Yes') {
            WpfLog "[İPTAL] Yüksek riskli ayar onayı reddedildi."
            return
        }
    }

    # --- VENDOR UYUMSUZLUK UYARISI ---
    # Vendor="NVIDIA"|"AMD" tagli tweak'lerin sistemdeki GPU ile uyumlu olup olmadigini kontrol eder.
    # Sadece Apply icin (Undo'da dokunmuyoruz, halihazirda yazilmis registry'leri silmek genelde guvenli).
    $vendorMismatch = @($toEnable | Where-Object {
        $_.Vendor -and ((Get-System-Gpu-Vendors) -notcontains $_.Vendor)
    })
    if ($vendorMismatch.Count -gt 0) {
        $sysVendors = Get-System-Gpu-Vendors
        $sysList = if ($sysVendors.Count -gt 0) { $sysVendors -join ", " } else { "Algılanmadı" }
        $vmList  = ($vendorMismatch | ForEach-Object { "  • $($_.Name) (gerekli: $($_.Vendor))" }) -join "`n"
        $vmMsg   = "DİKKAT — GPU uyumsuzluğu tespit edildi:`n`n$vmList`n`n" +
                   "Sisteminizde algılanan GPU(lar): $sysList`n`n" +
                   "Bu ayar(lar) farklı bir GPU üreticisi için tasarlanmış. Yine de uygulansın mı?`n" +
                   "(Hibrit sistemler için — örn. dizüstü Intel+NVIDIA — devam edebilirsiniz.)"
        if ([System.Windows.MessageBox]::Show($vmMsg, "GPU Uyumsuzluk Uyarısı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning) -ne 'Yes') {
            WpfLog "[İPTAL] GPU uyumsuzluk uyarisi reddedildi."
            return
        }
    }

    # Sistem Geri Yukleme: mode gore sor/olustur/atla. Cancel ise tweak islemi durur.
    $rpOK = Create-Restore-Point "Tweak Islemleri"
    if (-not $rpOK) {
        WpfLog "--- TWEAK ISLEMI IPTAL EDILDI ---"
        return
    }

    WpfLog "--- TWEAK İŞLEMİ BAŞLATILIYOR ---"
    # Restart Explorer mantigi 3 seviyeli:
    #   $false / null  → hicbir sey yapma
    #   "Soft" / $true → SHChangeNotify + WM_SETTINGCHANGE broadcast (acik pencereler refresh)
    #   "Hard"         → explorer.exe'yi kill et + /factory ile yeniden baslat (taskbar/desktop yenilenir)
    # Geriye uyumluluk: $true → Hard kabul edilir (mevcut config'lerde kalmis olabilir)
    $script:needsRestart    = $false  # Hard restart bayragi
    $script:needsSoftRefresh = $false # Soft refresh bayragi

    function Process-TweakItem($tweakItem, $isUndo) {
        $actionName = if ($isUndo) { "Geri Alınıyor" } else { "Uygulanıyor" }
        WpfLog "$actionName : $($tweakItem.Name)"
        Do-Events

        # RestartExplorer field'ini parse et — "Hard" / $true → hard, "Soft" → soft
        $rpAction = $null
        if ($tweakItem.RestartExplorer) {
            $val = "$($tweakItem.RestartExplorer)"
            if ($val -eq "Hard" -or $val -eq "True") { $rpAction = "Hard" }
            elseif ($val -eq "Soft") { $rpAction = "Soft" }
        }
        if     ($rpAction -eq "Hard") { $script:needsRestart    = $true }
        elseif ($rpAction -eq "Soft") { $script:needsSoftRefresh = $true }
        
        # Reboot warning gerektiren tweak kategorileri — ancak tweak'in SkipRebootDialog=$true
        # flag'i varsa bypass et (ornek: Timer Resolution helper instant aktif olur, reboot gereksiz).
        # v1.2.22: $tweakItem.RequiresReboot=$true tek-bayrak ile spesifik tweak tetikleyebilir
        # (yeni tweak ekleyenler SubCategory pattern bekleyip detection logic guncellemek yerine
        # direkt flag koyar — future-proof). HAGS buna ornek.
        if ((-not $tweakItem.SkipRebootDialog) -and (
            $tweakItem.RequiresReboot -eq $true -or
            $tweakItem.Group -eq "NetProfile" -or
            $tweakItem.SubCategory -match "Giriş ve İşlemci" -or
            $tweakItem.SubCategory -match "Ağ ve Ping" -or
            $tweakItem.SubCategory -match "Zamanlayıcı" -or
            $tweakItem.Name -match "TCP" -or
            $tweakItem.Name -match "Win32" -or
            $tweakItem.Name -match "HPET")) {

            $script:latencyChanged = $true
        }
        
        $batchList = if ($tweakItem.Batch) { $tweakItem.Batch } else { @($tweakItem) }
        
        foreach ($sub in $batchList) {
            try {
                if ($isUndo -and $sub.UndoCommand) {
                    # NetProfile komutları UI thread'ini bloklayabilir — önce UI'ı flush et
                    if ($sub.Group -eq "NetProfile") { Do-Events; Start-Sleep -Milliseconds 50; Do-Events }
                    # GÜVENLİ ÇALIŞTIRMA: Invoke-Expression yerine ScriptBlock (Invoke-TweakCommand: mesajlar islem kaydina)
                    Invoke-TweakCommand $sub.UndoCommand
                }
                elseif (-not $isUndo -and $sub.Command) {
                    if ($sub.Group -eq "NetProfile") { Do-Events; Start-Sleep -Milliseconds 50; Do-Events }
                    Invoke-TweakCommand $sub.Command
                }
                elseif ($isUndo -and $sub.Command -and -not $sub.Key -and -not $sub.Group) {
                    WpfLog "[BİLGİ] '$($tweakItem.Name)' geri alınamaz (tek yönlü işlem) — atlandı."
                }
                elseif ($sub.Key) {
                    $targetValue = if ($isUndo) { $sub.Undo } else { $sub.Data }
                    if ($targetValue -eq "DELETE_KEY") { 
                        if ($sub.ValueName) { if (Test-Path $sub.Key) { Remove-ItemProperty -Path $sub.Key -Name $sub.ValueName -ErrorAction SilentlyContinue } } 
                        else { if (Test-Path $sub.Key) { Remove-Item -Path $sub.Key -Force -Recurse -ErrorAction Stop } }
                    } 
                    elseif ($targetValue -eq "DELETE_VALUE") { if (Test-Path $sub.Key) { Remove-ItemProperty -Path $sub.Key -Name $sub.ValueName -ErrorAction SilentlyContinue } }
                    else {
                        if (-not (Test-Path $sub.Key)) { try { New-Item -Path $sub.Key -Force -ErrorAction Stop | Out-Null } catch { continue } }
                        if ([string]::IsNullOrEmpty($sub.ValueName)) { Set-Item -Path $sub.Key -Value $targetValue -Force -ErrorAction Stop } 
                        else { Set-ItemProperty -Path $sub.Key -Name $sub.ValueName -Value $targetValue -Type $sub.Type -Force -ErrorAction Stop }
                    }
                }
            } catch { 
                $errTitle = if ($isUndo) { "Geri Alma" } else { "Uygulama" }
                $errMsg = $_.Exception.Message
                
                # Sadece kritik hataları göster
                if ($errMsg -match "Access is denied" -or $errMsg -match "Erişim engellendi") {
                    WpfLog "🛡️ [YETKİ HATASI] $actionName ($($tweakItem.Name)): Registry erişimi engellendi."
                } else {
                    WpfLog "❌ [HATA] $actionName ($($tweakItem.Name)): $errMsg"
                }
            }
        }
    }

    # v1.3.0 (§93): once guc plani (plan degisirse acik guc ayarlari yeni plana tasinir), sonra digerleri.
    # Eskiden agac sirasi: guc ayarlari eski plana yaziliyor, ardindan plan degisip kayboluyordu.
    Invoke-MrCleanPowerPlanFirst $toDisable $toEnable { param($tw, $undo) Process-TweakItem $tw $undo }
    foreach ($t in $toDisable) { if ("$($t.Group)" -ne 'PowerPlan') { Process-TweakItem $t $true } }
    foreach ($t in $toEnable)  { if ("$($t.Group)" -ne 'PowerPlan') { Process-TweakItem $t $false } }
    # v1.3.0 (6. tur): guncelleme sonrasi denetim icin uygulanan listeyi guncelle
    Update-MrCleanAppliedList -Enabled $toEnable -Disabled $toDisable

    # v1.2.19: Dogrulama log'u Debug Mode toggle'a baglandi (default OFF). Kullanici Debug Mode'u
    # acarsa Apply sonrasi her tweak'in gercek state'ini gorebilir — bug raporu icin degerli.
    # Default OFF cunku log temiz kalsin. Toplu ozet de Debug Mode icinde.
    $isDbgApply = $false; try { $isDbgApply = [bool]$chkDebug.IsChecked } catch {}
    if ($isDbgApply -and ($toEnable.Count + $toDisable.Count) -gt 0) {
        WpfLog "--- DOGRULAMA (Apply sonrasi gercek state) ---"
        $okCnt = 0; $failCnt = 0
        foreach ($t in $toEnable) {
            try {
                $isActive = Get-Tweak-IsActive $t
                if ($isActive) {
                    WpfLog "[DOGRULAMA] ✓ AKTIF : $($t.Name)"
                    $okCnt++
                } else {
                    WpfLog "[DOGRULAMA] ❌ APPLY BASARISIZ veya DetectScript yanlis dondurdu : $($t.Name) — switch otomatik kapanacak"
                    $failCnt++
                }
            } catch {
                WpfLog "[DOGRULAMA] ⚠️ Detect hatasi : $($t.Name) — $($_.Exception.Message)"
                $failCnt++
            }
        }
        foreach ($t in $toDisable) {
            try {
                $isActive = Get-Tweak-IsActive $t
                if (-not $isActive) {
                    WpfLog "[DOGRULAMA] ✓ GERI ALINDI : $($t.Name)"
                    $okCnt++
                } else {
                    WpfLog "[DOGRULAMA] ❌ UNDO BASARISIZ veya DetectScript hala true diyor : $($t.Name)"
                    $failCnt++
                }
            } catch {
                WpfLog "[DOGRULAMA] ⚠️ Detect hatasi : $($t.Name) — $($_.Exception.Message)"
                $failCnt++
            }
        }
        WpfLog "[DOGRULAMA] Toplam: ✓ $okCnt basarili, ❌ $failCnt sorunlu"
    }

    # --- QUICK UNDO için snapshot (Sprint 4.3) ---
    $global:LastTweakOperation = [ordered]@{
        Applied = @($toEnable)
        Undone  = @($toDisable)
        Time    = (Get-Date).ToString("o")
    }
    if ($btnQuickUndo) { $btnQuickUndo.IsEnabled = ($toEnable.Count + $toDisable.Count -gt 0) }

    # --- AUDIT LOG (Bonus E1) ---
    Write-TweakAuditLog -Operation "Apply" -Applied $toEnable -Undone $toDisable

    WpfLog "--- İŞLEM TAMAMLANDI ---"
    
    # --- ÖNCE / SONRA KARŞILAŞTIRMA RAPORU ---
    # 14. tur: @() sart — tek oge kalinca PS 5.1 hashtable.Count = anahtar sayisi donduruyordu ("GERI ALINAN (11 adet)", gercekte 1)
    $appliedCount  = @($toEnable  | Where-Object { $_ }).Count
    $revertedCount = @($toDisable | Where-Object { $_ }).Count
    
    if ($appliedCount -gt 0 -or $revertedCount -gt 0) {
        WpfLog "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
        WpfLog "📊 UYGULAMA ÖZETİ"
        WpfLog "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
        if ($appliedCount -gt 0) {
            WpfLog "✅ UYGULANAN ($appliedCount adet):"
            foreach ($t in $toEnable) {
                WpfLog "   + $($t.Name)"
            }
        }
        if ($revertedCount -gt 0) {
            WpfLog "↩️  GERİ ALINAN ($revertedCount adet):"
            foreach ($t in $toDisable) {
                WpfLog "   - $($t.Name)"
            }
        }
        WpfLog "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    }
    
    # Cache'i silip 208'i yeniden denetleme — sadece degisen satirlari isaretle, Aktif cipini ac
    try { Update-TweakStatusAfterApply $toEnable $toDisable } catch {
        try { WpfLog ("[UYGULA] cache guncelleme: " + $_.Exception.Message) } catch {}
    }

    # 1) ONCE Soft refresh — sessizce, kullaniciya sormadan yapilir (gorunum tweak'leri)
    if ($script:needsSoftRefresh) {
        Invoke-ShellSoftRefresh
    }

    # 1b) Dashboard refresh — DNS/network tweak'leri Genel Bakis sekmesindeki Aktif DNS metnini etkiler.
    # KRITIK: Load-DashboardData 5 DAKIKA cache kullaniyor (L11005). Tweak sonrasi cache eski DNS donuyor.
    # v1.2.6: Onceki versiyonda tabDashboard.IsSelected check'i vardi — kullanici Tweaks tab'da Apply ederken
    # bu false donuyor, Load-DashboardData hic cagrilmiyordu. Cozum: garantili tetikle (runspace arka planda
    # calisir, tab acik degilse de cache yenilenir, kullanici Dashboard'a gecince taze veri hazir olur).
    $global:DashCache = $null
    $global:DashCacheTime = $null
    try { Load-DashboardData } catch { WpfLog "[HATA] Dashboard refresh: $($_.Exception.Message)" }

    # 14. tur: Explorer yeniden baslatildiysa (Baslat menusu vb.) pencere sirasi sifirlanir; diyalog ana pencerenin ARKASINDA
    # acilip programi kilitliyordu (kullanici: "dondu, kapatamiyorum"). Once ana pencere one, diyaloglar sahipli + en ustte.
    try { $Win.Activate() | Out-Null } catch {}
    # 2) Restart dialog — latencyChanged en agir, sonra hard restart, sonra hicbir sey
    if ($script:latencyChanged) {
        Show-RestartDialog
    }
    elseif ($script:needsRestart) {
        $msg = "Bu degisiklikler icin Windows Gezgini'nin yeniden baslatilmasi gerekiyor.`n`n" +
               "Acik Explorer pencereleri kapatilacak (taskbar/desktop yenilenecek).`n`n" +
               "Simdi yapilsin mi?"
        if ([System.Windows.MessageBox]::Show($Win, $msg, "Explorer Yeniden Baslat", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question) -eq 'Yes') {
            Invoke-ExplorerHardRestart
        } else {
            WpfLog "[BILGI] Kullanici yeniden baslatmayi erteledi. Bazi degisiklikler bir sonraki oturum acmada uygulanacak."
        }
    }
}

function Show-TweakManager {
    param($TargetTweak = $null)
    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlTweakMgr))
        $winTM = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winTM
        
        # Kontroller
        $lst = $winTM.FindName('lstTweaks')
        $txtName = $winTM.FindName('txtName')
        $cbCategory = $winTM.FindName('cbCategory')
        $txtSubCat = $winTM.FindName('txtSubCat')
        $txtGroup = $winTM.FindName('txtGroup')
        $txtTweakDesc = $winTM.FindName('txtTweakDesc') # YENİ AÇIKLAMA KUTUSU
        
        $rbReg = $winTM.FindName('rbReg')
        $rbCmd = $winTM.FindName('rbCmd')
        $rbBatch = $winTM.FindName('rbBatch')
        $rbDns = $winTM.FindName('rbDns')
        
        $pnlReg = $winTM.FindName('pnlRegistry')
        $pnlCmd = $winTM.FindName('pnlCommand')
        $pnlBatch = $winTM.FindName('pnlBatch')
        $pnlDns = $winTM.FindName('pnlDns')
        
        $txtKey = $winTM.FindName('txtKey')
        $txtValueName = $winTM.FindName('txtValueName')
        $cbType = $winTM.FindName('cbType')
        $txtData = $winTM.FindName('txtData')
        $txtUndo = $winTM.FindName('txtUndo')
        
        $txtCommand = $winTM.FindName('txtCommand')
        $txtUndoCommand = $winTM.FindName('txtUndoCommand')
        
        $txtBatchInput = $winTM.FindName('txtBatchInput')
        $txtRawInput = $winTM.FindName('txtRawInput')
        $btnConvert = $winTM.FindName('btnConvert')
        $btnValidate = $winTM.FindName('btnValidate')
        
        $txtDns1 = $winTM.FindName('txtDns1')
        $txtDns2 = $winTM.FindName('txtDns2')
        $chkDnsIPv6 = $winTM.FindName('chkDnsIPv6')
        $grdIPv6 = $winTM.FindName('grdIPv6')
        $txtDns6_1 = $winTM.FindName('txtDns6_1')
        $txtDns6_2 = $winTM.FindName('txtDns6_2')
        
        $btnSave = $winTM.FindName('btnSaveTweak')
        $btnNew = $winTM.FindName('btnNewTweak')
        $btnDel = $winTM.FindName('btnDelTweak')

        # YENİ KONTROLLER (Sprint 3)
        $btnClone        = $winTM.FindName('btnCloneTweak')
        $cbRestartMode   = $winTM.FindName('cbRestartMode')
        $cbRiskLevel     = $winTM.FindName('cbRiskLevel')
        $txtPreview      = $winTM.FindName('txtPreview')
        $btnPreviewRfsh  = $winTM.FindName('btnPreviewRefresh')

        # Placeholder Mantığı
        $placeholderText = "Örnek Girişler:`n1. Yöntem:`nreg add `"HKEY_CURRENT_USER\Software\Test`" /v Ornek /t REG_DWORD /d 0 /f`n`n2. Yöntem (.reg dosyası içeriği):`n[HKEY_LOCAL_MACHINE\SOFTWARE\Policies\Microsoft\Windows\OneDrive]`n`"DisableFileSyncNGSC`"=dword:00000001"
        $txtRawInput.Text = $placeholderText
        $txtRawInput.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#6B7280')
        
        $txtRawInput.Add_GotFocus({ if ($this.Text -eq $placeholderText) { $this.Text = ""; $this.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#E6E8EB') } })
        $txtRawInput.Add_LostFocus({ if ([string]::IsNullOrWhiteSpace($this.Text)) { $this.Text = $placeholderText; $this.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#6B7280') } })

        $btnConvert.Add_Click({
            $rawText = $txtRawInput.Text
            if ([string]::IsNullOrWhiteSpace($rawText) -or $rawText -eq $placeholderText) { return }
            
            $convertedList = @()
            $currentRegKey = ""
            $lines = $rawText -split "`n"
            
            foreach ($line in $lines) {
                $l = $line.Trim()
                if ([string]::IsNullOrWhiteSpace($l) -or $l.StartsWith(";")) { continue }

                if ($l -match "^\[(.*)\]$") { 
                    $currentRegKey = $Matches[1] -replace "HKEY_LOCAL_MACHINE", "HKLM:" -replace "HKEY_CURRENT_USER", "HKCU:"
                    continue 
                }

                if ($currentRegKey -ne "" -and $l -match '^"([^"]+)"=(.*)$') {
                     $vName = $Matches[1]; $vDataRaw = $Matches[2].Trim()
                     $vType = "String"; $vData = $vDataRaw -replace '"', ''
                     if ($vDataRaw -match "dword:([0-9a-fA-F]+)") { $vType = "DWord"; $vData = [Convert]::ToInt32($Matches[1], 16) }
                     $undoVal = if ($vData -eq 0) { 1 } else { 0 }
                     $convertedList += [ordered]@{ ValueName = $vName; Undo = $undoVal; Key = $currentRegKey; Data = $vData; Type = $vType }
                }

                if ($l -match 'reg add\s+"?([^"]+)"?\s+/v\s+"?([^"]+)"?\s+/t\s+(\w+)\s+/d\s+"?([^"/]+)"?') {
                    $rKey = $Matches[1] -replace "HKEY_LOCAL_MACHINE", "HKLM:" -replace "HKEY_CURRENT_USER", "HKCU:"
                    $rValName = $Matches[2]; $rTypeRaw = $Matches[3]; $rDataRaw = $Matches[4].Trim() -replace '"', ''
                    $rType = "String"; $rData = $rDataRaw
                    if ($rTypeRaw -eq "REG_DWORD") { $rType = "DWord"; $rData = [int]$rDataRaw }
                    $rUndo = if ($rData -eq 0) { 1 } else { 0 }
                    $convertedList += [ordered]@{ ValueName = $rValName; Undo = $rUndo; Key = $rKey; Data = $rData; Type = $rType }
                }
            }
            if ($convertedList.Count -gt 0) { $txtBatchInput.Text = $convertedList | ConvertTo-Json -Depth 5 } 
            else { [System.Windows.MessageBox]::Show("Geçerli format bulunamadı.", "Hata") | Out-Null }
        })

        $btnValidate.Add_Click({
            try {
                if ([string]::IsNullOrWhiteSpace($txtBatchInput.Text)) { throw "Kutu boş." }
                $testObj = $txtBatchInput.Text | ConvertFrom-Json
                $count = if ($testObj -is [Array]) { $testObj.Count } else { 1 }[System.Windows.MessageBox]::Show("✔ JSON Yapısı Geçerli!`nToplam İşlem Sayısı: $count", "Onaylandı") | Out-Null
            } catch { [System.Windows.MessageBox]::Show("❌ JSON Formatı HATALI!`n$($_.Exception.Message)", "Hata", [System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Error) | Out-Null }
        })

        $global:TweakList.Keys | ForEach-Object { $cbCategory.Items.Add($_) | Out-Null }
        
        function Refresh-List { 
            $lst.Items.Clear()
            foreach ($cat in $global:TweakList.Keys) { 
                foreach ($t in $global:TweakList[$cat]) { 
                    $lItem = New-Object System.Windows.Controls.ListBoxItem
                    $lItem.Content = "$cat - $($t.Name)"
                    $lItem.Tag = $t
                    $lst.Items.Add($lItem) | Out-Null 
                } 
            } 
        }
        Refresh-List
        
        $rbReg.Add_Checked({ $pnlReg.Visibility='Visible'; $pnlCmd.Visibility='Collapsed'; $pnlBatch.Visibility='Collapsed'; $pnlDns.Visibility='Collapsed' })
        $rbCmd.Add_Checked({ $pnlReg.Visibility='Collapsed'; $pnlCmd.Visibility='Visible'; $pnlBatch.Visibility='Collapsed'; $pnlDns.Visibility='Collapsed' })
        $rbBatch.Add_Checked({ $pnlReg.Visibility='Collapsed'; $pnlCmd.Visibility='Collapsed'; $pnlBatch.Visibility='Visible'; $pnlDns.Visibility='Collapsed' })
        $rbDns.Add_Checked({ $pnlReg.Visibility='Collapsed'; $pnlCmd.Visibility='Collapsed'; $pnlBatch.Visibility='Collapsed'; $pnlDns.Visibility='Visible' })
        $chkDnsIPv6.Add_Click({ if ($chkDnsIPv6.IsChecked) { $grdIPv6.IsEnabled=$true; $grdIPv6.Opacity=1 } else { $grdIPv6.IsEnabled=$false; $grdIPv6.Opacity=0.5 } })

        # Liste Seçimi (Yükleme)
        $lst.Add_SelectionChanged({
            if ($lst.SelectedIndex -ne -1) {
                $selTweak = $lst.SelectedItem.Tag
                $txtName.Text = $selTweak.Name
                $cbCategory.Text = $global:TweakList.Keys | Where-Object { $global:TweakList[$_] -contains $selTweak }
                
                $txtSubCat.Text = if ($selTweak.SubCategory) { $selTweak.SubCategory } else { "" }
                $txtGroup.Text = if ($selTweak.Group) { $selTweak.Group } else { "" }
                
                # --- YENİ EKLENEN: AÇIKLAMAYI (TOOLTIP) GETİR (DÜZELTİLDİ) ---
                if ($global:ItemDescriptions.ContainsKey($selTweak.Name)) {
                    # 1. Öncelik: Kullanıcının sonradan düzenleyip kaydettiği açıklama
                    $txtTweakDesc.Text = $global:ItemDescriptions[$selTweak.Name]
                } elseif ($selTweak.Description) {
                    # 2. Öncelik: Kodun içine gömülü orijinal (fabrika çıkışı) açıklama
                    $txtTweakDesc.Text = $selTweak.Description
                } else {
                    # Hiçbiri yoksa boş bırak
                    $txtTweakDesc.Text = ""
                }

                # RestartExplorer: 3 değerli mapping
                $rpVal = "$($selTweak.RestartExplorer)"
                if     ($rpVal -eq "Hard" -or $rpVal -eq "True") { $cbRestartMode.SelectedIndex = 2 }
                elseif ($rpVal -eq "Soft")                       { $cbRestartMode.SelectedIndex = 1 }
                else                                             { $cbRestartMode.SelectedIndex = 0 }

                # Risk seviyesi: Low/Medium/High → 0/1/2
                $rsVal = "$($selTweak.Risk)"
                if     ($rsVal -eq "High")   { $cbRiskLevel.SelectedIndex = 2 }
                elseif ($rsVal -eq "Medium") { $cbRiskLevel.SelectedIndex = 1 }
                else                         { $cbRiskLevel.SelectedIndex = 0 }

                if ($selTweak.Command -match "Set-DnsClientServerAddress" -and -not $selTweak.Batch) {
                    $rbDns.IsChecked = $true
                    if ($selTweak.Command -match "-ServerAddresses \((.*?)\)") {
                        $ips = $Matches[1] -split "," | ForEach-Object { $_.Trim().Trim("'").Trim('"') }
                        $txtDns1.Text = $ips[0]; $txtDns2.Text = $ips[1]
                        if ($ips.Count -gt 2) { 
                            $chkDnsIPv6.IsChecked = $true; $grdIPv6.IsEnabled = $true; $grdIPv6.Opacity = 1
                            $txtDns6_1.Text = $ips[2]; $txtDns6_2.Text = $ips[3] 
                        } else {
                            $chkDnsIPv6.IsChecked = $false; $grdIPv6.IsEnabled = $false; $grdIPv6.Opacity = 0.5
                            $txtDns6_1.Text = ""; $txtDns6_2.Text = ""
                        }
                    }
                } elseif ($selTweak.Batch) { 
                    $rbBatch.IsChecked = $true; $txtBatchInput.Text = $selTweak.Batch | ConvertTo-Json -Depth 5 
                } elseif ($selTweak.Key) { 
                    $rbReg.IsChecked = $true
                    $txtKey.Text = $selTweak.Key; $txtValueName.Text = $selTweak.ValueName
                    $cbType.Text = $selTweak.Type; $txtData.Text = $selTweak.Data; $txtUndo.Text = $selTweak.Undo
                } else {
                    $rbCmd.IsChecked = $true
                    $txtCommand.Text = $selTweak.Command; $txtUndoCommand.Text = $selTweak.UndoCommand
                }

                # Selection değişimi sonrası önizlemeyi güncelle
                Update-TweakPreview
            }
        })

        # ÖNİZLEME üreten yardımcı (form alanlarından okur)
        # Tek registry value icin "su an sistemde ne var?" oku
        function Get-CurrentRegistryValue($key, $valueName) {
            if ([string]::IsNullOrWhiteSpace($key)) { return @{ Status="EMPTY"; Value=$null } }
            if (-not (Test-Path $key)) { return @{ Status="NOKEY"; Value=$null } }
            try {
                if ([string]::IsNullOrEmpty($valueName)) {
                    $prop = Get-ItemProperty -Path $key -ErrorAction Stop
                    $val = $prop.'(default)'
                } else {
                    $prop = Get-ItemProperty -Path $key -Name $valueName -ErrorAction Stop
                    $val = $prop.$valueName
                }
                if ($null -eq $val) { return @{ Status="NOVALUE"; Value=$null } }
                # Binary array ise hex string'e cevir (ilk 16 byte)
                if ($val -is [byte[]]) {
                    $hex = ($val | Select-Object -First 16 | ForEach-Object { "{0:X2}" -f $_ }) -join " "
                    if ($val.Length -gt 16) { $hex += " ..." }
                    return @{ Status="OK"; Value=$hex }
                }
                return @{ Status="OK"; Value=$val }
            } catch {
                return @{ Status="NOVALUE"; Value=$null }
            }
        }

        # "su an" / "apply" / "undo" durumunu yorumla → Aktif / Pasif / Farkli
        function Get-RegistryDiffStatus($current, $applyVal, $undoVal) {
            if ($null -eq $current) { return "⚪ UYGULANMAMIS (deger yok)" }
            $curStr = "$current"
            if ($curStr -eq "$applyVal") { return "✅ AKTIF (Apply degeriyle uyusuyor)" }
            if ($curStr -eq "$undoVal")  { return "⚪ UYGULANMAMIS (Undo degeriyle uyusuyor)" }
            return "❓ FARKLI ($curStr — Apply'a da Undo'ya da uymuyor)"
        }

        function Update-TweakPreview {
            $sb = New-Object System.Text.StringBuilder
            [void]$sb.AppendLine("Ad: $($txtName.Text)")
            $rpIdx = $cbRestartMode.SelectedIndex
            $rpStr = @("Yok","Soft (refresh)","Hard (restart)")[$rpIdx]
            $rsIdx = $cbRiskLevel.SelectedIndex
            $rsStr = @("Düşük","Orta","Yüksek")[$rsIdx]
            [void]$sb.AppendLine("Restart: $rpStr  •  Risk: $rsStr")
            [void]$sb.AppendLine("─────────────────────────")

            if ($rbReg.IsChecked) {
                [void]$sb.AppendLine("[Registry]")
                [void]$sb.AppendLine("Key:   $($txtKey.Text)")
                [void]$sb.AppendLine("Value: $($txtValueName.Text)  ($($cbType.Text))")
                [void]$sb.AppendLine("")

                $cur = Get-CurrentRegistryValue $txtKey.Text $txtValueName.Text
                switch ($cur.Status) {
                    "EMPTY"   { [void]$sb.AppendLine("📌 SU AN sistemde: (Key alani bos)") }
                    "NOKEY"   { [void]$sb.AppendLine("📌 SU AN sistemde: KEY YOK (yeni olusturulacak)") }
                    "NOVALUE" { [void]$sb.AppendLine("📌 SU AN sistemde: VALUE YOK (yeni olusturulacak)") }
                    "OK"      { [void]$sb.AppendLine("📌 SU AN sistemde: $($cur.Value)") }
                }
                [void]$sb.AppendLine("✅ Apply edilirse: $($txtData.Text)")
                [void]$sb.AppendLine("↶  Undo edilirse:  $($txtUndo.Text)")

                if ($cur.Status -eq "OK") {
                    [void]$sb.AppendLine("")
                    [void]$sb.AppendLine("DURUM: $(Get-RegistryDiffStatus $cur.Value $txtData.Text $txtUndo.Text)")
                }
            } elseif ($rbCmd.IsChecked) {
                [void]$sb.AppendLine("[Komut]")
                [void]$sb.AppendLine("Apply  → $($txtCommand.Text)")
                [void]$sb.AppendLine("")
                [void]$sb.AppendLine("Undo   → $($txtUndoCommand.Text)")
                [void]$sb.AppendLine("")
                [void]$sb.AppendLine("(Komut tipi tweak'lerde mevcut sistem degeri otomatik tespit edilemez)")
            } elseif ($rbBatch.IsChecked) {
                [void]$sb.AppendLine("[Batch] (toplu islem)")
                try {
                    $batch = $txtBatchInput.Text | ConvertFrom-Json -ErrorAction Stop
                    $arr = @($batch)
                    [void]$sb.AppendLine("Toplam alt-islem: $($arr.Count)")
                    [void]$sb.AppendLine("")
                    $idx = 0
                    foreach ($b in $arr | Select-Object -First 5) {
                        $idx++
                        if ($b.Key) {
                            $cur = Get-CurrentRegistryValue $b.Key $b.ValueName
                            $curTxt = switch ($cur.Status) {
                                "NOKEY"   { "(key yok)" }
                                "NOVALUE" { "(value yok)" }
                                "OK"      { "$($cur.Value)" }
                                default   { "?" }
                            }
                            [void]$sb.AppendLine("  $idx) $($b.ValueName)")
                            [void]$sb.AppendLine("     SU AN: $curTxt   →   APPLY: $($b.Data)   |   UNDO: $($b.Undo)")
                        } elseif ($b.Command) {
                            $cmdShort = if ($b.Command.Length -gt 80) { $b.Command.Substring(0,80) + "..." } else { $b.Command }
                            [void]$sb.AppendLine("  $idx) CMD: $cmdShort")
                        }
                    }
                    if ($arr.Count -gt 5) { [void]$sb.AppendLine("  (+ $($arr.Count - 5) tane daha — Batch JSON'da hepsi var)") }
                } catch {
                    [void]$sb.AppendLine("⚠ Gecersiz JSON: $($_.Exception.Message)")
                }
            } elseif ($rbDns.IsChecked) {
                [void]$sb.AppendLine("[DNS]")
                [void]$sb.AppendLine("Hedef IPv4: $($txtDns1.Text), $($txtDns2.Text)")
                if ($chkDnsIPv6.IsChecked) {
                    [void]$sb.AppendLine("Hedef IPv6: $($txtDns6_1.Text), $($txtDns6_2.Text)")
                }
                [void]$sb.AppendLine("")
                # Mevcut sistem DNS'ini oku
                try {
                    $curList = Get-DnsClientServerAddress -ErrorAction SilentlyContinue |
                        Where-Object { $_.AddressFamily -eq 2 -and $_.ServerAddresses.Count -gt 0 -and $_.InterfaceAlias -notmatch "Loopback|VPN|Virtual|Tunnel" } |
                        Select-Object -First 3
                    if ($curList) {
                        [void]$sb.AppendLine("📌 SU AN aktif DNS sunuculari:")
                        foreach ($d in $curList) {
                            [void]$sb.AppendLine("   • $($d.InterfaceAlias): $($d.ServerAddresses -join ', ')")
                        }
                    } else {
                        [void]$sb.AppendLine("📌 SU AN: DNS bilgisi alinamadi (DHCP olabilir)")
                    }
                } catch {
                    [void]$sb.AppendLine("📌 SU AN: DNS sorgu hatasi")
                }
            }
            $txtPreview.Text = $sb.ToString()
        }

        $btnPreviewRfsh.Add_Click({ Update-TweakPreview })

        # Klonla butonu — seçili tweak'i kopyala, "(Kopya)" ekiyle yeni isim
        $btnClone.Add_Click({
            if ($lst.SelectedIndex -lt 0) {
                [System.Windows.MessageBox]::Show("Önce bir ayar seçin.", "Klonla") | Out-Null
                return
            }
            # Mevcut formu olduğu gibi bırak, sadece adı değiştir ve yeni kayıt yapılacak gibi seçimi sıfırla
            $txtName.Text = "$($txtName.Text) (Kopya)"
            $lst.SelectedIndex = -1
            Update-TweakPreview
            # v1.3.0 (§63): klonlama iki adımlı (form kopyalanır, kayıt KAYDET ile); eskiden hiçbir geri bildirim yoktu
            [System.Windows.MessageBox]::Show("Kopya hazırlandı: '$($txtName.Text)'.`n`nAlanları gerekirse değiştirin ve KAYDET'e basın; kopya listeye o zaman eklenir. Vazgeçmek için listeden başka bir ayar seçin.", "Klonla") | Out-Null
            $txtName.Focus() | Out-Null
            $txtName.SelectAll()
        })

        $btnNew.Add_Click({
            $lst.SelectedIndex = -1; $txtName.Text = ""; $txtKey.Text=""; $txtData.Text=""; $txtCommand.Text=""; $txtBatchInput.Text=""
            $txtSubCat.Text=""; $txtGroup.Text=""; $txtTweakDesc.Text="" # Açıklamayı da temizle
            # v1.3.0 (§65): eskiden ValueName / Undo / Undo komutu / Tip / DNS alanları dolu kalıyordu (kategori ve tür bilerek korunur)
            $txtValueName.Text=""; $txtUndo.Text=""; $txtUndoCommand.Text=""; $cbType.SelectedIndex = 0
            $txtDns1.Text=""; $txtDns2.Text=""; $txtDns6_1.Text=""; $txtDns6_2.Text=""; $chkDnsIPv6.IsChecked = $false
            $cbRestartMode.SelectedIndex = 0; $cbRiskLevel.SelectedIndex = 0
            $txtRawInput.Text = $placeholderText; $txtRawInput.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#6B7280')
            Update-TweakPreview
        })
        
        # KAYDET BUTONU (Sprint 3.2 + 3.4: schema validate + conflict check)
        $btnSave.Add_Click({
            $catName = $cbCategory.Text
            # --- TEMEL VALIDATION ---
            if ([string]::IsNullOrWhiteSpace($txtName.Text)) {
                [System.Windows.MessageBox]::Show("'Ad' alanı zorunludur.", "Eksik Bilgi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                return
            }
            if ([string]::IsNullOrWhiteSpace($catName)) {
                [System.Windows.MessageBox]::Show("'Kategori' alanı zorunludur.", "Eksik Bilgi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                return
            }
            if (-not $cbCategory.Items.Contains($catName)) { $cbCategory.Items.Add($catName) | Out-Null }

            # RestartExplorer mapping (cbRestartMode.SelectedIndex → string)
            $rpStrMap = @($false, "Soft", "Hard")
            $rpVal = $rpStrMap[$cbRestartMode.SelectedIndex]

            # Risk mapping
            $rsStrMap = @("Low", "Medium", "High")
            $rsVal = $rsStrMap[$cbRiskLevel.SelectedIndex]

            $newObj = [ordered]@{ Name = $txtName.Text; RestartExplorer = $rpVal; Risk = $rsVal }
            if ($txtSubCat.Text) { $newObj["SubCategory"] = $txtSubCat.Text }
            if ($txtGroup.Text)  { $newObj["Group"] = $txtGroup.Text }

            # v1.3.0 (11. tur, birlestirme): formda olmayan alanlar (DetectScript, Vendor, ...) Kaydet ile dusmesin
            # (eskiden resmi tweak Kaydet ten sonra tespitini kaybedip "uygulanmadi" gorunuyordu)
            if ($lst.SelectedIndex -ne -1) {
                $keepSrc = $lst.SelectedItem.Tag
                foreach ($keepKey in @("DetectScript", "Description", "Vendor", "Requires", "RequiresReboot", "SkipRebootDialog", "Since", "MinBuild", "MaxBuild")) {
                    $keepVal = Get-TweakField $keepSrc $keepKey
                    if ($null -ne $keepVal -and "$keepVal" -ne "") { $newObj[$keepKey] = $keepVal }
                }
            }

            # --- TÜR-BAZLI ALANLAR ---
            if ($rbDns.IsChecked) {
                # v1.2.5: netsh tabanli DNS set (Set-DnsClientServerAddress yerine — Win11 daha guvenilir).
                # IPv4 ve IPv6 ayri komutlarla, source=static persistent registry kaydi.
                $v4Primary = $txtDns1.Text; $v4Secondary = $txtDns2.Text
                $v6Primary = $null; $v6Secondary = $null
                if ($chkDnsIPv6.IsChecked) { $v6Primary = $txtDns6_1.Text; $v6Secondary = $txtDns6_2.Text }
                if ([string]::IsNullOrWhiteSpace($v4Primary) -or [string]::IsNullOrWhiteSpace($v4Secondary)) {
                    [System.Windows.MessageBox]::Show("DNS için en az 2 IPv4 sunucu adresi gerekir.", "DNS", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                    return
                }

                # Apply komutu insa et — netsh ile tum aktif adapter'lara
                $applyLines = @(
                    'if (Test-MrCleanDnsBlocked "Ozel DNS tweak") { return }'
                    '$adapters = @(Get-MrCleanPhysicalAdapters | Where-Object { "$($_.Status)" -eq "Up" })'
                    'foreach ($a in $adapters) {'
                    '    $name = $a.Name'
                    "    & netsh interface ipv4 set dnsservers name=`"`$name`" source=static address=$v4Primary register=primary validate=no | Out-Null"
                    "    & netsh interface ipv4 add dnsservers name=`"`$name`" address=$v4Secondary index=2 validate=no | Out-Null"
                )
                if ($v6Primary) {
                    $applyLines += "    & netsh interface ipv6 set dnsservers name=`"`$name`" source=static address=$v6Primary register=primary validate=no | Out-Null"
                }
                if ($v6Secondary) {
                    $applyLines += "    & netsh interface ipv6 add dnsservers name=`"`$name`" address=$v6Secondary index=2 validate=no | Out-Null"
                }
                $applyLines += '}'
                $applyLines += 'ipconfig /flushdns > $null'
                $newObj["Command"] = ($applyLines -join "`n")

                $newObj["UndoCommand"] = @'
if (Test-MrCleanDnsBlocked "Ozel DNS tweak geri alma") { return }
$adapters = @(Get-MrCleanPhysicalAdapters | Where-Object { "$($_.Status)" -eq "Up" })
foreach ($a in $adapters) {
    $name = $a.Name
    & netsh interface ipv4 set dnsservers name="$name" source=dhcp | Out-Null
    & netsh interface ipv6 set dnsservers name="$name" source=dhcp | Out-Null
}
ipconfig /flushdns > $null
'@
                $newObj["RestartExplorer"] = $false
            } elseif ($rbReg.IsChecked) {
                # Registry validation
                if ([string]::IsNullOrWhiteSpace($txtKey.Text)) {
                    [System.Windows.MessageBox]::Show("Registry için 'Key' alanı zorunludur.", "Validation", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                    return
                }
                if ($txtKey.Text -notmatch '^(HKCU|HKLM|HKCR|HKU|HKCC):\\') {
                    [System.Windows.MessageBox]::Show("Registry Key 'HKCU:\\...', 'HKLM:\\...' formatında olmalı.", "Validation", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                    return
                }
                if ([string]::IsNullOrWhiteSpace($cbType.Text)) {
                    [System.Windows.MessageBox]::Show("Registry için 'Tip' alanı zorunludur (DWord, String, Binary vb.).", "Validation", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                    return
                }
                $newObj["Key"] = $txtKey.Text; $newObj["ValueName"] = $txtValueName.Text; $newObj["Type"] = $cbType.Text; $newObj["Data"] = $txtData.Text; $newObj["Undo"] = $txtUndo.Text

                # --- CONFLICT DETECTION (Sprint 3.4) ---
                # Aynı Key+ValueName'i farklı bir tweak değiştiriyorsa uyar
                $conflicts = @()
                foreach ($cat in $global:TweakList.Keys) {
                    foreach ($t in $global:TweakList[$cat]) {
                        # Şu anki düzenlenen tweak'i atla
                        if ($lst.SelectedIndex -ge 0 -and $lst.SelectedItem.Tag -eq $t) { continue }
                        if ($t.Name -eq $txtName.Text) { continue }
                        if ($t.Key -eq $txtKey.Text -and "$($t.ValueName)" -eq "$($txtValueName.Text)") {
                            $conflicts += "$cat → $($t.Name) (Data=$($t.Data))"
                        }
                        # Batch içindeki sub-tweak'leri de kontrol et
                        if ($t.Batch) {
                            foreach ($sub in $t.Batch) {
                                if ($sub.Key -eq $txtKey.Text -and "$($sub.ValueName)" -eq "$($txtValueName.Text)") {
                                    $conflicts += "$cat → $($t.Name) [Batch] (Data=$($sub.Data))"
                                }
                            }
                        }
                    }
                }
                if ($conflicts.Count -gt 0) {
                    $msg = "Bu Key+ValueName başka ayar(lar)la çakışıyor:`n`n" + ($conflicts -join "`n") + "`n`nYine de kaydedilsin mi?"
                    if ([System.Windows.MessageBox]::Show($msg, "Çakışma Algılandı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning) -ne 'Yes') {
                        return
                    }
                }
            } elseif ($rbCmd.IsChecked) {
                if ([string]::IsNullOrWhiteSpace($txtCommand.Text)) {
                    [System.Windows.MessageBox]::Show("Komut tipinde 'Command' alanı zorunludur.", "Validation", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                    return
                }
                $newObj["Command"] = $txtCommand.Text; $newObj["UndoCommand"] = $txtUndoCommand.Text
            } elseif ($rbBatch.IsChecked) {
                try {
                    if ([string]::IsNullOrWhiteSpace($txtBatchInput.Text)) { throw "Batch JSON kutusu boş." }
                    $rawJson = $txtBatchInput.Text | ConvertFrom-Json -ErrorAction Stop
                    $newObj["Batch"] = if ($rawJson.value) { $rawJson.value } else { @($rawJson) }
                } catch {
                    [System.Windows.MessageBox]::Show("Batch JSON geçersiz: $($_.Exception.Message)", "Validation", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                    return
                }
            }

            if (-not $global:TweakList.Contains($catName)) { $global:TweakList[$catName] = @() }
            
            # --- YENİ EKLENEN: AÇIKLAMAYI (TOOLTIP) KAYDET ---
            $newDesc = $txtTweakDesc.Text.Trim()
            if ($lst.SelectedIndex -ne -1) {
                $oldTweak = $lst.SelectedItem.Tag
                
                # Eğer isim değiştirildiyse, eski açıklamayı sil
                if ($oldTweak.Name -ne $txtName.Text) {
                    $global:ItemDescriptions.Remove($oldTweak.Name)
                }

                $oldCat = $global:TweakList.Keys | Where-Object { $global:TweakList[$_] -contains $oldTweak }
                $arr = [System.Collections.ArrayList]$global:TweakList[$oldCat]
                $arr.Remove($oldTweak)
                $global:TweakList[$oldCat] = $arr.ToArray()
            }

            # Açıklama boş değilse ekle, boşsa sil
            if ([string]::IsNullOrWhiteSpace($newDesc)) { $global:ItemDescriptions.Remove($txtName.Text) } 
            else { $global:ItemDescriptions[$txtName.Text] = $newDesc }

            $global:TweakList[$catName] += $newObj
            Mark-ConfigDirty; Refresh-List; Load-Tweak-Tree
            try { Check-Tweak-Status -ForceRefresh } catch {}
            [System.Windows.MessageBox]::Show((T 'mbx_saved')) | Out-Null
        })
        
        # SİL BUTONU
        $btnDel.Add_Click({
            if ($lst.SelectedIndex -ne -1) {
                $selTweak = $lst.SelectedItem.Tag
                # v1.2.10: Yanlislikla silme onleme — onay MessageBox ekle.
                # Profil Yoneticisi Sil ve sag tik "Listeden Sil" zaten onay soruyor; bu da uyumlu.
                $confirm = [System.Windows.MessageBox]::Show(
                    ("'{0}' tweak'i Ayar Yöneticisi'nden kalıcı olarak silinecek.`n`nBu tweak Tweaks sekmesindeki listeden kaldırılır, geri alınamaz. (Sıfırlamak için 'Yeni' butonu ile yeniden ekleyebilirsin veya config dosyasını sıfırlayıp varsayılana dönebilirsin.)`n`nDevam edilsin mi?" -f $selTweak.Name),
                    "Tweak Sil — Onay",
                    [System.Windows.MessageBoxButton]::YesNo,
                    [System.Windows.MessageBoxImage]::Warning)
                if ($confirm -ne 'Yes') { return }

                $cat = $global:TweakList.Keys | Where-Object { $global:TweakList[$_] -contains $selTweak }
                $arr = [System.Collections.ArrayList]$global:TweakList[$cat]
                $arr.Remove($selTweak)
                $global:TweakList[$cat] = $arr.ToArray()

                # Silerken açıklamayı da JSON'dan temizle
                $global:ItemDescriptions.Remove($selTweak.Name)

                Mark-ConfigDirty; Refresh-List; Load-Tweak-Tree
                try { Check-Tweak-Status -ForceRefresh } catch {}
                # v1.3.0 (§64): form da boşaltılır (Yeni ile aynı). Eskiden silinen ayar formda kalıyordu ve KAYDET onu yeni ayar diye geri ekliyordu.
                $btnNew.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent)))
            }
        })

        if ($TargetTweak) { foreach ($item in $lst.Items) { if ($item.Tag.Name -eq $TargetTweak.Name) { $lst.SelectedItem = $item; $lst.ScrollIntoView($item); break } } }
        $winTM.ShowDialog() | Out-Null
    } catch { WpfLog "TweakMgr Hata: $_" }
}

# =========================================================
# TWEAK AUDIT LOG (Bonus E1)
# Her Apply / Undo islemini timestamp + tweak listesiyle dosyaya yazar.
# Dosya: %APPDATA%\MrClean\tweak_history.log
# =========================================================
function Write-TweakAuditLog {
    param(
        [string]$Operation,  # "Apply", "QuickUndo", vb.
        $Applied = @(),
        $Undone  = @()
    )
    if (-not $AppDataPath) { return }
    $logPath = Join-Path $LogsDir "tweak_history.log"
    try {
        $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.AppendLine("=== [$ts] $Operation ===")
        if ($Applied.Count -gt 0) {
            [void]$sb.AppendLine("UYGULANAN ($($Applied.Count) adet):")
            foreach ($t in $Applied) { [void]$sb.AppendLine("  + $($t.Name)") }
        }
        if ($Undone.Count -gt 0) {
            [void]$sb.AppendLine("GERI ALINAN ($($Undone.Count) adet):")
            foreach ($t in $Undone) { [void]$sb.AppendLine("  - $($t.Name)") }
        }
        [void]$sb.AppendLine("")
        Add-Content -Path $logPath -Value $sb.ToString() -Encoding UTF8 -ErrorAction SilentlyContinue

        # Dosya 5 MB'dan buyukse ilk yarisini kes
        if ((Test-Path $logPath) -and (Get-Item $logPath).Length -gt 5MB) {
            $lines = Get-Content $logPath
            $half = [int]($lines.Count / 2)
            Set-Content $logPath -Value ($lines | Select-Object -Skip $half) -Encoding UTF8
        }
    } catch {}
}

# =========================================================
# BENCHMARK SUITE (v1.2.10) — Tweak oncesi/sonrasi performans karsilastirmasi
# 7 metrik: timer, loopback, gateway, dns, processStart, ram, dpc, sysCounts. (disk4k kaldirildi)
# Her metrik kendi fonksiyonunda (test edilebilir/yeniden kullanilabilir). Top-level
# Get-BenchSnapshot tum suite'i siralı calistirir, hashtable doner. JSON CRUD ayri.
# =========================================================

# ---- METRIK 1: Timer / Sleep precision ----
# TimerRes::MeasureOnce N kez calistirir, Sleep(1)-1ms delta = "fazladan kac ms uyudu" olcumu.
# Lower = better. Detayli aciklama Show-TimerResolutionTest fonksiyonunda.
function Test-TimerPrecision {
    param([int]$Samples = 50)
    try {
        # REALTIME priority ile warmup + N sample
        [TimerRes]::SetRealtimePriority() | Out-Null
        $null = [TimerRes]::MeasureOnce()   # warmup atilir
        $deltas = New-Object System.Collections.Generic.List[double]
        for ($i = 0; $i -lt $Samples; $i++) {
            $d = [TimerRes]::MeasureOnce()
            [void]$deltas.Add($d)
        }
        [TimerRes]::SetNormalPriority() | Out-Null
        $avg = ($deltas | Measure-Object -Average).Average
        $sumSq = 0.0; foreach ($v in $deltas) { $sumSq += ($v - $avg) * ($v - $avg) }
        $stddev = if ($deltas.Count -gt 1) { [Math]::Sqrt($sumSq / ($deltas.Count - 1)) } else { 0.0 }
        return @{ Ok = $true; AvgMs = [Math]::Round($avg, 4); StddevMs = [Math]::Round($stddev, 4); Samples = $deltas.Count }
    } catch {
        try { [TimerRes]::SetNormalPriority() | Out-Null } catch {}
        return @{ Ok = $false; Error = $_.Exception.Message; AvgMs = -1; StddevMs = -1 }
    }
}

# ---- METRIK 2: Loopback ping (127.0.0.1) ----
# Pure TCP stack latency, NIC disinda. NIC-ozel tweak ile degismez ama TCP stack tweak ile degisir.
function Test-LoopbackPing {
    param([int]$Samples = 50)
    try {
        $ping = New-Object System.Net.NetworkInformation.Ping
        $times = New-Object System.Collections.Generic.List[double]
        # Warmup
        try { $ping.Send("127.0.0.1", 500) | Out-Null } catch {}
        for ($i = 0; $i -lt $Samples; $i++) {
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            try {
                $r = $ping.Send("127.0.0.1", 500)
                $sw.Stop()
                if ($r.Status -eq 'Success') {
                    # Stopwatch sub-ms hassasiyetli, Ping.RoundtripTime integer ms
                    [void]$times.Add($sw.Elapsed.TotalMilliseconds)
                }
            } catch { $sw.Stop() }
        }
        if ($times.Count -eq 0) { return @{ Ok = $false; AvgMs = -1; Error = "Hicbir ping basarili degil" } }
        $avg = ($times | Measure-Object -Average).Average
        $min = ($times | Measure-Object -Minimum).Minimum
        $max = ($times | Measure-Object -Maximum).Maximum
        $sumSq = 0.0; foreach ($v in $times) { $sumSq += ($v - $avg) * ($v - $avg) }
        $jit = if ($times.Count -gt 1) { [Math]::Sqrt($sumSq / ($times.Count - 1)) } else { 0.0 }
        return @{
            Ok = $true; AvgMs = [Math]::Round($avg, 3); MinMs = [Math]::Round($min, 3); MaxMs = [Math]::Round($max, 3); JitterMs = [Math]::Round($jit, 3); Samples = $times.Count
        }
    } catch { return @{ Ok = $false; Error = $_.Exception.Message; AvgMs = -1 } }
}

# ---- METRIK 3: Gateway ping ----
# Routera ping — yerel ag latency + jitter. NIC offload, MMCSS NetworkThrottling, packet processing
# path tweak'lerinden DOGRUDAN etkilenir.
function Test-GatewayPing {
    param([int]$Samples = 50)
    try {
        $gw = $null
        try {
            $gw = (Get-NetIPConfiguration -ErrorAction Stop | Where-Object { $_.IPv4DefaultGateway } | Select-Object -First 1).IPv4DefaultGateway.NextHop
        } catch {}
        if (-not $gw) { return @{ Ok = $false; Error = "Default gateway bulunamadi"; AvgMs = -1 } }
        $ping = New-Object System.Net.NetworkInformation.Ping
        $times = New-Object System.Collections.Generic.List[double]
        try { $ping.Send($gw, 1000) | Out-Null } catch {}
        for ($i = 0; $i -lt $Samples; $i++) {
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            try {
                $r = $ping.Send($gw, 1000)
                $sw.Stop()
                if ($r.Status -eq 'Success') { [void]$times.Add($sw.Elapsed.TotalMilliseconds) }
            } catch { $sw.Stop() }
            Start-Sleep -Milliseconds 20  # ag fairness, burst yapmasin
        }
        if ($times.Count -eq 0) { return @{ Ok = $false; AvgMs = -1; Error = "Gateway pinge cevap vermedi"; Gateway = $gw } }
        $avg = ($times | Measure-Object -Average).Average
        $min = ($times | Measure-Object -Minimum).Minimum
        $max = ($times | Measure-Object -Maximum).Maximum
        $sumSq = 0.0; foreach ($v in $times) { $sumSq += ($v - $avg) * ($v - $avg) }
        $jit = if ($times.Count -gt 1) { [Math]::Sqrt($sumSq / ($times.Count - 1)) } else { 0.0 }
        return @{
            Ok = $true; Gateway = $gw; AvgMs = [Math]::Round($avg, 3); MinMs = [Math]::Round($min, 3); MaxMs = [Math]::Round($max, 3); JitterMs = [Math]::Round($jit, 3); Samples = $times.Count
        }
    } catch { return @{ Ok = $false; Error = $_.Exception.Message; AvgMs = -1 } }
}

# ---- METRIK 4: DNS resolve latency ----
# 10 farkli domain icin Resolve-DnsName cagrisi, ortalama ms. DNS server degisikligi
# (Cloudflare vs Google vs ISP) ve cache tweak'leri buradan ölcülür.
function Test-DnsResolve {
    param([int]$DomainsPerRun = 10)
    try {
        $domains = @("google.com","cloudflare.com","github.com","stackoverflow.com","wikipedia.org","microsoft.com","amazon.com","reddit.com","youtube.com","apple.com")
        $domains = $domains | Get-Random -Count ([Math]::Min($DomainsPerRun, $domains.Count))
        $times = New-Object System.Collections.Generic.List[double]
        # Cache temizle (admin gerek; basarisizsa zaten cache var)
        try { Clear-DnsClientCache -ErrorAction SilentlyContinue } catch {}
        foreach ($d in $domains) {
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            try {
                $null = Resolve-DnsName -Name $d -Type A -DnsOnly -NoHostsFile -QuickTimeout -ErrorAction Stop
                $sw.Stop()
                [void]$times.Add($sw.Elapsed.TotalMilliseconds)
            } catch { $sw.Stop() }
        }
        if ($times.Count -eq 0) { return @{ Ok = $false; AvgMs = -1; Error = "DNS resolve hicbiri basarili degil" } }
        $avg = ($times | Measure-Object -Average).Average
        return @{ Ok = $true; AvgMs = [Math]::Round($avg, 2); Samples = $times.Count; DomainCount = $domains.Count }
    } catch { return @{ Ok = $false; Error = $_.Exception.Message; AvgMs = -1 } }
}

# ---- METRIK 5: Disk 4K random read ----
# 16MB test dosyasi olusur, N kez rastgele offset 4KB okur, IOPS + avg op time olcer.
# Disable Indexing, defrag, Superfetch tweak'leri buradan ölcülür.
function Test-Disk4kRead {
    param([int]$Iterations = 5000, [int]$FileSizeMB = 16)
    $testFile = Join-Path $env:TEMP ("mrclean_bench_disk_{0}.bin" -f ([Guid]::NewGuid().ToString("N")))
    try {
        # 1) Test dosyasi olustur (random data — compress edilebilir degil)
        $rng = New-Object System.Random
        $bytes = New-Object byte[] ($FileSizeMB * 1024 * 1024)
        $rng.NextBytes($bytes)
        [System.IO.File]::WriteAllBytes($testFile, $bytes)

        # 2) Disk cache temizleme imkansız (admin/IFS gerek), o yuzden iki kez okuyup ilkini at
        $buf = New-Object byte[] 4096
        $fileLen = (Get-Item $testFile).Length
        $maxOffset = $fileLen - 4096
        $fs = [System.IO.File]::Open($testFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
        try {
            # Warmup — ilk 20 okuma at
            for ($w = 0; $w -lt 20; $w++) {
                $off = $rng.Next(0, [int]$maxOffset) -band -4096
                $fs.Position = $off
                $null = $fs.Read($buf, 0, 4096)
            }
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            for ($i = 0; $i -lt $Iterations; $i++) {
                $off = $rng.Next(0, [int]$maxOffset) -band -4096
                $fs.Position = $off
                $null = $fs.Read($buf, 0, 4096)
            }
            $sw.Stop()
        } finally { $fs.Close() }

        $elapsedSec = $sw.Elapsed.TotalSeconds
        if ($elapsedSec -le 0) { $elapsedSec = 0.001 }
        $iops = [Math]::Round($Iterations / $elapsedSec, 0)
        $avgUs = [Math]::Round(($elapsedSec * 1e6) / $Iterations, 2)
        return @{ Ok = $true; IOPS = $iops; AvgMicroSec = $avgUs; Iterations = $Iterations; FileSizeMB = $FileSizeMB }
    } catch {
        return @{ Ok = $false; Error = $_.Exception.Message; IOPS = -1; AvgMicroSec = -1 }
    } finally {
        try { if (Test-Path $testFile) { Remove-Item $testFile -Force -ErrorAction SilentlyContinue } } catch {}
    }
}

# ---- METRIK 6: Process start latency ----
# cmd.exe /c exit N kez baslat, avg ms. AntiVirus on-access scan, UAC overhead, MsMpEng yuku
# buradan görunur.
function Test-ProcessStartLatency {
    param([int]$Samples = 20)
    try {
        # Warmup
        $p = Start-Process -FilePath "cmd.exe" -ArgumentList "/c","exit" -WindowStyle Hidden -PassThru
        $p.WaitForExit()
        $times = New-Object System.Collections.Generic.List[double]
        for ($i = 0; $i -lt $Samples; $i++) {
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            try {
                $p = Start-Process -FilePath "cmd.exe" -ArgumentList "/c","exit" -WindowStyle Hidden -PassThru -ErrorAction Stop
                $p.WaitForExit(5000) | Out-Null
                $sw.Stop()
                [void]$times.Add($sw.Elapsed.TotalMilliseconds)
            } catch { $sw.Stop() }
        }
        if ($times.Count -eq 0) { return @{ Ok = $false; AvgMs = -1 } }
        $avg = ($times | Measure-Object -Average).Average
        return @{ Ok = $true; AvgMs = [Math]::Round($avg, 1); Samples = $times.Count }
    } catch { return @{ Ok = $false; Error = $_.Exception.Message; AvgMs = -1 } }
}

# ---- METRIK 7: DPC time % (kernel deferred procedure load) ----
# Win32_PerfFormattedData_Counters_ProcessorInformation WMI class — locale-independent
# (Get-Counter "\Processor Information(_Total)\% DPC Time" TR Windowsta counter adi lokalize,
# match etmiyor). Yuksek DPC = NIC/disk driver kotu, audio glitch, oyunda frame stutter.
# NetAdapter offload, MSI Mode, NetAdapter PowerSave tweak'leri buradan ölcülür.
function Test-DpcTime {
    param([int]$DurationSec = 5)
    try {
        $vals  = New-Object System.Collections.Generic.List[double]
        $intrs = New-Object System.Collections.Generic.List[double]
        for ($i = 0; $i -lt $DurationSec; $i++) {
            $row = $null
            try {
                $row = Get-CimInstance -ClassName Win32_PerfFormattedData_Counters_ProcessorInformation -Filter "Name='_Total'" -ErrorAction Stop | Select-Object -First 1
            } catch {
                # Eski fallback (XP-era)
                try { $row = Get-CimInstance -ClassName Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction Stop | Select-Object -First 1 } catch {}
            }
            if ($row) {
                [void]$vals.Add([double]$row.PercentDPCTime)
                [void]$intrs.Add([double]$row.PercentInterruptTime)
            }
            Start-Sleep -Seconds 1
        }
        if ($vals.Count -eq 0) { return @{ Ok = $false; Error = "WMI counter okunamadi"; AvgPercent = -1; PeakPercent = -1 } }
        $avg  = ($vals | Measure-Object -Average).Average
        $peak = ($vals | Measure-Object -Maximum).Maximum
        $intAvg = if ($intrs.Count -gt 0) { ($intrs | Measure-Object -Average).Average } else { 0 }
        return @{ Ok = $true; AvgPercent = [Math]::Round($avg, 3); PeakPercent = [Math]::Round($peak, 3); InterruptAvgPercent = [Math]::Round($intAvg, 3); Samples = $vals.Count }
    } catch {
        return @{ Ok = $false; Error = $_.Exception.Message; AvgPercent = -1; PeakPercent = -1 }
    }
}

# ---- METRIK 8: Sistem snapshot (anlik sayilar) ----
# Memory Compression, Background Apps, Bloatware, Telemetri kapatma tweak'leri buradan ölcülür.
function Get-SystemSnapshot {
    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
        $availMB = if ($os) { [Math]::Round($os.FreePhysicalMemory / 1024, 0) } else { -1 }
        $totalMB = if ($os) { [Math]::Round($os.TotalVisibleMemorySize / 1024, 0) } else { -1 }
        $procCount = (Get-Process -ErrorAction SilentlyContinue).Count
        $svcRunning = (Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Running' }).Count
        # HandleCount: Get-Counter '\Process(_Total)\Handle Count' TR Windowsta lokalize. Get-Process
        # uzerinden topla — locale-independent + admin gerekmez.
        $handleCount = 0
        try { $handleCount = (Get-Process -ErrorAction SilentlyContinue | Measure-Object -Property HandleCount -Sum).Sum } catch {}
        return @{
            Ok = $true
            AvailableRamMB = $availMB
            TotalRamMB     = $totalMB
            ProcessCount   = $procCount
            ServicesRunning = $svcRunning
            HandleCount    = [int]$handleCount
        }
    } catch { return @{ Ok = $false; Error = $_.Exception.Message } }
}

# ---- v1.3.0 (13. tur): OYUN YUKU / SISTEM GECIKMESI / GPU KARE SURESI OLCUMLERI ----
# Gece olcum oturumunda gelistirilip dogrulanan araclar (DEGISIKLIKLER 22). Kaynak kod gomulu; ilk kullanimda Windows un
# kendi C# derleyicisiyle (csc.exe, .NET Framework 4) AppData\MrClean\benchmarks\tools altina BIR KEZ derlenir — disaridan
# hicbir sey indirilmez. GPU testi istege bagli: PresentMon (Intel imzali) + FurMark 2 (Geeks3D) resmi kaynaktan, SHA-256 dogrulamali.
$global:MrCleanBenchSrc = @{
    Lat  = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Runtime.InteropServices;
using System.Threading;

// MrClean gecikme olcum araci. Kullanim: LatBench.exe <saniye_carpani> <etiket>
// Cikti: tek satir "ETIKET | test: ..." satirlari (stdout)
public static class LatBench {
    [DllImport("winmm.dll")] static extern uint timeBeginPeriod(uint p);
    [DllImport("kernel32.dll")] static extern IntPtr VirtualAlloc(IntPtr a, UIntPtr s, uint t, uint p);
    [DllImport("kernel32.dll")] static extern bool VirtualFree(IntPtr a, UIntPtr s, uint t);
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode)] static extern uint GetFileAttributesW(string f);
    [DllImport("kernel32.dll")] static extern IntPtr CreateEventW(IntPtr a, bool m, bool i, IntPtr n);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);

    static double F = Stopwatch.Frequency / 1e6; // tick -> us
    static long Now() { return Stopwatch.GetTimestamp(); }
    static double Us(long a, long b) { return (b - a) / F; }

    static string Stat(List<double> v, string unit) {
        if (v.Count == 0) return "veri yok";
        double[] a = v.ToArray(); Array.Sort(a);
        double s = 0; foreach (double x in a) s += x;
        Func<double, double> p = q => a[Math.Min(a.Length - 1, (int)(a.Length * q))];
        return string.Format("n={0} ort={1:F1}{6} p50={2:F1} p99={3:F1} p99.9={4:F1} max={5:F1}", a.Length, s / a.Length, p(0.5), p(0.99), p(0.999), a[a.Length - 1], unit);
    }

    static volatile bool stop;
    static double sink;
    static System.Text.StringBuilder R = new System.Text.StringBuilder("RESULT");
    static void Put(string k, double v) { R.Append(" " + k + "=" + v.ToString("F2", System.Globalization.CultureInfo.InvariantCulture)); }
    static double Pc(List<double> v, double q) { double[] a = v.ToArray(); Array.Sort(a); return a[Math.Min(a.Length - 1, (int)(a.Length * q))]; }
    static double Avg(List<double> v) { double s = 0; foreach (double x in v) s += x; return v.Count > 0 ? s / v.Count : 0; }

    public static int Main(string[] args) {
        double k = args.Length > 0 ? double.Parse(args[0], System.Globalization.CultureInfo.InvariantCulture) : 1.0;
        string tag = args.Length > 1 ? args[1] : "test";
        timeBeginPeriod(1);
        Thread.CurrentThread.CurrentCulture = System.Globalization.CultureInfo.InvariantCulture;
        Process.GetCurrentProcess().PriorityClass = ProcessPriorityClass.High;   // oyunlar genelde Normal/High; adil karsilastirma icin sabit
        Random rnd = new Random(42);

        // 1) Uyanma gecikmesi: B is parcacigi rastgele araliklarla olay tetikler, A uyanma suresini olcer
        {
            var ev = new AutoResetEvent(false);
            long setAt = 0; var res = new List<double>();
            int n = (int)(3000 * k);
            var waiter = new Thread(() => {
                for (int i = 0; i < n; i++) { ev.WaitOne(); long t = Now(); res.Add(Us(Interlocked.Read(ref setAt), t)); }
            });
            waiter.Priority = ThreadPriority.AboveNormal; waiter.Start();
            for (int i = 0; i < n; i++) {
                // 0.3-3 ms bekle (oyun karesi arasi bosluk benzeri): Sleep + spin karisik
                double gap = 300 + rnd.NextDouble() * 2700; long s0 = Now();
                if (gap > 1500) Thread.Sleep(1);
                while (Us(s0, Now()) < gap) { }
                Interlocked.Exchange(ref setAt, Now()); ev.Set();
                while (res.Count <= i && waiter.IsAlive) { Thread.SpinWait(20); }
            }
            waiter.Join();
            Console.WriteLine(tag + " | uyanma_gecikmesi: " + Stat(res, "us")); Put("WakeAvgUs", Avg(res)); Put("WakeP99Us", Pc(res, 0.99)); Put("WakeP999Us", Pc(res, 0.999));
        }

        // 2) Sleep(1) gercek suresi
        {
            var res = new List<double>(); int n = (int)(2000 * k);
            for (int i = 0; i < n; i++) { long a = Now(); Thread.Sleep(1); res.Add(Us(a, Now())); }
            Console.WriteLine(tag + " | sleep1: " + Stat(res, "us")); Put("Sleep1AvgUs", Avg(res)); Put("Sleep1P99Us", Pc(res, 0.99));
        }

        // 3) Ani yuk tepkisi: bostan sonra sabit hesap paketi suresi (frekans yukselme / cekirdek park gecikmesi)
        {
            // kalibrasyon: sicak cekirdekte ~100 us'lik is
            int iters = 2000; long c0 = Now(); double x = 1; for (int i = 0; i < 2000000; i++) x = Math.Sqrt(x + i); double per = Us(c0, Now()) / 2000000.0; sink += x;
            iters = (int)(100.0 / per);
            var res = new List<double>(); int n = (int)(1500 * k);
            for (int i = 0; i < n; i++) {
                Thread.Sleep(2 + rnd.Next(9));   // 2-10 ms bosta
                long a = Now(); double y = 1; for (int j = 0; j < iters; j++) y = Math.Sqrt(y + j); sink += y;
                res.Add(Us(a, Now()));
            }
            Console.WriteLine(tag + " | ani_yuk_100us: " + Stat(res, "us")); Put("BurstP50Us", Pc(res, 0.5)); Put("BurstP99Us", Pc(res, 0.99));
        }

        // 4) Oyun dongusu: 240 FPS hedef (4167 us), kare basi 1500 us is, kalan sure Sleep+spin ile beklenir
        {
            double target = 4166.7; int frames = (int)(240 * 25 * k);
            int iters = 0; { long c0 = Now(); double x = 1; for (int i = 0; i < 2000000; i++) x = Math.Sqrt(x + i); iters = (int)(1500.0 / (Us(c0, Now()) / 2000000.0)); sink += x; }
            var ft = new List<double>(); int late1 = 0, late2 = 0;
            long next = Now(); long last = next;
            for (int f = 0; f < frames; f++) {
                double y = 1; for (int j = 0; j < iters; j++) y = Math.Sqrt(y + j); sink += y;
                next += (long)(target * F);
                while (true) { double rem = (next - Now()) / F; if (rem <= 0) break; if (rem > 1500) Thread.Sleep(1); }
                long t = Now(); double d = Us(last, t); last = t; ft.Add(d);
                if (d > target + 1000) late1++; if (d > target * 2) late2++;
                if (Now() - next > (long)(target * F)) next = Now();   // kaymayi biriktirme
            }
            Console.WriteLine(tag + " | oyun_dongusu_240fps: " + Stat(ft, "us") + string.Format(" gec>1ms={0} kare_kacti={1}", late1, late2)); Put("Loop240P999Us", Pc(ft, 0.999)); Put("Loop240Late", late1);
        }

        // 5) Cekirdek cagrisi yogun mikro testler (HVCI / VBS etkisi icin temel)
        {
            string f = Environment.GetFolderPath(Environment.SpecialFolder.System) + "\\kernel32.dll";
            int n = (int)(200000 * k); long a = Now(); for (int i = 0; i < n; i++) GetFileAttributesW(f); double t1 = Us(a, Now()) / n;
            n = (int)(100000 * k); a = Now(); for (int i = 0; i < n; i++) { IntPtr h = CreateEventW(IntPtr.Zero, false, false, IntPtr.Zero); CloseHandle(h); } double t2 = Us(a, Now()) / n;
            n = (int)(20000 * k); a = Now();
            for (int i = 0; i < n; i++) { IntPtr p = VirtualAlloc(IntPtr.Zero, (UIntPtr)65536, 0x3000, 0x04); unsafe { byte* b = (byte*)p; for (int o = 0; o < 65536; o += 4096) b[o] = 1; } VirtualFree(p, UIntPtr.Zero, 0x8000); }
            double t3 = Us(a, Now()) / n;
            int np = Math.Max(5, (int)(30 * k)); var pr = new List<double>();
            for (int i = 0; i < np; i++) { long s = Now(); var psi = new ProcessStartInfo("cmd.exe", "/c exit") { CreateNoWindow = true, UseShellExecute = false }; using (var p = Process.Start(psi)) p.WaitForExit(); pr.Add(Us(s, Now()) / 1000.0); }
            Put("FileAttrUs", t1); Put("PageFault64KUs", t3); Put("ProcStartMs", Avg(pr));
            Console.WriteLine(tag + string.Format(" | cekirdek: dosya_ozniteligi={0:F2}us olay_ac_kapa={1:F2}us bellek_64KB_sayfa_hatasi={2:F1}us surec_baslat: {3}", t1, t2, t3, Stat(pr, "ms")));
        }
        Console.WriteLine(R.ToString());
        return 0;
    }
}
'@
    Game = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;

// Oyun yuku benzetimi + yazilim giris gecikmesi olcumu.
// GameSim.exe <profil: cs2|bf6> <saniye> <etiket>
//  cs2: ana is parcacigi agir, 4 isci, kucuk bellek (yuksek FPS, CPU sinirli)
//  bf6: 10 isci, 768 MB rastgele bellek erisimi (RAM / onbellek baskisi), daha dusuk FPS
public static class GameSim {
    [StructLayout(LayoutKind.Sequential)] struct MOUSEINPUT { public int dx, dy; public uint mouseData, dwFlags, time; public IntPtr extra; }
    [StructLayout(LayoutKind.Sequential)] struct INPUT { public uint type; public MOUSEINPUT mi; }
    [DllImport("user32.dll")] static extern uint SendInput(uint n, INPUT[] i, int size);
    [StructLayout(LayoutKind.Sequential)] struct RAWINPUTDEVICE { public ushort usagePage, usage; public uint flags; public IntPtr target; }
    [DllImport("user32.dll")] static extern bool RegisterRawInputDevices(RAWINPUTDEVICE[] d, uint n, uint size);
    [DllImport("winmm.dll")] static extern uint timeBeginPeriod(uint p);
    [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr h);
    [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] static extern void keybd_event(byte k, byte s, uint f, UIntPtr e);
    static volatile int fgOk = 0, fgN = 0;

    static double F = Stopwatch.Frequency / 1e6;
    static long Now() { return Stopwatch.GetTimestamp(); }
    static volatile bool running = true;
    static long lastSend = 0; static volatile int pending = 0;
    static List<double> inLat = new List<double>(100000);
    static double sink; static int failed = 0;

    class SinkForm : Form {
        public static bool NoAct = false;
        protected override bool ShowWithoutActivation { get { return NoAct; } }
        protected override CreateParams CreateParams { get { var cp = base.CreateParams; if (NoAct) cp.ExStyle |= 0x08000000 | 0x80; return cp; } }
        protected override void WndProc(ref Message m) {
            if (m.Msg == 0x00FF) { // WM_INPUT
                long t = Now();
                if (pending == 1) { pending = 0; lock (inLat) inLat.Add((t - Interlocked.Read(ref lastSend)) / F); }
            }
            base.WndProc(ref m);
        }
    }

    static string Stat(List<double> v, string u) {
        if (v.Count == 0) return "veri yok";
        double[] a = v.ToArray(); Array.Sort(a); double s = 0; foreach (double x in a) s += x;
        Func<double, double> p = q => a[Math.Min(a.Length - 1, (int)(a.Length * q))];
        return string.Format(System.Globalization.CultureInfo.InvariantCulture, "ort={0:F1}{5} p50={1:F1} p99={2:F1} p99.9={3:F1} max={4:F1}", s / a.Length, p(0.5), p(0.99), p(0.999), a[a.Length - 1], u);
    }

    [STAThread]
    public static int Main(string[] args) {
        string prof = args.Length > 0 ? args[0] : "cs2";
        int secs = args.Length > 1 ? int.Parse(args[1]) : 30;
        string tag = args.Length > 2 ? args[2] : prof; bool bgMode = args.Length > 3 && args[3] == "bg";
        timeBeginPeriod(1);
        bool bf = prof == "bf6";
        int workers = bf ? 10 : 4;
        double mainUs = bf ? 1800 : 900, jobUs = bf ? 1600 : 500; int memTouches = bf ? 60000 : 4000;
        int memInts = (bf ? 768 : 64) * 1024 * 1024 / 4;

        // Bellek: rastgele zincir (onbellek iskasi yaratir)
        int[] mem = new int[memInts]; var rnd = new Random(7);
        for (int i = 0; i < memInts; i++) mem[i] = rnd.Next(memInts);
        // Kalibrasyon: 1 us = kac sqrt
        long c0 = Now(); double x0 = 1; for (int i = 0; i < 3000000; i++) x0 = Math.Sqrt(x0 + i); double perUs = 3000000.0 / ((Now() - c0) / F); sink += x0;

        // Giris dinleyici pencere (ekran disi)
        SinkForm.NoAct = bgMode; var form = new SinkForm(); form.ShowInTaskbar = false; form.StartPosition = FormStartPosition.Manual; form.Location = bgMode ? new System.Drawing.Point(-30000, -30000) : new System.Drawing.Point(40, 40); form.Size = new System.Drawing.Size(360, 90); form.TopMost = !bgMode; form.Text = "MrClean oyun benzetimi - " + tag;
        form.Load += (s, e) => { var r = new RAWINPUTDEVICE[1]; r[0].usagePage = 1; r[0].usage = 2; r[0].flags = 0x100; r[0].target = form.Handle; RegisterRawInputDevices(r, 1, (uint)Marshal.SizeOf(typeof(RAWINPUTDEVICE))); };

        var frames = new List<double>(500000);
        var start = new Barrier(workers + 1); var end = new Barrier(workers + 1);
        for (int w = 0; w < workers; w++) {
            int seed = w;
            var t = new Thread(() => {
                var rr = new Random(100 + seed); int idx = rr.Next(memInts);
                while (true) {
                    start.SignalAndWait(); if (!running) break;
                    long s0 = Now(); double y = 1; long n = (long)(jobUs * perUs * 0.6);
                    for (long j = 0; j < n; j++) y = Math.Sqrt(y + j);
                    for (int j = 0; j < memTouches; j++) idx = mem[idx];   // bagimli bellek okumasi
                    sink += y + idx;
                    end.SignalAndWait();
                }
            });
            t.IsBackground = true; t.Start();
        }
        var game = new Thread(() => {
            Thread.CurrentThread.Priority = ThreadPriority.AboveNormal;
            var sw = Stopwatch.StartNew(); long last = Now(); int midx = 0;
            while (sw.Elapsed.TotalSeconds < secs) {
                double y = 1; long n = (long)(mainUs * perUs * 0.5); for (long j = 0; j < n; j++) y = Math.Sqrt(y + j);
                for (int j = 0; j < memTouches / 4; j++) midx = mem[midx];
                start.SignalAndWait(); end.SignalAndWait();
                n = (long)(mainUs * perUs * 0.3); for (long j = 0; j < n; j++) y = Math.Sqrt(y + j);   // "render submit"
                sink += y + midx;
                long t = Now(); frames.Add((t - last) / F); last = t;
            }
            running = false; start.SignalAndWait();
        });
        var input = new Thread(() => {
            Thread.Sleep(1500); int dir = 1; var inp = new INPUT[1]; inp[0].type = 0;
            while (running) {
                inp[0].mi.dx = dir; inp[0].mi.dy = 0; inp[0].mi.dwFlags = 0x0001; dir = -dir;
                Interlocked.Exchange(ref lastSend, Now()); pending = 1;
                if (SendInput(1, inp, Marshal.SizeOf(typeof(INPUT))) == 0) { pending = 0; failed++; }
                Thread.Sleep(15);
            }
            form.BeginInvoke((Action)(() => form.Close()));
        });
        form.Shown += (s, e) => { if (!bgMode) { keybd_event(0x12, 0, 0, UIntPtr.Zero); SetForegroundWindow(form.Handle); keybd_event(0x12, 0, 2, UIntPtr.Zero); } game.Start(); input.Start(); };
        var fgTimer = new System.Windows.Forms.Timer(); fgTimer.Interval = 1000; fgTimer.Tick += (s, e) => { fgN++; if (GetForegroundWindow() == form.Handle) fgOk++; }; fgTimer.Start();
        Application.Run(form);
        game.Join();

        if (frames.Count > 20) frames.RemoveRange(0, 20);
        double[] a = frames.ToArray(); Array.Sort(a); double sum = 0; foreach (double v in a) sum += v;
        double med = a[a.Length / 2]; int stut = 0; foreach (double v in frames) if (v > med * 2) stut++;
        Func<double, double> pc = q => a[Math.Min(a.Length - 1, (int)(a.Length * q))];
        Console.WriteLine(string.Format(System.Globalization.CultureInfo.InvariantCulture,
            "{0} | {1}: FPS ort={2:F0} 1%low={3:F0} 0.1%low={4:F0} | kare p99={5:F2}ms max={6:F2}ms takilma(>2x medyan)={7}/{8} | giris_gecikmesi: {9} (SendInput hata={10}) onplan={11}/{12}",
            tag, prof, 1e6 / (sum / a.Length), 1e6 / pc(0.99), 1e6 / pc(0.999), pc(0.99) / 1000, a[a.Length - 1] / 1000, stut, a.Length, Stat(inLat, "us"), failed, fgOk, fgN));
        double inAvg = 0; foreach (double v in inLat) inAvg += v; inAvg = inLat.Count > 0 ? inAvg / inLat.Count : -1;
        double[] il = inLat.ToArray(); Array.Sort(il); double inP99 = il.Length > 0 ? il[Math.Min(il.Length - 1, (int)(il.Length * 0.99))] : -1;
        Console.WriteLine(string.Format(System.Globalization.CultureInfo.InvariantCulture, "RESULT Fps={0:F1} Low1={1:F1} Low01={2:F1} FrameP99Ms={3:F3} Stutters={4} InputAvgUs={5:F1} InputP99Us={6:F1}",
            1e6 / (sum / a.Length), 1e6 / pc(0.99), 1e6 / pc(0.999), pc(0.99) / 1000, stut, inAvg, inP99));
        return 0;
    }
}
'@
}

function Get-MrCleanBenchTool([ValidateSet("Lat","Game")][string]$Name) {
    try {
        $dir = Join-Path $global:BenchDir "tools"
        if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $src = $global:MrCleanBenchSrc[$Name]
        $sha = [Security.Cryptography.SHA256]::Create()
        $h = -join ($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($src)) | Select-Object -First 6 | ForEach-Object { $_.ToString("x2") })
        $exe = Join-Path $dir ("MrClean{0}_{1}.exe" -f $Name, $h)
        if (Test-Path $exe) { return $exe }
        Get-ChildItem $dir -Filter ("MrClean{0}_*.exe" -f $Name) -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
        $csc = Join-Path $env:WINDIR "Microsoft.NET\Framework64\v4.0.30319\csc.exe"
        if (-not (Test-Path $csc)) { WpfLog "[Bench] C# derleyicisi bulunamadi (.NET Framework 4)."; return $null }
        $cs = Join-Path $dir ("MrClean{0}.cs" -f $Name)
        [IO.File]::WriteAllText($cs, $src, (New-Object Text.UTF8Encoding($false)))
        $opt = if ($Name -eq "Lat") { "/unsafe" } else { "/r:System.Windows.Forms.dll /r:System.Drawing.dll" }
        $out = Invoke-HiddenCommand $csc "/nologo /optimize+ /platform:x64 $opt /out:`"$exe`" `"$cs`""
        Remove-Item $cs -Force -ErrorAction SilentlyContinue
        if (-not (Test-Path $exe)) { WpfLog "[Bench] Olcum araci derlenemedi ($Name): $out"; return $null }
        return $exe
    } catch { WpfLog "[Bench] Olcum araci hatasi: $($_.Exception.Message)"; return $null }
}

# Harici olcum surecini calistirir; arayuz donmasin diye beklerken Do-Events. RESULT satirindan anahtar=deger okur.
function Invoke-MrCleanBenchProcess([string]$Exe, [string]$Arguments, [int]$TimeoutSec, [switch]$Hidden) {
    $tmp = Join-Path $env:TEMP ("mrclean_bench_{0}.txt" -f ([guid]::NewGuid().ToString("N").Substring(0, 8)))
    try {
        $sp = @{ FilePath = $Exe; ArgumentList = $Arguments; PassThru = $true; RedirectStandardOutput = $tmp; WindowStyle = "Hidden" }
        $p = Start-Process @sp
        $sw = [Diagnostics.Stopwatch]::StartNew()
        while (-not $p.HasExited) {
            if ($sw.Elapsed.TotalSeconds -gt $TimeoutSec) { try { $p.Kill() } catch {}; return @{ Ok = $false; Error = "zaman asimi" } }
            Do-Events; Start-Sleep -Milliseconds 100
        }
        $line = Get-Content $tmp -ErrorAction SilentlyContinue | Where-Object { $_ -like "RESULT *" } | Select-Object -Last 1
        if (-not $line) { return @{ Ok = $false; Error = "sonuc satiri yok" } }
        $r = @{ Ok = $true }
        foreach ($kv in ($line -split '\s+' | Select-Object -Skip 1)) {
            $p2 = $kv -split '=', 2
            $d = 0.0; if ($p2.Count -eq 2 -and [double]::TryParse($p2[1], [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$d)) { $r[$p2[0]] = [Math]::Round($d, 3) }
        }
        return $r
    } catch { return @{ Ok = $false; Error = $_.Exception.Message } }
    finally { Remove-Item $tmp -Force -ErrorAction SilentlyContinue }
}

# ---- METRIK: Sistem gecikmesi (uyanma, ani yuk tepkisi, Sleep, cekirdek cagrisi) ~25 sn ----
function Test-SystemLatency {
    $exe = Get-MrCleanBenchTool "Lat"; if (-not $exe) { return @{ Ok = $false; Error = "arac yok" } }
    return (Invoke-MrCleanBenchProcess $exe "0.5 bench" 120)
}

# ---- METRIK: Oyun yuku benzetimi (CS2 benzeri + BF6 benzeri) + yazilim giris gecikmesi ~45 sn ----
function Test-GameLoad {
    $exe = Get-MrCleanBenchTool "Game"; if (-not $exe) { return @{ Ok = $false; Error = "arac yok" } }
    $a = Invoke-MrCleanBenchProcess $exe "cs2 20 bench" 90
    $b = Invoke-MrCleanBenchProcess $exe "bf6 20 bench" 120
    if (-not $a.Ok -or -not $b.Ok) { return @{ Ok = $false; Error = "oyun yuku: $($a.Error) $($b.Error)" } }
    return @{ Ok = $true
        Cs2Fps = $a.Fps; Cs2Low1 = $a.Low1; Cs2Low01 = $a.Low01
        Bf6Fps = $b.Fps; Bf6Low1 = $b.Low1; Bf6Low01 = $b.Low01
        Stutters = ($a.Stutters + $b.Stutters)
        InputAvgUs = [Math]::Round(($a.InputAvgUs + $b.InputAvgUs) / 2, 1); InputP99Us = [Math]::Round(($a.InputP99Us + $b.InputP99Us) / 2, 1) }
}

# ---- METRIK (istege bagli): GPU kare suresi — FurMark 2 (Vulkan, tam ekran) + PresentMon ~45 sn ----
$global:MrCleanBenchGpuTools = @{
    PmUrl = "https://github.com/GameTechDev/PresentMon/releases/download/v2.6.0/PresentMon-2.6.0-x64.exe"
    PmSha = "B2A706BC6AD475749E3B7E3409263AA1E6906D45BDCF993F6DBC0F660188F1AF"
    FmUrl = "https://gpumagick.com/downloads/files/2025/fm2/2_10_dbc69dd0a08da5ff09169a4fc759ddaa/FurMark_2.10.2_win64.zip"
    FmSha = "27AB2E723E2E65DF720BCAFEA681D2104744EDA4A1E0A0374D7E61EAA820E63B"
}
function Get-MrCleanBenchGpuTools([switch]$Download) {
    $dir = Join-Path $global:BenchDir "tools"; $c = $global:MrCleanBenchGpuTools
    $pm = Join-Path $dir "PresentMon.exe"; $fm = Join-Path $dir "fm2\FurMark_win64\furmark.exe"
    if ((Test-Path $pm) -and (Test-Path $fm)) { return @{ Pm = $pm; Fm = $fm } }
    if (-not $Download) { return $null }
    try {
        if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        if (-not (Test-Path $pm)) {
            $t = "$pm.tmp"; (New-Object Net.WebClient).DownloadFile($c.PmUrl, $t)
            $sig = Get-AuthenticodeSignature $t
            if ((Get-FileHash $t -Algorithm SHA256).Hash -ne $c.PmSha -or $sig.Status -ne "Valid" -or "$($sig.SignerCertificate.Subject)" -notmatch "Intel Corporation") { Remove-Item $t -Force; WpfLog "[Bench] PresentMon dogrulamasi BASARISIZ — silindi."; return $null }
            Move-Item $t $pm -Force
        }
        if (-not (Test-Path $fm)) {
            $z = Join-Path $dir "fm2.zip"; (New-Object Net.WebClient).DownloadFile($c.FmUrl, $z)
            if ((Get-FileHash $z -Algorithm SHA256).Hash -ne $c.FmSha) { Remove-Item $z -Force; WpfLog "[Bench] FurMark SHA-256 dogrulamasi BASARISIZ — silindi."; return $null }
            Expand-Archive -Path $z -DestinationPath (Join-Path $dir "fm2") -Force; Remove-Item $z -Force
        }
        if ((Test-Path $pm) -and (Test-Path $fm)) { WpfLog "[Bench] GPU test araclari indirildi ve dogrulandi."; return @{ Pm = $pm; Fm = $fm } }
    } catch { WpfLog "[Bench] GPU araclari indirilemedi: $($_.Exception.Message)" }
    return $null
}

function Test-GpuFrameTime {
    $tools = Get-MrCleanBenchGpuTools; if (-not $tools) { return @{ Ok = $false; Error = "GPU araclari yok" } }
    $csv = Join-Path $env:TEMP "mrclean_pm.csv"; Remove-Item $csv -Force -ErrorAction SilentlyContinue
    Get-Process furmark, PresentMon -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    $scr = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
    $fmDir = Split-Path $tools.Fm
    try {
        $fm = Start-Process $tools.Fm -ArgumentList "--demo furmark-vk --fullscreen --width $($scr.Width) --height $($scr.Height) --vsync 0 --max-time 42 --no-score-box --disable-demo-options --no-osi" -WorkingDirectory $fmDir -PassThru
        $sw = [Diagnostics.Stopwatch]::StartNew(); while ($sw.Elapsed.TotalSeconds -lt 8) { Do-Events; Start-Sleep -Milliseconds 100 }
        $pm = Start-Process $tools.Pm -ArgumentList "--process_name furmark.exe --output_file `"$csv`" --timed 28 --terminate_after_timed --stop_existing_session --no_console_stats" -PassThru -WindowStyle Hidden
        $sw.Restart(); while (-not $pm.HasExited -and $sw.Elapsed.TotalSeconds -lt 60) { Do-Events; Start-Sleep -Milliseconds 100 }
        if (-not $pm.HasExited) { try { $pm.Kill() } catch {} }
        $sw.Restart(); while (-not $fm.HasExited -and $sw.Elapsed.TotalSeconds -lt 20) { Do-Events; Start-Sleep -Milliseconds 100 }
        if (-not $fm.HasExited) { try { $fm.Kill() } catch {} }
        if (-not (Test-Path $csv)) { return @{ Ok = $false; Error = "PresentMon verisi yok" } }
        $inv = [Globalization.CultureInfo]::InvariantCulture
        $r = @(Import-Csv $csv | Where-Object { $_.Application -eq "furmark.exe" })
        if ($r.Count -lt 50) { return @{ Ok = $false; Error = "az kare ($($r.Count))" } }
        $ft = @($r | ForEach-Object { [double]::Parse($_.MsBetweenPresents, $inv) } | Sort-Object)
        $disp = @($r | Where-Object { $_.MsUntilDisplayed -ne "NA" } | ForEach-Object { [double]::Parse($_.MsUntilDisplayed, $inv) })
        $avg = ($ft | Measure-Object -Average).Average
        return @{ Ok = $true
            GpuFps = [Math]::Round(1000 / $avg, 1)
            GpuLow1 = [Math]::Round(1000 / $ft[[int][Math]::Floor($ft.Count * 0.99)], 1)
            GpuLow01 = [Math]::Round(1000 / $ft[[Math]::Min($ft.Count - 1, [int][Math]::Floor($ft.Count * 0.999))], 1)
            DisplayLatencyMs = [Math]::Round(($disp | Measure-Object -Average).Average, 2)
            PresentMode = "$(($r | Group-Object PresentMode | Sort-Object Count -Descending | Select-Object -First 1).Name)" }
    } catch { return @{ Ok = $false; Error = $_.Exception.Message } }
    finally { Get-Process furmark, PresentMon -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue; Remove-Item $csv -Force -ErrorAction SilentlyContinue }
}

# =========================================================
# v1.3.0 (14. tur): AMD YONGA SETI KURULUM ONARIMI
# Sik gorulen sorun: AMD Chipset Software guncellenemiyor / kaldirilamiyor ("Eksik dosyalar nedeniyle devam edemiyor",
# "Bu eylem yalnizca su anda yuklu olan urunler icin gecerlidir" = MSI 1605, kurulum 1603). Sebep: ana paket
# "AMD_Chipset_Drivers" un Windows Installer kaydi bozuk (yetim kaldirma kaydi ya da Windows\Installer onbellek dosyasi
# silinmis); yeni yukleyici eskiyi kaldirmaya calisip duser, AMD nin kendi kaldiricisi de ayni yerde takilir.
# Cozum: bozuk kayitlar yedeklenip temizlenir. SURUCULERE DOKUNULMAZ (DriverStore + aygitlar calismaya devam eder);
# ardindan yeni AMD Chipset Software yukleyicisi temiz kurulum yapar. Microsoft "Program Install and Uninstall"
# sorun gidericisiyle ayni yaklasim, sadece AMD yonga seti kayitlariyla sinirli.
# =========================================================
function ConvertTo-MsiPackedGuid([string]$Guid) {
    $g = $Guid.Trim('{', '}').Replace('-', '').ToUpperInvariant()
    if ($g.Length -ne 32) { return $null }
    $r = { param($x) -join ($x.ToCharArray()[($x.Length - 1)..0]) }
    $out = (& $r $g.Substring(0, 8)) + (& $r $g.Substring(8, 4)) + (& $r $g.Substring(12, 4))
    for ($i = 16; $i -lt 32; $i += 2) { $out += $g.Substring($i + 1, 1) + $g.Substring($i, 1) }
    return $out
}

function Get-AmdChipsetInstallState {
    $rx = '^(AMD[ _]Chipset|AMD PPM Provisioning|AMD 3D V-Cache|AMD Interface Driver|AMD Application Compatibility|AMD PSP Driver|AMD I2C|AMD GPIO|AMD SMBus|AMD SFH|AMD USB4|AMD Ryzen Power Plan|AMD PCI Device|AMD Wireless Button|AMD MicroPEP|AMD UART|AMD SPI)'
    $inst = $null; try { $inst = New-Object -ComObject WindowsInstaller.Installer } catch {}
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($root in "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall", "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall") {
        foreach ($k in @(Get-ChildItem $root -ErrorAction SilentlyContinue)) {
            $p = Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue
            $name = "$($p.DisplayName)"; if ($name -notmatch $rx) { continue }
            $id = $k.PSChildName; $isMsi = ($id -match '^\{[0-9A-Fa-f]{8}-([0-9A-Fa-f]{4}-){3}[0-9A-Fa-f]{12}\}$')
            $state = "Saglam"; $lp = $null
            if ($isMsi) {
                $known = $false; try { $lp = $inst.ProductInfo($id, "LocalPackage"); $known = $true } catch {}
                if (-not $known) { $state = "Yetim" }
                elseif (-not $lp -or -not (Test-Path $lp)) { $state = "OnbellekEksik" }
            } else {
                $exe = $null; if ("$($p.UninstallString)" -match '"([^"]+)"') { $exe = $Matches[1] } elseif ("$($p.UninstallString)" -match '^(\S+\.exe)') { $exe = $Matches[1] }
                if ($exe -and -not (Test-Path $exe)) { $state = "KaldiriciEksik" }
            }
            $list.Add([pscustomobject]@{ Name = $name; Version = "$($p.DisplayVersion)"; Id = $id; IsMsi = $isMsi; State = $state; KeyPath = $k.PSPath; RegPath = ($k.Name) })
        }
    }
    # Semsiye kayit ("AMD Chipset Software", MSI degil): ana MSI paketi (AMD_Chipset_Drivers) saglam degilse kendini kaldiramaz
    $mainOk = @($list | Where-Object { $_.IsMsi -and $_.Name -match '^AMD_Chipset_Drivers' -and $_.State -eq "Saglam" }).Count -gt 0
    foreach ($e in $list) { if (-not $e.IsMsi -and $e.Name -match '^AMD Chipset Software' -and $e.State -eq "Saglam" -and -not $mainOk) { $e.State = "AnaPaketBozuk" } }
    return $list
}

# 14. tur (canli bulgu): yukleyici paketlerini C:\AMD\Chipset_Software\Packages altina acar; onceki (or. Mart) kurulumdan
# kalan eski AMD_Chipset_Drivers.exe orada durursa yeni surum alt paketleri (IODriver\GPIO2 ...) acmiyor, zincir MSI 2203 /
# 0x80030003 (yol yok) ile dusup PPM i de geri aliyor -> her guncelleme 1603. Bu gecici klasorler kenara alinir (silinmez).
function Get-AmdChipsetStaleFolders($Items = $null) {
    $ts = Get-Date -Format "yyyyMMdd_HHmmss"
    $list = @(
        @{ Src = "C:\AMD\Chipset_Software";        Dst = "C:\AMD\_MrClean_eski_$ts" },
        @{ Src = "C:\AMD\Chipset_Installer";       Dst = "C:\AMD\_MrClean_eski_$ts" },
        @{ Src = "C:\AMD\Chipset_Software_Backup"; Dst = "C:\AMD\_MrClean_eski_$ts" },
        @{ Src = (Join-Path $env:APPDATA "AMD\Chipset_Software"); Dst = (Join-Path $env:APPDATA "AMD\_MrClean_eski_$ts") }
    )
    # 14. tur (4. sebep): ana AMD urunu (AMD_Chipset_Drivers MSI) kayitli + saglam DEGILSE Program Files taki eski AMD Chipset
    # Software uygulama klasoru de bayattir (yukleyici onu "kurulu" sayip degistirme moduna girer)
    $mainOk = @($Items | Where-Object { $_ -and $_.IsMsi -and "$($_.Name)" -match '^AMD_Chipset_Drivers' -and $_.State -eq "Saglam" }).Count -gt 0
    if (-not $mainOk) { $list += @{ Src = "${env:ProgramFiles(x86)}\AMD\Chipset_Software"; Dst = "C:\AMD\_MrClean_eski_$ts" } }
    return @($list | Where-Object { Test-Path $_.Src })
}

# 14. tur (canli bulgu, 4. sebep): AMD yukleyicisi kendi durumunu HKLM\SOFTWARE\WOW6432Node\AMD\AMD_Chipset_IODrivers altinda tutar
# (ProductVersion, InstallationPath, DeployedFeatures). Ana urun silinmis / yetimken bu anahtar kalirsa yukleyici "zaten kurulu,
# DEGISTIRME modu" sanip paketleri (Packages\IODriver\...) acmaz -> zincir 2203 / 0x80030003 ile duser (Device_ID.log:
# "Not appending since registry already exists ... in modify mode"). Ana urun saglam degilse anahtar bayattir.
function Get-AmdChipsetStaleStateKey($Items = $null) {
    $k = "HKLM:\SOFTWARE\WOW6432Node\AMD\AMD_Chipset_IODrivers"
    if (-not (Test-Path $k)) { return $null }
    $mainOk = @($Items | Where-Object { $_ -and $_.IsMsi -and "$($_.Name)" -match '^AMD_Chipset_Drivers' -and $_.State -eq "Saglam" }).Count -gt 0
    if ($mainOk) { return $null }
    return "HKLM\SOFTWARE\WOW6432Node\AMD\AMD_Chipset_IODrivers"
}

# 14. tur (canli bulgu, 3. sebep): kaldirma kaydi silinse de Windows Installer bilesen veritabaninda (UserData\S-1-5-18\Components)
# bilesenler hala ESKI urune ait gorunuyor -> yeni MSI 361/365 bileseni "Action: Null" ile atliyor, alt paketler (IODriver\...)
# olusmuyor, zincir 2203 / 0x80030003 ile dusuyor. Kayitli OLMAYAN bir urune ait VE yolu AMD / Chipset klasorunu gosteren bilesen
# referanslari bulunur (baska programlara dokunulmaz).
function Get-AmdOrphanComponentRefs {
    $prodRoot = "HKLM:\SOFTWARE\Classes\Installer\Products"
    $known = @{}; foreach ($p in @(Get-ChildItem $prodRoot -ErrorAction SilentlyContinue)) { $known[$p.PSChildName.ToUpperInvariant()] = $true }
    # 1. gecis: kayitli OLMAYAN urunlere ait tum referanslar. Cogunun degeri BOS (anahtar yolu olmayan klasor / isaret bileseni),
    # bu yuzden AMD olup olmadigi urun bazinda anlasilir: urunun en az bir referansi AMD / Chipset yolunu gosteriyorsa o urunun
    # TUM referanslari temizlenir (bu PC: 426 referansin 424 u bos, 2 si \SOFTWARE\AMD\AMD_Chipset_IODrivers).
    $all = New-Object System.Collections.Generic.List[object]; $amdProducts = @{}
    foreach ($ck in @(Get-ChildItem "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Installer\UserData\S-1-5-18\Components" -ErrorAction SilentlyContinue)) {
        $props = (Get-ItemProperty $ck.PSPath -ErrorAction SilentlyContinue).PSObject.Properties | Where-Object { $_.Name -match '^[0-9A-Fa-f]{32}$' }
        foreach ($pr in $props) {
            $pkU = $pr.Name.ToUpperInvariant()
            if ($known.ContainsKey($pkU)) { continue }
            $all.Add([pscustomobject]@{ KeyPath = $ck.PSPath; RegPath = $ck.Name; Product = $pr.Name; ProductU = $pkU; Value = "$($pr.Value)" })
            if ("$($pr.Value)" -match '(?i)\\AMD\\|Chipset_Software|AMD[ _]Chipset') { $amdProducts[$pkU] = $true }
        }
    }
    return @($all | Where-Object { $amdProducts.ContainsKey($_.ProductU) })
}

function Invoke-AmdChipsetRepair([switch]$Full, [switch]$AnalyzeOnly) {
    $items = @(Get-AmdChipsetInstallState)
    $broken = @($items | Where-Object { $_.State -ne "Saglam" })
    $healthy = @($items | Where-Object { $_.State -eq "Saglam" })
    $stale = @(Get-AmdChipsetStaleFolders $items)
    $orph = @(Get-AmdOrphanComponentRefs)
    $stateKey = Get-AmdChipsetStaleStateKey $items
    $res = [ordered]@{ Found = $items.Count; Broken = $broken.Count; Cleaned = 0; Uninstalled = 0; Failed = 0; BackupDir = $null; Items = $items; Stale = ($stale.Count + [int][bool]$stateKey); Moved = 0; OrphanRefs = $orph.Count; RefsRemoved = 0 }
    if ($AnalyzeOnly -or ($items.Count -eq 0 -and $stale.Count -eq 0 -and $orph.Count -eq 0 -and -not $stateKey)) { return $res }
    $script:__amdStateKey = $stateKey
    $bk = Join-Path $AppDataPath ("backups\AmdChipset_" + (Get-Date -Format "yyyyMMdd_HHmmss"))
    New-Item -ItemType Directory -Path $bk -Force | Out-Null; $res.BackupDir = $bk
    $n = 0
    function Export-Key([string]$RegPath) { if (-not $RegPath) { return }; $script:__bkN++; $f = Join-Path $bk ("{0:D2}.reg" -f $script:__bkN); $null = Invoke-HiddenCommand "reg.exe" "export `"$RegPath`" `"$f`" /y" }
    $script:__bkN = 0
    function Remove-MsiRegistration([string]$Guid) {
        $pk = ConvertTo-MsiPackedGuid $Guid; if (-not $pk) { return }
        foreach ($rp in @("HKLM\SOFTWARE\Classes\Installer\Products\$pk", "HKLM\SOFTWARE\Classes\Installer\Features\$pk", "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Installer\UserData\S-1-5-18\Products\$pk")) {
            if (Test-Path "Registry::$rp") { Export-Key $rp; Remove-Item "Registry::$rp" -Recurse -Force -ErrorAction SilentlyContinue }
        }
        foreach ($uc in @(Get-ChildItem "HKLM:\SOFTWARE\Classes\Installer\UpgradeCodes" -ErrorAction SilentlyContinue)) {
            $props = (Get-ItemProperty $uc.PSPath -ErrorAction SilentlyContinue).PSObject.Properties | Where-Object { $_.Name -eq $pk }
            if ($props) { Export-Key $uc.Name; Remove-ItemProperty -Path $uc.PSPath -Name $pk -Force -ErrorAction SilentlyContinue
                if (@((Get-Item $uc.PSPath).Property).Count -eq 0) { Remove-Item $uc.PSPath -Force -ErrorAction SilentlyContinue } }
        }
    }
    # Tam kaldir: saglam MSI bilesenleri Windows Installer ile sessizce kaldirilir (surucu dosyalari DriverStore da kalir)
    if ($Full) {
        foreach ($e in @($healthy | Where-Object { $_.IsMsi })) {
            WpfLog "[AMD] Kaldiriliyor: $($e.Name) $($e.Version)"
            $p = Start-Process msiexec.exe -ArgumentList "/x $($e.Id) /qn /norestart" -PassThru -WindowStyle Hidden
            $sw = [Diagnostics.Stopwatch]::StartNew(); while (-not $p.HasExited -and $sw.Elapsed.TotalSeconds -lt 300) { Do-Events; Start-Sleep -Milliseconds 200 }
            if (-not $p.HasExited) { try { $p.Kill() } catch {}; $code = -1 } else { $code = $p.ExitCode }
            if ($code -in 0, 3010, 1641) { $res.Uninstalled++ } else { WpfLog "[AMD] msiexec cikis kodu $code — kayit temizlenecek"; $e.State = "KaldirmaBasarisiz" }
        }
        foreach ($e in @($healthy | Where-Object { -not $e.IsMsi })) { $e.State = "TamKaldir" }
    }
    foreach ($e in @($items | Where-Object { $_.State -notin @("Saglam") })) {
        if (-not (Test-Path $e.KeyPath) -and $e.State -ne "KaldirmaBasarisiz") { continue }   # msiexec zaten kaldirdi
        try {
            WpfLog "[AMD] Temizleniyor ($($e.State)): $($e.Name) $($e.Version)"
            if ($e.IsMsi) { Remove-MsiRegistration $e.Id }
            if (Test-Path $e.KeyPath) { Export-Key $e.RegPath; Remove-Item $e.KeyPath -Recurse -Force -ErrorAction Stop }
            $res.Cleaned++
        } catch { $res.Failed++; WpfLog "[AMD] Temizlenemedi: $($e.Name) — $($_.Exception.Message)" }
    }
    # Yetim bilesen referanslari: degerler .reg olarak yedeklenir, sonra silinir; bos kalan bilesen anahtari kaldirilir
    if ($orph.Count -gt 0) {
        $sb = New-Object System.Text.StringBuilder; [void]$sb.AppendLine("Windows Registry Editor Version 5.00"); [void]$sb.AppendLine("")
        foreach ($g in ($orph | Group-Object RegPath)) {
            [void]$sb.AppendLine("[$($g.Name)]")
            foreach ($r in $g.Group) { [void]$sb.AppendLine(('"{0}"="{1}"' -f $r.Product, ($r.Value -replace '\\', '\\' -replace '"', '\"'))) }
            [void]$sb.AppendLine("")
        }
        [IO.File]::WriteAllText((Join-Path $bk "yetim_bilesenler.reg"), $sb.ToString(), [Text.Encoding]::Unicode)
        foreach ($r in $orph) {
            try { Remove-ItemProperty -Path $r.KeyPath -Name $r.Product -Force -ErrorAction Stop; $res.RefsRemoved++
                if (@((Get-Item $r.KeyPath -ErrorAction SilentlyContinue).Property).Count -eq 0) { Remove-Item $r.KeyPath -Force -ErrorAction SilentlyContinue } } catch { $res.Failed++ }
        }
        WpfLog "[AMD] Yetim bilesen referansi temizlendi: $($res.RefsRemoved) / $($orph.Count) (yedek: yetim_bilesenler.reg)"
    }
    if ($script:__amdStateKey) {
        try { Export-Key $script:__amdStateKey; Remove-Item ("Registry::" + $script:__amdStateKey) -Recurse -Force -ErrorAction Stop; $res.Moved++
            WpfLog "[AMD] Bayat yukleyici durum anahtari yedeklenip kaldirildi: $($script:__amdStateKey)" } catch { $res.Failed++; WpfLog "[AMD] Durum anahtari kaldirilamadi: $($_.Exception.Message)" }
    }
    foreach ($t in $stale) {
        try {
            if (-not (Test-Path $t.Dst)) { New-Item -ItemType Directory -Path $t.Dst -Force | Out-Null }
            $dest = Join-Path $t.Dst (Split-Path $t.Src -Leaf)
            if ($t.Src -like "*Program Files*") { $dest = Join-Path $t.Dst ("ProgramFiles_" + (Split-Path $t.Src -Leaf)) }
            if (Test-Path $dest) { $dest += "_" + [guid]::NewGuid().ToString("N").Substring(0, 6) }
            Move-Item -Path $t.Src -Destination $dest -Force -ErrorAction Stop
            $res.Moved++; WpfLog "[AMD] Eski yukleyici klasoru kenara alindi: $($t.Src) -> $($t.Dst)"
        } catch { $res.Failed++; WpfLog "[AMD] Klasor tasinamadi: $($t.Src) — $($_.Exception.Message)" }
    }
    WpfLog ("[AMD] Bitti: {0} kayit temizlendi, {1} bilesen kaldirildi, {2} eski klasor kenara alindi, {3} hata. Yedek: {4}" -f $res.Cleaned, $res.Uninstalled, $res.Moved, $res.Failed, $bk)
    return $res
}

# ---- v1.3.0 (14. tur): AMD YONGA SETI — DOGRUDAN SURUCU KURULUMU (resmi yukleyici basarisiz olursa) ----
# Hicbir surucu adi / surumu sabit DEGIL: paket, kullanicinin calistirdigi resmi AMD yukleyicisinin %APPDATA% altina actigi
# imzali AMD_Chipset_Drivers.msi den gelir; msiexec /a ile sisteme dokunmadan acilir; her INF in donanim kimlikleri bu PC deki
# CIHAZLARLA eslestirilir; yalnizca paketteki surum cihazdakinden YENIYSE pnputil ile kurulur (Windows daha iyi olani korur).
function Compare-AmdVersion([string]$A, [string]$B) {
    $pa = @(($A -replace '[^\d\.]', '').Split('.') | Where-Object { $_ -ne '' } | ForEach-Object { [int64]$_ })
    $pb = @(($B -replace '[^\d\.]', '').Split('.') | Where-Object { $_ -ne '' } | ForEach-Object { [int64]$_ })
    for ($i = 0; $i -lt [Math]::Max($pa.Count, $pb.Count); $i++) {
        $x = if ($i -lt $pa.Count) { $pa[$i] } else { 0 }; $y = if ($i -lt $pb.Count) { $pb[$i] } else { 0 }
        if ($x -ne $y) { return [Math]::Sign($x - $y) }
    }
    return 0
}

# Resmi yukleyicinin en son actigi ana paket (imza dogrulamali)
function Get-AmdChipsetPackage {
    $root = Join-Path $env:APPDATA "AMD\Chipset_Software"
    $msi = Get-ChildItem $root -Recurse -Filter "AMD_Chipset_Drivers.msi" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if (-not $msi) { return $null }
    $sig = Get-AuthenticodeSignature $msi.FullName
    $ok = ($sig.Status -eq "Valid" -and "$($sig.SignerCertificate.Subject)" -match "Advanced Micro Devices")
    $ver = $null; try { $db = (New-Object -ComObject WindowsInstaller.Installer).OpenDatabase($msi.FullName, 0); $v = $db.OpenView("SELECT Value FROM Property WHERE Property='ProductVersion'"); $v.Execute(); $ver = $v.Fetch().StringData(1) } catch {}
    return [pscustomobject]@{ Path = $msi.FullName; Version = $ver; Date = $msi.LastWriteTime; SignatureOk = $ok; Signer = "$($sig.SignerCertificate.Subject)" }
}

# Paketi sisteme dokunmadan acar (yonetici kurulumu)
function Expand-AmdChipsetPackage([string]$MsiPath) {
    $dst = Join-Path $env:TEMP ("MrClean_AMD_" + (Get-Date -Format "yyyyMMdd_HHmmss"))
    $p = Start-Process msiexec.exe -ArgumentList "/a `"$MsiPath`" /qn TARGETDIR=`"$dst`"" -PassThru -WindowStyle Hidden
    while (-not $p.HasExited) { Do-Events; Start-Sleep -Milliseconds 200 }
    if ($p.ExitCode -ne 0 -or -not (Test-Path $dst)) { return $null }
    return $dst
}

# Plani uygular: yalnizca Kur / Guncelle olan INF ler (tekil) pnputil ile; sonra cihaz surumleri yeniden okunur
function Install-AmdDriverPlan($Plan) {
    $reboot = $false; $done = @{}
    foreach ($p in @($Plan | Where-Object { $_.Action -in "Kur", "Guncelle" })) {
        if (-not $done.ContainsKey($p.Inf)) {
            WpfLog "[AMD] Kuruluyor: $(Split-Path $p.Inf -Leaf) ($($p.Package))"
            $o = & pnputil.exe /add-driver "$($p.Inf)" /install 2>&1; $code = $LASTEXITCODE
            $done[$p.Inf] = $code; if ($code -eq 3010) { $reboot = $true }
            Do-Events
        }
    }
    Start-Sleep -Seconds 2
    foreach ($p in $Plan) {
        $now = "$((Get-PnpDeviceProperty -InstanceId $p.InstanceId -KeyName DEVPKEY_Device_DriverVersion -ErrorAction SilentlyContinue).Data)"
        if ($p.Action -eq "Guncel") { $p.Result = "Güncel"; continue }
        $code = $done[$p.Inf]
        if ((Compare-AmdVersion $now $p.Package) -ge 0) { $p.Result = "✅ $($p.Current) → $now" }
        elseif ($code -eq 3010) { $p.Result = "🔄 Kuruldu — yeniden başlatınca $($p.Package)"; $reboot = $true }
        else { $p.Result = "❌ Kurulamadı (kod $code)" }
    }
    return [pscustomobject]@{ Plan = $Plan; RebootNeeded = $reboot }
}

# Resmi AMD yukleyicisinin son ozeti: basarisiz bilesen sayisi
function Get-AmdInstallerSummary {
    $f = "C:\AMD\Chipset_Software\Logs\AMD_Chipset_Software_Install_Summary.txt"
    if (-not (Test-Path $f)) { return $null }
    $t = [IO.File]::ReadAllText($f)
    return [pscustomobject]@{ Time = (Get-Item $f).LastWriteTime; Failed = ([regex]::Matches($t, '(?im)^\s*Install\s*:\s*Fail')).Count; Ok = ([regex]::Matches($t, '(?im)^\s*Install\s*:\s*Success')).Count }
}

# Bu PC deki AMD cihazlari (tek CIM sorgusu): kimlikler + su anki surucu (surum, INF, katalog)
function Get-AmdChipsetDevices {
    $ri = [System.Text.RegularExpressions.RegexOptions]'IgnoreCase, CultureInvariant'
    $drv = @{}; foreach ($s in @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue)) { if ($s.DeviceID) { $drv["$($s.DeviceID)".ToUpperInvariant()] = $s } }
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($e in @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue)) {
        $id = "$($e.DeviceID)"
        if (-not [regex]::IsMatch($id, '^(ACPI\\AMDI|ACPI\\VEN_AMDI|PCI\\VEN_1022|SWC\\|ROOT\\AMD)', $ri)) { continue }
        $s = $drv[$id.ToUpperInvariant()]
        $cat = $null
        if ($s -and $s.InfName) { $p = Join-Path $env:WINDIR "INF\$($s.InfName)"; if (Test-Path $p) { $m = [regex]::Match([IO.File]::ReadAllText($p), '^\s*CatalogFile(?:\.NTamd64)?\s*=\s*([^\s;]+)', [System.Text.RegularExpressions.RegexOptions]'IgnoreCase, CultureInvariant, Multiline'); if ($m.Success) { $cat = $m.Groups[1].Value.ToUpperInvariant() } } }
        $ids = @(@($e.HardwareID) + @($e.CompatibleID) | Where-Object { $_ } | ForEach-Object { "$_".ToUpperInvariant() })
        $list.Add([pscustomobject]@{ Name = "$($e.Name)"; InstanceId = $id; Status = "$($e.Status)"; Problem = [int]$e.ConfigManagerErrorCode
            Version = $(if ($s) { "$($s.DriverVersion)" } else { "" }); Inf = $(if ($s) { "$($s.InfName)" } else { "" }); Catalog = $cat; Ids = $ids })
    }
    return $list
}

# Acilmis paketteki INF ler -> bu PC deki cihazlarla eslesen surucu plani.
# Guvenlik kurali: surum karsilastirmasi YALNIZCA ayni surucu ailesi (ayni katalog dosyasi) icinde yapilir; farkli aile
# (or. cihaz AMD Interface kullaniyorken paketteki eski "SMBus" surucusu) ONERILMEZ. Surucusu olmayan / hatali cihaza kurulum onerilir.
function Get-AmdDriverPlan([string]$ExpandedRoot, $Devices) {
    $ri = [System.Text.RegularExpressions.RegexOptions]'IgnoreCase, CultureInvariant'
    $osTag = if ([Environment]::OSVersion.Version.Build -ge 22000) { "W11" } else { "WT" }
    $infs = @(Get-ChildItem $ExpandedRoot -Recurse -Filter *.inf -ErrorAction SilentlyContinue)
    $chosen = foreach ($g in ($infs | Group-Object { Split-Path $_.DirectoryName -Parent })) {
        $pref = @($g.Group | Where-Object { [regex]::IsMatch((Split-Path $_.DirectoryName -Leaf), "^$osTag", $ri) })
        if ($pref.Count -gt 0) { $pref } else { $g.Group }
    }
    $plan = New-Object System.Collections.Generic.List[object]
    foreach ($inf in @($chosen)) {
        $txt = [IO.File]::ReadAllText($inf.FullName)
        $dv = [regex]::Match($txt, '^\s*DriverVer\s*=\s*[^,]*,\s*([\d\.]+)', [System.Text.RegularExpressions.RegexOptions]'IgnoreCase, CultureInvariant, Multiline').Groups[1].Value
        $cat = [regex]::Match($txt, '^\s*CatalogFile(?:\.NTamd64)?\s*=\s*([^\s;]+)', [System.Text.RegularExpressions.RegexOptions]'IgnoreCase, CultureInvariant, Multiline').Groups[1].Value.ToUpperInvariant()
        $clean = [regex]::Replace($txt, ';.*$', '', [System.Text.RegularExpressions.RegexOptions]'Multiline')
        $hw = @([regex]::Matches($clean, '\b(?:ACPI|PCI|SWC|SWD|ROOT|HID|USB)\\[A-Z0-9_&\-\.\\]+', $ri) | ForEach-Object { $_.Value.ToUpperInvariant() } | Select-Object -Unique)
        foreach ($d in $Devices) {
            if (-not (@($d.Ids | Where-Object { $hw -contains $_ }).Count)) { continue }
            $noDriver = (-not $d.Version) -or ($d.Problem -ne 0)
            $sameFamily = ($d.Catalog -and $cat -and $d.Catalog -eq $cat)
            if (-not $noDriver -and -not $sameFamily) { continue }      # farkli surucu ailesi: dokunma
            $cmp = if ($d.Version) { Compare-AmdVersion $dv $d.Version } else { 1 }
            $act = if ($noDriver) { "Kur" } elseif ($cmp -gt 0) { "Guncelle" } else { "Guncel" }
            $plan.Add([pscustomobject]@{ Device = $d.Name; InstanceId = $d.InstanceId; Current = $d.Version; Package = $dv; Inf = $inf.FullName; Catalog = $cat; Action = $act; Result = "" })
        }
    }
    # Ayni cihaz birden fazla INF ile eslesirse en yuksek surumlu olani tut
    return @($plan | Group-Object InstanceId | ForEach-Object { $_.Group | Sort-Object { (@($_.Package -split '\.') | ForEach-Object { '{0:D10}' -f [int64]("0" + $_) }) -join '.' } -Descending | Select-Object -First 1 })
}

function Show-AmdChipsetRepair {
    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="🧩 AMD Yonga Seti Onarımı" Width="900" Height="680" MinWidth="760" MinHeight="560" Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner">
    <Window.Resources>
$($global:SubTheme)
        <Style TargetType="GridViewColumnHeader">
            <Setter Property="Background" Value="#13161B"/>
            <Setter Property="Foreground" Value="#8A919C"/>
            <Setter Property="Padding" Value="10,5"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="BorderThickness" Value="0,0,1,1"/>
            <Setter Property="BorderBrush" Value="#232831"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
        </Style>
        <Style TargetType="ListViewItem">
            <Setter Property="Foreground" Value="#E6E8EB"/>
            <Setter Property="BorderThickness" Value="0,0,0,1"/>
            <Setter Property="BorderBrush" Value="#1F232B"/>
            <Setter Property="Padding" Value="0,6"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ListViewItem">
                        <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}">
                            <GridViewRowPresenter Content="{TemplateBinding Content}" Margin="{TemplateBinding Padding}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True"><Setter Property="Background" Value="#181C23"/></Trigger>
                            <Trigger Property="IsSelected" Value="True"><Setter Property="Background" Value="#1C2433"/></Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
    </Window.Resources>
  <Grid Margin="16">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="110"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Grid.Row="0" Text="🧩 AMD Yonga Seti Onarımı" Foreground="#E6E8EB" FontSize="20" FontWeight="Bold"/>
    <TextBlock Grid.Row="1" Foreground="#A9B0BB" FontSize="13" TextWrapping="Wrap" Margin="0,6,0,10">
      <Run Text="Sıra: "/><Run Text="1) Kayıtları Onar" Foreground="#E0A23B"/><Run Text=" (bozuk kurulum kaydı varsa) → "/><Run Text="2) AMD Yükleyicisini Çalıştır" Foreground="#8CB4FF"/><Run Text=" (amd.com'dan indirdiğiniz dosya) → AMD başarısız olursa MrClean "/><Run Text="3) Sürücüleri Doğrudan Kur" Foreground="#3FB97A"/><Run Text=" adımına KENDİLİĞİNDEN geçer. Sürücü adı / sürümü sabit değildir: yalnızca bu bilgisayardaki cihazlarla eşleşen ve AYNI sürücü ailesinden daha yeni olan AMD imzalı sürücüler kurulur. Her şey yedeklenir; eski sürücüler Aygıt Yöneticisi'nden geri alınabilir."/>
    </TextBlock>
    <Border Grid.Row="2" x:Name="bdAmdBanner" CornerRadius="6" Padding="12,10" Margin="0,0,0,10" Background="#1C2433">
      <TextBlock x:Name="txtAmdBanner" Foreground="#E6E8EB" FontSize="14.5" FontWeight="SemiBold" TextWrapping="Wrap" Text="Analiz ediliyor..."/>
    </Border>
    <ListView Grid.Row="3" x:Name="lvAmd" Background="#15181E" Foreground="#E6E8EB" BorderBrush="#232831">
      <ListView.View><GridView>
        <GridViewColumn Header="Cihaz" Width="300" DisplayMemberBinding="{Binding Cihaz}"/>
        <GridViewColumn Header="Şu anki sürüm" Width="120" DisplayMemberBinding="{Binding Simdi}"/>
        <GridViewColumn Header="Paketteki" Width="110" DisplayMemberBinding="{Binding Paket}"/>
        <GridViewColumn Header="Durum" Width="300" DisplayMemberBinding="{Binding Durum}"/>
      </GridView></ListView.View>
    </ListView>
    <TextBox Grid.Row="4" x:Name="txtAmdLog" Margin="0,8,0,0" Background="#0C0E12" Foreground="#9AA3B2" FontFamily="Cascadia Mono, Consolas" FontSize="12" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" BorderBrush="#232831"/>
    <WrapPanel Grid.Row="5" Margin="0,10,0,0">
      <Button x:Name="btnAmdClean"  Content="🧹 1. Kayıtları Onar"            MinWidth="190" Height="36" Margin="0,0,8,0" FontWeight="Bold"/>
      <Button Style="{StaticResource SwBtnPrimary}" x:Name="btnAmdRun"    Content="▶ 2. AMD Yükleyicisini Çalıştır" MinWidth="230" Height="36" Margin="0,0,8,0" FontWeight="Bold"/>
      <Button x:Name="btnAmdDirect" Content="⚙ 3. Sürücüleri Doğrudan Kur"    MinWidth="220" Height="36" Margin="0,0,8,0" FontWeight="Bold"/>
      <Button Style="{StaticResource SwBtnDangerSolid}" x:Name="btnAmdReboot" Content="🔄 Şimdi Yeniden Başlat"         MinWidth="180" Height="36" Margin="0,0,8,0" FontWeight="Bold" Visibility="Collapsed"/>
      <Button x:Name="btnAmdClose"  Content="Kapat"                           MinWidth="80"  Height="36"/>
    </WrapPanel>
  </Grid>
</Window>
"@
    $w = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader ([xml]$xaml)))
    Initialize-SubWindow $w
    try { if ($Win -and $Win.IsVisible) { $w.Owner = $Win } } catch {}
    $c = @{}; foreach ($n in "bdAmdBanner", "txtAmdBanner", "lvAmd", "txtAmdLog", "btnAmdClean", "btnAmdRun", "btnAmdDirect", "btnAmdReboot", "btnAmdClose") { $c[$n] = $w.FindName($n) }
    $st = @{ X = $null; Pkg = $null; Plan = @(); Repair = $null; Busy = $false }
    $log = { param($m) $line = ("[{0}] {1}`r`n" -f (Get-Date -Format "HH:mm:ss"), $m); $c.txtAmdLog.AppendText($line); $c.txtAmdLog.ScrollToEnd(); WpfLog "[AMD] $m"; Do-Events }
    $banner = { param($kind, $text)
        $col = switch ($kind) { "ok" { "#16241C" } "warn" { "#2B2216" } "err" { "#2A1A1D" } "busy" { "#1C2433" } default { "#1C2433" } }   # v1.3.0 (B13 Grup 5): palet tonları
        $c.bdAmdBanner.Background = (New-Object System.Windows.Media.BrushConverter).ConvertFromString($col); $c.txtAmdBanner.Text = $text; Do-Events }
    $durum = { param($p) if ($p.Result) { $p.Result } else { switch ($p.Action) { "Guncel" { "✔ Güncel" } "Guncelle" { "⬆ Güncellenebilir" } "Kur" { "➕ Sürücü yok — kurulacak" } default { $p.Action } } } }
    $fill = {
        $rows = foreach ($p in @($st.Plan)) { [pscustomobject]@{ Cihaz = $p.Device; Simdi = $(if ($p.Current) { $p.Current } else { "—" }); Paket = $(if ($p.Package) { $p.Package } else { "—" }); Durum = (& $durum $p) } }
        $c.lvAmd.ItemsSource = @($rows) }
    # Analiz: kayit durumu + paket + cihaz plani + karar bandi
    $analyze = {
        & $banner "busy" "🔎 Analiz ediliyor (kurulum kayıtları, AMD cihazları, sürücü paketi)..."
        $st.Repair = Invoke-AmdChipsetRepair -AnalyzeOnly
        $pkg = Get-AmdChipsetPackage
        if ($pkg -and $pkg.SignatureOk -and ($null -eq $st.Pkg -or $st.Pkg.Path -ne $pkg.Path -or $st.Pkg.Date -ne $pkg.Date)) {
            if ($st.X) { Remove-Item $st.X -Recurse -Force -ErrorAction SilentlyContinue }
            & $log "Paket bulundu: AMD Chipset $($pkg.Version) (imza: Advanced Micro Devices, geçerli) — açılıyor..."
            $st.X = Expand-AmdChipsetPackage $pkg.Path; $st.Pkg = $pkg
        } elseif ($pkg -and -not $pkg.SignatureOk) { & $log "UYARI: bulunan paketin AMD imzası geçersiz — kullanılmayacak."; $pkg = $null }
        $devs = Get-AmdChipsetDevices
        if ($st.X) { $st.Plan = @(Get-AmdDriverPlan $st.X $devs) }
        else { $st.Plan = @($devs | Where-Object { $_.Name -match '^AMD ' -and $_.Inf } | ForEach-Object { [pscustomobject]@{ Device = $_.Name; InstanceId = $_.InstanceId; Current = $_.Version; Package = ""; Inf = ""; Action = "?"; Result = "Paket yok — önce 2. adım" } }) }
        & $fill
        # Gercek bozulma = yetim / bozuk kayit + yetim parca. Eski gecici klasor / durum anahtari her AMD calismasindan kalir;
        # yalnizca yukleyici TEKRAR calistirilacaginda sorun cikarir -> uyari degil bilgi, 2. adimda otomatik temizlenir.
        $r = $st.Repair; $issues = $r.Broken + $r.OrphanRefs
        $todo = @($st.Plan | Where-Object { $_.Action -in "Kur", "Guncelle" }).Count
        $sum = Get-AmdInstallerSummary
        if ($r.Stale -gt 0) { & $log "Bilgi: AMD yükleyicisinin önceki çalışmasından $($r.Stale) geçici klasör / durum anahtarı var — '2. AMD Yükleyicisini Çalıştır' öncesi otomatik temizlenir." }
        $c.btnAmdClean.IsEnabled = (($issues + $r.Stale) -gt 0); $c.btnAmdDirect.IsEnabled = ($todo -gt 0)
        if ($issues -gt 0) { & $banner "warn" ("⚠ Bozuk AMD kurulum kaydı bulundu ({0} sorun: bozuk kayıt {1}, yetim parça {2}). AMD yükleyicisi bu yüzden 'başarısız' oluyor. Önce '1. Kayıtları Onar' (2. adım bunu kendisi de yapar)." -f $issues, $r.Broken, $r.OrphanRefs) }
        elseif (-not $st.X) { & $banner "busy" "ℹ AMD sürücü paketi henüz yok. amd.com'dan anakartınızın yonga setine ait 'AMD Chipset Software' dosyasını indirip '2. AMD Yükleyicisini Çalıştır' ile seçin." }
        elseif ($todo -gt 0) { & $banner "warn" ("⬆ {0} AMD sürücüsü güncellenebilir (paket {1}).{2} '3. Sürücüleri Doğrudan Kur' ile MrClean kurar." -f $todo, $st.Pkg.Version, $(if ($sum -and $sum.Failed -gt 0) { " AMD yükleyicisinin son çalıştırması: $($sum.Failed) bileşen başarısız." } else { "" })) }
        else { & $banner "ok" ("✅ Tüm AMD yonga seti sürücüleri güncel (paket {0}). Yapılacak bir şey yok." -f $st.Pkg.Version) }
    }
    $direct = {
        $todo = @($st.Plan | Where-Object { $_.Action -in "Kur", "Guncelle" }).Count
        if ($todo -eq 0) { return }
        & $banner "busy" "⚙ MrClean $todo sürücüyü kuruyor (AMD imzalı paket, Windows sürücü kurulumu)... Bilgisayarı kullanmaya devam edebilirsiniz."
        $res = Install-AmdDriverPlan $st.Plan; & $fill
        $ok = @($res.Plan | Where-Object { $_.Result -like "✅*" -or $_.Result -like "🔄*" }).Count; $bad = @($res.Plan | Where-Object { $_.Result -like "❌*" }).Count
        foreach ($p in @($res.Plan | Where-Object { $_.Action -ne "Guncel" })) { & $log "$($p.Device): $($p.Result)" }
        if ($bad -gt 0) { & $banner "err" ("❌ {0} sürücü kurulamadı, {1} sürücü kuruldu. Ayrıntı aşağıdaki kayıtta ve MrClean işlem kaydında." -f $bad, $ok) }
        elseif ($res.RebootNeeded) { & $banner "ok" ("✅ MrClean {0} AMD sürücüsünü kurdu. 🔄 Bir sürücü yeniden başlatmadan sonra devreye girecek — 'Şimdi Yeniden Başlat' ya da daha sonra." -f $ok) }
        else { & $banner "ok" ("✅ MrClean {0} AMD sürücüsünü kurdu ve doğruladı. Yeniden başlatma gerekmiyor." -f $ok) }
        if ($res.RebootNeeded) { $c.btnAmdReboot.Visibility = "Visible" }
        $c.btnAmdDirect.IsEnabled = $false
    }
    $c.btnAmdClean.Add_Click({
        & $log "Kayıtlar onarılıyor (önce yedekleniyor)..."
        $r = Invoke-AmdChipsetRepair
        & $log ("Onarım: {0} kayıt, {1} yetim parça, {2} eski klasör / anahtar temizlendi, {3} hata. Yedek: {4}" -f $r.Cleaned, $r.RefsRemoved, $r.Moved, $r.Failed, $r.BackupDir)
        & $analyze
        if ($c.btnAmdClean.IsEnabled -eq $false) { & $banner "ok" "✅ Kurulum kayıtları onarıldı. Şimdi '2. AMD Yükleyicisini Çalıştır'." }
    })
    $c.btnAmdRun.Add_Click({
        if ($st.Busy) { return }
        if ($st.Repair -and ($st.Repair.Broken + $st.Repair.Stale + $st.Repair.OrphanRefs) -gt 0) { & $log "Önce bozuk kayıtlar onarılıyor..."; $r = Invoke-AmdChipsetRepair; & $log ("Onarım: {0} kayıt, {1} yetim parça, {2} eski klasör / anahtar temizlendi." -f $r.Cleaned, $r.RefsRemoved, $r.Moved) }
        $dlg = New-Object Microsoft.Win32.OpenFileDialog
        $dlg.Title = "amd.com'dan indirdiğiniz AMD Chipset Software dosyasını seçin"; $dlg.Filter = "AMD yükleyicisi (*.exe)|*.exe"
        $dlg.InitialDirectory = Join-Path $env:USERPROFILE "Downloads"
        if (-not $dlg.ShowDialog($w)) { return }
        $sig = Get-AuthenticodeSignature $dlg.FileName
        if ($sig.Status -ne "Valid" -or "$($sig.SignerCertificate.Subject)" -notmatch "Advanced Micro Devices") { & $banner "err" "❌ Seçilen dosya AMD tarafından imzalanmamış — çalıştırılmadı. amd.com'dan indirilen 'AMD Chipset Software' dosyasını seçin."; return }
        $st.Busy = $true; $c.btnAmdRun.IsEnabled = $false; $c.btnAmdDirect.IsEnabled = $false; $c.btnAmdClean.IsEnabled = $false
        $t0 = Get-Date
        & $log "AMD yükleyicisi başlatıldı: $(Split-Path $dlg.FileName -Leaf) (imza geçerli)"
        & $banner "busy" "⏳ AMD yükleyicisi açık. Kurulumu o pencerede tamamlayın ('Yükle'). Bittiğinde — başarılı ya da başarısız — MrClean KENDİLİĞİNDEN devam edecek. Bu pencereyi ve MrClean'i kapatmayın."
        try {
            $p = Start-Process -FilePath $dlg.FileName -PassThru
            $sw = [Diagnostics.Stopwatch]::StartNew(); $idle = 0
            while ($sw.Elapsed.TotalMinutes -lt 45) {
                Start-Sleep -Milliseconds 700; Do-Events
                $amdUi = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { "$($_.MainWindowTitle)" -match 'AMD' -and "$($_.MainWindowTitle)" -match '(?i)Y.kleyici|Installer|Chipset|Yonga' })
                $msiBusy = @(Get-CimInstance Win32_Process -Filter "Name='msiexec.exe'" -ErrorAction SilentlyContinue | Where-Object { "$($_.CommandLine)" -notmatch '/V\s*$' }).Count
                if ($p.HasExited -and $amdUi.Count -eq 0 -and $msiBusy -eq 0) { $idle++ } else { $idle = 0 }
                if ($idle -ge 4) { break }
            }
        } catch { & $log "Yükleyici başlatılamadı: $($_.Exception.Message)" }
        & $log "AMD yükleyicisi kapandı — sonuç değerlendiriliyor..."
        $sum = Get-AmdInstallerSummary
        & $analyze
        $todo = @($st.Plan | Where-Object { $_.Action -in "Kur", "Guncelle" }).Count
        $amdFail = ($sum -and $sum.Time -ge $t0 -and $sum.Failed -gt 0)
        if ($todo -gt 0) {
            & $log ("AMD yükleyicisi tamamlayamadı ({0}). MrClean doğrudan kuruluma geçiyor." -f $(if ($amdFail) { "$($sum.Failed) bileşen 'Fail'" } else { "sürücüler güncellenmedi" }))
            & $banner "warn" ("⚠ AMD yükleyicisi başarısız oldu ({0} bileşen). MrClean sürücüleri DOĞRUDAN kuruyor — tekrar tıklamanız gerekmez..." -f $(if ($amdFail) { $sum.Failed } else { $todo }))
            Start-Sleep -Milliseconds 800; & $direct
        }
        elseif ($amdFail) { & $banner "ok" ("✅ Tüm AMD sürücüleri güncel. (AMD yükleyicisi özetinde {0} bileşen 'Fail' yazsa da cihazlardaki sürücüler paketteki en yeni sürümde — AMD özet hatası.)" -f $sum.Failed) }
        else { & $banner "ok" "✅ AMD yükleyicisi başarıyla kurdu — tüm AMD yonga seti sürücüleri güncel. AMD yeniden başlatma isterse yapın." }
        $st.Busy = $false; $c.btnAmdRun.IsEnabled = $true
    })
    $c.btnAmdDirect.Add_Click({ if (-not $st.Busy) { $st.Busy = $true; & $direct; $st.Busy = $false } })
    $c.btnAmdReboot.Add_Click({
        if ([System.Windows.MessageBox]::Show($w, "Bilgisayar 10 saniye içinde yeniden başlatılacak. Açık çalışmalarınızı kaydettiniz mi?", "Yeniden Başlat", "YesNo", "Question") -eq 'Yes') { Start-Process shutdown.exe -ArgumentList "/r /t 10 /c `"MrClean: AMD surucu kurulumu`"" -WindowStyle Hidden }
    })
    $c.btnAmdClose.Add_Click({ $w.Close() })
    $w.Add_Closed({ if ($st.X) { Remove-Item $st.X -Recurse -Force -ErrorAction SilentlyContinue } })
    $w.Add_ContentRendered({ try { & $analyze } catch { & $banner "err" "Analiz hatası: $($_.Exception.Message)" } })
    $w.ShowDialog() | Out-Null
}

# ---- ORKESTRATOR ----
# Tum metrikleri sirali calistirir. ProgressCallback varsa her metrik sonu cagirir
# Multi-run median: N kez calistir, her numeric field icin median al + CV hesapla.
# Outlier'a dayanikli (mean'den daha sag - sample arasinda 1 cok kotu run varsa mean bozulur,
# median etkilenmez). Run sayisi UI'dan secilebilir (1/3/5).
function Get-Median {
    param([double[]]$Values)
    if (-not $Values -or $Values.Count -eq 0) { return 0 }
    $sorted = $Values | Sort-Object
    $n = $sorted.Count
    if ($n -eq 1) { return $sorted[0] }
    if ($n % 2 -eq 1) { return $sorted[[int][Math]::Floor($n/2)] }
    return ($sorted[$n/2 - 1] + $sorted[$n/2]) / 2.0
}

function Merge-BenchRuns {
    param([array]$Runs)
    if (-not $Runs -or $Runs.Count -eq 0) { return @{ Ok = $false; Error = "no runs" } }
    if ($Runs.Count -eq 1) { return $Runs[0] }

    $sample = $Runs[0]
    if (-not $sample -or -not $sample.Ok) { return $sample }

    $merged = @{ Ok = $true; _RunCount = $Runs.Count }

    foreach ($key in $sample.Keys) {
        if ($key -eq 'Ok' -or $key -eq '_RunCount') { continue }
        $vals = New-Object System.Collections.Generic.List[double]
        $isNumeric = $false
        foreach ($r in $Runs) {
            if ($r.ContainsKey($key) -and $null -ne $r[$key]) {
                $v = $r[$key]
                if ($v -is [System.ValueType] -and $v -isnot [bool]) {
                    $dv = [double]$v
                    if ($dv -ge 0) { [void]$vals.Add($dv); $isNumeric = $true }
                }
            }
        }
        if ($isNumeric -and $vals.Count -gt 0) {
            $med = Get-Median -Values $vals.ToArray()
            $merged[$key] = [Math]::Round($med, 4)
            # CV (coefficient of variation) = stddev / mean * 100
            if ($vals.Count -ge 2) {
                $avg = ($vals | Measure-Object -Average).Average
                $sumSq = 0.0; foreach ($v in $vals) { $sumSq += ($v - $avg) * ($v - $avg) }
                $stddev = [Math]::Sqrt($sumSq / ($vals.Count - 1))
                $cv = if ($avg -gt 0.001) { [Math]::Round(($stddev / $avg) * 100, 1) } else { 0 }
                $merged["${key}_CV"] = $cv
            }
        } else {
            # Non-numeric field (string), ilk run'dan al
            $merged[$key] = $sample[$key]
        }
    }
    return $merged
}

# (UI'da progress bar + step label icin).
function Get-BenchSnapshot {
    param(
        [scriptblock]$ProgressCallback = $null,
        [string]$Label = "",
        [int]$Runs = 3
    )
    if ($Runs -lt 1) { $Runs = 1 }
    if ($Runs -gt 10) { $Runs = 10 }
    $result = [ordered]@{
        timestamp = (Get-Date -Format "yyyy-MM-ddTHH:mm:ss")
        label     = $Label
        mrCleanVersion = $global:AppVersion
        runCount  = $Runs
        metrics   = [ordered]@{}
    }

    $steps = @(
        @{ Key = "timer";        Label = "Timer / Sleep precision";    Run = { Test-TimerPrecision -Samples 100 } }
        # loopback metrigi v1.2.10 sonu kaldirildi: 127.0.0.1 NIC uzerinden GITMEZ, kernel TCP
        # stack uzerinden gider. NIC offload (RSS/LSO/Checksum) ve TCP NoDelay tweak'leri loopback'i
        # ETKILEMEZ — kullanici yanlislikla iyilesme/kotulesme yorumluyor. Test-LoopbackPing helper
        # ileride TCP stack tweak'leri eklenirse geri eklenir.
        @{ Key = "gateway";      Label = "Gateway ping";               Run = { Test-GatewayPing -Samples 100 } }
        @{ Key = "dns";          Label = "DNS resolve";                Run = { Test-DnsResolve -DomainsPerRun 20 } }
        # disk4k step v1.2.10 sonu kaldirildi — programda disk-perf etkileyen tweak yok,
        # bos zaman harcamayalim. Test-Disk4kRead helper duruyor (ileride disk-related tweak
        # eklenirse anlik geri agirilabilir).
        @{ Key = "processStart"; Label = "Process start latency";      Run = { Test-ProcessStartLatency -Samples 40 } }
        @{ Key = "dpc";          Label = "DPC time (5 sn sample)";     Run = { Test-DpcTime -DurationSec 5 } }
        @{ Key = "system";       Label = "Sistem snapshot";            Run = { Get-SystemSnapshot } }
        # v1.3.0 (13. tur): olcum oturumunda dogrulanan oyun / gecikme metrikleri
        @{ Key = "latency";      Label = "Sistem gecikmesi (uyanma / ani yuk / Sleep)"; Run = { Test-SystemLatency } }
        @{ Key = "gameLoad";     Label = "Oyun yuku (CS2 + BF6 benzeri) + giris gecikmesi"; Run = { Test-GameLoad } }
    )
    if ($global:BenchGpuEnabled) { $steps += @{ Key = "frameTime"; Label = "GPU kare suresi (FurMark + PresentMon, tam ekran)"; Run = { Test-GpuFrameTime } } }
    else { $result.metrics["frameTime"] = @{ Ok = $false; Note = "GPU testi secilmedi" } }

    $i = 0
    $totalSteps = $steps.Count * $Runs
    foreach ($s in $steps) {
        $i++
        $runResults = New-Object System.Collections.Generic.List[hashtable]
        for ($r = 1; $r -le $Runs; $r++) {
            $globalStep = (($i - 1) * $Runs) + $r
            $rLabel = if ($Runs -gt 1) { "$($s.Label) (run $r/$Runs)" } else { $s.Label }
            if ($ProgressCallback) { & $ProgressCallback $globalStep $totalSteps $rLabel }
            try {
                $rr = & $s.Run
            } catch {
                $rr = @{ Ok = $false; Error = $_.Exception.Message }
            }
            [void]$runResults.Add($rr)
        }
        # Median + CV ile birlestir
        $merged = Merge-BenchRuns -Runs @($runResults)
        $result.metrics[$s.Key] = $merged
    }
    if ($ProgressCallback) { & $ProgressCallback $totalSteps $totalSteps "Tamamlandi" }

    return $result
}

# ---- JSON CRUD ----
function Save-BenchSnapshot {
    param([Parameter(Mandatory=$true)]$Snapshot)
    try {
        if (-not (Test-Path $global:BenchDir)) {
            New-Item -ItemType Directory -Path $global:BenchDir -Force | Out-Null
        }
        $ts = (Get-Date -Format "yyyyMMdd_HHmmss")
        $fn = "bench_$ts.json"
        $fp = Join-Path $global:BenchDir $fn
        $Snapshot.fileName = $fn
        $Snapshot | ConvertTo-Json -Depth 6 | Out-File -FilePath $fp -Encoding UTF8 -Force
        return $fp
    } catch {
        WpfLog ("[Bench] Snapshot kaydedilemedi: {0}" -f $_.Exception.Message)
        return $null
    }
}

function Get-BenchSnapshots {
    if (-not (Test-Path $global:BenchDir)) { return @() }
    $list = New-Object System.Collections.Generic.List[object]
    Get-ChildItem $global:BenchDir -Filter "bench_*.json" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | ForEach-Object {
        try {
            $obj = Get-Content $_.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
            $obj | Add-Member -NotePropertyName "_path" -NotePropertyValue $_.FullName -Force
            [void]$list.Add($obj)
        } catch {}
    }
    return $list
}

function Remove-BenchSnapshot {
    param([Parameter(Mandatory=$true)][string]$Path)
    if (Test-Path $Path) {
        try { Remove-Item $Path -Force -ErrorAction Stop; return $true } catch { return $false }
    }
    return $false
}

function Set-BenchSnapshotLabel {
    param([Parameter(Mandatory=$true)][string]$Path,
          [Parameter(Mandatory=$true)][string]$NewLabel)
    if (-not (Test-Path $Path)) { return $false }
    try {
        $obj = Get-Content $Path -Raw -Encoding UTF8 | ConvertFrom-Json
        $obj.label = $NewLabel
        $obj | ConvertTo-Json -Depth 6 | Out-File -FilePath $Path -Encoding UTF8 -Force
        return $true
    } catch { return $false }
}

# ---- METRIK DIFF — lower-is-better / higher-is-better flag tablosu ----
# Compare-BenchSnapshots iki snapshot uretir; her satir: metric, a, b, delta, pctChange, verdict.
# verdict: "better" | "worse" | "neutral" | "n/a"
function Get-BenchMetricCatalog {
    # field: metric path (snapshot.metrics.<group>.<field>), label, unit, direction
    # direction: "lower" = lower-is-better, "higher" = higher-is-better
    return @(
        @{ Group = "timer";        Field = "AvgMs";        Label = "Timer Sleep delta (avg)";    Unit = "ms";        Direction = "lower" }
        @{ Group = "timer";        Field = "StddevMs";     Label = "Timer Sleep delta (stddev)"; Unit = "ms";        Direction = "lower" }
        # loopback satirlari kaldirildi — NIC tweak'lerinden etkilenmez (kernel stack iceri)
        @{ Group = "gateway";      Field = "AvgMs";        Label = "Gateway ping (avg)";         Unit = "ms";        Direction = "lower" }
        @{ Group = "gateway";      Field = "JitterMs";     Label = "Gateway ping (jitter)";      Unit = "ms";        Direction = "lower" }
        @{ Group = "dns";          Field = "AvgMs";        Label = "DNS resolve (avg)";          Unit = "ms";        Direction = "lower" }
        # disk4k satirlari kaldirildi (orkestratorden cikti — disk tweak yok)
        @{ Group = "processStart"; Field = "AvgMs";        Label = "Process start (cmd /c exit)"; Unit = "ms";       Direction = "lower" }
        @{ Group = "dpc";          Field = "AvgPercent";   Label = "DPC time (avg)";              Unit = "%";         Direction = "lower" }
        @{ Group = "dpc";          Field = "PeakPercent";  Label = "DPC time (peak)";             Unit = "%";         Direction = "lower" }
        @{ Group = "system";       Field = "AvailableRamMB"; Label = "Bos RAM";                   Unit = "MB";        Direction = "higher" }
        @{ Group = "system";       Field = "ProcessCount"; Label = "Process sayisi";              Unit = "";          Direction = "lower" }
        @{ Group = "system";       Field = "ServicesRunning"; Label = "Calisan servis sayisi";    Unit = "";          Direction = "lower" }
        @{ Group = "system";       Field = "HandleCount";  Label = "Handle sayisi";               Unit = "";          Direction = "lower" }
        # v1.3.0 (13. tur)
        @{ Group = "latency";      Field = "WakeP99Us";    Label = "Uyanma gecikmesi (p99)";      Unit = "us";        Direction = "lower" }
        @{ Group = "latency";      Field = "BurstP50Us";   Label = "Ani yuk tepkisi (100us is)";  Unit = "us";        Direction = "lower" }
        @{ Group = "latency";      Field = "Sleep1AvgUs";  Label = "Sleep(1) gercek sure";        Unit = "us";        Direction = "lower" }
        @{ Group = "latency";      Field = "FileAttrUs";   Label = "Cekirdek cagrisi (HVCI duyarli)"; Unit = "us";    Direction = "lower" }
        @{ Group = "latency";      Field = "PageFault64KUs"; Label = "Bellek sayfa hatasi 64 KB";  Unit = "us";        Direction = "lower" }
        @{ Group = "gameLoad";     Field = "Cs2Fps";       Label = "CS2 benzeri yuk FPS";         Unit = "fps";       Direction = "higher" }
        @{ Group = "gameLoad";     Field = "Cs2Low1";      Label = "CS2 benzeri yuk 1% low";      Unit = "fps";       Direction = "higher" }
        @{ Group = "gameLoad";     Field = "Bf6Fps";       Label = "BF6 benzeri yuk FPS";         Unit = "fps";       Direction = "higher" }
        @{ Group = "gameLoad";     Field = "Bf6Low1";      Label = "BF6 benzeri yuk 1% low";      Unit = "fps";       Direction = "higher" }
        @{ Group = "gameLoad";     Field = "Stutters";     Label = "Takilma (kare > 2x medyan)";  Unit = "";          Direction = "lower" }
        @{ Group = "gameLoad";     Field = "InputAvgUs";   Label = "Giris gecikmesi (ort)";       Unit = "us";        Direction = "lower" }
        @{ Group = "gameLoad";     Field = "InputP99Us";   Label = "Giris gecikmesi (p99)";       Unit = "us";        Direction = "lower" }
        @{ Group = "frameTime";    Field = "GpuFps";       Label = "GPU FPS (FurMark)";           Unit = "fps";       Direction = "higher" }
        @{ Group = "frameTime";    Field = "GpuLow1";      Label = "GPU 1% low";                  Unit = "fps";       Direction = "higher" }
        @{ Group = "frameTime";    Field = "DisplayLatencyMs"; Label = "Ekrana ulasma gecikmesi"; Unit = "ms";        Direction = "lower" }
    )
}

function Compare-BenchSnapshots {
    param([Parameter(Mandatory=$true)]$SnapshotA, [Parameter(Mandatory=$true)]$SnapshotB)
    $catalog = Get-BenchMetricCatalog
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($c in $catalog) {
        $aVal = $null; $bVal = $null
        try { $aVal = $SnapshotA.metrics.$($c.Group).$($c.Field) } catch {}
        try { $bVal = $SnapshotB.metrics.$($c.Group).$($c.Field) } catch {}
        $aNum = $null; $bNum = $null
        if ($null -ne $aVal -and $aVal -is [System.ValueType]) { $aNum = [double]$aVal }
        elseif ($aVal -match '^-?\d+(\.\d+)?$') { $aNum = [double]$aVal }
        if ($null -ne $bVal -and $bVal -is [System.ValueType]) { $bNum = [double]$bVal }
        elseif ($bVal -match '^-?\d+(\.\d+)?$') { $bNum = [double]$bVal }

        $verdict = "n/a"; $delta = $null; $pct = $null
        if ($null -ne $aNum -and $null -ne $bNum -and $aNum -ge 0 -and $bNum -ge 0) {
            $delta = [Math]::Round($bNum - $aNum, 3)
            if ($aNum -ne 0) { $pct = [Math]::Round((($bNum - $aNum) / $aNum) * 100, 1) } else { $pct = 0 }
            # Noise esigi v1.2.10 sonu %2 -> %5. Modern Windowsta tek bench-arasi tipik varyans %3-7
            # (background process, AV scan, DPC burst). %5 alti farklar artik "neutral" — false
            # positive "iyilesti/kotulesti" yorumlarini engeller.
            $sig = if ([Math]::Abs($pct) -lt 5) { "neutral" } else { if ($delta -gt 0) { "up" } else { "down" } }
            if ($sig -eq "neutral") { $verdict = "neutral" }
            elseif ($c.Direction -eq "lower") { $verdict = if ($sig -eq "down") { "better" } else { "worse" } }
            else                              { $verdict = if ($sig -eq "up")   { "better" } else { "worse" } }
        }

        [void]$rows.Add([PSCustomObject]@{
            Label    = $c.Label
            Unit     = $c.Unit
            AValue   = $aVal
            BValue   = $bVal
            Delta    = $delta
            PctChange = $pct
            Verdict  = $verdict
            Direction = $c.Direction
        })
    }
    return $rows
}

# =========================================================
# QUICK UNDO (Sprint 4.3)
# Son apply'i tersine cevirir: $global:LastTweakOperation kullanilir.
# Apply edilenlerin Undo'sunu, Undo edilenlerin Apply'ini calistirir.
# =========================================================
function Invoke-QuickUndo {
    if (-not $global:LastTweakOperation) {
        [System.Windows.MessageBox]::Show((T 'mbx_noundo'), (T 'mb_info')) | Out-Null
        return
    }
    $op = $global:LastTweakOperation
    $applied = @($op.Applied)
    $undone  = @($op.Undone)
    $total = $applied.Count + $undone.Count
    if ($total -eq 0) { return }

    $msg = "Son tweak islemi tersine cevrilecek:`n`n" +
           "  • $($applied.Count) ayar GERI ALINACAK (Apply edilen → Undo)`n" +
           "  • $($undone.Count) ayar TEKRAR UYGULANACAK (Undo edilen → Apply)`n`n" +
           "Devam edilsin mi?"
    if ([System.Windows.MessageBox]::Show($msg, "Geri Al Onayi", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question) -ne 'Yes') {
        return
    }

    Refresh-PowerCfg-Cache
    WpfLog "--- QUICK UNDO BASLADI ---"

    # Process-TweakItem inline kopyasi (Apply-System-Tweaks icindeki nested fonksiyona disardan erisemiyoruz)
    function Invoke-TweakAction($tweakItem, [bool]$isUndo) {
        $actionName = if ($isUndo) { "Geri Aliniyor" } else { "Yeniden Uygulaniyor" }
        WpfLog "$actionName : $($tweakItem.Name)"
        Do-Events
        $batchList = if ($tweakItem.Batch) { $tweakItem.Batch } else { @($tweakItem) }
        foreach ($sub in $batchList) {
            try {
                if ($isUndo -and $sub.UndoCommand) {
                    Invoke-TweakCommand $sub.UndoCommand
                } elseif (-not $isUndo -and $sub.Command) {
                    Invoke-TweakCommand $sub.Command
                } elseif ($sub.Key) {
                    $targetValue = if ($isUndo) { $sub.Undo } else { $sub.Data }
                    if ($targetValue -eq "DELETE_KEY") {
                        if ($sub.ValueName) {
                            if (Test-Path $sub.Key) { Remove-ItemProperty -Path $sub.Key -Name $sub.ValueName -ErrorAction SilentlyContinue }
                        } else {
                            if (Test-Path $sub.Key) { Remove-Item -Path $sub.Key -Force -Recurse -ErrorAction Stop }
                        }
                    } elseif ($targetValue -eq "DELETE_VALUE") {
                        if (Test-Path $sub.Key) { Remove-ItemProperty -Path $sub.Key -Name $sub.ValueName -ErrorAction SilentlyContinue }
                    } else {
                        if (-not (Test-Path $sub.Key)) {
                            try { New-Item -Path $sub.Key -Force -ErrorAction Stop | Out-Null } catch { continue }
                        }
                        if ([string]::IsNullOrEmpty($sub.ValueName)) {
                            Set-Item -Path $sub.Key -Value $targetValue -Force -ErrorAction Stop
                        } else {
                            Set-ItemProperty -Path $sub.Key -Name $sub.ValueName -Value $targetValue -Type $sub.Type -Force -ErrorAction Stop
                        }
                    }
                }
            } catch {
                WpfLog "❌ [HATA] $actionName ($($tweakItem.Name)): $($_.Exception.Message)"
            }
        }
    }

    # Apply edilenler → Undo, Undone → Apply (TERSINE)
    # v1.3.0 (§93): guc plani once, acik guc ayarlari yeni plana tasinir (Apply ile ayni)
    Invoke-MrCleanPowerPlanFirst $applied $undone { param($tw, $undo) Invoke-TweakAction $tw $undo }
    foreach ($t in $applied) { if ("$($t.Group)" -ne 'PowerPlan') { Invoke-TweakAction $t $true  } }
    foreach ($t in $undone)  { if ("$($t.Group)" -ne 'PowerPlan') { Invoke-TweakAction $t $false } }
    Update-MrCleanAppliedList -Enabled $undone -Disabled $applied

    WpfLog "--- QUICK UNDO TAMAMLANDI ---"
    Write-TweakAuditLog -Operation "QuickUndo" -Applied $undone -Undone $applied

    # v1.3.0 (§98): Uygula'daki gibi Gezgin yenileme (eskiden Hizli Geri Al'da yoktu: Dosya Uzantilari geri alininca
    # masaustu / acik pencereler eski hâlde kaliyordu). Hard: onayla Explorer yeniden baslatma, Soft: yenileme.
    $rx = @(@($applied) + @($undone) | Where-Object { $_ } | ForEach-Object { "$($_.RestartExplorer)" })
    if ($rx -contains 'Hard' -or $rx -contains 'True') {
        try { $Win.Activate() | Out-Null } catch {}
        $msg = "Bu degisiklikler icin Windows Gezgini'nin yeniden baslatilmasi gerekiyor.`n`nAcik Explorer pencereleri kapatilacak (taskbar/desktop yenilenecek).`n`nSimdi yapilsin mi?"
        if ([System.Windows.MessageBox]::Show($Win, $msg, "Explorer Yeniden Baslat", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question) -eq 'Yes') { Invoke-ExplorerHardRestart }
        else { WpfLog "[BILGI] Kullanici yeniden baslatmayi erteledi. Bazi degisiklikler bir sonraki oturum acmada uygulanacak." }
    }
    elseif ($rx -contains 'Soft') { Invoke-ShellSoftRefresh }

    # Geri alindi → tek seferlik kullanilir, simdi temizle
    $global:LastTweakOperation = $null
    if ($btnQuickUndo) { $btnQuickUndo.IsEnabled = $false }

    # Cache'i invalidate et + UI'yi yenile
    $global:TweakStatusCache = @{}
    try {
        $cachePath = Get-TweakStatusCachePath
        if ($cachePath -and (Test-Path $cachePath)) { Remove-Item $cachePath -Force -ErrorAction SilentlyContinue }
    } catch {}
    Check-Tweak-Status -ForceRefresh
}

# =========================================================
# v1.3.0 (6. tur): GUNCELLEME SONRASI AYAR DENETIMI
# Windows guncellemesi (build/UBR), ekran karti surucusu veya ag karti surucusu degisince (ya da son denetimden 7 gun
# gecince) program acilisinda, kullanicinin UYGULADIGI tweak'ler arka planda parca parca (UI donmadan) yeniden tespit
# edilir. Varsayilana donmus olanlar listelenir; kullanici onaylarsa Tweaks sekmesinde isaretlenir, "Uygula" ile geri gelir.
# =========================================================
function Get-MrCleanEnvFingerprint {
    $gpu = ""; $nic = ""
    try { $gpu = (@(Get-CimInstance Win32_VideoController -ErrorAction Stop | Where-Object { "$($_.Name)" -notmatch "(?i)Basic Display|Temel G|Remote|Virtual|Parsec" } | ForEach-Object { "$($_.Name)=$($_.DriverVersion)" }) | Sort-Object) -join ";" } catch {}
    try { $nic = (@(Get-MrCleanPhysicalAdapters | ForEach-Object { "$($_.InterfaceDescription)=$($_.DriverVersion)" }) | Sort-Object) -join ";" } catch {}
    return @{ Win = "$($global:WinBuild).$($global:WinUBR)"; Gpu = $gpu; Nic = $nic }
}

# Uygulanan tweak listesini gunceller (Apply / Quick Undo sonrasi).
function Update-MrCleanAppliedList($Enabled, $Disabled) {
    try {
        $root = "HKCU:\Software\MrClean"
        if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }
        $cur = New-Object System.Collections.Generic.List[string]
        foreach ($n in @((Get-ItemProperty -Path $root -Name "AppliedTweaks" -ErrorAction SilentlyContinue).AppliedTweaks)) { if ($n -and -not $cur.Contains("$n")) { $cur.Add("$n") } }
        foreach ($t in @($Disabled)) { if ($t -and $t.Name) { [void]$cur.Remove("$($t.Name)") } }
        foreach ($t in @($Enabled))  { if ($t -and $t.Name -and -not $cur.Contains("$($t.Name)")) { $cur.Add("$($t.Name)") } }
        Set-ItemProperty -Path $root -Name "AppliedTweaks" -Value ([string[]]@($cur)) -Type MultiString -Force
    } catch {}
}

# =========================================================
# v1.3.0 (8. tur): TEK SEFERLIK YONETICI IZNI — "Onay sormadan baslat"
# MrClean her zaman yonetici olarak calisir (servis, kayit, EAPO, gorevler icin sart). Kullanici BIR KEZ izin verirse:
#  - program Program Files\MrClean altina kopyalanir (yalnizca yonetici yazabilir -> kotu amacli bir surecin dosyayi
#    degistirip sessizce yonetici yetkisi almasi engellenir)
#  - "MrClean (Yonetici Baslatici)" gorevi (en yuksek yetki, isteğe bagli calisir, normal oncelik) + Masaustu / Baslat kisayolu
#    (schtasks /run) -> sonraki acilislarda UAC sorulmaz
#  - klasordeki dosya yenilenirse (guncelleme) ilk yonetici acilisinda kopya da yenilenir
# Ayarlar > "Onay sormadan baslat" ile kapatilir (gorev, kisayollar ve kopya kaldirilir).
# =========================================================
function Get-MrCleanAdminLauncherState {
    $on = $false
    try { $on = ((Get-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AdminLauncher" -ErrorAction SilentlyContinue).AdminLauncher -eq 1) } catch {}
    $task = $null; try { $task = Get-ScheduledTask -TaskName $global:MrCleanElevTask -ErrorAction SilentlyContinue } catch {}
    return [pscustomobject]@{ Enabled = ($on -and [bool]$task); Task = [bool]$task }
}

function Enable-MrCleanAdminLauncher {
    $self = $global:MrCleanSelfPath
    if (-not $self -or -not (Test-Path $self)) { WpfLog "[Baslatici] Program dosyasi bulunamadi."; return $false }
    try {
        $dir = Join-Path $env:ProgramFiles "MrClean"
        if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $dst = Join-Path $dir ([IO.Path]::GetFileName($self))
        if ($self -ne $dst) { Copy-Item -Path $self -Destination $dst -Force }
        $ico = Join-Path (Split-Path -Parent $self) "mrclean.ico"
        if ((Test-Path $ico) -and ($ico -ne (Join-Path $dir "mrclean.ico"))) { Copy-Item $ico (Join-Path $dir "mrclean.ico") -Force }
        $isExe = $dst -like "*.exe"
        $action = if ($isExe) { New-ScheduledTaskAction -Execute $dst -WorkingDirectory $dir }
                  else { New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$dst`"" -WorkingDirectory $dir }
        $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Hours 0) -MultipleInstances IgnoreNew -Priority 4
        $principal = New-ScheduledTaskPrincipal -UserId "$env:USERDOMAIN\$env:USERNAME" -LogonType Interactive -RunLevel Highest
        # -ErrorAction Stop: gorev kaydi hata verirse (orn. yetki) catch e duser; kisayol olusturulmaz, "etkin" denmez
        Register-ScheduledTask -TaskName $global:MrCleanElevTask -Action $action -Settings $settings -Principal $principal -Description "MrClean'i UAC sormadan yonetici olarak baslatir (kullanici izniyle; Ayarlar'dan kapatilir)." -Force -ErrorAction Stop | Out-Null
        if (-not (Get-ScheduledTask -TaskName $global:MrCleanElevTask -ErrorAction SilentlyContinue)) { throw "gorev olusturulamadi" }
        $sh = New-Object -ComObject WScript.Shell
        $iconSrc = if (Test-Path (Join-Path $dir "mrclean.ico")) { Join-Path $dir "mrclean.ico" } elseif ($isExe) { $dst } else { "$env:SystemRoot\System32\shell32.dll,21" }
        foreach ($lnkDir in @([Environment]::GetFolderPath("Desktop"), (Join-Path ([Environment]::GetFolderPath("Programs")) ""))) {
            if (-not $lnkDir) { continue }
            $l = $sh.CreateShortcut((Join-Path $lnkDir "MrClean.lnk"))
            $l.TargetPath = Join-Path $env:SystemRoot "System32\schtasks.exe"
            $l.Arguments = "/run /tn `"$($global:MrCleanElevTask)`""
            $l.WindowStyle = 7; $l.IconLocation = $iconSrc; $l.Description = "MrClean (onay sormadan)"
            $l.Save()
        }
        if (-not (Test-Path "HKCU:\Software\MrClean")) { New-Item -Path "HKCU:\Software\MrClean" -Force | Out-Null }
        Set-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AdminLauncher" -Value 1 -Type DWord -Force
        Set-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AdminLauncherAsked" -Value 1 -Type DWord -Force
        WpfLog "[Baslatici] Etkin: Masaustu / Baslat menusundeki 'MrClean' kisayolu artik UAC sormadan acar (kopya: $dst)."
        return $true
    } catch { WpfLog "[Baslatici] Etkinlestirilemedi: $($_.Exception.Message)"; return $false }
}

function Disable-MrCleanAdminLauncher {
    try { Unregister-ScheduledTask -TaskName $global:MrCleanElevTask -Confirm:$false -ErrorAction SilentlyContinue } catch {}
    foreach ($lnkDir in @([Environment]::GetFolderPath("Desktop"), [Environment]::GetFolderPath("Programs"))) {
        $p = Join-Path $lnkDir "MrClean.lnk"
        try { if ((Test-Path $p) -and ((New-Object -ComObject WScript.Shell).CreateShortcut($p).Arguments -like "*$($global:MrCleanElevTask)*")) { Remove-Item $p -Force } } catch {}
    }
    $dir = Join-Path $env:ProgramFiles "MrClean"
    if ((Test-Path $dir) -and $global:MrCleanSelfPath -notlike "$dir\*") { Remove-Item $dir -Recurse -Force -ErrorAction SilentlyContinue }
    Set-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AdminLauncher" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
    WpfLog "[Baslatici] Kapatildi: MrClean yine her acilista UAC onayi ister."
}

# Yonetici olarak acilista: baslatici etkinse ve calisan dosya kopyadan farkliysa (yeni surum) kopyayi yeniler
function Update-MrCleanAdminLauncherCopy {
    try {
        if (-not (Get-MrCleanAdminLauncherState).Enabled) { return }
        $self = $global:MrCleanSelfPath; $dir = Join-Path $env:ProgramFiles "MrClean"
        if (-not $self -or $self -like "$dir\*") { return }
        $dst = Join-Path $dir ([IO.Path]::GetFileName($self))
        if (-not (Test-Path $dst) -or (Get-FileHash $dst -Algorithm SHA256).Hash -ne (Get-FileHash $self -Algorithm SHA256).Hash) {
            Copy-Item -Path $self -Destination $dst -Force
            WpfLog "[Baslatici] Yonetici kopyasi guncellendi (yeni surum)."
        }
    } catch {}
}

# Ilk yonetici acilisinda BIR KEZ sorar
function Request-MrCleanAdminLauncherOnce {
    try {
        $asked = (Get-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AdminLauncherAsked" -ErrorAction SilentlyContinue).AdminLauncherAsked
        if ($asked -eq 1) { return }
        if (-not (Test-Path "HKCU:\Software\MrClean")) { New-Item -Path "HKCU:\Software\MrClean" -Force | Out-Null }
        Set-ItemProperty -Path "HKCU:\Software\MrClean" -Name "AdminLauncherAsked" -Value 1 -Type DWord -Force
        $msg = "MrClean; servis, kayıt defteri, ses (Equalizer APO) ve zamanlanmış görev ayarları için her zaman YÖNETİCİ yetkisiyle çalışır — bu yüzden Windows her açılışta onay (UAC) soruyor.`n`n" +
               "Bir kez izin verirseniz: Masaüstü ve Başlat menüsündeki 'MrClean' kısayolu bundan sonra ONAY SORMADAN açılır; ayarların yetki yüzünden yarım kalması diye bir durum olmaz.`n`n" +
               "Güvenlik: yetkili kopya 'C:\Program Files\MrClean' içinde tutulur (yalnızca yönetici değiştirebilir). Ayarlar'dan istediğiniz an kapatabilirsiniz.`n`nEtkinleştirilsin mi?"
        if ([System.Windows.MessageBox]::Show($msg, "MrClean — Tek Seferlik İzin", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question) -eq "Yes") { [void](Enable-MrCleanAdminLauncher) }
    } catch {}
}

function Start-MrCleanDriftCheck {
    try {
        $root = "HKCU:\Software\MrClean"
        if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }
        $old = Get-ItemProperty -Path $root -ErrorAction SilentlyContinue
        $fp = Get-MrCleanEnvFingerprint
        $applied = @(@($old.AppliedTweaks) | Where-Object { $_ })
        $saveFp = {
            Set-ItemProperty -Path $root -Name "EnvWin" -Value $fp.Win -Type String -Force
            Set-ItemProperty -Path $root -Name "EnvGpu" -Value $fp.Gpu -Type String -Force
            Set-ItemProperty -Path $root -Name "EnvNic" -Value $fp.Nic -Type String -Force
            Set-ItemProperty -Path $root -Name "EnvCheckedAt" -Value ((Get-Date).ToString("o")) -Type String -Force
        }
        # Ilk calisma: uygulanan liste yoksa son taramanin "aktif" sonuclarindan tohumla; bu sefer denetleme yapma
        if (-not $old.EnvWin) {
            if ($applied.Count -eq 0) {
                try {
                    $cp = Get-TweakStatusCachePath
                    if ($cp -and (Test-Path $cp)) {
                        $raw = Get-Content $cp -Raw | ConvertFrom-Json
                        $seed = @($raw.results.PSObject.Properties | Where-Object { $_.Value -eq $true } | ForEach-Object { $_.Name })
                        if ($seed.Count -gt 0) { Set-ItemProperty -Path $root -Name "AppliedTweaks" -Value ([string[]]$seed) -Type MultiString -Force }
                    }
                } catch {}
            }
            & $saveFp
            return
        }
        $changes = New-Object System.Collections.Generic.List[string]
        if ("$($old.EnvWin)" -ne $fp.Win) { $changes.Add("Windows güncellemesi ($($old.EnvWin) → $($fp.Win))") }
        if ("$($old.EnvGpu)" -ne $fp.Gpu) { $changes.Add("ekran kartı sürücüsü güncellemesi") }
        if ("$($old.EnvNic)" -ne $fp.Nic) { $changes.Add("ağ kartı sürücüsü güncellemesi") }
        $stale = $true
        try { $stale = ((Get-Date) - [datetime]$old.EnvCheckedAt).TotalDays -ge 7 } catch {}
        & $saveFp
        if ($applied.Count -eq 0 -or ($changes.Count -eq 0 -and -not $stale)) { return }
        if ($changes.Count -eq 0) { $changes.Add("haftalık denetim") }

        $byName = @{}
        foreach ($c in $global:TweakList.Keys) { foreach ($t in $global:TweakList[$c]) { $byName["$($t.Name)"] = $t } }
        $queue = @($applied | Where-Object { $byName.ContainsKey("$_") } | ForEach-Object { $byName["$_"] } | Where-Object { Test-TweakBuildCompatible $_ })
        if ($queue.Count -eq 0) { return }
        try { Refresh-PowerCfg-Cache; Refresh-BcdEdit-Cache; Refresh-NetshTcp-Cache } catch {}
        $script:DriftQueue = $queue; $script:DriftIdx = 0; $script:DriftChanges = @($changes)
        $script:DriftReverted = New-Object System.Collections.Generic.List[string]
        WpfLog "[Denetim] $($changes -join ", ") algilandi — uyguladiginiz $($queue.Count) ayar kontrol ediliyor (arka planda)..."
        $script:DriftTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:DriftTimer.Interval = [TimeSpan]::FromMilliseconds(40)
        $script:DriftTimer.Add_Tick({
            $end = [Math]::Min($script:DriftIdx + 4, $script:DriftQueue.Count)
            for ($i = $script:DriftIdx; $i -lt $end; $i++) {
                $t = $script:DriftQueue[$i]
                try { if (-not (Test-TweakApplied $t)) { $script:DriftReverted.Add("$($t.Name)") } } catch {}
            }
            $script:DriftIdx = $end
            if ($script:DriftIdx -lt $script:DriftQueue.Count) { return }
            $script:DriftTimer.Stop()
            $rev = @($script:DriftReverted)
            if ($rev.Count -eq 0) { WpfLog "[Denetim] $($script:DriftChanges -join ", ") sonrasi ayarlariniz yerinde ($($script:DriftQueue.Count) kontrol edildi)."; return }
            WpfLog "[Denetim] $($rev.Count) ayar varsayilana donmus: $($rev -join " | ")"
            $list = ($rev | Select-Object -First 15 | ForEach-Object { "  • $_" }) -join "`n"
            if ($rev.Count -gt 15) { $list += "`n  … +$($rev.Count - 15)" }
            $msg = "$($script:DriftChanges -join ", ") algilandi. Uyguladiginiz $($rev.Count) ayar su an uygulanmis gorunmuyor (sebep guncelleme, sizin degisikliginiz ya da MrClean'in yeni surumundeki daha siki kontrol olabilir):`n`n$list`n`nTweaks sekmesinde isaretlensin mi? (Kontrol edip UYGULA ya basarak geri getirirsiniz.)"
            $r = [System.Windows.MessageBox]::Show($msg, "Güncelleme Sonrası Denetim", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Information)
            if ($r -eq 'Yes') {
                $script:PendingReapply = $rev
                try { $tabTweaks.IsSelected = $true } catch {}
                if ($global:TweaksLoaded -and -not ($script:TweakScanTimer -and $script:TweakScanTimer.IsEnabled)) { Set-MrCleanPendingReapply }
            }
        })
        $script:DriftTimer.Start()
    } catch { try { WpfLog "[Denetim] Hata: $($_.Exception.Message)" } catch {} }
}

# Bekleyen "yeniden uygula" listesindeki tweak'leri agacta isaretler (tarama bittikten sonra cagrilir).
function Set-MrCleanPendingReapply {
    $names = @($script:PendingReapply)
    $script:PendingReapply = $null
    if ($names.Count -eq 0) { $names = @($script:ReapplySticky) }   # 14. tur: sonraki taramalarda isaretler korunur
    if ($names.Count -eq 0) { return }
    $script:ReapplySticky = $names
    $n = 0
    foreach ($it in (Get-AllTweakItems)) {
        if ($names -contains "$($it.Tag.Name)") { $c = Get-CheckFromItem $it; if ($c -and $c.IsEnabled) { $c.IsChecked = $true; $n++ } }
    }
    try { Update-Parent-Headers-Recursive $tvTweaks.Items } catch {}
    WpfLog "[Denetim] $n ayar isaretlendi — UYGULA ile geri getirin."
}

# =========================================================
# TWEAK STATUS CACHE — ASYNC CHUNKED SCAN
# - Cache dosyasi: %APPDATA%\MrClean\tweak_status_cache.json
# - TTL: 30 dakika
# - Anahtar formati: tweak.Name (cogu unique)
# - Chunked scan: her DispatcherTimer tick'inde 10 tweak isle, UI nefes alsin
# =========================================================
$global:TweakStatusCachePath = $null  # Load-All-Settings'ten sonra set edilir
$global:TweakStatusCacheTTL  = [TimeSpan]::FromMinutes(30)
$global:TweakStatusCache     = @{}
$script:TweakScanTimer       = $null

function Get-TweakStatusCachePath {
    if ($global:TweakStatusCachePath) { return $global:TweakStatusCachePath }
    if ($AppDataPath) { return (Join-Path $CacheDir "tweak_status_cache.json") }
    return $null
}

function Load-TweakStatusCache {
    # Donus: hashtable (string→bool) veya $null (yok/expired/bozuk)
    $path = Get-TweakStatusCachePath
    if (-not $path -or -not (Test-Path $path)) { return $null }
    try {
        $raw = Get-Content $path -Raw -ErrorAction Stop | ConvertFrom-Json
        if (-not $raw -or -not $raw._timestamp) { return $null }
        $ts = [datetime]$raw._timestamp
        if ((Get-Date) - $ts -gt $global:TweakStatusCacheTTL) { return $null }
        $result = @{}
        if ($raw.results) {
            foreach ($prop in $raw.results.PSObject.Properties) {
                $result[$prop.Name] = [bool]$prop.Value
            }
        }
        return $result
    } catch { return $null }
}

function Save-TweakStatusCache($cacheMap) {
    $path = Get-TweakStatusCachePath
    if (-not $path) { return }
    try {
        $data = [ordered]@{
            _timestamp = (Get-Date).ToString("o")
            results    = $cacheMap
        }
        $data | ConvertTo-Json -Depth 4 | Set-Content $path -Encoding UTF8 -ErrorAction SilentlyContinue
    } catch {}
}

# Tweak agacindaki tum item'lari (sadece tweak olanlari) duz listeye topla
function Get-AllTweakItems {
    $list = New-Object System.Collections.ArrayList
    function Collect($nodes) {
        foreach ($item in $nodes) {
            if (($item.Tag -is [System.Collections.IDictionary] -or
                 $item.Tag -is [System.Management.Automation.PSCustomObject]) -and
                $item.Tag.Name) {
                [void]$list.Add($item)
            }
            if ($item.Items.Count -gt 0) { Collect $item.Items }
        }
    }
    Collect $tvTweaks.Items
    return $list
}

# Tek tweak icin "uygulanmis mi" hesapla (batch kontrolu dahil)
# =========================================================
# v1.3.0 (12. tur): EMEKLI TWEAKLER — olcum / kaynak arastirmasi sonucu etkisiz (ya da zararli) bulundu, menuden kaldirildi.
# Tanimlar AYNEN burada (tespit + geri alma kodu degismedi). Program bu surumle ilk acildiginda bunlardan UYGULANMIS olanlar
# bir kez Windows varsayilanina dondurulur (Invoke-RetiredTweakCleanup). Gerekce: ARASTIRILACAKLAR.md (12. tur).
# =========================================================
function Get-RetiredTweakDefs {
    return @(
        @{
                Name="Fullscreen Optimizations (FSO) Kapat";
                Description="DirectX 9/10/11 oyunlarda Windows'un 'tam ekran optimizasyonları' katmanını global olarak kapatır — oyun 'tam ekran' seçildiğinde gerçek exclusive fullscreen kullanılır.`n`nℹ️ Dürüst not: DirectX 12 ve Vulkan oyunları bu ayardan ETKİLENMEZ (exclusive fullscreen yoktur). Win11'de modern flip-model ile FSO çoğu oyunda exclusive ile aynı gecikmeyi verir; fark eski DX9/DX11 oyunlarda ve bazı sistemlerde ölçülür.`n`n⚠️ Exclusive fullscreen'de: Alt+Tab yavaşlar, bazı ekran görüntüsü araçları (PrtSc / Ekran Alıntısı) siyah kare yakalayabilir, bildirim/overlay pencereleri oyunu küçültebilir. Bunlar sizi rahatsız ederse geri alın — Discord overlay her iki modda da çalışır.`n`n✅ v1.3.0: Eksik olan asıl anahtar (GameDVR_FSEBehaviorMode=2) eklendi; önceki sürüm global kapatmayı tam yapmıyordu.";
                Risk="Low"; RestartExplorer=$false;
                Batch=@(
                    @{ Key="HKCU:\System\GameConfigStore"; ValueName="GameDVR_FSEBehaviorMode"; Type="DWord"; Data=2; Undo=0 },
                    @{ Key="HKCU:\System\GameConfigStore"; ValueName="GameDVR_FSEBehavior"; Type="DWord"; Data=2; Undo=0 },
                    @{ Key="HKCU:\System\GameConfigStore"; ValueName="GameDVR_HonorUserFSEBehaviorMode"; Type="DWord"; Data=1; Undo=0 },
                    @{ Key="HKCU:\System\GameConfigStore"; ValueName="GameDVR_DXGIHonorFSEWindowsCompatible"; Type="DWord"; Data=1; Undo=0 }
                )
            },
        @{
                Name="Memory Compression Kapat (RAM-aware)";
                Description="Windows'un boş RAM'i sıkıştırma mekanizmasını kapatır. 16GB+ RAM'de CPU yükü azalır (compression yok), bellek erişimi daha hızlı.`n`n🧠 RAM-aware (v1.2.10): Apply edilirken sistem RAM'i otomatik tespit edilir:`n  • 16GB+ → direkt uygulanır`n  • 8-16GB → onay sorusu gelir (RAM marjinal)`n  • <8GB → uygulanmaz, hata mesajı verir (swap'a düşer, sistem yavaşlar)`n`nDetectScript Get-MMAgent ile gerçek state okur (registry değil).";
                Command='
                    # RAM-aware kontrol: 16GB+ direkt, 8-16GB onay, <8GB iptal
                    try {
                        $totalGB = [Math]::Round(((Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop | Measure-Object -Property Capacity -Sum).Sum / 1GB), 0)
                    } catch {
                        # WMI hata verirse, alternatif: ComputerInfo
                        try {
                            $totalGB = [Math]::Round((Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).TotalPhysicalMemory / 1GB, 0)
                        } catch { $totalGB = 0 }
                    }

                    if ($totalGB -ge 16) {
                        Disable-MMAgent -MemoryCompression -ErrorAction SilentlyContinue
                        Write-Host "[MemCompression] Disabled — sistem RAM $totalGB GB (16GB+ guvenli)."
                    } elseif ($totalGB -ge 8) {
                        # Marjinal — kullaniciya soral
                        $msg = "Sistem RAM: $totalGB GB (16GB altinda).`n`nMemory Compression kapatmak bu durumda riskli olabilir — RAM yetersiz kalip swap dosyasina dusebilir, sistem yavaslar.`n`nYine de uygulamak istiyor musun?"
                        $resp = [System.Windows.MessageBox]::Show($msg, "Memory Compression — RAM Uyarisi", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
                        if ($resp -eq "Yes") {
                            Disable-MMAgent -MemoryCompression -ErrorAction SilentlyContinue
                            Write-Host "[MemCompression] Disabled — kullanici onayi ile ($totalGB GB RAM)."
                        } else {
                            Write-Host "[MemCompression] Atlandi — kullanici iptal etti ($totalGB GB RAM)."
                        }
                    } else {
                        # 8GB altinda risk yuksek
                        [System.Windows.MessageBox]::Show("Sistem RAM cok dusuk: $totalGB GB.`n`nMemory Compression bu durumda kapatilamaz — RAM yetersiz kalir, sistem ciddi yavaslar.`n`nTweak atlandi.", "Memory Compression — Iptal", "OK", "Error") | Out-Null
                        Write-Host "[MemCompression] IPTAL — RAM $totalGB GB (<8GB)."
                    }
                ';
                UndoCommand="Enable-MMAgent -MemoryCompression";
                # Detection: Get-MMAgent state'ten oku — registry tabanlı bir tweak değil
                DetectScript="(Get-MMAgent -ErrorAction SilentlyContinue).MemoryCompression -eq `$false";
                Risk="Medium"; RestartExplorer=$false
            },
        @{
                Name="Remote Desktop Connection (mstsc) Kaldır";
                Description="Klasik Uzak Masaustu Baglantisi (mstsc) uygulamasini kaldirir. Win10'da `mstsc /Uninstall` komutuyla program kaldirilir. Win11'de mstsc.exe sistem bileseni oldugu icin /Uninstall etkisiz olabilir — v1.3.0 (12. tur): bu durumda tweak artik DURUSTCE pasif kalir (eskiden yine de 'uygulandi' gorunuyordu). Eski not: tweak marker olarak Apply edildigini kaydeder.";
                Risk="Low"; RestartExplorer=$false;
                DetectScript='
                    # 12. tur (birlestirme): "yok != yesil" — mstsc.exe GERCEKTEN yok VE bu tweak uygulandi. Eskiden isaret tek basina
                    # yesil yakiyordu: Win11 kaldirmaya izin vermese de "uygulandi" gorunuyordu.
                    if (Test-Path "$env:SystemRoot\System32\mstsc.exe") { return $false }
                    $m = (Get-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "RdcUninstall" -ErrorAction SilentlyContinue).RdcUninstall
                    return ("$m" -eq "1")
                ';
                Command='
                    if (Test-Path "$env:SystemRoot\System32\mstsc.exe") {
                        Write-Host "[mstsc] Uninstall baslatiliyor..."
                        try { Start-Process "mstsc" -ArgumentList "/Uninstall" -ErrorAction SilentlyContinue } catch { }
                        $running = $true; $timeout = 0
                        while ($running) {
                            $p = Get-Process -Name mstsc -ErrorAction SilentlyContinue
                            if ($p -and $p.MainWindowHandle -ne 0) {
                                Stop-Process -Force -Name mstsc -ErrorAction SilentlyContinue | Out-Null
                                $running = $false
                            }
                            Start-Sleep -Milliseconds 100
                            $timeout++
                            if ($timeout -gt 100) { Stop-Process -Name mstsc -Force -ErrorAction SilentlyContinue; $running = $false }
                        }
                        Start-Sleep -Milliseconds 500
                        if (Test-Path "$env:SystemRoot\System32\mstsc.exe") { Write-Host "[mstsc] Windows bu surumde kaldirmaya izin vermedi (sistem bileseni) — tweak pasif kalir. Ayarlar > Uygulamalar listesinde Uzak Masaustu Baglantisi varsa oradan kaldirilabilir." }
                        else { Write-Host "[mstsc] Kaldirildi." }
                    } else {
                        Write-Host "[mstsc] Yuklu degil — atlandi."
                    }
                    # Marker — Win11 sistem bileseni olarak kaldirilmasa bile kullanici tweak uyguladigini bilsin
                    if (-not (Test-Path "HKCU:\Software\MrClean\AppliedMarkers")) {
                        New-Item -Path "HKCU:\Software\MrClean\AppliedMarkers" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "RdcUninstall" -Value 1 -Type DWord -Force
                ';
                UndoCommand='
                    Remove-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "RdcUninstall" -Force -ErrorAction SilentlyContinue
                    Write-Host "[mstsc] Marker silindi. NOT: mstsc.exe Win11 sistem bileseni olarak otomatik geri yuklenmiyor — gerekirse manuel olarak winget/Optional Features ile yukleyin."
                '
            },
        @{
                Name="Eski Snipping Tool (Win10) Kaldır";
                Description="Klasik Win10 Ekran Alintisi aracini (SnippingTool.exe) kaldirir. Win11 modern Snipping Tool etkilenmez. Win11'de eski araç zaten yok olabilir — marker ile Apply edildigi kaydedilir.";
                Risk="Low"; RestartExplorer=$false;
                DetectScript='
                    # 12. tur: "yok != yesil" — eski arac GERCEKTEN yok VE bu tweak uygulandi (Win11 de stokta yok diye yesil olmaz)
                    if (Test-Path "$env:SystemRoot\System32\SnippingTool.exe") { return $false }
                    $m = (Get-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "OldSnippingUninstall" -ErrorAction SilentlyContinue).OldSnippingUninstall
                    return ("$m" -eq "1")
                ';
                Command='
                    if (Test-Path "$env:SystemRoot\System32\SnippingTool.exe") {
                        Write-Host "[SnippingTool] Uninstall baslatiliyor..."
                        try { Start-Process "$env:SystemRoot\System32\SnippingTool.exe" -ArgumentList "/Uninstall" -ErrorAction SilentlyContinue } catch { }
                        $running = $true; $timeout = 0
                        while ($running) {
                            $p = Get-Process -Name SnippingTool -ErrorAction SilentlyContinue
                            if ($p -and $p.MainWindowHandle -ne 0) {
                                Stop-Process -Force -Name SnippingTool -ErrorAction SilentlyContinue | Out-Null
                                $running = $false
                            }
                            Start-Sleep -Milliseconds 100
                            $timeout++
                            if ($timeout -gt 100) { Stop-Process -Name SnippingTool -Force -ErrorAction SilentlyContinue; $running = $false }
                        }
                        Start-Sleep -Milliseconds 500
                        if (Test-Path "$env:SystemRoot\System32\SnippingTool.exe") { Write-Host "[SnippingTool] Windows kaldirmaya izin vermedi — tweak pasif kalir." }
                        else { Write-Host "[SnippingTool] Kaldirildi." }
                    } else {
                        Write-Host "[SnippingTool] Yuklu degil — atlandi."
                    }
                    if (-not (Test-Path "HKCU:\Software\MrClean\AppliedMarkers")) {
                        New-Item -Path "HKCU:\Software\MrClean\AppliedMarkers" -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    Set-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "OldSnippingUninstall" -Value 1 -Type DWord -Force
                ';
                UndoCommand='
                    Remove-ItemProperty -Path "HKCU:\Software\MrClean\AppliedMarkers" -Name "OldSnippingUninstall" -Force -ErrorAction SilentlyContinue
                    Write-Host "[SnippingTool] Marker silindi."
                '
            },
        @{ 
                Name="Win32 Öncelik Ayırma (CPU Oyuna Odaklanır)"; 
                SubCategory="Giriş ve İşlemci";
				Description="Windows iş parçacığı zamanlayıcısının 'quantum' (CPU dilimi) davranışını değiştirir. Değer: 26 (0x1A) = UZUN ve SABİT quantum.`n`n• Sabit quantum: oyun ve arka plan iş parçacıkları eşit uzunlukta CPU dilimi alır; bağlam değişimi azalır, frame time daha tutarlı olabilir (FPS kararlılığı).`n• Windows varsayılanı (2) masaüstünde 'kısa + değişken + ön plana 3 kat' davranışıdır (0x26 ile aynı).`n`nℹ️ Dürüst not (v1.3.0): Önceki açıklama '26 = kısa, değişken, ön plana odaklanır' ve 'anti-cheat 38'i işaretler' diyordu — ikisi de doğru değildi. Etki sisteme ve oyuna göre küçüktür; Blur Busters topluluğunda 0x1A/0x18 (sabit) ve 0x26/0x2A (kısa) arasında net bir kazanan yoktur. Takılma hissederseniz geri alın (varsayılan 2).";
                # 0x1A = 01 10 10 → bit5-4: 01 uzun quantum | bit3-2: 10 sabit | bit1-0: 10 (sabitte on plan carpani uygulanmaz)
                # 2 = Windows istemci varsayilani (kisa + degisken + 3:1 on plan = 0x26 esdegeri)
                Key="HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl"; ValueName="Win32PrioritySeparation"; Type="DWord"; Data=26; Undo=2; RestartExplorer=$false 
            },
        @{
                Name="Mouse Sürücü Önceliği (Thread Priority: High)";
                SubCategory="Giriş ve İşlemci";
                Description="Fare sınıf sürücüsünün (mouclass) iş parçacığı önceliğini yükseltir (ThreadPriority=26).`n`nℹ️ Dürüst not (v1.3.0): Bu değer Microsoft tarafından belgelenmemiştir ve gecikmeye etkisi bağımsız ölçümlerle kanıtlanmamıştır (topluluk ölçümlerinde fark ölçüm hatası sınırında). Zararsızdır; isteyen uygular. Önceki açıklamadaki anti-cheat yüzdeleri kaynaksızdı, kaldırıldı.`n⚠️ 31 (gerçek zamanlı) gibi daha yüksek değerler kullanılmaz — sistem iş parçacıklarını aç bırakabilir.";
                # GÜVENLİ DEĞER: 26 = Yüksek öncelik, anti-cheat uyumlu.
                # 31 (REAL-TIME/MAX) kullanılmaz — BattlEye bu değeri izleyebilir.
                Key="HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters"; ValueName="ThreadPriority"; Type="DWord"; Data=26; Undo="DELETE_VALUE"; RestartExplorer=$false
            },
        @{
                Name="Mouse Data Queue Size (Tamponu Artır)";
                Description="Fare olay kuyruğunu 256'ya çıkarır (varsayılan 100). Kuyruk, sistem anlık meşgulken gelen fare olaylarını tutan TAMPONDUR — büyütmek gecikmeyi azaltmaz, sadece 4000/8000 Hz fareler ağır yük altındayken olay düşmesine karşı pay bırakır.`n`nℹ️ v1.3.0 not: İnternette dolaşan 'kuyruğu KÜÇÜLT (14-20), gecikme azalır' önerisi kanıtsızdır ve çok küçük değerler hızlı hareketlerde olay kaybına yol açabilir; bu yüzden uygulanmaz. Anti-cheat uyumlu.";
                SubCategory="Giriş ve İşlemci";
                Key="HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters"; ValueName="MouseDataQueueSize"; Type="DWord"; Data=256; Undo=100; RestartExplorer=$false
            },
        @{
                Name="Keyboard Sürücü Önceliği (Thread Priority: High)";
                Description="Klavye sınıf sürücüsünün (kbdclass) iş parçacığı önceliğini yükseltir (ThreadPriority=26).`n`nℹ️ Dürüst not (v1.3.0): Belgelenmemiş bir değerdir; gecikmeye etkisi bağımsız ölçümlerle kanıtlanmamıştır. Zararsızdır. Önceki açıklamadaki anti-cheat yüzdeleri kaynaksızdı, kaldırıldı.";
                SubCategory="Giriş ve İşlemci";
                # GÜVENLİ DEĞER: 26 = Yüksek öncelik, anti-cheat uyumlu.
                Key="HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters"; ValueName="ThreadPriority"; Type="DWord"; Data=26; Undo="DELETE_VALUE"; RestartExplorer=$false
            },
        @{
                Name="Keyboard Data Queue Size (Tamponu Artır)";
                Description="Klavye olay kuyruğunu 256'ya çıkarır (varsayılan 100). Kuyruk bir TAMPONDUR: gecikmeyi azaltmaz, sistem meşgulken çok hızlı/çoklu tuş basışlarında (makro, N-Key Rollover) olay düşmesine karşı pay bırakır. Anti-cheat uyumlu.";
                SubCategory="Giriş ve İşlemci";
                Key="HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters"; ValueName="KeyboardDataQueueSize"; Type="DWord"; Data=256; Undo=100; RestartExplorer=$false
            },
        @{
                Name="TCP NoDelay ve AckFrequency (Nagle Algoritmasını Kapat)";
				Description="TCP gecikmeli onayını (delayed ACK) kapatır: her gelen pakete hemen onay gönderilir (sıklık 1, zaman aşımı 10 ms; Windows varsayılanı 2 paket / 40 ms). TCP trafiği daha hızlı ilerler.`n`n✅ v1.3.0 (4. tur): Artık Windows'un DESTEKLENEN yöntemiyle (netsh TCP 'internet' şablonu) uygulanır — yeniden başlatma gerekmez, sonradan bağlandığınız Wi-Fi ağları dahil her bağlantıda geçerli. Önceki sürümün yazdığı 'TCPNoDelay' ve 'TcpDelAckTicks' kayıt değerleri modern Windows'ta OKUNMUYORDU; temizlenir. İsim eski sürümle uyum için korundu.`n⚠️ Büyük indirmelerde yükleme yönünde biraz daha fazla ACK trafiği oluşur (çok yavaş yüklemeli ADSL'de fark edilebilir).`n`nℹ️ Dürüst not (v1.3.0): Rekabetçi oyunların çoğu (CS2, Valorant, Apex, Fortnite, CoD) oyun trafiğinde UDP kullanır — Nagle UDP'yi ETKİLEMEZ, dolayısıyla hitreg/ping değişmez. Fayda TCP kullanan oyunlarda (bazı MMO'lar, eski oyunlar), Uzak Masaüstü ve sohbet/komut trafiğinde görülür. Önceki açıklamadaki 'hitreg ciddi oranda artar' iddiası kaldırıldı. Zararsızdır.";
                SubCategory="Ağ ve Ping";
                SkipRebootDialog=$true;
                DetectScript='
                    # netsh int tcp show supplemental: deger satirlari sirasiyla MinRTO, ICW, CCP, CwndRestart, DelayedAckTimeout, DelayedAckFrequency...
                    $vals = @(& netsh int tcp show supplemental 2>$null | Where-Object { "$_" -match ":\s*\S+\s*$" -and "$_" -notmatch "(?i)template|sablon|şablon" } | ForEach-Object { ("$_" -split ":")[-1].Trim() })
                    if ($vals.Count -lt 6) { return $false }
                    return ("$($vals[5])" -eq "1")
                ';
                Command='
                    # v1.3.0 (4. tur): Desteklenen yontem — TCP "internet" sablonunda gecikmeli ACK: her pakete hemen ACK
                    # (frekans 1), zaman asimi 10 ms (en dusuk). Yeniden baslatma GEREKMEZ, yeni baglantilarda gecerli olur,
                    # sonradan baglanilan Wi-Fi aglari dahil tum arayuzleri kapsar.
                    & netsh int tcp set supplemental template=internet delayedackfrequency=1 delayedacktimeout=10 2>$null | Out-Null
                    # Eski surumun arayuz bazli kayit degerleri temizlenir: TCPNoDelay ve TcpDelAckTicks modern Windows ta
                    # okunmuyordu; TcpAckFrequency nin isini artik sablon yapiyor.
                    foreach ($nic in (Get-MrCleanPhysicalAdapters)) {
                        $path = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$($nic.InterfaceGuid)"
                        foreach ($n in @("TcpAckFrequency","TCPNoDelay","TcpDelAckTicks")) { Remove-ItemProperty -Path $path -Name $n -ErrorAction SilentlyContinue }
                    }
                ';
                UndoCommand='
                    # Windows varsayilani: 40 ms / her 2 pakette bir ACK
                    & netsh int tcp set supplemental template=internet delayedackfrequency=2 delayedacktimeout=40 2>$null | Out-Null
                    foreach ($nic in (Get-MrCleanPhysicalAdapters)) {
                        $path = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$($nic.InterfaceGuid)"
                        foreach ($n in @("TcpAckFrequency","TCPNoDelay","TcpDelAckTicks")) { Remove-ItemProperty -Path $path -Name $n -ErrorAction SilentlyContinue }
                    }
                ';
                RestartExplorer=$false
            },
        @{
                Name="TSC Sync Policy: Enhanced (Multi-CPU)";
                SubCategory="Zamanlayıcı (Timer)";
                Description="Time Stamp Counter (TSC) senkronizasyon politikasını 'enhanced' moduna alır. Çok çekirdekli CPU'larda çekirdekler arası TSC kayması varsa Windows daha agresif senkronlama uygular.`n`nℹ️ Dürüst not (v1.3.0, 4. tur): valleyofdoom/PC-Tuning araştırması yalnızca Windows varsayılanının 'enhanced' OLMADIĞINI gösteriyor; bu ayarın oyunda fayda sağladığına dair ölçüm yok. Önceki açıklamadaki 'önerilir' ifadesi kaldırıldı ve tweak 'Oyun' profilinden çıkarıldı. Zararsızdır; isteyen uygular.`n`n⚠️ Reboot şarttır (kernel boot config). Anti-cheat uyumlu.";
                Risk="Low"; RestartExplorer=$false;
                DetectScript='
                    # bcdedit cache uzerinden kontrol — Refresh-BcdEdit-Cache zaten Add_Loaded sonrasi prime ediliyor
                    if ($script:BcdEditEnumOutput -match "(?im)tscsyncpolicy\s+Enhanced") { return $true }
                    return $false
                ';
                Command='
                    $null = Invoke-HiddenCommand "bcdedit.exe" "/set tscsyncpolicy enhanced"
                    # Cache invalidate — bir sonraki DetectScript taze okusun
                    $script:BcdEditEnumOutput = ""
                ';
                UndoCommand='
                    $null = Invoke-HiddenCommand "bcdedit.exe" "/deletevalue tscsyncpolicy"
                    $script:BcdEditEnumOutput = ""
                '
            },
        @{
                Name="MMCSS Oyun Görevi Önceliği (Games: High)";
                SubCategory="Ses (Audio)"; Since="2.0.0";
                Risk="Low"; RestartExplorer=$false; RequiresReboot=$true;
                Description="Multimedia Class Scheduler (MMCSS) 'Games' görev profilini yükseltir: Priority 2 → 6, Scheduling Category Medium → High, SFIO (disk G/Ç) Priority Normal → High. GPU Priority zaten 8'dir (dokunulmaz).`n`nℹ️ Dürüst not (v1.3.0, 4. tur): djdallmann'ın izleme ölçümlerinde hiçbir oyunun bu göreve kaydolduğu gözlenmedi; Microsoft belgesine göre 'SFIO Priority' kullanılmıyor ve Scheduling Category High iken Priority değeri zaten 2 kabul ediliyor. Pratikte etkisi YOK denecek kadar azdır — zararı da yoktur. Bu yüzden 'Oyun' profilinden çıkarıldı; isteyen elle uygulayabilir. Arka plan müziği (Spotify), Discord sesi ve medya tuşları etkilenmez — onlar 'Audio/Pro Audio' görevlerini kullanır.`n`n⚠️ Yeniden başlatma sonrası tam etkin olur. Windows varsayılanlarına geri alınabilir.`n📚 Kaynak: Microsoft MMCSS belgeleri; tweaqas paketi (BareFox).";
                Batch=@(
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games"; ValueName="Priority"; Type="DWord"; Data=6; Undo=2 },
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games"; ValueName="Scheduling Category"; Type="String"; Data="High"; Undo="Medium" },
                    @{ Key="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games"; ValueName="SFIO Priority"; Type="String"; Data="High"; Undo="Normal" }
                )
            }
    )
}

function Invoke-RetiredTweakCleanup {
    $root = "HKCU:\Software\MrClean"; $ver = "r12b"
    try { if ("$((Get-ItemProperty -Path $root -Name "RetiredCleanup" -ErrorAction SilentlyContinue).RetiredCleanup)" -eq $ver) { return } } catch {}
    try { Refresh-BcdEdit-Cache } catch {}
    $defs = @(Get-RetiredTweakDefs)
    $done = New-Object System.Collections.Generic.List[string]
    # SysMain: eski "SSD Optimize (... + SysMain Disable)" kapatmissa (uygulanan listesinde) Windows varsayilanina (Otomatik) doner.
    # Kaynaklar: 16 GB+ RAM + NVMe de kapatmanin olculebilir oyun faydasi yok; bellek sikistirma da SysMain e bagli.
    # "Microsoft kapatmayi oneriyor" iddiasinin kaynagi ozel amacli IoT gercek zamanli cihaz belgesi (Windows Ses ve Update i de kapattiriyor).
    try {
        $oldSsd = "SSD Optimize (8.3 Filename + Last Access + SysMain Disable)"
        $appliedNow = @((Get-ItemProperty -Path $root -Name "AppliedTweaks" -ErrorAction SilentlyContinue).AppliedTweaks)
        $sm = Get-Service -Name SysMain -ErrorAction SilentlyContinue
        if ($sm -and "$($sm.StartType)" -eq "Disabled" -and $appliedNow -contains $oldSsd) {
            WpfLog "[Emekli] SysMain eski SSD tweaki tarafindan kapatilmis — Windows varsayilanina (Otomatik) donduruluyor."
            Set-Service -Name SysMain -StartupType Automatic -ErrorAction Stop
            Start-Service -Name SysMain -ErrorAction SilentlyContinue
            $done.Add("SysMain (Superfetch) yeniden açıldı — eski 'SSD Optimize' kapatmıştı")
        }
        if ($appliedNow -contains $oldSsd) { Update-MrCleanAppliedList -Enabled @() -Disabled @(@{ Name = $oldSsd }) }
    } catch { WpfLog "[Emekli] SysMain acilamadi: $($_.Exception.Message)" }
    # Eski (v1.2.x) TCP NoDelay arayuz bazli kayit degerleri: v1.3.0 tespiti sablona baktigi icin bunlari gormuyordu.
    # Sadece MrClean in uygulama listesinde bu tweak varsa (baska arac / kullanici kendisi yazdiysa dokunulmaz) TUM arayuzlerden silinir.
    try {
        if ($appliedNow -contains "TCP NoDelay ve AckFrequency (Nagle Algoritmasını Kapat)") {
            $cnt = 0
            Get-ChildItem "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces" -ErrorAction SilentlyContinue | ForEach-Object {
                $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                if ($null -ne $p.TCPNoDelay -or $null -ne $p.TcpAckFrequency -or $null -ne $p.TcpDelAckTicks) {
                    foreach ($vn in @("TcpAckFrequency","TCPNoDelay","TcpDelAckTicks")) { Remove-ItemProperty -Path $_.PSPath -Name $vn -ErrorAction SilentlyContinue }
                    $cnt++
                }
            }
            if ($cnt -gt 0) { WpfLog "[Emekli] Eski TCP NoDelay / AckFrequency degerleri $cnt arayuzden silindi."; $done.Add("TCP NoDelay / AckFrequency (eski arayüz değerleri, $cnt arayüz)") }
        }
    } catch {}
    foreach ($t in $defs) {
        $on = $false; try { $on = Test-TweakApplied $t } catch {}
        if (-not $on) { continue }
        WpfLog "[Emekli] Varsayilana donduruluyor: $($t.Name)"
        $batchList = if ($t.Batch) { $t.Batch } else { @($t) }
        foreach ($sub in $batchList) {
            try {
                if ($sub.UndoCommand) { Invoke-TweakCommand $sub.UndoCommand }
                elseif ($sub.Key -and $null -ne $sub.Undo) {
                    if ("$($sub.Undo)" -eq "DELETE_VALUE") { Remove-ItemProperty -Path $sub.Key -Name $sub.ValueName -ErrorAction SilentlyContinue }
                    else {
                        if (-not (Test-Path $sub.Key)) { New-Item -Path $sub.Key -Force | Out-Null }
                        Set-ItemProperty -Path $sub.Key -Name $sub.ValueName -Value $sub.Undo -Type $sub.Type -Force -ErrorAction Stop
                    }
                }
            } catch { WpfLog "[Emekli] Hata ($($t.Name)): $($_.Exception.Message)" }
        }
        $done.Add("$($t.Name)")
    }
    try { Update-MrCleanAppliedList -Enabled @() -Disabled $defs } catch {}
    try { if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }; Set-ItemProperty -Path $root -Name "RetiredCleanup" -Value $ver -Type String -Force } catch {}
    if ($done.Count -eq 0) { return }
    WpfLog "[Emekli] $($done.Count) etkisiz ayar Windows varsayilanina dondu (bir kismi yeniden baslatma sonrasi tam etkili olur)."
    $list = ($done | ForEach-Object { "  • $_" }) -join "`n"
    try { [System.Windows.MessageBox]::Show("Bu sürümde ölçüm ve araştırma sonucunda etkisiz (ya da zararlı) bulunan $($done.Count) ayar menüden kaldırıldı ve bu bilgisayarda Windows varsayılanına döndürüldü:`n`n$list`n`nBir kısmı yeniden başlatma sonrası tam etkili olur.", "MrClean — Kaldırılan Ayarlar", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null } catch {}
}

function Test-TweakApplied($tweak) {
    try {
        if (Get-Tweak-IsActive $tweak) { return $true }
        if ($tweak.Batch) {
            foreach ($sub in $tweak.Batch) {
                if (-not (Get-Tweak-IsActive $sub)) { return $false }
            }
            return $true
        }
    } catch {}
    return $false
}

# UI uzerinde tek tweak'i isaretle/temizle
function Set-TweakItemUI($item, $isApplied, [bool]$fromCache = $false) {
    $chk = Get-CheckFromItem $item
    if (-not $chk) { return }

    # v1.3.0 (§95): bu bilgisayarda uygulanamayan (surum / donanim) ama aktif olan tweak yalniz KAPATILABILIR; aktif degilse
    # kilitli kalir. Ornek: HDD'siz bilgisayarda plan degisimiyle aktif kalmis "Disklerin Kapanmasini Engelle" geri alinamiyordu.
    # Apply-System-Tweaks zaten yalniz acmayi atlar (isaretli + aktif degil + uyumsuz), kapatmaya izin verir.
    if ($script:TweakIncompatNames -and $script:TweakIncompatNames.ContainsKey([string]$item.Tag.Name)) {
        $chk.IsEnabled = [bool]$isApplied
        $chk.Opacity = $(if ($isApplied) { 0.8 } else { 0.45 })
    }

    # v1.3.0 (tasarım E): durum yalnizca anahtarla gosterilir. §96: eski "(Aktif)" eki + renk dali (tasarim E oncesi
    # satirlar) kaldirildi — tum tweak satirlari bu tasarimda.
    $chk.IsChecked = [bool]$isApplied
    Set-TweakPendingState $chk ([string]$item.Tag.Name) $false
}

# Parent SUBCAT header'lari guncelle (tum cocuklar checked ise parent da)
function Update-Parent-Headers-Recursive($nodes) {
    foreach ($item in $nodes) {
        if ($item.Items.Count -gt 0) {
            Update-Parent-Headers-Recursive $item.Items
            if ($item.Tag -eq "SUBCAT") {
                $allChildrenChecked = $true; $hasChildren = $false
                foreach ($child in $item.Items) {
                    $hasChildren = $true
                    $childChk = Get-CheckFromItem $child
                    if (-not $childChk.IsChecked) { $allChildrenChecked = $false; break }
                }
                if ($hasChildren) {
                    $headerChk = Get-CheckFromItem $item
                    if ($headerChk) { $headerChk.IsChecked = $allChildrenChecked }
                }
            }
        }
    }
}

function Check-Tweak-Status {
    param([switch]$ForceRefresh)  # Cache'i yoksay, sifirdan tara
    Start-MrCleanMeasure 'Tweak denetimi'   # v1.3.0 (§87)

    # Onceki tarama varsa iptal et
    if ($script:TweakScanTimer -and $script:TweakScanTimer.IsEnabled) {
        $script:TweakScanTimer.Stop()
    }

    # Cache'leri PRIME et — 3 external command tek seferde (terminal flash olmadan).
    # Tarama sirasinda tum tweak'ler bu cache'lerden okuyacak, her tweak icin ayri call yok.
    Refresh-PowerCfg-Cache
    Refresh-BcdEdit-Cache
    Refresh-NetshTcp-Cache

    if ($btnCheckTweaks) {
        $btnCheckTweaks.Content = "Denetleniyor..."
        $btnCheckTweaks.IsEnabled = $false
    }

    # 1) Tum tweak item'larini topla
    $allItems = Get-AllTweakItems
    $totalCount = $allItems.Count
    if ($totalCount -eq 0) {
        if ($btnCheckTweaks) { $btnCheckTweaks.Content = "♻ Denetle"; $btnCheckTweaks.IsEnabled = $true }
        return
    }

    # 2) Cache'ten ANINDA on-yukleme yap (UI'da hemen gozukur, donmaz)
    if (-not $ForceRefresh) {
        $cache = Load-TweakStatusCache
        if ($cache) {
            $global:TweakStatusCache = $cache
            foreach ($item in $allItems) {
                $key = $item.Tag.Name
                if ($cache.ContainsKey($key)) {
                    Set-TweakItemUI -item $item -isApplied $cache[$key] -fromCache $true
                }
            }
            Update-Parent-Headers-Recursive $tvTweaks.Items
            try { Update-TweakSummary $cache } catch {}
        }
    }

    # 3) Background scan'i baslat (chunked DispatcherTimer)
    # 10. tur: onceki sonuc saklanir -> bitince "son denetimden bu yana degisen" ozeti (Windows Update geri aldi mi?) gosterilir
    $script:TweakScanPrev = $null
    try { $script:TweakScanPrev = if ($global:TweakStatusCache) { $global:TweakStatusCache.Clone() } else { Load-TweakStatusCache } } catch {}
    $script:TweakScanIdx       = 0
    $script:TweakScanChunk     = 10
    $script:TweakScanItems     = $allItems
    $script:TweakScanResultMap = @{}
    $script:TweakScanWorkMs    = 0
    $script:TweakScanTimes     = New-Object System.Collections.Generic.List[object]
    $script:TweakScanWallSw    = [Diagnostics.Stopwatch]::StartNew()

    $script:TweakScanTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:TweakScanTimer.Interval = [TimeSpan]::FromMilliseconds(20)
    $script:TweakScanTimer.Add_Tick({
        $end = [Math]::Min($script:TweakScanIdx + $script:TweakScanChunk, $script:TweakScanItems.Count)
        for ($i = $script:TweakScanIdx; $i -lt $end; $i++) {
            $item  = $script:TweakScanItems[$i]
            $tweak = $item.Tag
            $itSw = [Diagnostics.Stopwatch]::StartNew()
            try {
                $isApplied = Test-TweakApplied $tweak
                Set-TweakItemUI -item $item -isApplied $isApplied -fromCache $false
                $script:TweakScanResultMap[$tweak.Name] = $isApplied
            } catch {}
            # v1.3.0 (§94): yavas denetimde kayda "is / bekleme" ayrimi + en yavas kalemler (asagida, yalniz > 6 sn ise)
            $script:TweakScanWorkMs += $itSw.ElapsedMilliseconds
            $script:TweakScanTimes.Add([pscustomobject]@{ Ms = $itSw.ElapsedMilliseconds; Name = "$($tweak.Name)" })
        }
        $script:TweakScanIdx = $end

        if ($btnCheckTweaks) {
            $pct = [int](($script:TweakScanIdx / $script:TweakScanItems.Count) * 100)
            $btnCheckTweaks.Content = "Denetleniyor... %$pct"
        }

        if ($script:TweakScanIdx -ge $script:TweakScanItems.Count) {
            $script:TweakScanTimer.Stop()
            Update-Parent-Headers-Recursive $tvTweaks.Items
            Save-TweakStatusCache $script:TweakScanResultMap
            $global:TweakStatusCache = $script:TweakScanResultMap
            try { Update-TweakSummary $script:TweakScanResultMap } catch {}
            # v1.3.0: Aktif/Pasif cipi seciliyse guncel tarama sonucuna gore listeyi yenile
            try { if ($script:TweakChipMode -in @("active","passive")) { Apply-TweakFilter } } catch {}
            # v1.3.0 (6. tur): guncelleme sonrasi denetimden bekleyen yeniden uygulama
            try { if ($script:PendingReapply -or $script:ReapplySticky) { Set-MrCleanPendingReapply } } catch {}
            # 10. tur (kullanici: "%100 olup hicbir sey cikmayinca ne ise yaradigini anlamadim"): sonuc ozeti + degisenler
            $res = $script:TweakScanResultMap
            $act = @($res.Values | Where-Object { $_ }).Count
            $chg = @()
            if ($script:TweakScanPrev) { foreach ($k in $res.Keys) { if ($script:TweakScanPrev.ContainsKey($k) -and [bool]$script:TweakScanPrev[$k] -ne [bool]$res[$k]) { $chg += [pscustomobject]@{ Name = $k; Now = [bool]$res[$k] } } } }
            try {
                Stop-MrCleanMeasure 'Tweak denetimi'   # v1.3.0 (§87)
                # v1.3.0 (§94): beklenmedik yavaslikta sebep: denetimlerin kendisi mi, yoksa arayuz / sistem baska isle mesgul mu
                $wall = [int64]$script:TweakScanWallSw.ElapsedMilliseconds
                if ($wall -gt 6000) {
                    WpfLog ("[ÖLÇÜM] Tweak denetimi ayrıntı: denetimlerin kendisi {0} ms, bekleme / arayüz {1} ms" -f $script:TweakScanWorkMs, [Math]::Max(0, $wall - $script:TweakScanWorkMs))
                    WpfLog ("   en yavaş: " + ((@($script:TweakScanTimes | Sort-Object Ms -Descending | Select-Object -First 5) | ForEach-Object { "$($_.Name) $($_.Ms) ms" }) -join " · "))
                }
                WpfLog ("[DENETİM] Bitti: {0} / {1} ayar aktif. Son denetimden bu yana değişen: {2}" -f $act, $res.Count, $(if (-not $script:TweakScanPrev) { "(karşılaştırılacak önceki denetim yok)" } elseif ($chg.Count) { $chg.Count } else { "yok — her şey yerinde" }))
                foreach ($c in @($chg | Select-Object -First 15)) { WpfLog ("   {0} {1}" -f $(if ($c.Now) { "✅ aktif oldu:" } else { "⚠ PASİF oldu (Windows / başka program geri almış olabilir):" }), $c.Name) }
                if ($chg.Count -gt 15) { WpfLog "   ... ve $($chg.Count - 15) tane daha" }
            } catch {}
            if ($btnCheckTweaks) {
                $btnCheckTweaks.Content = $(if ($chg.Count) { "✔ $($chg.Count) değişiklik" } else { "✔ Güncel" })
                $btnCheckTweaks.IsEnabled = $true
                $script:TweakCheckBtnTimer = New-Object System.Windows.Threading.DispatcherTimer; $script:TweakCheckBtnTimer.Interval = [TimeSpan]::FromSeconds(4)
                $script:TweakCheckBtnTimer.Add_Tick({ $script:TweakCheckBtnTimer.Stop(); if ($btnCheckTweaks -and $btnCheckTweaks.IsEnabled) { $btnCheckTweaks.Content = "♻ Denetle" } })
                $script:TweakCheckBtnTimer.Start()
            }
        }
    })
    $script:TweakScanTimer.Start()
}

# --- TARAYICI & SİSTEM FONKSİYONLARI ---

# #endregion 9 -- TWEAK SISTEMI (IsActive, Apply, Check, Manager)


