# ---- Tool script blocks ----
# --- SÜRÜCÜ YEDEKLEME (DRIVER EXPORT) MANTIĞI ---
$script:ExportDriversBlock = {
    # 1. Klasör Seçme Diyaloğu (UI Thread)
    $fbd = New-Object System.Windows.Forms.FolderBrowserDialog
    $fbd.Description = "Sürücülerin yedekleneceği klasörü seçin:"
    
    if ($fbd.ShowDialog() -eq 'OK') {
        $targetDir = $fbd.SelectedPath
        
        # Klasör dolu mu kontrolü
        if ((Get-ChildItem $targetDir -ErrorAction SilentlyContinue).Count -gt 0) {
            $msg = "Seçilen klasör boş değil. Mevcut dosyaların üzerine yazılabilir veya karmaşa oluşabilir.`n`nYine de devam edilsin mi?"
            if ([System.Windows.MessageBox]::Show($msg, "Uyarı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning) -eq 'No') { return }
        }

        # UI Hazırlığı
        $txtLog.Text = ""
        WpfLog "--- SÜRÜCÜ YEDEKLEME BAŞLATILDI (RAM MODU) ---"
        WpfLog "Hedef: $targetDir"
        $pbMain.IsIndeterminate = $true

        # 2. Arka Planda Çalışacak Script Bloğu (Boşluk Hatası Giderildi!)
        $innerScript = @"
            WS 'Hazırlanıyor...'
            Log 'İŞLEM BAŞLATILDI: DISM Driver Export'
            Log 'Lütfen bekleyin, sürücü sayısına göre 1-5 dakika sürebilir...'
            
            WS 'Sürücüler taranıyor...'
            
            # DISM komutunu çalıştır ve çıktısını yakala
            & dism /online /export-driver /destination:`"$targetDir`" 2>&1 | ForEach-Object {
                `$line = `$_.ToString().Trim()
                if (-not [string]::IsNullOrWhiteSpace(`$line)) {
                    Log ">> `$line"
                }
            }
            
            if (Test-Path `"$targetDir`") {
                Log '----------------------------------------'
                Log '✅ İŞLEM BAŞARIYLA TAMAMLANDI.'
                WS 'Bitti'
                
                # Klasörü kullanıcı için otomatik aç
                explorer.exe `"$targetDir`"
            }
"@

        Start-Worker-Process $innerScript $btnDriverBackup "SÜRÜCÜ YEDEKLEME"
    }
}
# ---- Show-RecommendedProfiles ----
# v1.2.10: Tag-based profil-tweak baglantisi — single source of truth.
# Tweak silindiginde otomatik filtrelenir (TweakList'te yoksa donmez), yeni tweak eklenince
# sadece $profileTagMap'i guncellemen yeterli.
# Cakisan tweak'ler birden fazla profil'de olabilir (orn. "Nihai Performans" hem Oyun hem Hiz).
function Get-ProfileTweaks {
    param([string]$ProfileKey)

    $profileTagMap = @{
        "Oyun" = @(
            "Nihai Performans Güç Planını Aktif Et",
            "İşlemci Minimum Durumu %100 — Yalnız Oyun Açıkken (Prizde)",
            "Fare İvmesini (Acceleration) Tamamen Kapat",
            "RSC (Receive Segment Coalescing) Kapat",
            "MSI Mode (GPU Interrupt) Aç",
            "HPET (Platform Clock) Kapat",
            "Görsel Efektler: Özel (Yazı Tipi + Küçük Resimler Açık)",
            "Xbox Game DVR Kapat",
            "USB Selective Suspend Devre Dışı",
            "CPU Core Parking Devre Dışı (Tüm Çekirdekler Aktif)",
            "Hardware Accelerated GPU Scheduling Aç (HAGS)",
            "Pencereli Oyunlar İçin Optimizasyon (Flip Model)",
            "Oturum Açıkken Güncelleme Sonrası Otomatik Yeniden Başlatmayı Engelle",
            "Ağ Kartı Güç Tasarrufu ve Uyandırma Kapat (Tümü)",
            "Oyun Modunu Aç",
            "USB 3 Bağlantı Güç Yönetimini Kapat (U1/U2)",
            "Oyun Çubuğu Başlangıç İpuçlarını Kapat",
            "Uygulama Arşivlemeyi Kapat (Oyunlar Silinmesin)",
            "Windows Update Arka Plan İndirme Hızını Sınırla (%30)",
            "Görüşmede Oyun/Müzik Sesini Kısmayı Kapat (Discord)",
            "Ses Kartı Güç Tasarrufunu Kapat (Ses Başı Kesilmesi / Pıt Sesi)",
            "Dinamik Aydınlatmayı Kapat (RGB)",
            "İçerik Uyarlamalı Parlaklığı Kapat (CABC)"
        )
        "Gizlilik" = @(
            "Reklam Kimliğini Kapat",
            "Konum Hizmetlerini Tamamen Kapat",
            "Bildirim Erişimi Kapat",
            "Kişilere (Contacts) Erişimi Kapat",
            "Takvim Erişimi Kapat",
            "Telefon Araması Erişimi Kapat",
            "Arama Geçmişi Erişimi Kapat",
            "E-posta Erişimi Kapat",
            "Görevler (Tasks) Erişimi Kapat",
            "Mesajlaşma (Chat) Erişimi Kapat",
            "Radyo (Bluetooth vb.) Erişimi Kapat",
            "Uygulama Tanılama (Diagnostics) Erişimi Kapat",
            "Arka Plan Uygulamalarını Kapat (Sistem Politikası)",
            "Cortana ve Cloud Aramayı Tamamen Kapat",
            "Yerel olarak uygun içerik Kapat",
            "Cloud Clipboard Devre Disi (Win+V Senkronizasyonu Kapat)",
            "Connected Devices Platform (CDP) Servisini El Ile Al",
            "Tailored Experiences (Kisisellestirilmis Deneyimler) Kapat",
            "LLMNR Devre Disi (DNS Multicast Privacy + Guvenlik)",
            "Windows Reklam ve Öneri Bildirimlerini Kapat (Hepsi)",
            "Etkinlik Geçmişini Kapat (Activity History)",
            "Mürekkep ve Yazma Kişiselleştirmesini Kapat",
            "Geri Bildirim İsteklerini Kapat (Sıklık: Asla)",
            "Telemetri Zamanlanmış Görevlerini Devre Dışı Bırak",
            "Recall (Anlık Görüntü Hafızası) Kapat",
            "Click to Do (Ekran Analizi) Kapat",
            "Explorer Arama Kutusu Önerilerini Kapat (Policy)",
            "Bulut Optimize İçerik, Üçüncü Taraf Öneriler ve Çevrimiçi İpuçlarını Kapat",
            "DiagTrack Önyükleme Telemetri Günlüğünü Kapat",
            "Uyumluluk (AppCompat) Telemetrisini Kapat",
            "PowerShell ve .NET Telemetrisini Kapat",
            "Uygulamaların Üretken AI ve Sistem AI Modellerine Erişimini Kapat",
            "Edge Reklam, Öneri ve Tanıtım Ekranlarını Kapat",
            "Aramada Bulut İçeriği ve Cihaz Arama Geçmişini Kapat",
            "Ek Telemetri Politikaları (Cihaz Adı / Döküm / Yazım Verisi)",
            "Hızlı Erişimde Son Kullanılan ve Sık Kullanılanları Gizle",
            "Phone Link / Mobil Cihazları Kapat"
        )
        "Hiz" = @(
            "Görsel Efektler: Özel (Yazı Tipi + Küçük Resimler Açık)",
            "Hazırda Bekletmeyi Kapat (Hibernate)",
            "Hızlı Başlatmayı Kapat (Fast Startup)",
            "Nihai Performans Güç Planını Aktif Et",
            "Cortana ve Cloud Aramayı Tamamen Kapat",
            "Windows Update'i Kısıtla (Otomatik Yüklemeyi Kapat)",
            "Xbox Game DVR Kapat",
            "Pencere Öğelerini (Widget) Kapat",
            "OneDrive'ı Sistemden Tamamen Kaldır",
            "Uygulama Başlangıç Gecikmesini Kaldır (Startup Delay)",
            "Edge Arka Planda Çalışmasın (Startup Boost + Arka Plan Modu)",
            "Windows AI Servisini Otomatik Başlatma (WSAIFabricSvc)",
            "Gereksiz Arka Plan Servislerini El ile Başlat (Güvenli Liste)",
            "Bellek Sayfa Birleştirmeyi Kapat (Page Combining)",
            "Saydamlık Efektlerini Kapat",
            "Fare Üzerine Gelme ve Görev Çubuğu Önizleme Gecikmesini Azalt",
            "Oturum Açma Ekranı Bulanıklığını Kapat (Acrylic)",
            "Küçük Resim Önbelleğinin Otomatik Silinmesini Engelle",
            "SSD Optimize (8.3 Filename + Last Access)",
            "Uygulama Arşivlemeyi Kapat (Oyunlar Silinmesin)",
            "Dev Home ve Yeni Outlook'un Kendiliğinden Kurulmasını Engelle",
            "Dinamik Aydınlatmayı Kapat (RGB)",
            "Phone Link / Mobil Cihazları Kapat"
        )
    }

    if (-not $profileTagMap.ContainsKey($ProfileKey)) { return @() }

    $profileTweakNames = $profileTagMap[$ProfileKey]
    # v1.3.0 (4. tur): AMD Ryzen (X3D dahil) icin AMD ve topluluk onerisi Windows Dengeli plandir; Nihai plan
    # minimum islemci durumunu %100 e sabitler (boostu ve sicakligi olumsuz etkiler, FPS kaniti yok).
    # AMD islemcide profiller guc planina dokunmaz; Intel masaustunde Nihai kalir. Dizustunde hicbir profil plan degistirmez.
    $skipPlan = $false
    try { $skipPlan = (Test-IsAmdCpu) -or (Test-IsLaptop) } catch {}
    if ($skipPlan) { $profileTweakNames = @($profileTweakNames | Where-Object { $_ -ne "Nihai Performans Güç Planını Aktif Et" }) }
    # v1.3.0 (5. tur): donanima ozel eklemeler (uyumsuz olanlar asagida zaten elenir)
    try {
        $hw = Get-MrCleanHwProfile
        if ($ProfileKey -eq "Oyun") {
            if ($hw.HasHDD) { $profileTweakNames += "Disklerin Kapanmasını Engelle (Prizde: Asla)" }
            # v1.3.0 (8. tur): Wi-Fi karti VARSA (Ethernet de olsa) uygulanir — kablo arizalanip Wi-Fi ye gecilince ayar zaten hazir olur.
            # Ayar sadece Wi-Fi kartinin surucu kaydini degistirir; bagli degilken Ethernet e etkisi yoktur.
            if ($hw.HasWiFi) { $profileTweakNames += "Wi-Fi: 5 GHz Bandını Tercih Et" }
            if ($hw.HasWiFi -and -not $hw.IsLaptop) { $profileTweakNames += "Wi-Fi: Dolaşımı En Aza İndir ve Güç Tasarrufunu Kapat (Tek Modem)" }
            if ($hw.HasWiFi -and $hw.IsLaptop) { $profileTweakNames += "Wi-Fi Güç Tasarrufunu Pilde de Kapat (Dizüstü)" }
        }
    } catch {}
    $result = @()

    # Sadece $global:TweakList'te gercekten var olan tweak'leri don — broken refs filtrelenir.
    # Kullanici silmis veya bizim sprint'te kaldirmis olabiliriz, broken referans gozukmesin.
    foreach ($cat in $global:TweakList.Keys) {
        foreach ($tweak in $global:TweakList[$cat]) {
            if ($profileTweakNames -contains $tweak.Name) {
                try { if (-not (Test-TweakBuildCompatible $tweak)) { continue } } catch {}
                $result += $tweak.Name
            } elseif ($tweak.Aliases -and ($profileTweakNames | Where-Object { @($tweak.Aliases) -contains $_ })) {
                try { if (-not (Test-TweakBuildCompatible $tweak)) { continue } } catch {}
                $result += $tweak.Name
            }
        }
    }

    return $result
}

function Show-RecommendedProfiles {
    # v1.2.10: Runtime tweak sayilari — kartta gosterilir, broken refs sayilmaz (Get-ProfileTweaks
    # mevcut TweakList'ten filtreler). Tweak silindiginde sayi otomatik dusyor.
    $oyunCount     = (Get-ProfileTweaks "Oyun").Count
    $gizlilikCount = (Get-ProfileTweaks "Gizlilik").Count
    $hizCount      = (Get-ProfileTweaks "Hiz").Count

    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="@@rec_title@@" Height="560" Width="820"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="NoResize">
    <Window.Resources>
$($global:SubTheme)
        <Style TargetType="CheckBox" x:Key="ProfileCheck" BasedOn="{StaticResource SwCheck}">
            <Setter Property="Foreground"   Value="#C9CED6"/>
            <Setter Property="FontSize"     Value="14"/>
            <Setter Property="Cursor"       Value="Hand"/>
            <Setter Property="Margin"       Value="0,0,0,4"/>
        </Style>
    </Window.Resources>
    <Grid Margin="16">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <!-- BASLIK -->
        <StackPanel Grid.Row="0" Margin="0,0,0,14">
            <TextBlock Text="@@rec_title@@" Style="{StaticResource SwTitle}"/>
            <TextBlock Text="@@rec_desc@@" Style="{StaticResource SwDesc}" Margin="0,4,0,0"/>
        </StackPanel>

        <!-- 3 KART -->
        <Grid Grid.Row="1">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="12"/>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="12"/>
                <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>

            <!-- OYUN KARTI -->
            <Border Grid.Column="0" Style="{StaticResource SwCard}">
                <StackPanel>
                    <Grid Margin="0,0,0,8">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <CheckBox x:Name="chkOyun" Grid.Column="0" Style="{StaticResource ProfileCheck}"
                                  VerticalAlignment="Center"/>
                        <StackPanel Grid.Column="1" Margin="8,0,0,0">
                            <TextBlock Text="@@gen_lowlatency@@" Foreground="#3FB97A"
                                       FontSize="15" FontWeight="SemiBold" TextWrapping="Wrap"/>
                            <TextBlock Text="@@gen_lowlatency_desc@@"
                                       Foreground="#8A919C" FontSize="13" TextWrapping="Wrap"/>
                        </StackPanel>
                        <Button x:Name="btnOyunExpand" Grid.Column="2" Content="▼"
                                Style="{StaticResource SwBtnGhost}" Width="26" Height="26"
                                VerticalAlignment="Top"/>
                    </Grid>
                    <Border Background="#1A1E25" CornerRadius="6" Padding="10,8"
                            Margin="0,0,0,4">
                        <TextBlock Foreground="#A9B0BB" FontSize="13" TextWrapping="Wrap">
                            <Run Text="$oyunCount tweak" FontWeight="Bold" Foreground="#3FB97A"/>
                            <Run Text=" · Güç planı, fare ivmesi, MSI Mode, Bellek Bütünlüğü, RSC, Game DVR, HAGS, pencereli oyun"/>
                        </TextBlock>
                    </Border>
                    <ScrollViewer x:Name="svOyun" MaxHeight="160"
                                  Visibility="Collapsed"
                                  VerticalScrollBarVisibility="Auto">
                        <ItemsControl x:Name="icOyun" Margin="0,4,0,0"/>
                    </ScrollViewer>
                </StackPanel>
            </Border>

            <!-- GİZLİLİK KARTI -->
            <Border Grid.Column="2" Style="{StaticResource SwCard}">
                <StackPanel>
                    <Grid Margin="0,0,0,8">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <CheckBox x:Name="chkGizlilik" Grid.Column="0" Style="{StaticResource ProfileCheck}"
                                  VerticalAlignment="Center"/>
                        <StackPanel Grid.Column="1" Margin="8,0,0,0">
                            <TextBlock Text="🔒 Gizlilik Odaklı" Foreground="#4C8DFF"
                                       FontSize="15" FontWeight="SemiBold" TextWrapping="Wrap"/>
                            <TextBlock Text="Telemetri, izinler ve Microsoft takibini kapatır"
                                       Foreground="#8A919C" FontSize="13" TextWrapping="Wrap"/>
                        </StackPanel>
                        <Button x:Name="btnGizlilikExpand" Grid.Column="2" Content="▼"
                                Style="{StaticResource SwBtnGhost}" Width="26" Height="26"
                                VerticalAlignment="Top"/>
                    </Grid>
                    <Border Background="#1A1E25" CornerRadius="6" Padding="10,8"
                            Margin="0,0,0,4">
                        <TextBlock Foreground="#A9B0BB" FontSize="13" TextWrapping="Wrap">
                            <Run Text="$gizlilikCount tweak" FontWeight="Bold" Foreground="#4C8DFF"/>
                            <Run Text=" · Konum, kamera, telemetri, Cortana, arka plan uygulamaları, izinler"/>
                        </TextBlock>
                    </Border>
                    <ScrollViewer x:Name="svGizlilik" MaxHeight="160"
                                  Visibility="Collapsed"
                                  VerticalScrollBarVisibility="Auto">
                        <ItemsControl x:Name="icGizlilik" Margin="0,4,0,0"/>
                    </ScrollViewer>
                </StackPanel>
            </Border>

            <!-- HIZ KARTI -->
            <Border Grid.Column="4" Style="{StaticResource SwCard}">
                <StackPanel>
                    <Grid Margin="0,0,0,8">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <CheckBox x:Name="chkHiz" Grid.Column="0" Style="{StaticResource ProfileCheck}"
                                  VerticalAlignment="Center"/>
                        <StackPanel Grid.Column="1" Margin="8,0,0,0">
                            <TextBlock Text="⚡ Maksimum Hız" Foreground="#E0A23B"
                                       FontSize="15" FontWeight="SemiBold" TextWrapping="Wrap"/>
                            <TextBlock Text="Gereksiz servisler ve görsel efektleri kapatır"
                                       Foreground="#8A919C" FontSize="13" TextWrapping="Wrap"/>
                        </StackPanel>
                        <Button x:Name="btnHizExpand" Grid.Column="2" Content="▼"
                                Style="{StaticResource SwBtnGhost}" Width="26" Height="26"
                                VerticalAlignment="Top"/>
                    </Grid>
                    <Border Background="#1A1E25" CornerRadius="6" Padding="10,8"
                            Margin="0,0,0,4">
                        <TextBlock Foreground="#A9B0BB" FontSize="13" TextWrapping="Wrap">
                            <Run Text="$hizCount tweak" FontWeight="Bold" Foreground="#E0A23B"/>
                            <Run Text=" · Görsel efektler, hibernate, gereksiz servisler"/>
                        </TextBlock>
                    </Border>
                    <ScrollViewer x:Name="svHiz" MaxHeight="160"
                                  Visibility="Collapsed"
                                  VerticalScrollBarVisibility="Auto">
                        <ItemsControl x:Name="icHiz" Margin="0,4,0,0"/>
                    </ScrollViewer>
                </StackPanel>
            </Border>
        </Grid>

        <!-- BİLGİ SATIRI -->
        <TextBlock x:Name="txtProfileInfo" Grid.Row="2"
                   Text="En az bir profil seçin."
                   Foreground="#8A919C" FontSize="13"
                   Margin="0,12,0,8" HorizontalAlignment="Center"/>

        <!-- BUTONLAR -->
        <Grid Grid.Row="3">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="12"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="12"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <TextBlock Grid.Column="0" x:Name="txtTweakCount"
                       Text="" Foreground="#8A919C" FontSize="13"
                       VerticalAlignment="Center"/>
            <Button x:Name="btnProfileCancel" Grid.Column="2"
                    Content="@@m_cancel@@" MinWidth="96" Height="36"/>
            <Button x:Name="btnProfileApply" Grid.Column="4"
                    Content="✔ Seçip Uygula" Style="{StaticResource SwBtnPrimary}"
                    MinWidth="150" Height="36" IsEnabled="False"/>
        </Grid>
    </Grid>
</Window>
"@

    try {
        $reader  = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xaml))
        $winP    = [Windows.Markup.XamlReader]::Load($reader)
        $winP.Owner = $Win
        Initialize-SubWindow $winP

        $chkOyun    = $winP.FindName('chkOyun')
        $chkGizlilik= $winP.FindName('chkGizlilik')
        $chkHiz     = $winP.FindName('chkHiz')

        $svOyun     = $winP.FindName('svOyun')
        $svGizlilik = $winP.FindName('svGizlilik')
        $svHiz      = $winP.FindName('svHiz')

        $icOyun     = $winP.FindName('icOyun')
        $icGizlilik = $winP.FindName('icGizlilik')
        $icHiz      = $winP.FindName('icHiz')

        $txtInfo    = $winP.FindName('txtProfileInfo')
        $txtCount   = $winP.FindName('txtTweakCount')
        $btnApply   = $winP.FindName('btnProfileApply')
        $btnCancel  = $winP.FindName('btnProfileCancel')

        $btnOyunExpand     = $winP.FindName('btnOyunExpand')
        $btnGizlilikExpand = $winP.FindName('btnGizlilikExpand')
        $btnHizExpand      = $winP.FindName('btnHizExpand')

        # Tweak listelerini doldur
        function Fill-TweakList($ic, $profileKey) {
            $ic.Items.Clear()
            foreach ($tweak in (Get-ProfileTweaks $profileKey)) {
                $tb = New-Object System.Windows.Controls.TextBlock
                $tb.Text       = "• $tweak"
                $tb.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#8A919C')
                $tb.FontSize   = 12
                $tb.Margin     = [System.Windows.Thickness]::new(0,1,0,1)
                $tb.TextWrapping = [System.Windows.TextWrapping]::Wrap
                $ic.Items.Add($tb) | Out-Null
            }
        }
        Fill-TweakList $icOyun     "Oyun"
        Fill-TweakList $icGizlilik "Gizlilik"
        Fill-TweakList $icHiz      "Hiz"

        # Expand toggle
        function Toggle-Expand($sv, $btn) {
            if ($sv.Visibility -eq [System.Windows.Visibility]::Collapsed) {
                $sv.Visibility = [System.Windows.Visibility]::Visible
                $btn.Content = "▲"
            } else {
                $sv.Visibility = [System.Windows.Visibility]::Collapsed
                $btn.Content = "▼"
            }
        }
        $btnOyunExpand.Add_Click({     Toggle-Expand $svOyun     $btnOyunExpand     })
        $btnGizlilikExpand.Add_Click({ Toggle-Expand $svGizlilik $btnGizlilikExpand })
        $btnHizExpand.Add_Click({      Toggle-Expand $svHiz      $btnHizExpand      })

        # Checkbox değişince tweak sayısını güncelle
        function Update-Selection {
            $allTweaks = @()
            if ($chkOyun.IsChecked)     { $allTweaks += Get-ProfileTweaks "Oyun" }
            if ($chkGizlilik.IsChecked) { $allTweaks += Get-ProfileTweaks "Gizlilik" }
            if ($chkHiz.IsChecked)      { $allTweaks += Get-ProfileTweaks "Hiz" }

            # Tekrarları kaldır
            $unique = $allTweaks | Select-Object -Unique
            $count  = $unique.Count

            if ($count -gt 0) {
                $btnApply.IsEnabled = $true
                $parts = @()
                if ($chkOyun.IsChecked)     { $parts += "Oyun" }
                if ($chkGizlilik.IsChecked) { $parts += "Gizlilik" }
                if ($chkHiz.IsChecked)      { $parts += "Hız" }
                $txtInfo.Text  = "$($parts -join ' + ') profili seçili"
                $txtCount.Text = "$count tweak uygulanacak (tekrarlar birleştirildi)"
            } else {
                $btnApply.IsEnabled = $false
                $txtInfo.Text  = "En az bir profil seçin."
                $txtCount.Text = ""
            }
        }

        $chkOyun.Add_Checked({     Update-Selection })
        $chkOyun.Add_Unchecked({   Update-Selection })
        $chkGizlilik.Add_Checked({ Update-Selection })
        $chkGizlilik.Add_Unchecked({ Update-Selection })
        $chkHiz.Add_Checked({      Update-Selection })
        $chkHiz.Add_Unchecked({    Update-Selection })

        $btnCancel.Add_Click({ $winP.Close() })

        # Uygula
        $btnApply.Add_Click({
            $allTweaks = @()
            if ($chkOyun.IsChecked)     { $allTweaks += Get-ProfileTweaks "Oyun" }
            if ($chkGizlilik.IsChecked) { $allTweaks += Get-ProfileTweaks "Gizlilik" }
            if ($chkHiz.IsChecked)      { $allTweaks += Get-ProfileTweaks "Hiz" }
            $unique = $allTweaks | Select-Object -Unique

            $parts = @()
            if ($chkOyun.IsChecked)     { $parts += "🎮 Oyun" }
            if ($chkGizlilik.IsChecked) { $parts += "🔒 Gizlilik" }
            if ($chkHiz.IsChecked)      { $parts += "⚡ Hız" }

            # SNAPSHOT: Profildeki tweaklerin SADECE suan false olanlari kaydet
            # (true olanlar zaten aktif, onlara dokunmuyoruz)
            # Performans: tum agaci degil sadece $unique listesini hedef aliyoruz
            $snapshot = @{}  # TweakName -> onceki IsChecked degeri
            function Take-Snapshot($nodes) {
                foreach ($node in $nodes) {
                    if ($node.Tag -is [System.Collections.IDictionary] -or
                        $node.Tag -is [System.Management.Automation.PSCustomObject]) {
                        $name = $node.Tag.Name
                        if ($unique -contains $name) {
                            $snapshot[$name] = (Get-CheckFromItem $node).IsChecked
                        }
                    }
                    if ($node.Items.Count -gt 0) { Take-Snapshot $node.Items }
                }
            }
            foreach ($cat in $tvTweaks.Items) { Take-Snapshot $cat.Items }

            # Checkbox'lari isaretleme fonksiyonu
            function Set-Checks($nodes) {
                foreach ($node in $nodes) {
                    if ($node.Tag -is [System.Collections.IDictionary] -or
                        $node.Tag -is [System.Management.Automation.PSCustomObject]) {
                        if ($unique -contains $node.Tag.Name) {
                            (Get-CheckFromItem $node).IsChecked = $true
                        }
                    }
                    if ($node.Items.Count -gt 0) { Set-Checks $node.Items }
                }
            }

            # Snapshot'tan geri yükleme — sadece degistirdigimiz tweak'leri hedef alir
            function Restore-Snapshot($nodes) {
                foreach ($node in $nodes) {
                    if ($node.Tag -is [System.Collections.IDictionary] -or
                        $node.Tag -is [System.Management.Automation.PSCustomObject]) {
                        $name = $node.Tag.Name
                        if ($snapshot.ContainsKey($name)) {
                            (Get-CheckFromItem $node).IsChecked = $snapshot[$name]
                        }
                    }
                    if ($node.Items.Count -gt 0) { Restore-Snapshot $node.Items }
                }
            }

            # Checkbox'lari isaretliyoruz
            foreach ($cat in $tvTweaks.Items) { Set-Checks $cat.Items }

            $winP.Close()

            # Apply-System-Tweaks cagir — ici zaten kendi onayini sorar
            # Kullanici Hayir derse Apply hicbir sey yapmaz VE biz snapshot'tan geri aliyoruz
            $Win.Dispatcher.Invoke([action]{
                # Apply'in kendi onay penceresini yakala:
                # Apply-System-Tweaks icerisinde MessageBox.Show YesNo var
                # Biz Apply'i cagirmadan once bir wrapper yazamayiz dogrudan,
                # bu yuzden Apply'dan once onay biz sorar, Apply'in onayini atlatmayiz —
                # bunun yerine Apply'i cagirip sonucunu kontrol etmek mumkun degil (void).
                # Cozum: Apply cagrilmadan ONCE biz onayi sorup,
                # Hayir ise snapshot restore edip duruyoruz.
                # DIFF analizi (Bonus E2): zaten aktif olanlar vs yeni uygulanacaklar
                $alreadyOn  = 0
                $willChange = 0
                foreach ($snapVal in $snapshot.Values) {
                    if ($snapVal) { $alreadyOn++ } else { $willChange++ }
                }
                $confirmMsg = "$($parts -join ' + ') profili:`n`n" +
                              "  ✅ $alreadyOn tweak zaten aktif (degismeyecek)`n" +
                              "  🆕 $willChange tweak yeni uygulanacak`n`n" +
                              "Toplam $($unique.Count) tweak.`n`n" +
                              "Devam edilsin mi?"
                $confirmRes = [System.Windows.MessageBox]::Show(
                    $confirmMsg, "Profil Uygula",
                    [System.Windows.MessageBoxButton]::YesNo,
                    [System.Windows.MessageBoxImage]::Question)

                if ($confirmRes -ne 'Yes') {
                    # Kullanici Hayir dedi — snapshot'tan geri al
                    foreach ($cat in $tvTweaks.Items) { Restore-Snapshot $cat.Items }
                    return
                }

                # Evet — Apply'in kendi onay penceresini atlamak icin
                # Apply-System-Tweaks'in Scan-Nodes mantigi sadece
                # "isaretli ama aktif degil" veya "aktif ama isaretsiz" olanlari isler.
                # Snapshot'ta false olan tweakler Set-Checks ile true yapildi,
                # bunlar "isaretli ama aktif degil" kategorisine giriyor = uygulanacak.
                # Apply'in kendi onay mesaji bu durumu dogru gosterir.
                Apply-System-Tweaks
            }, [System.Windows.Threading.DispatcherPriority]::Background)
        })

        $winP.ShowDialog() | Out-Null
    } catch {
        [System.Windows.MessageBox]::Show("Pencere açılamadı: $($_.Exception.Message)", "Hata") | Out-Null
    }
}

# ---- Show-ProfileManager ----
# v1.2.25: Profil paylasim modallari — programa uygun WPF (dark theme + PMButton + scrollbar).
# MessageBox yerine XAML kullanilir (tutarli gorunum, renkli tweak listesi, scroll).

# Ortak buton stili XAML parcasi (her iki modal da kullanir)
$global:PMShareBtnStyle = @"
        <!-- v1.3.0 (§70): ortak düğmeden türer (renk ve şablon ortak stil bloğunda). Bu dize çift tırnaklı: buraya dolar işaretiyle değişken adı yazılmaz (§72). -->
        <Style x:Key="ShareBtn" TargetType="Button" BasedOn="{StaticResource SwBtn}"/>
"@

# Disa Aktar kaynak secimi. Donus: 'profile' / 'checked' / 'cancel'
function Show-ExportSourceDialog {
    # v1.3.0 (§71): -Owner = açan pencere (Profil Yöneticisi). Eskiden ana pencereye bağlanıyordu; Profil Yöneticisi
    # modal açıkken ana pencere devre dışı olduğundan bu pencere arkada açılıp yönetici kilitleniyordu.
    # Profil seçili değilse (ProfileName boş) "Seçili profil" seçeneği pasif gösterilir.
    param([string]$ProfileName, [int]$ProfileCount, $Owner)
    $script:_exportChoice = 'cancel'
    $xamlEx = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="@@ex_title@@" Height="280" Width="460"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner" WindowStyle="ToolWindow" ResizeMode="NoResize">
    <Window.Resources>
$($global:SubTheme)
$global:PMShareBtnStyle
    </Window.Resources>
    <Grid Margin="18">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        <TextBlock Grid.Row="0" Text="@@ex_which@@" Foreground="#E6E8EB" FontSize="17" FontWeight="Bold" Margin="0,0,0,6"/>
        <TextBlock Grid.Row="1" Text="@@ex_desc@@" Foreground="#8A919C" FontSize="13" TextWrapping="Wrap" Margin="0,0,0,14"/>
        <StackPanel Grid.Row="2" VerticalAlignment="Top">
            <Button x:Name="btnExSelProfile" Style="{StaticResource SwBtnPrimary}" Height="42" Margin="0,0,0,10" Content="📁 Seçili Profil ($ProfileName · $ProfileCount tweak)"/>
            <Button x:Name="btnExChecked" Style="{StaticResource SwBtnPrimary}" Height="42" Content="@@ex_checked@@"/>
        </StackPanel>
        <Button Grid.Row="3" x:Name="btnExCancel" Style="{StaticResource ShareBtn}" Height="32" MinWidth="100" HorizontalAlignment="Right" Content="@@m_cancel@@"/>
    </Grid>
</Window>
"@
    try {
        $r = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlEx))
        $w = [Windows.Markup.XamlReader]::Load($r)
        Initialize-SubWindow $w
        try { if ($Owner) { $w.Owner = $Owner } else { $w.Owner = $Win } } catch {}
        if ([string]::IsNullOrWhiteSpace($ProfileName)) {
            $bsp = $w.FindName('btnExSelProfile')
            $bsp.IsEnabled = $false
            $bsp.Content = "📁 Seçili profil — önce listeden bir profil seçin"
            # açıklama satırı (Grid'in 2. çocuğu) "Bir profil seçili…" diyordu
            try { $w.Content.Children[1].Text = "Listede seçili profil yok. Şu an Tweaks sekmesinde işaretli olan tweak'leri paylaşabilir ya da önce listeden bir profil seçebilirsin." } catch {}
        }
        $w.FindName('btnExSelProfile').Add_Click({ $script:_exportChoice = 'profile'; $w.Close() })
        $w.FindName('btnExChecked').Add_Click({ $script:_exportChoice = 'checked'; $w.Close() })
        $w.FindName('btnExCancel').Add_Click({ $script:_exportChoice = 'cancel'; $w.Close() })
        [void]$w.ShowDialog()
    } catch { $script:_exportChoice = 'cancel'; try { WpfLog "[HATA] Dışa aktarma penceresi: $($_.Exception.Message)" } catch {} }
    return $script:_exportChoice
}

# Ice Aktar onay penceresi. Donus: 'apply' / 'mark' / 'cancel'
function Show-ImportConfirmDialog {
    # v1.3.0 (§71): -Owner = açan pencere (Profil Yöneticisi); bkz. Show-ExportSourceDialog
    param([string]$ProfileName, [string]$AppVer, $FoundList, $MissingList, $Owner)
    $script:_importChoice = 'cancel'

    # Renkli liste item'lari (found yesil, missing kirmizi)
    $items = New-Object System.Collections.ArrayList
    foreach ($n in $FoundList)   { [void]$items.Add([PSCustomObject]@{ Mark="✓"; Name=$n; Color="#5CD68A" }) }
    foreach ($n in $MissingList) { [void]$items.Add([PSCustomObject]@{ Mark="✗"; Name="$n  (bu sürümde yok - atlanacak)"; Color="#E06666" }) }

    $verLine = if ($AppVer) { "Oluşturulduğu sürüm: v$AppVer" } else { "" }
    $missNote = if ($MissingList.Count -gt 0) { "⚠️ $($MissingList.Count) tweak bu sürümde yok, atlanacak (kırmızı). " } else { "" }

    $xamlIm = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="@@im_title@@" Height="600" Width="560"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner" WindowStyle="ToolWindow" ResizeMode="CanResize" MinHeight="420" MinWidth="440">
    <Window.Resources>
$($global:SubTheme)
$global:PMShareBtnStyle
    </Window.Resources>
    <Grid Margin="16">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <StackPanel Grid.Row="0" Margin="0,0,0,8">
            <TextBlock Text="@@im_importing@@" Foreground="#E6E8EB" FontSize="18" FontWeight="Bold"/>
            <TextBlock Text="Profil: $ProfileName" Foreground="#C9CED6" FontSize="14" Margin="0,4,0,0"/>
            <TextBlock Text="$verLine" Foreground="#8A919C" FontSize="12" Margin="0,2,0,0"/>
        </StackPanel>

        <TextBlock Grid.Row="1" Foreground="#A9B0BB" FontSize="13" Margin="0,0,0,8" TextWrapping="Wrap"
                   Text="Uygulanacak $($FoundList.Count) tweak (yeşil ✓). $missNote"/>

        <Border Grid.Row="2" Background="#15181E" CornerRadius="6" BorderBrush="#232831" BorderThickness="1">
            <ScrollViewer VerticalScrollBarVisibility="Auto" Padding="4">
                <ItemsControl x:Name="icList">
                    <ItemsControl.ItemTemplate>
                        <DataTemplate>
                            <Grid Margin="8,3">
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="Auto"/>
                                    <ColumnDefinition Width="*"/>
                                </Grid.ColumnDefinitions>
                                <TextBlock Grid.Column="0" Text="{Binding Mark}" Foreground="{Binding Color}" FontWeight="Bold" FontSize="14" Margin="0,0,8,0"/>
                                <TextBlock Grid.Column="1" Text="{Binding Name}" Foreground="{Binding Color}" FontSize="13" TextWrapping="Wrap"/>
                            </Grid>
                        </DataTemplate>
                    </ItemsControl.ItemTemplate>
                </ItemsControl>
            </ScrollViewer>
        </Border>

        <TextBlock Grid.Row="3" Foreground="#6B7280" FontSize="12" TextWrapping="Wrap" Margin="0,10,0,0"
                   Text="@@im_security@@"/>

        <Grid Grid.Row="4" Margin="0,12,0,0">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <Button x:Name="btnImApply" Grid.Column="1" Style="{StaticResource SwBtnPrimary}" Height="36" MinWidth="170" Content="@@im_apply@@"/>
            <Button x:Name="btnImMark" Grid.Column="3" Style="{StaticResource SwBtnPrimary}" Height="36" MinWidth="120" Content="@@im_mark@@"/>
            <Button x:Name="btnImCancel" Grid.Column="5" Style="{StaticResource ShareBtn}" Height="36" MinWidth="90" Content="@@m_cancel@@"/>
        </Grid>
    </Grid>
</Window>
"@
    try {
        $r = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlIm))
        $w = [Windows.Markup.XamlReader]::Load($r)
        Initialize-SubWindow $w
        try { if ($Owner) { $w.Owner = $Owner } else { $w.Owner = $Win } } catch {}
        $w.FindName('icList').ItemsSource = $items
        $w.FindName('btnImApply').Add_Click({ $script:_importChoice = 'apply'; $w.Close() })
        $w.FindName('btnImMark').Add_Click({ $script:_importChoice = 'mark'; $w.Close() })
        $w.FindName('btnImCancel').Add_Click({ $script:_importChoice = 'cancel'; $w.Close() })
        if ($FoundList.Count -eq 0) { $w.FindName('btnImApply').IsEnabled = $false; $w.FindName('btnImMark').IsEnabled = $false }
        [void]$w.ShowDialog()
    } catch { $script:_importChoice = 'cancel' }
    return $script:_importChoice
}

function Show-ProfileManager {
    $profileDir = Join-Path $env:APPDATA "MrClean\Profiles"
    if (-not (Test-Path $profileDir)) {
        New-Item -ItemType Directory -Path $profileDir -Force | Out-Null
    }

    function Load-ProfileFiles {
        # v1.2.10: 3 -> 50 profil listele (kullanici eski profilleri silebilsin).
        # Cogu kullanici icin 50 yeterli, daha fazlasi UI kalabalik olur.
        $profiles = @()
        Get-ChildItem $profileDir -Filter "*.json" -ErrorAction SilentlyContinue |
        Sort-Object LastWriteTime -Descending |
        Select-Object -First 50 |
        ForEach-Object {
            try {
                $data = Get-Content $_.FullName -Raw | ConvertFrom-Json
                $profiles += [PSCustomObject]@{
                    Name     = $data.Name
                    Date     = $_.LastWriteTime.ToString("dd.MM.yyyy HH:mm")
                    Count    = $data.Tweaks.Count
                    Tweaks   = $data.Tweaks
                    FilePath = $_.FullName
                }
            } catch {}
        }
        return $profiles
    }

    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="@@pm_title@@" Height="540" Width="560"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="NoResize">
    <Window.Resources>
$($global:SubTheme)
        <!-- Custom Button Style: disabled state okunaklı kalır -->
        <Style x:Key="PMButton" TargetType="Button" BasedOn="{StaticResource SwBtn}"/>
    </Window.Resources>
    <Grid Margin="16">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <TextBlock Grid.Row="0" Text="@@pm_title@@" Foreground="#E6E8EB"
                   FontSize="20" FontWeight="Bold" Margin="0,0,0,4"/>
        <TextBlock Grid.Row="1" Text="@@pm_desc@@"
                   Foreground="#6B7280" FontSize="12" Margin="0,0,0,12" TextWrapping="Wrap"/>

        <!-- PROFİL LİSTESİ -->
        <Border Grid.Row="2" Background="#15181E" CornerRadius="6"
                BorderBrush="#232831" BorderThickness="1">
            <ListBox x:Name="lstProfiles" Background="Transparent" BorderThickness="0"
                     Foreground="#E6E8EB">
                <ListBox.ItemContainerStyle>
                    
                </ListBox.ItemContainerStyle>
                <ListBox.ItemTemplate>
                    <DataTemplate>
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="*"/>
                                <ColumnDefinition Width="Auto"/>
                                <ColumnDefinition Width="Auto"/>
                            </Grid.ColumnDefinitions>
                            <StackPanel Grid.Column="0">
                                <TextBlock Text="{Binding Name}" Foreground="#E6E8EB"
                                           FontWeight="SemiBold" FontSize="14"/>
                                <TextBlock Foreground="#8A919C" FontSize="12">
                                    <Run Text="{Binding Date}"/>
                                    <Run Text="  ·  "/>
                                    <Run Text="{Binding Count}"/>
                                    <Run Text=" tweak"/>
                                </TextBlock>
                            </StackPanel>
                        </Grid>
                    </DataTemplate>
                </ListBox.ItemTemplate>
            </ListBox>
        </Border>

        <!-- KAYDET BÖLÜMÜ -->
        <Border Grid.Row="3" Background="#15181E" CornerRadius="6"
                BorderBrush="#232831" BorderThickness="1"
                Padding="12,10" Margin="0,8,0,0">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="8"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <TextBox x:Name="txtProfileName" Grid.Column="0"
                         Background="#13161B" Foreground="#E6E8EB"
                         BorderBrush="#232831" BorderThickness="1"
                         Padding="8,4" MinHeight="32" VerticalContentAlignment="Center"
                         Text="Profilim"/>
                <Button x:Name="btnSave" Grid.Column="2"
                        Style="{StaticResource SwBtnPrimary}"
                        Content="💾 Kaydet" Height="32" MinWidth="100"
                       />
            </Grid>
        </Border>

        <!-- PAYLAŞIM BUTONLARI (v1.2.25) -->
        <Grid Grid.Row="4" Margin="0,8,0,0">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <Button x:Name="btnExportProfile" Grid.Column="0"
                    Style="{StaticResource SwBtnPrimary}"
                    Content="📤 Dışa Aktar (Paylaş)" Height="32"
                   
                    ToolTip="İşaretli tweak'leri veya seçili profili .json olarak kaydet — başka biriyle paylaş"/>
            <Button x:Name="btnImportProfile" Grid.Column="2"
                    Style="{StaticResource PMButton}"
                    Content="📥 İçe Aktar" Height="32" MinWidth="140"
                   
                    ToolTip="Birinin paylaştığı profil .json dosyasını yükle — içeriği önce gösterilir, sonra onaylarsın"/>
        </Grid>

        <!-- ALT BUTONLAR -->
        <Grid Grid.Row="5" Margin="0,8,0,0">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <TextBlock x:Name="txtPMStatus" Grid.Column="0"
                       Text="" Foreground="#8A919C" FontSize="12"
                       VerticalAlignment="Center"/>
            <Button x:Name="btnDelete" Grid.Column="2"
                    Style="{StaticResource SwBtnDanger}"
                    Content="🗑️ Sil" Height="34" MinWidth="80"
                    IsEnabled="False"
                    ToolTip="Seçili profili kalıcı olarak sil"/>
            <Button x:Name="btnLoad" Grid.Column="4"
                    Style="{StaticResource SwBtnPrimary}"
                    Content="📂 Yükle" Height="34" MinWidth="100"
                    IsEnabled="False"/>
            <Button x:Name="btnPMClose" Grid.Column="6"
                    Style="{StaticResource PMButton}"
                    Content="@@m_close@@" Height="34" MinWidth="80"
                   />
        </Grid>
    </Grid>
</Window>
"@

    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xaml))
        $winPM  = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winPM
        $winPM.Owner = $Win

        $lstP    = $winPM.FindName('lstProfiles')
        $txtName = $winPM.FindName('txtProfileName')
        $btnSv   = $winPM.FindName('btnSave')
        $btnLd   = $winPM.FindName('btnLoad')
        $btnDel  = $winPM.FindName('btnDelete')
        $btnCl   = $winPM.FindName('btnPMClose')
        $txtStat = $winPM.FindName('txtPMStatus')
        $btnExp  = $winPM.FindName('btnExportProfile')
        $btnImp  = $winPM.FindName('btnImportProfile')

        function Refresh-List {
            $lstP.Items.Clear()
            $profiles = Load-ProfileFiles
            if ($profiles.Count -eq 0) {
                $txtStat.Text = "Henüz kayıtlı profil yok."
            } else {
                foreach ($p in $profiles) { $lstP.Items.Add($p) | Out-Null }
                $txtStat.Text = "$($profiles.Count) profil"
            }
        }
        Refresh-List

        $lstP.Add_SelectionChanged({
            $hasSel = ($null -ne $lstP.SelectedItem)
            $btnLd.IsEnabled  = $hasSel
            $btnDel.IsEnabled = $hasSel
        })

        # Sil: secili profili kalici kaldir (onay sorulur)
        $btnDel.Add_Click({
            $sel = $lstP.SelectedItem
            if (-not $sel) { return }
            $confirm = [System.Windows.MessageBox]::Show(
                ("'{0}' profili kalıcı olarak silinecek.`n`nDosya: {1}`n`nDevam edilsin mi?" -f $sel.Name, $sel.FilePath),
                "Profil Sil",
                [System.Windows.MessageBoxButton]::YesNo,
                [System.Windows.MessageBoxImage]::Warning)
            if ($confirm -ne 'Yes') { return }
            try {
                Remove-Item -Path $sel.FilePath -Force -ErrorAction Stop
                $txtStat.Text = ("🗑️ '{0}' silindi." -f $sel.Name)
                Refresh-List
                $btnDel.IsEnabled = $false
                $btnLd.IsEnabled  = $false
            } catch {
                [System.Windows.MessageBox]::Show(
                    ("Profil silinemedi: {0}" -f $_.Exception.Message),
                    "Hata", "OK", "Error") | Out-Null
            }
        })

        # Kaydet
        $btnSv.Add_Click({
            $name = $txtName.Text.Trim()
            if ([string]::IsNullOrWhiteSpace($name)) {
                $txtStat.Text = "Profil adı boş olamaz."
                return
            }

            # Şu an işaretli tweak isimlerini topla
            $tweakNames = @()
            foreach ($cat in $tvTweaks.Items) {
                function ScanSave($nodes) {
                    foreach ($node in $nodes) {
                        if ($node.Tag -is [System.Collections.IDictionary] -or
                            $node.Tag -is [System.Management.Automation.PSCustomObject]) {
                            if ((Get-CheckFromItem $node).IsChecked) {
                                $script:_savedTweaks += $node.Tag.Name
                            }
                        }
                        if ($node.Items.Count -gt 0) { ScanSave $node.Items }
                    }
                }
                $script:_savedTweaks = @()
                ScanSave $cat.Items
                $tweakNames += $script:_savedTweaks
            }

            $safeFileName = ($name -replace '[\\/:*?"<>|]', '_') + "_$(Get-Date -Format 'yyyyMMdd_HHmm').json"
            $filePath = Join-Path $profileDir $safeFileName
            $data = @{ Name=$name; Date=(Get-Date -Format "yyyy-MM-dd HH:mm"); Tweaks=$tweakNames }
            $data | ConvertTo-Json -Depth 3 | Set-Content $filePath -Encoding UTF8

            $txtStat.Text = "✅ '$name' kaydedildi ($($tweakNames.Count) tweak)."
            Refresh-List
        })

        # Yükle (sadece checkbox işaretle, uygulamaz)
        $btnLd.Add_Click({
            $sel = $lstP.SelectedItem
            if (-not $sel) { return }

            $loaded = 0
            foreach ($cat in $tvTweaks.Items) {
                function ScanLoad($nodes) {
                    foreach ($node in $nodes) {
                        if ($node.Tag -is [System.Collections.IDictionary] -or
                            $node.Tag -is [System.Management.Automation.PSCustomObject]) {
                            $chk = Get-CheckFromItem $node
                            if ($sel.Tweaks -contains $node.Tag.Name) {
                                $chk.IsChecked = $true
                                $script:_loadCount++
                            } else {
                                $chk.IsChecked = $false
                            }
                        }
                        if ($node.Items.Count -gt 0) { ScanLoad $node.Items }
                    }
                }
                $script:_loadCount = 0
                ScanLoad $cat.Items
                $loaded += $script:_loadCount
            }

            $winPM.Close()
            [System.Windows.MessageBox]::Show(
                "'$($sel.Name)' profili yüklendi.`n$loaded tweak işaretlendi.`n`nUYGULA butonuna basarak sisteme uygulayabilirsiniz.",
                "Profil Yüklendi",
                [System.Windows.MessageBoxButton]::OK,
                [System.Windows.MessageBoxImage]::Information) | Out-Null
        })

        # v1.2.25: O an tvTweaks'te isaretli tweak isimlerini topla (btnSave ScanSave ile ayni mantik)
        function Get-CheckedTweakNames {
            $names = @()
            foreach ($cat in $tvTweaks.Items) {
                function ScanChk($nodes) {
                    foreach ($node in $nodes) {
                        if ($node.Tag -is [System.Collections.IDictionary] -or
                            $node.Tag -is [System.Management.Automation.PSCustomObject]) {
                            if ((Get-CheckFromItem $node).IsChecked) { $script:_chkNames += $node.Tag.Name }
                        }
                        if ($node.Items.Count -gt 0) { ScanChk $node.Items }
                    }
                }
                $script:_chkNames = @()
                ScanChk $cat.Items
                $names += $script:_chkNames
            }
            return $names
        }

        # v1.2.25: DISA AKTAR — isaretli tweak'ler VEYA secili profil -> .json (paylasilabilir)
        $btnExp.Add_Click({
            $sel = $lstP.SelectedItem
            # v1.3.0 (§71): kaynak her zaman sorulur (profil seçili değilse o seçenek pasif); sahip Profil Yöneticisi
            $pName = ''; $pCount = 0
            if ($sel) { $pName = $sel.Name; $pCount = $sel.Count }
            $choice = Show-ExportSourceDialog -ProfileName $pName -ProfileCount $pCount -Owner $winPM
            if ($choice -eq 'cancel') { return }
            $useProfile = ($sel -and $choice -eq 'profile')

            if ($useProfile) {
                $expName = $sel.Name
                $expTweaks = @($sel.Tweaks)
            } else {
                $expName = $txtName.Text.Trim(); if ([string]::IsNullOrWhiteSpace($expName)) { $expName = "Paylasilan Profil" }
                $expTweaks = @(Get-CheckedTweakNames)
            }

            if ($expTweaks.Count -eq 0) {
                [System.Windows.MessageBox]::Show("Aktarilacak tweak yok (hic isaretli tweak yok veya profil bos).", "Uyari", "OK", "Warning") | Out-Null
                return
            }

            $sfd = New-Object Microsoft.Win32.SaveFileDialog
            $sfd.Filter = "MrClean Profil Dosyasi (*.json)|*.json"
            $sfd.FileName = (($expName -replace '[\\/:*?"<>|]', '_') + ".json")
            if ($sfd.ShowDialog() -eq $true) {
                try {
                    $data = @{ Name=$expName; Date=(Get-Date -Format "yyyy-MM-dd HH:mm"); Tweaks=$expTweaks; AppVersion=$global:AppVersion }
                    $data | ConvertTo-Json -Depth 3 | Set-Content $sfd.FileName -Encoding UTF8
                    [System.Windows.MessageBox]::Show(
                        ("Profil disa aktarildi.`n`n  Ad: {0}`n  Tweak: {1}`n  Dosya: {2}`n`nBu dosyayi baska biriyle paylasabilirsin." -f $expName, $expTweaks.Count, $sfd.FileName),
                        "Başarılı", "OK", "Information") | Out-Null
                } catch {
                    [System.Windows.MessageBox]::Show("Dosya yazma hatasi: $($_.Exception.Message)", "Hata", "OK", "Error") | Out-Null
                }
            }
        })

        # v1.2.25: ICE AKTAR — paylasilan .json -> onay penceresi (liste+total+eksik uyari) -> uygula/isaretle
        $btnImp.Add_Click({
            $ofd = New-Object Microsoft.Win32.OpenFileDialog
            $ofd.Filter = "MrClean Profil Dosyasi (*.json)|*.json"
            if ($ofd.ShowDialog() -ne $true) { return }
            try {
                $imp = Get-Content $ofd.FileName -Raw -ErrorAction Stop | ConvertFrom-Json
            } catch {
                [System.Windows.MessageBox]::Show("Dosya okunamadi veya gecersiz JSON: $($_.Exception.Message)", "Hata", "OK", "Error") | Out-Null
                return
            }
            $impName = if ($imp.Name) { [string]$imp.Name } else { "Bilinmeyen" }
            $impTweaks = @($imp.Tweaks)
            if ($impTweaks.Count -eq 0) {
                [System.Windows.MessageBox]::Show("Dosyada tweak bulunamadi (gecersiz veya bos profil).", "Uyari", "OK", "Warning") | Out-Null
                return
            }

            # Sende olan / olmayan tweak'leri ayir (Find-TweakByName cross-check — guvenlik: sadece isim eslesir)
            $found = New-Object System.Collections.ArrayList
            $missing = New-Object System.Collections.ArrayList
            foreach ($tn in $impTweaks) {
                if (Find-TweakByName $tn) { [void]$found.Add($tn) } else { [void]$missing.Add($tn) }
            }

            # XAML onay penceresi (renkli liste + scroll + dark theme)
            $resp = Show-ImportConfirmDialog -ProfileName $impName -AppVer $imp.AppVersion -FoundList $found -MissingList $missing -Owner $winPM
            if ($resp -eq 'cancel') { return }
            if ($found.Count -eq 0) {
                [System.Windows.MessageBox]::Show("Uygulanabilir tweak yok (hepsi bu surumde eksik).", "Uyari", "OK", "Warning") | Out-Null
                return
            }

            # tvTweaks'te ilgili tweak'leri isaretle
            $marked = 0
            foreach ($cat in $tvTweaks.Items) {
                function ScanMark($nodes) {
                    foreach ($node in $nodes) {
                        if ($node.Tag -is [System.Collections.IDictionary] -or
                            $node.Tag -is [System.Management.Automation.PSCustomObject]) {
                            if ($found -contains $node.Tag.Name) {
                                (Get-CheckFromItem $node).IsChecked = $true
                                $script:_markCount++
                            }
                        }
                        if ($node.Items.Count -gt 0) { ScanMark $node.Items }
                    }
                }
                $script:_markCount = 0
                ScanMark $cat.Items
                $marked += $script:_markCount
            }

            $winPM.Close()
            if ($resp -eq 'apply') {
                # Hemen uygula
                Apply-System-Tweaks
            } else {
                [System.Windows.MessageBox]::Show("$marked tweak isaretlendi.`n`nTweaks sekmesinde UYGULA butonuna basarak sisteme uygulayabilirsin.", "İçe Aktarildi", "OK", "Information") | Out-Null
            }
        })

        $btnCl.Add_Click({ $winPM.Close() })
        $winPM.ShowDialog() | Out-Null
    } catch {
        [System.Windows.MessageBox]::Show("Pencere açılamadı: $($_.Exception.Message)", "Hata") | Out-Null
    }
}

# ---- Check-BlackBoxStatus ----
function Check-BlackBoxStatus {
    $isEnabled = $true
    $reasons = @()

    # 1. WER Servisi
    $werSvc = Get-Service -Name "WerSvc" -ErrorAction SilentlyContinue
    if ($werSvc -and $werSvc.StartType -eq 'Disabled') {
        $isEnabled = $false
        $reasons += (T 'cr_bb_r_wer')
    }

    # 2. Mavi ekran dökümü. CrashDumpEnabled: 0=Kapalı, 1=Tam, 2=Çekirdek, 3=Küçük (minidump), 7=Otomatik (Windows varsayılanı).
    # Mavi ekran analizi için minidump yeterli; yalnız 0 (ya da değer yok) eksik sayılır. LogEvent=0 ise mavi ekran olay günlüğüne yazılmaz.
    $crashReg = Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl" -ErrorAction SilentlyContinue
    if ($null -eq $crashReg -or $null -eq $crashReg.CrashDumpEnabled -or $crashReg.CrashDumpEnabled -eq 0) {
        $isEnabled = $false
        $reasons += (T 'cr_bb_r_bsod')
    }
    if ($crashReg -and $null -ne $crashReg.LogEvent -and $crashReg.LogEvent -eq 0) {
        $isEnabled = $false
        $reasons += (T 'cr_bb_r_log')
    }
    $baseOk = $isEnabled

    # 3. Local Dumps (uygulama/oyun çökmeleri) — Windows'ta varsayılan kapalı
    $dumpReg = Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\Windows Error Reporting\LocalDumps" -Name "DumpType" -ErrorAction SilentlyContinue
    if ($null -eq $dumpReg -or $dumpReg.DumpType -notin @(1, 2)) {
        $isEnabled = $false
        $reasons += (T 'cr_bb_r_dmp')
    }

    # Arayüzü Güncelle
    $bc = New-Object System.Windows.Media.BrushConverter
    if ($isEnabled) {
        $shpBlackBoxStatus.Fill = $bc.ConvertFromString('#3FB97A')
        $txtBlackBoxStatus.Text = T 'cr_bb_ok'
        $btnFixBlackBox.Content = T 'cr_bb_disable'
        $btnFixBlackBox.Tag = "on"
    } elseif ($baseOk) {
        $shpBlackBoxStatus.Fill = $bc.ConvertFromString('#4C8DFF')
        $txtBlackBoxStatus.Text = T 'cr_bb_basic'
        $btnFixBlackBox.Content = T 'cr_bb_enable'
        $btnFixBlackBox.Tag = "off"
    } else {
        $shpBlackBoxStatus.Fill = $bc.ConvertFromString('#E0A23B')
        $txtBlackBoxStatus.Text = (T 'cr_bb_missing') -f ($reasons -join ', ')
        $btnFixBlackBox.Content = T 'cr_bb_enable'
        $btnFixBlackBox.Tag = "off"
    }
    $btnFixBlackBox.Visibility = "Visible"
}

# ---- Start-ShutdownCountdown ----
function Start-ShutdownCountdown {
    $global:NightModeActive = $false
    if ($global:NightModeTimer) { $global:NightModeTimer.Stop() }
    
    $Win.Dispatcher.Invoke([action]{
        $btnNightMode.Content = "🌙 Shutdown"
        $btnNightMode.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#A9B0BB')
        
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlCountdown))
        $winCount = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winCount
        
        $txtSec = $winCount.FindName('txtSeconds')
        $btnAbort = $winCount.FindName('btnAbort')
        
        $script:timeLeft = 60
        $cdTimer = New-Object System.Windows.Threading.DispatcherTimer
        $cdTimer.Interval =[TimeSpan]::FromSeconds(1)
        
        $cdTimer.Add_Tick({
            $script:timeLeft--
            $txtSec.Text = $script:timeLeft.ToString()
            if ($script:timeLeft -le 0) {
                $cdTimer.Stop()
                $winCount.Close()
                # ZORLA KAPATMA KOMUTU
                Start-Process shutdown.exe -ArgumentList "/s /f /t 0" -WindowStyle Hidden
            }
        })
        
        $btnAbort.Add_Click({
            $cdTimer.Stop()
            $winCount.Close()
            WpfLog "🌙 [GECE MODU] Geri sayım kullanıcı tarafından İPTAL EDİLDİ."
        })
        
        $cdTimer.Start()
        $winCount.ShowDialog() | Out-Null
    })
}

# ---- Show-Winapp2Editor ----
function Show-Winapp2Editor {
    $xamlEdit = @"
    <Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
            xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
            Title="@@we_title@@" Height="600" Width="700" 
            Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterScreen" WindowStyle="ToolWindow">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
        <Grid Margin="15">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="5"/>
                <RowDefinition Height="200"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            
            <!-- ARAMA -->
            <StackPanel Grid.Row="0">
                <TextBlock Text="@@we_search@@" Foreground="#8CB4FF" FontWeight="Bold" Margin="0,0,0,5"/>
                <Grid>
                    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="80"/></Grid.ColumnDefinitions>
                    <TextBox x:Name="txtSearch" Padding="5" Background="#15181E" Foreground="#E6E8EB" Text=""/>
                    <Button Style="{StaticResource SwBtnPrimary}" x:Name="btnSearch" Grid.Column="1" Content="@@we_find@@" Margin="5,0,0,0"/>
                </Grid>
                <TextBlock Text="@@we_results@@" Foreground="#A9B0BB" Margin="0,10,0,5"/>
            </StackPanel>

            <!-- SONUÇ LİSTESİ -->
            <ListBox x:Name="lstResults" Grid.Row="1" Background="#0C0E12" Foreground="#E6E8EB" BorderBrush="#232831"/>

            <GridSplitter Grid.Row="2" HorizontalAlignment="Stretch" Background="#1D2129"/>

            <!-- EDİTÖR -->
            <Grid Grid.Row="3">
                <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
                <TextBlock Text="@@we_editlabel@@" Foreground="#E0A23B" FontWeight="Bold" Margin="0,5,0,5"/>
                <TextBox x:Name="txtContent" Grid.Row="1" AcceptsReturn="True" Background="#15181E" Foreground="#3FB97A" FontFamily="Cascadia Mono, Consolas" Padding="5" VerticalScrollBarVisibility="Auto"/>
            </Grid>

            <!-- BUTONLAR -->
            <StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,15,0,0">
                <Button Style="{StaticResource SwBtnDanger}" x:Name="btnDeleteOverride" Content="@@we_deleteoverride@@" MinWidth="150" Margin="0,0,10,0" Visibility="Collapsed"/>
                <Button Style="{StaticResource SwBtnPrimary}" x:Name="btnSave" Content="@@we_saveexit@@" FontWeight="Bold" MinWidth="120" Height="30"/>
            </StackPanel>
        </Grid>
    </Window>
"@
    
    $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlEdit))
    $winEd = [Windows.Markup.XamlReader]::Load($reader)
    Initialize-SubWindow $winEd
    
    $txtS = $winEd.FindName('txtSearch'); $btnS = $winEd.FindName('btnSearch')
    $lst = $winEd.FindName('lstResults'); $txtC = $winEd.FindName('txtContent')
    $btnSave = $winEd.FindName('btnSave'); $btnDel = $winEd.FindName('btnDeleteOverride')

    $btnS.Add_Click({
        $k = $txtS.Text; if (-not $k -or -not (Test-Path $global:Winapp2Path)) { return }
        $lst.Items.Clear()
        $content = [System.IO.File]::ReadAllText($global:Winapp2Path)
        $matches = [regex]::Matches($content, "\[.*?$k.*?\]", "IgnoreCase")
        foreach ($m in $matches) { $lst.Items.Add($m.Value) | Out-Null }
    })

    $lst.Add_SelectionChanged({
        if ($lst.SelectedItem) {
            $appName = $lst.SelectedItem.ToString().Trim('[]')
            
            if ($global:PathOverrides.ContainsKey($appName)) {
                $rawLines = $global:PathOverrides[$appName]
                if ($rawLines -is [string]) { $txtC.Text = $rawLines }
                elseif ($rawLines -is [Array]) { $txtC.Text = $rawLines -join "`r`n" }
                
                $btnDel.Visibility = "Visible"
                $btnSave.Content = "GÜNCELLE"
            } 
            else {
                $lines = [System.IO.File]::ReadAllLines($global:Winapp2Path)
                $block = @()
                $capture = $false
                foreach ($line in $lines) {
                    if ($line.Trim() -eq "[$appName]") { $capture = $true; continue }
                    if ($capture) {
                        if ($line.StartsWith("[")) { break }
                        if ($line.Trim() -ne "") { $block += $line }
                    }
                }
                $txtC.Text = $block -join "`r`n"
                $btnDel.Visibility = "Collapsed"
                $btnSave.Content = "KAYDET"
            }
        }
    })

    $btnSave.Add_Click({
        if ($lst.SelectedItem) {
            $appName = $lst.SelectedItem.ToString().Trim('[]')
            
            # DÜZELTME: Satırları bölerken daha esnek bir ayırıcı kullanıldı
            $newRules = $txtC.Text -split "\r?\n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
            
            $global:PathOverrides[$appName] = $newRules
            Mark-ConfigDirty
            [System.Windows.MessageBox]::Show("'$appName' için özel ayarlar kaydedildi.`nAna menüdeki Güncelle -> Listeyi Yenile butonuna basarak görebilirsiniz.", "Başarılı") | Out-Null
            $winEd.Close()
        }
    })

    $btnDel.Add_Click({
        if ($lst.SelectedItem) {
            $appName = $lst.SelectedItem.ToString().Trim('[]')
            if ($global:PathOverrides.ContainsKey($appName)) {
                $global:PathOverrides.Remove($appName)
                Mark-ConfigDirty
                [System.Windows.MessageBox]::Show("Özel ayar silindi. Orijinal Winapp2 ayarlarına dönüldü.", "Bilgi") | Out-Null
                $winEd.Close()
            }
        }
    })

    $winEd.ShowDialog() | Out-Null
}

# ---- GERI BILDIRIM (v1.2.3) ----
# Send-Feedback: form alanlarindan + (opsiyonel) sistem bilgilerinden Discord embed JSON olustur, webhook'a POST.
# JSON manuel string olarak compose ediliyor (PS5.1 ConvertTo-Json bazi nested array'leri yanlis serialize ediyor).
function Send-Feedback {
    param(
        [Parameter(Mandatory=$true)] [string]$Type,    # bug | suggestion | question
        [Parameter(Mandatory=$true)] [string]$Title,
        [Parameter(Mandatory=$true)] [string]$Body,
        [string]$Email = "",
        [bool]$IncludeSystemInfo = $true
    )

    if ([string]::IsNullOrWhiteSpace($global:FeedbackWebhookUrl)) {
        return @{ Success = $false; Error = "Webhook URL tanimli degil." }
    }

    # Tip mapping
    $emoji = "🐛"; $color = 16711680  # bug = kirmizi
    if ($Type -eq "suggestion") { $emoji = "💡"; $color = 3447003 }  # mavi
    elseif ($Type -eq "question") { $emoji = "❓"; $color = 16776960 }  # sari
    $typeLabel = if ($Type -eq "bug") { "Hata" } elseif ($Type -eq "suggestion") { "Öneri" } else { "Soru" }

    # JSON-safe escape (control chars + quotes + backslash) -- String overload (Char overload bos string kabul etmez)
    function _Esc($s) {
        if ($null -eq $s) { return "" }
        $r = $s.ToString()
        $r = $r.Replace('\', '\\').Replace('"', '\"').Replace("`r", "").Replace("`n", '\n').Replace("`t", '\t')
        return $r
    }

    # v1.2.27: Discord embed limitleri — asilirsa 400 "Bad Request". Once kirp, SONRA escape.
    # title <= 256, description <= 4096. Guvenli payda biraz altinda tutariz.
    $titleRaw = "$emoji [$typeLabel] $Title"
    if ($titleRaw.Length -gt 240) { $titleRaw = $titleRaw.Substring(0, 240) + "..." }
    $bodyRaw = $Body
    if ($bodyRaw.Length -gt 3800) { $bodyRaw = $bodyRaw.Substring(0, 3800) + "`n...(mesaj çok uzun, kısaltıldı)" }
    $titleEsc = _Esc $titleRaw
    $bodyEsc  = _Esc $bodyRaw

    # Embed fields — PowerShell single-quoted string + concatenation, double quote escape gerekmiyor
    $fieldsArr = @()
    if ($IncludeSystemInfo) {
        # Win surumu
        $winInfo = "?"
        try {
            $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
            if ($os) { $winInfo = "$($os.Caption) (Build $($os.BuildNumber))" }
        } catch {}
        $winEsc = _Esc $winInfo
        $fieldsArr += '{"name":"Windows","value":"' + $winEsc + '","inline":true}'

        # MrClean surumu
        $verEsc = _Esc "v$($global:AppVersion)"
        $fieldsArr += '{"name":"MrClean","value":"' + $verEsc + '","inline":true}'

        # Son 30 log satiri
        try {
            $logLines = @()
            if ($txtLog -and $txtLog.Text) {
                $allLines = $txtLog.Text -split "`r?`n"
                $tail = $allLines | Select-Object -Last 30
                $logLines = $tail | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
            }
            if ($logLines.Count -gt 0) {
                $logText = ($logLines -join "`n")
                # Discord field max 1024 char (markdown code block ile birlikte)
                if ($logText.Length -gt 980) { $logText = $logText.Substring(0, 980) + "..." }
                $logWithFences = "``````" + "`n" + $logText + "`n" + "``````"
                $logEsc = _Esc $logWithFences
                $fieldsArr += '{"name":"Son log satirlari","value":"' + $logEsc + '","inline":false}'
            }
        } catch {}
    }
    if (-not [string]::IsNullOrWhiteSpace($Email)) {
        $emailEsc = _Esc $Email
        $fieldsArr += '{"name":"E-posta","value":"' + $emailEsc + '","inline":false}'
    }

    $fieldsJson = if ($fieldsArr.Count -gt 0) { ',"fields":[' + ($fieldsArr -join ',') + ']' } else { '' }
    $tsIso = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ss.fffZ")

    # Final embed JSON (manuel compose — single-quoted concatenation, escape derdi yok)
    $payload = '{"embeds":[{"title":"' + $titleEsc + '","description":"' + $bodyEsc + '","color":' + $color + $fieldsJson + ',"timestamp":"' + $tsIso + '"}]}'

    try {
        # KRITIK: PS5.1 Invoke-RestMethod string body'i ANSI olarak encode eder.
        # Turkce/emoji karakterler bozulur -> Discord 400 "Bad Request". UTF-8 byte array zorunlu.
        $payloadBytes = [System.Text.Encoding]::UTF8.GetBytes($payload)
        Invoke-RestMethod -Uri $global:FeedbackWebhookUrl -Method Post -Body $payloadBytes -ContentType 'application/json; charset=utf-8' -ErrorAction Stop | Out-Null
        return @{ Success = $true }
    } catch {
        return @{ Success = $false; Error = $_.Exception.Message }
    }
}

# Show-FeedbackWindow: modal form'u acar
function Show-FeedbackWindow {
    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlFeedback))
        $winFb = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winFb

        $cb       = $winFb.FindName('cbFeedbackType')
        $title    = $winFb.FindName('txtFeedbackTitle')
        $body     = $winFb.FindName('txtFeedbackBody')
        $email    = $winFb.FindName('txtFeedbackEmail')
        $chkSys   = $winFb.FindName('chkIncludeSystem')
        $lblStat  = $winFb.FindName('lblFeedbackStatus')
        $btnSend  = $winFb.FindName('btnFeedbackSend')
        $btnCanc  = $winFb.FindName('btnFeedbackCancel')
        $btnClip  = $winFb.FindName('btnFeedbackClipboard')
        $btnGH    = $winFb.FindName('btnFeedbackGitHub')

        $btnCanc.Add_Click({ $winFb.Close() })

        # v1.2.7: Form icerigini "plain text" olarak compose eden helper — script: scope ki Add_Click handler'lari erisebilsin.
        $script:_BuildFeedbackBody = {
            $tagItem = $cb.SelectedItem
            $typeLabel = if ($tagItem.Tag -eq "bug") { "🐛 Hata" } elseif ($tagItem.Tag -eq "suggestion") { "💡 Öneri" } else { "❓ Soru" }
            $lines = @()
            $lines += "## $typeLabel"
            $lines += ""
            $lines += $body.Text.Trim()
            $lines += ""
            if (-not [string]::IsNullOrWhiteSpace($email.Text)) {
                $lines += "**E-posta**: $($email.Text.Trim())"
                $lines += ""
            }
            if ($chkSys.IsChecked) {
                $winInfo = "?"
                try {
                    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
                    if ($os) { $winInfo = "$($os.Caption) (Build $($os.BuildNumber))" }
                } catch {}
                $lines += "---"
                $lines += "**Sistem bilgileri**"
                $lines += "- Windows: $winInfo"
                $lines += "- MrClean: v$($global:AppVersion)"
                try {
                    if ($txtLog -and $txtLog.Text) {
                        $allLines = $txtLog.Text -split "`r?`n"
                        $tail = $allLines | Select-Object -Last 30 | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                        if ($tail.Count -gt 0) {
                            $lines += ""
                            $lines += "**Son log satırları:**"
                            $lines += '```'
                            $lines += $tail
                            $lines += '```'
                        }
                    }
                } catch {}
            }
            return ($lines -join "`r`n")
        }

        # 📋 PANOYA KOPYALA (her zaman calisir, internet/Discord gerekmez)
        $btnClip.Add_Click({
            $titleVal = $title.Text.Trim()
            if ([string]::IsNullOrWhiteSpace($titleVal)) {
                $lblStat.Foreground = '#FF6B6B'; $lblStat.Text = "Başlık boş olamaz."; return
            }
            try {
                $plainBody = & $script:_BuildFeedbackBody
                $full = "# $titleVal`r`n`r`n$plainBody"
                [System.Windows.Clipboard]::SetText($full)
                $lblStat.Foreground = '#90EE90'; $lblStat.Text = "✅ Panoya kopyalandı — istediğiniz yere yapıştırın."
            } catch {
                $lblStat.Foreground = '#FF6B6B'; $lblStat.Text = "❌ Kopyalama hatası: $($_.Exception.Message)"
            }
        })

        # 🐙 GITHUB ISSUE — pre-filled URL ile tarayicida ac (Discord erisimi olmayanlar icin)
        $btnGH.Add_Click({
            $titleVal = $title.Text.Trim()
            if ([string]::IsNullOrWhiteSpace($titleVal) -or $titleVal.Length -lt 3) {
                $lblStat.Foreground = '#FF6B6B'; $lblStat.Text = "Başlık en az 3 karakter olmalı."; return
            }
            try {
                Add-Type -AssemblyName System.Web -ErrorAction SilentlyContinue
                $tagItem = $cb.SelectedItem
                $label = if ($tagItem.Tag -eq "bug") { "bug" } elseif ($tagItem.Tag -eq "suggestion") { "enhancement" } else { "question" }
                $plainBody = & $script:_BuildFeedbackBody
                $encodedTitle = [System.Web.HttpUtility]::UrlEncode($titleVal)
                $encodedBody  = [System.Web.HttpUtility]::UrlEncode($plainBody)
                $url = "https://github.com/$($global:AppRepo)/issues/new?title=$encodedTitle&body=$encodedBody&labels=$label"

                # v1.2.27 FIX: Cok uzun URL (log satirlari encode edilince binlerce char) ShellExecute
                # sinirini asip "Sistem belirtilen dosyayi bulamiyor" hatasi veriyordu. GitHub pratik
                # limiti ~8000. Asilirsa body'yi kisalt (log'u at), title+mesaj kalsin; log icin
                # "Panoya Kopyala" onerilir.
                $trimmed = $false
                if ($url.Length -gt 7500) {
                    $shortBody = "$($body.Text.Trim())`r`n`r`n_(Sistem bilgileri/log cok uzun oldugu icin URL'e sigmadi — detay icin 'Panoya Kopyala' kullanip issue'ya yapistirin.)_"
                    $encodedBody = [System.Web.HttpUtility]::UrlEncode($shortBody)
                    $url = "https://github.com/$($global:AppRepo)/issues/new?title=$encodedTitle&body=$encodedBody&labels=$label"
                    $trimmed = $true
                }
                # Hala uzunsa (cok uzun mesaj) tamamen kis
                if ($url.Length -gt 7500) {
                    $url = "https://github.com/$($global:AppRepo)/issues/new?title=$encodedTitle&labels=$label"
                    $trimmed = $true
                }

                Start-Process $url
                if ($trimmed) {
                    $lblStat.Foreground = '#E68A00'; $lblStat.Text = "⚠️ Tarayıcı açıldı (mesaj uzun olduğu için kısaltıldı — log için Panoya Kopyala)."
                } else {
                    $lblStat.Foreground = '#90EE90'; $lblStat.Text = "✅ Tarayıcı açıldı — GitHub'da Submit edin."
                }
            } catch {
                $lblStat.Foreground = '#FF6B6B'; $lblStat.Text = "❌ GitHub açılamadı: $($_.Exception.Message)"
            }
        })

        $btnSend.Add_Click({
            $titleVal = $title.Text.Trim()
            $bodyVal  = $body.Text.Trim()
            if ([string]::IsNullOrWhiteSpace($titleVal) -or $titleVal.Length -lt 3) {
                $lblStat.Foreground = '#FF6B6B'; $lblStat.Text = "Başlık en az 3 karakter olmalı."; return
            }
            if ([string]::IsNullOrWhiteSpace($bodyVal) -or $bodyVal.Length -lt 10) {
                $lblStat.Foreground = '#FF6B6B'; $lblStat.Text = "Mesaj en az 10 karakter olmalı."; return
            }

            $tag = ($cb.SelectedItem.Tag).ToString()
            $btnSend.IsEnabled = $false; $btnCanc.IsEnabled = $false
            $lblStat.Foreground = '#888'; $lblStat.Text = "Gönderiliyor..."
            Do-Events

            $result = Send-Feedback -Type $tag -Title $titleVal -Body $bodyVal -Email $email.Text.Trim() -IncludeSystemInfo $chkSys.IsChecked

            if ($result.Success) {
                $lblStat.Foreground = '#90EE90'; $lblStat.Text = "✅ Gönderildi. Teşekkürler!"
                $btnSend.Content = "✅ Gönderildi"
                Start-Sleep -Milliseconds 1500
                $winFb.Close()
            } else {
                $lblStat.Foreground = '#FF6B6B'; $lblStat.Text = "❌ Hata: $($result.Error)"
                $btnSend.IsEnabled = $true; $btnCanc.IsEnabled = $true
            }
        })

        $winFb.ShowDialog() | Out-Null
    } catch {
        WpfLog "[HATA] Geri Bildirim penceresi: $($_.Exception.Message)"
    }
}

# ---- Show-AppUpdateWindow (Otomatik program guncellemesi, Show-UpdateWindow Winapp2 icin) ----
function Show-AppUpdateWindow {
    if (-not $global:UpdateAvailable) {
        [System.Windows.MessageBox]::Show("Su an icin yeni bir surum yok veya kontrol henuz tamamlanmadi.", "Guncelleme Yok", "OK", "Information") | Out-Null
        return
    }
    $upd = $global:UpdateAvailable

    $xamlAU = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="@@au_title@@" Height="520" Width="640"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="NoResize">
    <Window.Resources>
$($global:SubTheme)
        <Style x:Key="AUButton" TargetType="Button" BasedOn="{StaticResource SwBtn}"/>
    </Window.Resources>
    <Grid Margin="20">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <!-- BASLIK -->
        <StackPanel Grid.Row="0">
            <TextBlock Text="@@au_available@@" Foreground="#8CB4FF" FontSize="22" FontWeight="Bold"/>
            <TextBlock x:Name="txtAUSubtitle" Text="" Foreground="#8A919C" FontSize="13" Margin="0,4,0,16"/>
        </StackPanel>

        <!-- VERSION GRID -->
        <Grid Grid.Row="1" Margin="0,0,0,12">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>
            <Border Grid.Column="0" Background="#15181E" CornerRadius="6" BorderBrush="#232831" BorderThickness="1" Padding="12,10">
                <StackPanel>
                    <TextBlock Text="@@au_current@@" Foreground="#8A919C" FontSize="12" HorizontalAlignment="Center"/>
                    <TextBlock x:Name="txtAUCurrent" Text="" Foreground="#E6E8EB" FontWeight="Bold" FontSize="17" HorizontalAlignment="Center" Margin="0,4,0,0"/>
                </StackPanel>
            </Border>
            <TextBlock Grid.Column="1" Text="➔" Foreground="#8CB4FF" FontSize="24" VerticalAlignment="Center" Margin="12,0"/>
            <Border Grid.Column="2" Background="#16241C" CornerRadius="6" BorderBrush="#2A4A36" BorderThickness="1" Padding="12,10">
                <StackPanel>
                    <TextBlock Text="@@au_new@@" Foreground="#8A919C" FontSize="12" HorizontalAlignment="Center"/>
                    <TextBlock x:Name="txtAUNew" Text="" Foreground="#3FB97A" FontWeight="Bold" FontSize="17" HorizontalAlignment="Center" Margin="0,4,0,0"/>
                </StackPanel>
            </Border>
        </Grid>

        <!-- RELEASE NOTES -->
        <Border Grid.Row="2" Background="#15181E" CornerRadius="6" BorderBrush="#232831" BorderThickness="1" Padding="12,10">
            <Grid>
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                </Grid.RowDefinitions>
                <TextBlock Grid.Row="0" Text="@@pm_changes@@" Foreground="#E0A23B" FontWeight="Bold" FontSize="13" Margin="0,0,0,6"/>
                <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
                    <TextBlock x:Name="txtAUNotes" Foreground="#C9CED6" FontSize="13" TextWrapping="Wrap" FontFamily="Cascadia Mono, Consolas"/>
                </ScrollViewer>
            </Grid>
        </Border>

        <!-- PROGRESS -->
        <Grid Grid.Row="3" Margin="0,12,0,0">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <TextBlock Grid.Row="0" x:Name="txtAUProgress" Text="" Foreground="#A9B0BB" FontSize="12" Margin="0,0,0,4"/>
            <ProgressBar Grid.Row="1" x:Name="pbAU" Height="6" Background="#15181E" Foreground="#8CB4FF" BorderThickness="0" Value="0"/>
        </Grid>

        <!-- BUTONLAR -->
        <Grid Grid.Row="4" Margin="0,16,0,0">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <Button Grid.Column="0" x:Name="btnAUSkip" Style="{StaticResource AUButton}" Content="@@au_skip@@" Height="36" HorizontalAlignment="Stretch"/>
            <Button Grid.Column="2" x:Name="btnAULater" Style="{StaticResource AUButton}" Content="@@au_later@@" Height="36" MinWidth="140"/>
            <Button Grid.Column="4" x:Name="btnAUUpdate" Style="{StaticResource SwBtnPrimary}" Content="@@au_update@@" Height="36" MinWidth="170"/>
            <Button Grid.Column="6" x:Name="btnAURelease" Style="{StaticResource AUButton}" Content="🌐" Height="36" MinWidth="44" ToolTip="@@au_releasetip@@"/>
        </Grid>
    </Grid>
</Window>
"@

    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlAU))
        $winAU  = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winAU
        $winAU.Owner = $Win

        $txtSub      = $winAU.FindName('txtAUSubtitle')
        $txtCurrent  = $winAU.FindName('txtAUCurrent')
        $txtNew      = $winAU.FindName('txtAUNew')
        $txtNotes    = $winAU.FindName('txtAUNotes')
        $txtProgress = $winAU.FindName('txtAUProgress')
        $pbAU        = $winAU.FindName('pbAU')
        $btnSkip     = $winAU.FindName('btnAUSkip')
        $btnLater    = $winAU.FindName('btnAULater')
        $btnUpdate   = $winAU.FindName('btnAUUpdate')
        $btnRelease  = $winAU.FindName('btnAURelease')

        # Verileri doldur
        $txtSub.Text     = "GitHub Releases'tan otomatik kontrol — $($global:AppRepo)"
        $txtCurrent.Text = "v$($global:AppVersion)"
        $txtNew.Text     = $upd.Tag
        $txtNotes.Text   = if ($upd.Notes) { $upd.Notes } else { "(Release notlari yok)" }

        # 4 buton handler

        $btnSkip.Add_Click({
            Add-SkippedVersion -VersionTag $upd.Tag
            WpfLog "[Update] $($upd.Tag) atlandi — bu surum icin tekrar uyari gosterilmeyecek."
            $global:UpdateAvailable = $null
            if ($lblStatus) { $lblStatus.Text = "Sistem Hazır" }
            $winAU.Close()
        })

        $btnLater.Add_Click({ $winAU.Close() })

        $btnRelease.Add_Click({
            try { Start-Process $upd.ReleaseUrl } catch {}
        })

        $btnUpdate.Add_Click({
            # UI'i progress moda al
            $btnUpdate.IsEnabled = $false
            $btnSkip.IsEnabled = $false
            $btnLater.IsEnabled = $false

            # Progress callback — her step'te UI'a yansitir
            $progressCb = {
                param($pct, $msg)
                $winAU.Dispatcher.Invoke([action]{
                    $pbAU.Value = $pct
                    $txtProgress.Text = "[$pct%] $msg"
                }) | Out-Null
            }

            # Async olarak download flow'u baslat
            $dispatcher = $winAU.Dispatcher
            $dispatcher.Invoke([action]{
                $ok = Invoke-AppUpdate -ProgressCallback $progressCb
                if ($ok) {
                    $txtProgress.Text = "✓ Hazir. Program yeniden baslatiliyor..."
                    Start-Sleep -Milliseconds 800
                    # Ana programi kapat — updater script otomatik tetiklenecek
                    $winAU.Close()
                    if ($Win) { $Win.Close() }
                    [Environment]::Exit(0)
                } else {
                    [System.Windows.MessageBox]::Show("Guncelleme basarisiz oldu. Log'u kontrol edin.", "Hata", "OK", "Error") | Out-Null
                    $btnUpdate.IsEnabled = $true
                    $btnSkip.IsEnabled = $true
                    $btnLater.IsEnabled = $true
                }
            }) | Out-Null
        })

        # Bellek sizinti koruma
        $winAU.Add_Closed({
            $txtSub = $null; $txtCurrent = $null; $txtNew = $null; $txtNotes = $null
            $txtProgress = $null; $pbAU = $null
            $btnSkip = $null; $btnLater = $null; $btnUpdate = $null; $btnRelease = $null
        })

        $winAU.ShowDialog() | Out-Null

    } catch {
        WpfLog "❌ Show-AppUpdateWindow hatasi: $($_.Exception.Message)"
    }
}

# ---- Show-UpdateWindow (Winapp2.ini icin — eski isim, korunmasi gereken Winapp2 update mantigi) ----
function Get-Winapp2Diff {
    # Iki Winapp2.ini dosyasini [Section] bloklarina ayirip fark cikarir.
    # Doner: @{ Added=@(ad); Removed=@(ad); Changed=@(ad); OldCount; NewCount }
    param([string]$OldPath, [string]$NewPath)
    $parse = {
        param($p)
        $map = [ordered]@{}
        if (-not (Test-Path $p)) { return $map }
        $cur = $null
        $sb = $null
        foreach ($line in [System.IO.File]::ReadLines($p)) {
            $t = $line.Trim()
            if ($t -match '^\[(.+)\]$') {
                if ($cur) { $map[$cur] = ($sb -join "`n") }
                $cur = $Matches[1].Trim()
                $sb = New-Object System.Collections.Generic.List[string]
            }
            elseif ($cur -and $t -ne '' -and -not $t.StartsWith(';')) {
                $sb.Add($t)
            }
        }
        if ($cur) { $map[$cur] = ($sb -join "`n") }
        return $map
    }
    $old = & $parse $OldPath
    $new = & $parse $NewPath
    $added = @(); $removed = @(); $changed = @()
    foreach ($k in $new.Keys) {
        if (-not $old.Contains($k)) { $added += $k }
        elseif ($old[$k] -ne $new[$k]) { $changed += $k }
    }
    foreach ($k in $old.Keys) { if (-not $new.Contains($k)) { $removed += $k } }
    return @{ Added = $added; Removed = $removed; Changed = $changed; OldCount = $old.Count; NewCount = $new.Count }
}

function New-Winapp2DiffReport {
    # Eski<->yeni farki hesaplar, txt rapor yazar. Doner: @{ Path; Added; Changed; Removed }
    param([string]$OldPath, [string]$NewPath, [string]$OnlineVer = "")
    $d = Get-Winapp2Diff -OldPath $OldPath -NewPath $NewPath
    $ts = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
    $reportPath = Join-Path $DatabaseDir "winapp2_diff_$stamp.txt"
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine("Winapp2.ini Guncelleme Fark Raporu")
    [void]$sb.AppendLine("Tarih: $ts")
    if ($OnlineVer) { [void]$sb.AppendLine("Yeni surum satiri: $OnlineVer") }
    [void]$sb.AppendLine("Eski toplam uygulama: $($d.OldCount)   ->   Yeni toplam: $($d.NewCount)")
    [void]$sb.AppendLine("OZET:  +$($d.Added.Count) eklenen   ~$($d.Changed.Count) degisen   -$($d.Removed.Count) cikarilan")
    [void]$sb.AppendLine(("=" * 62))
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("EKLENEN UYGULAMALAR ($($d.Added.Count)):")
    if ($d.Added.Count -eq 0) { [void]$sb.AppendLine("  (yok)") } else { foreach ($n in ($d.Added | Sort-Object)) { [void]$sb.AppendLine("  + $n") } }
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("DEGISEN UYGULAMALAR ($($d.Changed.Count)):")
    if ($d.Changed.Count -eq 0) { [void]$sb.AppendLine("  (yok)") } else { foreach ($n in ($d.Changed | Sort-Object)) { [void]$sb.AppendLine("  ~ $n") } }
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("CIKARILAN UYGULAMALAR ($($d.Removed.Count)):")
    if ($d.Removed.Count -eq 0) { [void]$sb.AppendLine("  (yok)") } else { foreach ($n in ($d.Removed | Sort-Object)) { [void]$sb.AppendLine("  - $n") } }
    try { [System.IO.File]::WriteAllText($reportPath, $sb.ToString(), (New-Object System.Text.UTF8Encoding($true))) } catch {}
    return @{ Path = $reportPath; Added = $d.Added.Count; Changed = $d.Changed.Count; Removed = $d.Removed.Count }
}

function Show-UpdateWindow {
    # --- XAML ARAYÜZÜ ---
    $xamlUpdate = @"
    <Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
            xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
            Title="@@uw_title@@" Height="250" Width="500" 
            Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterScreen" WindowStyle="ToolWindow" ResizeMode="NoResize">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
        <Grid Margin="20">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>

            <TextBlock Text="@@uw_header@@" Foreground="#8CB4FF" FontSize="17" FontWeight="Bold" HorizontalAlignment="Center"/>

            <!-- SÜRÜM BİLGİLERİ -->
            <Grid Grid.Row="1" VerticalAlignment="Center">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>
                
                <StackPanel Grid.Column="0" HorizontalAlignment="Center">
                    <TextBlock Text="@@set_curver@@" Foreground="#8A919C" FontSize="12" HorizontalAlignment="Center"/>
                    <TextBlock x:Name="txtLocalVer" Text="..." Foreground="#E6E8EB" FontWeight="Bold" FontSize="14" HorizontalAlignment="Center" Margin="0,5,0,0"/>
                </StackPanel>

                <TextBlock Grid.Column="1" Text="➔" Foreground="#6B7280" FontSize="22" VerticalAlignment="Center" Margin="10,0"/>

                <StackPanel Grid.Column="2" HorizontalAlignment="Center">
                    <TextBlock Text="@@uw_server@@" Foreground="#8A919C" FontSize="12" HorizontalAlignment="Center"/>
                    <TextBlock x:Name="txtOnlineVer" Text="@@uw_checking@@" Foreground="#E0A23B" FontWeight="Bold" FontSize="14" HorizontalAlignment="Center" Margin="0,5,0,0"/>
                </StackPanel>
            </Grid>

            <!-- DURUM VE BUTONLAR -->
            <StackPanel Grid.Row="2">
                <TextBlock x:Name="txtStatus" Text="@@uw_wait@@" Foreground="#A9B0BB" HorizontalAlignment="Center" Margin="0,0,0,15"/>
                
                <!-- 3 SÜTUNLU BUTON YAPISI -->
                <Grid>
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="5"/>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="5"/>
                        <ColumnDefinition Width="*"/>
                    </Grid.ColumnDefinitions>
                    
                    <Button x:Name="btnOpenFolder" Grid.Column="0" Content="@@uw_openfolder@@" Height="35" ToolTip="@@uw_foldertip@@"/>
                    <Button x:Name="btnRescan" Grid.Column="2" Content="@@uw_rescan@@" Height="35" FontWeight="SemiBold" ToolTip="@@uw_rescantip@@"/>
                    <Button Style="{StaticResource SwBtnPrimary}" x:Name="btnDoUpdate" Grid.Column="4" Content="@@uw_do@@" Height="35" FontWeight="Bold" IsEnabled="False" ToolTip="@@uw_dotip@@"/>
                </Grid>
            </StackPanel>
        </Grid>
    </Window>
"@

    # --- PENCEREYİ YÜKLE ---
    $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlUpdate))
    $winUpd = [Windows.Markup.XamlReader]::Load($reader)
    Initialize-SubWindow $winUpd

    # Kontroller
    $txtLocal = $winUpd.FindName('txtLocalVer')
    $txtOnline = $winUpd.FindName('txtOnlineVer')
    $txtStat = $winUpd.FindName('txtStatus')
    $btnUpd = $winUpd.FindName('btnDoUpdate')
    $btnFol = $winUpd.FindName('btnOpenFolder')
    $btnRescan = $winUpd.FindName('btnRescan')

    # Yollar
    $localFile = $global:Winapp2Path 
    $url = $global:Winapp2Sources[0]

    # --- 1. MEVCUT SÜRÜMÜ OKU (TEMİZLİK EKLENDİ) ---
    $localVer = "Yok"
    if (Test-Path $localFile) {
        try {
            $reader = New-Object System.IO.StreamReader($localFile)
            $line = $reader.ReadLine()
            $reader.Close()
            if ($line -match "Version") { 
                # DÜZELTME: Noktalı virgülü sil ve boşlukları temizle
                $localVer = $line.Replace(";", "").Trim() 
            } else { 
                $localVer = "Bilinmiyor" 
            }
        } catch { $localVer = "Okunamadı" }
    }
    $txtLocal.Text = $localVer

    $script:UpdTimer = $null
    $script:CloseTimer = $null

    # --- 2. ONLINE KONTROL (ARKA PLAN + TEMİZLİK) ---
    $winUpd.Add_Loaded({
        $script:UpdRunspace = [powershell]::Create()
        $script:UpdRunspace.AddScript({
            param($u)
            [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12
            $wc = New-Object System.Net.WebClient
			$wc.Headers.Add("User-Agent", "Mozilla/5.0")
			try {
				$stream = $wc.OpenRead($u)
				$r = New-Object System.IO.StreamReader($stream)
				$ver = $r.ReadLine()
				$r.Close(); $stream.Close()
				if ($ver) { return $ver.Replace(";", "").Trim() }
				return "HATA"
			} catch { return "HATA" } finally { $wc.Dispose() }
        })
        $script:UpdRunspace.AddArgument($url)
        $script:UpdAsync = $script:UpdRunspace.BeginInvoke()

        $script:UpdTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:UpdTimer.Interval = [TimeSpan]::FromMilliseconds(200)
        
        $script:UpdTimer.Add_Tick({
            if (-not $winUpd.IsLoaded) { 
                $script:UpdTimer.Stop()
                return 
            }

            if ($script:UpdAsync.IsCompleted) {
			# 1. Döngüyü hemen durdur
			$script:UpdTimer.Stop()

			try {
				# 2. Sonucu al
				$onlineVer = $script:UpdRunspace.EndInvoke($script:UpdAsync)
				$txtOnline.Text = $onlineVer
				
				# 3. Sonuca göre arayüzü güncelle
				if ($onlineVer -eq "HATA" -or [string]::IsNullOrWhiteSpace($onlineVer)) {
					$txtStat.Text = "Sunucuya bağlanılamadı veya yanıt boş."
					$txtOnline.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#E5484D')
					$txtOnline.Text = "Hata"
				}
				elseif ($onlineVer -ne $txtLocal.Text) {
					$txtStat.Text = "✨ Yeni sürüm mevcut!"
					$txtStat.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#3FB97A')
					$btnUpd.IsEnabled = $true
					$btnUpd.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#4C8DFF')
				} 
				else {
					$txtStat.Text = "✅ Veritabanı güncel."
					$btnUpd.Content = "Yine de İndir"
					$btnUpd.IsEnabled = $true
					$btnUpd.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#1D2129')
				}
			} 
			catch {
				# 4. Hata olursa kullanıcıya bilgi ver
				$txtStat.Text = "Sürüm kontrolü sırasında bir hata oluştu."
				$txtOnline.Text = "Hata"
				$txtOnline.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#E5484D')
				WpfLog "Update Check Hatası: $($_.Exception.Message)"
			} 
			finally {
				# 5. KRİTİK: Hata olsa da olmasa da Runspace'i RAM'den temizle
				if ($script:UpdRunspace) {
					$script:UpdRunspace.Dispose()
					$script:UpdRunspace = $null
				}
			}
		}
        })
        $script:UpdTimer.Start()
    })

    # --- PENCERE KAPANINCA TEMİZLİK ---
    $winUpd.Add_Closed({
        if ($script:UpdTimer) { $script:UpdTimer.Stop() }
        if ($script:CloseTimer) { $script:CloseTimer.Stop() }
        if ($script:UpdRunspace) { $script:UpdRunspace.Dispose() }
    })

    # --- 3. BUTON OLAYLARI ---
    
    # KLASÖRÜ AÇ
    $btnFol.Add_Click({
        Invoke-Item (Split-Path $localFile)
    })

    # LİSTEYİ YENİLE
    $btnRescan.Add_Click({
        if (Test-Path $global:CachePath) { Remove-Item $global:CachePath -Force }
        Start-Winapp2-Process 
        $winUpd.Close()
    })

    # GÜNCELLEME İŞLEMİ
    $btnUpd.Add_Click({
        $btnUpd.IsEnabled = $false
        $btnUpd.Content = "İndiriliyor..."
        $txtStat.Text = "Dosya indiriliyor, lütfen bekleyin..."
        Do-Events

        try {
            $backupFile = "$localFile.old"
            
            if (Test-Path $localFile) {
                if (Test-Path $backupFile) { Remove-Item $backupFile -Force }
                Move-Item $localFile $backupFile -Force
            }

            [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12
            $wc = New-Object System.Net.WebClient
			try { $wc.DownloadFile($url, $localFile) } finally { $wc.Dispose() }

            if ((Test-Path $localFile) -and (Get-Item $localFile).Length -gt 1024) {
                $txtStat.Text = "✔ Başarıyla güncellendi!"
                $txtStat.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#3FB97A')
                $btnUpd.Content = "TAMAMLANDI"

                # v1.2.29: Eski <-> yeni Winapp2 fark raporu (txt) uret + ac, eski surumu kalici sakla
                if (Test-Path $backupFile) {
                    try {
                        $rep = New-Winapp2DiffReport -OldPath $backupFile -NewPath $localFile -OnlineVer $txtOnline.Text
                        $txtStat.Text = "✔ Güncellendi!  +$($rep.Added) yeni · ~$($rep.Changed) değişen · -$($rep.Removed) çıkan"
                        $prev = Join-Path $DatabaseDir "Winapp2.prev.ini"
                        Copy-Item $backupFile $prev -Force -ErrorAction SilentlyContinue
                        if ($rep.Path -and (Test-Path $rep.Path)) { Invoke-Item $rep.Path }
                    } catch { WpfLog "[UYARI] Winapp2 fark raporu uretilemedi: $($_.Exception.Message)" }
                }
                
				if (Test-Path $backupFile) { Remove-Item $backupFile -Force -ErrorAction SilentlyContinue }
				
                if (Test-Path $global:CachePath) { Remove-Item $global:CachePath -Force }
                Start-Winapp2-Process 
                
                $script:CloseTimer = New-Object System.Windows.Threading.DispatcherTimer
                $script:CloseTimer.Interval = [TimeSpan]::FromSeconds(2)
                $script:CloseTimer.Add_Tick({ 
                    $script:CloseTimer.Stop()
                    if ($winUpd.IsLoaded) { $winUpd.Close() }
                })
                $script:CloseTimer.Start()

            } else {
                throw "İndirilen dosya bozuk veya çok küçük."
            }

        } catch {
            $txtStat.Text = "❌ HATA: Eski sürüme dönülüyor..."
            $txtStat.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#E5484D')
            WpfLog "[HATA] Güncelleme başarısız: $($_.Exception.Message)"
            
            if (Test-Path $localFile) { Remove-Item $localFile -Force }
            if (Test-Path $backupFile) { Move-Item $backupFile $localFile -Force }
            
            $btnUpd.Content = "HATA"
            $btnUpd.Background = "#A00"
            $btnUpd.IsEnabled = $true
        }
    })

    $winUpd.ShowDialog() | Out-Null
}

# ---- Show-RestartDialog ----
function Show-RestartDialog {
    $xamlRestart = @"
    <Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
            xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
            Title="@@rs_title@@" MinHeight="220" Width="500" 
            Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterScreen" WindowStyle="ToolWindow" ResizeMode="NoResize" SizeToContent="Height">
        <Window.Resources>
$($global:SubTheme)
        </Window.Resources>
        <Grid Margin="22">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>

            <!-- BAŞLIK VE İKON -->
            <StackPanel Grid.Row="0" Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,0,0,15">
                <TextBlock Text="⚠️" FontSize="22" Margin="0,0,10,0"/>
                <TextBlock Text="@@rs_needed@@" Foreground="#E5484D" FontSize="20" FontWeight="SemiBold" VerticalAlignment="Center"/>
            </StackPanel>

            <!-- AÇIKLAMA -->
            <TextBlock Grid.Row="1" Text="@@rs_desc@@" 
                       Foreground="#C9CED6" TextWrapping="Wrap" TextAlignment="Center" FontSize="14"/>

            <!-- BUTONLAR -->
            <Grid Grid.Row="2" Margin="0,15,0,0">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="10"/>
                    <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>
                
                <Button x:Name="btnLater" Grid.Column="0" Content="@@rs_later@@" Height="40"/>
                
                <Button x:Name="btnRestartNow" Grid.Column="2" Height="40" Style="{StaticResource SwBtnDangerSolid}">
                    <StackPanel Orientation="Horizontal">
                        <TextBlock Text="@@rs_now@@" VerticalAlignment="Center"/>
                    </StackPanel>
                </Button>
            </Grid>
        </Grid>
    </Window>
"@
    
    $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlRestart))
    $winRes = [Windows.Markup.XamlReader]::Load($reader)
    Initialize-SubWindow $winRes
    
    $btnLater = $winRes.FindName('btnLater')
    $btnNow = $winRes.FindName('btnRestartNow')
    
    $btnLater.Add_Click({ $winRes.Close() })
    
    $btnNow.Add_Click({
        $winRes.Close()
        # ZORLA YENİDEN BAŞLATMA KOMUTU (/f = Force, /r = Restart, /t 0 = Hemen)
        Start-Process shutdown.exe -ArgumentList "/r /f /t 0" -WindowStyle Hidden
    })
    
    # 14. tur: sahipli + en ustte + etkin (Explorer yeniden baslatildiktan sonra arkada kalip ana pencereyi kilitliyordu)
    try { if ($Win -and $Win.IsVisible) { $winRes.Owner = $Win; $winRes.WindowStartupLocation = "CenterOwner" } } catch {}
    $winRes.Topmost = $true
    $winRes.Add_ContentRendered({ try { $this.Activate() | Out-Null } catch {} })
    $winRes.ShowDialog() | Out-Null
}

# ---- Show-HardwareDetail ----
function Show-HardwareDetail {
    $d = $global:DashResult
    if (-not $d) { return }

    $xamlHW = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="@@hw_title@@" Height="640" Width="700"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="CanResize">
    <Window.Resources>
$($global:SubTheme)
        <Style x:Key="LblStyle" TargetType="TextBlock">
            <Setter Property="Foreground"        Value="#8A919C"/>
            <Setter Property="FontSize"          Value="13"/>
            <Setter Property="VerticalAlignment" Value="Center"/>
            <Setter Property="Margin"            Value="0,3,12,3"/>
        </Style>
        <Style x:Key="ValStyle" TargetType="TextBox">
            <Setter Property="Foreground"        Value="#E6E8EB"/>
            <Setter Property="Background"        Value="Transparent"/>
            <Setter Property="BorderThickness"   Value="0"/>
            <Setter Property="IsReadOnly"        Value="True"/>
            <Setter Property="FontSize"          Value="13"/>
            <Setter Property="Padding"           Value="0"/>
            <Setter Property="Margin"            Value="0,3,0,3"/>
            <Setter Property="VerticalAlignment" Value="Center"/>
            <Setter Property="TextWrapping"      Value="Wrap"/>
            <Setter Property="Cursor"            Value="IBeam"/>
        </Style>
        <Style x:Key="Card" TargetType="Border">
            <Setter Property="Background"      Value="#15181E"/>
            <Setter Property="CornerRadius"    Value="10"/>
            <Setter Property="Padding"         Value="16,14"/>
            <Setter Property="Margin"          Value="0,0,0,10"/>
            <Setter Property="BorderBrush"     Value="#232831"/>
            <Setter Property="BorderThickness" Value="1"/>
        </Style>
        <Style x:Key="SectionTitle" TargetType="TextBlock">
            <Setter Property="Foreground"  Value="#E6E8EB"/>
            <Setter Property="FontSize"    Value="15"/>
            <Setter Property="FontWeight"  Value="SemiBold"/>
            <Setter Property="Margin"      Value="0,0,0,10"/>
        </Style>
        <Style x:Key="SubCard" TargetType="Border">
            <Setter Property="Background"      Value="#13161B"/>
            <Setter Property="CornerRadius"    Value="8"/>
            <Setter Property="Padding"         Value="12,8"/>
            <Setter Property="Margin"          Value="0,0,0,6"/>
            <Setter Property="BorderBrush"     Value="#1F232B"/>
            <Setter Property="BorderThickness" Value="1"/>
        </Style>
    </Window.Resources>
    <Grid Margin="16">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        <StackPanel Grid.Row="0" Margin="0,0,0,14">
            <TextBlock Text="@@hw_title@@" Style="{StaticResource SwTitle}"/>
            <TextBlock Text="@@hw_copyhint@@" Foreground="#6B7280" FontSize="12" Margin="0,4,0,0"/>
        </StackPanel>
        <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
            <StackPanel>
                <!-- ANAKART ve BIOS -->
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Style="{StaticResource SectionTitle}" Text="@@hw_moboBios@@"/>
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="130"/><ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>
                            <Grid.RowDefinitions><RowDefinition/><RowDefinition/></Grid.RowDefinitions>
                            <TextBlock Grid.Row="0" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_mobo@@"/>
                            <TextBox   Grid.Row="0" Grid.Column="1" Style="{StaticResource ValStyle}" x:Name="txtMB"/>
                            <TextBlock Grid.Row="1" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_biosver@@"/>
                            <TextBox   Grid.Row="1" Grid.Column="1" Style="{StaticResource ValStyle}" x:Name="txtBIOS"/>
                        </Grid>
                    </StackPanel>
                </Border>
                <!-- RAM -->
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Style="{StaticResource SectionTitle}" Text="@@hw_rammodules@@"/>
                        <ItemsControl x:Name="icRAM">
                            <ItemsControl.ItemTemplate>
                                <DataTemplate>
                                    <Border Style="{StaticResource SubCard}">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="130"/><ColumnDefinition Width="*"/>
                                            </Grid.ColumnDefinitions>
                                            <Grid.RowDefinitions>
                                                <RowDefinition/><RowDefinition/><RowDefinition/><RowDefinition/>
                                            </Grid.RowDefinitions>
                                            <TextBlock Grid.Row="0" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_slot@@"/>
                                            <TextBox   Grid.Row="0" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding Slot}"/>
                                            <TextBlock Grid.Row="1" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_brandmodel@@"/>
                                            <TextBox   Grid.Row="1" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding MfrPart}"/>
                                            <TextBlock Grid.Row="2" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_capacity@@"/>
                                            <TextBox   Grid.Row="2" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding CapStr}"/>
                                            <TextBlock Grid.Row="3" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_speed@@"/>
                                            <TextBox   Grid.Row="3" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding SpeedStr}"/>
                                        </Grid>
                                    </Border>
                                </DataTemplate>
                            </ItemsControl.ItemTemplate>
                        </ItemsControl>
                    </StackPanel>
                </Border>
                <!-- GPU -->
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Style="{StaticResource SectionTitle}" Text="@@hw_gpu@@"/>
                        <ItemsControl x:Name="icGPU">
                            <ItemsControl.ItemTemplate>
                                <DataTemplate>
                                    <Border Style="{StaticResource SubCard}">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="130"/><ColumnDefinition Width="*"/>
                                            </Grid.ColumnDefinitions>
                                            <Grid.RowDefinitions>
                                                <RowDefinition/><RowDefinition/><RowDefinition/><RowDefinition/>
                                            </Grid.RowDefinitions>
                                            <TextBlock Grid.Row="0" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_aib@@"/>
                                            <TextBox   Grid.Row="0" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding Vendor}"/>
                                            <TextBlock Grid.Row="1" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_model@@"/>
                                            <TextBox   Grid.Row="1" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding Name}"/>
                                            <TextBlock Grid.Row="2" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_vram@@"/>
                                            <TextBox   Grid.Row="2" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding VramStr}"/>
                                            <TextBlock Grid.Row="3" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_driver@@"/>
                                            <TextBox   Grid.Row="3" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding Driver}"/>
                                        </Grid>
                                    </Border>
                                </DataTemplate>
                            </ItemsControl.ItemTemplate>
                        </ItemsControl>
                    </StackPanel>
                </Border>
                <!-- DISK -->
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Style="{StaticResource SectionTitle}" Text="@@hw_disks@@"/>
                        <ItemsControl x:Name="icDisk">
                            <ItemsControl.ItemTemplate>
                                <DataTemplate>
                                    <Border Style="{StaticResource SubCard}">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="130"/><ColumnDefinition Width="*"/>
                                            </Grid.ColumnDefinitions>
                                            <Grid.RowDefinitions>
                                                <RowDefinition/><RowDefinition/><RowDefinition/>
                                            </Grid.RowDefinitions>
                                            <TextBlock Grid.Row="0" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_model@@"/>
                                            <TextBox   Grid.Row="0" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding Model}"/>
                                            <TextBlock Grid.Row="1" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_capacity@@"/>
                                            <TextBox   Grid.Row="1" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding SizeStr}"/>
                                            <TextBlock Grid.Row="2" Grid.Column="0" Style="{StaticResource LblStyle}" Text="@@hw_serial@@"/>
                                            <TextBox   Grid.Row="2" Grid.Column="1" Style="{StaticResource ValStyle}" Text="{Binding Serial}"/>
                                        </Grid>
                                    </Border>
                                </DataTemplate>
                            </ItemsControl.ItemTemplate>
                        </ItemsControl>
                    </StackPanel>
                </Border>
            </StackPanel>
        </ScrollViewer>
        <Button x:Name="btnCloseHW" Grid.Row="2" Content="@@m_close@@" Height="34" MinWidth="100"
                HorizontalAlignment="Right" Margin="0,10,0,0"/>
    </Grid>
</Window>
"@

    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlHW))
        $winHW  = [Windows.Markup.XamlReader]::Load($reader)
        $winHW.Owner = $Win
        Initialize-SubWindow $winHW

        $txtMB   = $winHW.FindName('txtMB')
        $txtBIOS = $winHW.FindName('txtBIOS')
        $icRAM   = $winHW.FindName('icRAM')
        $icGPU   = $winHW.FindName('icGPU')
        $icDisk  = $winHW.FindName('icDisk')
        $btnCl   = $winHW.FindName('btnCloseHW')

        # ── ANAKART & BIOS ─────────────────────────────────────
        $txtMB.Text   = if ($d.MbInfo)   { $d.MbInfo }   else { "Alinamadi" }
        $txtBIOS.Text = if ($d.BiosInfo) { $d.BiosInfo } else { "Alinamadi" }

        # ── RAM ────────────────────────────────────────────────
        $brandTable = @{
            "F4-"  = "G.Skill";  "F5-"  = "G.Skill";  "FA-"  = "G.Skill"
            "CMK"  = "Corsair";  "CMW"  = "Corsair";  "CMH"  = "Corsair"
            "CMP"  = "Corsair";  "CMT"  = "Corsair";  "CML"  = "Corsair"
            "KF4"  = "Kingston (Fury)"; "KF5"  = "Kingston (Fury)"
            "KVR"  = "Kingston"; "HX"   = "Kingston (HyperX)"
            "CT"   = "Crucial";  "BL"   = "Crucial (Ballistix)"
            "M378" = "Samsung";  "M471" = "Samsung";  "M425" = "Samsung"
            "M324" = "Samsung";  "M4R"  = "Samsung"
            "HMA"  = "SK Hynix"; "HMT"  = "SK Hynix"; "HMCG" = "SK Hynix"; "HMAA" = "SK Hynix"
            "MTC"  = "Micron"
            "TF4"  = "TeamGroup"; "TF5" = "TeamGroup"; "TLZGD" = "TeamGroup"
            "AX4"  = "ADATA (XPG)"; "AX5" = "ADATA (XPG)"; "AD4U" = "ADATA"; "AD5U" = "ADATA"
            "PVS"  = "Patriot";  "PX4"  = "Patriot";  "PX5"  = "Patriot"
            "RG"   = "Thermaltake (TOUGHRAM)"
            "KD4"  = "Klevv";    "KD5"  = "Klevv"
            "LD4"  = "Lexar";    "LD5"  = "Lexar"
        }

        function Resolve-RamBrand([string]$pn) {
            if ([string]::IsNullOrWhiteSpace($pn)) { return $null }
            $pn = $pn.Trim()
            foreach ($len in 5,4,3,2) {
                if ($pn.Length -ge $len) {
                    $pfx = $pn.Substring(0,$len)
                    if ($brandTable.ContainsKey($pfx)) { return $brandTable[$pfx] }
                }
            }
            return $null
        }

        function Resolve-DdrType([int]$t) {
            switch ($t) {
                19 { return "DDR2"    }
                24 { return "DDR3"    }
                26 { return "DDR4"    }
                27 { return "LPDDR4"  }
                28 { return "LPDDR4X" }
                29 { return "DDR5"    }
                34 { return "DDR5"    }
                35 { return "LPDDR5"  }
                default { return $null }
            }
        }

        $ramItems = New-Object System.Collections.ObjectModel.ObservableCollection[Object]
        foreach ($mod in $d.RamModules) {
            $brand   = Resolve-RamBrand $mod.Part
            $ddrType = Resolve-DdrType ([int]$mod.MemType)

            # "G.Skill  -  F5-6000J3038F16G  (DDR5)"
            $mfrPart = if ($brand) { "$brand  -  $($mod.Part)" } else { "$($mod.Part)" }
            if ($ddrType) { $mfrPart += "  ($ddrType)" }

            # Hiz: ConfiguredClockSpeed = BIOS aktif hiz (XMP/EXPO dahil)
            # Speed (Win32_PhysicalMemory.Speed) = SPD max profili
            # Ikisi esitse XMP/EXPO tam calisuyor demektir.
            # Cfg < Spd   = XMP/EXPO etkin degil (JEDEC ile calisuyor)
            $cfg = [int]$mod.CfgMHz
            $spd = [int]$mod.SpeedMHz
            $speedStr = "$cfg MHz"
            if ($spd -gt 0 -and $spd -ne $cfg) {
                if ($cfg -lt $spd) {
                    $speedStr = "$cfg MHz  (XMP/EXPO etkin degil  -  Kit hizi: $spd MHz)"
                } else {
                    $speedStr = "$cfg MHz  (Kit SPD max: $spd MHz)"
                }
            }

            $ramItems.Add([PSCustomObject]@{
                Slot    = $mod.Slot
                MfrPart = $mfrPart
                CapStr  = "$($mod.Capacity) GB"
                SpeedStr = $speedStr
            }) | Out-Null
        }
        $icRAM.ItemsSource = $ramItems

        # ── GPU ────────────────────────────────────────────────
        # PCI SubSystem Vendor ID tablosu -> AIB kart uretici
        # SUBSYS_SSSSSVVVV formatinda:
        #   SSSS = SubSystem Device ID (kart modeli, ornegin 89D7)
        #   VVVV = SubSystem Vendor ID  (AIB uretici, ornegin 1043 = ASUS)
        # Senin RTX 5080: SUBSYS_89D71043 -> SubVendor=1043 -> ASUS
        $aibTable = @{
            "1043" = "ASUS"
            "1462" = "MSI"
            "1458" = "Gigabyte"
            "3842" = "EVGA"
            "174B" = "Sapphire"
            "1DA2" = "Sapphire"
            "148C" = "PowerColor"
            "1682" = "XFX"
            "19DA" = "Zotac"
            "196E" = "Palit / Gainward"
            "1B4C" = "Inno3D / Galax"
            "1849" = "ASRock"
            "7377" = "Colorful"
            "1ACC" = "Manli"
        }

        function Get-GpuAibMap {
            # PnPClass = "Display" olan tum cihazlari tara.
            # HardwareID listesindeki ilk SUBSYS degerinin son 4 hanesini SubVendor olarak al.
            # { "NVIDIA GeForce RTX 5080" -> "ASUS" } seklinde map dondurur.
            $map = @{}
            try {
                $displays = Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue |
                            Where-Object { $_.PNPClass -eq "Display" }
                foreach ($dev in $displays) {
                    if (-not $dev.HardwareID -or -not $dev.Name) { continue }
                    foreach ($hwId in $dev.HardwareID) {
                        # Ornek: PCI\VEN_10DE&DEV_2C02&SUBSYS_89D71043&REV_A1
                        if ($hwId -match "SUBSYS_([0-9A-Fa-f]{4})([0-9A-Fa-f]{4})") {
                            $subVendorId = $Matches[2].ToUpper()   # son 4 hane = AIB
                            if ($aibTable.ContainsKey($subVendorId)) {
                                $map[$dev.Name] = $aibTable[$subVendorId]
                            }
                            break  # bu cihaz icin ilk SUBSYS yeterli
                        }
                    }
                }
            } catch {}
            return $map
        }

        function Get-GpuVramMap {
            $map = @{}
            $regKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
            try {
                Get-ChildItem $regKey -ErrorAction SilentlyContinue |
                Where-Object { $_.PSChildName -match '^\d{4}$' } |
                ForEach-Object {
                    $props = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                    $desc  = $props.DriverDesc
                    if (-not $desc) { return }
                    $qw = $props."HardwareInformation.qwMemorySize"
                    if (-not $qw) { $qw = $props."HardwareInformation.MemorySize" }
                    if ($qw) { $map[$desc] = [Math]::Round([long]$qw / 1GB, 1) }
                }
            } catch {}
            return $map
        }

        $aibMap  = Get-GpuAibMap
        $vramMap = Get-GpuVramMap
        $gpuItems = New-Object System.Collections.ObjectModel.ObservableCollection[Object]

        foreach ($g in $d.GpuDetail) {
            # v1.2.10: iGPU tespit — CPU icine gomulu GPU'larda AIB (Add-in Board) uretici anlamsiz.
            # Sebep: iGPU'nun PCI subsystem vendor ID si anakart ureticisinden gelir (orn. MSI 1462)
            # ama MSI iGPU uretmedi — MSI anakart uretti, GPU AMD/Intel CPU icinde. Eski kod bu
            # subsystem vendor ID'sini AIB olarak gosterip "MSI" diyordu (yaniltici).
            # Pattern match: "Radeon(TM) Graphics" (model suffix yok) = AMD iGPU (Ryzen 7000+ APU),
            # "UHD/HD Graphics" + "Iris" = Intel iGPU. Dedicated isim varsa zorla false.
            $isIntegrated = $false
            if ($g.Name -match "Radeon\(TM\) Graphics|Radeon Graphics$|UHD Graphics|^Intel.*HD Graphics|Iris(\s|$)") {
                $isIntegrated = $true
            }
            if ($g.Name -match "GeForce|RTX|GTX|Quadro|Radeon RX|Radeon Pro|Arc\s") {
                $isIntegrated = $false   # dedicated patterni override eder (overlap yakalama)
            }

            $vendor = $null
            if ($isIntegrated) {
                # iGPU: AIB yok, CPU uretici belirt
                if     ($g.Name -match "Radeon|AMD")        { $vendor = "iGPU (AMD CPU icinde)"   }
                elseif ($g.Name -match "Intel|UHD|Iris|HD") { $vendor = "iGPU (Intel CPU icinde)" }
                else                                          { $vendor = "iGPU (CPU icinde gomulu)" }
            } else {
                # AIB eslestirmesi (sadece dedicated GPU'lar icin) — once birebir, sonra partial
                foreach ($pnpName in $aibMap.Keys) {
                    if ($pnpName -eq $g.Name -or
                        $pnpName.ToLower().Contains($g.Name.ToLower()) -or
                        $g.Name.ToLower().Contains($pnpName.ToLower())) {
                        $vendor = $aibMap[$pnpName]; break
                    }
                }
                # Partial match fallback (GPU adi parcalara bolunup aranir)
                if (-not $vendor) {
                    foreach ($part in ($g.Name -split '\s+' | Where-Object { $_.Length -gt 4 })) {
                        foreach ($pnpName in $aibMap.Keys) {
                            if ($pnpName.ToLower().Contains($part.ToLower())) {
                                $vendor = $aibMap[$pnpName]; break
                            }
                        }
                        if ($vendor) { break }
                    }
                }
                # Son fallback: chip uretici
                if (-not $vendor) {
                    if     ($g.Name -match "NVIDIA|GeForce|RTX|GTX|Quadro") { $vendor = "NVIDIA" }
                    elseif ($g.Name -match "Radeon|RX |AMD")                 { $vendor = "AMD"    }
                    elseif ($g.Name -match "Intel|Arc|Iris|UHD")             { $vendor = "Intel"  }
                    else                                                      { $vendor = "Bilinmiyor" }
                }
            }

            # VRAM: registry QWORD, fallback WMI degerine don
            $vramGB = $null
            foreach ($rk in $vramMap.Keys) {
                if ($rk -eq $g.Name -or
                    $rk.ToLower().Contains($g.Name.ToLower()) -or
                    $g.Name.ToLower().Contains($rk.ToLower())) {
                    $vramGB = $vramMap[$rk]; break
                }
            }
            $vramStr = if ($vramGB) { "$vramGB GB" } else { "$($g.VRAM) GB" }
            # iGPU VRAM shared memory'den ayrilir (dedicated VRAM yok). Kullaniciya net olsun.
            if ($isIntegrated) { $vramStr = "$vramStr (paylaşımlı)" }

            # Surucu versiyonu: NVIDIA Windows suru numarasini oyun suru numarasina cevir
            $drv = $g.Driver
            if ($g.Name -match "NVIDIA|GeForce|RTX|GTX" -and $drv) {
                $digits = $drv -replace "\D",""
                if ($digits.Length -ge 5) {
                    $drv = $digits.Substring($digits.Length - 5).Insert(3,".")
                }
            }

            $gpuItems.Add([PSCustomObject]@{
                Vendor  = $vendor
                Name    = $g.Name
                VramStr = $vramStr
                Driver  = $drv
            }) | Out-Null
        }
        $icGPU.ItemsSource = $gpuItems

        # ── DISK ───────────────────────────────────────────────
        $diskItems = New-Object System.Collections.ObjectModel.ObservableCollection[Object]
        foreach ($dk in $d.DiskDetail) {
            $diskItems.Add([PSCustomObject]@{
                Model   = $dk.Model
                SizeStr = "$($dk.SizeGB) GB"
                Serial  = if ($dk.Serial -and $dk.Serial.Trim()) { $dk.Serial.Trim() } else { "-" }
            }) | Out-Null
        }
        $icDisk.ItemsSource = $diskItems

        $btnCl.Add_Click({ $winHW.Close() })
        $winHW.ShowDialog() | Out-Null

    } catch {
        [System.Windows.MessageBox]::Show("Pencere acilamadi: $($_.Exception.Message)", "Hata") | Out-Null
    }
}

# ---- Load-DashboardData ----
# v1.3.0 (§54): tek palet — normal çubuk vurgu mavisi, eşik aşılınca kırmızı
function Get-DashBrush([string]$hex) { return (New-Object System.Windows.Media.BrushConverter).ConvertFromString($hex) }
function Get-DashBarBrush([bool]$bad) { if ($bad) { return Get-DashBrush '#E5484D' } return Get-DashBrush '#4C8DFF' }

function Load-DashboardData {
    # =========================================================
    # 5 DAKİKA CACHE — Her yenileme WMI sorgularını tekrar çalıştırmaz.
    # Bu sayede sekme değişimlerinde UI donması yaşanmaz.
    # =========================================================
    if ($global:DashCache -and $global:DashCacheTime -and 
        ((Get-Date) - $global:DashCacheTime).TotalMinutes -lt 5) {
        
        $cached = $global:DashCache
        $global:DashResult = $cached
        
        # UI'ı cache'den doldur
        $txtDashOS.Text   = $cached.OS
        $txtDashCPU.Text  = $cached.CPU
        $txtDashGPU.Text  = $cached.GPU
		$txtDashDNS.Text  = $cached.DNS
        $txtDashRAM.Text  = $cached.RAM_Text
        $pbDashRAM.Value  = $cached.RAM_Val
        $pbDashRAM.Foreground = Get-DashBarBrush ($cached.RAM_Val -gt 85)
        $txtDashDisk.Text = $cached.Disk_Text
        $pbDashDisk.Value = $cached.Disk_Val
        $pbDashDisk.Foreground = Get-DashBarBrush ($cached.Disk_Val -gt 90 -or $cached.Smart -match "Kritik")
        if ($script:txtDashRamInfo)  { $script:txtDashRamInfo.Text  = [string]$cached.RAM_Info }
        if ($script:txtDashDiskInfo) { $script:txtDashDiskInfo.Text = [string]$cached.Disk_Info }
        if ($txtDashWinVer)     { $txtDashWinVer.Text     = [string]$cached.WinFullVer }
        if ($txtDashUptime)     { $txtDashUptime.Text     = [string]$cached.Uptime }
        if ($txtDashSecurity)   { $txtDashSecurity.Text   = [string]$cached.Security }
        if ($txtDashLastUpdate) { $txtDashLastUpdate.Text = [string]$cached.LastUpdate }
        $txtDashSubHeader.Text = "✅ Önbellekten yüklendi. (Son tarama: $($global:DashCacheTime.ToString('HH:mm:ss')))"
        if ($btnHardwareDetail) { $btnHardwareDetail.IsEnabled = $true }
        try { Update-DashRecommendations } catch {}
        try { Start-WingetUpdateCheck } catch {}
        return
    }

    # 1. Arka Plan Motorunu Başlat
    $script:DashRunspace = [powershell]::Create()
    
    $script:DashRunspace.AddScript({
        $ErrorActionPreference = "SilentlyContinue"
        
        # --- CimSession: Tek bağlantıyla tüm WMI sorguları (her Get-CimInstance ayrı bağlantı açar) ---
        $cim = New-CimSession -ErrorAction SilentlyContinue
        
        # --- 1. İŞLETİM SİSTEMİ ---
        $os = Get-CimInstance Win32_OperatingSystem -CimSession $cim
        $regPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion"
        $displayVersion = (Get-ItemProperty -Path $regPath -Name "DisplayVersion" -ErrorAction SilentlyContinue).DisplayVersion
        if (-not $displayVersion) { $displayVersion = (Get-ItemProperty -Path $regPath -Name "ReleaseId" -ErrorAction SilentlyContinue).ReleaseId }
        $osName = "$($os.Caption)"
        
        # --- 2. CPU ---
        $cpu = Get-CimInstance Win32_Processor -CimSession $cim | Select-Object -First 1
        $cpuName = $cpu.Name

        # --- 3. GPU (SÜRÜCÜ PARSE EDİCİ EKLENDİ) ---
        $gpus = Get-CimInstance Win32_VideoController -CimSession $cim
        $gpuList = @()
        
        if ($gpus) {
            foreach ($g in $gpus) {
                $gName = $g.Name
                $drvRaw = $g.DriverVersion
                $drvFinal = ""

                # NVIDIA Sürücü Numarası Çevirici (Örn: 32.0.15.5186 -> 551.86)
                if ($gName -match "NVIDIA" -and $drvRaw) {
                    $digits = $drvRaw -replace "\D", "" 
                    if ($digits.Length -ge 5) {
                        $last5 = $digits.Substring($digits.Length - 5)
                        $drvFinal = $last5.Insert(3, ".")
                    } else {
                        $drvFinal = $drvRaw
                    }
                } 
                elseif ($drvRaw) {
                    $drvFinal = $drvRaw
                }

                if ($drvFinal) {
                    $gpuList += "$gName  ·  sürücü $drvFinal"
                } else {
                    $gpuList += "$gName"
                }
            }
            $gpuName = $gpuList -join "`n"
        } else {
            $gpuName = "Standart Grafik Kartı"
        }

        # --- 4. RAM ---
        $totalRamBytes = $os.TotalVisibleMemorySize * 1KB
        $freeRamBytes  = $os.FreePhysicalMemory * 1KB
        $usedRamBytes  = $totalRamBytes - $freeRamBytes
        
        $totalRamGB = [Math]::Round($totalRamBytes / 1GB, 1)
        $usedRamGB  = [Math]::Round($usedRamBytes / 1GB, 1)
        $ramPercent = [Math]::Round(($usedRamBytes / $totalRamBytes) * 100)
        
        # --- 5. DISK ---
        $disk = Get-CimInstance Win32_LogicalDisk -CimSession $cim -Filter "DeviceID='C:'" | Select-Object -First 1
        $diskSizeGB = [Math]::Round($disk.Size / 1GB, 1)
        $diskFreeGB = [Math]::Round($disk.FreeSpace / 1GB, 1)
        # Ham byte'tan hesapla, SONRA yuvarla — yoksa iki yuvarlanmis sayinin farki floating-point
        # artigi birakir (orn 70.1999999999999). $disk.Size 0 ise bolme hatasi onlenir.
        $diskUsedGB = [Math]::Round(($disk.Size - $disk.FreeSpace) / 1GB, 1)
        $diskPercent = if ($disk.Size -gt 0) { [Math]::Round((($disk.Size - $disk.FreeSpace) / $disk.Size) * 100) } else { 0 }
        
        # --- 6. S.M.A.R.T. ---
        $smartStatus = "Sağlıklı"
        try {
            $smart = Get-CimInstance -CimSession $cim -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictStatus -ErrorAction SilentlyContinue
            if ($smart -and $smart.PredictFailure) { $smartStatus = "Kritik (arıza riski)" }
        } catch {}

        # --- 7. RAM DETAY (Marka, Model, MHz, DDR Tipi) ---
        $ramModules = @()
        try {
            $physRam = Get-CimInstance Win32_PhysicalMemory -CimSession $cim -ErrorAction SilentlyContinue
            foreach ($mod in $physRam) {
                $mfr    = if ($mod.Manufacturer -and $mod.Manufacturer.Trim() -notmatch "^\s*$|Unknown|Not Specified") { $mod.Manufacturer.Trim() } else { "" }
                $part   = if ($mod.PartNumber   -and $mod.PartNumber.Trim()   -ne "") { $mod.PartNumber.Trim() }   else { "?" }
                $cap    = [Math]::Round($mod.Capacity / 1GB)
                $spd    = $mod.Speed
                $cfgSpd = $mod.ConfiguredClockSpeed
                $slot   = $mod.DeviceLocator
                $memType = [int]$mod.SMBIOSMemoryType

                $ramModules += [PSCustomObject]@{
                    Slot    = $slot
                    Capacity = $cap
                    Mfr     = $mfr
                    Part    = $part
                    SpeedMHz = $spd
                    CfgMHz  = $cfgSpd
                    MemType = $memType
                }
            }
        } catch {}

        # --- 8. BIOS ---
        $biosInfo = ""
        try {
            $bios = Get-CimInstance Win32_BIOS -CimSession $cim -ErrorAction SilentlyContinue
            $biosVer  = $bios.SMBIOSBIOSVersion
            $biosDate = if ($bios.ReleaseDate) { ([DateTime]$bios.ReleaseDate).ToString("yyyy-MM-dd") } else { "?" }
            $biosInfo = "$biosVer  ($biosDate)"
        } catch {}

        # --- 9. ANAKART ---
        $mbInfo = ""
        try {
            $mb = Get-CimInstance Win32_BaseBoard -CimSession $cim -ErrorAction SilentlyContinue
            $mbInfo = "$($mb.Manufacturer) $($mb.Product)"
        } catch {}

        # --- 10. GPU DETAY (VRAM) ---
        $gpuDetail = @()
        try {
            foreach ($g in $gpus) {
                $vramGB = if ($g.AdapterRAM -gt 0) { [Math]::Round($g.AdapterRAM / 1GB, 1) } else { "?" }
                $gpuDetail += [PSCustomObject]@{
                    Name   = $g.Name
                    VRAM   = $vramGB
                    Driver = $g.DriverVersion
                }
            }
        } catch {}

        # --- 11. DİSK DETAY (Fiziksel Diskler) ---
        $diskDetail = @()
        try {
            foreach ($d in (Get-CimInstance Win32_DiskDrive -CimSession $cim -ErrorAction SilentlyContinue)) {
                $sizeGB = [Math]::Round($d.Size / 1GB, 0)
                $diskDetail += [PSCustomObject]@{
                    Model  = $d.Model
                    SizeGB = $sizeGB
                    Serial = $d.SerialNumber
                }
            }
        } catch {}
		# --- 12. AKTİF DNS (v1.2.6: WMI yerine Get-DnsClientServerAddress — netsh ile set edilen DNS i de gorur) ---
        # WMI Win32_NetworkAdapterConfiguration.DNSServerSearchOrder cache'inden okurdu, netsh sonrasi stale kalabiliyordu.
        # Get-DnsClientServerAddress live DNS Client query'si yapar, IPv4 (AddressFamily=2) ile filtreli.
        $activeDns = "Bilinmiyor"
        try {
            $upAdapters = Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq "Up" -and $_.InterfaceAlias -notmatch "Loopback|VPN|Virtual|Tunnel|Hyper-V" }
            $dnsList = @()
            foreach ($a in $upAdapters) {
                $dns = Get-DnsClientServerAddress -InterfaceAlias $a.InterfaceAlias -AddressFamily IPv4 -ErrorAction SilentlyContinue |
                       Select-Object -ExpandProperty ServerAddresses -ErrorAction SilentlyContinue
                if ($dns) { $dnsList += $dns }
            }
            if ($dnsList.Count -gt 0) { $activeDns = ($dnsList | Select-Object -Unique) -join ", " }
        } catch {}

        # --- 13. WINDOWS TAM SURUM (v1.2.24): Edition + DisplayVersion + Build.UBR ---
        $winFullVer = ""
        try {
            $prodName = (Get-ItemProperty -Path $regPath -Name "ProductName" -ErrorAction SilentlyContinue).ProductName
            $buildNum = (Get-ItemProperty -Path $regPath -Name "CurrentBuildNumber" -ErrorAction SilentlyContinue).CurrentBuildNumber
            $ubr      = (Get-ItemProperty -Path $regPath -Name "UBR" -ErrorAction SilentlyContinue).UBR
            # Win11 ProductName hala "Windows 10..." diyebilir; build >= 22000 ise Windows 11 olarak duzelt
            if ($buildNum -and [int]$buildNum -ge 22000 -and $prodName -match "Windows 10") {
                $prodName = $prodName -replace "Windows 10", "Windows 11"
            }
            $buildStr = if ($ubr) { "$buildNum.$ubr" } else { "$buildNum" }
            # txtDashOS zaten "Caption (DisplayVersion)" gosteriyor; burada sadece build satiri (tekrar olmasin)
            $winFullVer = "$displayVersion  ·  derleme $buildStr"
        } catch { $winFullVer = "" }

        # --- 14. CALISMA SURESI / UPTIME (v1.2.24) ---
        $uptimeStr = ""
        try {
            $bootTime = $os.LastBootUpTime
            if ($bootTime -is [string]) { $bootTime = [Management.ManagementDateTimeConverter]::ToDateTime($bootTime) }
            $up = (Get-Date) - $bootTime
            $parts = @()
            if ($up.Days -gt 0)  { $parts += "$($up.Days) gün" }
            if ($up.Hours -gt 0) { $parts += "$($up.Hours) saat" }
            $parts += "$($up.Minutes) dk"
            $uptimeStr = ($parts -join " ")
        } catch {}

        # --- 15. SISTEM TURU + SECURE BOOT + TPM (v1.2.24) ---
        $secStr = ""
        try {
            # Firmware turu: UEFI vs Legacy BIOS
            $fwType = "?"
            try { if ($env:firmware_type) { $fwType = $env:firmware_type } } catch {}
            if ($fwType -notmatch "UEFI|Legacy") {
                # Fallback: SecureBoot key varsa UEFI demektir
                if (Test-Path "HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State") { $fwType = "UEFI" } else { $fwType = "Legacy BIOS" }
            }
            # Secure Boot durumu (locale-independent registry)
            $sbState = "Bilinmiyor"
            try {
                $sbVal = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State" -Name "UEFISecureBootEnabled" -ErrorAction SilentlyContinue).UEFISecureBootEnabled
                if ($null -ne $sbVal) { $sbState = if ([int]$sbVal -eq 1) { "açık" } else { "kapalı" } }
            } catch {}
            # TPM (CIM — Get-Tpm yavas/yetki isteyebilir)
            $tpmStr = "Yok"
            try {
                $tpm = Get-CimInstance -CimSession $cim -Namespace "root\cimv2\Security\MicrosoftTpm" -ClassName Win32_Tpm -ErrorAction SilentlyContinue | Select-Object -First 1
                if ($tpm) {
                    $spec = ($tpm.SpecVersion -split ",")[0].Trim()
                    $tpmStr = if ($tpm.IsEnabled_InitialValue) { "TPM $spec (aktif)" } else { "TPM $spec (pasif)" }
                }
            } catch {}
            $secStr = "$fwType  ·  Secure Boot $sbState  ·  $tpmStr"
        } catch {}

        # --- 16. SON WINDOWS UPDATE (v1.2.24) ---
        $lastUpdStr = ""
        try {
            $hf = Get-CimInstance -CimSession $cim -ClassName Win32_QuickFixEngineering -ErrorAction SilentlyContinue |
                  Where-Object { $_.InstalledOn } | Sort-Object InstalledOn -Descending | Select-Object -First 1
            if ($hf) {
                $instDate = $hf.InstalledOn
                $daysAgo = [Math]::Round(((Get-Date) - $instDate).TotalDays)
                $lastUpdStr = "$($hf.HotFixID)  ·  $($instDate.ToString('dd.MM.yyyy'))"
            } else {
                $lastUpdStr = "bilgi yok"
            }
        } catch { $lastUpdStr = "okunamadı" }

        # v1.3.0 (§54): kart alt satırı ve sistem bilgisi satırları (etiket solda, değerde ön ek yok)
        $ramTxt  = '{0:N1} / {1:N1} GB' -f $usedRamGB, $totalRamGB
        $diskTxt = '{0:0} / {1:0} GB' -f $diskUsedGB, $diskSizeGB
        $memInfo = '{0:N1} GB' -f $totalRamGB
        if ($ramModules.Count -gt 0) {
            $memInfo += "  ·  $($ramModules.Count) modül"
            $mhz = ($ramModules | Measure-Object -Property CfgMHz -Maximum).Maximum
            if ($mhz -gt 0) { $memInfo += "  ·  $mhz MHz" }
        }
        $diskInfo = ('{0:0} GB  ·  {1:0} GB dolu  ·  ' -f $diskSizeGB, $diskUsedGB) + $smartStatus

        # CimSession'ı kapat
        if ($cim) { Remove-CimSession $cim -ErrorAction SilentlyContinue }

        # Sonuç Paketi
        return @{
            OS = $osName
            CPU = $cpuName
            GPU = $gpuName
			DNS = $activeDns
            
            RAM_Text = $ramTxt
            RAM_Info = $memInfo
            RAM_Val  = $ramPercent
            
            Disk_Text = $diskTxt
            Disk_Info = $diskInfo
            Disk_Val  = $diskPercent
            
            Smart      = $smartStatus
            RamModules = $ramModules
            BiosInfo   = $biosInfo
            MbInfo     = $mbInfo
            GpuDetail  = $gpuDetail
            DiskDetail = $diskDetail

            WinFullVer = $winFullVer
            Uptime     = $uptimeStr
            Security   = $secStr
            LastUpdate = $lastUpdStr
        }
    })

    $script:DashAsync = $script:DashRunspace.BeginInvoke()
    
	# 2. Zamanlayıcı (DASHBOARD SONUÇLANDIRICI)
	$script:DashTimer = New-Object System.Windows.Threading.DispatcherTimer
	$script:DashTimer.Interval = [TimeSpan]::FromMilliseconds(500)

	$script:DashTimer.Add_Tick({
		# Eğer async handle null ise veya işlem bitmemişse hiç girme
		if ($null -eq $script:DashAsync -or -not $script:DashAsync.IsCompleted) { return }

		# 1. Hemen durdur (Birden fazla tetiklenmeyi ve çakışmayı önle)
		$script:DashTimer.Stop()
		
		$result = $null
		try {
			# 2. Arka plan verisini al
			$rawResult = $script:DashRunspace.EndInvoke($script:DashAsync)
			
			# PowerShell asenkron sonuçları bazen koleksiyon içinde döndürür, tekil nesneye indirge
			if ($rawResult -is [System.Collections.IEnumerable]) { 
				$result = $rawResult | Select-Object -First 1 
			} else { 
				$result = $rawResult 
			}
			
			if ($null -ne $result) {
				# 3. Cache Güncelleme (Atomik İşlem)
				$global:DashResult = $result
				$global:DashCache  = $result
				$global:DashCacheTime = Get-Date

				# --- 4. ARAYÜZ GÜNCELLEME (Hata Toleranslı) ---
				$txtDashOS.Text   = [string]$result.OS
				$txtDashCPU.Text  = [string]$result.CPU
				$txtDashGPU.Text  = [string]$result.GPU
				$txtDashDNS.Text  = [string]$result.DNS
				
				# RAM Kontrolü
				$txtDashRAM.Text = [string]$result.RAM_Text
				$pbDashRAM.Value = [double]$result.RAM_Val
				$pbDashRAM.Foreground = Get-DashBarBrush ($result.RAM_Val -gt 85)
				
				# Disk Kontrolü
				$txtDashDisk.Text = [string]$result.Disk_Text
				$pbDashDisk.Value = [double]$result.Disk_Val
				
				# Kritik Durum Renklendirmesi (P7 iyileştirmesi)
				$pbDashDisk.Foreground = Get-DashBarBrush ($result.Disk_Val -gt 90 -or $result.Smart -match "Kritik")
				if ($script:txtDashRamInfo)  { $script:txtDashRamInfo.Text  = [string]$result.RAM_Info }
				if ($script:txtDashDiskInfo) { $script:txtDashDiskInfo.Text = [string]$result.Disk_Info }
				
				# Sistem & Güvenlik kartı (v1.2.24)
				if ($txtDashWinVer)     { $txtDashWinVer.Text     = [string]$result.WinFullVer }
				if ($txtDashUptime)     { $txtDashUptime.Text     = [string]$result.Uptime }
				if ($txtDashSecurity)   { $txtDashSecurity.Text   = [string]$result.Security }
				if ($txtDashLastUpdate) { $txtDashLastUpdate.Text = [string]$result.LastUpdate }

				$txtDashSubHeader.Text = "✅ Sistem verileri başarıyla güncellendi."
				$txtDashSubHeader.Foreground = Get-DashBrush '#8A919C'
				
				# Buton Kilidini Aç
				if ($btnHardwareDetail) { $btnHardwareDetail.IsEnabled = $true }
                try { Update-DashRecommendations } catch {}
                try { Start-WingetUpdateCheck } catch {}
			}
		} 
		catch {
			# 5. Hata Yönetimi
			$txtDashSubHeader.Text = "⚠️ Donanım verileri okunamadı!"
			$txtDashSubHeader.Foreground = Get-DashBrush '#E5484D'
			WpfLog "Dashboard Hatası: $($_.Exception.Message)"
		} 
		finally {
			# 6. KRİTİK BELLEK TEMİZLİĞİ (B1 Çözümü)
			if ($script:DashRunspace) { 
				$script:DashRunspace.Dispose()
				$script:DashRunspace = $null 
			}
			# Nesne referanslarını tamamen kopar (Garbage Collector'a yardım et)
			$script:DashAsync = $null
			$result = $null
			$rawResult = $null
		}
	})

$script:DashTimer.Start()
}

# v1.3.0: Genel bakış öneri motoru — yalnız okur, tıklayınca sayfaya gider, kendiliğinden işlem yok.
function Get-DashAgeText([datetime]$when) {
    $m = [int]((Get-Date) - $when).TotalMinutes
    if ($m -lt 1) { return T 'dash_age_now' }
    if ($m -lt 60) { return (T 'dash_age_min') -f $m }
    return (T 'dash_age_hour') -f [int]($m / 60)
}

function Get-DashStartupEnabledCount {
    $n = 0
    $regs = @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
    )
    $apprs = @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run32'
    )
    for ($i = 0; $i -lt $regs.Count; $i++) {
        if (-not (Test-Path $regs[$i])) { continue }
        $props = Get-ItemProperty -Path $regs[$i] -ErrorAction SilentlyContinue
        $appr = $null
        if (Test-Path $apprs[$i]) { $appr = Get-ItemProperty -Path $apprs[$i] -ErrorAction SilentlyContinue }
        foreach ($p in $props.PSObject.Properties) {
            if ($p.Name -match '^PS' -or $p.Name -eq 'System') { continue }
            $name = $p.Name
            if ($name -match '^(?:GeminiDisabled|MrCleanDisabled)_') { continue }
            $on = $true
            if ($appr -and $null -ne $appr.$name) {
                $b = $appr.$name[0]
                if ($b -eq 0x03 -or $b -eq 0x01 -or ($b % 2 -ne 0)) { $on = $false }
            }
            if ($on) { $n++ }
        }
    }
    foreach ($dir in @("$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup", "$env:ALLUSERSPROFILE\Microsoft\Windows\Start Menu\Programs\StartUp")) {
        if (-not (Test-Path $dir)) { continue }
        Get-ChildItem -Path $dir -File -ErrorAction SilentlyContinue | ForEach-Object {
            if ($_.Name -eq 'desktop.ini' -or $_.Extension -eq '.disabled') { return }
            $n++
        }
    }
    return $n
}

function Read-WingetUpdateCache {
    if ($script:WgUpdateCache) { return $script:WgUpdateCache }
    if ($script:WgUpdateCachePath -and (Test-Path $script:WgUpdateCachePath)) {
        try {
            $j = Get-Content -LiteralPath $script:WgUpdateCachePath -Raw -Encoding UTF8 | ConvertFrom-Json
            $script:WgUpdateCache = [PSCustomObject]@{ Status = [string]$j.Status; Count = [int]$j.Count; Time = [datetime]$j.Time }
            return $script:WgUpdateCache
        } catch {}
    }
    return $null
}

function Save-WingetUpdateCache($obj) {
    $script:WgUpdateCache = $obj
    try {
        if (-not (Test-Path $CacheDir)) { New-Item -ItemType Directory -Path $CacheDir -Force | Out-Null }
        $obj | ConvertTo-Json | Set-Content -LiteralPath $script:WgUpdateCachePath -Encoding UTF8
    } catch {}
}

function Start-WingetUpdateCheck {
    if ($script:WgUpdateChecking) { return }
    $cur = Read-WingetUpdateCache
    if ($cur -and $cur.Time -and ((Get-Date) - $cur.Time).TotalHours -lt 6) { return }
    $wg = Get-Command winget -ErrorAction SilentlyContinue
    if (-not $wg) {
        Save-WingetUpdateCache ([PSCustomObject]@{ Status = 'fail'; Count = 0; Time = Get-Date })
        Update-DashRecommendations
        return
    }
    $script:WgUpdateChecking = $true
    $rs = [powershell]::Create()
    $rs.AddScript({
        $ErrorActionPreference = 'SilentlyContinue'
        $out = & winget upgrade --include-unknown --accept-source-agreements --disable-interactivity 2>&1 | Out-String
        $n = 0
        if ($out -match '(?m)(\d+)\s+upgrade') { $n = [int]$Matches[1] }
        elseif ($out -match '(?m)(\d+)\s+paket') { $n = [int]$Matches[1] }
        $ok = $LASTEXITCODE -eq 0 -or $out -match 'upgrade|güncelle|No installed package|available'
        [PSCustomObject]@{ Ok = [bool]$ok; Count = $n; RawLen = $out.Length }
    }) | Out-Null
    $async = $rs.BeginInvoke()
    Start-MrCleanMeasure 'Winget güncelleme denetimi'   # v1.3.0 (§87)
    $tm = New-Object System.Windows.Threading.DispatcherTimer
    $tm.Interval = [TimeSpan]::FromMilliseconds(800)
    $tm.Add_Tick({
        if (-not $async.IsCompleted) { return }
        $tm.Stop()
        try {
            $r = @($rs.EndInvoke($async)) | Select-Object -First 1
            Stop-MrCleanMeasure 'Winget güncelleme denetimi'   # v1.3.0 (§87)
            $st = if ($r -and $r.Ok) { 'ok' } else { 'fail' }
            $c = if ($r) { [int]$r.Count } else { 0 }
            Save-WingetUpdateCache ([PSCustomObject]@{ Status = $st; Count = $c; Time = Get-Date })
        } catch {
            Save-WingetUpdateCache ([PSCustomObject]@{ Status = 'fail'; Count = 0; Time = Get-Date })
        } finally {
            $rs.Dispose()
            $script:WgUpdateChecking = $false
            try { Update-DashRecommendations } catch {}
        }
    }.GetNewClosure())
    $tm.Start()
}

function Open-DashTarget([string]$tabName) {
    # v1.3.0 (§98): Winget önerisinden gelince "Kurulu" süzgeci açık gelir (sekme seçilince kurulu durumu da taranır)
    if ($tabName -eq 'tabWinget' -and $chipWgInstalled) { try { $chipWgInstalled.IsChecked = $true } catch {} }
    $tab = $Win.FindName($tabName)
    if ($tab) { $tab.IsSelected = $true }
}

# v1.3.0 (§54): öneri satırı Onizleme5 Rec görünümünde — simge kutusu + başlık + tek satır kaynak/yaş + ok. Tıklayınca yalnız sekme seçilir.
function Add-DashRecRow($title, $src, $tab) {
    if (-not $script:pnlDashRec) { return }
    $glyph = switch ($tab) {
        'tabTweaks'     { [char]0xE9E9 }
        'tabStartup'    { [char]0xE7E8 }
        'tabWinget'     { [char]0xE7B8 }
        'tabLargeFiles' { [char]0xEDA2 }
        default         { [char]0xE946 }
    }
    $bc = New-Object System.Windows.Media.BrushConverter
    $glc = New-Object System.Windows.GridLengthConverter
    $iconFont = New-Object System.Windows.Media.FontFamily('Segoe Fluent Icons, Segoe MDL2 Assets')
    $btn = New-Object System.Windows.Controls.Button
    $btn.Style = $Win.FindResource('DashRec')
    $btn.Tag = $tab
    $btn.ToolTip = "$title`n$src"
    $g = New-Object System.Windows.Controls.Grid
    foreach ($w in @('44', '*', 'Auto')) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = $glc.ConvertFromString($w)
        $g.ColumnDefinitions.Add($cd)
    }
    $ib = New-Object System.Windows.Controls.Border
    $ib.Width = 34; $ib.Height = 34; $ib.CornerRadius = 8
    $ib.Background = $bc.ConvertFromString('#1C2433')
    $ib.HorizontalAlignment = 'Left'
    $ic = New-Object System.Windows.Controls.TextBlock
    $ic.Text = [string]$glyph; $ic.FontFamily = $iconFont; $ic.FontSize = 16
    $ic.Foreground = $bc.ConvertFromString('#8CB4FF')
    $ic.HorizontalAlignment = 'Center'; $ic.VerticalAlignment = 'Center'
    $ib.Child = $ic
    [void]$g.Children.Add($ib)
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.VerticalAlignment = 'Center'
    [System.Windows.Controls.Grid]::SetColumn($sp, 1)
    $t1 = New-Object System.Windows.Controls.TextBlock
    $t1.Text = $title; $t1.FontSize = 14; $t1.FontWeight = 'SemiBold'
    $t1.Foreground = $bc.ConvertFromString('#E6E8EB'); $t1.TextTrimming = 'CharacterEllipsis'
    $t2 = New-Object System.Windows.Controls.TextBlock
    $t2.Text = $src; $t2.FontSize = 13; $t2.Margin = '0,2,0,0'
    $t2.Foreground = $bc.ConvertFromString('#8A919C'); $t2.TextTrimming = 'CharacterEllipsis'
    [void]$sp.Children.Add($t1); [void]$sp.Children.Add($t2)
    [void]$g.Children.Add($sp)
    $ch = New-Object System.Windows.Controls.TextBlock
    $ch.Text = [string][char]0xE76C; $ch.FontFamily = $iconFont; $ch.FontSize = 12
    $ch.Foreground = $bc.ConvertFromString('#5D6470')
    $ch.Margin = '8,0,0,0'; $ch.VerticalAlignment = 'Center'
    [System.Windows.Controls.Grid]::SetColumn($ch, 2)
    [void]$g.Children.Add($ch)
    $btn.Content = $g
    $btn.Add_Click({ Open-DashTarget ([string]$this.Tag) })
    [void]$script:pnlDashRec.Children.Add($btn)
}

# v1.3.0 (§54): "Son işlemler" yalnız gerçek kayıttan — clean_history.json (Temizlik) ve tweak_history.log (Uygula / Geri al). Kayıt yoksa blok gizli.
function Get-DashHistoryItems {
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($h in @(Get-CleanHistory)) {
        $t = [datetime]::MinValue
        if (-not [datetime]::TryParse("$($h.Time)", [ref]$t)) { continue }
        $txt = (T 'dash_hist_clean') -f (Format-CleanSize ([double]$h.Bytes))
        $items.Add([PSCustomObject]@{ Time = $t; Text = $txt })
    }
    $logPath = Join-Path $LogsDir 'tweak_history.log'
    if (Test-Path -LiteralPath $logPath) {
        $lines = @(Get-Content -LiteralPath $logPath -Tail 600 -Encoding UTF8 -ErrorAction SilentlyContinue)
        $cur = $null
        foreach ($ln in $lines) {
            if ($ln -match '^=== \[(.+?)\] (.+?) ===$') {
                $cur = $null
                try { $cur = [DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture) } catch {}
                continue
            }
            if (-not $cur) { continue }
            $txt = $null
            if ($ln -match '^UYGULANAN \((\d+)') { $txt = (T 'dash_hist_tw_apply') -f [int]$Matches[1] }
            elseif ($ln -match '^GERI ALINAN \((\d+)') { $txt = (T 'dash_hist_tw_undo') -f [int]$Matches[1] }
            if ($txt) { $items.Add([PSCustomObject]@{ Time = $cur; Text = $txt }) }
        }
    }
    return @($items | Sort-Object Time -Descending | Select-Object -First 4)
}

function Update-DashHistory {
    if (-not $script:pnlDashHist) { return }
    $script:pnlDashHist.Children.Clear()
    $list = @(Get-DashHistoryItems)
    if ($script:bdDashHist) { $script:bdDashHist.Visibility = if ($list.Count -gt 0) { 'Visible' } else { 'Collapsed' } }
    $bc = New-Object System.Windows.Media.BrushConverter
    $glc = New-Object System.Windows.GridLengthConverter
    $today = (Get-Date).Date
    [System.Windows.Controls.Grid]::SetIsSharedSizeScope($script:pnlDashHist, $true)
    foreach ($it in $list) {
        $when = if ($it.Time.Date -eq $today) { "$(T 'cl_today') $($it.Time.ToString('HH:mm'))" }
                elseif ($it.Time.Date -eq $today.AddDays(-1)) { "$(T 'dash_yesterday') $($it.Time.ToString('HH:mm'))" }
                else { $it.Time.ToString('dd.MM') }
        $g = New-Object System.Windows.Controls.Grid
        $g.Margin = '0,7,0,7'
        $cw = New-Object System.Windows.Controls.ColumnDefinition
        $cw.Width = $glc.ConvertFromString('Auto'); $cw.MinWidth = 96; $cw.SharedSizeGroup = 'DashHistWhen'
        $g.ColumnDefinitions.Add($cw)
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = $glc.ConvertFromString('*')
        $g.ColumnDefinitions.Add($cd)
        $a = New-Object System.Windows.Controls.TextBlock
        $a.Text = $when; $a.FontSize = 13; $a.Foreground = $bc.ConvertFromString('#6B7280'); $a.VerticalAlignment = 'Center'
        $a.Margin = '0,0,16,0'
        $b = New-Object System.Windows.Controls.TextBlock
        $b.Text = $it.Text; $b.FontSize = 13.5; $b.Foreground = $bc.ConvertFromString('#C9CED6')
        $b.TextTrimming = 'CharacterEllipsis'; $b.VerticalAlignment = 'Center'
        [System.Windows.Controls.Grid]::SetColumn($b, 1)
        [void]$g.Children.Add($a); [void]$g.Children.Add($b)
        [void]$script:pnlDashHist.Children.Add($g)
    }
}

function Update-DashRecommendations {
    if (-not $script:pnlDashRec -and -not $txtDashSubHeader) { return }
    $pending = 0
    if ($script:pnlDashRec) { $script:pnlDashRec.Children.Clear() }

    $tw = 0
    if ($script:TweakPendingSet) { $tw = $script:TweakPendingSet.Count }
    if ($tw -gt 0) {
        $pending++
        Add-DashRecRow ((T 'dash_tw_n') -f $tw) (T 'dash_src_tw') 'tabTweaks'
    }

    $su = 0
    try { $su = Get-DashStartupEnabledCount } catch {}
    Add-DashRecRow ((T 'dash_su_n') -f $su) (T 'dash_src_su') 'tabStartup'

    $wg = Read-WingetUpdateCache
    if ($script:WgUpdateChecking -and -not $wg) {
        Add-DashRecRow (T 'dash_wg_wait') ((T 'dash_src_wg') -f (T 'dash_age_now')) 'tabWinget'
    } elseif (-not $wg) {
        Add-DashRecRow (T 'dash_wg_wait') ((T 'dash_src_wg') -f '—') 'tabWinget'
    } elseif ($wg.Status -eq 'fail') {
        $pending++
        Add-DashRecRow (T 'dash_wg_fail') ((T 'dash_src_wg') -f (Get-DashAgeText $wg.Time)) 'tabWinget'
    } elseif ($wg.Count -gt 0) {
        $pending++
        Add-DashRecRow ((T 'dash_wg_n') -f $wg.Count) ((T 'dash_src_wg') -f (Get-DashAgeText $wg.Time)) 'tabWinget'
    } else {
        Add-DashRecRow (T 'dash_wg_ok0') ((T 'dash_src_wg') -f (Get-DashAgeText $wg.Time)) 'tabWinget'
    }

    $diskVal = $null
    if ($global:DashCache) { try { $diskVal = [double]$global:DashCache.Disk_Val } catch {} }
    if ($diskVal -gt 90) {
        $pending++
        Add-DashRecRow ((T 'dash_disk_full') -f [int]$diskVal) ((T 'dash_src_hw') -f (Get-DashAgeText $global:DashCacheTime)) 'tabLargeFiles'
    }

    if ($script:txtDashHero) {
        $script:txtDashHero.Text = "$pending"
        $script:txtDashHeroSub.Text = if ($pending -gt 0) { (T 'dash_rec_n') -f $pending } else { T 'dash_rec_none' }
    }
    if ($txtDashSubHeader) {
        $txtDashSubHeader.Text = if ($pending -gt 0) { (T 'dash_rec_n') -f $pending } else { T 'dash_rec_none' }
        $txtDashSubHeader.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#8A919C')
    }
    if ($script:txtDashHwAge -and $global:DashCacheTime) {
        $script:txtDashHwAge.Text = (T 'dash_src_hw') -f (Get-DashAgeText $global:DashCacheTime)
    }
    try { Update-DashHistory } catch {}
}

if ($script:cardDashRec) {
    $script:cardDashRec.Add_MouseLeftButtonUp({
        if ($script:TweakPendingSet -and $script:TweakPendingSet.Count -gt 0) { Open-DashTarget 'tabTweaks' }
        else { Open-DashTarget 'tabWinget' }
    })
}
if ($script:cardDashDisk) { $script:cardDashDisk.Add_MouseLeftButtonUp({ Open-DashTarget 'tabLargeFiles' }) }

# =========================================================
# Show-BenchmarkPanel (v1.2.10) — Performans olcum + snapshot karsilastirma
# 9 metrik suite (Get-BenchSnapshot) UI thread'de senkron calistirilir, Do-Events ile UI
# her 20ms nefes alir. Snapshot listesi DataGrid'de gosterilir, 2 secim ile diff modal.
# =========================================================

function Show-BenchDiffModal {
    param([Parameter(Mandatory=$true)]$SnapA, [Parameter(Mandatory=$true)]$SnapB)
    $rows = Compare-BenchSnapshots -SnapshotA $SnapA -SnapshotB $SnapB
    $xamlD = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="🔄 Benchmark Karsilastirma" Height="600" Width="920"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner" WindowStyle="ToolWindow" ResizeMode="CanResize">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid Margin="14">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <TextBlock Grid.Row="0" Text="🔄 Benchmark Karsilastirma" Foreground="#E6E8EB" FontSize="20" FontWeight="Bold" Margin="0,0,0,6"/>

        <Grid Grid.Row="1" Margin="0,0,0,10">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>
            <Border Grid.Column="0" Background="#15181E" CornerRadius="5" Padding="10" Margin="0,0,5,0">
                <StackPanel>
                    <TextBlock Text="A (Once)" Foreground="#8CB4FF" FontWeight="Bold"/>
                    <TextBlock x:Name="lblALabel" Foreground="#E6E8EB" FontSize="13"/>
                    <TextBlock x:Name="lblATime"  Foreground="#8A919C" FontSize="12"/>
                </StackPanel>
            </Border>
            <Border Grid.Column="1" Background="#15181E" CornerRadius="5" Padding="10" Margin="5,0,0,0">
                <StackPanel>
                    <TextBlock Text="B (Sonra)" Foreground="#E0A23B" FontWeight="Bold"/>
                    <TextBlock x:Name="lblBLabel" Foreground="#E6E8EB" FontSize="13"/>
                    <TextBlock x:Name="lblBTime"  Foreground="#8A919C" FontSize="12"/>
                </StackPanel>
            </Border>
        </Grid>

        <Border Grid.Row="2" Background="#15181E" CornerRadius="5" BorderBrush="#232831" BorderThickness="1">
            <ListView x:Name="lvDiff" Background="Transparent" BorderThickness="0" Foreground="#E6E8EB">
                <ListView.View>
                    <GridView>
                        <GridView.ColumnHeaderContainerStyle>
                            <Style TargetType="GridViewColumnHeader" BasedOn="{StaticResource SwGridHeader}"/>
                        </GridView.ColumnHeaderContainerStyle>
                        <GridViewColumn Header="Metrik"   Width="260" DisplayMemberBinding="{Binding Label}"/>
                        <GridViewColumn Header="A"        Width="100" DisplayMemberBinding="{Binding AValue}"/>
                        <GridViewColumn Header="B"        Width="100" DisplayMemberBinding="{Binding BValue}"/>
                        <GridViewColumn Header="Delta"    Width="90"  DisplayMemberBinding="{Binding Delta}"/>
                        <GridViewColumn Header="% Degis." Width="90"  DisplayMemberBinding="{Binding PctDisplay}"/>
                        <GridViewColumn Header="Birim"    Width="60"  DisplayMemberBinding="{Binding Unit}"/>
                        <GridViewColumn Header="Sonuc"    Width="110" DisplayMemberBinding="{Binding VerdictIcon}"/>
                    </GridView>
                </ListView.View>
                <ListView.ItemContainerStyle>
                    <Style TargetType="ListViewItem" BasedOn="{StaticResource SwListRow}"/>   <!-- v1.3.0 (§85) -->
                </ListView.ItemContainerStyle>
            </ListView>
        </Border>

        <TextBlock Grid.Row="3" x:Name="txtSummary" Foreground="#8A919C" FontSize="12" Margin="0,8,0,0" TextWrapping="Wrap"/>

        <StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,8,0,0">
            <Button Style="{StaticResource SwBtnPrimary}" x:Name="btnDChart" Content="📊 Grafik Olarak Göster" MinWidth="200" Height="30" Margin="0,0,8,0" Cursor="Hand"/>
            <Button x:Name="btnDClose" Content="@@m_close@@" MinWidth="100" Height="30" Cursor="Hand"/>
        </StackPanel>
    </Grid>
</Window>
"@
    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlD))
        $w = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $w
        $w.Owner = $Win

        $w.FindName('lblALabel').Text = if ($SnapA.label) { $SnapA.label } else { "(etiketsiz)" }
        $w.FindName('lblBLabel').Text = if ($SnapB.label) { $SnapB.label } else { "(etiketsiz)" }
        $w.FindName('lblATime').Text  = $SnapA.timestamp
        $w.FindName('lblBTime').Text  = $SnapB.timestamp

        $lv = $w.FindName('lvDiff')
        $win = 0; $loss = 0; $neutral = 0; $na = 0
        foreach ($r in $rows) {
            $icon = switch ($r.Verdict) {
                'better'  { '🟢 Iyilesti';  $win++ }
                'worse'   { '🔴 Kotulesti'; $loss++ }
                'neutral' { '⚪ Aynı';      $neutral++ }
                default   { '— Yok';        $na++ }
            }
            $r | Add-Member -NotePropertyName VerdictIcon -NotePropertyValue $icon -Force

            # PctDisplay: +/- yerine ok yonu + mutlak deger. Eksi sign "iyi" verdict ile cakisip
            # kafa karistiriyordu — ok raw delta yonunu gosterir, renk yargi (chart ile tutarli).
            if ($null -ne $r.PctChange) {
                $pn = [double]$r.PctChange
                $ar = if     ($pn -gt 0.05)  { [char]0x2191 }
                      elseif ($pn -lt -0.05) { [char]0x2193 }
                      else                    { [char]0x2022 }
                $disp = ("{0} {1:F1}%" -f $ar, [Math]::Abs($pn))
            } else { $disp = "—" }
            $r | Add-Member -NotePropertyName PctDisplay -NotePropertyValue $disp -Force

            $lv.Items.Add($r) | Out-Null
        }
        $w.FindName('txtSummary').Text = ("Toplam {0} metrik · 🟢 {1} iyilesti · 🔴 {2} kotulesti · ⚪ {3} ayni · — {4} olculemedi" -f $rows.Count, $win, $loss, $neutral, $na)

        # Grafik butonu — chart modal'ini ac, owner = diff modal
        $w.FindName('btnDChart').Add_Click({
            try {
                $aLab = if ($SnapA.label) { $SnapA.label } else { "(etiketsiz)" }
                $bLab = if ($SnapB.label) { $SnapB.label } else { "(etiketsiz)" }
                Show-BenchDiffChart -Rows $rows -ALabel $aLab -BLabel $bLab -ATime $SnapA.timestamp -BTime $SnapB.timestamp -Owner $w
            } catch {
                WpfLog ("BenchChart Hata: " + $_.Exception.Message)
            }
        })
        $w.FindName('btnDClose').Add_Click({ $w.Close() })
        $w.ShowDialog() | Out-Null
    } catch {
        WpfLog ("BenchDiff Hata: " + $_.Exception.Message)
    }
}

# =========================================================
# Show-BenchDiffChart (v1.2.10) — Karsilastirma sonucunu yatay bar chart olarak gosterir.
# WPF Canvas uzerinde Rectangle + TextBlock cizimi (3rd party kutuphane yok). Her metrik bir
# bar: uzunluk = |% degisim|, renk = verdict (better/worse/neutral/n/a).
# =========================================================
function Show-BenchDiffChart {
    param(
        [Parameter(Mandatory=$true)]$Rows,
        [string]$ALabel = "A",
        [string]$BLabel = "B",
        [string]$ATime  = "",
        [string]$BTime  = "",
        $Owner = $null
    )

    # Sadece sayisal (N/A olmayan) ve degisimli metrikleri al — temiz chart
    $chartRows = @($Rows | Where-Object { $null -ne $_.PctChange })
    if ($chartRows.Count -eq 0) {
        [System.Windows.MessageBox]::Show("Grafige cevrilebilir veri yok (tum metrikler N/A).", "Bilgi") | Out-Null
        return
    }

    # Bar genisligi olceklendirme — %50 hedef tavan; outlier varsa max'a clamp ama tepe %100'de
    $maxPct = 10.0
    foreach ($r in $chartRows) {
        $abs = [Math]::Abs([double]$r.PctChange)
        if ($abs -gt $maxPct -and $abs -le 200) { $maxPct = $abs }
    }
    if ($maxPct -lt 10) { $maxPct = 10 }  # minimum scale (cok kucuk degisimler de gorunsun)
    if ($maxPct -gt 100) { $maxPct = 100 } # ust tavan

    # Layout sabitleri (pixel)
    $labelW = 270
    $pctW   = 70
    $barAreaW = 440
    $barH   = 18
    $rowH   = 30
    $marginTop = 12
    $canvasW = $labelW + $pctW + $barAreaW + 80
    $canvasH = ($chartRows.Count * $rowH) + (2 * $marginTop)

    # px per percent point
    $pxPerPct = ($barAreaW - 20) / $maxPct

    $xamlC = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="📊 Bench Karsilastirma — Grafik" Height="640" Width="$($canvasW + 60)"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="CanResize" MinWidth="700" MinHeight="400">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid Margin="14">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <TextBlock Grid.Row="0" Text="📊 Karsilastirma Grafigi (yuzdesel degisim)" Foreground="#E6E8EB" FontSize="18" FontWeight="Bold" Margin="0,0,0,4"/>

        <Grid Grid.Row="1" Margin="0,0,0,8">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>
            <Border Grid.Column="0" Background="#15181E" CornerRadius="4" Padding="8" Margin="0,0,5,0">
                <StackPanel>
                    <TextBlock Foreground="#8CB4FF" FontWeight="Bold" FontSize="13" Text="A (Once)"/>
                    <TextBlock Foreground="#E6E8EB" FontSize="12" x:Name="lblCA"/>
                </StackPanel>
            </Border>
            <Border Grid.Column="1" Background="#15181E" CornerRadius="4" Padding="8" Margin="5,0,0,0">
                <StackPanel>
                    <TextBlock Foreground="#E0A23B" FontWeight="Bold" FontSize="13" Text="B (Sonra)"/>
                    <TextBlock Foreground="#E6E8EB" FontSize="12" x:Name="lblCB"/>
                </StackPanel>
            </Border>
        </Grid>

        <!-- LEGEND -->
        <StackPanel Grid.Row="2" Orientation="Vertical" Margin="0,0,0,8">
            <StackPanel Orientation="Horizontal" Margin="0,0,0,3">
                <Rectangle Width="14" Height="14" Fill="#3FB97A" VerticalAlignment="Center"/>
                <TextBlock Text="  🟢 Iyilesti     " Foreground="#C9CED6" FontSize="12" VerticalAlignment="Center" Margin="2,0,12,0"/>
                <Rectangle Width="14" Height="14" Fill="#E5484D" VerticalAlignment="Center"/>
                <TextBlock Text="  🔴 Kotulesti     " Foreground="#C9CED6" FontSize="12" VerticalAlignment="Center" Margin="2,0,12,0"/>
                <Rectangle Width="14" Height="14" Fill="#6B7280" VerticalAlignment="Center"/>
                <TextBlock Text="  ⚪ Aynı (noise &lt; 2%)" Foreground="#C9CED6" FontSize="12" VerticalAlignment="Center" Margin="2,0,12,0"/>
            </StackPanel>
            <TextBlock Foreground="#8A919C" FontSize="11" FontStyle="Italic" Margin="0,2,0,0" TextWrapping="Wrap">
                <Run Text="↑ = değer arttı  ·  ↓ = değer azaldı  ·  Renk: iyileşme/kötüleşme yargısı (örnek: ↓ ping yeşil = düşüş iyi)."/>
            </TextBlock>
        </StackPanel>

        <Border Grid.Row="3" Background="#15181E" CornerRadius="5" BorderBrush="#232831" BorderThickness="1">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="6">
                <Canvas x:Name="chartCanvas" Background="Transparent" Width="$canvasW" Height="$canvasH"/>
            </ScrollViewer>
        </Border>

        <TextBlock Grid.Row="4" x:Name="lblCFoot" Foreground="#8A919C" FontSize="12" Margin="0,8,0,0" TextWrapping="Wrap"/>

        <StackPanel Grid.Row="5" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,6,0,0">
            <Button x:Name="btnCClose" Content="@@m_close@@" MinWidth="100" Height="30" Cursor="Hand"/>
        </StackPanel>
    </Grid>
</Window>
"@
    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlC))
        $winC = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winC
        if ($Owner) { $winC.Owner = $Owner } else { $winC.Owner = $Win }

        $winC.FindName('lblCA').Text = ("{0}   ·   {1}" -f $ALabel, $ATime)
        $winC.FindName('lblCB').Text = ("{0}   ·   {1}" -f $BLabel, $BTime)

        $canvas = $winC.FindName('chartCanvas')

        # Verdict renkleri (hex brush)
        $colorBetter  = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0x3F, 0xB9, 0x7A))
        $colorWorse   = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0xE5, 0x48, 0x4D))
        $colorNeutral = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0x6B, 0x72, 0x80))
        $colorNA      = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0x2C, 0x31, 0x3B))
        $colorAxis    = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0x23, 0x28, 0x31))
        $colorText    = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0xE6, 0xE8, 0xEB))
        $colorTextDim = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0xA9, 0xB0, 0xBB))

        # X axis baseline (bar baslangic noktasi)
        $axisX = $labelW + $pctW + 10
        $axisLine = New-Object System.Windows.Shapes.Rectangle
        $axisLine.Width = 1
        $axisLine.Height = ($chartRows.Count * $rowH)
        $axisLine.Fill = $colorAxis
        [System.Windows.Controls.Canvas]::SetLeft($axisLine, $axisX)
        [System.Windows.Controls.Canvas]::SetTop($axisLine, $marginTop)
        $canvas.Children.Add($axisLine) | Out-Null

        # Olcek etiketleri — 0%, %25, %50 vb. tepe ucu
        $scaleSteps = @(0, 0.25, 0.5, 0.75, 1.0)
        foreach ($s in $scaleSteps) {
            $tickX = $axisX + ($s * $maxPct * $pxPerPct)
            $tickTb = New-Object System.Windows.Controls.TextBlock
            $tickTb.Text = ("{0}%" -f [int]($s * $maxPct))
            $tickTb.Foreground = $colorTextDim
            $tickTb.FontSize = 9
            [System.Windows.Controls.Canvas]::SetLeft($tickTb, $tickX - 8)
            [System.Windows.Controls.Canvas]::SetTop($tickTb, ($marginTop + $chartRows.Count * $rowH))
            $canvas.Children.Add($tickTb) | Out-Null

            # Hafif dikey kilavuz cizgi
            if ($s -gt 0) {
                $guide = New-Object System.Windows.Shapes.Rectangle
                $guide.Width = 1; $guide.Height = ($chartRows.Count * $rowH)
                $guide.Fill = $colorAxis; $guide.Opacity = 0.45
                [System.Windows.Controls.Canvas]::SetLeft($guide, $tickX)
                [System.Windows.Controls.Canvas]::SetTop($guide, $marginTop)
                $canvas.Children.Add($guide) | Out-Null
            }
        }

        $y = $marginTop
        foreach ($r in $chartRows) {
            # Metrik adi (sol)
            $tbLabel = New-Object System.Windows.Controls.TextBlock
            $tbLabel.Text = $r.Label
            $tbLabel.Foreground = $colorText
            $tbLabel.FontSize = 12
            $tbLabel.Width = $labelW - 10
            $tbLabel.TextTrimming = 'CharacterEllipsis'
            $tbLabel.ToolTip = $r.Label
            [System.Windows.Controls.Canvas]::SetLeft($tbLabel, 4)
            [System.Windows.Controls.Canvas]::SetTop($tbLabel, $y + 3)
            $canvas.Children.Add($tbLabel) | Out-Null

            # Pct text (orta) — ok yonu raw delta'yi (arti/azalis) gosterir, renk yargi (iyi/kotu).
            # +/- sign kafa karistiriyordu: "lower=better" metrikte deger -%50 dustugunde gozle
            # eksi = kotu okunur ama bizim verdict = iyi. Ok + mutlak deger daha tutarli.
            $pctNum = [double]$r.PctChange
            $arrow  = if     ($pctNum -gt 0.05) { [char]0x2191 }   # ↑ arttı
                      elseif ($pctNum -lt -0.05) { [char]0x2193 }  # ↓ azaldı
                      else                       { [char]0x2022 }  # • degismez (sifir civari)
            $tbPct = New-Object System.Windows.Controls.TextBlock
            $tbPct.Text = ("{0} {1:F1}%" -f $arrow, [Math]::Abs($pctNum))
            $tbPct.Foreground = switch ($r.Verdict) {
                'better'  { $colorBetter }
                'worse'   { $colorWorse }
                default   { $colorTextDim }
            }
            $tbPct.FontSize = 12
            $tbPct.FontWeight = 'SemiBold'
            $tbPct.TextAlignment = 'Right'
            $tbPct.Width = $pctW
            [System.Windows.Controls.Canvas]::SetLeft($tbPct, $labelW - 5)
            [System.Windows.Controls.Canvas]::SetTop($tbPct, $y + 3)
            $canvas.Children.Add($tbPct) | Out-Null

            # Bar
            $absPct = [Math]::Min([Math]::Abs($pctNum), $maxPct)
            $barW   = $absPct * $pxPerPct
            if ($barW -lt 2) { $barW = 2 }   # cok kucuk degisimler bile ipucu olarak gorunsun
            $rect = New-Object System.Windows.Shapes.Rectangle
            $rect.Width  = $barW
            $rect.Height = $barH
            $rect.RadiusX = 2; $rect.RadiusY = 2
            $rect.Fill = switch ($r.Verdict) {
                'better'  { $colorBetter }
                'worse'   { $colorWorse }
                'neutral' { $colorNeutral }
                default   { $colorNA }
            }
            [System.Windows.Controls.Canvas]::SetLeft($rect, $axisX)
            [System.Windows.Controls.Canvas]::SetTop($rect, $y + 2)
            $canvas.Children.Add($rect) | Out-Null

            # A -> B raw deger (bar sonuna)
            $tbAB = New-Object System.Windows.Controls.TextBlock
            $tbAB.Text = ("{0} -> {1} {2}" -f $r.AValue, $r.BValue, $r.Unit)
            $tbAB.Foreground = $colorTextDim
            $tbAB.FontSize = 11
            [System.Windows.Controls.Canvas]::SetLeft($tbAB, $axisX + $barW + 8)
            [System.Windows.Controls.Canvas]::SetTop($tbAB, $y + 3)
            $canvas.Children.Add($tbAB) | Out-Null

            $y += $rowH
        }

        # Footer summary
        $wins  = @($chartRows | Where-Object { $_.Verdict -eq 'better'  }).Count
        $loss  = @($chartRows | Where-Object { $_.Verdict -eq 'worse'   }).Count
        $neut  = @($chartRows | Where-Object { $_.Verdict -eq 'neutral' }).Count
        $winC.FindName('lblCFoot').Text = ("{0} metrik gorulmektedir · 🟢 {1} · 🔴 {2} · ⚪ {3} · olceklendirme: max {4:F0}% bar = tepe" -f $chartRows.Count, $wins, $loss, $neut, $maxPct)

        $winC.FindName('btnCClose').Add_Click({ $winC.Close() })
        $winC.ShowDialog() | Out-Null
    } catch {
        WpfLog ("BenchChart Hata: " + $_.Exception.Message)
    }
}

# =========================================================
# Show-BenchMetricGuide (v1.2.10) — Hangi metrik hangi tweak'ten etkilenir?
# Statik referans tablo. Bench panel'den buton ile acilir, kullanici tweak Apply etmeden
# once veya bench diff sonrasi "X metrik degisti, hangi tweak yapmistim" yorumu icin.
# =========================================================
function Get-BenchMetricToTweakMap {
    return @(
        @{
            Metric    = "⏱️ Timer Sleep precision (avg + stddev)"
            Direction = "Düşük = İyi"
            Affects   = @(
                "Araclar > Timer Testi (Optimal ile Baslat)",
                "HPET (Platform Clock) Kapat",
                "MSI Mode (GPU Interrupt) Aç"
            )
            Note = "Win11 EcoQoS sleep'i throttle ediyorsa 5-7ms gorulur; tweak'lerle 0.5-1.5ms hedef."
        }
        # Loopback ping metrigi v1.2.10 sonunda bench'ten kaldirildi: 127.0.0.1 NIC uzerinden
        # GITMEZ (kernel TCP stack). NIC offload + TCP NoDelay tweak'leri loopback'i etkilemez.
        # Kullanicilar yanlislikla "iyilesme/kotulesme" yorumluyor. Tweak etki gozlemi icin
        # Gateway ping + DPC time daha dogru.
        @{
            Metric    = "🌐 Gateway ping (router) avg + jitter"
            Direction = "Düşük = İyi"
            Affects   = @(
                "Ağ Adaptörü Offload Profili (LSO Kapalı, RSS/Checksum Açık)",
                "RSC (Receive Segment Coalescing) Kapat",
                "Ağ Kartı Güç Tasarrufu ve Uyandırma Kapat (Tümü)"
            )
            Note = "Yerel ağ latency. Modern ev ağında 1-3ms tipik. Düşüş genelde marjinal (0.1-0.3ms)."
        }
        @{
            Metric    = "🔎 DNS resolve (10 domain avg)"
            Direction = "Düşük = İyi"
            Affects   = @(
                "DNS: Cloudflare (Gizlilik ve Hız)  — 1.1.1.1 / 1.0.0.1",
                "DNS: Google (Hız ve Kararlılık)    — 8.8.8.8 / 8.8.4.4",
                "DNS: Otomatik (Varsayılan / İSS)   — DHCP (Undo)"
            )
            Note = "ISP DNS yerine Cloudflare (1.1.1.1) veya Google (8.8.8.8) genelde 30-100ms düşürür. Cloudflare gizlilik odaklı (logging minimal), Google daha stabil global ağ. Üçü mutual exclusive (Group=DNS, birini seçince diğeri kapanır)."
        }
        @{
            Metric    = "🚀 Process start latency (cmd /c exit)"
            Direction = "Düşük = İyi"
            Affects   = @(
                "UAC Bildirimini Kapat (Never Notify)",
                "Arka Plan Uygulamalarını Kapat (Sistem Politikası)",
                "Microsoft GameInput Servisini El Ile Al",
                "Copilot Tamamen Kapat (Uninstall + Policy)",
                "Microsoft Update Health Tools Kaldır"
            )
            Note = "AntiVirus on-access scan (MsMpEng), UAC consent dialog overhead, process spawn yükü."
        }
        @{
            Metric    = "⚡ DPC time % (kernel deferred procedure)"
            Direction = "Düşük = İyi"
            Affects   = @(
                "Ağ Adaptörü Offload Profili (LSO Kapalı, RSS/Checksum Açık)",
                "MSI Mode (GPU Interrupt) Aç",
                "Ağ Kartı Güç Tasarrufu ve Uyandırma Kapat (Tümü)",
                "Araclar > Timer Testi",
                "HPET (Platform Clock) Kapat",
                "NVIDIA / AMD Optimizasyonu (manuel)"
            )
            Note = "Driver kalitesi göstergesi. Audio glitch, oyun stutter, frame time jitter sebebi. <1% iyi, >5% sorun."
        }
        @{
            Metric    = "💾 Boş RAM (MB)"
            Direction = "Yüksek = İyi"
            Affects   = @(
                "Arka Plan Uygulamalarını Kapat (Sistem Politikası)",
                "Windows Tanılama Verileri Kapat",
                "Bloatware kaldırma (Update Health)",
                "Copilot Tamamen Kapat",
                "Karanlık Mod (DWM marjinal)"
            )
            Note = "Tweak öncesi/sonrası 100-500MB fark görülebilir."
        }
        @{
            Metric    = "🔢 Process count"
            Direction = "Düşük = İyi"
            Affects   = @(
                "Bloatware kaldırma (Update Health / Meet Now)",
                "Copilot Tamamen Kapat (Uninstall + Policy)",
                "Arka Plan Uygulamalarını Kapat"
            )
            Note = "Tipik Win11: 180-220 process. Her bloatware kaldırma 2-5 process azaltır."
        }
        @{
            Metric    = "⚙️ Servis sayısı (Running)"
            Direction = "Düşük = İyi"
            Affects   = @(
                "Windows Tanılama Verileri Kapat (DiagTrack)",
                "Microsoft Update Health Tools Kaldır (uhssvc)",
                "Gereksiz Arka Plan Servislerini El ile Başlat (Güvenli Liste)"
            )
            Note = "Tipik Win11: 100-130 running service. Telemetri kapatma ~3-5 servis azaltır."
        }
        # v1.3.0 (13. tur): olcum oturumunda dogrulanan oyun / gecikme metrikleri (MrClean olcumu, Ryzen 7 9850X3D + RTX 3080)
        @{
            Metric    = "🎮 Oyun yükü 1% low (CS2 / BF6 benzeri)"
            Direction = "Yüksek = İyi"
            Affects   = @(
                "İşlemci Minimum Durumu %100 — Yalnız Oyun Açıkken (Prizde)",
                "Nihai Performans Güç Planını Aktif Et",
                "Bellek Bütünlüğü (HVCI / Çekirdek Yalıtımı) Kapat - Oyun FPS",
                "CPU Core Parking Devre Dışı (Tüm Çekirdekler Aktif)"
            )
            Note = "Ölçüm: işlemci min %100 ile CS2 benzeri 1% low +%14, BF6 benzeri +%11; Dengeli plan −%7. SysMain açık/kapalı fark yok."
        }
        @{
            Metric    = "🖱️ Giriş gecikmesi (yazılım yolu, p99)"
            Direction = "Düşük = İyi"
            Affects   = @(
                "İşlemci Minimum Durumu %100 — Yalnız Oyun Açıkken (Prizde)",
                "Nihai Performans Güç Planını Aktif Et",
                "Gereksiz Arka Plan Servislerini El ile Başlat (Güvenli Liste)"
            )
            Note = "SendInput → ham giriş mesajı süresi, oyun yükü altında. Fare / USB donanım gecikmesini içermez. Ölçüm: min %100 ile p99 248 → 126 µs."
        }
        @{
            Metric    = "⏰ Uyanma gecikmesi / ani yük tepkisi"
            Direction = "Düşük = İyi"
            Affects   = @(
                "İşlemci Minimum Durumu %100 — Yalnız Oyun Açıkken (Prizde)",
                "PCIe Bağlantı Güç Tasarrufunu Kapat (ASPM, Prizde)",
                "Araclar > Timer Testi (Optimal ile Baslat)"
            )
            Note = "Boşta bekleyen çekirdeğin uyanıp iş bitirme süresi. Ölçüm: min %100 ile ani yük 200 → 115 µs."
        }
        @{
            Metric    = "🧱 Çekirdek çağrısı / sayfa hatası maliyeti"
            Direction = "Düşük = İyi"
            Affects   = @(
                "Bellek Bütünlüğü (HVCI / Çekirdek Yalıtımı) Kapat - Oyun FPS"
            )
            Note = "HVCI açıkken çekirdek geçişleri ve bellek sayfa işlemleri pahalanır. HVCI kapatmadan önce / sonra bench alıp bu satıra bakın."
        }
        @{
            Metric    = "🖥️ GPU FPS / ekrana ulaşma gecikmesi (GPU testi)"
            Direction = "FPS yüksek, gecikme düşük = İyi"
            Affects   = @(
                "NVIDIA Optimizasyonu (Inspector profili)",
                "Pencereli Oyunlar İçin Optimizasyon (Flip Model)",
                "Hardware Accelerated GPU Scheduling Aç (HAGS)"
            )
            Note = "Ölçüm: aynı yük tam ekranda (Legacy Flip) 187 FPS / 16 ms, pencerelide (bileşik) 171 FPS / 19.5 ms. NVIDIA güç modu (Maks. performans / varsayılan) fark yaratmadı."
        }
        @{
            Metric    = "📎 Handle count (toplam)"
            Direction = "Düşük = İyi"
            Affects   = @(
                "Arka Plan Uygulamalarını Kapat",
                "Bloatware + Copilot kaldırma",
                "Karanlık Mod (DWM marjinal)"
            )
            Note = "Tipik sistem: 80k-150k handle. Background app'leri kapatma 10-30k azaltır."
        }
    )
}

function Show-BenchMetricGuide {
    $xamlG = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="📋 Bench Metrik Rehberi — Hangi tweak neyi etkiler?" Height="700" Width="880"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="CanResize" MinWidth="700" MinHeight="500">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid Margin="14">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <TextBlock Grid.Row="0" Text="📋 Metrik Rehberi" Foreground="#E6E8EB" FontSize="20" FontWeight="Bold" Margin="0,0,0,4"/>
        <TextBlock Grid.Row="1" Foreground="#8A919C" FontSize="12" Margin="0,0,0,10" TextWrapping="Wrap">
            <Run Text="Bench yapan tweak'in hangi metriğe etki etmesi BEKLENİR. Bench öncesi/sonrası diff'e bakarken yorumu kolaylaştırır."/><LineBreak/>
            <Run Text="ÖNEMLİ: Bir metrik beklenmedik şekilde değişmezse, tweak'in o sistem üzerinde gerçekten çalışmadığını (TR Windows lokalization, driver uyumsuzluğu, vb.) gösterebilir." Foreground="#E0A23B" FontStyle="Italic"/>
        </TextBlock>

        <Border Grid.Row="2" Background="#15181E" CornerRadius="5" BorderBrush="#232831" BorderThickness="1">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="6">
                <StackPanel x:Name="spGuide"/>
            </ScrollViewer>
        </Border>

        <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,8,0,0">
            <Button x:Name="btnGClose" Content="@@m_close@@" MinWidth="100" Height="32" Cursor="Hand"/>
        </StackPanel>
    </Grid>
</Window>
"@
    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlG))
        $winG = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winG
        $winG.Owner = $Win

        $sp = $winG.FindName('spGuide')
        foreach ($entry in (Get-BenchMetricToTweakMap)) {
            # Her metrik bir card
            $border = New-Object System.Windows.Controls.Border
            $border.Background  = '#252525'
            $border.CornerRadius = '4'
            $border.BorderBrush = '#333'
            $border.BorderThickness = 1
            $border.Padding = '12,10'
            $border.Margin = '0,0,0,8'

            $stack = New-Object System.Windows.Controls.StackPanel

            # Baslik + direction
            $titleRow = New-Object System.Windows.Controls.DockPanel
            $tbTitle = New-Object System.Windows.Controls.TextBlock
            $tbTitle.Text = $entry.Metric
            $tbTitle.Foreground = '#FFFFFF'
            $tbTitle.FontSize = 14
            $tbTitle.FontWeight = 'Bold'
            $stack.Children.Add($tbTitle) | Out-Null

            $tbDir = New-Object System.Windows.Controls.TextBlock
            $tbDir.Text = ("Yön: {0}" -f $entry.Direction)
            $tbDir.Foreground = '#4CC2FF'
            $tbDir.FontSize = 11
            $tbDir.Margin = '0,2,0,8'
            $stack.Children.Add($tbDir) | Out-Null

            # Affects list
            $tbLab = New-Object System.Windows.Controls.TextBlock
            $tbLab.Text = "Bu metriği etkileyen tweak'ler:"
            $tbLab.Foreground = '#CCC'
            $tbLab.FontSize = 11
            $tbLab.Margin = '0,2,0,4'
            $stack.Children.Add($tbLab) | Out-Null

            foreach ($t in $entry.Affects) {
                $tbItem = New-Object System.Windows.Controls.TextBlock
                $tbItem.Text = "  • $t"
                $tbItem.Foreground = '#E8E8E8'
                $tbItem.FontSize = 12
                $tbItem.Margin = '12,1,0,1'
                $stack.Children.Add($tbItem) | Out-Null
            }

            # Note
            if ($entry.Note) {
                $tbN = New-Object System.Windows.Controls.TextBlock
                $tbN.Text = "💡 " + $entry.Note
                $tbN.Foreground = '#888'
                $tbN.FontSize = 11
                $tbN.FontStyle = 'Italic'
                $tbN.TextWrapping = 'Wrap'
                $tbN.Margin = '0,8,0,0'
                $stack.Children.Add($tbN) | Out-Null
            }

            $border.Child = $stack
            $sp.Children.Add($border) | Out-Null
        }

        $winG.FindName('btnGClose').Add_Click({ $winG.Close() })
        $winG.ShowDialog() | Out-Null
    } catch {
        WpfLog ("BenchGuide Hata: " + $_.Exception.Message)
    }
}

function Show-BenchmarkPanel {
    $xamlB = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="⚖️ Performans Benchmark" Height="680" Width="1280"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="CanResize" MinWidth="820" MinHeight="560">
    <Window.Resources>
$($global:SubTheme)
        <Style x:Key="BBtn" TargetType="Button" BasedOn="{StaticResource SwBtn}"/>
    </Window.Resources>
    <Grid Margin="14">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <TextBlock Grid.Row="0" Text="⚖️ Performans Benchmark" Foreground="#E6E8EB" FontSize="20" FontWeight="Bold" Margin="0,0,0,4"/>
        <TextBlock Grid.Row="1" Foreground="#8A919C" FontSize="12" Margin="0,0,0,10" TextWrapping="Wrap">
            <Run Text="Sistem + oyun yuku olcumu: FPS / 1% low (CS2 ve BF6 benzeri yuk), takilma, giris gecikmesi, sistem uyanma gecikmesi, DPC. Tweak oncesi / sonrasi snapshot al, karsilastir — gercek etki gor."/><LineBreak/>
            <Run Text="Multi-run median: 3 run onerilir — tek run guvenilir degil (tipik %3-7 gurultu). Noise esigi %5. Olcum sirasinda bilgisayari kullanmayin; oyun yuku testinde kucuk bir pencere acilir ve imlec 1 piksel oynar." Foreground="#6B7280" FontStyle="Italic"/>
        </TextBlock>

        <!-- BENCH BUTONLARI + ETIKET + RUN MODU INPUT -->
        <Grid Grid.Row="2" Margin="0,0,0,10">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="12"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <TextBlock Grid.Column="0" Text="Etiket:" Foreground="#C9CED6" VerticalAlignment="Center" Margin="0,0,8,0"/>
            <TextBox x:Name="txtBLabel" Grid.Column="1" Width="220" MinHeight="32" Background="#15181E" Foreground="#E6E8EB" BorderBrush="#232831" Padding="6,2" VerticalContentAlignment="Center" Text=""/>
            <TextBlock Grid.Column="3" Text="Run modu:" Foreground="#C9CED6" VerticalAlignment="Center" Margin="0,0,8,0"/>
            <ComboBox x:Name="cbBRunMode" Grid.Column="4" MinWidth="230" MinHeight="32" VerticalContentAlignment="Center" ToolTip="Bench kaç kez tekrar edilecek (medyan alınır). Daha çok run = daha güvenilir ama daha uzun.">
                <ComboBoxItem Content="1 run (hızlı ~1.5 dk)"/>
                <ComboBoxItem Content="3 run (önerilen ~4 dk)" IsSelected="True"/>
                <ComboBoxItem Content="5 run (detaylı ~7 dk)"/>
            </ComboBox>
            <CheckBox x:Name="chkBGpu" Grid.Column="5" Content="🎮 GPU testi" Foreground="#C9CED6" VerticalAlignment="Center" HorizontalAlignment="Right" Margin="0,0,12,0" ToolTip="FurMark 2 (Geeks3D) + PresentMon (Intel) ile tam ekran GPU kare süresi, 1% low ve ekrana ulaşma gecikmesi. İlk kullanımda resmi kaynaklardan ~36 MB indirilir (SHA-256 doğrulamalı). Her run'da ekran ~40 sn tam ekran test görüntüsüne geçer; GPU tam güç çeker."/>
            <Button x:Name="btnRunBench" Grid.Column="6" Style="{StaticResource SwBtnPrimary}" Content="📊 Tam Bench Calistir" MinWidth="200" Height="32" FontWeight="Bold"/>
        </Grid>

        <!-- PROGRESS BAR + STATUS -->
        <Grid Grid.Row="3" Margin="0,0,0,12">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <ProgressBar Grid.Row="0" x:Name="pbBench" Height="14" Background="#15181E" Foreground="#8CB4FF" BorderBrush="#232831" Minimum="0" Maximum="100" Value="0"/>
            <TextBlock Grid.Row="1" x:Name="lblBStat" Foreground="#8A919C" FontSize="12" Margin="0,4,0,0" Text="Hazir"/>
        </Grid>

        <!-- SNAPSHOT LISTESI -->
        <Border Grid.Row="4" Background="#15181E" CornerRadius="5" BorderBrush="#232831" BorderThickness="1">
            <ListView x:Name="lvBench" Background="Transparent" BorderThickness="0" Foreground="#E6E8EB" SelectionMode="Extended">
                <ListView.View>
                    <GridView>
                        <GridView.ColumnHeaderContainerStyle>
                            <Style TargetType="GridViewColumnHeader" BasedOn="{StaticResource SwGridHeader}"/>
                        </GridView.ColumnHeaderContainerStyle>
                        <GridViewColumn Header="Tarih"     Width="160" DisplayMemberBinding="{Binding timestamp}"/>
                        <GridViewColumn Header="Etiket"    Width="240" DisplayMemberBinding="{Binding label}"/>
                        <GridViewColumn Header="Timer Avg" Width="90"  DisplayMemberBinding="{Binding _timer}"/>
                        <GridViewColumn Header="GW Ping"   Width="90"  DisplayMemberBinding="{Binding _gw}"/>
                        <GridViewColumn Header="Proc Start" Width="100" DisplayMemberBinding="{Binding _proc}"/>
                        <GridViewColumn Header="DPC %"     Width="80"  DisplayMemberBinding="{Binding _dpc}"/>
                        <GridViewColumn Header="Bos RAM"   Width="100" DisplayMemberBinding="{Binding _ram}"/>
                        <GridViewColumn Header="CS2 1%low" Width="90"  DisplayMemberBinding="{Binding _c2l}"/>
                        <GridViewColumn Header="BF6 1%low" Width="90"  DisplayMemberBinding="{Binding _b6l}"/>
                        <GridViewColumn Header="Giriş p99" Width="90"  DisplayMemberBinding="{Binding _inp}"/>
                        <GridViewColumn Header="GPU FPS"   Width="80"  DisplayMemberBinding="{Binding _gpu}"/>
                    </GridView>
                </ListView.View>
                <ListView.ItemContainerStyle>
                    <Style TargetType="ListViewItem" BasedOn="{StaticResource SwListRow}">   <!-- v1.3.0 (§85) -->
                        <Setter Property="Padding" Value="2,3"/>
                    </Style>
                </ListView.ItemContainerStyle>
            </ListView>
        </Border>

        <TextBlock Grid.Row="5" x:Name="txtBSummary" Foreground="#8A919C" FontSize="12" Margin="0,8,0,0"/>

        <Grid Grid.Row="6" Margin="0,8,0,0">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <Button x:Name="btnCompare" Grid.Column="0" Style="{StaticResource SwBtnPrimary}" Content="🔄 Karsilastir (2 sec)" MinWidth="180" Height="32" IsEnabled="False"/>
            <Button x:Name="btnRelabel" Grid.Column="2" Style="{StaticResource BBtn}" Content="✏️ Etiket Degistir" MinWidth="150" Height="32" IsEnabled="False"/>
            <Button x:Name="btnDelBench" Grid.Column="4" Style="{StaticResource SwBtnDanger}" Content="🗑️ Sil" MinWidth="80" Height="32" IsEnabled="False"/>
            <Button x:Name="btnGuide" Grid.Column="6" Style="{StaticResource SwBtnPrimary}" Content="📋 Metrik Rehberi" MinWidth="160" Height="32" ToolTip="Hangi tweak hangi metriği etkilemesi beklenir — referans tablo"/>
            <Button x:Name="btnDnsBenchOpen" Grid.Column="8" Style="{StaticResource SwBtnPrimary}" Content="🔎 DNS Benchmark" MinWidth="160" Height="32" ToolTip="5 popüler DNS server hız karşılaştırması — en hızlısını Apply et"/>
            <Button x:Name="btnBRefresh" Grid.Column="10" Style="{StaticResource BBtn}" Content="@@btn_refresh@@" MinWidth="100" Height="32"/>
            <Button x:Name="btnBClose" Grid.Column="12" Style="{StaticResource BBtn}" Content="@@m_close@@" MinWidth="100" Height="32"/>
        </Grid>
    </Grid>
</Window>
"@
    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlB))
        $winB   = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winB
        $winB.Owner = $Win

        $txtLabel    = $winB.FindName('txtBLabel')
        $cbRunMode   = $winB.FindName('cbBRunMode')
        $btnRun      = $winB.FindName('btnRunBench')
        $chkGpu      = $winB.FindName('chkBGpu')
        $pb          = $winB.FindName('pbBench')
        $lblStat     = $winB.FindName('lblBStat')
        $lv          = $winB.FindName('lvBench')
        $txtSummary  = $winB.FindName('txtBSummary')
        $btnCmp      = $winB.FindName('btnCompare')
        $btnRelabel  = $winB.FindName('btnRelabel')
        $btnDel      = $winB.FindName('btnDelBench')
        $btnGuide    = $winB.FindName('btnGuide')
        $btnDnsOpen  = $winB.FindName('btnDnsBenchOpen')
        $btnRefresh  = $winB.FindName('btnBRefresh')
        $btnClose    = $winB.FindName('btnBClose')

        function Refresh-BenchList {
            $lv.Items.Clear()
            $snaps = Get-BenchSnapshots
            if (-not $snaps -or $snaps.Count -eq 0) {
                $txtSummary.Text = "Henuz benchmark snapshot yok. 'Tam Bench Calistir' ile ilk olcumu al."
                return
            }
            foreach ($s in $snaps) {
                # Ozet sutunlar icin (display-only). disk4k v1.2.10 sonu kaldirildi,
                # yerini Process Start aldi (UAC/AntiVirus/process spawn tweak'lerine duyarli).
                $tAvg  = try { [Math]::Round([double]$s.metrics.timer.AvgMs, 3) } catch { "-" }
                $gAvg  = try { [Math]::Round([double]$s.metrics.gateway.AvgMs, 2) } catch { "-" }
                $proc  = try { [Math]::Round([double]$s.metrics.processStart.AvgMs, 1) } catch { "-" }
                $dpc   = try { [Math]::Round([double]$s.metrics.dpc.AvgPercent, 2) } catch { "-" }
                $ram   = try { [int]$s.metrics.system.AvailableRamMB } catch { "-" }
                $s | Add-Member -NotePropertyName "_timer" -NotePropertyValue ("$tAvg ms") -Force
                $s | Add-Member -NotePropertyName "_gw"    -NotePropertyValue ("$gAvg ms") -Force
                $s | Add-Member -NotePropertyName "_proc"  -NotePropertyValue ("$proc ms") -Force
                $s | Add-Member -NotePropertyName "_dpc"   -NotePropertyValue ("$dpc %")   -Force
                $s | Add-Member -NotePropertyName "_ram"   -NotePropertyValue ("$ram MB")  -Force
                $c2l = try { if ($s.metrics.gameLoad.Ok) { "{0:N0}" -f [double]$s.metrics.gameLoad.Cs2Low1 } else { "-" } } catch { "-" }
                $b6l = try { if ($s.metrics.gameLoad.Ok) { "{0:N0}" -f [double]$s.metrics.gameLoad.Bf6Low1 } else { "-" } } catch { "-" }
                $inp = try { if ($s.metrics.gameLoad.Ok) { "{0:N0} µs" -f [double]$s.metrics.gameLoad.InputP99Us } else { "-" } } catch { "-" }
                $gpu = try { if ($s.metrics.frameTime.Ok) { "{0:N0}" -f [double]$s.metrics.frameTime.GpuFps } else { "-" } } catch { "-" }
                $s | Add-Member -NotePropertyName "_c2l" -NotePropertyValue $c2l -Force
                $s | Add-Member -NotePropertyName "_b6l" -NotePropertyValue $b6l -Force
                $s | Add-Member -NotePropertyName "_inp" -NotePropertyValue $inp -Force
                $s | Add-Member -NotePropertyName "_gpu" -NotePropertyValue $gpu -Force
                $lv.Items.Add($s) | Out-Null
            }
            $txtSummary.Text = "$($snaps.Count) snapshot · 2 secip 'Karsilastir' = diff modal"
        }
        Refresh-BenchList

        $lv.Add_SelectionChanged({
            $cnt = $lv.SelectedItems.Count
            $btnCmp.IsEnabled = ($cnt -eq 2)
            $btnRelabel.IsEnabled = ($cnt -eq 1)
            $btnDel.IsEnabled = ($cnt -ge 1)
            if ($cnt -eq 2)     { $btnCmp.Content = "🔄 Karsilastir (2 sec)" }
            elseif ($cnt -gt 2) { $btnCmp.Content = "🔄 Karsilastir (cok fazla sec)" }
            else                { $btnCmp.Content = ("🔄 Karsilastir ($cnt/2 sec)") }
        })

        $btnRun.Add_Click({
            $btnRun.IsEnabled = $false
            $btnRefresh.IsEnabled = $false
            $lv.IsEnabled = $false
            $pb.Value = 0
            $lblStat.Text = "Baslatiliyor..."
            Do-Events

            $label = $txtLabel.Text.Trim()
            if ([string]::IsNullOrEmpty($label)) { $label = "Manuel " + (Get-Date -Format "HH:mm:ss") }

            # Run modu dropdown -> Runs param
            $runs = switch ($cbRunMode.SelectedIndex) {
                0 { 1 }
                1 { 3 }
                2 { 5 }
                default { 3 }
            }

            # v1.3.0 (13. tur): istege bagli GPU testi — araclar yoksa onay alinip resmi kaynaktan indirilir (SHA-256 / imza dogrulamali)
            $global:BenchGpuEnabled = [bool]$chkGpu.IsChecked
            if ($global:BenchGpuEnabled -and -not (Get-MrCleanBenchGpuTools)) {
                $q = [System.Windows.MessageBox]::Show("GPU testi için iki araç indirilecek (~36 MB, bir kez):`n`n  • PresentMon 2.6 — Intel, github.com/GameTechDev (Intel imzası doğrulanır)`n  • FurMark 2.10 — Geeks3D, resmi indirme sunucusu (SHA-256 doğrulanır)`n`nİndirilsin mi? (Hayır: GPU testi atlanır, diğer ölçümler yapılır.)", "GPU Testi", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
                if ($q -eq 'Yes') { $lblStat.Text = "GPU araçları indiriliyor..."; Do-Events; if (-not (Get-MrCleanBenchGpuTools -Download)) { $global:BenchGpuEnabled = $false; $lblStat.Text = "GPU araçları indirilemedi — GPU testi atlanıyor" } }
                else { $global:BenchGpuEnabled = $false }
            }

            $progressCb = {
                param($step, $total, $stepLabel)
                $pb.Value = if ($total -gt 0) { ($step / $total) * 100 } else { 0 }
                $lblStat.Text = ("[{0}/{1}] {2}" -f $step, $total, $stepLabel)
                Do-Events
            }

            try {
                $snap = Get-BenchSnapshot -ProgressCallback $progressCb -Label $label -Runs $runs
                $fp = Save-BenchSnapshot -Snapshot $snap
                if ($fp) {
                    $lblStat.Text = "Snapshot kaydedildi: " + (Split-Path $fp -Leaf)
                    $txtLabel.Text = ""
                    Refresh-BenchList
                } else {
                    $lblStat.Text = "HATA: snapshot kaydedilemedi (log'a bak)"
                }
            } catch {
                $lblStat.Text = "HATA: " + $_.Exception.Message
            } finally {
                $pb.Value = 100
                $btnRun.IsEnabled = $true
                $btnRefresh.IsEnabled = $true
                $lv.IsEnabled = $true
            }
        })

        $btnCmp.Add_Click({
            if ($lv.SelectedItems.Count -ne 2) { return }
            # En eski = A, en yeni = B (timestamp'a gore)
            $two = @($lv.SelectedItems) | Sort-Object { [datetime]$_.timestamp }
            $a = $two[0]; $b = $two[1]
            Show-BenchDiffModal -SnapA $a -SnapB $b
        })

        $btnRelabel.Add_Click({
            if ($lv.SelectedItems.Count -ne 1) { return }
            $sel = $lv.SelectedItem
            Add-Type -AssemblyName Microsoft.VisualBasic
            $newLbl = [Microsoft.VisualBasic.Interaction]::InputBox(
                "Yeni etiket (snapshot icin):",
                "Etiket Degistir",
                [string]$sel.label)
            if ($null -eq $newLbl) { return }
            if ([string]::IsNullOrWhiteSpace($newLbl)) { return }
            $ok = Set-BenchSnapshotLabel -Path $sel._path -NewLabel $newLbl
            if ($ok) {
                Refresh-BenchList
            } else {
                [System.Windows.MessageBox]::Show("Etiket degistirilemedi.", "Hata", "OK", "Error") | Out-Null
            }
        })

        $btnDel.Add_Click({
            $sels = @($lv.SelectedItems)
            if ($sels.Count -eq 0) { return }
            $confirm = [System.Windows.MessageBox]::Show(
                ("$($sels.Count) snapshot silinecek. Devam edilsin mi?"),
                "Sil Onayi", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
            if ($confirm -ne 'Yes') { return }
            $ok = 0; $fail = 0
            foreach ($s in $sels) {
                if (Remove-BenchSnapshot -Path $s._path) { $ok++ } else { $fail++ }
            }
            Refresh-BenchList
            $lblStat.Text = "$ok silindi, $fail hata"
        })

        $btnGuide.Add_Click({ Show-BenchMetricGuide })
        $btnDnsOpen.Add_Click({ Show-DnsBenchmark })
        $btnRefresh.Add_Click({ Refresh-BenchList })
        $btnClose.Add_Click({ $winB.Close() })

        $winB.ShowDialog() | Out-Null
    } catch {
        WpfLog ("Benchmark Hata: " + $_.Exception.Message)
        [System.Windows.MessageBox]::Show(
            ("Benchmark panel acilamadi: {0}" -f $_.Exception.Message),
            "Hata", "OK", "Error") | Out-Null
    }
}

# =========================================================
# Show-ActivityLog (v1.2.10) — Apply / Undo gecmisi paneli
# Snapshot yerine eklendi. tweak_history.log (Write-TweakAuditLog) icerigini parse eder,
# son N kaydi listeler, secimle veya per-row buton ile tek/coklu geri alma sunar.
# =========================================================

# $global:TweakList yapisi: [ordered]@{ "Kategori Adi" = @(tweakHash1, tweakHash2, ...); ... }
# Yani anahtar KATEGORI, deger ise tweak array. Tweak adi anahtar DEGIL — bu yuzden
# .Contains($tweakName) calismaz. Tum kategoriler iterate edilip Name esitligi aranmali.
function Find-TweakByName {
    param([string]$Name)
    if (-not $global:TweakList -or [string]::IsNullOrEmpty($Name)) { return $null }
    foreach ($cat in $global:TweakList.Keys) {
        $arr = $global:TweakList[$cat]
        if (-not $arr) { continue }
        foreach ($tw in $arr) {
            if (-not $tw) { continue }
            if ($tw.Name -eq $Name) { return $tw }
            if ($tw.Aliases -and @($tw.Aliases) -contains $Name) { return $tw }
        }
    }
    return $null
}

# tweak_history.log parser. Her tweak adi icin bir entry uretir (Apply ve Undo bucket ayri).
# Find-TweakByName ile Risk + Command/UndoCommand bilgisini iliskilendirir.
function Get-ActivityLogEntries {
    param([int]$Limit = 100)
    $logPath = Join-Path $LogsDir "tweak_history.log"
    if (-not (Test-Path $logPath)) { return @() }

    $entries  = New-Object System.Collections.Generic.List[object]
    $lines    = Get-Content $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
    if (-not $lines) { return @() }

    $curTime   = $null
    $curBucket = $null
    foreach ($line in $lines) {
        if ($line -match '^=== \[(.+?)\] (.+?) ===$') {
            try {
                $curTime = [DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture)
            } catch { $curTime = $null }
            $curBucket = $null
            continue
        }
        if ($line -match '^UYGULANAN') { $curBucket = 'Apply'; continue }
        if ($line -match '^GERI ALINAN') { $curBucket = 'Undo';  continue }
        if (-not $curTime -or -not $curBucket) { continue }
        # "  + Tweak Adi" veya "  - Tweak Adi"
        if ($line -match '^\s*[\+\-]\s+(.+?)\s*$') {
            $tweakName = $Matches[1].Trim()
            if ([string]::IsNullOrEmpty($tweakName)) { continue }

            # Tweak metadata lookup — kategori-iterating Find-TweakByName ile
            $risk     = '?'
            $hasFix   = $false
            $tw       = Find-TweakByName $tweakName
            if ($tw) {
                if ($tw.Risk) { $risk = [string]$tw.Risk }
                # Geri alabilir mi: Apply ise UndoCommand/Undo, Undo ise Command/Data var mi
                if ($curBucket -eq 'Apply') {
                    $hasFix = ($tw.UndoCommand -or $tw.Undo -or ($tw.Batch -and $tw.Batch.Count -gt 0))
                } else {
                    $hasFix = ($tw.Command -or $tw.Data -or ($tw.Batch -and $tw.Batch.Count -gt 0))
                }
            }

            $riskIcon = switch ($risk) {
                'High'    { '🔴 Yüksek' }
                'Medium'  { '🟡 Orta' }
                'Low'     { '🟢 Düşük' }
                default   { '⚪ —' }
            }
            $actionIcon = if ($curBucket -eq 'Apply') { '✅ Apply' } else { '↶ Undo' }

            $entries.Add([PSCustomObject]@{
                DateTime    = $curTime
                DateStr     = $curTime.ToString('yyyy-MM-dd')
                TimeStr     = $curTime.ToString('HH:mm:ss')
                Action      = $curBucket          # 'Apply' veya 'Undo'
                ActionIcon  = $actionIcon
                TweakName   = $tweakName
                Risk        = $risk
                RiskIcon    = $riskIcon
                CanReverse  = $hasFix
            }) | Out-Null
        }
    }

    # En yeni en ustte — son $Limit kayit
    @($entries | Sort-Object DateTime -Descending | Select-Object -First $Limit)
}

# Tek entry icin reverse — Apply ise Undo komutu, Undo ise Apply komutu uygulanir.
# Invoke-QuickUndo icindeki Invoke-TweakAction pattern'i ile birebir mantik.
function Invoke-SingleActivityReverse {
    param([Parameter(Mandatory=$true)]$Entry)

    $tw = Find-TweakByName $Entry.TweakName
    if (-not $tw) {
        return @{ Ok = $false; Reason = "Tweak tanimi bulunamadi (silinmis veya yeniden adlandirilmis): $($Entry.TweakName)" }
    }
    $isUndo  = ($Entry.Action -eq 'Apply')   # Apply yapilmissa Undo et, Undo yapilmissa yeniden Apply et
    $batch   = if ($tw.Batch) { $tw.Batch } else { @($tw) }

    try {
        foreach ($sub in $batch) {
            if ($isUndo -and $sub.UndoCommand) {
                Invoke-TweakCommand $sub.UndoCommand
            } elseif (-not $isUndo -and $sub.Command) {
                Invoke-TweakCommand $sub.Command
            } elseif ($sub.Key) {
                $targetValue = if ($isUndo) { $sub.Undo } else { $sub.Data }
                if ($targetValue -eq "DELETE_KEY") {
                    if ($sub.ValueName) {
                        if (Test-Path $sub.Key) { Remove-ItemProperty -Path $sub.Key -Name $sub.ValueName -ErrorAction SilentlyContinue }
                    } else {
                        if (Test-Path $sub.Key) { Remove-Item -Path $sub.Key -Force -Recurse -ErrorAction SilentlyContinue }
                    }
                } elseif ($targetValue -eq "DELETE_VALUE") {
                    if (Test-Path $sub.Key) { Remove-ItemProperty -Path $sub.Key -Name $sub.ValueName -ErrorAction SilentlyContinue }
                } else {
                    if (-not (Test-Path $sub.Key)) {
                        try { New-Item -Path $sub.Key -Force -ErrorAction Stop | Out-Null } catch { continue }
                    }
                    if ([string]::IsNullOrEmpty($sub.ValueName)) {
                        Set-Item -Path $sub.Key -Value $targetValue -Force -ErrorAction Stop
                    } else {
                        Set-ItemProperty -Path $sub.Key -Name $sub.ValueName -Value $targetValue -Type $sub.Type -Force -ErrorAction Stop
                    }
                }
            }
        }
        return @{ Ok = $true; Reason = "" }
    } catch {
        return @{ Ok = $false; Reason = $_.Exception.Message }
    }
}

# =========================================================
# SISTEM & GUVENLIK DETAY (v1.2.24)
# Genel Bakis kartindaki "Detay" butonu acar. Lazy-load: pencere acilinca async runspace tum
# veriyi ceker (Defender/BitLocker yavas olabilir, UI donmasin). Sonuc kopyalanabilir TextBox'ta.
# Donanim DEGIL (o Show-HardwareDetail'de) — guvenlik + sistem kimligi + bakim odakli.
# =========================================================
function Show-SystemSecurityDetail {
    try {
        $xamlSS = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="@@ss_title@@" Height="640" Width="720"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="CanResize" MinWidth="560" MinHeight="460">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid Margin="16">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        <TextBlock Grid.Row="0" Text="@@ss_title@@" Style="{StaticResource SwTitle}" Margin="0,0,0,12"/>
        <Border Grid.Row="1" Background="#15181E" CornerRadius="10" BorderBrush="#232831" BorderThickness="1">
            <TextBox x:Name="txtSSBody" Background="Transparent" Foreground="#C9CED6" BorderThickness="0"
                     FontFamily="Cascadia Mono, Consolas" FontSize="14" Padding="12" IsReadOnly="True"
                     TextWrapping="Wrap" VerticalScrollBarVisibility="Auto"
                     VerticalContentAlignment="Top" Text="@@hw_collecting@@"/>
        </Border>
        <StackPanel Grid.Row="2" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,10,0,0">
            <Button x:Name="btnSSCopy" Content="@@copy_all@@" MinWidth="160" Height="34" Margin="0,0,8,0" Style="{StaticResource SwBtnPrimary}"/>
            <Button x:Name="btnSSClose" Content="@@m_close@@" MinWidth="100" Height="34"/>
        </StackPanel>
    </Grid>
</Window>
"@
        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlSS))
        $winSS = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winSS
        try { $winSS.Owner = $Win } catch {}
        $txtSSBody  = $winSS.FindName('txtSSBody')
        $btnSSCopy  = $winSS.FindName('btnSSCopy')
        $btnSSClose = $winSS.FindName('btnSSClose')

        $btnSSCopy.Add_Click({ try { [System.Windows.Clipboard]::SetText($txtSSBody.Text) } catch {} })
        $btnSSClose.Add_Click({ $winSS.Close() })

        # Veri toplama scriptblock'u (async runspace — Defender/BitLocker yavas olabilir)
        $collectScript = {
            $sb = New-Object System.Text.StringBuilder
            $add = { param($line) [void]$sb.AppendLine($line) }

            # ===== GENEL =====
            [void]$sb.AppendLine("=== SISTEM OZETI ===")
            try {
                $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
                $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
                $reg = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion"
                $dv  = (Get-ItemProperty $reg -Name DisplayVersion -ErrorAction SilentlyContinue).DisplayVersion
                $bn  = (Get-ItemProperty $reg -Name CurrentBuildNumber -ErrorAction SilentlyContinue).CurrentBuildNumber
                $ubr = (Get-ItemProperty $reg -Name UBR -ErrorAction SilentlyContinue).UBR
                [void]$sb.AppendLine("Isletim Sistemi : $($os.Caption)")
                [void]$sb.AppendLine("Surum / Build   : $dv  (Build $bn.$ubr)")
                $instDate = $os.InstallDate
                if ($instDate) {
                    $age = [Math]::Round(((Get-Date) - $instDate).TotalDays)
                    [void]$sb.AppendLine("Kurulum Tarihi  : $($instDate.ToString('dd.MM.yyyy'))  ($age gun once)")
                }
                $boot = $os.LastBootUpTime
                if ($boot) {
                    $up = (Get-Date) - $boot
                    [void]$sb.AppendLine("Calisma Suresi  : $($up.Days) gun $($up.Hours) saat $($up.Minutes) dk  (acilis: $($boot.ToString('dd.MM.yyyy HH:mm')))")
                }
            } catch {}

            # ===== SISTEM KIMLIGI =====
            [void]$sb.AppendLine("")
            [void]$sb.AppendLine("=== SISTEM KIMLIGI ===")
            try {
                [void]$sb.AppendLine("Bilgisayar Adi  : $env:COMPUTERNAME")
                [void]$sb.AppendLine("Kullanici       : $env:USERNAME")
                $cs2 = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
                if ($cs2) {
                    $grp = if ($cs2.PartOfDomain) { "Domain: $($cs2.Domain)" } else { "Workgroup: $($cs2.Workgroup)" }
                    [void]$sb.AppendLine("Ag Uyeligi      : $grp")
                    [void]$sb.AppendLine("Uretici / Model : $($cs2.Manufacturer) $($cs2.Model)")
                }
                $tz = (Get-CimInstance Win32_TimeZone -ErrorAction SilentlyContinue).Caption
                if ($tz) { [void]$sb.AppendLine("Saat Dilimi     : $tz") }
                try {
                    $cult = (Get-Culture).DisplayName
                    [void]$sb.AppendLine("Sistem Dili     : $cult")
                } catch {}
                [void]$sb.AppendLine("PowerShell      : $($PSVersionTable.PSVersion.ToString())")
                try {
                    $netRel = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full" -Name Release -ErrorAction SilentlyContinue).Release
                    if ($netRel) { [void]$sb.AppendLine(".NET Framework  : Release $netRel") }
                } catch {}
            } catch {}

            # ===== GUVENLIK =====
            [void]$sb.AppendLine("")
            [void]$sb.AppendLine("=== GUVENLIK ===")
            # Firmware + Secure Boot
            try {
                $fw = if ($env:firmware_type) { $env:firmware_type } elseif (Test-Path "HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State") { "UEFI" } else { "Legacy BIOS" }
                $sbv = (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State" -Name UEFISecureBootEnabled -ErrorAction SilentlyContinue).UEFISecureBootEnabled
                $sbs = if ($null -ne $sbv) { if ([int]$sbv -eq 1) { "Acik" } else { "Kapali" } } else { "Bilinmiyor" }
                [void]$sb.AppendLine("Firmware        : $fw")
                [void]$sb.AppendLine("Secure Boot     : $sbs")
            } catch {}
            # TPM
            try {
                $tpm = Get-CimInstance -Namespace "root\cimv2\Security\MicrosoftTpm" -ClassName Win32_Tpm -ErrorAction SilentlyContinue | Select-Object -First 1
                if ($tpm) {
                    $spec = ($tpm.SpecVersion -split ",")[0].Trim()
                    $st = if ($tpm.IsEnabled_InitialValue) { "aktif" } else { "pasif" }
                    [void]$sb.AppendLine("TPM             : $spec ($st)")
                } else { [void]$sb.AppendLine("TPM             : Yok / algilanmadi") }
            } catch {}
            # UAC
            try {
                $lua = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" -Name EnableLUA -ErrorAction SilentlyContinue).EnableLUA
                [void]$sb.AppendLine("UAC             : $(if ([int]$lua -eq 1) { 'Acik' } else { 'Kapali' })")
            } catch {}
            # Windows Defender
            try {
                $mp = Get-MpComputerStatus -ErrorAction SilentlyContinue
                if ($mp) {
                    [void]$sb.AppendLine("Defender RT     : $(if ($mp.RealTimeProtectionEnabled) { 'Acik' } else { 'Kapali / 3.parti AV' })")
                    [void]$sb.AppendLine("Imza Tarihi     : $(if ($mp.AntivirusSignatureLastUpdated) { $mp.AntivirusSignatureLastUpdated.ToString('dd.MM.yyyy HH:mm') } else { '?' })")
                    $qs = $mp.QuickScanEndTime
                    [void]$sb.AppendLine("Son Hizli Tarama: $(if ($qs) { $qs.ToString('dd.MM.yyyy HH:mm') } else { 'kayit yok' })")
                }
            } catch {}
            # Firewall
            try {
                $fps = Get-NetFirewallProfile -ErrorAction SilentlyContinue
                if ($fps) {
                    $line = ($fps | ForEach-Object { "$($_.Name)=$(if ($_.Enabled) { 'Acik' } else { 'Kapali' })" }) -join "  "
                    [void]$sb.AppendLine("Guvenlik Duvari : $line")
                }
            } catch {}
            # BitLocker C:
            try {
                $bl = Get-BitLockerVolume -MountPoint "C:" -ErrorAction SilentlyContinue
                if ($bl) { [void]$sb.AppendLine("BitLocker (C:)  : $($bl.ProtectionStatus) / $($bl.VolumeStatus)") }
                else { [void]$sb.AppendLine("BitLocker (C:)  : Kapali / desteklenmiyor") }
            } catch { [void]$sb.AppendLine("BitLocker (C:)  : Kapali / desteklenmiyor") }

            # ===== BAKIM =====
            [void]$sb.AppendLine("")
            [void]$sb.AppendLine("=== BAKIM ve GUNCELLEME ===")
            try {
                $hfs = Get-CimInstance Win32_QuickFixEngineering -ErrorAction SilentlyContinue |
                       Where-Object { $_.InstalledOn } | Sort-Object InstalledOn -Descending | Select-Object -First 5
                if ($hfs) {
                    [void]$sb.AppendLine("Son 5 Guncelleme:")
                    foreach ($h in $hfs) { [void]$sb.AppendLine("  - $($h.HotFixID)  ($($h.InstalledOn.ToString('dd.MM.yyyy')))") }
                } else { [void]$sb.AppendLine("Guncellemeler   : kayit okunamadi") }
            } catch {}
            try {
                $pf = Get-CimInstance Win32_PageFileUsage -ErrorAction SilentlyContinue | Select-Object -First 1
                if ($pf) { [void]$sb.AppendLine("Pagefile        : $($pf.Name)  ($([Math]::Round($pf.AllocatedBaseSize/1024,1)) GB)") }
            } catch {}
            try {
                $srEnabled = $false
                $srVal = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore" -Name RPSessionInterval -ErrorAction SilentlyContinue).RPSessionInterval
                $rp = Get-ComputerRestorePoint -ErrorAction SilentlyContinue | Sort-Object CreationTime -Descending | Select-Object -First 1
                if ($rp) {
                    $rpDate = [Management.ManagementDateTimeConverter]::ToDateTime($rp.CreationTime)
                    [void]$sb.AppendLine("Sistem Geri Yukleme: Acik (son nokta: $($rpDate.ToString('dd.MM.yyyy HH:mm')))")
                } else {
                    [void]$sb.AppendLine("Sistem Geri Yukleme: nokta yok / kapali")
                }
            } catch { [void]$sb.AppendLine("Sistem Geri Yukleme: okunamadi") }

            return $sb.ToString()
        }

        # Async calistir — UI donmasin
        $ssRs = [powershell]::Create()
        [void]$ssRs.AddScript($collectScript)
        $ssHandle = $ssRs.BeginInvoke()

        $ssTimer = New-Object System.Windows.Threading.DispatcherTimer
        $ssTimer.Interval = [TimeSpan]::FromMilliseconds(200)
        $ssTimer.Add_Tick({
            if (-not $ssHandle.IsCompleted) { return }
            $ssTimer.Stop()
            try {
                $out = $ssRs.EndInvoke($ssHandle)
                $text = if ($out -and $out.Count -gt 0) { [string]($out | Select-Object -Last 1) } else { "Veri toplanamadi." }
                $txtSSBody.Text = $text
            } catch {
                $txtSSBody.Text = "Hata: $($_.Exception.Message)"
            } finally {
                try { $ssRs.Dispose() } catch {}
            }
        }.GetNewClosure())
        $ssTimer.Start()

        [void]$winSS.ShowDialog()
    } catch {
        WpfLog ("SystemSecurityDetail Hata: " + $_.Exception.Message)
    }
}

# =========================================================
# DNS BENCHMARK (v1.2.22)
# 5 populer DNS server + ISP DNS karsilastir, Resolve-DnsName ile median lookup time olc,
# en hizliyi otomatik vurgula, "Apply" ile mevcut DNS ayarini degistir.
# =========================================================

function Get-DnsServersToTest {
    return @(
        @{ Name="Cloudflare";              Primary="1.1.1.1";        Secondary="1.0.0.1";          Vendor="Cloudflare (Gizlilik + Hizli)" }
        @{ Name="Google";                  Primary="8.8.8.8";        Secondary="8.8.4.4";          Vendor="Google Public DNS" }
        @{ Name="Quad9";                   Primary="9.9.9.9";        Secondary="149.112.112.112";  Vendor="Quad9 (Malware Block)" }
        @{ Name="AdGuard DNS";             Primary="94.140.14.14";   Secondary="94.140.15.15";     Vendor="AdGuard (Reklam Bloku)" }
        @{ Name="CleanBrowsing Security";  Primary="185.228.168.9";  Secondary="185.228.169.9";    Vendor="CleanBrowsing" }
        # NOT: OpenDNS (208.67.222.222) cikarildi - varsayilan sorgu icin Cisco hesabi/yapilandirma
        # gerekiyor, blank sorguda timeout veriyordu. DNS0.eu (193.110.81.0) cikarildi - servis
        # Aralik 2024'te KAPANDI (justgeek.fr/fermeture-dns0eu). Ikisi de olu-server timeout'u ile
        # benchmark'i ~40sn yavaslatiyordu.
        # v1.3.0 (§84): DNS.WATCH (84.200.69.80/70.40) ve Comodo Secure DNS (8.26.56.26/8.20.247.20) cikarildi —
        # kullanici hattindan sorgularin bir kismi yanitsiz (~7 sn zaman asimi; 84.200.69.80 0/5), median 1-1,3 sn,
        # basari 4/10. Ikisi de DoH/DoT sunmuyor. Kalan 5 server + ISP/mevcut DNS.
    )
}

function Get-IspDns {
    # Mevcut aktif NIC'lerin DNS server adreslerini topla (ISP DNS veya kullanici-set)
    $servers = New-Object System.Collections.Generic.List[string]
    try {
        $adapters = Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq "Up" -and $_.InterfaceType -in @(6, 71) }
        foreach ($a in $adapters) {
            try {
                $dns = (Get-DnsClientServerAddress -InterfaceIndex $a.InterfaceIndex -AddressFamily IPv4 -ErrorAction Stop).ServerAddresses
                foreach ($d in $dns) {
                    if ($d -and -not $servers.Contains($d)) { [void]$servers.Add($d) }
                }
            } catch {}
        }
    } catch {}
    return @($servers)
}

function Test-DnsServer {
    param(
        [Parameter(Mandatory=$true)][string]$DnsIp,
        [Parameter(Mandatory=$true)][array]$Domains,
        [int]$WarmupCount = 1
    )
    $times = New-Object System.Collections.Generic.List[double]
    $errCnt = 0
    # Warmup — ilk lookup cache populasyonu icin atla
    for ($w = 0; $w -lt $WarmupCount; $w++) {
        try { $null = Resolve-DnsName -Name $Domains[0] -Type A -Server $DnsIp -DnsOnly -NoHostsFile -QuickTimeout -ErrorAction Stop } catch {}
    }
    foreach ($d in $Domains) {
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            $null = Resolve-DnsName -Name $d -Type A -Server $DnsIp -DnsOnly -NoHostsFile -QuickTimeout -ErrorAction Stop
            $sw.Stop()
            [void]$times.Add($sw.Elapsed.TotalMilliseconds)
        } catch {
            $sw.Stop()
            $errCnt++
        }
    }
    if ($times.Count -eq 0) {
        return @{ Ok=$false; AvgMs=99999; MedianMs=99999; MinMs=-1; MaxMs=-1; ErrorCount=$errCnt; SuccessCount=0; Total=$Domains.Count }
    }
    $sorted = $times | Sort-Object
    $n = $sorted.Count
    $median = if ($n % 2 -eq 1) { $sorted[[int][Math]::Floor($n/2)] } else { ($sorted[$n/2 - 1] + $sorted[$n/2]) / 2 }
    return @{
        Ok=$true
        AvgMs    = [Math]::Round(($times | Measure-Object -Average).Average, 1)
        MedianMs = [Math]::Round($median, 1)
        MinMs    = [Math]::Round(($times | Measure-Object -Minimum).Minimum, 1)
        MaxMs    = [Math]::Round(($times | Measure-Object -Maximum).Maximum, 1)
        ErrorCount = $errCnt
        SuccessCount = $times.Count
        Total = $Domains.Count
    }
}

function Set-PreferredDns {
    param(
        [Parameter(Mandatory=$true)][string]$PrimaryIp,
        [string]$SecondaryIp = ""
    )
    $count = 0
    try {
        $adapters = Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq "Up" -and $_.InterfaceType -in @(6, 71) }
        $addrs = @($PrimaryIp)
        if ($SecondaryIp -and $SecondaryIp -ne "") { $addrs += $SecondaryIp }
        foreach ($a in $adapters) {
            try {
                & netsh interface ipv4 set dnsservers name="$($a.Name)" source=static address=$PrimaryIp register=primary validate=no 2>&1 | Out-Null
                if ($SecondaryIp -and $SecondaryIp -ne "") {
                    & netsh interface ipv4 add dnsservers name="$($a.Name)" address=$SecondaryIp index=2 validate=no 2>&1 | Out-Null
                }
                $count++
            } catch {}
        }
    } catch {}
    & ipconfig /flushdns 2>&1 | Out-Null
    return $count
}

function Show-DnsBenchmark {
    # v1.2.22 WPF + PARALEL RUNSPACE rewrite.
    # NOT (kok neden gecmisi): Onceki crash ("Bagimsiz degisken turleri eslesmiyor") WPF/WinForms
    # ile alakali DEGILDI. Suclu "@(arr) + @($genericList)" deseniydi; Generic.List[object] ile
    # array (+) birlestirme, scriptblock DELEGATE (buton click) olarak calisinca PSToObjectArrayBinder
    # crash veriyordu. Cozum: tek ArrayList + (+) operatoru yok. Bu surumde de bu kurala uyulur.
    #
    # PARALEL: Eski surum DNS serverlari SIRAYLA test ediyordu; cevap vermeyen (olu) server basina
    # ~15-20 sn timeout bekleniyordu (ornek OpenDNS/DNS0.eu bloklu ise toplam +30-40 sn). Yeni surum
    # her server icin ayri runspace acar (paralel), toplam sure ~ en yavas tek server. Dispatcher
    # pump (DispatcherPriority.Background) ile UI donmaz, progress bar canli ilerler.
    try {
        $domains = @("google.com","cloudflare.com","github.com","stackoverflow.com","wikipedia.org","microsoft.com","amazon.com","reddit.com","youtube.com","apple.com")

        # Runspace icinde calisacak DNS olcum scriptblock'u (kendi runspace'inde Test-DnsServer
        # fonksiyonuna erisimi olmadigindan mantik buraya gomulu — Test-DnsServer ile birebir ayni).
        $dnsTestScript = {
            param($DnsIp, $Domains, $WarmupCount)
            $times = New-Object System.Collections.Generic.List[double]
            $errCnt = 0
            for ($w = 0; $w -lt $WarmupCount; $w++) {
                try { $null = Resolve-DnsName -Name $Domains[0] -Type A -Server $DnsIp -DnsOnly -NoHostsFile -QuickTimeout -ErrorAction Stop } catch {}
            }
            foreach ($d in $Domains) {
                $sw = [System.Diagnostics.Stopwatch]::StartNew()
                try {
                    $null = Resolve-DnsName -Name $d -Type A -Server $DnsIp -DnsOnly -NoHostsFile -QuickTimeout -ErrorAction Stop
                    $sw.Stop(); [void]$times.Add($sw.Elapsed.TotalMilliseconds)
                } catch { $sw.Stop(); $errCnt++ }
            }
            if ($times.Count -eq 0) {
                return @{ Ok=$false; AvgMs=99999; MedianMs=99999; MinMs=-1; MaxMs=-1; ErrorCount=$errCnt; SuccessCount=0; Total=$Domains.Count }
            }
            $sortedT = $times | Sort-Object
            $n = $sortedT.Count
            $median = if ($n % 2 -eq 1) { $sortedT[[int][Math]::Floor($n/2)] } else { ($sortedT[$n/2 - 1] + $sortedT[$n/2]) / 2 }
            return @{
                Ok=$true
                AvgMs    = [Math]::Round(($times | Measure-Object -Average).Average, 1)
                MedianMs = [Math]::Round($median, 1)
                MinMs    = [Math]::Round(($times | Measure-Object -Minimum).Minimum, 1)
                MaxMs    = [Math]::Round(($times | Measure-Object -Maximum).Maximum, 1)
                ErrorCount = $errCnt; SuccessCount = $times.Count; Total = $Domains.Count
            }
        }

        $xamlDns = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="🔎 DNS Benchmark - En Hizli DNS Server" Height="640" Width="980"
        Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner"
        WindowStyle="ToolWindow" ResizeMode="CanResize" MinWidth="780" MinHeight="500">
    <Window.Resources>
$($global:SubTheme)
        <Style x:Key="DBtn" TargetType="Button" BasedOn="{StaticResource SwBtn}"/>
    </Window.Resources>
    <Grid Margin="14">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <TextBlock Grid.Row="0" Text="🔎 DNS Benchmark" Foreground="#E6E8EB" FontSize="20" FontWeight="Bold" Margin="0,0,0,4"/>
        <TextBlock Grid.Row="1" Foreground="#8A919C" FontSize="12" Margin="0,0,0,10" TextWrapping="Wrap"
                   Text="5 populer DNS server + ISP/mevcut DNS karsilastirma. Her server icin 10 domain test (Resolve-DnsName). Tum serverlar PARALEL test edilir (hizli). Sonuc median'a gore sirali, en hizli ustte (yesil). Cevap vermeyen serverlar en altta (kirmizi). 'Uygula' ile secili DNS tum aktif NIC'lere yazilir."/>

        <Grid Grid.Row="2" Margin="0,0,0,10">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>
            <Button x:Name="btnBench" Grid.Column="0" Style="{StaticResource SwBtnPrimary}" Content="&gt;&gt; Benchmark Baslat" MinWidth="200" Height="32" FontWeight="Bold"/>
            <ProgressBar x:Name="pbDns" Grid.Column="1" Height="18" Margin="12,0,0,0" Background="#15181E" Foreground="#8CB4FF" BorderBrush="#232831" Minimum="0" Maximum="100" Value="0" VerticalAlignment="Center"/>
        </Grid>

        <TextBlock Grid.Row="3" x:Name="lblStat" Foreground="#8A919C" FontSize="12" Margin="0,0,0,8" Text="Hazir - Bench baslatmak icin yukaridaki butona tikla"/>

        <Border Grid.Row="4" Background="#15181E" CornerRadius="5" BorderBrush="#232831" BorderThickness="1">
            <ListView x:Name="lvDns" Background="Transparent" BorderThickness="0" Foreground="#E6E8EB">
                <ListView.View>
                    <GridView>
                        <GridView.ColumnHeaderContainerStyle>
                            <Style TargetType="GridViewColumnHeader" BasedOn="{StaticResource SwGridHeader}"/>
                        </GridView.ColumnHeaderContainerStyle>
                        <GridViewColumn Header="#"           Width="44"  DisplayMemberBinding="{Binding Rank}"/>
                        <GridViewColumn Header="DNS Server"  Width="280" DisplayMemberBinding="{Binding Vendor}"/>
                        <GridViewColumn Header="Primary IP"  Width="140" DisplayMemberBinding="{Binding Primary}"/>
                        <GridViewColumn Header="Median (ms)" Width="100" DisplayMemberBinding="{Binding MedianDisp}"/>
                        <GridViewColumn Header="Avg (ms)"    Width="90"  DisplayMemberBinding="{Binding AvgDisp}"/>
                        <GridViewColumn Header="Min / Max"   Width="120" DisplayMemberBinding="{Binding MinMaxDisp}"/>
                        <GridViewColumn Header="Basari"      Width="80"  DisplayMemberBinding="{Binding SuccessDisp}"/>
                    </GridView>
                </ListView.View>
                <ListView.ItemContainerStyle>
                    <Style TargetType="ListViewItem" BasedOn="{StaticResource SwListRow}">   <!-- v1.3.0 (§85) -->
                        <Setter Property="Padding" Value="2,3"/>
                        <Style.Triggers>
                            <DataTrigger Binding="{Binding RowKind}" Value="best">
                                <Setter Property="Background" Value="#16241C"/>
                                <Setter Property="Foreground" Value="#E6E8EB"/>
                                <Setter Property="FontWeight" Value="Bold"/>
                            </DataTrigger>
                            <DataTrigger Binding="{Binding RowKind}" Value="dead">
                                <Setter Property="Foreground" Value="#E5484D"/>
                            </DataTrigger>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter Property="Background" Value="#1C2433"/>
                            </Trigger>
                        </Style.Triggers>
                    </Style>
                </ListView.ItemContainerStyle>
            </ListView>
        </Border>

        <Grid Grid.Row="5" Margin="0,10,0,0">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <Button x:Name="btnApply" Grid.Column="0" Style="{StaticResource SwBtnPrimary}" Content="Secili DNS'i Uygula" MinWidth="180" Height="32" IsEnabled="False"/>
            <Button x:Name="btnClose" Grid.Column="2" Style="{StaticResource DBtn}" Content="@@m_close@@" MinWidth="100" Height="32"/>
        </Grid>
    </Grid>
</Window>
"@

        $reader = New-Object System.Xml.XmlNodeReader ([xml](Localize-Xaml $xamlDns))
        $winDns = [Windows.Markup.XamlReader]::Load($reader)
        Initialize-SubWindow $winDns
        try { $winDns.Owner = $Win } catch {}

        $btnBench = $winDns.FindName('btnBench')
        $pbDns    = $winDns.FindName('pbDns')
        $lblStat  = $winDns.FindName('lblStat')
        $lvDns    = $winDns.FindName('lvDns')
        $btnApply = $winDns.FindName('btnApply')
        $btnClose = $winDns.FindName('btnClose')

        $btnBench.Add_Click({
            try {
                $btnBench.IsEnabled = $false
                $btnApply.IsEnabled = $false
                $lvDns.ItemsSource = $null
                $pbDns.Value = 0

                # Sunucu listesi + ISP/mevcut DNS — tek ArrayList, (+) operatoru YOK (delegate crash onlemi)
                $servers = @(Get-DnsServersToTest)
                $ispDns  = @(Get-IspDns)
                $allServers = New-Object System.Collections.ArrayList
                foreach ($s in $servers) { [void]$allServers.Add($s) }
                foreach ($ip in $ispDns) {
                    $found = $false
                    foreach ($s in $servers) { if ($s.Primary -eq $ip -or $s.Secondary -eq $ip) { $found = $true; break } }
                    if (-not $found) {
                        [void]$allServers.Add(@{ Name="ISP/Mevcut"; Primary=$ip; Secondary=""; Vendor="ISP DNS / Mevcut (auto-detect)" })
                    }
                }

                $lblStat.Text = "Test basliyor: $($allServers.Count) DNS server PARALEL test ediliyor (x $($domains.Count) domain)..."
                $winDns.Dispatcher.Invoke([action]{}, [System.Windows.Threading.DispatcherPriority]::Background)

                # PARALEL: her server icin ayri runspace (dedicated pool, server sayisi kadar)
                $iss  = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
                $pool = [runspacefactory]::CreateRunspacePool(1, [Math]::Min([Math]::Max($allServers.Count,1), 16), $iss, $Host)
                $pool.Open()
                $jobs = New-Object System.Collections.ArrayList
                foreach ($s in $allServers) {
                    $ps = [powershell]::Create(); $ps.RunspacePool = $pool
                    [void]$ps.AddScript($dnsTestScript).AddArgument($s.Primary).AddArgument($domains).AddArgument(1)
                    $h = $ps.BeginInvoke()
                    [void]$jobs.Add(@{ PS=$ps; Handle=$h; Server=$s })
                }

                # Bekleme + UI pump (donmaz, progress canli)
                $done = 0
                while ($done -lt $jobs.Count) {
                    $done = 0
                    foreach ($j in $jobs) { if ($j.Handle.IsCompleted) { $done++ } }
                    $pbDns.Value = [int](($done / $jobs.Count) * 100)
                    $lblStat.Text = "$done / $($jobs.Count) server tamamlandi..."
                    $winDns.Dispatcher.Invoke([action]{}, [System.Windows.Threading.DispatcherPriority]::Background)
                    Start-Sleep -Milliseconds 50
                }

                # Sonuclari topla
                $results = New-Object System.Collections.ArrayList
                foreach ($j in $jobs) {
                    $r = $null
                    try { $out = $j.PS.EndInvoke($j.Handle); if ($out -and $out.Count -gt 0) { $r = $out[0] } } catch {}
                    if (-not $r) { $r = @{ Ok=$false; AvgMs=99999; MedianMs=99999; MinMs=-1; MaxMs=-1; SuccessCount=0; Total=$domains.Count } }
                    $s = $j.Server
                    [void]$results.Add([PSCustomObject]@{
                        Vendor=$s.Vendor; Primary=$s.Primary; Secondary=$s.Secondary
                        MedianMs=[double]$r.MedianMs; AvgMs=$r.AvgMs; MinMs=$r.MinMs; MaxMs=$r.MaxMs
                        SuccessCount=$r.SuccessCount; Total=$r.Total; OkFlag=$r.Ok
                    })
                    try { $j.PS.Dispose() } catch {}
                }
                try { $pool.Close(); $pool.Dispose() } catch {}

                # Siralama: calisanlar median'a gore artan, olular en altta. (+) operatoru iki duz
                # array uzerinde — guvenli (Generic.List degil).
                $okList = New-Object System.Collections.ArrayList
                $failList = New-Object System.Collections.ArrayList
                foreach ($r in $results) { if ($r.OkFlag) { [void]$okList.Add($r) } else { [void]$failList.Add($r) } }
                $okSorted = @(); $failSorted = @()
                if ($okList.Count -gt 0)   { $okSorted   = @($okList   | Sort-Object -Property MedianMs) }
                if ($failList.Count -gt 0) { $failSorted = @($failList | Sort-Object -Property MedianMs) }
                $sorted = @($okSorted) + @($failSorted)

                # Goruntu modelleri (ItemsSource icin)
                $items = New-Object System.Collections.ArrayList
                $rank = 0
                foreach ($r in $sorted) {
                    $rank++
                    $kind = if (-not $r.OkFlag) { "dead" } elseif ($rank -eq 1) { "best" } else { "normal" }
                    [void]$items.Add([PSCustomObject]@{
                        Rank        = $rank
                        Vendor      = $r.Vendor
                        Primary     = $r.Primary
                        Secondary   = $r.Secondary
                        MedianDisp  = $(if ($r.OkFlag) { "$($r.MedianMs)" } else { "-" })
                        AvgDisp     = $(if ($r.OkFlag) { "$($r.AvgMs)" } else { "-" })
                        MinMaxDisp  = $(if ($r.OkFlag) { "$($r.MinMs) / $($r.MaxMs)" } else { "-" })
                        SuccessDisp = "$($r.SuccessCount)/$($r.Total)"
                        RowKind     = $kind
                    })
                }
                $lvDns.ItemsSource = $items
                $pbDns.Value = 100

                if ($sorted.Count -gt 0 -and $sorted[0].OkFlag) {
                    $lblStat.Text = "Tamamlandi. En hizli: $($sorted[0].Vendor) ($($sorted[0].Primary)) - median $($sorted[0].MedianMs) ms"
                    if ($lvDns.Items.Count -gt 0) { $lvDns.SelectedIndex = 0; $btnApply.IsEnabled = $true }
                } else {
                    $lblStat.Text = "Tamamlandi - hicbir server yanit vermedi (ag/firewall DNS portunu blokluyor olabilir)."
                }
                $btnBench.IsEnabled = $true
            } catch {
                $lblStat.Text = "Hata: $($_.Exception.Message)"
                WpfLog ("DnsBenchmark click hata: " + $_.Exception.Message)
                WpfLog ("  Stack: " + $_.ScriptStackTrace)
                $btnBench.IsEnabled = $true
            }
        })

        $btnApply.Add_Click({
            try {
                $sel = $lvDns.SelectedItem
                if (-not $sel) { return }
                $primary = [string]$sel.Primary
                $secondary = [string]$sel.Secondary
                $vendor = [string]$sel.Vendor
                $msg = "DNS degistirilecek:`n`n  Primary: $primary"
                if ($secondary -and $secondary -ne "") { $msg += "`n  Secondary: $secondary" }
                $msg += "`n  Server: $vendor`n`nTum aktif NIC'lere yazilir + DNS cache flush. Devam?"
                # v1.3.0 (5. tur): YogaDNS / NextDNS / GoodbyeDPI vb. calisiyorsa DNS e dokunma
                $g = @(Get-MrCleanDnsGuard -Fresh)
                if ($g.Count -gt 0) { [System.Windows.MessageBox]::Show("DNS degistirilmedi: $($g -join ", ") calisiyor ve DNS ayarini o yonetiyor.`n`nDNS i degistirmek istiyorsaniz once o araci kapatin.", "DNS") | Out-Null; return }
                $resp = [System.Windows.MessageBox]::Show($msg, "DNS Apply - Onay", "YesNo", "Question")
                if ($resp -ne "Yes") { return }
                $count = Set-PreferredDns -PrimaryIp $primary -SecondaryIp $secondary
                [System.Windows.MessageBox]::Show("DNS uygulandi.`n`n  $count NIC guncellendi`n  DNS cache flush yapildi`n`nDashboard 'Aktif DNS' gostergesi 5-10 sn icinde guncellenir.", "Basarili") | Out-Null
            } catch {
                WpfLog ("DnsBenchmark apply hata: " + $_.Exception.Message)
            }
        })

        $btnClose.Add_Click({ $winDns.Close() })

        [void]$winDns.ShowDialog()
    } catch {
        WpfLog ("DnsBenchmark Hata: " + $_.Exception.Message)
        if ($_.Exception.InnerException) { WpfLog ("  Inner: " + $_.Exception.InnerException.Message) }
    }
}

# =========================================================
# v1.3.0 (6. tur): AG KALITE TESTI — hiz + yuk altinda gecikme (bufferbloat) + hatta gore oneri
# Hiz BAZLI elle ayar yoktur (Windows TCP otomatik ayari 10 Mbps - 10 Gbps arasini zaten uyarlar). Asil sorunlar:
# yuk altinda gecikme sismesi (router kuyrugu), arka plan indirmeleri, Wi-Fi, kablo/port darbogazi, TCP otomatik
# ayarinin baska bir aracla kisilmis olmasi. Bu test bunlari OLCER ve sadece ilgili oneriyi gosterir.
# Sadece kullanici "Baslat" deyince calisir. 7. tur: yurtici (Cloudflare IST) + yurtdisi 3 saglayici (Hetzner DE, Linode DE,
# OVH FR) + oyun bolgeleri (Valve SDR relay ICMP, AWS bolge TCP 443) + gecmis ortancasi (HKCU\Software\MrClean NetTestHistory).
# =========================================================
function Show-NetworkQualityTest {
    $xamlNq = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="🌐 Ağ Kalite Testi" Height="760" Width="880" Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner" WindowStyle="ToolWindow" ResizeMode="CanResize">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <Grid Margin="14">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <TextBlock Grid.Row="0" TextWrapping="Wrap" Foreground="#C9CED6" FontSize="13"
                   Text="Yurtiçi (Cloudflare İstanbul) ve yurtdışı (Almanya x2, Fransa) sunuculara indirme / yükleme hızını, hat YÜK ALTINDAYKEN ping artışını (bufferbloat) ve oyun sunucusu bölgelerine (CS2 Valve, Battlefield / PUBG AWS Frankfurt, Warzone AB, Valorant İstanbul) gecikmeyi ölçer. Tek sunucu ya da tek an yanıltmasın diye her sınıfta birden çok sunucu ölçülür, yavaş kalan tek sunucu ayıklanır ve son testlerin ortancası (medyan) kullanılır. HİÇBİR AYAR DEĞİŞTİRİLMEZ — sadece ölçüm ve öneri. Süre ~1 dk; veri: hızınıza göre ~100 MB - 2 GB."/>
        <Border Grid.Row="1" Background="#15181E" CornerRadius="6" Padding="12" Margin="0,10,0,10">
            <TextBlock x:Name="txtNqStatus" Foreground="#E6E8EB" FontSize="13.5" FontFamily="Cascadia Mono, Consolas" TextWrapping="Wrap" Text="Hazır. 'Testi Başlat'a basın."/>
        </Border>
        <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto">
            <TextBlock x:Name="txtNqAdvice" Foreground="#E6E8EB" FontSize="14" TextWrapping="Wrap"/>
        </ScrollViewer>
        <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,10,0,0">
            <Button x:Name="btnNqClear" Content="Geçmişi Sil" MinWidth="110" Height="34" Margin="0,0,8,0"/>
            <Button Style="{StaticResource SwBtnPrimary}" x:Name="btnNqStart" Content="▶ Testi Başlat" MinWidth="160" Height="34" Margin="0,0,8,0"/>
            <Button x:Name="btnNqClose" Content="Kapat" MinWidth="90" Height="34"/>
        </StackPanel>
    </Grid>
</Window>
"@
    $w = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader ([xml]$xamlNq)))
    Initialize-SubWindow $w
    $txtNqStatus = $w.FindName('txtNqStatus'); $txtNqAdvice = $w.FindName('txtNqAdvice')
    $btnNqStart = $w.FindName('btnNqStart'); $btnNqClose = $w.FindName('btnNqClose'); $btnNqClear = $w.FindName('btnNqClear')
    $script:NqSync = [hashtable]::Synchronized(@{ Phase = ""; Done = $false; Err = ""; Live = "" })
    $script:NqHistKey = "HKCU:\Software\MrClean"

    $worker = {
        param($sync)
        $ErrorActionPreference = "SilentlyContinue"
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
        [Net.ServicePointManager]::DefaultConnectionLimit = 64
        $UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) MrClean-NetTest"   # Hetzner vb. User-Agent siz istegi keser
        function Med($a) { $s = @($a | Sort-Object); if ($s.Count -eq 0) { return $null }; $m = [int][Math]::Floor($s.Count / 2); if ($s.Count % 2) { return [double]$s[$m] }; return ([double]$s[$m - 1] + [double]$s[$m]) / 2 }
        function Jit($a) { $a = @($a); if ($a.Count -lt 2) { return 0 }; $d = 0; for ($i = 1; $i -lt $a.Count; $i++) { $d += [Math]::Abs($a[$i] - $a[$i - 1]) }; return $d / ($a.Count - 1) }
        function TcpRtt([System.Net.IPAddress]$ip, [int]$port) {
            $c = New-Object System.Net.Sockets.TcpClient
            try { $sw = [Diagnostics.Stopwatch]::StartNew(); $t = $c.ConnectAsync($ip, $port); if ($t.Wait(2000) -and $c.Connected) { return $sw.Elapsed.TotalMilliseconds } } catch {} finally { $c.Close() }
            return $null
        }
        # ICMP (yoksa TCP 443 baglanti suresi). Ilk olcum (DNS / ARP / TLS isinmasi) atilir.
        function Probe([string]$target, [int]$n, [int]$gap, [switch]$Tcp) {
            $ok = New-Object System.Collections.Generic.List[double]; $lost = 0
            if ($Tcp) {
                $ip = $null; try { $ip = [System.Net.Dns]::GetHostAddresses($target) | Where-Object { $_.AddressFamily -eq "InterNetwork" } | Select-Object -First 1 } catch {}
                if (-not $ip) { return @{ S = @(); Lost = $n; N = $n } }
                [void](TcpRtt $ip 443)
                for ($i = 0; $i -lt $n; $i++) { $r = TcpRtt $ip 443; if ($null -ne $r) { $ok.Add($r) } else { $lost++ }; Start-Sleep -Milliseconds $gap }
            } else {
                $p = New-Object System.Net.NetworkInformation.Ping
                try { [void]$p.Send($target, 1000) } catch {}
                for ($i = 0; $i -lt $n; $i++) { try { $r = $p.Send($target, 1000); if ($r.Status -eq "Success") { $ok.Add([double]$r.RoundtripTime) } else { $lost++ } } catch { $lost++ }; Start-Sleep -Milliseconds $gap }
            }
            return @{ S = $ok.ToArray(); Lost = $lost; N = $n }
        }
        # Cok akisli yuk testi. Hiz = 1.5 sn isinma sonrasi araliklarin en dusuk %25 i atilarak ortalamasi (Ookla benzeri);
        # son 2 sn kararliysa (std < %5) erken biter. Yuk altindaki ping ayni anda olculur.
        function LoadTest([string[]]$urls, [string]$mode, [int]$streams, [int]$maxSec, [double]$capBytes, [string]$pingIp) {
            $ctl = [hashtable]::Synchronized(@{ Stop = $false }); $jobs = @()
            for ($k = 0; $k -lt $streams; $k++) {
                $ctl["b$k"] = [long]0
                $ps = [powershell]::Create()
                [void]$ps.AddScript({
                    param($ctl, $k, $mode, $url, $UA)
                    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
                    $buf = New-Object byte[] 65536; (New-Object System.Random).NextBytes($buf)
                    while (-not $ctl.Stop) {
                        try {
                            if ($mode -eq "down") {
                                $req = [System.Net.HttpWebRequest]::Create($url); $req.UserAgent = $UA
                                if ($url -match "speed\.cloudflare\.com") { $req.Referer = "https://speed.cloudflare.com/"; $req.Headers.Add("Origin", "https://speed.cloudflare.com") }
                                $req.Timeout = 8000; $req.ReadWriteTimeout = 8000
                                $resp = $req.GetResponse(); $st = $resp.GetResponseStream()
                                while (-not $ctl.Stop) { $n = $st.Read($buf, 0, $buf.Length); if ($n -le 0) { break }; $ctl["b$k"] += $n }
                                $st.Close(); $resp.Close()
                            } else {
                                $req = [System.Net.HttpWebRequest]::Create($url); $req.UserAgent = $UA
                                if ($url -match "speed\.cloudflare\.com") { $req.Referer = "https://speed.cloudflare.com/"; $req.Headers.Add("Origin", "https://speed.cloudflare.com") }
                                $req.Method = "POST"; $req.ContentType = "application/octet-stream"; $req.AllowWriteStreamBuffering = $false
                                $req.ContentLength = 100000000; $req.Timeout = 8000; $req.ReadWriteTimeout = 8000
                                $st = $req.GetRequestStream(); $sent = 0
                                while (-not $ctl.Stop -and $sent -lt 100000000) { $st.Write($buf, 0, $buf.Length); $sent += $buf.Length; $ctl["b$k"] += $buf.Length }
                                if ($ctl.Stop) { $req.Abort() } else { $st.Close(); try { ($req.GetResponse()).Close() } catch {} }
                            }
                        } catch {
                            $code = 0; try { $code = [int]$_.Exception.InnerException.Response.StatusCode } catch {}
                            if ($code -eq 429 -or $code -eq 403) { $ctl["e$k"] = $code; break }
                            Start-Sleep -Milliseconds 300
                        }
                    }
                }).AddArgument($ctl).AddArgument($k).AddArgument($mode).AddArgument($urls[$k % $urls.Count]).AddArgument($UA)
                $jobs += @{ PS = $ps; H = $ps.BeginInvoke() }
            }
            $sum = { $t = 0; for ($q = 0; $q -lt $streams; $q++) { $t += $ctl["b$q"] }; $t }
            $sw = [Diagnostics.Stopwatch]::StartNew()
            Start-Sleep -Milliseconds 1500
            $lastB = & $sum; $lastT = $sw.Elapsed.TotalSeconds; $warmT = $lastT
            $rates = New-Object System.Collections.Generic.List[double]; $pings = New-Object System.Collections.Generic.List[double]
            $p = New-Object System.Net.NetworkInformation.Ping; $i = 0
            while ($sw.Elapsed.TotalSeconds -lt $maxSec) {
                if ($pingIp -and ($i % 2 -eq 0)) { try { $r = $p.Send($pingIp, 1000); if ($r.Status -eq "Success") { $pings.Add([double]$r.RoundtripTime) } } catch {} }
                Start-Sleep -Milliseconds 200; $i++
                $b = & $sum; $t = $sw.Elapsed.TotalSeconds
                if ($t - $lastT -gt 0.05) { $rates.Add((($b - $lastB) * 8 / 1e6) / ($t - $lastT)) }
                $lastB = $b; $lastT = $t
                if ($rates.Count -gt 0) { $sync.Live = ("{0:N0} Mbps" -f $rates[$rates.Count - 1]) }
                if ($b -gt $capBytes) { break }
                if (($t - $warmT) -ge 4 -and $rates.Count -ge 8) {
                    $last = @($rates | Select-Object -Last 8); $avg = ($last | Measure-Object -Average).Average
                    if ($avg -gt 0) { $var = 0; foreach ($x in $last) { $var += ($x - $avg) * ($x - $avg) }; if ([Math]::Sqrt($var / 8) -lt 0.05 * $avg) { break } }
                }
            }
            $total = & $sum
            $ctl.Stop = $true
            foreach ($j in $jobs) { try { [void]$j.H.AsyncWaitHandle.WaitOne(2500); $j.PS.Stop(); $j.PS.Dispose() } catch {} }
            $mbps = 0
            if ($rates.Count -gt 0) { $s = @($rates | Sort-Object); $skip = [int][Math]::Floor($s.Count * 0.25); $keep = @($s | Select-Object -Skip $skip); $mbps = ($keep | Measure-Object -Average).Average }
            return @{ Mbps = [Math]::Round($mbps, 1); Pings = $pings.ToArray(); MB = [Math]::Round($total / 1MB) }
        }

        try {
            # 0) Cloudflare hangi noktaya gidiyor? (IST = yurtici)
            $sync.Phase = "Sunucu konumu kontrol ediliyor..."
            $colo = ""; $loc = ""
            try {
                $rq = [System.Net.HttpWebRequest]::Create("https://speed.cloudflare.com/cdn-cgi/trace"); $rq.UserAgent = $UA; $rq.Timeout = 8000
                $rs = $rq.GetResponse(); $tx = (New-Object System.IO.StreamReader($rs.GetResponseStream())).ReadToEnd(); $rs.Close()
                if ($tx -match "colo=(\w+)") { $colo = $Matches[1] }; if ($tx -match "loc=(\w+)") { $loc = $Matches[1] }
            } catch {}
            $sync.Colo = $colo; $sync.Loc = $loc

            # 1) Bostaki gecikme (Cloudflare anycast 1.1.1.1 — Turkiye de IST)
            $sync.Phase = "Boştaki gecikme ölçülüyor..."
            $idle = Probe "1.1.1.1" 20 100
            $icmp = $true
            if (@($idle.S).Count -lt 5) { $icmp = $false; $idle = Probe "1.1.1.1" 15 100 -Tcp }
            if (@($idle.S).Count -lt 5) { $sync.Err = "1.1.1.1 e ulaşılamadı (internet / güvenlik duvarı)."; $sync.Done = $true; return }
            $sync.Idle = $idle; $sync.Icmp = $icmp

            # 2) Oyun bolgeleri: Valve SDR (CS2) relay ICMP + AWS bolge uc noktalari TCP 443 (cloudping yontemi)
            $sync.Phase = "Oyun sunucusu bölgeleri ölçülüyor (Valve / AWS)..."
            $reg = [ordered]@{}
            try {
                $rq = [System.Net.HttpWebRequest]::Create("https://api.steampowered.com/ISteamApps/GetSDRConfig/v1/?appid=730"); $rq.UserAgent = $UA; $rq.Timeout = 10000
                $rs = $rq.GetResponse(); $js = (New-Object System.IO.StreamReader($rs.GetResponseStream())).ReadToEnd(); $rs.Close()
                $cfg = $js | ConvertFrom-Json
                foreach ($pop in @("vie","fra","waw","ams","par","sto","dxb")) {
                    $rl = @($cfg.pops.$pop.relays); if ($rl.Count -eq 0) { continue }
                    $r = Probe "$($rl[0].ipv4)" 8 60
                    $reg["valve_$pop"] = @{ Med = (Med $r.S); Lost = $r.Lost; N = $r.N }
                }
            } catch {}
            foreach ($aws in @("eu-central-1","eu-south-1","eu-west-3","eu-west-2","eu-north-1","me-central-1")) {
                $r = Probe "dynamodb.$aws.amazonaws.com" 6 60 -Tcp
                $reg["aws_$aws"] = @{ Med = (Med $r.S); Lost = $r.Lost; N = $r.N }
            }
            $sync.Regions = $reg

            # 3) Yurtici indirme (Cloudflare IST) + yuk altinda ping. NOT (2026-10): Cloudflare, Referer / Origin speed.cloudflare.com OLMAYAN 100 MB+ istegi 403 ile reddediyor (kotuye kullanim kurali,
            # boyut destegi degil). Resmi istemci (cloudflare/speedtest defaultConfig: 1e8) gibi Referer + Origin ile 100 MB istek.
            # Az istek = 429 (Retry-After ~1 saat) riski dusuk; 429 gelirse o akis durur.
            $sync.Phase = "Yurtiçi indirme (Cloudflare $colo) — hat yük altında..."
            $sync.Dom = LoadTest @("https://speed.cloudflare.com/__down?bytes=100000000") "down" 4 10 6e8 $(if ($icmp) { "1.1.1.1" } else { "" })

            # 4) Yurtdisi indirme: 3 farkli saglayici (tek sunucu yaniltmasin). Yuk altinda ping: Valve Frankfurt relay.
            $fraIp = ""; try { $fraIp = "$(@($cfg.pops.fra.relays)[0].ipv4)" } catch {}
            $intl = [ordered]@{}
            $srv = [ordered]@{
                "Hetzner Falkenstein (DE)" = "https://fsn1-speed.hetzner.com/100MB.bin"
                "Linode Frankfurt (DE)"    = "https://speedtest.frankfurt.linode.com/100MB-frankfurt.bin"
                "OVH Roubaix (FR)"         = "https://proof.ovh.net/files/100Mb.dat"
            }
            foreach ($nm in $srv.Keys) {
                $sync.Phase = "Yurtdışı indirme: $nm..."
                $intl[$nm] = LoadTest @($srv[$nm]) "down" 4 7 3e8 $(if ($icmp) { $fraIp } else { "" })
            }
            $sync.Intl = $intl

            # 5) Yukleme (Cloudflare) + yuk altinda ping
            $sync.Phase = "Yükleme testi (hat yük altında)..."
            $sync.Up = LoadTest @("https://speed.cloudflare.com/__up") "up" 3 9 3e8 $(if ($icmp) { "1.1.1.1" } else { "" })
            $sync.Phase = "Bitti"
        } catch { $sync.Err = "$($_.Exception.Message)" }
        $sync.Done = $true
    }

    $med = { param($a) $s = @($a | Where-Object { $null -ne $_ } | Sort-Object); if ($s.Count -eq 0) { return $null }; $m = [int][Math]::Floor($s.Count / 2); if ($s.Count % 2) { return [double]$s[$m] }; return ([double]$s[$m - 1] + [double]$s[$m]) / 2 }
    $stat = { param($a) $arr = @($a); if ($arr.Count -eq 0) { return @{ Med = 0; Min = 0; Jit = 0; P90 = 0 } }
        $s = @($arr | Sort-Object); $m = & $med $arr
        $d = 0; for ($i = 1; $i -lt $arr.Count; $i++) { $d += [Math]::Abs($arr[$i] - $arr[$i - 1]) }
        return @{ Med = [Math]::Round($m, 1); Min = [Math]::Round($s[0], 1); Jit = [Math]::Round($(if ($arr.Count -gt 1) { $d / ($arr.Count - 1) } else { 0 }), 1); P90 = [Math]::Round($s[[Math]::Min($s.Count - 1, [int][Math]::Floor(0.9 * ($s.Count - 1) + 0.5))], 1) } }
    $grade = { param($delta) if ($delta -le 5) { "A+" } elseif ($delta -le 30) { "A" } elseif ($delta -le 60) { "B" } elseif ($delta -le 200) { "C" } elseif ($delta -le 400) { "D" } else { "F" } }
    $loadHist = { try { $raw = (Get-ItemProperty -Path $script:NqHistKey -Name "NetTestHistory" -ErrorAction SilentlyContinue).NetTestHistory; if ($raw) { return @($raw | ConvertFrom-Json) } } catch {}; return @() }

    $script:NqTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:NqTimer.Interval = [TimeSpan]::FromMilliseconds(300)
    $script:NqTimer.Add_Tick({
        $sy = $script:NqSync
        if (-not $sy.Done) { $txtNqStatus.Text = "⏳ $($sy.Phase)   $($sy.Live)"; return }
        $script:NqTimer.Stop(); $btnNqStart.IsEnabled = $true
        if ($sy.Err) { $txtNqStatus.Text = "❌ Test tamamlanamadı: $($sy.Err)"; return }
        $vpn = @(); try { $vpn = @((Get-MrCleanVpnState).Connected) } catch {}
        $i = & $stat $sy.Idle.S; $dn = & $stat $sy.Dom.Pings; $up = & $stat $sy.Up.Pings
        $dDelta = if (@($sy.Dom.Pings).Count) { [Math]::Max(0, $dn.Med - $i.Med) } else { $null }
        $uDelta = if (@($sy.Up.Pings).Count) { [Math]::Max(0, $up.Med - $i.Med) } else { $null }
        $idleLoss = [Math]::Round(100.0 * $sy.Idle.Lost / [Math]::Max(1, $sy.Idle.N), 1)

        # Yurtdisi: sunucu bazli; en iyinin yarisindan dusuk kalan TEK sunucu "sunucu kaynakli" sayilip ayiklanir
        $intlRows = @(); $vals = @()
        foreach ($k in $sy.Intl.Keys) { $vals += [double]$sy.Intl[$k].Mbps }
        # 8. tur: ortanca tabanli — 3 sunucunun ortancasi tek kotu (ya da tek asiri iyi) sunucudan etkilenmez; ortancanin
        # yarisinin altinda kalan sunucu "sunucu kaynakli" diye bilgi olarak gosterilir (cogunluk asla ayiklanmaz)
        $okVals = @($vals | Where-Object { $_ -gt 0 })
        $medAll = if ($okVals.Count) { [double](& $med $okVals) } else { 0 }
        $outl = @()
        foreach ($k in $sy.Intl.Keys) { $v = [double]$sy.Intl[$k].Mbps; if ($v -le 0) { $outl += "$k (yanıt yok)" } elseif ($okVals.Count -ge 3 -and $v -lt 0.5 * $medAll) { $outl += ("{0} ({1} Mbps)" -f $k, $v) }; $intlRows += ("  {0,-26}: {1,7} Mbps" -f $k, $v) }
        $intlMed = [Math]::Round($medAll, 1)
        $iDn = $null; $allIntlPings = @(); foreach ($k in $sy.Intl.Keys) { $allIntlPings += @($sy.Intl[$k].Pings) }

        $R = $sy.Regions
        $rg = { param($key) if ($R -and $R.Contains($key) -and $null -ne $R[$key].Med) { "{0} ms" -f [Math]::Round($R[$key].Med) } else { "—" } }
        $valveBest = $null; $valveBestName = ""
        foreach ($pp in @(@("vie","Viyana"),@("fra","Frankfurt"),@("waw","Varşova"),@("ams","Amsterdam"),@("par","Paris"),@("sto","Stockholm"))) { $k = "valve_$($pp[0])"; if ($R -and $R.Contains($k) -and $null -ne $R[$k].Med -and ($null -eq $valveBest -or $R[$k].Med -lt $valveBest)) { $valveBest = $R[$k].Med; $valveBestName = $pp[1] } }
        $coloTxt = if ($sy.Colo -eq "IST") { "Cloudflare İstanbul" } elseif ($sy.Colo) { "Cloudflare $($sy.Colo) (YURTDIŞI!)" } else { "Cloudflare" }

        $lines = @()
        if ($vpn.Count) { $lines += "🔒 VPN BAĞLI: $($vpn -join ', ') — ölçümler VPN sunucusu üzerinden." }
        $lines += ("Boşta ping      : {0} ms (en düşük {1}, p90 {2}, dalgalanma {3} ms, kayıp %{4}){5}" -f $i.Med, $i.Min, $i.P90, $i.Jit, $idleLoss, $(if (-not $sy.Icmp) { " [TCP]" } else { "" }))
        $lines += ("Yurtiçi indirme : {0} Mbps  ({1})  yük altında ping +{2} ms → {3}" -f $sy.Dom.Mbps, $coloTxt, $(if ($null -ne $dDelta) { [Math]::Round($dDelta) } else { "?" }), $(if ($null -ne $dDelta) { & $grade $dDelta } else { "?" }))
        $lines += ("Yurtdışı indirme: {0} Mbps (sunucuların ortancası)" -f $intlMed)
        $lines += $intlRows
        $lines += ("Yükleme         : {0} Mbps  yük altında ping +{1} ms → {2}" -f $sy.Up.Mbps, $(if ($null -ne $uDelta) { [Math]::Round($uDelta) } else { "?" }), $(if ($null -ne $uDelta) { & $grade $uDelta } else { "?" }))
        $lines += ""
        $lines += "OYUN SUNUCUSU BÖLGELERİ (Türkiye'den tipik eşleşme):"
        $lines += ("  CS2 (Valve)          : Viyana {0} · Frankfurt {1} · Varşova {2} · Amsterdam {3}" -f (& $rg "valve_vie"), (& $rg "valve_fra"), (& $rg "valve_waw"), (& $rg "valve_ams"))
        $lines += ("  BF6 / BF2042 / PUBG  : AWS Frankfurt {0} (Milano {1})" -f (& $rg "aws_eu-central-1"), (& $rg "aws_eu-south-1"))
        $lines += ("  BF4 / BF1            : topluluk sunucuları, çoğu Almanya → Frankfurt {0}" -f (& $rg "aws_eu-central-1"))
        $lines += ("  Warzone (tahmini)    : Frankfurt {0} · Paris {1} · Londra {2}" -f (& $rg "aws_eu-central-1"), (& $rg "aws_eu-west-3"), (& $rg "aws_eu-west-2"))
        $lines += ("  Valorant / LoL TR    : İstanbul (AWS İstanbul) ≈ yurtiçi {0} ms" -f $i.Med)
        $lines += ("  Orta Doğu            : Dubai (Valve) {0} · AWS BAE {1}" -f (& $rg "valve_dxb"), (& $rg "aws_me-central-1"))
        $mbTot = $sy.Dom.MB + $sy.Up.MB; foreach ($k in $sy.Intl.Keys) { $mbTot += $sy.Intl[$k].MB }
        $lines += ""; $lines += "Kullanılan veri: ~$mbTot MB"
        $txtNqStatus.Text = ($lines -join "`n")

        # Gecmis (son 6 test) — kararlar TEK olcume degil ortancaya dayanir
        $hist = @(& $loadHist)
        $entry = [ordered]@{ T = (Get-Date).ToString("yyyy-MM-dd HH:mm"); Dom = $sy.Dom.Mbps; Intl = $intlMed; Up = $sy.Up.Mbps; Bd = $dDelta; Bu = $uDelta; Idle = $i.Med; Vpn = [bool]$vpn.Count; Colo = $sy.Colo }
        if (-not $vpn.Count) {
            $hist = @(@($hist) + @([pscustomobject]$entry) | Select-Object -Last 6)
            try { if (-not (Test-Path $script:NqHistKey)) { New-Item -Path $script:NqHistKey -Force | Out-Null }; Set-ItemProperty -Path $script:NqHistKey -Name "NetTestHistory" -Value (ConvertTo-Json @($hist) -Compress) -Type String -Force } catch {}
        }
        $hn = @($hist).Count
        $hDom = & $med @($hist | ForEach-Object { [double]$_.Dom }); $hUp = & $med @($hist | ForEach-Object { [double]$_.Up }); $hIntl = & $med @($hist | ForEach-Object { [double]$_.Intl })
        $bloatRuns = @($hist | Where-Object { ($null -ne $_.Bd -and $_.Bd -ge 60) -or ($null -ne $_.Bu -and $_.Bu -ge 60) }).Count

        $adv = New-Object System.Collections.Generic.List[string]
        if ($vpn.Count) { $adv.Add("🔒 VPN bağlıyken test edildi: hız ve ping VPN sunucusunun konumuna ve yüküne bağlıdır (WireGuard ile %10-30 hız kaybı ve +5-30 ms normaldir). Bu sonuç geçmişe KAYDEDİLMEDİ. Hattınızın gerçek değeri için VPN'i kısa süreliğine ayırıp tekrar test edin. MrClean VPN tünel kartına ve DNS'ine dokunmaz.") }
        if ($sy.Colo -and $sy.Colo -ne "IST" -and -not $vpn.Count) { $adv.Add("🌍 Cloudflare sizi İstanbul yerine '$($sy.Colo)' noktasına yönlendiriyor (ISS yönlendirmesi). Yurtiçi sanılan ölçüm aslında yurtdışı; bu bir PC ayarı değildir.") }
        try {
            $g = "$(& netsh int tcp show global 2>$null)"
            if ($g -match "(?:Auto-Tuning Level|Otomatik Ayar Düzeyi|Alma Penceresi Otomatik Ayarlama Düzeyi)\s*:\s*(\S+)" -and $Matches[1] -notmatch "(?i)normal") {
                $adv.Add("🔴 TCP otomatik pencere ayarı '$($Matches[1])' — özellikle yurtdışı ve 50 Mbps üstü hatlarda hızı ciddi SINIRLAR (genelde başka bir 'optimizasyon' aracının bıraktığı ayar). Tweaks > Ağ > '[SIFIRLA] Windows Varsayılanları' ile düzeltin.")
            }
        } catch {}
        try {
            # 12. tur: dinamik port araligi (sayilar dile gore degismez). Eski "MaxUserPort" tweakleri 1024'e indiriyor.
            $dp = "$(& netsh int ipv4 show dynamicport tcp 2>$null)"
            $dpNums = @([regex]::Matches($dp, ":\s*(\d+)") | ForEach-Object { [int]$_.Groups[1].Value })
            if ($dpNums.Count -ge 2 -and $dpNums[0] -ne 49152) {
                $adv.Add("🟠 TCP dinamik port aralığı $($dpNums[0])'dan başlıyor (Windows varsayılanı 49152). Hıza / pinge etkisi yoktur; ama eski bir 'MaxUserPort' optimizasyonunun kalıntısıdır ve WSL / Docker / Hyper-V'de 'port kullanımda' hatalarına yol açabilir. Tweaks > Ağ > '[SIFIRLA] Windows Varsayılanları' düzeltir.")
            }
        } catch {}
        # Yurtici / yurtdisi karsilastirmasi
        if ($outl.Count) { $adv.Add("ℹ️ Şu sunucu(lar) diğerlerinden çok yavaş kaldı (sonuç ortanca olduğu için etkilemez): $($outl -join ', '). Tek sunucunun o anki yoğunluğu/sorunudur, sizin hattınızla ilgili değildir.") }
        if ($sy.Dom.Mbps -gt 30 -and $intlMed -gt 0 -and $intlMed -lt 0.5 * $sy.Dom.Mbps -and $intlMed -ge 250) {
            $adv.Add(("🟢 Yurtdışı {0} Mbps (yurtiçi {1} Mbps). Gigabit hatlarda yurtdışı tek sunucudan bu değer normaldir: uzak sunucular bağlantı başına hız sınırlar ve 50+ ms mesafe tek bağlantıyı yavaşlatır. Oyun, Discord, yayın ve indirme için fazlasıyla yeterli — ISS darboğazı değil." -f $intlMed, $sy.Dom.Mbps))
        } elseif ($sy.Dom.Mbps -gt 30 -and $intlMed -gt 0 -and $intlMed -lt 0.5 * $sy.Dom.Mbps) {
            $adv.Add(("🟠 Yurtdışı hız ({0} Mbps) yurtiçinin ({1} Mbps) yarısından düşük." -f $intlMed, $sy.Dom.Mbps) + " Bu, ISS'nin yurtdışı çıkış kapasitesidir (özellikle akşam 20-24 arası yoğunluk) — Windows ayarıyla düzelmez. Farklı saatte tekrar test edin; hep böyleyse ISS'ye 'yurtdışı hız' şikâyeti açın. Oyunda asıl önemli olan hız değil ping ve kayıptır (aşağıdaki bölge pingleri).")
        } elseif ($intlMed -gt 0) {
            $adv.Add(("🟢 Yurtdışı hız yurtiçiyle uyumlu ({0} / {1} Mbps)" -f $intlMed, $sy.Dom.Mbps) + " — ISS yurtdışı çıkışında darboğaz görünmüyor.")
        }
        # Bufferbloat — gecmise gore
        $mx = [Math]::Max([double]$(if ($null -ne $dDelta) { $dDelta } else { 0 }), [double]$(if ($null -ne $uDelta) { $uDelta } else { 0 }))
        if ($mx -ge 60) {
            $sure = if ($bloatRuns -ge 2) { "Son $hn testin $bloatRuns tanesinde tekrarlandı — KALICI." } else { "Tek ölçüm: farklı bir saatte 1-2 kez daha test edin; tekrarlanırsa kalıcıdır." }
            $sqmD = if ($hDom) { [Math]::Round($hDom * 0.85) } else { [Math]::Round($sy.Dom.Mbps * 0.85) }
            $sqmU = if ($hUp) { [Math]::Round($hUp * 0.85) } else { [Math]::Round($sy.Up.Mbps * 0.85) }
            $adv.Add("🟠 Bufferbloat: hat dolunca ping +$([Math]::Round($mx)) ms artıyor. $sure Oyun + Discord + YouTube/Spotify birlikteyken yaşanan ping sıçramasının nedeni budur ve kaynağı modemin kuyruğudur (PC ayarıyla çözülmez). ÇÖZÜM: modem/router'da SQM / Akıllı QoS (CAKE / fq_codel) açın, hız sınırını ölçülenin ~%85'ine girin → indirme ≈ $sqmD Mbps, yükleme ≈ $sqmU Mbps (son testlerin ortancasına göre). Bu, uygulama önceliği vermeden TÜM uygulamalar için hattı dengeler. Ek: 'Windows Update Arka Plan İndirme Hızını Sınırla' tweak'i; Steam/Battle.net/EA indirme limitini açın.")
            if ($null -ne $uDelta -and $null -ne $dDelta -and $uDelta -gt $dDelta + 30) { $adv.Add("   • Yükleme yönü daha kötü: düşük yüklemeli hatlarda (ADSL/VDSL) Discord ekran paylaşımı, bulut yedekleme ve yayın ping'i en çok bozan şeylerdir.") }
        } elseif ($mx -ge 30) {
            $adv.Add("🟡 Hafif bufferbloat (+$([Math]::Round($mx)) ms). Arka planda büyük indirme olmadıkça oyunda hissedilmez.")
        } else {
            $adv.Add("🟢 Yük altında gecikme artışı çok düşük (A/A+). Hattınız oyun + Discord + müzik/YouTube'u birlikte rahat kaldırır.")
        }
        # Oyun bolgeleri yorumu
        if ($null -ne $valveBest) { $adv.Add("🎮 CS2 için en yakın Valve noktası: $valveBestName (~$([Math]::Round($valveBest)) ms). Battlefield 6 / 2042 / PUBG Türkiye'den AWS Frankfurt'a bağlanır (~$(& $rg 'aws_eu-central-1')); Türkiye'de BF / CS2 / Warzone sunucusu yoktur, 45-65 ms bu oyunlar için normaldir.") }
        if ($R -and $R.Contains("valve_dxb") -and $null -ne $R["valve_dxb"].Med -and $null -ne $valveBest -and $R["valve_dxb"].Med -gt $valveBest + 60) { $adv.Add("⚠️ Orta Doğu (Dubai) Türkiye'den daha uzak yönlendiriliyor ($(& $rg 'valve_dxb')). Oyunlarda bölge seçimi varsa Avrupa (Frankfurt / Viyana) seçin; 'en yakın ülke' mantığı burada yanıltıcı.") }
        # Kayip / dalgalanma / Wi-Fi / kablo
        if ($idleLoss -ge 2) { $adv.Add("🔴 Boştayken bile paket kaybı %$idleLoss. Kablo/modem/ISS hattını kontrol edin (modemi yeniden başlatın, kabloyu değiştirin); sürerse ISS arızası.") }
        if ($i.Jit -ge 5) { $adv.Add("🟡 Boştayken ping dalgalanıyor ($($i.Jit) ms). Genelde Wi-Fi parazitidir ya da modem/ISS kaynaklıdır.") }
        $act = $null
        try { $act = Get-MrCleanPhysicalAdapters | Where-Object { "$($_.Status)" -eq "Up" } | Sort-Object { if ($_.InterfaceType -eq 6) { 0 } else { 1 } } | Select-Object -First 1 } catch {}
        if ($act -and $act.InterfaceType -eq 71) { $adv.Add("📶 Wi-Fi ile bağlısınız. Oyunda en kararlı sonuç kablodur. Kablo yoksa Tweaks > Wi-Fi altındaki '5 GHz tercih' / 'Dolaşımı azalt' (kartınız destekliyorsa) yardımcı olur.") }
        try {
            if ($act -and $act.InterfaceType -eq 6) {
                $link = [double]$act.ReceiveLinkSpeed / 1e6
                if ($link -gt 0 -and $sy.Dom.Mbps -ge 0.85 * $link) { $adv.Add("🔌 Ölçülen hız ağ kartının bağlantı hızına ($([Math]::Round($link)) Mbps) dayanmış. Hattınız daha hızlıysa darboğaz kablo/modem portu (Cat6 kablo, modemde 2.5G port).") }
                elseif ($link -gt 0 -and $link -le 100) { $adv.Add("🔌 Ethernet sadece $([Math]::Round($link)) Mbps ile bağlı. Hattınız 100 Mbps üstündeyse kablo (4 damarlı / hasarlı) ya da port sorunludur.") }
            }
        } catch {}
        try {
            $vi = @((Get-MrCleanVpnState).Installed) -join " "
            if ($vi -match "(?i)mullvad" -and (@(Get-MrCleanDnsGuard) -join " ") -match "(?i)WinDivert|GoodbyeDPI|zapret") {
                $adv.Add("ℹ️ Mullvad + GoodbyeDPI/zapret (WinDivert) birlikte kurulu. Normal VPN kullanımında sorun çıkarmazlar; ancak Mullvad'ın kendi belgesine göre GoodbyeDPI, Mullvad'ın 'Split tunneling' (bazı uygulamaları VPN dışında tutma) özelliğini bozabilir. O özelliği kullanacaksanız GoodbyeDPI'ı geçici durdurun. MrClean ikisinin de servisine/sürücüsüne dokunmaz.")
            }
        } catch {}
        try {
            if ((@(Get-MrCleanDnsGuard) -join " ") -match "(?i)WinDivert") {
                $adv.Add("🎮 WinDivert sürücüsü (GoodbyeDPI / zapret) yüklü: Call of Duty Warzone / BO6-7 (Ricochet) ve PUBG hile koruması bu sürücüyü görünce oyunu AÇTIRMAZ — paket ayarlarından bağımsız, sürücü yüklü olması yeterli (servisi durdurmak da çoğu zaman yetmez, yeniden başlatma gerekir). Discord için sürücüsüz yöntem: ByeDPI (yerel proxy) + discord-drover (sadece Discord'u proxy'den geçirir) — örn. SplitWire-Turkey'in 'ByeDPI DLL (Drover)' modu. MrClean bu araçlara dokunmaz.")
            }
        } catch {}
        if ($hn -ge 2) { $adv.Add("📊 Son $hn testin ortancası: yurtiçi $([Math]::Round($hDom)) Mbps · yurtdışı $([Math]::Round($hIntl)) Mbps · yükleme $([Math]::Round($hUp)) Mbps. Öneriler tek ölçüme değil bu ortancaya göredir.") }
        $adv.Add("ℹ️ Hız bazlı elle ayar YAPILMAZ ve bu test hiçbir ayarı değiştirmez: Windows TCP otomatik ayarı 10 Mbps'ten 10 Gbps'e kadar her hıza ve her mesafeye (İstanbul 15 ms, Frankfurt 55 ms) kendiliğinden uyum sağlar. Hat kapasitesinin tamamını oyun + Discord + müzik arasında dengeli kullanmanın doğru yolu uygulama önceliği değil, modemde SQM'dir.")
        $txtNqAdvice.Text = ($adv -join "`n`n")
    })

    $btnNqStart.Add_Click({
        $vpnNow = @(); try { $vpnNow = @((Get-MrCleanVpnState).Connected) } catch {}
        if ($vpnNow.Count) {
            $a = [System.Windows.MessageBox]::Show("VPN bağlı: $($vpnNow -join ', ')`n`nTest VPN sunucusu üzerinden ölçer (hattınızın gerçek değeri değil) ve sonuç geçmişe kaydedilmez. Yine de devam edilsin mi?", "Ağ Kalite Testi", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Information)
            if ($a -ne 'Yes') { return }
        }
        $btnNqStart.IsEnabled = $false; $txtNqAdvice.Text = ""
        $script:NqSync.Done = $false; $script:NqSync.Err = ""; $script:NqSync.Live = ""; $script:NqSync.Phase = "Başlıyor..."
        $rs = [runspacefactory]::CreateRunspace(); $rs.Open()
        $script:NqPS = [powershell]::Create(); $script:NqPS.Runspace = $rs
        [void]$script:NqPS.AddScript($worker).AddArgument($script:NqSync)
        [void]$script:NqPS.BeginInvoke()
        $script:NqTimer.Start()
    })
    $btnNqClear.Add_Click({ try { Remove-ItemProperty -Path $script:NqHistKey -Name "NetTestHistory" -ErrorAction SilentlyContinue } catch {}; $txtNqAdvice.Text = "Test geçmişi silindi." })
    $btnNqClose.Add_Click({ $w.Close() })
    $w.Add_Closed({ try { $script:NqTimer.Stop() } catch {}; try { $script:NqPS.Stop(); $script:NqPS.Dispose() } catch {} })
    try { $w.Owner = $Win } catch {}
    [void]$w.ShowDialog()
}

