    # ADClip8: kazanc 0, tavan -1 dBFS — sadece mikrofonun zaten kirptigi tepelerde devreye girer.
    Clip = @(0.0, 0.4308, 0.0)
    BrowserUA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0 Safari/537.36"
}

# Zip icindeki TEK dosyayi HTTP Range ile alir (merkez dizin okunur; 37 MB zip yerine sadece gereken eklenti). SHA-256 verilirse dogrular.
function Install-MrCleanZipMember([string]$Url, [string]$Member, [string]$Dest, [string]$Sha256 = "", [string]$UA = "MrClean") {
    if (Test-Path $Dest) { return $true }
    $get = {
        param([long]$a, [long]$b)
        $rq = [System.Net.HttpWebRequest]::Create($Url); $rq.UserAgent = $UA; $rq.Timeout = 60000; $rq.ReadWriteTimeout = 60000
        if ($a -ge 0) { $rq.AddRange($a, $b) } else { $rq.Method = "HEAD" }
        $rs = $rq.GetResponse()
        if ($a -lt 0) { $len = $rs.ContentLength; $rs.Close(); return $len }
        $ms = New-Object IO.MemoryStream; $rs.GetResponseStream().CopyTo($ms); $rs.Close(); return ,$ms.ToArray()
    }
    try {
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
        $len = [long](& $get -1 -1)
        $ts = [Math]::Max(0, $len - 262144); $tail = [byte[]](& $get $ts ($len - 1))
        $eocd = -1; for ($i = $tail.Length - 22; $i -ge 0; $i--) { if ([BitConverter]::ToUInt32($tail, $i) -eq 0x06054b50) { $eocd = $i; break } }
        if ($eocd -lt 0) { throw "zip dizini bulunamadi" }
        $cdSize = [BitConverter]::ToUInt32($tail, $eocd + 12); $cdOff = [long][BitConverter]::ToUInt32($tail, $eocd + 16)
        $cd = if ($cdOff -ge $ts) { [byte[]]$tail[($cdOff - $ts)..($cdOff - $ts + $cdSize - 1)] } else { [byte[]](& $get $cdOff ($cdOff + $cdSize - 1)) }
        $pos = 0; $hit = $null
        while ($pos -lt $cd.Length - 46 -and [BitConverter]::ToUInt32($cd, $pos) -eq 0x02014b50) {
            $nl = [BitConverter]::ToUInt16($cd, $pos + 28); $xl = [BitConverter]::ToUInt16($cd, $pos + 30); $cl = [BitConverter]::ToUInt16($cd, $pos + 32)
            $nm = [Text.Encoding]::UTF8.GetString($cd, $pos + 46, $nl)
            if ($nm -eq $Member -or $nm -like "*/$Member" -or ($nm -split "/")[-1] -eq $Member) {
                $hit = @{ Method = [BitConverter]::ToUInt16($cd, $pos + 10); CSize = [BitConverter]::ToUInt32($cd, $pos + 20); USize = [BitConverter]::ToUInt32($cd, $pos + 24); Off = [long][BitConverter]::ToUInt32($cd, $pos + 42) }
                break
            }
            $pos += 46 + $nl + $xl + $cl
        }
        if (-not $hit) { throw "$Member zip icinde yok" }
        $blk = [byte[]](& $get $hit.Off ($hit.Off + 30 + 2048 + $hit.CSize))
        if ([BitConverter]::ToUInt32($blk, 0) -ne 0x04034b50) { throw "yerel baslik hatali" }
        $ds = 30 + [BitConverter]::ToUInt16($blk, 26) + [BitConverter]::ToUInt16($blk, 28)
        $raw = New-Object byte[] $hit.CSize; [Array]::Copy($blk, $ds, $raw, 0, $hit.CSize)
        $data = $raw
        if ($hit.Method -eq 8) { $in = New-Object IO.MemoryStream(, $raw); $z = New-Object IO.Compression.DeflateStream($in, [IO.Compression.CompressionMode]::Decompress); $o = New-Object IO.MemoryStream; $z.CopyTo($o); $z.Close(); $data = $o.ToArray() }
        elseif ($hit.Method -ne 0) { throw "desteklenmeyen sikistirma ($($hit.Method))" }
        if ($data.Length -ne $hit.USize -or $data[0] -ne 0x4D -or $data[1] -ne 0x5A) { throw "dosya dogrulanamadi" }
        if ($Sha256) {
            $h = [BitConverter]::ToString((New-Object Security.Cryptography.SHA256Managed).ComputeHash($data)).Replace("-", "")
            if ($h -ne $Sha256.ToUpper()) { throw "SHA-256 uyusmuyor (test edilen surum degil)" }
        }
        $dir = Split-Path -Parent $Dest; if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        [IO.File]::WriteAllBytes($Dest, $data)
        Write-MrCleanAudioLog ("{0} kuruldu ({1:N0} KB)." -f (Split-Path -Leaf $Dest), ($data.Length / 1KB))
        return $true
    } catch { Write-MrCleanAudioLog "$(Split-Path -Leaf $Dest) alinamadi: $($_.Exception.Message)"; return $false }
}

# Mikrofon zinciri bilesenleri: secilen gurultu motoru + Airwindows (DeEss / Logical4 / ADClip8)
function Install-MrCleanMicComponents([string]$Engine) {
    $C = $global:MrCleanMicConst
    $inst = Get-MrCleanEapoInstallDir; if (-not $inst) { return }
    $vst = Join-Path $inst "VSTPlugins"
    foreach ($f in $C.AwFiles) { [void](Install-MrCleanZipMember $C.AwUrl $f (Join-Path $vst $f) "" $C.BrowserUA) }
    if ($Engine -eq "rnnoise") { [void](Install-MrCleanZipMember $C.RnnUrl $C.RnnMember (Join-Path $vst $C.RnnFile) $C.RnnSha) }
    if ($Engine -eq "dfn") { Write-MrCleanAudioLog "DeepFilterNet3 indiriliyor (~10-30 MB)..."; [void](Install-MrCleanZipMember $C.DfnUrl $C.DfnMember (Join-Path $vst $C.DfnFile) $C.DfnSha) }
}

# Aygit bicimi (Windows Ses Ayarlari > Bicim): ornekleme hizi ve kanal sayisi (PKEY_AudioEngine_DeviceFormat blob)
function Get-MrCleanEndpointFormat([string]$Flow, [string]$Guid) {
    try {
        $p = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\$Flow\{$($Guid.Trim('{}'))}\Properties" -ErrorAction Stop
        $b = $p.'{f19f064d-082c-4e27-bc73-6882a1bb8e4c},0'
        if ($b -and $b.Length -ge 24) { return @{ Rate = [int][BitConverter]::ToUInt32($b, 12); Channels = [int][BitConverter]::ToUInt16($b, 10) } }
    } catch {}
    return @{ Rate = 0; Channels = 0 }
}

# Mikrofon turu: headset (kulaklik / boom / Bluetooth / 3.5 mm), desk (USB masaustu), laptop (dahili dizi / webcam)
function Get-MrCleanMicType($Dev) {
    $t = "$($Dev.Name) $($Dev.Desc)"
    if ($Dev.Bus -match "(?i)BTH" -or $t -match "(?i)hands-free|headset|kulakl|arctis|cloud|blackshark|kraken|virtuoso|\bhs\d{2}|g ?pro|pro x|inzone|maxwell|airpods|stealth|nova|barracuda|astro") { return "headset" }
    if ($t -match "(?i)array|dizi|camera|kamera|webcam|brio|c9\d\d|kiyo|facecam|integrated|dahili") { return "laptop" }
    if ($Dev.Bus -match "(?i)USB" -and $t -notmatch "(?i)realtek") { return "desk" }
    return "headset"
}

function Get-MrCleanDfnChunk([int]$AttenDb) {
    $xml = '<?xml version="1.0" encoding="UTF-8"?> <PARAMETERS uiLanguage="en"><PARAM id="attenLimDb" value="' + ([double]$AttenDb).ToString("0.0", [Globalization.CultureInfo]::InvariantCulture) + '"/><PARAM id="postFilterBeta" value="0.0"/><PARAM id="reduceMask" value="2.0"/></PARAMETERS>'
    $xb = [Text.Encoding]::UTF8.GetBytes($xml); $ms = New-Object IO.MemoryStream
    $ms.Write([byte[]](0x56, 0x43, 0x32, 0x21), 0, 4); $ms.Write([BitConverter]::GetBytes([uint32]($xb.Length + 1)), 0, 4); $ms.Write($xb, 0, $xb.Length); $ms.WriteByte(0)
    return [Convert]::ToBase64String($ms.ToArray())
}

# Mikrofon / ortam testi: bip -> 5 sn SESSIZ (oda gurultusu) -> bip -> 5 sn EN YUKSEK SES (kirpilma). RAW kayit.
# Gercek kayit + eklenen klima / fan testi (2026-10): arka plani ~-70 dBFS altina indiren EN DUSUK bastirma secilir; gucu artirmak
# gurultulu odada sesi neredeyse hic ek bozmuyor (0.1-0.7 dB), sessiz odada gereksiz.
function Measure-MrCleanMicEnvironment([string]$FullId) {
    if (-not (Initialize-MrCleanAudioNative)) { return $null }
    $db = { param($v) 20 * [Math]::Log10([Math]::Max($v, 1e-9)) }
    try { [Console]::Beep(880, 250) } catch {}
    Write-MrCleanAudioLog "1/2: SESSIZ kalin (5 sn) - oda gurultusu olculuyor..."
    $r = 0; $a = [MrCleanAudioV2.Capture]::Record($FullId, 5.0, [ref]$r)
    try { [Console]::Beep(1320, 250) } catch {}
    Write-MrCleanAudioLog "2/2: EN YUKSEK sesinizle konusun / bagirin (5 sn)..."
    $b = [MrCleanAudioV2.Capture]::Record($FullId, 5.0, [ref]$r)
    try { [Console]::Beep(660, 400) } catch {}
    if ($a.Length -lt 1000 -or $b.Length -lt 1000) { Write-MrCleanAudioLog "Kayit alinamadi (mikrofon bagli / izinli mi?)."; return $null }
    $fs = [Math]::Max(1, [int]($r / 100)); $fr = New-Object System.Collections.Generic.List[double]
    for ($i = [int]($r * 0.5); $i + $fs -le $a.Length; $i += $fs) { $s = 0.0; for ($j = $i; $j -lt $i + $fs; $j++) { $s += $a[$j] * $a[$j] }; $fr.Add([Math]::Sqrt($s / $fs)) }
    $srt = @($fr | Sort-Object); $floor = & $db $srt[[int]($srt.Count * 0.5)]        # sessizlikte ortanca kare = oda gurultusu
    $pk = 0.0; $clip = 0; $s2 = 0.0; foreach ($v in $b) { $x = [Math]::Abs($v); if ($x -gt $pk) { $pk = $x }; if ($x -ge 0.989) { $clip++ }; $s2 += $v * $v }
    $att = if ($floor -le -60) { 20 } elseif ($floor -le -50) { 30 } else { 40 }
    return @{ Floor = [Math]::Round($floor, 1); Peak = [Math]::Round((& $db $pk), 1); Clip = $clip; Loud = [Math]::Round((& $db ([Math]::Sqrt($s2 / $b.Length))), 1); Atten = $att; Rate = $r }
}

function ConvertTo-MrCleanFloatChunk([double[]]$Vals) {
    $ms = New-Object IO.MemoryStream
    foreach ($v in $Vals) { $b = [BitConverter]::GetBytes([float]$v); $ms.Write($b, 0, 4) }
    return [Convert]::ToBase64String($ms.ToArray())
}

# Mikrofon aygit dosyasi satirlari
function Get-MrCleanMicChainLines($Pl, $Settings) {
    $C = $global:MrCleanMicConst
    $inst = Get-MrCleanEapoInstallDir; $vst = if ($inst) { Join-Path $inst "VSTPlugins" } else { "" }
    $has = { param($f) $vst -and (Test-Path (Join-Path $vst $f)) }
    $type = if ($Pl.MicType -in @("headset", "desk", "laptop")) { $Pl.MicType } else { Get-MrCleanMicType $Pl.Dev }
    $fmt = Get-MrCleanEndpointFormat "Capture" $Pl.Dev.Guid
    $hp = @{ headset = 100; desk = 80; laptop = 120 }[$type]
    $l = @("# Mikrofon ($type) - $($Pl.Dev.Name) ($($Pl.Dev.Desc)) - $($fmt.Rate) Hz / $($fmt.Channels) kanal" -replace "[^\x20-\x7E]", "")
    if ($fmt.Channels -eq 2) { $l += "Copy: L=0.5*L+0.5*R R=0.5*L+0.5*R" }      # iki kanal ayni karari versin (EAPO kanal basina ayri ornek acar)
    $l += "Preamp: 0 dB"
    $l += ("Filter: ON HPQ Fc {0} Hz Q 0.5412" -f $hp); $l += ("Filter: ON HPQ Fc {0} Hz Q 1.3066" -f $hp)    # 24 dB/oktav: ugultu + P/B patlamasi
    $eng = "$($Settings.MicEngine)"; $note = ""
    $rnnOk = (& $has $C.RnnFile) -and ($fmt.Rate -eq 48000)
    $dfnOk = (& $has $C.DfnFile)
    $useDfn = ($eng -eq "dfn" -and $dfnOk) -or ($eng -eq "rnnoise" -and -not $rnnOk -and $dfnOk)
    $useRnn = -not $useDfn -and $eng -in @("rnnoise", "dfn") -and $rnnOk
    if ($useRnn) { $l += "VSTPlugin: Library `"$($C.RnnFile)`" ChunkData `"$($C.RnnChunk)`"" }
    elseif ($useDfn) { $att = if ([int]$Settings.MicAtten -ge 10) { [int]$Settings.MicAtten } else { 30 }; $l += "VSTPlugin: Library `"$($C.DfnFile)`" ChunkData `"$(Get-MrCleanDfnChunk $att)`"" }
    elseif ($eng -ne "off") { $note = $(if ($fmt.Rate -ne 48000 -and (& $has $C.RnnFile)) { "gurultu bastirma YOK: aygit $($fmt.Rate) Hz (RNNoise 48 kHz ister) - 'Guclu' secin ya da Ses Ayarlari > mikrofon > Bicim: 48000 Hz" } else { "gurultu bastirma bileseni yok" }) }
    $l += @(Get-MrCleanAudioCurve "mic_$type" 0 | ForEach-Object { Format-MrCleanEqFilter $_ })
    if (& $has "ADClip864.dll") { $l += "VSTPlugin: Library `"ADClip864.dll`" ChunkData `"$(ConvertTo-MrCleanFloatChunk $C.Clip)`"" }
    return @{ Lines = $l; Note = $note; Type = $type; Engine = $(if ($useRnn) { "RNNoise" } elseif ($useDfn) { "DeepFilterNet3 $(if ([int]$Settings.MicAtten -ge 10) { [int]$Settings.MicAtten } else { 30 }) dB" } else { "yok" }) }
}

function Write-MrCleanAudioLog([string]$m) {
    if ($global:MrCleanAudioSync) { [void]$global:MrCleanAudioSync.Log.Add($m) } else { try { WpfLog "[Ses] $m" } catch {} }
}

function Get-MrCleanEapoInstallDir {
    $p = $null
    try { $p = (Get-ItemProperty -Path "HKLM:\SOFTWARE\EqualizerAPO" -Name "InstallPath" -ErrorAction SilentlyContinue).InstallPath } catch {}
    if (-not $p) { $p = Join-Path $env:ProgramFiles "EqualizerAPO" }
    if (Test-Path (Join-Path $p "EqualizerAPO.dll")) { return $p }
    return $null
}

function Get-MrCleanEapoConfigDir {
    $p = $null
    try { $p = (Get-ItemProperty -Path "HKLM:\SOFTWARE\EqualizerAPO" -Name "ConfigPath" -ErrorAction SilentlyContinue).ConfigPath } catch {}
    if (-not $p) { $p = Join-Path $env:ProgramFiles "EqualizerAPO\config" }
    if (Test-Path $p) { return $p }
    return $null
}

function Initialize-MrCleanAudioNative {
    if ("MrCleanAudioV2.Native" -as [type]) { return $true }
    try {
        Add-Type -ReferencedAssemblies System.Core -TypeDefinition @'
using System; using System.Collections.Generic; using System.IO; using System.IO.Pipes; using System.Runtime.InteropServices;
using System.Security.AccessControl; using System.Security.Principal; using System.Text; using System.Threading;
namespace MrCleanAudioV2 {
  [ComImport, Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IMMDeviceEnumerator { [PreserveSig] int EnumAudioEndpoints(int f, int m, out IntPtr c); [PreserveSig] int GetDefaultAudioEndpoint(int f, int r, out IMMDevice d); [PreserveSig] int GetDevice([MarshalAs(UnmanagedType.LPWStr)] string id, out IMMDevice d); }
  [ComImport, Guid("D666063F-1587-4E43-81F1-B948E807363F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IMMDevice { [PreserveSig] int Activate(ref Guid iid, int ctx, IntPtr p, [MarshalAs(UnmanagedType.IUnknown)] out object o); [PreserveSig] int OpenPropertyStore(int a, out IntPtr s); [PreserveSig] int GetId([MarshalAs(UnmanagedType.LPWStr)] out string id); [PreserveSig] int GetState(out int s); }
  [ComImport, Guid("1CB9AD4C-DBFA-4c32-B178-C2F568A703B2"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioClient { [PreserveSig] int Initialize(int share, int flags, long dur, long period, IntPtr fmt, IntPtr session); [PreserveSig] int GetBufferSize(out uint n); [PreserveSig] int GetStreamLatency(out long l); [PreserveSig] int GetCurrentPadding(out uint p); [PreserveSig] int IsFormatSupported(int m, IntPtr f, out IntPtr c); [PreserveSig] int GetMixFormat(out IntPtr f); }
  [ComImport, Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")] class MMDeviceEnumeratorCo {}
  [ComImport, Guid("726778CD-F60A-4eda-82DE-E47610CD78AA"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioClient2 {
    [PreserveSig] int Initialize(int share, int flags, long dur, long period, IntPtr fmt, IntPtr session);
    [PreserveSig] int GetBufferSize(out uint n); [PreserveSig] int GetStreamLatency(out long l); [PreserveSig] int GetCurrentPadding(out uint p);
    [PreserveSig] int IsFormatSupported(int m, IntPtr f, out IntPtr c); [PreserveSig] int GetMixFormat(out IntPtr f); [PreserveSig] int GetDevicePeriod(out long d, out long m);
    [PreserveSig] int Start(); [PreserveSig] int Stop(); [PreserveSig] int Reset(); [PreserveSig] int SetEventHandle(IntPtr h);
    [PreserveSig] int GetService(ref Guid iid, [MarshalAs(UnmanagedType.IUnknown)] out object o);
    [PreserveSig] int IsOffloadCapable(int cat, out int cap); [PreserveSig] int SetClientProperties(ref ClientProps p);
  }
  [StructLayout(LayoutKind.Sequential)] struct ClientProps { public uint cbSize; public int bIsOffload; public int eCategory; public int Options; }
  [ComImport, Guid("C8ADBD64-E71E-48a0-A4DE-185C395CD317"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioCaptureClient { [PreserveSig] int GetBuffer(out IntPtr data, out uint frames, out uint flags, out ulong pos, out ulong qpc); [PreserveSig] int ReleaseBuffer(uint frames); [PreserveSig] int GetNextPacketSize(out uint n); }
  // Mikrofon testi: RAW modda (Windows / uretici efektleri atlanir) mono float kayit
  public static class Capture {
    public static float[] Record(string fullId, double seconds, out int rate) {
      rate = 0; var e = (IMMDeviceEnumerator)(new MMDeviceEnumeratorCo()); IMMDevice d; if (e.GetDevice(fullId, out d) != 0) return new float[0];
      Guid iid = new Guid("726778CD-F60A-4eda-82DE-E47610CD78AA"); object o; if (d.Activate(ref iid, 23, IntPtr.Zero, out o) != 0) return new float[0];
      var c = (IAudioClient2)o; var pr = new ClientProps { cbSize = 16, Options = 1 }; c.SetClientProperties(ref pr);
      IntPtr fmt; if (c.GetMixFormat(out fmt) != 0) return new float[0];
      int tag = Marshal.ReadInt16(fmt, 0), ch = Marshal.ReadInt16(fmt, 2), bits = Marshal.ReadInt16(fmt, 14), align = Marshal.ReadInt16(fmt, 12); rate = Marshal.ReadInt32(fmt, 4);
      bool isFloat = (tag == 3) || (tag == unchecked((short)0xFFFE) && bits == 32 && Marshal.ReadInt16(fmt, 24) == 3);
      if (c.Initialize(0, 0, 10000000, 0, fmt, IntPtr.Zero) != 0) { Marshal.FreeCoTaskMem(fmt); return new float[0]; }
      Guid ic = new Guid("C8ADBD64-E71E-48a0-A4DE-185C395CD317"); object co; c.GetService(ref ic, out co); var cap = (IAudioCaptureClient)co;
      var outp = new List<float>((int)(rate * seconds) + rate); c.Start(); var sw = System.Diagnostics.Stopwatch.StartNew();
      while (sw.Elapsed.TotalSeconds < seconds) { Thread.Sleep(10); uint n;
        while (cap.GetNextPacketSize(out n) == 0 && n > 0) { IntPtr data; uint frames, flags; ulong p1, p2; cap.GetBuffer(out data, out frames, out flags, out p1, out p2);
          for (int i = 0; i < frames; i++) { double s = 0; for (int k = 0; k < ch; k++) { int off = i * align + k * (bits / 8);
              if ((flags & 2) != 0) continue; if (isFloat) s += BitConverter.ToSingle(BitConverter.GetBytes(Marshal.ReadInt32(data, off)), 0); else if (bits == 16) s += Marshal.ReadInt16(data, off) / 32768.0; else s += Marshal.ReadInt32(data, off) / 2147483648.0; }
            outp.Add((float)(s / ch)); }
          cap.ReleaseBuffer(frames); } }
      c.Stop(); Marshal.FreeCoTaskMem(fmt); return outp.ToArray();
    }
  }
  public static class Native {
    public static string DefaultIdRole(int flow, int role) {
      try { var e = (IMMDeviceEnumerator)(new MMDeviceEnumeratorCo()); IMMDevice d; if (e.GetDefaultAudioEndpoint(flow, role, out d) != 0 || d == null) return null; string id; d.GetId(out id); return id; } catch { return null; }
    }
    public static string DefaultId(int flow) {
      try { var e = (IMMDeviceEnumerator)(new MMDeviceEnumeratorCo()); IMMDevice d; if (e.GetDefaultAudioEndpoint(flow, 1, out d) != 0 || d == null) return null; string id; d.GetId(out id); return id; } catch { return null; }
    }
    // EAPO DeviceAPOInfo::testAPOInstallation ile ayni: paylasimli modda Initialize -> APO yuklenir
    public static int OpenShared(string fullId) {
      IntPtr fmt = IntPtr.Zero; object o = null;
      try {
        var e = (IMMDeviceEnumerator)(new MMDeviceEnumeratorCo()); IMMDevice d; int hr = e.GetDevice(fullId, out d); if (hr != 0) return hr;
        Guid iid = new Guid("1CB9AD4C-DBFA-4c32-B178-C2F568A703B2"); hr = d.Activate(ref iid, 23, IntPtr.Zero, out o); if (hr != 0) return hr;
        var c = (IAudioClient)o; hr = c.GetMixFormat(out fmt); if (hr != 0) return hr;
        return c.Initialize(0, 0, 1000000, 0, fmt, IntPtr.Zero);
      } catch (Exception ex) { return Marshal.GetHRForException(ex); }
      finally { if (fmt != IntPtr.Zero) Marshal.FreeCoTaskMem(fmt); if (o != null) { try { Marshal.ReleaseComObject(o); } catch {} } }
    }
    // EAPO, DeviceTestPipeName ayarliyken her APO baslangicinda {"deviceGuid":..,"stage":..,"phase":..} yazar
    public static string[] ProbeEapo(string pipeName, string[] fullIds, int waitMs) {
      var got = new List<string>(); object sync = new object(); bool stop = false; var threads = new List<Thread>();
      for (int k = 0; k < 4; k++) {
        var t = new Thread(() => {
          while (!stop) {
            try {
              var sec = new PipeSecurity();
              sec.AddAccessRule(new PipeAccessRule(new SecurityIdentifier(WellKnownSidType.WorldSid, null), PipeAccessRights.ReadWrite, AccessControlType.Allow));
              using (var srv = new NamedPipeServerStream(pipeName, PipeDirection.In, NamedPipeServerStream.MaxAllowedServerInstances, PipeTransmissionMode.Byte, PipeOptions.Asynchronous, 4096, 0, sec)) {
                var ar = srv.BeginWaitForConnection(null, null);
                while (!ar.AsyncWaitHandle.WaitOne(100)) { if (stop) return; }
                srv.EndWaitForConnection(ar);
                var ms = new MemoryStream(); var buf = new byte[4096]; var sw = System.Diagnostics.Stopwatch.StartNew();
                while (sw.ElapsedMilliseconds < 1500) { var rr = srv.BeginRead(buf, 0, buf.Length, null, null); if (!rr.AsyncWaitHandle.WaitOne(1500)) break; int n = srv.EndRead(rr); if (n <= 0) break; ms.Write(buf, 0, n); }
                lock (sync) got.Add(Encoding.UTF8.GetString(ms.ToArray()));
              }
            } catch { Thread.Sleep(50); }
          }
        });
        t.IsBackground = true; t.Start(); threads.Add(t);
      }
      Thread.Sleep(250);
      foreach (var id in fullIds) { try { OpenShared(id); } catch {} }
      Thread.Sleep(waitMs); stop = true;
      foreach (var t in threads) t.Join(1500);
      lock (sync) return got.ToArray();
    }
  }
}
'@ -ErrorAction Stop
        return $true
    } catch { Write-MrCleanAudioLog "Ses API yuklenemedi: $($_.Exception.Message)"; return $false }
}

# Windows uzamsal ses (Dolby Atmos / Windows Sonic / DTS) — WinRT ile okunur. Bu Windows ayari programla KAPATILAMAZ
# (Microsoft: formatin sahibi uygulama degistirebilir); MrClean aygitin ses ayar sayfasini acar.
function Get-MrCleanSpatialFormat([string]$Guid) {
    $map = @{ "B53D940C-B846-4831-9F76-D102B9B725A0" = "Windows Sonic"; "1459AC38-3875-49BF-BB59-0FE80F4D395D" = "Dolby Atmos (Kulaklık)"
              "A289735D-FA3E-4E35-9D7D-B6F896ACB2E7" = "Dolby Atmos (Ev Sineması)"; "4C81E564-C8EF-4AD9-9F2C-9EF995533790" = "Dolby Atmos (Hoparlör)"
              "4444ACB0-8DC0-4C2C-A0D8-2C76DB470F86" = "DTS Headphone:X"; "ADAFD3C6-AC4C-404A-836A-9615E9060564" = "DTS:X Ultra"; "10201B4A-3322-4967-BF40-2CAA9BAFCA44" = "DTS:X (Ev Sineması)" }
    try {
        $null = [Windows.Media.Audio.SpatialAudioDeviceConfiguration, Windows.Media.Audio, ContentType = WindowsRuntime]
        $id = "\\?\SWD#MMDEVAPI#{0.0.0.00000000}.$($Guid.ToLower())#{e6327cad-dcec-4949-ae8a-991e976a79d2}"
        $c = [Windows.Media.Audio.SpatialAudioDeviceConfiguration]::GetForDeviceId($id)
        $f = "$($c.ActiveSpatialAudioFormat)".Trim("{}").ToUpper()
        if ($f -and $f -ne "00000000-0000-0000-0000-000000000000") { if ($map.ContainsKey($f)) { return $map[$f] }; return "Uzamsal ses ($f)" }
    } catch {}
    return ""
}

# Ses aygitlari (aktif + takili olmayan jak). Kind: Headphones / Speaker / Mic / Virtual / Digital / HandsFree
function Get-MrCleanAudioDevices([switch]$NoSpatial) {
    $C = $global:MrCleanEapoConst
    [void](Initialize-MrCleanAudioNative)
    $defR = $null; $defC = $null
    $defComm = $null
    try { $defR = [MrCleanAudioV2.Native]::DefaultId(0); $defC = [MrCleanAudioV2.Native]::DefaultId(1); $defComm = [MrCleanAudioV2.Native]::DefaultIdRole(0, 2) } catch {}
    $out = @()
    foreach ($flow in @("Render", "Capture")) {
        foreach ($k in @(Get-ChildItem "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\$flow" -ErrorAction SilentlyContinue)) {
            $st = (Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue).DeviceState
            if ($st -ne 1 -and $st -ne 8) { continue }
            $g = $k.PSChildName.ToLower()
            $pr = Get-ItemProperty "$($k.PSPath)\Properties" -ErrorAction SilentlyContinue
            $name = "$($pr.'{a45c254e-df1c-4efd-8020-67d146a850e0},2')"; $desc = "$($pr.'{b3f8fa53-0004-438e-9003-51a46e139bfc},6')"
            $ff = $pr.'{1da5d803-d492-4edd-8c23-e0c0ffee7f0e},0'; $bus = "$($pr.'{a45c254e-df1c-4efd-8020-67d146a850e0},24')"
            $fxPath = "$($k.PSPath)\FxProperties"; $fx = Get-ItemProperty $fxPath -ErrorAction SilentlyContinue
            $eapo = $false; $vendor = @()
            if ($fx) {
                foreach ($s in @($C.L, $C.G, $C.S, $C.M, $C.E, $C.S13, $C.M14, $C.E15)) {
                    $v = "$($fx.$s)"; if (-not $v) { continue }
                    if ($v -match [regex]::Escape($C.PreMix.Trim("{}")) -or $v -match [regex]::Escape($C.PostMix.Trim("{}"))) { $eapo = $true; continue }
                    $fn = ""
                    try { $fn = (Get-ItemProperty "Registry::HKEY_CLASSES_ROOT\AudioEngine\AudioProcessingObjects\$v" -ErrorAction SilentlyContinue).FriendlyName } catch {}
                    if (-not $fn) { try { $fn = Split-Path -Leaf ((Get-ItemProperty "Registry::HKEY_CLASSES_ROOT\CLSID\$v\InprocServer32" -ErrorAction SilentlyContinue).'(default)') } catch {} }
                    if ($fn -and $fn -notmatch "(?i)^Microsoft|^WM |WMALFXGFXDSP|^AudioEndpoint|^$") { $vendor += $fn }   # Windows in kendi varsayilan efektleri sayilmaz
                }
            }
            $isDef = [bool](($flow -eq "Render" -and $defR -and $defR -like "*$g*") -or ($flow -eq "Capture" -and $defC -and $defC -like "*$g*"))
            $isComm = [bool]($flow -eq "Render" -and $defComm -and $defComm -like "*$g*")
            $kind = "Speaker"
            $txt = "$name $desc"
            if ($flow -eq "Capture") { $kind = "Mic" }
            elseif ($txt -match "(?i)sonar|virtual|voicemeeter|vb-audio|cable (in|out)|broadcast|steam streaming|oculus|nahimic mirroring|wave link") { $kind = "Virtual" }
            elseif ($bus -match "(?i)BTHHFENUM" -or $txt -match "(?i)hands-free|eller serbest|headset earphone") { $kind = "HandsFree" }
            elseif ($ff -eq 8) { $kind = "Digital" }
            elseif ($ff -in @(3, 5)) { $kind = "Headphones" }
            elseif ($txt -match "(?i)\bchat\b|sohbet|communication") { $kind = "Voice" }     # kulaklik sohbet kanali (Arctis / INZONE / Maxwell Game + Chat)
            elseif ($txt -match "(?i)arctis|cloud ?(ii|iii|alpha|flight|stinger|mix)|blackshark|kraken|barracuda|nari|virtuoso|\bhs\d{2}|void|g ?pro|pro x|astro a\d|inzone|maxwell|airpods|stealth|recon|quantum|h\d{3}|wh-1000|bose|sennheiser|beyerdynamic|hyperx|corsair hs|yeti|quadcast|wave:\d|snowball") { $kind = "Headphones" }   # USB mikrofonlarin kulaklik cikisi da kulaklik
            $out += [pscustomobject]@{ Flow = $flow; Guid = $g; FullId = $(if ($flow -eq "Render") { "{0.0.0.00000000}.$g" } else { "{0.0.1.00000000}.$g" })
                Name = $name; Desc = $desc; FormFactor = $ff; Bus = $bus; State = $st; HasFx = [bool]$fx; Eapo = $eapo
                Vendor = (@($vendor | Select-Object -Unique) -join ", "); Combined = [bool]($null -ne $pr.($C.Combined)); Default = $isDef; Comm = $isComm; Kind = $kind; Spatial = "" }
        }
    }
    foreach ($d in @($out | Where-Object { $_.Comm -and -not $_.Default -and $_.Kind -eq "Headphones" })) {
        if (@($out | Where-Object { $_.Default -and $_.Desc -eq $d.Desc }).Count -gt 0) { $d.Kind = "Voice" }
    }
    foreach ($d in $out) {
        if ($d.Kind -eq "Speaker" -and $d.FormFactor -eq 9 -and -not $NoSpatial) { $d.Spatial = Get-MrCleanSpatialFormat $d.Guid; if ($d.Spatial -match "Kulakl|Sonic|Headphone") { $d.Kind = "Headphones" } }
        elseif ($d.Flow -eq "Render" -and $d.Kind -in @("Headphones", "Speaker") -and -not $NoSpatial) { $d.Spatial = Get-MrCleanSpatialFormat $d.Guid }
    }
    return @($out | Sort-Object Flow, @{ e = { -not $_.Default } }, Name)
}

# --- AutoEq ---
function Get-MrCleanAutoEqIndex([switch]$Offline) {
    if ($global:MrCleanAutoEqIndex) { return $global:MrCleanAutoEqIndex }
    $dir = Join-Path $env:LOCALAPPDATA "MrClean"; $f = Join-Path $dir "autoeq_index.md"
    try {
        if (-not $Offline -and (-not (Test-Path $f) -or ((Get-Date) - (Get-Item $f).LastWriteTime).TotalDays -gt 14)) {
            if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
            try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
            $wc = New-Object System.Net.WebClient; $wc.Headers.Add("User-Agent", "MrClean"); $wc.Encoding = [Text.Encoding]::UTF8
            [IO.File]::WriteAllText($f, $wc.DownloadString("https://raw.githubusercontent.com/jaakkopasanen/AutoEq/master/results/INDEX.md"), (New-Object Text.UTF8Encoding($false)))
        }
        if (-not (Test-Path $f)) { return @() }
        $list = New-Object System.Collections.Generic.List[object]
        foreach ($ln in [IO.File]::ReadAllLines($f)) {
            if ($ln -match "^- \[(.+?)\]\(\./(.+?)\)\s+by\s+(.*)$") { $list.Add([pscustomobject]@{ Name = $Matches[1]; Rel = $Matches[2]; Src = $Matches[3] }) }
        }
        $global:MrCleanAutoEqIndex = $list
        return $list
    } catch { Write-MrCleanAudioLog "AutoEq listesi alinamadi: $($_.Exception.Message)"; return @() }
}

# Aygit adindan AutoEq modeli: tum anlamli kelimeler eslesmeli. Kaynak onceligi oratory1990 > crinacle > 5128 > Rtings;
# Bluetooth aygitta Bluetooth olcumu, kablolu / 2.4 GHz te "(wired)" tercih edilir. Tek kelimelik adlar (orn. "Yeti") eslenmez.
function Find-MrCleanAutoEqMatch([string]$Text, [bool]$Bluetooth, $Index) {
    $t = ($Text -replace "\([^)]*\)", " ") -replace "(?i)\b(headphones?|headset|earphones?|speakers?|hoparl\w*|kulakl\w*|game|chat|stereo|hands-free|audio|usb|gaming|digital|output|device|high definition|realtek|nvidia|amd|intel)\b", " " -replace "(?i)2\.4\s*ghz|2\.4g", " " -replace "[^\w\s\-+]", " "
    $tok = @($t.ToLower() -split "\s+" | Where-Object { $_.Length -ge 2 } | Select-Object -Unique)
    if ($tok.Count -lt 2) { return $null }
    $best = $null; $bs = -999
    foreach ($e in $Index) {
        $n = $e.Name.ToLower(); $ok = $true
        foreach ($w in $tok) { if ($n -notmatch ("(^|[^a-z0-9])" + [regex]::Escape($w) + "([^a-z0-9]|$)")) { $ok = $false; break } }
        if (-not $ok) { continue }
        $sc = 100 - 3 * ([Math]::Max(0, [regex]::Matches($n, "[a-z0-9]+").Count - $tok.Count))
        if ($e.Src -match "^oratory1990") { $sc += 30 } elseif ($e.Src -match "^crinacle") { $sc += 20 } elseif ($e.Src -match "5128") { $sc += 12 } elseif ($e.Src -match "^Rtings") { $sc += 8 }
        if ($Bluetooth) { if ($n -match "bluetooth") { $sc += 15 }; if ($n -match "anc off") { $sc += 3 } }
        else { if ($n -match "bluetooth") { $sc -= 40 }; if ($n -match "wired") { $sc += 10 } }
        if ($n -match "anc on") { $sc -= 5 }
        if ($sc -gt $bs) { $bs = $sc; $best = $e }
    }
    return $best
}

function Get-MrCleanAutoEqFilters([string]$Rel, [switch]$Offline) {
    $dir = Join-Path $env:LOCALAPPDATA "MrClean\autoeq"
    $name = [uri]::UnescapeDataString(($Rel -split "/")[-1])
    $cache = Join-Path $dir (($Rel -replace "[^\w\-]", "_") + ".txt")
    $txt = $null
    if (Test-Path $cache) { $txt = [IO.File]::ReadAllText($cache) }
    elseif (-not $Offline) {
        try {
            if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
            try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
            $wc = New-Object System.Net.WebClient; $wc.Headers.Add("User-Agent", "MrClean"); $wc.Encoding = [Text.Encoding]::UTF8
            $txt = $wc.DownloadString("https://raw.githubusercontent.com/jaakkopasanen/AutoEq/master/results/$Rel/" + [uri]::EscapeDataString("$name ParametricEQ.txt"))
            [IO.File]::WriteAllText($cache, $txt, (New-Object Text.UTF8Encoding($false)))
        } catch { Write-MrCleanAudioLog "AutoEq profili indirilemedi ($name): $($_.Exception.Message)"; return @() }
    }
    if (-not $txt) { return @() }
    $fl = @(); foreach ($ln in ($txt -split "`r?`n")) { $p = ConvertFrom-MrCleanEqLine $ln; if ($p) { $fl += $p } }
    return $fl
}

# --- Karakter egrileri (8. tur arastirmasi: Harman tercihi + rekabetci FPS + soundbar guvenligi + temiz mikrofon) ---
# Kulaklik modlari AutoEq (Harman hedefi, ~+6 dB bas zaten icinde) USTUNE uygulanir:
#  balanced : gunluk — hafif sicak bas, 220 Hz camur -1, 2.8 kHz netlik +1.5, 6.8 kHz sertlik -1
#  music    : derin bas — 105 Hz raf +Bas (vars. 3.5 dB; Harman "daha fazla bas" grubu), 45 Hz alt bas +1, 10 kHz -1 (yorgunluk yok)
#  game     : HIBRIT (oyun + arkada muzik ayni EQ dan gecer) — atmosfer KORUNUR (alt bas dokunulmaz — patlama / mesafe hissi), 220 Hz camur -2, 2.8 kHz adim / sarjor +2.5,
#             6.8 kHz dar sertlik -1.5, 10 kHz yukseklik / on-arka ipucu +0.5 (4-10 kHz pinna bolgesi OYULMAZ)
function Get-MrCleanAudioCurve([string]$Id, [double]$Bass) {
    $spec = @()
    switch ($Id) {
        # v1.3.0 (10. tur) SICAK TON: gercek muzik kaydinda (YouTube, loopback, Arctis Nova Pro) AutoEq (Harman) + Dengeli, saf Dolby ye gore
        # 80-315 Hz -2..-4.9 dB ince, 1.25-8 kHz +1.2..+4.2 dB parlakti ("bas ve vokal zayif"). Fark AutoEq in hedefinden (her kulaklik ayni
        # hedefe duzeltilir) geldigi icin TUM kulakliklara genellenir: govde 150 Hz +6 (Q 0.8), "Harman bagirmasi" 3.6 kHz -4.2 (Q 0.6).
        # Ikinci kayitta tum bantlar Dolby ye +-1.4 dB. SADECE Dengeli ve Muzik: Oyun modu ayak sesi bandini (1.5-6 kHz) korur.
        "balanced" { $spec = @(@("LSC",105,2.0,0.71), @("PK",150,6.0,0.8), @("PK",220,-1.0,0.9), @("PK",2800,1.5,1.1), @("PK",3600,-4.2,0.6), @("PK",6800,-1.0,3.0)) }
        "music"    { $spec = @(@("LSC",105,$Bass,0.71), @("PK",45,1.0,0.8), @("PK",150,6.0,0.8), @("PK",3600,-4.2,0.6), @("HSC",10000,-1.0,0.7)) }
        # Oyun (hibrit): BF6 RedSec videosu, gercek loopback (120 sn) saf Dolby ile: adim bandi (1.5-6 kHz) sakin anda +6.2 dB, catismada
        # adim / patlama orani +8.5 dB daha iyi, vurus keskinligi ayni — ama 80-250 Hz -4..-6 dB (adim "tok" degil, ince) ve 3-5 kHz +4..+5
        # (uzun oyunda yorucu). -> 150 Hz +3.5 (adim govdesi; 30-60 Hz patlama gumbursu yine Dolby nin altinda), 3.6 kHz -2 (adim bandi
        # Dolby nin hala +2..+3 dB ustunde).
        # Kullanici geri bildirimi (gercek BF6 oyunu): "adim bir tik daha belirgin, bas bir tik daha, tiz kacinca bas agrisi" ->
        # 150 Hz +4.5 (tokluk), 7 kHz ustu -2 (yorgunluk bandi; adim bandi 1.5-3.5 kHz e dokunmaz). Belirginlik tiz ile DEGIL oyun
        # dengeleyicisiyle (LevGame) verilir.
        "game"     { $spec = @(@("PK",150,4.5,0.8), @("PK",220,-2.0,0.9), @("PK",2800,2.5,1.1), @("PK",3600,-2.0,0.6), @("PK",6800,-1.5,3.0), @("HSC",7000,-2.0,0.7), @("HSC",10000,0.5,0.7)) }
        # ranked: patlama / ugultu rafi -4 dB (80 Hz), hareket 1.5 kHz +1.5, adim 3.3 kHz +3 (genis Q — ates sesiyle ayni bant, asiri degil),
        # sarjor 6 kHz +1.5, tiz rafi -1.5 (yorgunluk yok). Arkadaki muzik ince kalir — bu yuzden varsayilan degil.
        "competitive" { $spec = @(@("LSC",80,-4.0,0.7), @("PK",1500,1.5,1.2), @("PK",3300,3.0,1.2), @("PK",6000,1.5,2.0), @("HSC",10000,-1.5,0.7)) }
        # Soundbar / hoparlor: kullanicinin Leviathan V2 X inde loopback ile OLCULEN Dolby Atmos profiline gore (2026-10):
        # Dolby = ~+3.5 dB seviye, 63-250 Hz ortalara gore ~+2 dB sicak bas, 10 kHz ustu ~-3.5 dB yumusak tiz, 40 Hz e dokunmaz.
        # HP 50 Hz: kucuk surucunun uretemedigi en alt bas zorlanmaz. Seviye (+3 dB fazladan yukseltme) Write-MrCleanAudioConfig te.
        "speaker"  { $spec = @(@("HP",50,0,0.71), @("LSC",480,4.0,0.7), @("HSC",5400,-2.0,0.7)) }
        # sesli sohbet kanali: konusma bandi net (3 kHz +2), boğukluk (250 Hz) ve sert "s" (7 kHz) yumusak, ugultu kesik; moda gore DEGISMEZ
        "voice"    { $spec = @(@("HP",70,0,0.71), @("PK",250,-1.5,1.0), @("PK",3000,2.0,1.2), @("PK",7000,-1.5,3.0)) }
        # mikrofon turune gore (HP ayrica, bastirmadan once): kulaklik ince / sert -> govde +2, 3 kHz -2.5, 6.5 kHz -2, 12 kHz ustu kesik;
        # masaustu oda / yakinlik -> 250 Hz -3, 3.5 kHz +2, 7 kHz -2, hava +1.5; dizustu / webcam -> 300 Hz -3, 900 Hz -2, 3 kHz +2, 10 kHz ustu kesik
        "mic_headset" { $spec = @(@("PK",180,1.0,0.9), @("PK",3000,-1.25,1.4), @("PK",6500,-1.0,2.0), @("LPQ",12000,0,0.707)) }
        "mic_desk"    { $spec = @(@("PK",250,-1.5,1.0), @("PK",3500,1.0,1.0), @("PK",7000,-1.0,3.0), @("HSC",10000,0.75,0.7)) }
        "mic_laptop"  { $spec = @(@("PK",300,-2.0,1.0), @("PK",900,-1.0,1.4), @("PK",3000,1.5,1.0), @("LPQ",10000,0,0.707)) }
        "mic"      { $spec = @(@("HP",90,0,0.71), @("PK",250,-2.0,1.0), @("PK",4000,2.0,1.0), @("PK",7500,-1.5,3.0)) }
    }
    $out = foreach ($x in $spec) { if ($x[0] -in @("HP", "LPQ") -or [Math]::Abs([double]$x[2]) -ge 0.05) { [pscustomobject]@{ T = [string]$x[0]; F = [double]$x[1]; G = [double]$x[2]; Q = [double]$x[3] } } }
    return @($out)
}

function Format-MrCleanEqFilter($f) {
    $ic = [Globalization.CultureInfo]::InvariantCulture
    if ($f.T -eq "HP") { return ("Filter: ON HP Fc {0} Hz" -f $f.F.ToString("0.##", $ic)) }
    if ($f.T -in @("HPQ", "LPQ")) { return ("Filter: ON {0} Fc {1} Hz Q {2}" -f $f.T, $f.F.ToString("0.##", $ic), $f.Q.ToString("0.0###", $ic)) }
    return ("Filter: ON {0} Fc {1} Hz Gain {2} dB Q {3}" -f $f.T, $f.F.ToString("0.##", $ic), $f.G.ToString("0.0#", $ic), $f.Q.ToString("0.0##", $ic))
}

# --- EAPO aygit kurulumu (DeviceAPOInfo::install birebir) ---
# FxProperties ACL i: Administrators = SetValue + ReadKey (CreateSubKey YOK). Set-ItemProperty anahtari daha genis haklarla
# acmaya calisip "erisim engellendi" alir (ve hata sessiz gecer) — gercek kurulumda yakalandi. EAPO Device Selector gibi sadece
# SetValue + ReadKey ile acilir; DeleteValue da KEY_SET_VALUE ile calisir.
function Set-MrCleanFxValue([string]$FxPath, [string]$Name, $Value, [string]$Kind = "String") {
    $sub = $FxPath -replace '^HKLM:\\', ''
    $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($sub, [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree, ([System.Security.AccessControl.RegistryRights]::SetValue -bor [System.Security.AccessControl.RegistryRights]::ReadKey))
    if (-not $k) { throw "FxProperties acilamadi: $sub" }
    try { if ($null -eq $Value) { $k.DeleteValue($Name, $false) } else { $k.SetValue($Name, $Value, [Microsoft.Win32.RegistryValueKind]$Kind) } } finally { $k.Close() }
}

function Install-MrCleanEapoDevice($Dev, [string]$Mode = "") {
    $C = $global:MrCleanEapoConst
    $flowKey = if ($Dev.Flow -eq "Capture") { "Capture" } else { "Render" }
    $ep = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\$flowKey\{$($Dev.Guid.Trim('{}'))}"
    $fx = "$ep\FxProperties"
    if (-not (Test-Path $fx)) { return "" }      # FxProperties yok: EAPO GUI anahtar sahipligini alir; MrClean bu riski almaz
    $root = "HKLM:\SOFTWARE\EqualizerAPO\Child APOs"; $child = "$root\{$($Dev.Guid.Trim('{}'))}"
    if (Test-Path $child) { Uninstall-MrCleanEapoDevice $Dev.Guid $flowKey }      # EAPO reinstall(): once eski hale, sonra kur
    $p = Get-ItemProperty $fx -ErrorAction SilentlyContinue
    $slots = @($C.L, $C.G, $C.S, $C.M, $C.E)
    $isEapo = { param($v) "$v" -eq $C.PreMix -or "$v" -eq $C.PostMix }
    if (-not (Test-Path $child)) {
        New-Item -Path $child -Force | Out-Null
        foreach ($s in $slots) { $v = $p.$s; if ($null -eq $v -or (& $isEapo $v)) { $v = "!VALUE" }; Set-ItemProperty -Path $child -Name $s -Value "$v" -Type String -Force }
        $sf = $p.($C.SysFx); Set-ItemProperty -Path $child -Name "MrCleanSysFx" -Value $(if ($null -eq $sf) { "!VALUE" } else { "$sf" }) -Type String -Force
    }
    $orig = Get-ItemProperty $child -ErrorAction SilentlyContinue
    $has = { param($n) $v = "$($orig.$n)"; $v -and $v -ne "!VALUE" -and $v -ne "!KEY" }
    if (-not $Mode) {
        $Mode = "SFX_EFX"
        $newSlots = (& $has $C.S) -or (& $has $C.M) -or (& $has $C.E) -or ($null -ne $p.($C.S13)) -or ($null -ne $p.($C.M14)) -or ($null -ne $p.($C.E15))
        if (((& $has $C.L) -or (& $has $C.G)) -and -not $newSlots) { $Mode = "LFX_GFX" }
        elseif ($Dev.Combined) { $Mode = "SFX_MFX" }
    }
    # Uretici APO lari (Dolby / Nahimic / Sonic Studio / G HUB surround ...) zincirde TUTULMAZ: PreMixChild / PostMixChild bos
    Set-ItemProperty -Path $child -Name "PreMixChild" -Value "" -Type String -Force
    Set-ItemProperty -Path $child -Name "PostMixChild" -Value "" -Type String -Force
    Set-ItemProperty -Path $child -Name "AllowSilentBufferModification" -Value "false" -Type String -Force
    Remove-ItemProperty -Path $child -Name "DisableAutomaticAdjustment" -ErrorAction SilentlyContinue
    Set-ItemProperty -Path $child -Name "Version" -Value "2" -Type String -Force
    Set-ItemProperty -Path $child -Name "MrCleanMode" -Value $Mode -Type String -Force
    $isCap = ($flowKey -eq "Capture")
    $del = { param($n) Set-MrCleanFxValue $fx $n $null }
    $pm = { param($n) if ($null -eq (Get-ItemProperty -Path $fx -Name $n -ErrorAction SilentlyContinue)) { Set-MrCleanFxValue $fx $n ([string[]]@($C.PmDefault)) "MultiString"
                $a = "$((Get-ItemProperty -Path $child -Name 'MrCleanPmAdded' -ErrorAction SilentlyContinue).MrCleanPmAdded)"
                Set-ItemProperty -Path $child -Name "MrCleanPmAdded" -Value (@(@($a -split "\|") + $n | Where-Object { $_ } | Select-Object -Unique) -join "|") -Type String -Force } }
    switch ($Mode) {
        "LFX_GFX" {
            Set-MrCleanFxValue $fx $C.L $C.PreMix
            if (-not $isCap) { Set-MrCleanFxValue $fx $C.G $C.PostMix }
            & $del $C.S; & $del $C.M; & $del $C.E
        }
        "SFX_MFX" {
            & $del $C.L; & $del $C.G
            Set-MrCleanFxValue $fx $C.S $C.PreMix; & $pm $C.PmS
            if (-not $isCap) { Set-MrCleanFxValue $fx $C.M $C.PostMix; & $pm $C.PmM }
        }
        default {
            & $del $C.L; & $del $C.G
            Set-MrCleanFxValue $fx $C.S $C.PreMix; & $pm $C.PmS
            if (-not $isCap) { Set-MrCleanFxValue $fx $C.E $C.PostMix; & $pm $C.PmE }
        }
    }
    # 10. tur: MIKROFONDA ureticinin MFX / EFX efekti (Logitech Blue VO!CE, Realtek ses iyilestirme vb.) EAPO dan SONRA calismaya devam
    # ediyordu (gercek Yeti X kurulumunda goruldu: EFX = Blue VO!CE). MrClean temizligiyle cift islem -> robotik ses. Orijinal deger
    # Child APOs yedeginde, Uninstall geri yazar.
    if ($isCap -and $Mode -ne "LFX_GFX") { & $del $C.M; & $del $C.E }
    & $del $C.SysFx      # "Ses gelistirmeleri kapali" isareti EAPO yu da kapatir -> EAPO gibi kaldirilir
    # Geri okuma: yazilan yuva gercekten EAPO mu? (sessiz yazma hatasi bir daha gozden kacmasin)
    $chk = Get-ItemProperty $fx -ErrorAction SilentlyContinue
    $slot = if ($Mode -eq "LFX_GFX") { $C.L } else { $C.S }
    if ("$($chk.$slot)" -ne $C.PreMix) { Write-MrCleanAudioLog "$($Dev.Name): FxProperties yazilamadi ($slot = '$($chk.$slot)')."; return "" }
    return $Mode
}

# 15. tur: APO CLSID gercekten kayitli mi (InprocServer32 + DLL var). "" = saglam; dolu = neden.
# Kaldirilmis bir ureticinin (G HUB / Blue VO!CE / Nahimic) ya da Equalizer APO nun efektini gosteren yuva, ses motorunun o aygiti
# acamamasina -> SESSIZ aygita yol acar (arkadas PC: G933 secili ama ses gelmiyor; bu PC: Yeti X iki kayitsiz CLSID).
function Test-MrCleanApoClsid([string]$Clsid) {
    $c = "$Clsid".Trim()
    if ($c -notmatch '^\{[0-9A-Fa-f\-]{36}\}$') { return "gecersiz deger" }
    $ip = "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Classes\CLSID\$c\InprocServer32"
    if (-not (Test-Path $ip)) { return "kayitli degil" }
    $dll = [Environment]::ExpandEnvironmentVariables("$((Get-ItemProperty $ip -ErrorAction SilentlyContinue).'(default)')").Trim('"')
    if ($dll -and -not [IO.Path]::IsPathRooted($dll)) { $dll = Join-Path "$env:WINDIR\System32" $dll }
    if (-not $dll -or -not (Test-Path $dll)) { return "DLL yok" }
    return ""
}

# Tum etkin ses aygitlarinda kayitsiz / kaldirilmis efekt (APO) gosteren yuvalari temizler. Varsayilan aygita dokunmaz.
# Kayitsiz bir APO zaten yuklenemez; kaydi silmek aygiti ancak duzeltir (Windows kendi varsayilan isleme yoluna doner).
function Repair-MrCleanAudioEndpoints {
    $C = $global:MrCleanEapoConst
    $eapoOk = [bool](Get-MrCleanEapoInstallDir)
    $slots = @(1, 2, 5, 6, 7, 13, 14, 15) | ForEach-Object { "{d04e05a6-594b-4fb6-a80d-01af5eed7d1d},$_" }
    $n = 0
    foreach ($flow in "Render", "Capture") {
        foreach ($d in @(Get-ChildItem "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\$flow" -ErrorAction SilentlyContinue)) {
            if ((Get-ItemProperty $d.PSPath -ErrorAction SilentlyContinue).DeviceState -ne 1) { continue }
            $fx = "$($d.PSPath)\FxProperties"; if (-not (Test-Path $fx)) { continue }
            $fxp = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\$flow\$($d.PSChildName)\FxProperties"
            $p = Get-ItemProperty $fx -ErrorAction SilentlyContinue
            $nm = "$((Get-ItemProperty "$($d.PSPath)\Properties" -ErrorAction SilentlyContinue).'{a45c254e-df1c-4efd-8020-67d146a850e0},2')"
            foreach ($s in $slots) {
                $v = $p.$s; if ($null -eq $v) { continue }
                $list = @($v | ForEach-Object { "$_" } | Where-Object { $_ })
                $keep = @($list | Where-Object { -not (Test-MrCleanApoClsid $_) -and ($eapoOk -or ($_ -ne $C.PreMix -and $_ -ne $C.PostMix)) })
                if ($keep.Count -eq $list.Count) { continue }
                try {
                    if ($keep.Count -eq 0) { Set-MrCleanFxValue $fxp $s $null }
                    elseif ($v -is [array]) { Set-MrCleanFxValue $fxp $s ([string[]]$keep) "MultiString" }
                    else { Set-MrCleanFxValue $fxp $s ([string]$keep[0]) }
                    $n++; Write-MrCleanAudioLog "$nm : kaldirilmis bir programin efekt kaydi temizlendi ($($s.Split(',')[1]). yuva)."
                } catch { Write-MrCleanAudioLog "$nm : efekt kaydi temizlenemedi ($($_.Exception.Message))." }
            }
        }
    }
    return $n
}

function Restart-MrCleanAudioService {
    $deps = @(); try { $deps = @((Get-Service Audiosrv).DependentServices | Where-Object { "$($_.Status)" -eq "Running" } | ForEach-Object { $_.Name }) } catch {}
    try { Restart-Service -Name Audiosrv -Force -ErrorAction Stop } catch { Write-MrCleanAudioLog "Ses servisi yeniden baslatilamadi: $($_.Exception.Message)"; return }
    foreach ($d in $deps) { try { Start-Service -Name $d -ErrorAction SilentlyContinue } catch {} }
}

function Uninstall-MrCleanEapoDevice([string]$Guid, [string]$Flow) {
    $C = $global:MrCleanEapoConst
    $g = "{$($Guid.Trim('{}'))}"
    $child = "HKLM:\SOFTWARE\EqualizerAPO\Child APOs\$g"
    if (-not (Test-Path $child)) { return }
    $fx = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\$Flow\$g\FxProperties"
    $o = Get-ItemProperty $child -ErrorAction SilentlyContinue
    if ("$($o.($C.L))" -ne "!KEY" -and (Test-Path $fx)) {
        foreach ($s in @($C.L, $C.G, $C.S, $C.M, $C.E)) {
            $v = "$($o.$s)"
            if ($v -eq "!VALUE" -or -not $v -or $v -eq $C.PreMix -or $v -eq $C.PostMix) { Set-MrCleanFxValue $fx $s $null }
            elseif (Test-MrCleanApoClsid $v) { Set-MrCleanFxValue $fx $s $null; Write-MrCleanAudioLog "$g : orijinal efekt ($v) artik sistemde yok (program kaldirilmis) - geri yazilmadi." }
            else { Set-MrCleanFxValue $fx $s $v }
        }
        $sf = "$($o.MrCleanSysFx)"
        if ($sf -and $sf -ne "!VALUE") { try { Set-MrCleanFxValue $fx $C.SysFx ([int]$sf) "DWord" } catch {} }
        foreach ($n in @("$($o.MrCleanPmAdded)" -split "\|" | Where-Object { $_ })) { Set-MrCleanFxValue $fx $n $null }
    }
    Remove-Item -Path $child -Recurse -Force -ErrorAction SilentlyContinue
    $root = "HKLM:\SOFTWARE\EqualizerAPO\Child APOs"
    if ((Test-Path $root) -and -not (Get-ChildItem $root -ErrorAction SilentlyContinue)) { Remove-Item $root -Force -ErrorAction SilentlyContinue }
}

# Ses servisini (bagimli servisleriyle) yeniden baslatir ve EAPO yu test borusuyla dogrular. Doner: calisan GUID listesi.
function Test-MrCleanEapoDevices($Devs) {
    if (-not (Initialize-MrCleanAudioNative)) { return @() }
    $deps = @(); try { $deps = @((Get-Service Audiosrv).DependentServices | Where-Object { "$($_.Status)" -eq "Running" } | ForEach-Object { $_.Name }) } catch {}
    Write-MrCleanAudioLog "Ses servisi yeniden baslatiliyor (2-3 sn ses kesilir)..."
    try { Restart-Service -Name Audiosrv -Force -ErrorAction Stop } catch { Write-MrCleanAudioLog "Ses servisi yeniden baslatilamadi: $($_.Exception.Message)"; return @() }
    foreach ($d in $deps) { try { Start-Service -Name $d -ErrorAction SilentlyContinue } catch {} }
    Start-Sleep -Milliseconds 800
    $pipe = "MrCleanEapoTest$(Get-Random)"
    Set-ItemProperty -Path "HKLM:\SOFTWARE\EqualizerAPO" -Name "DeviceTestPipeName" -Value $pipe -Type String -Force
    $msgs = @()
    try { $msgs = @([MrCleanAudioV2.Native]::ProbeEapo($pipe, [string[]]@($Devs | Where-Object { $_.State -eq 1 } | ForEach-Object { $_.FullId }), 3000)) }
    finally { Remove-ItemProperty -Path "HKLM:\SOFTWARE\EqualizerAPO" -Name "DeviceTestPipeName" -ErrorAction SilentlyContinue }
    $ok = @()
    foreach ($m in $msgs) { if ($m -match '"deviceGuid"\s*:\s*"\{?([0-9a-fA-F\-]{36})') { $ok += $Matches[1].ToLower() } }
    return @($ok | Select-Object -Unique)
}

# --- Indirme / kurulum ---
function Install-MrCleanEapoPackage {
    $C = $global:MrCleanEapoConst
    # 15. tur: dosyalar var diye "kurulu" sayma — COM kaydi da olmali. Ses servisi DLL i tutarken yapilan kaldirma
    # (eski Geri Al) kaydi siler ama dosyalar kalir; boyle bir PC de her kurulum "EQ yuklenemedi" ile bitiyordu (arkadas PC, G933).
    if (Get-MrCleanEapoInstallDir) {
        if (-not (Test-MrCleanApoClsid $C.PreMix) -and -not (Test-MrCleanApoClsid $C.PostMix)) { return $true }
        Write-MrCleanAudioLog "Equalizer APO dosyalari var ama Windows kaydi eksik (yarim kalmis bir kaldirma) - yeniden kuruluyor..."
    }
    $exe = Join-Path $env:TEMP "MrClean-EqualizerAPO-x64-1.4.2.exe"
    try {
        Write-MrCleanAudioLog "Equalizer APO 1.4.2 indiriliyor (SourceForge, ~12 MB)..."
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
        $wc = New-Object System.Net.WebClient; $wc.Headers.Add("User-Agent", "Wget/1.21")
        $wc.DownloadFile($C.Url, $exe)
        $h = (Get-FileHash -Path $exe -Algorithm SHA256).Hash
        if ($h -ne $C.Sha256) { Remove-Item $exe -Force -ErrorAction SilentlyContinue; Write-MrCleanAudioLog "GUVENLIK: indirilen dosyanin SHA-256 degeri beklenenle ayni DEGIL ($h) — kurulum iptal edildi."; return $false }
        Write-MrCleanAudioLog "SHA-256 dogrulandi. Sessiz kurulum..."
        $pr = Start-Process -FilePath $exe -ArgumentList "/S" -PassThru
        $sw = [Diagnostics.Stopwatch]::StartNew()
        while (-not $pr.HasExited -and $sw.Elapsed.TotalSeconds -lt 180) {
            # Kurulum sonunda acilan Device Selector penceresi kapatilir (aygitlari MrClean kendisi ayarlar)
            Get-Process -Name "DeviceSelector", "Configurator" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
            Start-Sleep -Milliseconds 400
        }
        Get-Process -Name "DeviceSelector", "Configurator" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        $dir = Get-MrCleanEapoInstallDir
        if (-not $dir) { Write-MrCleanAudioLog "Kurulum tamamlanamadi."; return $false }
        if (Test-MrCleanApoClsid $C.PreMix) {
            # Kurucu kaydi yazamadiysa (or. eski DLL kilitliydi) dogrudan kaydet
            try { Start-Process -FilePath "$env:WINDIR\System32\regsvr32.exe" -ArgumentList "/s `"$(Join-Path $dir 'EqualizerAPO.dll')`"" -Wait -WindowStyle Hidden } catch {}
            if (Test-MrCleanApoClsid $C.PreMix) { Write-MrCleanAudioLog "Equalizer APO Windows'a kaydedilemedi - bilgisayari yeniden baslatip tekrar deneyin."; return $false }
        }
        # Oturum acilisindaki guncelleme denetleyicisi gorevi kaldirilir (arka planda gereksiz is olmasin)
        $uc = Join-Path $dir "UpdateChecker.exe"
        # UpdateChecker.exe -u kendi klasorunde calismazsa Qt hatasi penceresi acar -> gorev dogrudan kaldirilir
        Unregister-ScheduledTask -TaskName "EqualizerAPOUpdateChecker" -Confirm:$false -ErrorAction SilentlyContinue
        Write-MrCleanAudioLog "Equalizer APO kuruldu: $dir"
        return $true
    } catch { Write-MrCleanAudioLog "Equalizer APO kurulamadi: $($_.Exception.Message)"; return $false }
    finally { Remove-Item $exe -Force -ErrorAction SilentlyContinue }
}

# Airwindows WinVST64s.zip (41 MB) icinden SADECE ClipOnly264.dll (~100 KB) HTTP Range ile alinir (zip merkez dizini okunur).
function Install-MrCleanClipOnly {
    $C = $global:MrCleanEapoConst
    $inst = Get-MrCleanEapoInstallDir; if (-not $inst) { return $false }
    $vdir = Join-Path $inst "VSTPlugins"; $dst = Join-Path $vdir "ClipOnly2.dll"
    if (Test-Path $dst) { return $true }
    $ua = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0 Safari/537.36"
    $get = {
        param([long]$a, [long]$b)
        $rq = [System.Net.HttpWebRequest]::Create($C.ClipUrl); $rq.UserAgent = $ua; $rq.Timeout = 20000
        if ($a -ge 0) { $rq.AddRange($a, $b) } else { $rq.Method = "HEAD" }
        $rs = $rq.GetResponse()
        if ($a -lt 0) { $len = $rs.ContentLength; $rs.Close(); return $len }
        $ms = New-Object IO.MemoryStream; $rs.GetResponseStream().CopyTo($ms); $rs.Close(); return ,$ms.ToArray()
    }
    try {
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
        Write-MrCleanAudioLog "Airwindows ClipOnly2 (MIT) aliniyor..."
        $len = [long](& $get -1 -1)
        $tailStart = [Math]::Max(0, $len - 262144); $tail = & $get $tailStart ($len - 1)
        $eocd = -1; for ($i = $tail.Length - 22; $i -ge 0; $i--) { if ([BitConverter]::ToUInt32($tail, $i) -eq 0x06054b50) { $eocd = $i; break } }
        if ($eocd -lt 0) { throw "zip dizini bulunamadi" }
        $cdSize = [BitConverter]::ToUInt32($tail, $eocd + 12); $cdOff = [long][BitConverter]::ToUInt32($tail, $eocd + 16)
        $cd = if ($cdOff -ge $tailStart) { $tail[($cdOff - $tailStart)..($cdOff - $tailStart + $cdSize - 1)] } else { & $get $cdOff ($cdOff + $cdSize - 1) }
        $cd = [byte[]]$cd; $pos = 0; $hit = $null
        while ($pos -lt $cd.Length - 46 -and [BitConverter]::ToUInt32($cd, $pos) -eq 0x02014b50) {
            $nl = [BitConverter]::ToUInt16($cd, $pos + 28); $xl = [BitConverter]::ToUInt16($cd, $pos + 30); $cl = [BitConverter]::ToUInt16($cd, $pos + 32)
            $nm = [Text.Encoding]::ASCII.GetString($cd, $pos + 46, $nl)
            if ($nm -match ("(^|/)" + [regex]::Escape($C.ClipName) + "$")) {
                $hit = @{ Method = [BitConverter]::ToUInt16($cd, $pos + 10); CSize = [BitConverter]::ToUInt32($cd, $pos + 20); USize = [BitConverter]::ToUInt32($cd, $pos + 24); Off = [long][BitConverter]::ToUInt32($cd, $pos + 42) }
                break
            }
            $pos += 46 + $nl + $xl + $cl
        }
        if (-not $hit) { throw "ClipOnly2 zip icinde bulunamadi" }
        $blk = [byte[]](& $get $hit.Off ($hit.Off + 30 + 1024 + $hit.CSize))
        if ([BitConverter]::ToUInt32($blk, 0) -ne 0x04034b50) { throw "yerel baslik hatali" }
        $ds = 30 + [BitConverter]::ToUInt16($blk, 26) + [BitConverter]::ToUInt16($blk, 28)
        $raw = New-Object byte[] $hit.CSize; [Array]::Copy($blk, $ds, $raw, 0, $hit.CSize)
        $data = $raw
        if ($hit.Method -eq 8) {
            $in = New-Object IO.MemoryStream(, $raw); $z = New-Object IO.Compression.DeflateStream($in, [IO.Compression.CompressionMode]::Decompress)
            $o = New-Object IO.MemoryStream; $z.CopyTo($o); $z.Close(); $data = $o.ToArray()
        }
        if ($data.Length -ne $hit.USize -or $data[0] -ne 0x4D -or $data[1] -ne 0x5A) { throw "dosya dogrulanamadi" }
        if (-not (Test-Path $vdir)) { New-Item -ItemType Directory -Path $vdir -Force | Out-Null }
        [IO.File]::WriteAllBytes($dst, $data)
        Write-MrCleanAudioLog "ClipOnly2 kuruldu ($([Math]::Round($data.Length / 1KB)) KB)."
        return $true
    } catch { Write-MrCleanAudioLog "ClipOnly2 alinamadi ($($_.Exception.Message)) — ses yukseltme kapali kalir."; return $false }
}

# --- Ayarlar ---
function Get-MrCleanAudioSettings {
    $k = $global:MrCleanEapoConst.SettingsKey
    $s = [ordered]@{ DefaultMode = "balanced"; GameCurve = "game"; AutoGame = $true; Bass = 3.5; Boost = 3; Leveler = "auto"; MicEngine = "dfn"; MicLevel = $false; MicAtten = 30; MicFloor = ""; Configured = $false }
    try {
        $p = Get-ItemProperty -Path $k -ErrorAction SilentlyContinue
        if ($p) {
            if ($p.DefaultMode) { $s.DefaultMode = "$($p.DefaultMode)" }
            if ($p.GameCurve -in @("game", "competitive")) { $s.GameCurve = "$($p.GameCurve)" }
            if ($p.MicEngine -in @("rnnoise", "dfn", "off")) { $s.MicEngine = "$($p.MicEngine)" }
            if ($null -ne $p.MicLevel) { $s.MicLevel = ([int]$p.MicLevel -eq 1) }
            if ($p.MicAtten) { $s.MicAtten = [int]$p.MicAtten }
            if ($p.MicFloor) { $s.MicFloor = "$($p.MicFloor)" }
            if ($null -ne $p.AutoGame) { $s.AutoGame = ([int]$p.AutoGame -eq 1) }
            if ($p.Bass) { $s.Bass = [double]::Parse("$($p.Bass)", [Globalization.CultureInfo]::InvariantCulture) }
            if ($null -ne $p.Boost) { $s.Boost = [int]$p.Boost }
            if ($p.Leveler -in @("auto", "full", "light", "off")) { $s.Leveler = "$($p.Leveler)" }
            $s.Configured = ([int]$p.Configured -eq 1)
        }
    } catch {}
    return $s
}
function Get-MrCleanAudioDevicePref([string]$Guid) {
    $k = "$($global:MrCleanEapoConst.SettingsKey)\Devices\$($Guid.Trim('{}'))"
    $p = Get-ItemProperty -Path $k -ErrorAction SilentlyContinue
    if (-not $p) { return $null }
    return [pscustomobject]@{ Enabled = ([int]$p.Enabled -eq 1); Kind = "$($p.Kind)"; Model = "$($p.Model)"; Rel = "$($p.Rel)" }
}
function Set-MrCleanAudioDevicePref([string]$Guid, [bool]$Enabled, [string]$Kind, [string]$Model, [string]$Rel) {
    $k = "$($global:MrCleanEapoConst.SettingsKey)\Devices\$($Guid.Trim('{}'))"
    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
    Set-ItemProperty -Path $k -Name "Enabled" -Value ([int]$Enabled) -Type DWord -Force
    Set-ItemProperty -Path $k -Name "Kind" -Value $Kind -Type String -Force
    Set-ItemProperty -Path $k -Name "Model" -Value "$Model" -Type String -Force
    Set-ItemProperty -Path $k -Name "Rel" -Value "$Rel" -Type String -Force
}

# Logitech G HUB kurulu mu (Yeti / Blue mikrofonlarin Blue VO!CE islemesi G HUB icinde calisir)
function Test-MrCleanGhubPresent {
    return [bool]((Get-Service -Name "LGHUBUpdaterService" -ErrorAction SilentlyContinue) -or (Test-Path (Join-Path $env:ProgramFiles "LGHUB\lghub.exe")))
}

# Aygit icin varsayilan plan (kullanici tercihi yoksa)
function Get-MrCleanAudioDevicePlan($Dev, $Index, [switch]$Offline) {
    $pref = Get-MrCleanAudioDevicePref $Dev.Guid
    $kind = $Dev.Kind; $model = ""; $rel = ""; $en = $true
    if ($pref) { $en = $pref.Enabled; if ($pref.Kind) { $kind = $pref.Kind }; $model = $pref.Model; $rel = $pref.Rel }
    else {
        if ($kind -in @("Virtual", "HandsFree", "Digital")) { $en = $false }
        if ($Dev.FormFactor -eq 9 -and -not $Dev.Default) { $en = $false }   # varsayilan olmayan monitor / TV ses cikisi
        # v1.3.0 (10. tur, kullanici: "her seyi isaretlemis, kafasina gore secmis"): ilk acilista varsayilan secim daraltildi.
        # Takili olmayan jak (DeviceState 8) isaretsiz; mikrofonlardan SADECE Windows varsayilani; USB mikrofonun kulaklik cikisi
        # (Yeti / QuadCast / Wave / Snowball) sadece varsayilan cikissa. Kullanicinin onceki secimi ($pref) her zaman korunur.
        if ($Dev.State -ne 1) { $en = $false }
        if ($kind -eq "Mic" -and -not $Dev.Default) { $en = $false }
        if ($kind -eq "Headphones" -and "$($Dev.Name) $($Dev.Desc)" -match "(?i)yeti|quadcast|wave|snowball" -and -not $Dev.Default) { $en = $false }
        # Mikrofonun kendi isleme yazilimi KURULUYSA (Yeti / Blue -> G HUB Blue VO!CE) cift islem olmasin diye atlanir;
        # yazilim yoksa (kullanici G HUB i kaldirdiysa) MrClean temiz mikrofon EQ sunu uygular. Sanal mikrofonlar (Broadcast / Wave Link) hic ayarlanmaz.
        if ($kind -eq "Mic" -and "$($Dev.Name) $($Dev.Desc)" -match "(?i)broadcast|wave link|voicemeeter|virtual") { $en = $false }
        if ($kind -eq "Mic" -and "$($Dev.Name) $($Dev.Desc)" -match "(?i)yeti|blue" -and (Test-MrCleanGhubPresent)) { $en = $false }
        if ($kind -in @("Headphones", "Speaker", "Voice") -and $Index) {
            $m = Find-MrCleanAutoEqMatch $Dev.Desc ($Dev.Bus -match "(?i)BTH") $Index
            if (-not $m) { $m = Find-MrCleanAutoEqMatch $Dev.Name ($Dev.Bus -match "(?i)BTH") $Index }
            if ($m) { if ($kind -ne "Voice") { $kind = "Headphones" }; $model = "$($m.Name) ($($m.Src))"; $rel = $m.Rel }
        }
    }
    $micType = ""
    if ($kind -eq "Mic") { $micType = if ($pref -and $pref.Model -in @("headset", "desk", "laptop")) { $pref.Model } else { Get-MrCleanMicType $Dev }; $model = "" }
    return [pscustomobject]@{ Dev = $Dev; Enabled = $en; Kind = $kind; Model = $model; Rel = $rel; MicType = $micType }
}

# --- Config yazimi ---
function Write-MrCleanAudioConfig($Plans, $Settings, [bool]$HasClip) {
    $cfg = Get-MrCleanEapoConfigDir; if (-not $cfg) { return $false }
    $ic = [Globalization.CultureInfo]::InvariantCulture; $enc = New-Object Text.UTF8Encoding($false)
    $main = Join-Path $cfg "config.txt"; $bk = Join-Path $cfg "config.mrclean-yedek.txt"
    if ((Test-Path $main) -and -not (Test-Path $bk) -and ([IO.File]::ReadAllText($main) -notmatch "MrClean")) { Copy-Item $main $bk -Force }
    Remove-Item (Join-Path $cfg "MrClean-Ses.txt") -Force -ErrorAction SilentlyContinue      # 7. tur tek dosyali surum
    $modes = @("balanced", "music", "game")
    $gc = if ($Settings.GameCurve -eq "competitive") { "competitive" } else { "game" }
    $curveOf = @{ balanced = "balanced"; music = "music"; game = $gc }
    foreach ($m in $modes) {
        $lines = @("# MrClean kulaklik modu: $m / $($curveOf[$m]) (AutoEq / Harman ustune)") + @(Get-MrCleanAudioCurve $curveOf[$m] $Settings.Bass | ForEach-Object { Format-MrCleanEqFilter $_ })
        if ($m -eq "game" -and $HasClip -and "$($Settings.Leveler)" -ne "off" -and (Test-Path (Join-Path (Join-Path (Get-MrCleanEapoInstallDir) "VSTPlugins") $global:MrCleanEapoConst.LevFile))) {
            $lines += "VSTPlugin: Library `"$($global:MrCleanEapoConst.LevFile)`" $($global:MrCleanEapoConst.LevGame)"
        }
        [IO.File]::WriteAllText((Join-Path $cfg "MrClean-hp-$m.txt"), ($lines -join "`r`n") + "`r`n", $enc)
    }
    # Kullanicinin kendi ince ayari (Peace gerekmez): her kulaklik / hoparlor zincirine eklenir; MrClean bu dosyayi ASLA ezmez
    $uf = Join-Path $cfg "MrClean-user.txt"
    if (-not (Test-Path $uf)) {
        [IO.File]::WriteAllText($uf, (@(
            "# MrClean - kullanici ince ayari (bos = etkisiz). Kaydedince Equalizer APO aninda uygular.",
            "# Bicim: Filter: ON PK Fc 3200 Hz Gain 1.5 dB Q 1.4   (PK = tepe, LSC = alt raf, HSC = ust raf)",
            "# Yukseltme yaparsaniz ayni miktarda eksi on kazanc ekleyin, orn: Preamp: -1.5 dB  (yoksa kirpilma / cizirti olabilir)",
            "# Sadece belirli aygit icin: Device: Arctis   ... satirlari ...   Device: all",
            "# Ayrintili gorsel duzenleme: Equalizer APO klasorundeki Editor.exe"
        ) -join "`r`n") + "`r`n", $enc)
    }
    $act = Join-Path $cfg "MrClean-hp-active.txt"
    Copy-Item (Join-Path $cfg "MrClean-hp-$($Settings.DefaultMode).txt") $act -Force
    $cfgLines = @("# MrClean Otomatik Ses - $(Get-Date -Format 'yyyy-MM-dd HH:mm') (orijinal ayar: config.mrclean-yedek.txt)")
    $levOk = $HasClip -and (Test-Path (Join-Path (Join-Path (Get-MrCleanEapoInstallDir) "VSTPlugins") $global:MrCleanEapoConst.LevFile))
    $levMultiOk = $levOk -and (Test-Path (Join-Path (Join-Path (Get-MrCleanEapoInstallDir) "VSTPlugins") $global:MrCleanEapoConst.LevMultiFile))
    $levMode = if ($Settings.Leveler) { "$($Settings.Leveler)" } else { "auto" }
    foreach ($pl in @($Plans | Where-Object { $_.Enabled -and $_.Kind -in @("Headphones", "Speaker", "Mic", "Voice") })) {
        $g = $pl.Dev.Guid.Trim("{}"); $file = "MrClean-dev-$g.txt"
        if ($pl.Kind -eq "Mic") {
            $mc = Get-MrCleanMicChainLines $pl $Settings
            [IO.File]::WriteAllText((Join-Path $cfg $file), ($mc.Lines -join "`r`n") + "`r`n", $enc)
            $cfgLines += "Device: {$g}"; $cfgLines += "Include: $file"
            Write-MrCleanAudioLog ("{0}: mikrofon ({1}), gurultu bastirma {2}{3}" -f $pl.Dev.Name, $mc.Type, $mc.Engine, $(if ($mc.Note) { " - " + $mc.Note } else { "" }))
            continue
        }
        $dl = @("# $($pl.Dev.Name) ($($pl.Dev.Desc)) - $($pl.Kind)$(if ($pl.Model) { ' - ' + $pl.Model })" -replace "[^\x20-\x7E]", "")
        $aeq = @(); if ($pl.Kind -in @("Headphones", "Voice") -and $pl.Rel) { $aeq = @(Get-MrCleanAutoEqFilters $pl.Rel) }
        $peak = 0.0
        switch ($pl.Kind) {
            "Headphones" { foreach ($m in $modes) { $pk = (Measure-MrCleanEqPeak (@($aeq) + @(Get-MrCleanAudioCurve $curveOf[$m] $Settings.Bass))).Peak; if ($pk -gt $peak) { $peak = $pk } } }
            "Speaker"    { $peak = (Measure-MrCleanEqPeak (Get-MrCleanAudioCurve "speaker" 0)).Peak }
            "Voice"      { $peak = (Measure-MrCleanEqPeak (@($aeq) + @(Get-MrCleanAudioCurve "voice" 0))).Peak }
            "Mic"        { $peak = (Measure-MrCleanEqPeak (Get-MrCleanAudioCurve "mic" 0)).Peak }
        }
        $boost = if ($pl.Kind -in @("Headphones", "Voice") -and $HasClip) { [double]$Settings.Boost } elseif ($pl.Kind -eq "Speaker" -and $HasClip -and [double]$Settings.Boost -gt 0) { [double]$Settings.Boost + 3 } else { 0.0 }
        # Ses dengeleyici (Dolby Volume Leveler esdegeri): Otomatik = hoparlor / soundbar Tam (saf Dolby ile olculup eslendi), kulaklik ve
        # sohbet kanali Hafif (yarim egri: kisik adim / konusma one cikar, patlama bastirilir; kulaklikta tam egri yorucu olur)
        $lv = ""
        if ($levOk -and $pl.Kind -in @("Headphones", "Speaker", "Voice")) {
            $lv = switch ($levMode) { "full" { "full" } "light" { "light" } "off" { "" } default { if ($pl.Kind -eq "Speaker") { "full" } else { "light" } } }
        }
        if ($lv -eq "full" -and -not $levMultiOk) { $lv = "light" }
        $pre = -[Math]::Ceiling(([Math]::Max(0, $peak) + 0.5) * 10) / 10 + $boost
        # Tam modda seviye dengeleyici calisma noktasina gore: benzetimdeki +7 dB (hoparlor egrisi tepe 4 dB); daha yuksek EQ tepesi kadar dusulur
        if ($lv -eq "full") { $pre = $global:MrCleanEapoConst.LevFullPre - [Math]::Max(0, $peak - 4.0) }
        $dl += "Preamp: $($pre.ToString('0.0', $ic)) dB"
        if ($aeq.Count) { $dl += @($aeq | ForEach-Object { Format-MrCleanEqFilter $_ }) }
        switch ($pl.Kind) {
            "Headphones" { $dl += "Include: MrClean-hp-active.txt" }
            "Speaker"    { $dl += @(Get-MrCleanAudioCurve "speaker" 0 | ForEach-Object { Format-MrCleanEqFilter $_ }) }
            "Voice"      { $dl += @(Get-MrCleanAudioCurve "voice" 0 | ForEach-Object { Format-MrCleanEqFilter $_ }) }
            "Mic"        { $dl += @(Get-MrCleanAudioCurve "mic" 0 | ForEach-Object { Format-MrCleanEqFilter $_ }) }
        }
        if ($pl.Kind -in @("Headphones", "Speaker", "Voice")) { $dl += "Include: MrClean-user.txt" }
        # Aygita ozel kisisel ton (10. tur): MrClean-user-<guid>.txt varsa SADECE bu aygitin zincirine eklenir, MrClean asla ezmez.
        # (Genel MrClean-user.txt icinde "Device:" kullanmak tehlikeli: Include sonrasi satirlar baska aygita kayabilir.)
        if ($pl.Kind -in @("Headphones", "Speaker", "Voice") -and (Test-Path (Join-Path $cfg "MrClean-user-$g.txt"))) { $dl += "Include: MrClean-user-$g.txt" }
        if ($lv -eq "full") { $dl += "VSTPlugin: Library `"$($global:MrCleanEapoConst.LevMultiFile)`" $($global:MrCleanEapoConst.LevMulti)" }
        if ($lv) { $dl += "VSTPlugin: Library `"$($global:MrCleanEapoConst.LevFile)`" $(if ($lv -eq 'full') { $global:MrCleanEapoConst.LevFull } else { $global:MrCleanEapoConst.LevLight })" }
        if ($lv) { $dl += "VSTPlugin: Library `"$($global:MrCleanEapoConst.LevFile)`" $($global:MrCleanEapoConst.LevTop)" }
        if ($lv -eq "full") { $dl += "Preamp: $(([double]$global:MrCleanEapoConst.LevFullPost).ToString('0.0', $ic)) dB" }
        elseif ($lv -eq "light") { $dl += "Preamp: $(([double]$global:MrCleanEapoConst.LevLightPost).ToString('0.0', $ic)) dB" }
        # Son asama: seffaf guvenlik kirpicisi (1 ornek gecikme) — yukseltilmis seste kirpilma "cizirti" yerine yumusak
        if ($boost -gt 0 -or $lv) { $dl += 'VSTPlugin: Library "ClipOnly2.dll"' }
        [IO.File]::WriteAllText((Join-Path $cfg $file), ($dl -join "`r`n") + "`r`n", $enc)
        # v1.3.0 (10. tur): KAPI. Olculdu: Dolby Atmos / Windows Sonic acikken EAPO zinciri KAPANMIYOR, uzamsal islemin USTUNE ekleniyor
        # (cift EQ + cift seviye dengeleme; kisik seste +27 dB). Uzamsal ses aciksa kapi zinciri devre disi birakir; "MrClean Ses Modu"
        # gorevi uzamsal ses acilip kapandikca kapiyi 2 sn icinde gunceller (Dolby <-> MrClean karsilastirmasi da boylece adil olur).
        $spOn = [bool](Get-MrCleanSpatialFormat $pl.Dev.Guid)
        [IO.File]::WriteAllText((Join-Path $cfg "MrClean-gate-$g.txt"), $(if ($spOn) { "# Uzamsal ses (Dolby / Sonic) acik: MrClean bu aygitta devre disi (cift islem olmasin)" } else { "Include: $file" }) + "`r`n", $enc)
        $cfgLines += "Device: {$g}"; $cfgLines += "Include: MrClean-gate-$g.txt"
        Write-MrCleanAudioLog ("{0}: {1}{2}, on kazanc {3} dB{4}" -f $pl.Dev.Name, $pl.Kind, $(if ($pl.Model) { " / $($pl.Model)" } else { "" }), $pre.ToString("0.0", $ic), $(switch ($lv) { "full" { ", ses dengeleyici TAM (Dolby esdegeri, 3 bant)" } "light" { ", ses dengeleyici hafif" } default { "" } }))
    }
    # v1.3.0 (10. tur) HATA DUZELTMESI: kurulu ama SU AN bagli olmayan aygit (kapali soundbar, cikarilmis kulaklik) config.txt den
    # dusuyordu; tekrar takilinca EQ gelmiyordu (Maintain kayit zaten var diye yeniden yazmaz). Plan listesinde olmayan, tercihi
    # "etkin" ve dosyasi duran aygitlar korunur. Planda olup kapatilanlar (Enabled = false) eklenmez.
    $inPlan = @($Plans | ForEach-Object { "$($_.Dev.Guid)".Trim("{}").ToLower() })
    foreach ($df in @(Get-ChildItem $cfg -Filter "MrClean-dev-*.txt" -ErrorAction SilentlyContinue)) {
        $g2 = $df.BaseName.Substring(12)
        if ($inPlan -contains $g2.ToLower()) { continue }
        $pref = Get-MrCleanAudioDevicePref $g2
        if (-not ($pref -and $pref.Enabled)) { continue }
        $inc = if (Test-Path (Join-Path $cfg "MrClean-gate-$g2.txt")) { "MrClean-gate-$g2.txt" } else { $df.Name }
        $cfgLines += "Device: {$g2}"; $cfgLines += "Include: $inc"
    }
    $cfgLines += "Device: all"
    [IO.File]::WriteAllText($main, ($cfgLines -join "`r`n") + "`r`n", $enc)
    [IO.File]::WriteAllText((Join-Path $cfg "MrClean-default-mode.txt"), $Settings.DefaultMode, $enc)
    return $true
}

# --- Oyun algilayan mod gorevi (olay tabanli; oyun yokken CPU 0, ~30-40 MB RAM) ---
function Register-MrCleanAudioModeTask([string[]]$Games = @(), [switch]$NoGames) {
    $C = $global:MrCleanEapoConst
    $cfg = Get-MrCleanEapoConfigDir; if (-not $cfg) { return $false }
    $known = @("cs2.exe","cod.exe","bf6.exe","bf2042.exe","bf1.exe","bf4.exe","bfv.exe","tslgame.exe","valorant-win64-shipping.exe","r5apex.exe","r5apex_dx12.exe",
               "fortniteclient-win64-shipping.exe","rainbowsix.exe","rainbowsix_be.exe","overwatch.exe","marvel-win64-shipping.exe","deltaforceclient-win64-shipping.exe",
               "escapefromtarkov.exe","rustclient.exe","hunt.exe","thefinals.exe","dota2.exe","leagueoflegends.exe","league of legends.exe")
    $found = @($Games | ForEach-Object { "$_".ToLower() })
    if ($found.Count -eq 0) { try { $found = @(Get-MrCleanGameExes | ForEach-Object { [IO.Path]::GetFileName("$_").ToLower() }) } catch {} }
    $games = @(@($known) + @($found) | Where-Object { $_ -match "\.exe$" -and $_ -notmatch "'" } | Select-Object -Unique)
    if ($NoGames) { $games = @() }
    [IO.File]::WriteAllLines((Join-Path $cfg "MrClean-games.txt"), [string[]]$games)
    $script = @'
# MrClean Ses Modu — oyun acilinca kulaklik EQ "Oyun", kapaninca varsayilan mod. Olay tabanli (WMI process trace), yoklama yok.
$ErrorActionPreference = "SilentlyContinue"
$dir = Split-Path -Parent $MyInvocation.MyCommand.Path
$games = @(Get-Content (Join-Path $dir "MrClean-games.txt") | ForEach-Object { $_.Trim().ToLower() } | Where-Object { $_ })
$null = [Windows.Media.Audio.SpatialAudioDeviceConfiguration, Windows.Media.Audio, ContentType = WindowsRuntime]
$gates = @{}; $gateScan = 0
function Sync-Gates {
    # Kapi listesi dakikada bir taranir; uzamsal durum her turda (WinRT, aygit basina < 1 ms). Dosyaya sadece degisince yazilir.
    if ($script:gateScan -le 0) {
        $script:gateScan = 30
        foreach ($gf in @(Get-ChildItem $dir -Filter "MrClean-gate-*.txt")) {
            $g = $gf.BaseName.Substring(13)
            if (-not $script:gates.ContainsKey($g)) { $script:gates[$g] = @{ File = $gf.FullName; Cfg = $null; Cur = [IO.File]::ReadAllText($gf.FullName).Trim() } }
        }
    }
    $script:gateScan--
    foreach ($g in @($script:gates.Keys)) {
        $o = $script:gates[$g]; $sp = $false
        try {
            if (-not $o.Cfg) { $o.Cfg = [Windows.Media.Audio.SpatialAudioDeviceConfiguration]::GetForDeviceId("\\?\SWD#MMDEVAPI#{0.0.0.00000000}.{" + $g.ToLower() + "}#{e6327cad-dcec-4949-ae8a-991e976a79d2}") }
            $f = "$($o.Cfg.ActiveSpatialAudioFormat)"; $sp = ($f -and $f -notmatch '^\{?0{8}-')
        } catch { $o.Cfg = $null }
        $want = if ($sp) { "# Uzamsal ses (Dolby / Sonic) acik: MrClean bu aygitta devre disi (cift islem olmasin)" } else { "Include: MrClean-dev-$g.txt" }
        if ($o.Cur -ne $want -and (Test-Path $o.File)) { try { [IO.File]::WriteAllText($o.File, $want + "`r`n"); $o.Cur = $want } catch {} }
    }
}
Sync-Gates
function Get-Def { $d = "$(Get-Content (Join-Path $dir 'MrClean-default-mode.txt') -TotalCount 1)".Trim(); if ($d -notin @("balanced","music","game")) { $d = "balanced" }; $d }
function Set-Mode([string]$m) {
    $src = Join-Path $dir "MrClean-hp-$m.txt"; $dst = Join-Path $dir "MrClean-hp-active.txt"
    if (-not (Test-Path $src)) { return }
    $t = [IO.File]::ReadAllText($src); $c = ""; if (Test-Path $dst) { $c = [IO.File]::ReadAllText($dst) }
    if ($t -ne $c) { [IO.File]::WriteAllText($dst, $t) }
}
$run = @{}
foreach ($p in Get-Process) { if ($games -contains ("$($p.ProcessName).exe").ToLower()) { $run[$p.Id] = 1 } }
if ($run.Count) { Set-Mode "game" } else { Set-Mode (Get-Def) }
# 1. tercih: cekirdek surec olaylari (yonetici; sifir yoklama). Yetki yoksa: WMI __Instance olaylari (3 sn de bir WMI ici kontrol).
if ($games.Count) { try {
    $w = ($games | ForEach-Object { "ProcessName='" + $_ + "'" }) -join " OR "
    Register-CimIndicationEvent -Query "SELECT ProcessID, ProcessName FROM Win32_ProcessStartTrace WHERE $w" -SourceIdentifier MrcAudStart -ErrorAction Stop | Out-Null
    Register-CimIndicationEvent -Query "SELECT ProcessID, ProcessName FROM Win32_ProcessStopTrace WHERE $w" -SourceIdentifier MrcAudStop -ErrorAction Stop | Out-Null
} catch {
    Unregister-Event -SourceIdentifier MrcAudStart -ErrorAction SilentlyContinue; Unregister-Event -SourceIdentifier MrcAudStop -ErrorAction SilentlyContinue
    $w = ($games | ForEach-Object { "TargetInstance.Name='" + $_ + "'" }) -join " OR "
    Register-CimIndicationEvent -Query "SELECT * FROM __InstanceCreationEvent WITHIN 3 WHERE TargetInstance ISA 'Win32_Process' AND ($w)" -SourceIdentifier MrcAudStart | Out-Null
    Register-CimIndicationEvent -Query "SELECT * FROM __InstanceDeletionEvent WITHIN 3 WHERE TargetInstance ISA 'Win32_Process' AND ($w)" -SourceIdentifier MrcAudStop | Out-Null
} }
while ($true) {
    $e = Wait-Event -Timeout 2
    Sync-Gates
    if (-not $e) { continue }
    $ne = $e.SourceEventArgs.NewEvent; $src = $e.SourceIdentifier
    $id = if ($null -ne $ne.TargetInstance) { [int]$ne.TargetInstance.ProcessId } else { [int]$ne.ProcessID }
    Remove-Event -EventIdentifier $e.EventIdentifier
    if ($src -eq "MrcAudStart") { $run[$id] = 1 } else { $run.Remove($id) }
    if ($run.Count) { Set-Mode "game" } else { Set-Mode (Get-Def) }
}
'@
    $sp = Join-Path $cfg "MrClean-AudioMode.ps1"     # Program Files altinda: sadece yonetici yazabilir (yukseltilmis gorev guvenli)
    [IO.File]::WriteAllText($sp, $script, (New-Object Text.UTF8Encoding($true)))
    Unregister-ScheduledTask -TaskName $C.TaskName -Confirm:$false -ErrorAction SilentlyContinue
    Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -like "*MrClean-AudioMode.ps1*" } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
    $action = New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot "System32\conhost.exe") -Argument "--headless powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$sp`""
    $trigger = New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME
    $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Hours 0) -RestartCount 3 -RestartInterval (New-TimeSpan -Minutes 1) -Priority 7
    $principal = New-ScheduledTaskPrincipal -UserId $env:USERNAME -LogonType Interactive -RunLevel Highest   # WMI process trace yonetici ister
    Register-ScheduledTask -TaskName $C.TaskName -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force | Out-Null
    Start-ScheduledTask -TaskName $C.TaskName -ErrorAction SilentlyContinue
    Write-MrCleanAudioLog "Ses modu gorevi kuruldu ($(if ($games.Count) { "$($games.Count) oyun exe, olay tabanli; " } else { '' })Dolby / uzamsal ses acilinca MrClean o aygitta kendini devre disi birakir)."
    return $true
}
function Unregister-MrCleanAudioModeTask {
    Unregister-ScheduledTask -TaskName $global:MrCleanEapoConst.TaskName -Confirm:$false -ErrorAction SilentlyContinue
    Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -like "*MrClean-AudioMode.ps1*" } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
}

# --- Tam otomatik kurulum (isci runspace te calisir) ---
function Invoke-MrCleanAudioSetup($Plans, $Settings) {
    if (-not (Install-MrCleanEapoPackage)) { return $false }
    $hasClip = $false
    $wantLev = ("$($Settings.Leveler)" -ne "off")
    if ([int]$Settings.Boost -gt 0 -or $wantLev) { $hasClip = Install-MrCleanClipOnly }
    if ($wantLev -and $hasClip) {
        $C = $global:MrCleanEapoConst; $vd = Join-Path (Get-MrCleanEapoInstallDir) "VSTPlugins"
        if (-not (Test-Path $vd)) { New-Item -ItemType Directory -Path $vd -Force | Out-Null }
        if (-not (Test-Path (Join-Path $vd $C.LevFile))) {
            Write-MrCleanAudioLog "Ses dengeleyici (ZamCompX2, GPL, ~1.5 MB) indiriliyor..."
            [void](Install-MrCleanZipMember $C.LevUrl $C.LevMember (Join-Path $vd $C.LevFile) $C.LevSha)
        }
        if (-not (Test-Path (Join-Path $vd $C.LevMultiFile))) {
            Write-MrCleanAudioLog "3 bantli dengeleyici (ZaMultiCompX2, GPL, ~2 MB) indiriliyor..."
            [void](Install-MrCleanZipMember $C.LevUrl $C.LevMultiMember (Join-Path $vd $C.LevMultiFile) $C.LevMultiSha)
        }
    }
    $todo = @($Plans | Where-Object { $_.Enabled -and $_.Kind -in @("Headphones", "Speaker", "Mic", "Voice") })
    if (@($todo | Where-Object { $_.Kind -eq "Mic" }).Count -gt 0) { Install-MrCleanMicComponents "$($Settings.MicEngine)" }
    $skip = @($Plans | Where-Object { -not ($_.Enabled -and $_.Kind -in @("Headphones", "Speaker", "Mic", "Voice")) })
    foreach ($pl in $skip) { if ($pl.Dev.Eapo -or (Test-Path "HKLM:\SOFTWARE\EqualizerAPO\Child APOs\$($pl.Dev.Guid)")) { Uninstall-MrCleanEapoDevice $pl.Dev.Guid $pl.Dev.Flow; Write-MrCleanAudioLog "$($pl.Dev.Name): EQ kaldirildi (secilmedi)." } }
    try {
        $dk = "HKCU:\Software\Microsoft\Multimedia\Audio"; $sk = $global:MrCleanEapoConst.SettingsKey
        if (-not (Test-Path $sk)) { New-Item -Path $sk -Force | Out-Null }
        $cur = (Get-ItemProperty -Path $dk -Name "UserDuckingPreference" -ErrorAction SilentlyContinue).UserDuckingPreference
        if ($null -eq (Get-ItemProperty -Path $sk -Name "PrevDucking" -ErrorAction SilentlyContinue)) { Set-ItemProperty -Path $sk -Name "PrevDucking" -Value $(if ($null -eq $cur) { "none" } else { "$cur" }) -Type String -Force }
        if (-not (Test-Path $dk)) { New-Item -Path $dk -Force | Out-Null }
        if ("$cur" -ne "3") { Set-ItemProperty -Path $dk -Name "UserDuckingPreference" -Value 3 -Type DWord -Force; Write-MrCleanAudioLog "Discord / sesli gorusmede Windows'un oyun ve muzik sesini kismasi kapatildi." }
    } catch {}
    $modeOf = @{}
    foreach ($pl in $todo) {
        $m = Install-MrCleanEapoDevice $pl.Dev
        if (-not $m) { Write-MrCleanAudioLog "$($pl.Dev.Name): bu aygitin surucusu efekt (APO) desteklemiyor — atlandi."; $pl.Enabled = $false; continue }
        $modeOf[$pl.Dev.Guid] = $m
    }
    [void](Write-MrCleanAudioConfig $Plans $Settings $hasClip)
    # Dogrulama: calismayan aygitta sirayla diger kurulum modlari denenir (EAPO Cihaz Secici ile ayni mantik)
    $active = @($todo | Where-Object { $_.Enabled -and $_.Dev.State -eq 1 } | ForEach-Object { $_.Dev })
    $result = @{}
    if ($active.Count) {
        $ok = @(Test-MrCleanEapoDevices $active)
        foreach ($round in 1..2) {
            $bad = @($active | Where-Object { $ok -notcontains $_.Guid.Trim("{}") })
            if ($bad.Count -eq 0) { break }
            foreach ($d in $bad) {
                $order = @("SFX_EFX", "SFX_MFX", "LFX_GFX"); $cur = $modeOf[$d.Guid]
                $next = $order[([Array]::IndexOf($order, $cur) + 1) % 3]
                $modeOf[$d.Guid] = Install-MrCleanEapoDevice $d $next
                Write-MrCleanAudioLog "$($d.Name): $cur calismadi, $next deneniyor..."
            }
            $ok = @(Test-MrCleanEapoDevices $active)
        }
        foreach ($d in $active) { $result[$d.Guid] = ($ok -contains $d.Guid.Trim("{}")) }
    }
    foreach ($pl in $todo) { Set-MrCleanAudioDevicePref $pl.Dev.Guid $pl.Enabled $pl.Kind $(if ($pl.Kind -eq "Mic") { $pl.MicType } else { $pl.Model }) $pl.Rel }
    foreach ($pl in $skip) { Set-MrCleanAudioDevicePref $pl.Dev.Guid $false $pl.Kind $(if ($pl.Kind -eq "Mic") { $pl.MicType } else { $pl.Model }) $pl.Rel }
    $k = $global:MrCleanEapoConst.SettingsKey
    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
    Set-ItemProperty -Path $k -Name "DefaultMode" -Value $Settings.DefaultMode -Type String -Force
    Set-ItemProperty -Path $k -Name "MicEngine" -Value $(if ($Settings.MicEngine) { $Settings.MicEngine } else { "rnnoise" }) -Type String -Force
    Set-ItemProperty -Path $k -Name "MicLevel" -Value ([int][bool]$Settings.MicLevel) -Type DWord -Force
    if ([int]$Settings.MicAtten -ge 10) { Set-ItemProperty -Path $k -Name "MicAtten" -Value ([int]$Settings.MicAtten) -Type DWord -Force }
    Set-ItemProperty -Path $k -Name "GameCurve" -Value $(if ($Settings.GameCurve) { $Settings.GameCurve } else { "game" }) -Type String -Force
    Set-ItemProperty -Path $k -Name "AutoGame" -Value ([int][bool]$Settings.AutoGame) -Type DWord -Force
    Set-ItemProperty -Path $k -Name "Bass" -Value ([double]$Settings.Bass).ToString([Globalization.CultureInfo]::InvariantCulture) -Type String -Force
    Set-ItemProperty -Path $k -Name "Boost" -Value ([int]$Settings.Boost) -Type DWord -Force
    Set-ItemProperty -Path $k -Name "Leveler" -Value $(if ($Settings.Leveler) { "$($Settings.Leveler)" } else { "auto" }) -Type String -Force
    Set-ItemProperty -Path $k -Name "Configured" -Value 1 -Type DWord -Force
    [void](Register-MrCleanAudioModeTask ([string[]]@($Settings.Games)) -NoGames:(-not $Settings.AutoGame))
    foreach ($g in $result.Keys) { $d = @($active | Where-Object { $_.Guid -eq $g })[0]; Write-MrCleanAudioLog ("{0} {1}" -f $(if ($result[$g]) { "✔ EQ CALISIYOR:" } else { "✖ EQ yuklenemedi:" }), $d.Name) }
    return $true
}

# Hepsini geri al. -RemoveEapo: programi da kaldir.
function Remove-MrCleanAudioAll([switch]$RemoveEapo) {
    Unregister-MrCleanAudioModeTask
    $root = "HKLM:\SOFTWARE\EqualizerAPO\Child APOs"
    foreach ($c in @(Get-ChildItem $root -ErrorAction SilentlyContinue)) {
        if ($null -eq (Get-ItemProperty $c.PSPath -Name "MrCleanMode" -ErrorAction SilentlyContinue)) { continue }   # sadece MrClean in kurduklari
        $flow = if (Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Capture\$($c.PSChildName)") { "Capture" } else { "Render" }
        # 15. tur: bir aygitin hatasi digerlerini yarim birakmasin
        try { Uninstall-MrCleanEapoDevice $c.PSChildName $flow } catch { Write-MrCleanAudioLog "$($c.PSChildName): geri alma hatasi ($($_.Exception.Message)) - onarim adiminda tekrar denenecek." }
    }
    $cfg = Get-MrCleanEapoConfigDir
    if ($cfg) {
        $bk = Join-Path $cfg "config.mrclean-yedek.txt"; $main = Join-Path $cfg "config.txt"
        if (Test-Path $bk) { Copy-Item $bk $main -Force; Remove-Item $bk -Force } else { [IO.File]::WriteAllText($main, "", (New-Object Text.UTF8Encoding($false))) }
        # kullanicinin kendi ince ayarlari (MrClean-user.txt, MrClean-user-<guid>.txt) silinmez — tekrar kurulunca aynen kullanilir
        Get-ChildItem $cfg -Filter "MrClean-*" -ErrorAction SilentlyContinue | Where-Object { $_.Name -notlike "MrClean-user*" -or $RemoveEapo } | Remove-Item -Force -ErrorAction SilentlyContinue
    }
    try {
        $pd = "$((Get-ItemProperty -Path $global:MrCleanEapoConst.SettingsKey -Name 'PrevDucking' -ErrorAction SilentlyContinue).PrevDucking)"
        $dk = "HKCU:\Software\Microsoft\Multimedia\Audio"
        if ($pd -eq "none") { Remove-ItemProperty -Path $dk -Name "UserDuckingPreference" -ErrorAction SilentlyContinue }
        elseif ($pd -match "^\d+$") { Set-ItemProperty -Path $dk -Name "UserDuckingPreference" -Value ([int]$pd) -Type DWord -Force }
    } catch {}
    Remove-Item -Path $global:MrCleanEapoConst.SettingsKey -Recurse -Force -ErrorAction SilentlyContinue
    # 15. tur: aygitlar eski haline dondukten sonra ses servisi yeniden baslatilir (aksi halde ses motoru eski efekt zincirini tutar;
    # program da kaldirilirsa aygit sessiz kalabiliyordu). Kaldirilmis programlarin efekt kayitlari temizlenir.
    [void](Repair-MrCleanAudioEndpoints)
    Write-MrCleanAudioLog "Ses servisi yeniden baslatiliyor (2-3 sn ses kesilir)..."
    Restart-MrCleanAudioService
    if ($RemoveEapo) {
        $inst = Get-MrCleanEapoInstallDir
        if ($inst -and (Test-Path (Join-Path $inst "Uninstall.exe"))) { try { Start-Process -FilePath (Join-Path $inst "Uninstall.exe") -ArgumentList "/S" -Wait } catch {} }
        if ((Repair-MrCleanAudioEndpoints) -gt 0) { Restart-MrCleanAudioService }
    }
    Write-MrCleanAudioLog "Ses ayarlari geri alindi$(if ($RemoveEapo) { ' ve Equalizer APO kaldirildi' })."
}

# Program acilisinda (hizli, ag yok): yapilandirilmis aygitin EAPO kaydi surucu / Windows guncellemesiyle koptuysa geri takar;
# yeni takilan kulaklik / hoparlor varsa (onbellekteki AutoEq ile) ekler. Ses servisi YENIDEN BASLATILMAZ (yeni akista devreye girer).
function Invoke-MrCleanAudioMaintain {
    $s = Get-MrCleanAudioSettings
    if (-not $s.Configured -or -not (Get-MrCleanEapoConfigDir)) { return }
    $devs = @(Get-MrCleanAudioDevices -NoSpatial)
    $idx = @(Get-MrCleanAutoEqIndex -Offline)
    $plans = @($devs | ForEach-Object { Get-MrCleanAudioDevicePlan $_ $idx -Offline })
    $changed = $false
    foreach ($pl in $plans) {
        if (-not ($pl.Enabled -and $pl.Kind -in @("Headphones", "Speaker", "Mic", "Voice"))) { continue }
        $known = $null -ne (Get-MrCleanAudioDevicePref $pl.Dev.Guid)
        if (-not $pl.Dev.Eapo) {
            if (Install-MrCleanEapoDevice $pl.Dev) { $changed = $true; Write-MrCleanAudioLog "$($pl.Dev.Name): $(if ($known) { 'EQ baglantisi kopmustu (guncelleme), geri takildi' } else { 'yeni aygit, otomatik ayarlandi' })." }
        }
        if (-not $known) { Set-MrCleanAudioDevicePref $pl.Dev.Guid $true $pl.Kind $(if ($pl.Kind -eq "Mic") { $pl.MicType } else { $pl.Model }) $pl.Rel; $changed = $true }
    }
    if ($changed) { [void](Write-MrCleanAudioConfig $plans $s (Test-Path (Join-Path (Get-MrCleanEapoInstallDir) "VSTPlugins\ClipOnly2.dll"))) }
}

# Filtre satiri ayrisma (EAPO / AutoEq bicimi) — sayilar her zaman InvariantCulture (Turkce virgul hatasi olmasin)
function ConvertFrom-MrCleanEqLine([string]$line) {
    $ic = [Globalization.CultureInfo]::InvariantCulture
    if ($line -match "(?i)^\s*Filter\s*\d*\s*:\s*ON\s+(PK|LSC|HSC|LS|HS)\s+Fc\s+([\d.]+)\s*Hz\s+Gain\s+(-?[\d.]+)\s*dB(?:\s+Q\s+([\d.]+))?") {
        $q = if ($Matches[4]) { [double]::Parse($Matches[4], $ic) } else { 0.707 }
        $t = $Matches[1].ToUpper(); if ($t -eq "LS") { $t = "LSC" }; if ($t -eq "HS") { $t = "HSC" }
        return [pscustomobject]@{ T = $t; F = [double]::Parse($Matches[2], $ic); G = [double]::Parse($Matches[3], $ic); Q = $q }
    }
    return $null
}

# Filtre zincirinin 20 Hz - 20 kHz arasi en yuksek kazanci (dB) — RBJ Audio EQ Cookbook, fs 48 kHz
function Measure-MrCleanEqPeak($filters) {
    $fs = 48000.0; $max = -999.0; $maxF = 0
    $co = @()
    foreach ($f in $filters) {
        $A = [Math]::Pow(10, $f.G / 40); $w0 = 2 * [Math]::PI * $f.F / $fs; $cs = [Math]::Cos($w0); $al = [Math]::Sin($w0) / (2 * $f.Q); $sa = 2 * [Math]::Sqrt($A) * $al
        switch ($f.T) {
            "PK"  { $co += ,@((1 + $al * $A), (-2 * $cs), (1 - $al * $A), (1 + $al / $A), (-2 * $cs), (1 - $al / $A)) }
            "LSC" { $co += ,@(($A * (($A + 1) - ($A - 1) * $cs + $sa)), (2 * $A * (($A - 1) - ($A + 1) * $cs)), ($A * (($A + 1) - ($A - 1) * $cs - $sa)), ((($A + 1) + ($A - 1) * $cs + $sa)), (-2 * (($A - 1) + ($A + 1) * $cs)), ((($A + 1) + ($A - 1) * $cs - $sa))) }
            "HSC" { $co += ,@(($A * (($A + 1) + ($A - 1) * $cs + $sa)), (-2 * $A * (($A - 1) + ($A + 1) * $cs)), ($A * (($A + 1) + ($A - 1) * $cs - $sa)), ((($A + 1) - ($A - 1) * $cs + $sa)), (2 * (($A - 1) - ($A + 1) * $cs)), ((($A + 1) - ($A - 1) * $cs - $sa))) }
        }
    }
    for ($i = 0; $i -le 240; $i++) {
        $fr = 20 * [Math]::Pow(1000, $i / 240.0); $w = 2 * [Math]::PI * $fr / $fs
        $c1 = [Math]::Cos($w); $s1 = [Math]::Sin($w); $c2 = [Math]::Cos(2 * $w); $s2 = [Math]::Sin(2 * $w)
        $db = 0.0
        foreach ($c in $co) {
            $nr = $c[0] + $c[1] * $c1 + $c[2] * $c2; $ni = -($c[1] * $s1 + $c[2] * $s2)
            $dr = $c[3] + $c[4] * $c1 + $c[5] * $c2; $di = -($c[4] * $s1 + $c[5] * $s2)
            $db += 10 * [Math]::Log10(($nr * $nr + $ni * $ni) / ($dr * $dr + $di * $di))
        }
        if ($db -gt $max) { $max = $db; $maxF = $fr }
    }
    return @{ Peak = [Math]::Round($max, 2); At = [Math]::Round($maxF) }
}


function Show-AudioProfileTool {
    $xamlAs = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="🎧 Otomatik Ses (Equalizer APO + AutoEq)" SizeToContent="Height" Width="1080" MinHeight="480" Background="#0F1115" Foreground="#E6E8EB" FontFamily="{DynamicResource UiFont}" FontSize="14" WindowStartupLocation="CenterOwner" WindowStyle="ToolWindow" ResizeMode="CanResize">
    <Window.Resources>
$($global:SubTheme)
    </Window.Resources>
    <!-- 10. tur: dugmeler HER ZAMAN altta sabit; icerik ekrana sigmazsa ust kisim kaydirilir (kucuk ekranda dugmeler kayboluyordu) -->
    <Grid Margin="14">
        <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <ScrollViewer Grid.Row="0" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <Grid>
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
