$btnResetNet.Add_Click({
    if ([System.Windows.MessageBox]::Show((T 'mbx_net_reset'), (T 'mb_confirm'), [System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning) -eq 'Yes') {
        
        $txtLog.Text = ""
        WpfLog "--- AĞ SIFIRLAMA (RAM) ---"
        
        $s = @'
        try {
            WS 'Ag sifirlaniyor...'

            WS 'Winsock sifirlaniyor...'
            Log '1/5: WinSock yapilandirmasi sifirlaniyor (netsh winsock reset)...'
            & netsh winsock reset | Out-Null
            Log '✅ WinSock sifirlandi.'

            WS 'TCP/IP sifirlaniyor...'
            Log '2/5: TCP/IP yigini sifirlaniyor (netsh int ip reset)...'
            & netsh int ip reset | Out-Null
            Log '✅ TCP/IP sifirlandi.'

            WS 'DNS DHCP zorlaniyor...'
            Log '3/5: Aktif adapter DNS ayarlari DHCP olarak ayarlaniyor (per-adapter source=dhcp)...'
            $adapters = @()
            if (__SKIPDNS__) { Log '   ATLANDI: DNS araci / VPN calisiyor (__DNSTOOLS__) - DNS ayarina dokunulmadi.' }
            else { $adapters = @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq "Up" -and $_.InterfaceType -in @(6, 71) -and $_.InterfaceDescription -notmatch "(?i)VPN|Virtual|Tunnel|Loopback|TAP|Hyper-V|WireGuard|Wintun|Mullvad|Proton|NordLynx|Cloudflare|WARP|OpenVPN|ovpn|Tailscale|ZeroTier" }) }
            foreach ($a in $adapters) {
                $nm = $a.InterfaceAlias
                & netsh interface ipv4 set dnsservers name="$nm" source=dhcp | Out-Null
                & netsh interface ipv6 set dnsservers name="$nm" source=dhcp | Out-Null
            }
            Log '✅ DNS DHCP olarak ayarlandi.'

            WS 'DHCP renew...'
            Log '4/5: DHCP lease yenileniyor (ipconfig /release + /renew)...'
            & ipconfig /release > $null
            Start-Sleep -Milliseconds 500
            & ipconfig /renew > $null
            Log '✅ DHCP lease yenilendi.'

            WS 'DNS cache temizleniyor...'
            Log '5/5: DNS Önbelleği boşaltılıyor (ipconfig /flushdns)...'
            & ipconfig /flushdns > $null
            Log '✅ DNS önbelleği boşaltıldı.'

            Log '⚠️ İŞLEM TAMAMLANDI: Lütfen değişikliklerin tam uygulanması için BİLGİSAYARINIZI YENİDEN BAŞLATIN.'
        } catch {
            Log "❌ HATA: $_"
        }
'@
        # v1.3.0 (7. tur): YogaDNS / NextDNS / GoodbyeDPI / bagli VPN varsa DNS adimi atlanir
        $nrGuard = @(); try { $nrGuard = @(Get-MrCleanDnsGuard -Fresh) } catch {}
        $s = $s.Replace('__SKIPDNS__', $(if ($nrGuard.Count -gt 0) { '$true' } else { '$false' })).Replace('__DNSTOOLS__', (($nrGuard -join ", ") -replace "'", ""))
        Start-Worker-Process $s $btnResetNet "AĞ SIFIRLAMA"
    }
})

