        elseif ($tabWinget -and $tabWinget.IsSelected) {
            try { Ensure-WingetAppxLoaded } catch {}
            # v1.3.0 (§98): oturumdaki ilk ziyarette "Kurulu" durumu sessizce taranir (kayit defteri). Eskiden yalniz son
            # "Denetle"nin kaydi gosteriliyordu; kayit yoksa Genel Bakis "8 guncelleme var" derken sayfada kurulu gorunmuyordu.
            if (-not $script:WingetStatusScanned) { try { Refresh-Winget-Status -Silent $true } catch {} }
        }
        # 3. BAŞLANGIÇ SEKME KONTROLÜ (başlık dile göre değişir; sekme nesnesiyle bakılır)
        elseif (($script:tabStartup -and $script:tabStartup.IsSelected) -or $header -eq "Başlangıç") {
