# (SelectionChanged handler'ları yukarıda birleştirildi)

function Resume-MrCleanBoot {
    $q = $script:MrCleanBootQueue
    if ($null -eq $q -or $q.Count -lt 1) {
        try { if ($script:pbBoot) { $script:pbBoot.Value = 100 } } catch {}
        if ($script:grdBootOverlay) { $script:grdBootOverlay.Visibility = 'Collapsed' }
        try {
            $ms = 0
            if ($global:BootT0) { $ms = [int]$global:BootT0.ElapsedMilliseconds }
            WpfLog ("[BOOT] overlay kapandi: " + $ms + " ms")
        } catch {}
        [void]$Win.Dispatcher.BeginInvoke(
            [System.Windows.Threading.DispatcherPriority]::Background,
            [System.Action]{
                Measure-BootStep 'Load-Tweak-Tree' { Load-Tweak-Tree }
                Measure-BootStep 'Load-Winget-Tree' { Load-Winget-Tree -SkipAppx }
                try {
                    $ms2 = 0
                    if ($global:BootT0) { $ms2 = [int]$global:BootT0.ElapsedMilliseconds }
                    WpfLog ("[BOOT] agaclar bitti: " + $ms2 + " ms")
                } catch {}
            }
        )
        return
    }
    $step = $q.Dequeue()
    try { & $step } catch { try { WpfLog ("Boot: " + $_.Exception.Message) } catch {} }
    [void]$Win.Dispatcher.BeginInvoke(
        [System.Windows.Threading.DispatcherPriority]::Background,
        [System.Action]{ Resume-MrCleanBoot }
    )
}

$Win.Add_Loaded({
    if ($script:grdBootOverlay) { $script:grdBootOverlay.Visibility = 'Visible' }
    try { if ($script:txtBootStatus) { $script:txtBootStatus.Text = [string](T 'boot_loading') } } catch {}
    try { if ($script:pbBoot) { $script:pbBoot.Value = 4 } } catch {}
    if ($script:MrCleanBootStarted) { return }
    $script:MrCleanBootStarted = $true
    $script:BootPctTarget = 8
    $q = New-Object System.Collections.Queue
    $q.Enqueue({
        Set-BootProgress 'boot_loading' 10
        Measure-BootStep 'Cleanup-OldUpdateFiles' { try { Cleanup-OldUpdateFiles } catch {} }
    })
    $q.Enqueue({
        Set-BootProgress 'boot_settings' 38
        Measure-BootStep 'Start-Winapp2-Process' { Start-Winapp2-Process }
    })
    $q.Enqueue({
        Set-BootProgress 'boot_settings' 48
        Measure-BootStep 'Load-DashboardData' { Load-DashboardData }
    })
    $q.Enqueue({
        Set-BootProgress 'boot_lists' 88
        Measure-BootStep 'Load-Repair-Tree' { Load-Repair-Tree }
        Test-AppUpdate

    # 5b. v1.3.0 (6. tur): Guncelleme sonrasi ayar denetimi — acilistan 6 sn sonra, tek sefer
    $script:DriftStartTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:DriftStartTimer.Interval = [TimeSpan]::FromSeconds(6)
    $script:DriftStartTimer.Add_Tick({ $script:DriftStartTimer.Stop(); try { Update-MrCleanAdminLauncherCopy } catch {}; try { Request-MrCleanAdminLauncherOnce } catch {}; try { Invoke-RetiredTweakCleanup } catch {}; try { Start-MrCleanDriftCheck } catch {}; try { Invoke-MrCleanAudioMaintain } catch {} })
    $script:DriftStartTimer.Start()

    # 6. v1.2.22: Connection Monitor — Dashboard'da real-time bandwidth + canli ping (1sn refresh)
    # Sadece Dashboard sekmesinde aktif (CPU tasarrufu icin diger sekmelerde skip)
    $script:CmPrevSample = $null   # Bandwidth delta hesabi icin onceki snapshot
    $script:CmPing = New-Object System.Net.NetworkInformation.Ping
    # v1.3.0 (§86, §57 P2): kart + ağ geçidi önbelleği (30 sn) ve beklemeyen ping. Eski tik her saniye arayüz iş parçacığında
    # Get-NetAdapter + Get-NetAdapterStatistics + Get-NetIPConfiguration + senkron Ping.Send çalıştırıyordu: ort. 121 ms / sn,
    # ilk tik ~0,9-1,6 sn, ağ geçidi yanıtsızsa +500 ms. Şimdi tik yalnız .NET sayacını okur (<1 ms).
    $script:CmNic = $null; $script:CmGw = $null; $script:CmNicTime = [datetime]::MinValue; $script:CmPingTask = $null
    $script:CmPingBrush = @{}
    foreach ($c in '#E6E8EB', '#E0A23B', '#E5484D') { $b = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.ColorConverter]::ConvertFromString($c)); $b.Freeze(); $script:CmPingBrush[$c] = $b }
    $script:CmTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:CmTimer.Interval = [TimeSpan]::FromSeconds(1)
    $script:CmTimer.Add_Tick({
        # Sadece Dashboard sekmesinde aktif
        try { if (-not $tabDashboard.IsSelected) { return } } catch { return }
        try {
            # Etkin kart: önbellekte (30 sn) ya da kart düşmüşse yeniden bul — Ethernet öncelikli, sonra Wi-Fi
            $now = Get-Date
            if (-not $script:CmNic -or ($now - $script:CmNicTime).TotalSeconds -ge 30 -or "$($script:CmNic.Ni.OperationalStatus)" -ne "Up") {
                $script:CmNic = $null; $script:CmGw = $null
                try {
                    $script:CmNic = @(Get-MrCleanNicFast | Where-Object { $_.Up } | Sort-Object { if ($_.InterfaceType -eq 6) { 0 } else { 1 } }) | Select-Object -First 1
                    if ($script:CmNic) {
                        $g4 = @($script:CmNic.Ni.GetIPProperties().GatewayAddresses | Where-Object { $_.Address.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetwork }) | Select-Object -First 1
                        if ($g4) { $script:CmGw = "$($g4.Address)" }
                    }
                } catch {}
                $script:CmNicTime = $now
            }
            $adapter = $script:CmNic

            if (-not $adapter) {
                $txtDashDownload.Text = "—"; $txtDashUpload.Text = "—"; $txtDashNic.Text = "—"
                return
            }

            $cur = $null
            try {
                $stats = $adapter.Ni.GetIPStatistics()
                $cur = @{ Rx = [double]$stats.BytesReceived; Tx = [double]$stats.BytesSent; T = $now; Name = $adapter.Name }
            } catch { $script:CmNic = $null; return }

            if ($script:CmPrevSample) {
                $elapsedSec = ($cur.T - $script:CmPrevSample.T).TotalSeconds
                if ($elapsedSec -gt 0.1 -and $script:CmPrevSample.Name -eq $cur.Name) {
                    $dRx = ($cur.Rx - $script:CmPrevSample.Rx) / $elapsedSec
                    $dTx = ($cur.Tx - $script:CmPrevSample.Tx) / $elapsedSec
                    if ($dRx -lt 0) { $dRx = 0 }
                    if ($dTx -lt 0) { $dTx = 0 }
                    # Otomatik birim secimi (KB/s vs MB/s)
                    $fmtDown = if ($dRx -ge 1MB) { "{0:N1} MB/s" -f ($dRx / 1MB) } elseif ($dRx -ge 1KB) { "{0:N1} KB/s" -f ($dRx / 1KB) } else { "{0:N0} B/s" -f $dRx }
                    $fmtUp   = if ($dTx -ge 1MB) { "{0:N1} MB/s" -f ($dTx / 1MB) } elseif ($dTx -ge 1KB) { "{0:N1} KB/s" -f ($dTx / 1KB) } else { "{0:N0} B/s" -f $dTx }
                    $txtDashDownload.Text = $fmtDown
                    $txtDashUpload.Text = $fmtUp
                }
            }
            $script:CmPrevSample = $cur
            $nicShort = if ($adapter.Name.Length -gt 18) { $adapter.Name.Substring(0, 18) + "..." } else { $adapter.Name }
            $txtDashNic.Text = $nicShort

            # Canli ping — gateway, BEKLEMEZ: önceki tikte başlatılan ping bittiyse sonucu yazılır, sonra yenisi başlatılır (500 ms zaman aşımı)
            try {
                $pt = $script:CmPingTask
                if ($pt -and $pt.IsCompleted) {
                    $script:CmPingTask = $null
                    $reply = $null; try { if (-not $pt.IsFaulted) { $reply = $pt.Result } } catch {}
                    if ($reply -and $reply.Status -eq 'Success') {
                        $rt = $reply.RoundtripTime
                        $color = if ($rt -lt 20) { "#E6E8EB" } elseif ($rt -lt 60) { "#E0A23B" } else { "#E5484D" }
                        $txtDashLivePing.Text = "$rt"
                        $txtDashLivePing.Foreground = $script:CmPingBrush[$color]
                    } else {
                        $txtDashLivePing.Text = "—"
                        $txtDashLivePing.Foreground = $script:CmPingBrush["#E5484D"]
                    }
                }
                if (-not $script:CmPingTask -and $script:CmGw) { $script:CmPingTask = $script:CmPing.SendPingAsync($script:CmGw, 500) }
            } catch {}
        } catch {}
    })
    $script:CmTimer.Start()
    })
    $script:MrCleanBootQueue = $q
    [void]$Win.Dispatcher.BeginInvoke(
        [System.Windows.Threading.DispatcherPriority]::Background,
        [System.Action]{ Resume-MrCleanBoot }
    )
})
try {
    $preMs = 0
    if ($global:BootT0) { $preMs = [int]$global:BootT0.ElapsedMilliseconds }
    WpfLog ("[BOOT] ShowDialog oncesi: " + $preMs + " ms")
    if ($script:UiFontOk) { WpfLog ("[BOOT] yazı tipi Inter: " + $script:UiFontSw.ElapsedMilliseconds + " ms") }
    else { WpfLog "[UYARI] Inter yazı tipi yüklenemedi; arayüz Segoe UI Variable ile açıldı." }
} catch {}
$Win.ShowDialog() | Out-Null

# #endregion 15 -- PENCERE YASAM DONGUSU (Add_Closing, Add_Loaded, ShowDialog)



